/**
 * Bible Book 4: எண்ணாகமம் (Numbers)
 */
if (typeof window.registerBibleBook === 'function') {
  window.registerBibleBook(4, {"id": 4, "testament": "OT", "code": "NUM", "name_en": "Numbers", "name_ta": "எண்ணாகமம்", "category": "Law", "category_ta": "மோசேயின் ஆகமங்கள்", "total_chapters": 36, "chapters": {"1": {"chapter": 1, "duration": 452.81, "audio_url": "audio_ot/OT04_01.mp3", "total_verses": 54, "verses": [{"verse": 1, "start": 4.8, "end": 16.55, "ta": "இஸ்ரவேலர் எகிப்துதேசத்திலிருந்து புறப்பட்ட இரண்டாம் வருஷம் இரண்டாம் மாதம் முதல் தேதியில், கர்த்தர் சீனாய் வனாந்தரத்திலிருக்கிற ஆசரிப்புக் கூடாரத்திலே மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the wilderness of Sinai, in the tabernacle of the congregation, on the first day of the second month, in the second year after they were come out of the land of Egypt, saying,"}, {"verse": 2, "start": 16.55, "end": 28.15, "ta": "நீங்கள் இஸ்ரவேல் புத்திரரின் முழுச்சபையாயிருக்கிற அவர்கள் பிதாக்களுடைய வீட்டு வம்சங்களிலுள்ள புருஷர்களாகிய சகல தலைகளையும் பேர்பேராக எண்ணித் தொகையேற்றுங்கள்.", "en": "Take ye the sum of all the congregation of the children of Israel, after their families, by the house of their fathers, with the number of their names, every male by their polls;"}, {"verse": 3, "start": 28.15, "end": 38.98, "ta": "இஸ்ரவேலிலே இருபது வயதுள்ளவர்கள் முதல் யுத்தத்துக்குப் புறப்படத்தக்கவர்கள் எல்லாரையும் அவர்கள் சேனைகளின்படி நீயும் ஆரோனும் எண்ணிப் பார்ப்பீர்களாக.", "en": "From twenty years old and upward, all that are able to go forth to war in Israel: thou and Aaron shall number them by their armies."}, {"verse": 4, "start": 38.98, "end": 48.34, "ta": "ஒவ்வொரு கோத்திரத்துக்கு ஒவ்வொரு மனிதன் உங்களோடே இருப்பானாக; அவன் தன் பிதாக்களின் வம்சத்துக்குத் தலைவனாயிருக்கவேண்டும்.", "en": "And with you there shall be a man of every tribe; every one head of the house of his fathers."}, {"verse": 5, "start": 48.34, "end": 55.44, "ta": "உங்களோடே நிற்கவேண்டிய மனிதருடைய நாமங்களாவன: ரூபன் கோத்திரத்தில் சேதேயூருடைய குமாரன் எலிசூர்.", "en": "And these are the names of the men that shall stand with you: of the tribe of Reuben; Elizur the son of Shedeur."}, {"verse": 6, "start": 55.44, "end": 59.95, "ta": "சிமியோன் கோத்திரத்தில் சூரிஷதாயின் குமாரன் செலுூமியேல்.", "en": "Of Simeon; Shelumiel the son of Zurishaddai."}, {"verse": 7, "start": 59.95, "end": 63.88, "ta": "யூதா கோத்திரத்தில் அம்மினதாபின் குமாரன் நகசோன்.", "en": "Of Judah; Nahshon the son of Amminadab."}, {"verse": 8, "start": 63.88, "end": 68.03, "ta": "இசக்கார் கோத்திரத்தில் சூவாரின் குமாரன் நெதனெயேல்.", "en": "Of Issachar; Nethaneel the son of Zuar."}, {"verse": 9, "start": 68.03, "end": 71.97, "ta": "செபுலோன் கோத்திரத்தில் ஏலோனின் குமாரன் எலியாப்.", "en": "Of Zebulun; Eliab the son of Helon."}, {"verse": 10, "start": 71.97, "end": 81.89, "ta": "யோசேப்பின் குமாரராகிய எப்பிராயீம் கோத்திரத்தில் அம்மியூதின் குமாரன் எலிஷாமா; மனாசே கோத்திரத்தில் பெதாசூரின் குமாரன் கமாலியேல்.", "en": "Of the children of Joseph: of Ephraim; Elishama the son of Ammihud: of Manasseh; Gamaliel the son of Pedahzur."}, {"verse": 11, "start": 81.89, "end": 86.11, "ta": "பென்யமீன் கோத்திரத்தில் கீதெயோனின் குமாரன் அபீதான்.", "en": "Of Benjamin; Abidan the son of Gideoni."}, {"verse": 12, "start": 86.11, "end": 90.26, "ta": "தாண் கோத்திரத்தில் அம்மிஷதாயின் குமாரன் அகியேசேர்.", "en": "Of Dan; Ahiezer the son of Ammishaddai."}, {"verse": 13, "start": 90.26, "end": 94.2, "ta": "ஆசேர் கோத்திரத்தில் ஓகிரானின் குமாரன் பாகியேல்.", "en": "Of Asher; Pagiel the son of Ocran."}, {"verse": 14, "start": 94.2, "end": 98.21, "ta": "காத் கோத்திரத்தில் தேகுவேலின் குமாரன் எலியாசாப்.", "en": "Of Gad; Eliasaph the son of Deuel."}, {"verse": 15, "start": 98.21, "end": 101.87, "ta": "நப்தலி கோத்திரத்தில் ஏனானின் குமாரன் அகீரா.", "en": "Of Naphtali; Ahira the son of Enan."}, {"verse": 16, "start": 101.87, "end": 111.86, "ta": "இவர்களே சபையில் ஏற்படுத்தப்பட்டவர்களும், தங்கள் தங்கள் பிரபுக்களும், இஸ்ரவேலில் ஆயிரவர்களுக்குத் தலைவருமாயிருப்பவர்கள் என்றார்.", "en": "These were the renowned of the congregation, princes of the tribes of their fathers, heads of thousands in Israel."}, {"verse": 17, "start": 111.86, "end": 117.76, "ta": "அப்படியே மோசேயும் ஆரோனும் பேர்பேராகக் குறிக்கப்பட்ட இந்த மனிதரைக் கூட்டிக்கொண்டு,", "en": "And Moses and Aaron took these men which are expressed by their names:"}, {"verse": 18, "start": 117.76, "end": 138.3, "ta": "இரண்டாம் மாதம் முதல் தேதியில் சபையார் எல்லாரையும் கூடிவரச்செய்தார்கள். அப்பொழுது அவர்கள் தங்கள் தங்கள் குடும்பத்தின்படிக்குή், பߠΤாக்கγுடைί வή்சத்தߠΩ்படοக்கும், நாமத்தொகையின்படிக்கும், இருபது வயதுள்ளவர்கள் முதல் தலைதலையாகத் தங்கள் வம்ச உற்பத்தியைத் தெரிவித்தார்கள்.", "en": "And they assembled all the congregation together on the first day of the second month, and they declared their pedigrees after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, by their polls."}, {"verse": 19, "start": 138.3, "end": 145.48, "ta": "இப்படிக் கர்த்தர் கட்டளையிட்டபடியே, மோசே அவர்களைச் சீனாய் வனாந்தரத்தில் எண்ணிப்பார்த்தான்.", "en": "As the LORD commanded Moses, so he numbered them in the wilderness of Sinai."}, {"verse": 20, "start": 145.48, "end": 158.28, "ta": "இஸ்ரவேலின் மூத்தகுமாரனாகிய ரூபன் புத்திரருடைய பிதாக்களின் வீட்டுவம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் தலைதலையாக எண்ணப்பட்டபோது,", "en": "And the children of Reuben, Israel’s eldest son, by their generations, after their families, by the house of their fathers, according to the number of the names, by their polls, every male from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 21, "start": 158.28, "end": 163.98, "ta": "ரூபன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பத்தாறாயிரத்து ஐந்நூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Reuben, were forty and six thousand and five hundred."}, {"verse": 22, "start": 163.98, "end": 175.23, "ta": "சிமியோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் தலைதலையாக எண்ணப்பட்டபோது,", "en": "Of the children of Simeon, by their generations, after their families, by the house of their fathers, those that were numbered of them, according to the number of the names, by their polls, every male from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 23, "start": 175.23, "end": 181.49, "ta": "சிமியோன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்தொன்பதினாயிரத்து முந்நூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Simeon, were fifty and nine thousand and three hundred."}, {"verse": 24, "start": 181.49, "end": 191.83, "ta": "காத் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Gad, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 25, "start": 191.83, "end": 198.09, "ta": "காத் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பத்தையாயிரத்து அறுநூற்று ஐம்பதுபேர்.", "en": "Those that were numbered of them, even of the tribe of Gad, were forty and five thousand six hundred and fifty."}, {"verse": 26, "start": 198.09, "end": 208.36, "ta": "யூதா புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Judah, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 27, "start": 208.36, "end": 214.13, "ta": "யூதா கோத்திரத்தில் எண்ணப்பட்டவர்கள், எழுபத்து நாலாயிரத்து அறுநூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Judah, were threescore and fourteen thousand and six hundred."}, {"verse": 28, "start": 214.13, "end": 224.68, "ta": "இசக்கார் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Issachar, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 29, "start": 224.68, "end": 230.66, "ta": "இசக்கார் கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்து நாலாயிரத்து நானூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Issachar, were fifty and four thousand and four hundred."}, {"verse": 30, "start": 230.66, "end": 241.21, "ta": "செபுலோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Zebulun, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 31, "start": 241.21, "end": 246.98, "ta": "செபுலோன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்தேழாயிரத்து நானூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Zebulun, were fifty and seven thousand and four hundred."}, {"verse": 32, "start": 246.98, "end": 259.22, "ta": "யோசேப்பின் குமாரரில் எப்பிராயீம் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Joseph, namely , of the children of Ephraim, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 33, "start": 259.22, "end": 265.19, "ta": "எப்பிராயீம் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பதினாயிரத்து ஐந்நூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Ephraim, were forty thousand and five hundred."}, {"verse": 34, "start": 265.19, "end": 275.53, "ta": "மனாசே புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Manasseh, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 35, "start": 275.53, "end": 281.23, "ta": "மனாசே கோத்திரத்தில் எண்ணப்பட்டவர்கள், முப்பத்தீராயிரத்து இருநூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Manasseh, were thirty and two thousand and two hundred."}, {"verse": 36, "start": 281.23, "end": 291.85, "ta": "பென்யமீன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Benjamin, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 37, "start": 291.85, "end": 297.76, "ta": "பென்யமீன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், முப்பத்தையாயிரத்து நானூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Benjamin, were thirty and five thousand and four hundred."}, {"verse": 38, "start": 297.76, "end": 308.03, "ta": "தாண் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Dan, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 39, "start": 308.03, "end": 313.59, "ta": "தாண் கோத்திரத்தில் எண்ணப்பட்டவர்கள், அறுபத்தீராயிரத்து எழுநூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Dan, were threescore and two thousand and seven hundred."}, {"verse": 40, "start": 313.59, "end": 323.93, "ta": "ஆசேர் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Asher, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 41, "start": 323.93, "end": 329.62, "ta": "ஆசேர் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பத்தோராயிரத்து ஐந்நூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Asher, were forty and one thousand and five hundred."}, {"verse": 42, "start": 329.62, "end": 340.03, "ta": "நப்தலி புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Naphtali, throughout their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 43, "start": 340.03, "end": 345.87, "ta": "நப்தலி கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்து மூவாயிரத்து நானூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Naphtali, were fifty and three thousand and four hundred."}, {"verse": 44, "start": 345.87, "end": 357.34, "ta": "எண்ணப்பட்டவர்கள் இவர்களே; மோசேயும் ஆரோனும் இஸ்ரவேலுடைய பிதாக்களின் வம்சத்தில் ஒவ்வொரு வம்சத்துக்கு ஒவ்வொரு பிரபுவாகிய பன்னிரண்டுபேரும் எண்ணினார்கள்.", "en": "These are those that were numbered, which Moses and Aaron numbered, and the princes of Israel, being twelve men: each one was for the house of his fathers."}, {"verse": 45, "start": 357.34, "end": 368.38, "ta": "இஸ்ரவேல் புத்திரருடைய பிதாக்களின் வம்சத்தில் இருபது வயதுள்ளவர்கள்முதல், இஸ்ரவேலில் யுத்தத்திற்குப் புறப்படத்தக்கவர்களாகிய எண்ணப்பட்ட பேர்கள் எல்லாரும்,", "en": "So were all those that were numbered of the children of Israel, by the house of their fathers, from twenty years old and upward, all that were able to go forth to war in Israel;"}, {"verse": 46, "start": 368.38, "end": 373.16, "ta": "ஆறுலட்சத்து மூவாயிரத்து ஐந்நூற்று ஐம்பது பேராயிருந்தார்கள்.", "en": "Even all they that were numbered were six hundred thousand and three thousand and five hundred and fifty."}, {"verse": 47, "start": 373.16, "end": 379.42, "ta": "லேவியர் தங்கள் பிதாக்களுடைய கோத்திரத்தின்படியே, மற்றவர்களுடனே எண்ணப்படவில்லை.", "en": "But the Levites after the tribe of their fathers were not numbered among them."}, {"verse": 48, "start": 379.42, "end": 381.04, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "For the LORD had spoken unto Moses, saying,"}, {"verse": 49, "start": 381.04, "end": 388.22, "ta": "நீ லேவி கோத்திரத்தாரைமாத்திரம் எண்ணாமலும், இஸ்ரவேல் புத்திரருக்குள்ளே அவர்கள் தொகையை ஏற்றாமலும்,", "en": "Only thou shalt not number the tribe of Levi, neither take the sum of them among the children of Israel:"}, {"verse": 50, "start": 388.22, "end": 409.6, "ta": "லேவியரைச் சாட்சியின் வாசஸ்தலத்திற்கும், அதினுடைய சகல பணிமுட்டுகளுக்கும், அதிலுள்ள சமஸ்த பொருள்களுக்கும் விசாரிப்புக்காரராக ஏற்படுத்து; அவர்கள் வாசஸ்தலத்தையும் அதின் சகல பணிமுட்டுகளையும் சுமப்பார்களாக; அதினிடத்தில் ஊழியம்செய்து, வாசஸ்தலத்தைச் சுற்றிலும் பாளயமிறங்கக்கடவர்கள்.", "en": "But thou shalt appoint the Levites over the tabernacle of testimony, and over all the vessels thereof, and over all things that belong to it: they shall bear the tabernacle, and all the vessels thereof; and they shall minister unto it, and shall encamp round about the tabernacle."}, {"verse": 51, "start": 409.6, "end": 423.88, "ta": "வாசஸ்தலம் புறப்படும்போது, லேவியர் அதை இறக்கிவைத்து, அது ஸ்தாபனம் பண்ணப்படும்போது, லேவியர் அதை எடுத்து நிறுத்தக்கடவர்கள்; அந்நியன் அதற்குச் சமீபத்தில் வந்தால் கொலைசெய்யப்படக்கடவன்.", "en": "And when the tabernacle setteth forward, the Levites shall take it down: and when the tabernacle is to be pitched, the Levites shall set it up: and the stranger that cometh nigh shall be put to death."}, {"verse": 52, "start": 423.88, "end": 431.97, "ta": "இஸ்ரவேல் புத்திரர் தங்கள் தங்கள் பாளயத்தோடும், தங்கள் தங்கள் சேனையின் கொடியோடும் கூடாரம் போடக்கடவர்கள்.", "en": "And the children of Israel shall pitch their tents, every man by his own camp, and every man by his own standard, throughout their hosts."}, {"verse": 53, "start": 431.97, "end": 444.98, "ta": "இஸ்ரவேல் புத்திரராகிய சபையின்மேல் கடுங்கோபம் வராதபடிக்கு லேவியர் சாட்சியின் வாசஸ்தலத்தைச் சுற்றிலும் பாளயமிறங்கி, லேவியர் சாட்சியின் வாசஸ்தலத்தைக் காவல்காப்பார்களாக என்றார்.", "en": "But the Levites shall pitch round about the tabernacle of testimony, that there be no wrath upon the congregation of the children of Israel: and the Levites shall keep the charge of the tabernacle of testimony."}, {"verse": 54, "start": 444.98, "end": 451.31, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடி எல்லாவற்றையும் இஸ்ரவேல் புத்திரர் செய்தார்கள்.", "en": "And the children of Israel did according to all that the LORD commanded Moses, so did they."}]}, "2": {"chapter": 2, "duration": 323.12, "audio_url": "audio_ot/OT04_02.mp3", "total_verses": 34, "verses": [{"verse": 1, "start": 3.8, "end": 6.49, "ta": "கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 2, "start": 6.49, "end": 21.61, "ta": "இஸ்ரவேல் புத்திரர் அவரவர் தங்கள் தங்கள் பிதாக்களுடைய வம்சத்தின் விருதாகிய தங்கள் தங்கள் கொடியண்டையிலே தங்கள் கூடாரங்களைப் போட்டு, ஆசரிப்புக் கூடாரத்திற்கு எதிராகச் சுற்றிலும் பாளயமிறங்கக்கடவர்கள்.", "en": "Every man of the children of Israel shall pitch by his own standard, with the ensign of their father’s house: far off about the tabernacle of the congregation shall they pitch."}, {"verse": 3, "start": 21.61, "end": 34.83, "ta": "யூதாவின் பாளயத்துக் கொடியையுடைய சேனைகள் சூரியன் உதிக்கும் கீழ்ப்புறத்திலே பாளயமிறங்கவேண்டும்; அம்மினதாபின் குமாரனாகிய நகசோன் யூதா சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And on the east side toward the rising of the sun shall they of the standard of the camp of Judah pitch throughout their armies: and Nahshon the son of Amminadab shall be captain of the children of Judah."}, {"verse": 4, "start": 34.83, "end": 39.63, "ta": "எண்ணப்பட்ட அவனுடைய சேனை எழுபத்து நாலாயிரத்து அறுநூறுபேர்.", "en": "And his host, and those that were numbered of them, were threescore and fourteen thousand and six hundred."}, {"verse": 5, "start": 39.63, "end": 49.95, "ta": "அவன் அருகே இசக்கார் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; சூவாரின் குமாரன் நெதனெயேல் இசக்கார் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And those that do pitch next unto him shall be the tribe of Issachar: and Nethaneel the son of Zuar shall be captain of the children of Issachar."}, {"verse": 6, "start": 49.95, "end": 54.67, "ta": "எண்ணப்பட்ட அவனுடைய சேனை ஐம்பத்து நாலாயிரத்து நானூறுபேர்.", "en": "And his host, and those that were numbered thereof, were fifty and four thousand and four hundred."}, {"verse": 7, "start": 54.67, "end": 64.99, "ta": "அவன் அருகே செபுலோன் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; ஏலோனின் குமாரனாகிய எலியாப் செபுலோன் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "Then the tribe of Zebulun: and Eliab the son of Helon shall be captain of the children of Zebulun."}, {"verse": 8, "start": 64.99, "end": 70.23, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் ஐம்பத்தேழாயிரத்து நானூறுபேர்.", "en": "And his host, and those that were numbered thereof, were fifty and seven thousand and four hundred."}, {"verse": 9, "start": 70.23, "end": 82.66, "ta": "எண்ணப்பட்ட யூதாவின் பாளயத்தார் எல்லாரும் தங்கள் சேனைகளின்படியே இலட்சத்து எண்பத்து ஆறாயிரத்து நானூறுபேர்; இவர்கள் பிரயாணத்திலே முதற்பாளயமாய்ப் போகக்கடவர்கள்.", "en": "All that were numbered in the camp of Judah were an hundred thousand and fourscore thousand and six thousand and four hundred, throughout their armies. These shall first set forth."}, {"verse": 10, "start": 82.66, "end": 94.72, "ta": "ரூபனுடைய பாளயத்துக் கொடியையுடைய சேனைகள் தென்புறத்தில் பாளயமிறங்கவேண்டும்; சேதேயூரின் குமாரனாகிய எலிசூர் ரூபன் சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "On the south side shall be the standard of the camp of Reuben according to their armies: and the captain of the children of Reuben shall be Elizur the son of Shedeur."}, {"verse": 11, "start": 94.72, "end": 100.1, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பத்தாறாயிரத்து ஐந்நூறுபேர்.", "en": "And his host, and those that were numbered thereof, were forty and six thousand and five hundred."}, {"verse": 12, "start": 100.1, "end": 111.29, "ta": "அவன் அருகே சிமியோன் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; சூரிஷதாயின் குமாரனாகிய செலுூமியேல் சிமியோன் சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And those which pitch by him shall be the tribe of Simeon: and the captain of the children of Simeon shall be Shelumiel the son of Zurishaddai."}, {"verse": 13, "start": 111.29, "end": 117.03, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் ஐம்பத்தொன்பதினாயிரத்து முந்நூறுபேர்.", "en": "And his host, and those that were numbered of them, were fifty and nine thousand and three hundred."}, {"verse": 14, "start": 117.03, "end": 127.42, "ta": "அவன் அருகே காத் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; தேகுவேலின் குமாரனாகிய எலியாசாப் காத் சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "Then the tribe of Gad: and the captain of the sons of Gad shall be Eliasaph the son of Reuel."}, {"verse": 15, "start": 127.42, "end": 133.46, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பத்தையாயிரத்து அறுநூற்று ஐம்பதுபேர்.", "en": "And his host, and those that were numbered of them, were forty and five thousand and six hundred and fifty."}, {"verse": 16, "start": 133.46, "end": 146.76, "ta": "எண்ணப்பட்ட ரூபனின் பாளயத்தார் எல்லாரும் தங்கள் சேனைகளின்படியே இலட்சத்து ஐம்பத்து ஓராயிரத்து நானூற்று ஐம்பதுபேர்; இவர்கள் பிரயாணத்தில் இரண்டாம் பாளயமாய்ப் போகக்கடவர்கள்.", "en": "All that were numbered in the camp of Reuben were an hundred thousand and fifty and one thousand and four hundred and fifty, throughout their armies. And they shall set forth in the second rank."}, {"verse": 17, "start": 146.76, "end": 162.6, "ta": "பின்பு ஆசரிப்புக் கூடாரம் லேவியரின் சேனையோடே பாளயங்களின் நடுவே பிரயாணப்பட்டுப் போகவேண்டும்; எப்படிப் பாளயமிறங்குகிறார்களோ, அப்படியே அவரவர் தங்கள் வரிசையிலே தங்கள் கொடிகளோடே பிரயாணமாய்ப் போகக்கடவர்கள்.", "en": "Then the tabernacle of the congregation shall set forward with the camp of the Levites in the midst of the camp: as they encamp, so shall they set forward, every man in his place by their standards."}, {"verse": 18, "start": 162.6, "end": 175.1, "ta": "எப்பிராயீமுடைய பாளயத்துக் கொடியையுடைய சேனைகள் மேல்புறத்தில் இறங்கவேண்டும்; அம்மியூதின் குமாரனாகிய எலிஷாமா எப்பிராயீமின் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "On the west side shall be the standard of the camp of Ephraim according to their armies: and the captain of the sons of Ephraim shall be Elishama the son of Ammihud."}, {"verse": 19, "start": 175.1, "end": 180.33, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பதினாயிரத்து ஐந்நூறுபேர்.", "en": "And his host, and those that were numbered of them, were forty thousand and five hundred."}, {"verse": 20, "start": 180.33, "end": 190.58, "ta": "அவன் அருகே மனாசே கோத்திரத்தார் பாளயமிறங்கவேண்டும்; பெதாசூரின் குமாரனாகிய கமாலியேல் மனாசே சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And by him shall be the tribe of Manasseh: and the captain of the children of Manasseh shall be Gamaliel the son of Pedahzur."}, {"verse": 21, "start": 190.58, "end": 195.96, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் முப்பத்தீராயிரத்து இருநூறுபேர்.", "en": "And his host, and those that were numbered of them, were thirty and two thousand and two hundred."}, {"verse": 22, "start": 195.96, "end": 206.64, "ta": "அவன் அருகே பென்யமீன் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; கீதெயோனின் குமாரனாகிய அபீதான் பென்யமீன் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "Then the tribe of Benjamin: and the captain of the sons of Benjamin shall be Abidan the son of Gideoni."}, {"verse": 23, "start": 206.64, "end": 211.95, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் முப்பத்தையாயிரத்து நானூறுபேர்.", "en": "And his host, and those that were numbered of them, were thirty and five thousand and four hundred."}, {"verse": 24, "start": 211.95, "end": 224.38, "ta": "எண்ணப்பட்ட எப்பிராயீமின் பாளயத்தார் எல்லாரும் தங்கள் சேனைகளின்படியே இலட்சத்து எண்ணாயிரத்து நூறுபேர்; இவர்கள் பிரயாணத்தில் மூன்றாம் பாளயமாய்ப் போகக்கடவர்கள்.", "en": "All that were numbered of the camp of Ephraim were an hundred thousand and eight thousand and an hundred, throughout their armies. And they shall go forward in the third rank."}, {"verse": 25, "start": 224.38, "end": 235.93, "ta": "தாணுடைய பாளயத்துக் கொடியையுடைய சேனைகள் வடபுறத்தில் இறங்கவேண்டும்; அம்மிஷதாயின் குமாரனாகிய அகியேசேர் தாண் வம்சத்திற்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "The standard of the camp of Dan shall be on the north side by their armies: and the captain of the children of Dan shall be Ahiezer the son of Ammishaddai."}, {"verse": 26, "start": 235.93, "end": 241.24, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் அறுபத்தீராயிரத்து எழுநூறுபேர்.", "en": "And his host, and those that were numbered of them, were threescore and two thousand and seven hundred."}, {"verse": 27, "start": 241.24, "end": 251.34, "ta": "அவன் அருகே ஆசேர் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; ஓகிரானின் குமாரனாகிய பாகியேல் ஆசேர் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And those that encamp by him shall be the tribe of Asher: and the captain of the children of Asher shall be Pagiel the son of Ocran."}, {"verse": 28, "start": 251.34, "end": 256.72, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பத்தோராயிரத்து ஐந்நூறுபேர்.", "en": "And his host, and those that were numbered of them, were forty and one thousand and five hundred."}, {"verse": 29, "start": 256.72, "end": 266.89, "ta": "அவன் அருகே நப்தலி கோத்திரத்தார் பாளயமிறங்கவேண்டும்; ஏனானின் குமாரனாகிய அகீரா நப்தலி சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "Then the tribe of Naphtali: and the captain of the children of Naphtali shall be Ahira the son of Enan."}, {"verse": 30, "start": 266.89, "end": 272.34, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் ஐம்பத்து மூவாயிரத்து நானூறுபேர்.", "en": "And his host, and those that were numbered of them, were fifty and three thousand and four hundred."}, {"verse": 31, "start": 272.34, "end": 283.17, "ta": "எண்ணப்பட்ட தாணின் பாளயத்தார் எல்லாரும் இலட்சத்து ஐம்பத்தேழாயிரத்து அறுநூறுபேர்; இவர்கள் தங்கள் கொடிகளோடே பின்பாளயமாய்ப் போகக்கடவர்கள்.", "en": "All they that were numbered in the camp of Dan were an hundred thousand and fifty and seven thousand and six hundred. They shall go hindmost with their standards."}, {"verse": 32, "start": 283.17, "end": 300.03, "ta": "இவர்களே தங்கள் தங்கள் பிதாக்களின் வம்சத்தின்படி இஸ்ரவேல் புத்திரரில் எண்ணப்பட்டவர்கள். பாளயங்களிலே தங்கள் தங்கள் சேனைகளின்படியே எண்ணப்பட்டவர்கள் எல்லாரும் ஆறுலட்சத்து மூவாயிரத்து ஐந்நூற்று ஐம்பது பேராயிருந்தார்கள்.", "en": "These are those which were numbered of the children of Israel by the house of their fathers: all those that were numbered of the camps throughout their hosts were six hundred thousand and three thousand and five hundred and fifty."}, {"verse": 33, "start": 300.03, "end": 307.45, "ta": "லேவியரோ, கர்த்தர் மோசேக்குக் கட்டளையிட்டபடி, இஸ்ரவேல் புத்திரருக்குள்ளே எண்ணப்படவில்லை.", "en": "But the Levites were not numbered among the children of Israel; as the LORD commanded Moses."}, {"verse": 34, "start": 307.45, "end": 321.62, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியெல்லாம் இஸ்ரவேல் புத்திரர் செய்து, தங்கள் தங்கள் கொடிகளின்கீழ் பாளயமிறங்கி, தங்கள் தங்கள் பிதாக்களுடைய வம்சங்களின்படியே பிரயாணப்பட்டுப்போனார்கள்.", "en": "And the children of Israel did according to all that the LORD commanded Moses: so they pitched by their standards, and so they set forward, every one after their families, according to the house of their fathers."}]}, "3": {"chapter": 3, "duration": 552.41, "audio_url": "audio_ot/OT04_03.mp3", "total_verses": 51, "verses": [{"verse": 1, "start": 3.8, "end": 10.57, "ta": "சீனாய் மலையில் கர்த்தர் மோசேயோடே பேசின நாளிலே, ஆரோன் மோசே என்பவர்களுடைய வம்சவரலாறாவது:", "en": "These also are the generations of Aaron and Moses in the day that the LORD spake with Moses in mount Sinai."}, {"verse": 2, "start": 10.57, "end": 18.55, "ta": "ஆரோனுடைய குமாரர், முதல் பிறந்தவனாகிய நாதாப், அபியூ, எலெயாசார், இத்தாமார் என்பவர்களே.", "en": "And these are the names of the sons of Aaron; Nadab the firstborn, and Abihu, Eleazar, and Ithamar."}, {"verse": 3, "start": 18.55, "end": 27.98, "ta": "ஆசாரிய ஊழியம்செய்கிறதற்கு அவனால் பிரதிஷ்டை செய்யப்பட்டு அபிஷேகம்பெற்ற ஆசாரியரான ஆரோனுடைய குமாரரின் நாமங்கள் இவைகளே.", "en": "These are the names of the sons of Aaron, the priests which were anointed, whom he consecrated to minister in the priest’s office."}, {"verse": 4, "start": 27.98, "end": 49.57, "ta": "நாதாபும் அபியூவும் சீனாய் வனாந்தரத்தில் அந்நிய அக்கினியைக் கர்த்தருடைய சந்நிதியில் கொண்டுவந்தபோது, கர்த்தருடைய சந்நிதியில் மரித்துப்போனார்கள்; அவர்களுக்குப் பிள்ளைகள் இல்லை; எலெயாசாரும் இத்தாமாருமே தங்கள் தகப்பனாகிய ஆரோனுக்கு முன்பாக ஆசாரிய ஊழியம் செய்தார்கள்.", "en": "And Nadab and Abihu died before the LORD , when they offered strange fire before the LORD , in the wilderness of Sinai, and they had no children: and Eleazar and Ithamar ministered in the priest’s office in the sight of Aaron their father."}, {"verse": 5, "start": 49.57, "end": 51.32, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 6, "start": 51.32, "end": 59.91, "ta": "நீ லேவிகோத்திரத்தாரைச் சேர்த்து, அவர்கள் ஆசாரியனாகிய ஆரோனுக்குப் பணிவிடைசெய்யும்படி அவர்களை நிறுத்து.", "en": "Bring the tribe of Levi near, and present them before Aaron the priest, that they may minister unto him."}, {"verse": 7, "start": 59.91, "end": 71.54, "ta": "அவர்கள் ஆசரிப்புக் கூடாரத்துக்கு முன்பாக அவனுடைய காவலையும் எல்லாச் சபையின் காவலையும் காத்து, வாசஸ்தலத்தின் பணிவிடை வேலைகளைச் செய்யக்கடவர்கள்.", "en": "And they shall keep his charge, and the charge of the whole congregation before the tabernacle of the congregation, to do the service of the tabernacle."}, {"verse": 8, "start": 71.54, "end": 83.48, "ta": "அவர்கள் ஆசரிப்புக் கூடாரத்தின் தட்டுமுட்டு முதலானவைகளையும், இஸ்ரவேல் புத்திரரின் காவலையும் காத்து, வாசஸ்தலத்தின் பணிவிடைகளைச் செய்யக்கடவர்கள்.", "en": "And they shall keep all the instruments of the tabernacle of the congregation, and the charge of the children of Israel, to do the service of the tabernacle."}, {"verse": 9, "start": 83.48, "end": 96.56, "ta": "ஆகையால் லேவியரை ஆரோனிடத்திலும் அவன் குமாரரிடத்திலும் ஒப்புக்கொடுப்பாயாக; இஸ்ரவேல் புத்திரரில் இவர்கள் முற்றிலும் அவனுக்கு ஒப்புக்கொடுக்கப்பட்டிருக்கிறார்கள்.", "en": "And thou shalt give the Levites unto Aaron and to his sons: they are wholly given unto him out of the children of Israel."}, {"verse": 10, "start": 96.56, "end": 109.63, "ta": "ஆரோனையும் அவன் குமாரரையுமோ, தங்கள் ஆசாரிய ஊழியத்தைச் செய்வதற்காக நியமிக்கக்கடவாய், அந்த ஊழியத்தைச் செய்யும்படி சேருகிற அந்நியன் கொலைசெய்யப்படக்கடவன் என்றார்.", "en": "And thou shalt appoint Aaron and his sons, and they shall wait on their priest’s office: and the stranger that cometh nigh shall be put to death."}, {"verse": 11, "start": 109.63, "end": 112.07, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 12, "start": 112.07, "end": 126.59, "ta": "இஸ்ரவேல் புத்திரரில் கர்ப்பந்திறந்து பிறக்கிற முதற்பேறான யாவுக்கும் பதிலாக, நான் லேவியரை இஸ்ரவேல் புத்திரரிலிருந்து எடுத்துக்கொண்டேன்; அவர்கள் என்னுடையவர்களாயிருக்கிறார்கள்.", "en": "And I, behold, I have taken the Levites from among the children of Israel instead of all the firstborn that openeth the matrix among the children of Israel: therefore the Levites shall be mine;"}, {"verse": 13, "start": 126.59, "end": 147.5, "ta": "முதற்பேறானவையெல்லாம் என்னுடையவை; நான் எகிப்துதேசத்தில் முதற்பேறான யாவையும் சங்கரித்த நாளில், இஸ்ரவேலில் மனிதர்முதல் மிருகஜீவன்மட்டுமுள்ள முதற்பேறான யாவையும் எனக்கென்று பரிசுத்தப்படுத்தினதினாலே, அவைகள் என்னுடையவைகளாயிருக்கும்; நான் கர்த்தர் என்றார்.", "en": "Because all the firstborn are mine; for on the day that I smote all the firstborn in the land of Egypt I hallowed unto me all the firstborn in Israel, both man and beast: mine shall they be: I am the LORD ."}, {"verse": 14, "start": 147.5, "end": 151.53, "ta": "பின்னும் கர்த்தர் சீனாய் வனாந்தரத்தில் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the wilderness of Sinai, saying,"}, {"verse": 15, "start": 151.53, "end": 164.3, "ta": "லேவிபுத்திரரை அவர்கள் பிதாக்களின் வம்சங்களின்படியே எண்ணுவாயாக; அவர்களில் ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளையெல்லாம் எண்ணுவாயாக என்றார்.", "en": "Number the children of Levi after the house of their fathers, by their families: every male from a month old and upward shalt thou number them."}, {"verse": 16, "start": 164.3, "end": 172.13, "ta": "அப்பொழுது கர்த்தருடைய வாக்கின்படி, மோசே தனக்குக் கற்பிக்கப்பட்ட பிரகாரம் அவர்களை எண்ணினான்.", "en": "And Moses numbered them according to the word of the LORD , as he was commanded."}, {"verse": 17, "start": 172.13, "end": 179.35, "ta": "லேவியின் குமாரர் தங்கள் நாமங்களின்படியே, கெர்சோன், கோகாத், மெராரி என்பவர்கள்.", "en": "And these were the sons of Levi by their names; Gershon, and Kohath, and Merari."}, {"verse": 18, "start": 179.35, "end": 186.58, "ta": "தங்கள் வம்சத்தின்படியே கெர்சோனுடைய குமாரரின் நாமங்கள், லிப்னி, சீமேயி என்பவைகள்.", "en": "And these are the names of the sons of Gershon by their families; Libni, and Shimei."}, {"verse": 19, "start": 186.58, "end": 195.24, "ta": "தங்கள் வம்சங்களின்படியே கோகாத்துடைய குமாரர், அம்ராம், இத்சேயார், எப்ரோன், ஊசியேல் என்பவர்கள்.", "en": "And the sons of Kohath by their families; Amram, and Izehar, Hebron, and Uzziel."}, {"verse": 20, "start": 195.24, "end": 205.43, "ta": "தங்கள் வம்சங்களின்படியே மெராரியினுடைய குமாரர், மகேலி, மூசி என்பவர்கள்; இவர்களே லேவியருடைய பிதாக்களின் வம்சத்தார்.", "en": "And the sons of Merari by their families; Mahli, and Mushi. These are the families of the Levites according to the house of their fathers."}, {"verse": 21, "start": 205.43, "end": 214.1, "ta": "கெர்சோனின் வழியாய் லிப்னீயரின் வம்சமும் சீமேயியர் வம்சமும் தோன்றின; இவைகளே கெர்சோனியரின் வம்சங்கள்.", "en": "Of Gershon was the family of the Libnites, and the family of the Shimites: these are the families of the Gershonites."}, {"verse": 22, "start": 214.1, "end": 225.5, "ta": "அவர்களில் ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளெல்லாம் எண்ணப்பட்டபோது, எண்ணப்பட்டவர்கள் ஏழாயிரத்து ஐந்நூறுபேராயிருந்தார்கள்.", "en": "Those that were numbered of them, according to the number of all the males, from a month old and upward, even those that were numbered of them were seven thousand and five hundred."}, {"verse": 23, "start": 225.5, "end": 232.12, "ta": "கெர்சோனியரின் வம்சங்கள் வாசஸ்தலத்தின் பின்புறத்தில் மேற்கே பாளயமிறங்கவேண்டும்.", "en": "The families of the Gershonites shall pitch behind the tabernacle westward."}, {"verse": 24, "start": 232.12, "end": 239.11, "ta": "கெர்சோனியருடைய தகப்பன் வம்சத்துக்குத் தலைவன் லாயேலின் குமாரனாகிய எலியாசாப் என்பவன்.", "en": "And the chief of the house of the father of the Gershonites shall be Eliasaph the son of Lael."}, {"verse": 25, "start": 239.11, "end": 249.45, "ta": "ஆசரிப்புக் கூடாரத்திலே கெர்சோன் புத்திரரின் காவலாவது: வாசஸ்தலமும், கூடாரமும், அதின் மூடியும், ஆசரிப்புக் கூடாரவாசல் மறைவும்,", "en": "And the charge of the sons of Gershon in the tabernacle of the congregation shall be the tabernacle, and the tent, the covering thereof, and the hanging for the door of the tabernacle of the congregation,"}, {"verse": 26, "start": 249.45, "end": 263.59, "ta": "வாசஸ்தலத்தண்டையிலும் பலிபீடத்தண்டையிலும் சுற்றிலும் இருக்கிற பிராகாரத்தின் தொங்குதிரைகளும், பிராகாரவாசல் மூடுதிரையும், அவைகளின் வேலைகளுக்கெல்லாம் உரிய அவைகளின் கயிறுகளுமே.", "en": "And the hangings of the court, and the curtain for the door of the court, which is by the tabernacle, and by the altar round about, and the cords of it for all the service thereof."}, {"verse": 27, "start": 263.59, "end": 275.68, "ta": "கோகாத்தின் வழியாய் அம்ராமியரின் வம்சமும் இத்சேயாரின் வம்சமும் எப்ரோனியரின் வம்சமும் ஊசியேலரின் வம்சமும் தோன்றின; இவைகளே கோகாத்தியரின் வம்சங்கள்.", "en": "And of Kohath was the family of the Amramites, and the family of the Izeharites, and the family of the Hebronites, and the family of the Uzzielites: these are the families of the Kohathites."}, {"verse": 28, "start": 275.68, "end": 288.76, "ta": "ஒரு மாதம்முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளெல்லாம் எண்ணப்பட்டபோது, பரிசுத்த ஸ்தலத்துக்குரியவைகளைக் காப்பவர்கள், எண்ணாயிரத்து அறுநூறுபேராயிருந்தார்கள்.", "en": "In the number of all the males, from a month old and upward, were eight thousand and six hundred, keeping the charge of the sanctuary."}, {"verse": 29, "start": 288.76, "end": 295.83, "ta": "கோகாத் புத்திரரின் வம்சங்கள் வாசஸ்தலத்தின் தென்புறமான பக்கத்திலே பாளயமிறங்கவேண்டும்.", "en": "The families of the sons of Kohath shall pitch on the side of the tabernacle southward."}, {"verse": 30, "start": 295.83, "end": 300.47, "ta": "அவர்களின் தலைவன், ஊசியேலின் குமாரனாகிய எல்சாபான்.", "en": "And the chief of the house of the father of the families of the Kohathites shall be Elizaphan the son of Uzziel."}, {"verse": 31, "start": 300.47, "end": 316.05, "ta": "அவர்களுடைய காவலாவது: பெட்டியும், மேஜையும், குத்துவிளக்கும், பீடங்களும், ஆராதனைக்கேற்ற பரிசுத்தஸ்தலத்தின் பணிமுட்டுகளும், தொங்குதிரையும், அதினுடைய எல்லா வேலைகளுக்கும் ஏற்றவைகளுமே.", "en": "And their charge shall be the ark, and the table, and the candlestick, and the altars, and the vessels of the sanctuary wherewith they minister, and the hanging, and all the service thereof."}, {"verse": 32, "start": 316.05, "end": 328.9, "ta": "ஆசாரியனாகிய ஆரோனின் குமாரன் எலெயாசார் என்பவன் லேவியருடைய தலைவர்களுக்குத் தலைவனாய்ப் பரிசுத்த ஸ்தலத்தைக் காவல்காக்கிறவர்களுக்கு விசாரிப்புக்காரனாயிருக்கவேண்டும்.", "en": "And Eleazar the son of Aaron the priest shall be chief over the chief of the Levites, and have the oversight of them that keep the charge of the sanctuary."}, {"verse": 33, "start": 328.9, "end": 337.27, "ta": "மெராரியின் வழியாய் மகேலியரின் வம்சமும் மூசியரின் வம்சமும் தோன்றின; இவைகளே மெராரியின் வம்சங்கள்.", "en": "Of Merari was the family of the Mahlites, and the family of the Mushites: these are the families of Merari."}, {"verse": 34, "start": 337.27, "end": 348.59, "ta": "அவர்களில் ஒரு மாதம்முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளெல்லாம் எண்ணப்பட்டபோது, எண்ணப்பட்டவர்கள் ஆறாயிரத்து இருநூறுபேராயிருந்தார்கள்.", "en": "And those that were numbered of them, according to the number of all the males, from a month old and upward, were six thousand and two hundred."}, {"verse": 35, "start": 348.59, "end": 359.85, "ta": "அபியாயேலின் குமாரனாகிய சூரியேல் என்பவன் அவர்களுக்குத் தலைவனாயிருந்தான்; இவர்கள் வாசஸ்தலத்தின் வடபுறமான பக்கத்தில் பாளயமிறங்கவேண்டும்.", "en": "And the chief of the house of the father of the families of Merari was Zuriel the son of Abihail: these shall pitch on the side of the tabernacle northward."}, {"verse": 36, "start": 359.85, "end": 372.77, "ta": "அவர்களுடைய காவல் விசாரிப்பாவது: வாசஸ்தலத்தின் பலகைகளும், தாழ்ப்பாள்களும், தூண்களும், பாதங்களும் அதினுடைய எல்லாப் பணிமுட்டுகளும், அதற்கடுத்தவைகள் அனைத்தும்,", "en": "And under the custody and charge of the sons of Merari shall be the boards of the tabernacle, and the bars thereof, and the pillars thereof, and the sockets thereof, and all the vessels thereof, and all that serveth thereto,"}, {"verse": 37, "start": 372.77, "end": 379.92, "ta": "சுற்றுப்பிராகாரத்தின் தூண்களும், அவைகளின் பாதங்களும், முளைகளும், கயிறுகளுமே.", "en": "And the pillars of the court round about, and their sockets, and their pins, and their cords."}, {"verse": 38, "start": 379.92, "end": 402.73, "ta": "ஆசரிப்புக் கூடாரமாகிய வாசஸ்தலத்துக்கு முன்பாக, சூரியன் உதிக்கும் கீழ்ப்புறத்திலே மோசேயும் ஆரோனும் அவன் குமாரரும் கூடாரங்களைப் போட்டு இறங்கி, இஸ்ரவேல் புத்திரரின் காவலுக்குப் பதிலாகப் பரிசுத்த ஸ்தலத்தைக் காவல் காக்கவேண்டும். வாசஸ்தலத்தில் சேருகிற அந்நியன் கொலைசெய்யப்படக்கடவன்.", "en": "But those that encamp before the tabernacle toward the east, even before the tabernacle of the congregation eastward, shall be Moses, and Aaron and his sons, keeping the charge of the sanctuary for the charge of the children of Israel; and the stranger that cometh nigh shall be put to death."}, {"verse": 39, "start": 402.73, "end": 419.15, "ta": "மோசேயும் ஆரோனும், கர்த்தருடைய வாக்கின்படி, லேவியரில் ஒரு மாதம்முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளையெல்லாம் அவர்களுடைய வம்சங்களின்படி எண்ணினார்கள்; அவர்கள் இருபத்தீராயிரம் பேராயிருந்தார்கள்.", "en": "All that were numbered of the Levites, which Moses and Aaron numbered at the commandment of the LORD , throughout their families, all the males from a month old and upward, were twenty and two thousand."}, {"verse": 40, "start": 419.15, "end": 432.3, "ta": "அதன்பின்பு கர்த்தர் மோசேயை நோக்கி: நீ இஸ்ரவேல் புத்திரரில் ஒருமாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள முதற்பேறான ஆண்பிள்ளைகளையெல்லாம் எண்ணி, அவர்கள் நாமங்களைத் தொகையேற்றி,", "en": "And the LORD said unto Moses, Number all the firstborn of the males of the children of Israel from a month old and upward, and take the number of their names."}, {"verse": 41, "start": 432.3, "end": 449.49, "ta": "இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறான யாவுக்கும் பதிலாக லேவியரையும், இஸ்ரவேல் புத்திரரின் மிருகஜீவன்களிலுள்ள தலையீற்றான யாவுக்கும் பதிலாக லேவியரின் மிருகஜீவன்களையும் எனக்கென்று பிரித்தெடு; நான் கர்த்தர் என்றார்.", "en": "And thou shalt take the Levites for me (I am the LORD ) instead of all the firstborn among the children of Israel; and the cattle of the Levites instead of all the firstlings among the cattle of the children of Israel."}, {"verse": 42, "start": 449.49, "end": 458.76, "ta": "அப்பொழுது மோசே, கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறான யாவரையும் எண்ணினான்.", "en": "And Moses numbered, as the LORD commanded him, all the firstborn among the children of Israel."}, {"verse": 43, "start": 458.76, "end": 471.69, "ta": "ஒரு மாதம்முதல் அதற்கு மேற்பட்ட வயதுள்ள முதற்பேறான ஆண்பிள்ளைகளெல்லாரும் பேர்பேராக எண்ணப்பட்டபோது, இருபத்தீராயிரத்து இருநூற்று எழுபத்துமூன்று பேராயிருந்தார்கள்.", "en": "And all the firstborn males by the number of names, from a month old and upward, of those that were numbered of them, were twenty and two thousand two hundred and threescore and thirteen."}, {"verse": 44, "start": 471.69, "end": 474.2, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 45, "start": 474.2, "end": 491.07, "ta": "நீ இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறான யாவருக்கும் பதிலாக லேவியரையும், அவர்களுடைய மிருகஜீவன்களுக்குப்பதிலாக லேவியரின் மிருகஜீவன்களையும் பிரித்தெடு; லேவியர் என்னுடையவர்களாயிருப்பார்கள்; நான் கர்த்தர்.", "en": "Take the Levites instead of all the firstborn among the children of Israel, and the cattle of the Levites instead of their cattle; and the Levites shall be mine: I am the LORD ."}, {"verse": 46, "start": 491.07, "end": 501.19, "ta": "இஸ்ரவேல் புத்திரருடைய முதற்பேறுகளில் லேவியரின் தொகைக்கு அதிகமாயிருந்து, மீட்கப்படவேண்டிய இருநூற்று எழுபத்துமூன்றுபேரிடத்திலும்,", "en": "And for those that are to be redeemed of the two hundred and threescore and thirteen of the firstborn of the children of Israel, which are more than the Levites;"}, {"verse": 47, "start": 501.19, "end": 510.39, "ta": "நீ தலைக்கு ஐந்து சேக்கல் வீதமாகப் பரிசுத்த சேக்கல் கணக்கின்படி வாங்குவாயாக; அந்தச் சேக்கலானது இருபது கேரா.", "en": "Thou shalt even take five shekels apiece by the poll, after the shekel of the sanctuary shalt thou take them: (the shekel is twenty gerahs:)"}, {"verse": 48, "start": 510.39, "end": 519.36, "ta": "லேவியருடைய தொகைக்கு அதிகமானவர்கள் மீட்கப்படும் திரவியத்தை ஆரோனுக்கும் அவன் குமாரருக்கும் கொடுப்பாயாக என்றார்.", "en": "And thou shalt give the money, wherewith the odd number of them is to be redeemed, unto Aaron and to his sons."}, {"verse": 49, "start": 519.36, "end": 531.6, "ta": "அப்படியே லேவியரால் மீட்கப்பட்டவர்களின் தொகைக்கு அதிகமாயிருந்து, இன்னும் மீட்கப்படவேண்டியவர்களுக்கு ஈடாக மோசே இஸ்ரவேல் புத்திரருடைய முதற்பேறானவர்களிடத்தில்,", "en": "And Moses took the redemption money of them that were over and above them that were redeemed by the Levites:"}, {"verse": 50, "start": 531.6, "end": 539.89, "ta": "ஆயிரத்து முந்நூற்று அறுபத்தைந்து சேக்கலாகிய திரவியத்தை, பரிசுத்த ஸ்தலத்துச் சேக்கல் கணக்கின்படி வாங்கி,", "en": "Of the firstborn of the children of Israel took he the money; a thousand three hundred and threescore and five shekels , after the shekel of the sanctuary:"}, {"verse": 51, "start": 539.89, "end": 550.91, "ta": "கர்த்தருடைய வாக்கின்படியே மீட்கப்பட்டவர்களின் கிரயத்தை ஆரோனுக்கும் அவன் குமாரருக்கும், கர்த்தர் தனக்குக் கட்டளையிட்டபடியே கொடுத்தான்.", "en": "And Moses gave the money of them that were redeemed unto Aaron and to his sons, according to the word of the LORD , as the LORD commanded Moses."}]}, "4": {"chapter": 4, "duration": 540.76, "audio_url": "audio_ot/OT04_04.mp3", "total_verses": 49, "verses": [{"verse": 1, "start": 3.8, "end": 6.63, "ta": "கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 2, "start": 6.63, "end": 13.52, "ta": "லேவியின் புத்திரருக்குள்ளே இருக்கிற கோகாத் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களில்,", "en": "Take the sum of the sons of Kohath from among the sons of Levi, after their families, by the house of their fathers,"}, {"verse": 3, "start": 13.52, "end": 24.54, "ta": "ஆசரிப்புக் கூடாரத்திலே வேலைசெய்யும் சேனைக்கு உட்படத்தக்க முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணி, தொகையிடுவாயாக.", "en": "From thirty years old and upward even until fifty years old, all that enter into the host, to do the work in the tabernacle of the congregation."}, {"verse": 4, "start": 24.54, "end": 31.36, "ta": "ஆசரிப்புக் கூடாரத்திலே கோகாத் புத்திரரின் பணிவிடை மகா பரிசுத்தமானவைகளுக்குரியது.", "en": "This shall be the service of the sons of Kohath in the tabernacle of the congregation, about the most holy things:"}, {"verse": 5, "start": 31.36, "end": 41.08, "ta": "பாளயம் புறப்படும்போது, ஆரோனும் அவன் குமாரரும் வந்து, மறைவின் திரைச்சீலையை இறக்கி, அதினாலே சாட்சியின் பெட்டியை மூடி,", "en": "And when the camp setteth forward, Aaron shall come, and his sons, and they shall take down the covering vail, and cover the ark of testimony with it:"}, {"verse": 6, "start": 41.08, "end": 50.42, "ta": "அதின்மேல் தகசுத்தோல் மூடியைப்போட்டு, அதின்மேல் முற்றிலும் நீலமான துப்பட்டியை விரித்து, அதின் தண்டுகளைப் பாய்ச்சி,", "en": "And shall put thereon the covering of badgers’ skins, and shall spread over it a cloth wholly of blue, and shall put in the staves thereof."}, {"verse": 7, "start": 50.42, "end": 65.96, "ta": "சமுகத்தப்ப மேஜையின்மேல் நீலத் துப்பட்டியை விரித்து, தட்டுகளையும் தூபக்கரண்டிகளையும் கிண்ணங்களையும் மூடுகிற தட்டுகளையும் அதின்மேல் வைப்பார்களாக; நித்திய அப்பமும் அதின்மேல் இருக்கக்கடவது.", "en": "And upon the table of shewbread they shall spread a cloth of blue, and put thereon the dishes, and the spoons, and the bowls, and covers to cover withal: and the continual bread shall be thereon:"}, {"verse": 8, "start": 65.96, "end": 75.14, "ta": "அவைகளின்மேல் அவர்கள் சிவப்புத் துப்பட்டியை விரித்து, அதைத் தகசுத்தோல் மூடியால் மூடி, அதின் தண்டுகளைப் பாய்ச்சி,", "en": "And they shall spread upon them a cloth of scarlet, and cover the same with a covering of badgers’ skins, and shall put in the staves thereof."}, {"verse": 9, "start": 75.14, "end": 89.0, "ta": "இளநீலத் துப்பட்டியை எடுத்து, குத்துவிளக்குத்தண்டையும், அதின் அகல்களையும், அதின் கத்தரிகளையும், சாம்பல் பாத்திரங்களையும், அதற்குரிய எண்ணெய்ப் பாத்திரங்களையும் மூடி,", "en": "And they shall take a cloth of blue, and cover the candlestick of the light, and his lamps, and his tongs, and his snuffdishes, and all the oil vessels thereof, wherewith they minister unto it:"}, {"verse": 10, "start": 89.0, "end": 96.88, "ta": "அதையும் அதற்கடுத்த தட்டுமுட்டுகள் யாவையும் தகசுத்தோல் மூடிக்குள்ளே போட்டு, அதை ஒரு தண்டிலே கட்டி,", "en": "And they shall put it and all the vessels thereof within a covering of badgers’ skins, and shall put it upon a bar."}, {"verse": 11, "start": 96.88, "end": 105.69, "ta": "பொற்பீடத்தின்மேல் இளநீலத் துப்பட்டியை விரித்து, அதைத் தகசுத்தோல் மூடியால் மூடி, அதின் தண்டுகளைப் பாய்ச்சி,", "en": "And upon the golden altar they shall spread a cloth of blue, and cover it with a covering of badgers’ skins, and shall put to the staves thereof:"}, {"verse": 12, "start": 105.69, "end": 118.16, "ta": "பரிசுத்த ஸ்தலத்தில் வழங்கும் ஆராதனைக்கேற்ற சகல தட்டுமுட்டுகளையும் எடுத்து, இளநீலத் துப்பட்டியிலே போட்டு, தகசுத்தோல் மூடியினால் மூடி, தண்டின்மேல் கட்டி,", "en": "And they shall take all the instruments of ministry, wherewith they minister in the sanctuary, and put them in a cloth of blue, and cover them with a covering of badgers’ skins, and shall put them on a bar:"}, {"verse": 13, "start": 118.16, "end": 124.29, "ta": "பலிபீடத்தைச் சாம்பலற விளக்கி, அதின்மேல் இரத்தாம்பரத் துப்பட்டியை விரித்து,", "en": "And they shall take away the ashes from the altar, and spread a purple cloth thereon:"}, {"verse": 14, "start": 124.29, "end": 146.41, "ta": "அதின்மேல் ஆராதனைக்கேற்ற சகல பணிமுட்டுகளாகிய கலசங்களையும், முள்துறடுகளையும், சாம்பல் எடுக்கும் கரண்டிகளையும், கலசங்களையும், பலிபீடத்திற்கடுத்த எல்லாப் பாத்திரங்களையும், அதின்மேல் வைத்து, அதின்மேல் தகசுத்தோல் மூடியை விரித்து, அதின் தண்டுகளைப் பாய்ச்சக்கடவர்கள்.", "en": "And they shall put upon it all the vessels thereof, wherewith they minister about it, even the censers, the fleshhooks, and the shovels, and the basons, all the vessels of the altar; and they shall spread upon it a covering of badgers’ skins, and put to the staves of it."}, {"verse": 15, "start": 146.41, "end": 171.75, "ta": "பாளயம் புறப்படும்போது, ஆரோனும் அவன் குமாரரும் பரிசுத்த ஸ்தலத்தையும் அதினுடைய சகல பணிமுட்டுகளையும் மூடித் தீர்ந்தபின்பு, கோகாத் புத்திரர் அதை எடுத்துக்கொண்டுபோகிறதற்கு வரக்கடவர்கள்; அவர்கள் சாகாதபடிக்குப் பரிசுத்தமானதைத் தொடாதிருக்கக்கடவர்கள்; ஆசரிப்புக் கூடாரத்திலே கோகாத் புத்திரர் சுமக்கும் சுமை இதுவே.", "en": "And when Aaron and his sons have made an end of covering the sanctuary, and all the vessels of the sanctuary, as the camp is to set forward; after that, the sons of Kohath shall come to bear it: but they shall not touch any holy thing, lest they die. These things are the burden of the sons of Kohath in the tabernacle of the congregation."}, {"verse": 16, "start": 171.75, "end": 193.79, "ta": "ஆசாரியனாகிய ஆரோனின் குமாரன் எலெயாசார், விளக்குக்கு எண்ணெயையும், சுகந்த தூபவர்க்கத்தையும், தினந்தோறும் இடும் போஜனபலியையும், அபிஷேக தைலத்தையும், வாசஸ்தலம் முழுவதையும், அதிலுள்ள யாவையும், பரிசுத்தஸ்தலத்தையும் அதின் பணிமுட்டுகளையும், விசாரிக்கக்கடவன் என்றார்.", "en": "And to the office of Eleazar the son of Aaron the priest pertaineth the oil for the light, and the sweet incense, and the daily meat offering, and the anointing oil, and the oversight of all the tabernacle, and of all that therein is , in the sanctuary, and in the vessels thereof."}, {"verse": 17, "start": 193.79, "end": 196.63, "ta": "கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 18, "start": 196.63, "end": 202.9, "ta": "லேவியருக்குள்ளே கோகாத் வம்சமாகிய கோத்திரத்தார் அழிந்துபோகாதபடி பாருங்கள்.", "en": "Cut ye not off the tribe of the families of the Kohathites from among the Levites:"}, {"verse": 19, "start": 202.9, "end": 212.4, "ta": "அவர்கள் மகா பரிசுத்தமானவைகளைக் கிட்டுகையில், சாகாமல் உயிரோடிருக்கும்படிக்கு, நீங்கள் அவர்களுக்காகச் செய்யவேண்டியதாவது:", "en": "But thus do unto them, that they may live, and not die, when they approach unto the most holy things: Aaron and his sons shall go in, and appoint them every one to his service and to his burden:"}, {"verse": 20, "start": 212.4, "end": 231.38, "ta": "ஆரோனும் அவன் குமாரரும் வந்து, அவர்களில் அவனவனை அவனவன் செய்யும் வேலைக்கும் அவனவன் சுமக்கும் சுமைக்கும் நியமிக்கக்கடவர்கள்; அவர்களோ சாகாதபடிக்குப் பரிசுத்தமானவைகள் மூடப்படும்போது பார்க்கிறதற்கு உட்பிரவேசியாமல் இருப்பார்களாக என்றார்.", "en": "But they shall not go in to see when the holy things are covered, lest they die."}, {"verse": 21, "start": 231.38, "end": 234.14, "ta": "பின்னும், கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 22, "start": 234.14, "end": 243.55, "ta": "கெர்சோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை வேலைசெய்யும் சேனைக்கு உட்படத்தக்க,", "en": "Take also the sum of the sons of Gershon, throughout the houses of their fathers, by their families;"}, {"verse": 23, "start": 243.55, "end": 250.36, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணி, தொகை ஏற்றுவாயாக.", "en": "From thirty years old and upward until fifty years old shalt thou number them; all that enter in to perform the service, to do the work in the tabernacle of the congregation."}, {"verse": 24, "start": 250.36, "end": 255.65, "ta": "பணிவிடை செய்கிறதிலும் சுமக்கிறதிலும் கெர்சோன் வம்சத்தாரின் வேலையாவது:", "en": "This is the service of the families of the Gershonites, to serve, and for burdens:"}, {"verse": 25, "start": 255.65, "end": 269.2, "ta": "அவர்கள் வாசஸ்தலத்துக்கும் ஆசரிப்புக் கூடாரத்துக்கும் உரிய தொங்குதிரையையும், மூடியையும், அவைகளின்மேல் இருக்கிற தகசுத்தோல் மூடியையும், ஆசரிப்புக் கூடாரவாசல் மறைவையும்,", "en": "And they shall bear the curtains of the tabernacle, and the tabernacle of the congregation, his covering, and the covering of the badgers’ skins that is above upon it, and the hanging for the door of the tabernacle of the congregation,"}, {"verse": 26, "start": 269.2, "end": 290.63, "ta": "பிராகாரத்தின் தொங்குதிரைகளையும், வாசஸ்தலத்தண்டையிலும் பலிபீடத்தண்டையிலும் சுற்றிலும் இருக்கிற பிராகாரத்தினுடைய வாசல் தொங்குதிரையையும், அவைகளின் கயிறுகளையும், அவைகளின் வேலைக்கடுத்த கருவிகள் யாவையும் சுமந்து, அவைகளுக்காகச் செய்யவேண்டிய யாவையும் செய்யக்கடவர்கள்.", "en": "And the hangings of the court, and the hanging for the door of the gate of the court, which is by the tabernacle and by the altar round about, and their cords, and all the instruments of their service, and all that is made for them: so shall they serve."}, {"verse": 27, "start": 290.63, "end": 308.92, "ta": "கெர்சோன் புத்திரர் சுமக்கவேண்டிய சுமைகளும் செய்யவேண்டிய பணிவிடைகளாகிய சகல வேலைகளும் ஆரோனும் அவன் குமாரரும் சொல்லுகிறபடியே செய்யவேண்டும், அவர்கள் சுமக்கவேண்டிய சகல சுமைகளையும் நீங்கள் நியமித்து, அவர்களிடத்தில் ஒப்புவியுங்கள்.", "en": "At the appointment of Aaron and his sons shall be all the service of the sons of the Gershonites, in all their burdens, and in all their service: and ye shall appoint unto them in charge all their burdens."}, {"verse": 28, "start": 308.92, "end": 323.77, "ta": "கெர்சோன் புத்திரரின் வம்சத்தார் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடை இதுதான்; அவர்களை வேலைகொள்ளும் விசாரணை, ஆசாரியனாகிய ஆரோரின் குமாரன் இத்தாமாருடைய கைக்குள் இருக்கவேண்டும்.", "en": "This is the service of the families of the sons of Gershon in the tabernacle of the congregation: and their charge shall be under the hand of Ithamar the son of Aaron the priest."}, {"verse": 29, "start": 323.77, "end": 333.04, "ta": "மெராரி புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை வேலைசெய்யும் சேனைக்கு உட்படத்தக்க,", "en": "As for the sons of Merari, thou shalt number them after their families, by the house of their fathers;"}, {"verse": 30, "start": 333.04, "end": 338.85, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணக்கடவாய்.", "en": "From thirty years old and upward even unto fifty years old shalt thou number them, every one that entereth into the service, to do the work of the tabernacle of the congregation."}, {"verse": 31, "start": 338.85, "end": 351.56, "ta": "ஆசரிப்புக் கூடாரத்தில் அவர்கள் செய்யும் எல்லாப் பணிவிடைக்கும் அடுத்த காவல் விசாரிப்பாவது: வாசஸ்தலத்தின் பலகைகளும், தாழ்ப்பாள்களும், தூண்களும், பாதங்களும்,", "en": "And this is the charge of their burden, according to all their service in the tabernacle of the congregation; the boards of the tabernacle, and the bars thereof, and the pillars thereof, and sockets thereof,"}, {"verse": 32, "start": 351.56, "end": 372.31, "ta": "சுற்றிலும் இருக்கிற பிராகாரத்தின் தூண்களும், அவைகளின் பாதங்களும், முளைகளும், கயிறுகளும், அவைகளின் சகல கருவிகளும், அவற்றிற்கு அடுத்த மற்றெல்லா வேலையும்தானே; அவர்கள் சுமந்து காவல்காக்கும்படி ஒப்புவிக்கப்படுகிறவைகளைப் பேர்பேராக எண்ணக்கடவீர்கள்.", "en": "And the pillars of the court round about, and their sockets, and their pins, and their cords, with all their instruments, and with all their service: and by name ye shall reckon the instruments of the charge of their burden."}, {"verse": 33, "start": 372.31, "end": 385.7, "ta": "ஆசாரியனாகிய ஆரோனுடைய குமாரனான இத்தாமாருடைய கைக்குள்ளாக மெராரி புத்திரரின் வம்சத்தாரர் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடைக்கு அடுத்த எல்லா வேலையும் இதுவே என்றார்.", "en": "This is the service of the families of the sons of Merari, according to all their service, in the tabernacle of the congregation, under the hand of Ithamar the son of Aaron the priest."}, {"verse": 34, "start": 385.7, "end": 398.33, "ta": "அப்படியே மோசேயும் ஆரோனும் சபையின் பிரபுக்களும் கோகாத் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களின்படி ஆசரிப்புக் கூடாரத்திலே பணிவிடை செய்யும் சேனைக்கு உட்படத்தக்க,", "en": "And Moses and Aaron and the chief of the congregation numbered the sons of the Kohathites after their families, and after the house of their fathers,"}, {"verse": 35, "start": 398.33, "end": 404.15, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணினார்கள்.", "en": "From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation:"}, {"verse": 36, "start": 404.15, "end": 410.35, "ta": "அவர்கள் வம்சங்களில் எண்ணப்பட்டவர்கள் இரண்டாயிரத்து எழுநூற்று ஐம்பதுபேர்.", "en": "And those that were numbered of them by their families were two thousand seven hundred and fifty."}, {"verse": 37, "start": 410.35, "end": 424.51, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, மோசேயினாலும் ஆரோனாலும் கோகாத் வம்சத்தாரில் ஆசரிப்புக் கூடாரத்தில் வேலை செய்கிறதற்காக, எண்ணித் தொகையிடப்பட்டவர்கள் எல்லாரும் இவர்களே.", "en": "These were they that were numbered of the families of the Kohathites, all that might do service in the tabernacle of the congregation, which Moses and Aaron did number according to the commandment of the LORD by the hand of Moses."}, {"verse": 38, "start": 424.51, "end": 433.62, "ta": "கெர்சோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை செய்யும் சேனைக்கு உட்படத்தக்க,", "en": "And those that were numbered of the sons of Gershon, throughout their families, and by the house of their fathers,"}, {"verse": 39, "start": 433.62, "end": 439.59, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரும் எண்ணப்பட்டார்கள்.", "en": "From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,"}, {"verse": 40, "start": 439.59, "end": 450.23, "ta": "அவர்களில் எண்ணப்பட்டவர்கள் அவரவர் குடும்பத்தின்படிக்கும், பிதாக்களுடைய வம்சத்தின்படிக்கும் இரண்டாயிரத்து அறுநூற்று முப்பதுபேர்.", "en": "Even those that were numbered of them, throughout their families, by the house of their fathers, were two thousand and six hundred and thirty."}, {"verse": 41, "start": 450.23, "end": 463.32, "ta": "மோசேயினாலும் ஆரோனாலும் கர்த்தர் கட்டளையிட்டபடியே கெர்சோன் புத்திரரின் வம்சத்தாரில் ஆசரிப்புக் கூடாரத்தில் வேலைசெய்ய எண்ணித் தொகையிடப்பட்டவர்கள் எல்லாரும் இவர்களே.", "en": "These are they that were numbered of the families of the sons of Gershon, of all that might do service in the tabernacle of the congregation, whom Moses and Aaron did number according to the commandment of the LORD ."}, {"verse": 42, "start": 463.32, "end": 472.28, "ta": "மெராரி புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை செய்யும் சேனைக்கு உட்படத்தக்க,", "en": "And those that were numbered of the families of the sons of Merari, throughout their families, by the house of their fathers,"}, {"verse": 43, "start": 472.28, "end": 478.02, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுள்ளவர்கள் எல்லாரும் எண்ணப்பட்டார்கள்.", "en": "From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,"}, {"verse": 44, "start": 478.02, "end": 484.68, "ta": "அவர்களில் எண்ணப்பட்டவர்கள் தங்கள் குடும்பங்களின்படியே மூவாயிரத்து இருநூறுபேர்.", "en": "Even those that were numbered of them after their families, were three thousand and two hundred."}, {"verse": 45, "start": 484.68, "end": 496.16, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே மோசேயினாலும் ஆரோனாலும் மெராரி புத்திரரின் குடும்பத்தாரில் எண்ணித் தொகையிடப்பட்டவர்கள் எல்லாரும் இவர்களே.", "en": "These be those that were numbered of the families of the sons of Merari, whom Moses and Aaron numbered according to the word of the LORD by the hand of Moses."}, {"verse": 46, "start": 496.16, "end": 510.17, "ta": "லேவியருடைய பிதாக்களின் வீட்டு வம்சங்களில் முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ளவர்கள் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடைவேலைக்கும் சுமையின் வேலைக்கும் உட்படத்தக்கவர்களும்,", "en": "All those that were numbered of the Levites, whom Moses and Aaron and the chief of Israel numbered, after their families, and after the house of their fathers,"}, {"verse": 47, "start": 510.17, "end": 516.75, "ta": "மோசேயினாலும் ஆரோனாலும் இஸ்ரவேலின் பிரபுக்களாலும் எண்ணப்பட்டவர்களும் ஆகிய எல்லாரும்,", "en": "From thirty years old and upward even unto fifty years old, every one that came to do the service of the ministry, and the service of the burden in the tabernacle of the congregation,"}, {"verse": 48, "start": 516.75, "end": 521.04, "ta": "எண்ணாயிரத்து ஐந்நூற்று எண்பதுபேராயிருந்தார்கள்.", "en": "Even those that were numbered of them, were eight thousand and five hundred and fourscore."}, {"verse": 49, "start": 521.04, "end": 539.26, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, அவர்கள் தங்கள் தங்கள் பணிவிடைக்கென்றும் தங்கள் தங்கள் சுமைக்கென்றும் மோசேயினால் எண்ணப்பட்டார்கள்; இவ்விதமாய், கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே அவர்கள் அவனால் எண்ணப்பட்டார்கள்.", "en": "According to the commandment of the LORD they were numbered by the hand of Moses, every one according to his service, and according to his burden: thus were they numbered of him, as the LORD commanded Moses."}]}, "5": {"chapter": 5, "duration": 393.34, "audio_url": "audio_ot/OT04_05.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 5.54, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.54, "end": 18.59, "ta": "குஷ்டரோகிகள் யாவரையும், பிரமியமுள்ளவர்கள் யாவரையும், சவத்தினால் தீட்டுப்பட்டவர்கள் யாவரையும் பாளயத்திலிருந்து விலக்கிவிட இஸ்ரவேல் புத்திரருக்குக் கட்டளையிடு.", "en": "Command the children of Israel, that they put out of the camp every leper, and every one that hath an issue, and whosoever is defiled by the dead:"}, {"verse": 3, "start": 18.59, "end": 35.57, "ta": "ஆண்பிள்ளையானாலும் பெண்பிள்ளையானாலும் அப்படிப்பட்டவர்களை நீங்கள் விலக்கி, நான் வாசம்பண்ணுகிற தங்கள் பாளயங்களை அவர்கள் தீட்டுப்படுத்தாதபடிக்கு, நீங்கள் அவர்களைப் பாளயத்திற்குப் புறம்பாக்கிவிடக்கடவீர்கள் என்றார்.", "en": "Both male and female shall ye put out, without the camp shall ye put them; that they defile not their camps, in the midst whereof I dwell."}, {"verse": 4, "start": 35.57, "end": 44.83, "ta": "கர்த்தர் மோசேக்குச் சொன்னபடியே, இஸ்ரவேல் புத்திரர் செய்து, அவர்களைப் பாளயத்திற்குப் புறம்பாக்கிவிட்டார்கள்.", "en": "And the children of Israel did so, and put them out without the camp: as the LORD spake unto Moses, so did the children of Israel."}, {"verse": 5, "start": 44.83, "end": 47.1, "ta": "மேலும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 6, "start": 47.1, "end": 60.98, "ta": "இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: ஒரு புருஷனானாலும் ஸ்திரீயானாலும், கர்த்தருடைய கட்டளையை மீறி மனிதர் செய்யும் பாவங்களில் யாதொரு பாவத்தைச் செய்து குற்றவாளியானால்,", "en": "Speak unto the children of Israel, When a man or woman shall commit any sin that men commit, to do a trespass against the LORD , and that person be guilty;"}, {"verse": 7, "start": 60.98, "end": 76.45, "ta": "அவர்கள் தாங்கள் செய்த பாவத்தை அறிக்கையிடக்கடவர்கள்; அப்படிப்பட்டவன் தான் செய்த குற்றத்தினிமித்தம் அபராதத்தின் முதலோடே ஐந்தில் ஒருபங்கை அதிகமாய்க் கூட்டி, தான் குற்றஞ்செய்தவனுக்குச் செலுத்தக்கடவன்", "en": "Then they shall confess their sin which they have done: and he shall recompense his trespass with the principal thereof, and add unto it the fifth part thereof, and give it unto him against whom he hath trespassed."}, {"verse": 8, "start": 76.45, "end": 94.19, "ta": "அதைக் கேட்டு வாங்குகிறதற்கு இனத்தான் ஒருவனும் இல்லாதிருந்தால், அப்பொழுது அவனுக்காகப் பாவநிவிர்த்தி செய்யும்படி ஆட்டுக்கடா செலுத்தப்படுவதுமல்லாமல், கர்த்தருக்கு அந்த அபராதம் செலுத்தப்பட்டு, அது ஆசாரியனைச் சேரவேண்டும்.", "en": "But if the man have no kinsman to recompense the trespass unto, let the trespass be recompensed unto the LORD , even to the priest; beside the ram of the atonement, whereby an atonement shall be made for him."}, {"verse": 9, "start": 94.19, "end": 104.2, "ta": "இஸ்ரவேல் புத்திரர் ஏறெடுத்துப் படைக்கும்படி ஆசாரியனிடத்தில் கொண்டுவருகிற எல்லாப் பரிசுத்தமான படைப்பும் அவனுடையதாயிருக்கும்.", "en": "And every offering of all the holy things of the children of Israel, which they bring unto the priest, shall be his."}, {"verse": 10, "start": 104.2, "end": 116.26, "ta": "ஒவ்வொருவரும் படைக்கும் பரிசுத்தமான வஸ்துக்கள் அவனுடையதாயிருக்கும்; ஒருவன் ஆசாரியனுக்குக் கொடுக்கிறது எதுவும் அவனுக்கே உரியது என்று சொல் என்றார்.", "en": "And every man’s hallowed things shall be his: whatsoever any man giveth the priest, it shall be his."}, {"verse": 11, "start": 116.26, "end": 118.01, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 12, "start": 118.01, "end": 127.64, "ta": "நீ இஸ்ரவேல் புத்திரருக்குச் சொல்லவேண்டியது என்னவென்றால்: ஒருவனுடைய மனைவி பிறர்முகம் பார்த்து, புருஷனுக்குத் துரோகம்பண்ணி,", "en": "Speak unto the children of Israel, and say unto them, If any man’s wife go aside, and commit a trespass against him,"}, {"verse": 13, "start": 127.64, "end": 145.68, "ta": "ஒருவனோடே சம்யோகமாய்ச் சயனித்திருந்த விஷயத்தில் அவள் தீட்டுப்பட்டவளாயிருந்தும், அவளுடைய புருஷன் கண்களுக்கு அது மறைக்கப்பட்டு வெளிக்கு வராமல் இருக்கிறபோதும், சாட்சியில்லாமலும் அவள் கையும் களவுமாகப் பிடிக்கப்படாமலும் இருக்கிறபோதும்,", "en": "And a man lie with her carnally, and it be hid from the eyes of her husband, and be kept close, and she be defiled, and there be no witness against her, neither she be taken with the manner;"}, {"verse": 14, "start": 145.68, "end": 166.61, "ta": "எரிச்சலின் ஆவி அவன்மேல் வந்து, அவன் தன்னுடைய மனைவி தீட்டுப்படுத்தப்பட்டிருக்க, தீட்டுப்படுத்தப்பட்ட தன் மனைவியின்மேல் குரோதங்கொண்டிருந்தாலும், அல்லது அவன் மனைவி தீட்டுப்படுத்தப்படாதிருக்க, எரிச்சலின் ஆவி அவன்மேல் வந்து, அவன் அவள்மேல் குரோதங்கொண்டிருந்தாலும்,", "en": "And the spirit of jealousy come upon him, and he be jealous of his wife, and she be defiled: or if the spirit of jealousy come upon him, and he be jealous of his wife, and she be not defiled:"}, {"verse": 15, "start": 166.61, "end": 191.72, "ta": "அந்தப் புருஷன் தன் மனைவியை ஆசாரியனிடத்தில் அழைத்துக்கொண்டு வந்து, அவள் நிமித்தம் ஒரு எப்பா அளவான வாற்கோதுமை மாவிலே பத்தில் ஒரு பங்கைப் படைப்பாகக் கொடுக்கக்கடவன்; அது எரிச்சலின் காணிக்கையும் அக்கிரமத்தை நினைப்பூட்டும் காணிக்கையுமாய் இருப்பதினால், அதின்மேல் எண்ணெய் வார்க்காமலும் தூபவர்க்கம்போடாமலும் இருப்பானாக.", "en": "Then shall the man bring his wife unto the priest, and he shall bring her offering for her, the tenth part of an ephah of barley meal; he shall pour no oil upon it, nor put frankincense thereon; for it is an offering of jealousy, an offering of memorial, bringing iniquity to remembrance."}, {"verse": 16, "start": 191.72, "end": 197.33, "ta": "ஆசாரின் அவளைச் சமீபத்தில் அழைத்து, கர்த்தருடைய சந்நிதியில் நிறுத்தி,", "en": "And the priest shall bring her near, and set her before the LORD :"}, {"verse": 17, "start": 197.33, "end": 207.26, "ta": "ஒரு மண்பாண்டத்திலே பரிசுத்த ஜலம் வார்த்து, வாசஸ்தலத்தின் தரையிலிருக்கும் புழுதியிலே கொஞ்சம் எடுத்து, அந்த ஜலத்திலே போட்டு,", "en": "And the priest shall take holy water in an earthen vessel; and of the dust that is in the floor of the tabernacle the priest shall take, and put it into the water:"}, {"verse": 18, "start": 207.26, "end": 223.94, "ta": "ஸ்திரீயைக் கர்த்தருடைய சந்நிதியில் நிறுத்தி, அவள் முக்காட்டை நீக்கி, எரிச்சலின் காணிக்கையாகிய நினைப்பூட்டுதலின் காணிக்கையை அவள் உள்ளங்கையிலே வைப்பானாக; சாபகாரணமான கசப்பான ஜலம் ஆசாரியன் கையிலிருக்கவேண்டும்,", "en": "And the priest shall set the woman before the LORD , and uncover the woman’s head, and put the offering of memorial in her hands, which is the jealousy offering: and the priest shall have in his hand the bitter water that causeth the curse:"}, {"verse": 19, "start": 223.94, "end": 241.77, "ta": "பின்பு ஆசாரியன் அவளை ஆணையிடுவித்து ஒருவனும் உன்னோடே சயனியாமலும், உன் புருஷனுக்கு உட்பட்டிருக்கிற நீ தீட்டுப்படத்தக்கதாய்ப் பிறர்முகம் பாராமலும் இருந்தால், சாபகாரணமான இந்தக் கசப்பான ஜலத்தின் தோஷத்துக்கு நீங்கலாயிருப்பாய்.", "en": "And the priest shall charge her by an oath, and say unto the woman, If no man have lain with thee, and if thou hast not gone aside to uncleanness with another instead of thy husband, be thou free from this bitter water that causeth the curse:"}, {"verse": 20, "start": 241.77, "end": 252.38, "ta": "உன் புருஷனுக்கு உட்பட்டிருக்கிற நீ பிறர்முகம் பார்த்து, உன் புருஷனோடேயன்றி அந்நியனோடே சம்யோகமாய் சயனித்துத் தீட்டுப்பட்டிருப்பாயானால்,", "en": "But if thou hast gone aside to another instead of thy husband, and if thou be defiled, and some man have lain with thee beside thine husband:"}, {"verse": 21, "start": 252.38, "end": 262.7, "ta": "கர்த்தர் உன் இடுப்பு சூம்பவும், உன் வயிறு வீங்கவும்பண்ணி, உன்னை உன் ஜனங்களுக்குள்ளே சாபமும் ஆணையிடுங்குறியுமாக வைப்பாராக.", "en": "Then the priest shall charge the woman with an oath of cursing, and the priest shall say unto the woman, The LORD make thee a curse and an oath among thy people, when the LORD doth make thy thigh to rot, and thy belly to swell;"}, {"verse": 22, "start": 262.7, "end": 281.2, "ta": "சாபகாரணமான இந்த ஜலம் உன் வயிறு வீங்கவும் இடுப்பு சூம்பவும் பண்ணும்படி, உன் குடலுக்குள் பிரவேசிக்கக்கடவது என்கிற சாபவார்த்தையாலே ஸ்திரீயை ஆணையிடுவித்துச் சொல்வானாக. அதற்கு அந்த ஸ்திரீ: ஆமென், ஆமென், என்று சொல்லக்கடவள்.", "en": "And this water that causeth the curse shall go into thy bowels, to make thy belly to swell, and thy thigh to rot: And the woman shall say, Amen, amen."}, {"verse": 23, "start": 281.2, "end": 289.31, "ta": "பின்பு ஆசாரியன் இந்தச் சாப வார்த்தைகளை ஒரு சீட்டில் எழுதி, அவைகளைக் கசப்பான ஜலத்தினால் கழுவிப்போட்டு,", "en": "And the priest shall write these curses in a book, and he shall blot them out with the bitter water:"}, {"verse": 24, "start": 289.31, "end": 299.93, "ta": "சாபகாரணமான அந்தக் கசப்பான ஜலத்தை அவள் குடிக்கும்படி பண்ணுவான்; அப்பொழுது சாபகாரணமான அந்த ஜலம் அவளுக்குள் இறங்கிக் கசப்பாகும்.", "en": "And he shall cause the woman to drink the bitter water that causeth the curse: and the water that causeth the curse shall enter into her, and become bitter."}, {"verse": 25, "start": 299.93, "end": 311.15, "ta": "பின்பு ஆசாரியன் எரிச்சலின் காணிக்கையை அந்த ஸ்திரீயின் கையிலிருந்து வாங்கி, அதைக் கர்த்தருடைய சந்நிதியில் அசைவாட்டி, பீடத்தின்மேல் செலுத்தி,", "en": "Then the priest shall take the jealousy offering out of the woman’s hand, and shall wave the offering before the LORD , and offer it upon the altar:"}, {"verse": 26, "start": 311.15, "end": 322.38, "ta": "ஞாபகக்குறியாக அதிலே ஒரு கைப்பிடி நிறைய எடுத்து, பீடத்தின்மேல் தகனித்து, பின்பு ஸ்திரீக்கு அந்த ஜலத்தைக் குடிக்கும்படி கொடுக்கக்கடவன்.", "en": "And the priest shall take an handful of the offering, even the memorial thereof, and burn it upon the altar, and afterward shall cause the woman to drink the water."}, {"verse": 27, "start": 322.38, "end": 345.58, "ta": "அந்த ஜலத்தைக் குடிக்கச் செய்தபின்பு சம்பவிப்பதாவது: அவள் தீட்டுப்பட்டு, தன் புருஷனுக்குத் துரோகம்பண்ணியிருந்தால், சாபகாரணமான அந்த ஜலம் அவளுக்குள் பிரவேசித்துக் கசப்புண்டானதினால், அவள் வயிறு வீங்கி, அவள் இடுப்பு சூம்பும்; இப்படியே அந்த ஸ்திரீ தன் ஜனங்களுக்குள்ளே சாபமாக இருப்பாள்.", "en": "And when he hath made her to drink the water, then it shall come to pass, that , if she be defiled, and have done trespass against her husband, that the water that causeth the curse shall enter into her, and become bitter, and her belly shall swell, and her thigh shall rot: and the woman shall be a curse among her people."}, {"verse": 28, "start": 345.58, "end": 354.53, "ta": "அந்த ஸ்திரீ தீட்டுப்படாமல் சுத்தமாயிருந்தால், அவள் அதற்கு நீங்கலாகி, கர்ப்பந்தரிக்கத்தக்கவளாயிருப்பாள்.", "en": "And if the woman be not defiled, but be clean; then she shall be free, and shall conceive seed."}, {"verse": 29, "start": 354.53, "end": 362.11, "ta": "ஒரு ஸ்திரீ தன் புருஷனோடேயன்றி அந்நிய புருஷனோடே சேர்ந்து தீட்டுப்பட்டதினால் உண்டான எரிச்சலுக்கும்,", "en": "This is the law of jealousies, when a wife goeth aside to another instead of her husband, and is defiled;"}, {"verse": 30, "start": 362.11, "end": 381.6, "ta": "புருஷன்மேல் எரிச்சலின் ஆவி வருகிறதினால், அவன் தன் மனைவியின்மேல் அடைந்த சமுசயத்துக்கும் அடுத்த பிரமாணம் இதுவே. அவன் கர்த்தருடைய சந்நிதியில் தன் மனைவியை நிறுத்துவானாக; ஆசாரியன் இந்தப் பிரமாணத்தின்படியெல்லாம் அவளுக்குச் செய்யக்கடவன்.", "en": "Or when the spirit of jealousy cometh upon him, and he be jealous over his wife, and shall set the woman before the LORD , and the priest shall execute upon her all this law."}, {"verse": 31, "start": 381.6, "end": 391.84, "ta": "புருஷனானவன் அக்கிரமத்திற்கு நீங்கலாயிருப்பான்; அப்படிப்பட்ட ஸ்திரீயோ, தன் அக்கிரமத்தைச் சுமப்பாள் என்று சொல் என்றார்.", "en": "Then shall the man be guiltless from iniquity, and this woman shall bear her iniquity."}]}, "6": {"chapter": 6, "duration": 342.46, "audio_url": "audio_ot/OT04_06.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 5.6, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.6, "end": 20.84, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: புருஷனாகிலும் ஸ்திரீயாகிலும் கர்த்தருக்கென்று விரதம் பண்ணிக்கொண்டவர்களாயிருக்கும்படி நசரேய விரதமாகிய ஒரு விசேஷித்த பொருத்தனையைப் பண்ணினால்,", "en": "Speak unto the children of Israel, and say unto them, When either man or woman shall separate themselves to vow a vow of a Nazarite, to separate themselves unto the LORD :"}, {"verse": 3, "start": 20.84, "end": 40.92, "ta": "அப்படிப்பட்டவன் திராட்சரசத்தையும் மதுபானத்தையும் விலக்கக்கடவன்; அவன் திராட்சரசத்தின் காடியையும் மற்ற மதுபானத்தின் காடியையும், திராட்சரசத்தினால் செய்த எவ்விதமான பானத்தையும் குடியாமலும், திராட்சப்பழங்களையாவது திராட்ச வற்றல்களையாவது புசியாமலும்,", "en": "He shall separate himself from wine and strong drink, and shall drink no vinegar of wine, or vinegar of strong drink, neither shall he drink any liquor of grapes, nor eat moist grapes, or dried."}, {"verse": 4, "start": 40.92, "end": 52.02, "ta": "தான் நசரேயனாயிருக்கும் நாளெல்லாம் திராட்சச்செடி விதைமுதல் தோல்வரையிலுள்ளவைகளினால் செய்யப்பட்ட யாதொன்றையும் புசியாமலும் இருக்கக்கடவன்.", "en": "All the days of his separation shall he eat nothing that is made of the vine tree, from the kernels even to the husk."}, {"verse": 5, "start": 52.02, "end": 67.65, "ta": "அவன் நசரேய விரதங்காக்கும் நாளெல்லாம் சவரகன் கத்தி அவன் தலையின்மேல் படலாகாது; அவன் கர்த்தருக்கென்று விரதங்காக்கும் காலம் நிறைவேறுமளவும் பரிசுத்தமாயிருந்து, தன் தலைமயிரை வளரவிடக்கடவன்.", "en": "All the days of the vow of his separation there shall no razor come upon his head: until the days be fulfilled, in the which he separateth himself unto the LORD , he shall be holy, and shall let the locks of the hair of his head grow."}, {"verse": 6, "start": 67.65, "end": 75.0, "ta": "அவன் கர்த்தருக்கென்று விரதங்காக்கும் நாளெல்லாம் யாதொரு பிரேதத்தண்டையில் போகக் கூடாது.", "en": "All the days that he separateth himself unto the LORD he shall come at no dead body."}, {"verse": 7, "start": 75.0, "end": 90.08, "ta": "அவன் தன் தேவனுக்கென்று செய்த நசரேய விரதம் அவன் தலைமேல் இருக்கிறபடியால், மரணமடைந்த தன் தகப்பனாலாகிலும் தாயினாலாகிலும் சகோதரனாலாகிலும் சகோதரியினாலாகிலும் தன்னைத் தீட்டுப்படுத்தலாகாது.", "en": "He shall not make himself unclean for his father, or for his mother, for his brother, or for his sister, when they die: because the consecration of his God is upon his head."}, {"verse": 8, "start": 90.08, "end": 96.26, "ta": "அவன் நசரேயனாயிருக்கும் நாளெல்லாம் கர்த்தருக்குப் பரிசுத்தமாயிருப்பான்.", "en": "All the days of his separation he is holy unto the LORD ."}, {"verse": 9, "start": 96.26, "end": 110.48, "ta": "அவனண்டையிலே ஒருவன் சடுதியில் மரணமடைந்ததினால், நசரேயவிரதமுள்ள அவனுடைய தலை தீட்டுப்பட்டதேயாகில், அவன் தன் சுத்திகரிப்பின் நாளாகிய ஏழாம் நாளில் தன் தலைமயிரைச் சிரைத்துக்கொண்டு,", "en": "And if any man die very suddenly by him, and he hath defiled the head of his consecration; then he shall shave his head in the day of his cleansing, on the seventh day shall he shave it."}, {"verse": 10, "start": 110.48, "end": 121.27, "ta": "எட்டாம் நாளில் இரண்டு காட்டுப்புறாக்களையாவது இரண்டு புறாக்குஞ்சுகளையாவது ஆசரிப்புக் கூடாரவாசலில் ஆசாரியனிடத்தில் கொண்டுவரக்கடவன்.", "en": "And on the eighth day he shall bring two turtles, or two young pigeons, to the priest, to the door of the tabernacle of the congregation:"}, {"verse": 11, "start": 121.27, "end": 137.44, "ta": "அப்பொழுது ஆசாரியன் ஒன்றைப் பாவநிவரணபலியாகவும், மற்றொன்றைச் சர்வாங்க தகனபலியாகவும் செலுத்தி, பிணத்தினால் அவனுக்கு உண்டான தீட்டை நிவிர்த்திசெய்து, அவன் தலையை அந்நாளில் பரிசுத்தப்படுத்துவானாக.", "en": "And the priest shall offer the one for a sin offering, and the other for a burnt offering, and make an atonement for him, for that he sinned by the dead, and shall hallow his head that same day."}, {"verse": 12, "start": 137.44, "end": 154.09, "ta": "அவன் திரும்பவும் தன் விரதநாட்களைக் கர்த்தருக்கென்று காத்து, ஒரு வருஷத்து ஆட்டுக்குட்டியைக் குற்றநிவாரணபலியாகக் கொண்டுவரக்கடவன்; அவனுடைய நசரேய விரதம் தீட்டுப்பட்டதினால் சென்ற நாட்கள் விருதாவாகும்.", "en": "And he shall consecrate unto the LORD the days of his separation, and shall bring a lamb of the first year for a trespass offering: but the days that were before shall be lost, because his separation was defiled."}, {"verse": 13, "start": 154.09, "end": 163.0, "ta": "நசரேயனுக்குரிய பிரமாணமாவது: அவன் விரதங்காக்கும் நாட்கள் நிறைவேறின அன்றே, அவன் ஆசரிப்புக் கூடாரவாசலிலே வந்து,", "en": "And this is the law of the Nazarite, when the days of his separation are fulfilled: he shall be brought unto the door of the tabernacle of the congregation:"}, {"verse": 14, "start": 163.0, "end": 176.99, "ta": "சர்வாங்க தகனபலியாக ஒரு வருஷத்து பழுதற்ற ஒரு ஆட்டுக்குட்டியையும் பாவநிவாரணபலியாக ஒரு வருஷத்து பழுதற்ற ஒரு பெண்ணாட்டுக்குட்டியையும், சமாதானபலியாக பழுதற்ற ஒரு ஆட்டுக்கடாவையும்,", "en": "And he shall offer his offering unto the LORD , one he lamb of the first year without blemish for a burnt offering, and one ewe lamb of the first year without blemish for a sin offering, and one ram without blemish for peace offerings,"}, {"verse": 15, "start": 176.99, "end": 195.83, "ta": "ஒரு கூடையில் எண்ணெயிலே பிசைந்த புளிப்பில்லாத மெல்லிய மாவினால் செய்த அதிரசங்களையும், எண்ணெய் தடவப்பட்ட புளிப்பில்லாத அடைகளையும், அவைகளுக்கு அடுத்த போஜனபலியையும், பானபலிகளையும் கர்த்தருக்குத் தன் காணிக்கையாகச் செலுத்தக்கடவன்.", "en": "And a basket of unleavened bread, cakes of fine flour mingled with oil, and wafers of unleavened bread anointed with oil, and their meat offering, and their drink offerings."}, {"verse": 16, "start": 195.83, "end": 205.67, "ta": "அவைகளை ஆசாரியன் கர்த்தருடைய சந்நிதியில் கொண்டுவந்து, அவனுடைய பாவநிவாரண பலியையும் அவனுடைய சர்வாங்க தகனபலியையும் செலுத்தி,", "en": "And the priest shall bring them before the LORD , and shall offer his sin offering, and his burnt offering:"}, {"verse": 17, "start": 205.67, "end": 218.41, "ta": "ஆட்டுக்கடாவைக் கூடையிலிருக்கும் புளிப்பில்லாத அப்பங்களோடுங்கூடக் கர்த்தருக்குச் சமாதானபலியாகச் செலுத்தி, அவனுடைய போஜனபலியையும் பானபலியையும் படைப்பானாக.", "en": "And he shall offer the ram for a sacrifice of peace offerings unto the LORD , with the basket of unleavened bread: the priest shall offer also his meat offering, and his drink offering."}, {"verse": 18, "start": 218.41, "end": 233.81, "ta": "அப்பொழுது நசரேயன் ஆசரிப்புக் கூடாரவாசலிலே, பொருத்தனை செய்யப்பட்ட தன் தலையைச் சிரைத்து, பொருத்தனை செய்யப்பட்ட தன் தலைமயிரை எடுத்து, சமாதானபலியின்கீழ் எரிகிற அக்கினியில் போடக்கடவன்.", "en": "And the Nazarite shall shave the head of his separation at the door of the tabernacle of the congregation, and shall take the hair of the head of his separation, and put it in the fire which is under the sacrifice of the peace offerings."}, {"verse": 19, "start": 233.81, "end": 254.68, "ta": "நசரேயன் பொருத்தனை செய்யப்பட்ட தன் தலைமயிரைச் சிரைத்துக்கொண்டபின்பு, ஆசாரியன் ஆட்டுக்கடாவினுடைய வேவிக்கப்பட்ட ஒரு முன்னந்தொடையையும், கூடையில் இருக்கிறவைகளிலே புளிப்பில்லாத ஒரு அதிரசத்தையும் புளிப்பில்லாத ஒரு அடையையும் எடுத்து, அவனுடைய உள்ளங்கைகளில் வைத்து,", "en": "And the priest shall take the sodden shoulder of the ram, and one unleavened cake out of the basket, and one unleavened wafer, and shall put them upon the hands of the Nazarite, after the hair of his separation is shaven:"}, {"verse": 20, "start": 254.68, "end": 273.12, "ta": "அவைகளைக் கர்த்தருடைய சந்நிதியில் அசைவாட்டக்கடவன்; அது அசைவாட்டப்பட்ட மார்க்கண்டத்தோடும், ஏறெடுத்துப் படைக்கப்பட்ட முன்னந்தொடையோடும், ஆசாரியனைச் சேரும்; அது பரிசுத்தமானது பின்பு நசரேயன் திராட்சரசம் குடிக்கலாம்.", "en": "And the priest shall wave them for a wave offering before the LORD : this is holy for the priest, with the wave breast and heave shoulder: and after that the Nazarite may drink wine."}, {"verse": 21, "start": 273.12, "end": 295.47, "ta": "பொருத்தனைபண்ணின நசரேயனுக்கும், அவன் தன் கைக்கு உதவுகிறதையல்லாமல், தன் நசரேய விரதத்தினிமித்தம் கர்த்தருக்குச் செலுத்தும் காணிக்கைக்கும் அடுத்த பிரமாணம் இதுவே. அவன் செய்த பொருத்தனையின்படியே தன் பொருத்தனையின் பிரமாணத்துக்கேற்க செய்து தீரவேண்டும் என்று சொல் என்றார்.", "en": "This is the law of the Nazarite who hath vowed, and of his offering unto the LORD for his separation, beside that that his hand shall get: according to the vow which he vowed, so he must do after the law of his separation."}, {"verse": 22, "start": 295.47, "end": 297.97, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 23, "start": 297.97, "end": 309.54, "ta": "நீ ஆரோனோடும் அவன் குமாரரோடும் சொல்லவேண்டியது என்னவென்றால்: நீங்கள் இஸ்ரவேல் புத்திரரை ஆசீர்வதிக்கும்போது, அவர்களைப் பார்த்துச் சொல்லவேண்டியதாவது:", "en": "Speak unto Aaron and unto his sons, saying, On this wise ye shall bless the children of Israel, saying unto them,"}, {"verse": 24, "start": 309.54, "end": 314.39, "ta": "கர்த்தர் உன்னை ஆசீர்வதித்து, உன்னைக் காக்கக்கடவர்.", "en": "The LORD bless thee, and keep thee:"}, {"verse": 25, "start": 314.39, "end": 321.89, "ta": "கர்த்தர் தம்முடைய முகத்தை உன்மேல் பிரகாசிக்கப்பண்ணி, உன்மேல் கிருபையாயிருக்கக்கடவர்.", "en": "The LORD make his face shine upon thee, and be gracious unto thee:"}, {"verse": 26, "start": 321.89, "end": 329.94, "ta": "கர்த்தர் தம்முடைய முகத்தை உன்மேல் பிரசன்னமாக்கி, உனக்குச் சமாதானம் கட்டளையிடக்கடவர் என்பதே.", "en": "The LORD lift up his countenance upon thee, and give thee peace."}, {"verse": 27, "start": 329.94, "end": 340.96, "ta": "இவ்விதமாய் அவர்கள் என் நாமத்தை இஸ்ரவேல் புத்திரர்மேல் கூறக்கடவர்கள்; அப்பொழுது நான் அவர்களை ஆசீர்வதிப்பேன் என்று சொல் என்றார்.", "en": "And they shall put my name upon the children of Israel; and I will bless them."}]}, "7": {"chapter": 7, "duration": 941.61, "audio_url": "audio_ot/OT04_07.mp3", "total_verses": 89, "verses": [{"verse": 1, "start": 3.8, "end": 17.18, "ta": "மோசே வாசஸ்தலத்தை ஸ்தாபனம்பண்ணி, அதையும் அதின் எல்லாப் பணிமுட்டுகளையும், பலிபீடத்தையும் அதின் எல்லாப் பணிமுட்டுகளையும் அபிஷேகம்பண்ணி, பரிசுத்தப்படுத்தி முடித்தநாளில்,", "en": "And it came to pass on the day that Moses had fully set up the tabernacle, and had anointed it, and sanctified it, and all the instruments thereof, both the altar and all the vessels thereof, and had anointed them, and sanctified them;"}, {"verse": 2, "start": 17.18, "end": 30.18, "ta": "தங்கள் பிதாக்களுடைய வம்சத்தலைவரும், எண்ணப்பட்டவர்களின் விசாரிப்புக்கு வைக்கப்பட்ட கோத்திரப் பிரபுக்களுமாகிய இஸ்ரவேலின் பிரபுக்கள் காணிக்கைகளைச் செலுத்தினார்கள்.", "en": "That the princes of Israel, heads of the house of their fathers, who were the princes of the tribes, and were over them that were numbered, offered:"}, {"verse": 3, "start": 30.18, "end": 48.16, "ta": "தங்கள் காணிக்கையாக, ஆறு கூண்டு வண்டில்களையும், பன்னிரண்டு மாடுகளையும் இரண்டிரண்டு பிரபுக்களுக்கு ஒவ்வொரு வண்டிலும், ஒவ்வொரு பிரபுக்கு ஒவ்வொரு மாடுமாக, கர்த்தருக்குச் செலுத்த வாசஸ்தலத்திற்கு முன்பாகக் கொண்டுவந்தார்கள்.", "en": "And they brought their offering before the LORD , six covered wagons, and twelve oxen; a wagon for two of the princes, and for each one an ox: and they brought them before the tabernacle."}, {"verse": 4, "start": 48.16, "end": 50.66, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 5, "start": 50.66, "end": 61.92, "ta": "நீ அவர்களிடத்தில் ஆசரிப்புக் கூடாரத்தின் ஊழியத்திற்காக அவைகளை வாங்கி, லேவியருக்கு அவரவர் வேலைக்குத்தக்கவைகளாகப் பங்கிட்டுக் கொடு என்றார்.", "en": "Take it of them, that they may be to do the service of the tabernacle of the congregation; and thou shalt give them unto the Levites, to every man according to his service."}, {"verse": 6, "start": 61.92, "end": 68.87, "ta": "அப்பொழுது மோசே அந்த வண்டில்களையும் மாடுகளையும் வாங்கி, லேவியருக்குக் கொடுத்தான்.", "en": "And Moses took the wagons and the oxen, and gave them unto the Levites."}, {"verse": 7, "start": 68.87, "end": 77.94, "ta": "இரண்டு வண்டில்களையும் நான்கு மாடுகளையும் கெர்சோன் புத்திரருக்கு, அவர்கள் வேலைக்குத்தக்க பங்காகக் கொடுத்தான்.", "en": "Two wagons and four oxen he gave unto the sons of Gershon, according to their service:"}, {"verse": 8, "start": 77.94, "end": 91.85, "ta": "நான்கு வண்டில்களையும் எட்டு மாடுகளையும் மெராரியின் புத்திரருக்கு, ஆசாரியனாகிய ஆரோனின் குமாரர் இத்தாமாருடைய கையின் கீழிருக்கிற அவர்களுடைய வேலைக்குத்தக்க பங்காகக் கொடுத்தான்.", "en": "And four wagons and eight oxen he gave unto the sons of Merari, according unto their service, under the hand of Ithamar the son of Aaron the priest."}, {"verse": 9, "start": 91.85, "end": 101.82, "ta": "கோகாத்தின் புத்திரருக்கோ ஒன்றும் கொடுக்கவில்லை; தோள்மேல் சுமப்பதே அவர்களுக்குரிய பரிசுத்த ஸ்தலத்தின் வேலையாயிருந்தது.", "en": "But unto the sons of Kohath he gave none: because the service of the sanctuary belonging unto them was that they should bear upon their shoulders."}, {"verse": 10, "start": 101.82, "end": 114.82, "ta": "பலிபீடம் அபிஷேகம்பண்ணப்பட்ட நாளிலே, பிரபுக்கள் அதின் பிரதிஷ்டைக்காகக் காணிக்கைகளைச் செலுத்தி, பலிபீடத்துக்கு முன்பாகத் தங்கள் காணிக்கைகளைக் கொண்டுவந்தார்கள்.", "en": "And the princes offered for dedicating of the altar in the day that it was anointed, even the princes offered their offering before the altar."}, {"verse": 11, "start": 114.82, "end": 126.16, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி: பலிபீடத்தின் பிரதிஷ்டைக்காக, ஒவ்வொரு பிரபுவும் தன்தன் நாளில் தன்தன் காணிக்கையைச் செலுத்தக்கடவன் என்றார்.", "en": "And the LORD said unto Moses, They shall offer their offering, each prince on his day, for the dedicating of the altar."}, {"verse": 12, "start": 126.16, "end": 134.7, "ta": "அப்படியே முதலாம் நாளில் தன் காணிக்கையைச் செலுத்தினவன் யூதா கோத்திரத்தானாகிய அம்மினதாபின் குமாரன் நகசோன்.", "en": "And he that offered his offering the first day was Nahshon the son of Amminadab, of the tribe of Judah:"}, {"verse": 13, "start": 134.7, "end": 154.5, "ta": "அவன் காணிக்கையாவது: போஜனபலியாக படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "And his offering was one silver charger, the weight thereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them were full of fine flour mingled with oil for a meat offering:"}, {"verse": 14, "start": 154.5, "end": 160.77, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One spoon of ten shekels of gold, full of incense:"}, {"verse": 15, "start": 160.77, "end": 167.88, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 16, "start": 167.88, "end": 171.13, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 17, "start": 171.13, "end": 185.64, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது அம்மினதாபின் குமாரனாகிய நகசோனின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Nahshon the son of Amminadab."}, {"verse": 18, "start": 185.64, "end": 192.89, "ta": "இரண்டாம் நாளில் இசக்காரின் பிரபுவாகிய சூவாரின் குமாரன் நெதனெயேல் காணிக்கை செலுத்தினான்.", "en": "On the second day Nethaneel the son of Zuar, prince of Issachar, did offer:"}, {"verse": 19, "start": 192.89, "end": 212.84, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "He offered for his offering one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 20, "start": 212.84, "end": 219.12, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One spoon of gold of ten shekels , full of incense:"}, {"verse": 21, "start": 219.12, "end": 225.92, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 22, "start": 225.92, "end": 229.17, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 23, "start": 229.17, "end": 243.6, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது சூவாரின் குமாரனாகிய நெதனெயேலின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Nethaneel the son of Zuar."}, {"verse": 24, "start": 243.6, "end": 251.84, "ta": "மூன்றாம் நாளில் ஏலோனின் குமாரனாகிய எலியாப் என்னும் செபுலோன் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the third day Eliab the son of Helon, prince of the children of Zebulun, did offer:"}, {"verse": 25, "start": 251.84, "end": 271.72, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல்நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 26, "start": 271.72, "end": 277.99, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 27, "start": 277.99, "end": 285.09, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 28, "start": 285.09, "end": 288.34, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 29, "start": 288.34, "end": 302.55, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது ஏலோனின் குமாரனாகிய எலியாபின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Eliab the son of Helon."}, {"verse": 30, "start": 302.55, "end": 311.09, "ta": "நான்காம் நாளில் சேதேயூரின் குமாரனாகிய எலிசூர் என்னும் ரூபன் புத்திரரின் பிரபு காணிக்கை, செலுத்தினான்.", "en": "On the fourth day Elizur the son of Shedeur, prince of the children of Reuben, did offer:"}, {"verse": 31, "start": 311.09, "end": 330.74, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும் பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger of the weight of an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 32, "start": 330.74, "end": 337.01, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 33, "start": 337.01, "end": 344.12, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 34, "start": 344.12, "end": 347.37, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 35, "start": 347.37, "end": 361.8, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது சேதேயூரின் குமாரனாகிய எலிசூரின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Elizur the son of Shedeur."}, {"verse": 36, "start": 361.8, "end": 370.57, "ta": "ஐந்தாம் நாளில் சூரிஷதாயின் குமாரனாகிய செலுூமியேல் என்னும் சிமியோன் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the fifth day Shelumiel the son of Zurishaddai, prince of the children of Simeon, did offer:"}, {"verse": 37, "start": 370.57, "end": 390.52, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 38, "start": 390.52, "end": 396.79, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 39, "start": 396.79, "end": 403.9, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 40, "start": 403.9, "end": 407.15, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 41, "start": 407.15, "end": 421.96, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது சூரிஷதாயின் குமாரனாகிய செலுூமியேலின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Shelumiel the son of Zurishaddai."}, {"verse": 42, "start": 421.96, "end": 430.05, "ta": "ஆறாம் நாளில் தேகுவேலின் குமாரனாகிய எலியாசாப் என்னும் காத் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the sixth day Eliasaph the son of Deuel, prince of the children of Gad, offered:"}, {"verse": 43, "start": 430.05, "end": 450.0, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger of the weight of an hundred and thirty shekels , a silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 44, "start": 450.0, "end": 456.27, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 45, "start": 456.27, "end": 463.38, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 46, "start": 463.38, "end": 466.63, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 47, "start": 466.63, "end": 480.61, "ta": "சமாதானபலியாக இரண்டு மாடுகளும் ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும் ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது தேகுவேலின் குமாரனாகிய எலியாசாபின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Eliasaph the son of Deuel."}, {"verse": 48, "start": 480.61, "end": 489.15, "ta": "ஏழாம் நாளில் அம்மியூதின் குமாரனாகிய எலிஷாமா என்னும் எப்பிராயீம் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the seventh day Elishama the son of Ammihud, prince of the children of Ephraim, offered:"}, {"verse": 49, "start": 489.15, "end": 509.1, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 50, "start": 509.1, "end": 515.37, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 51, "start": 515.37, "end": 522.48, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 52, "start": 522.48, "end": 525.8, "ta": "பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 53, "start": 525.8, "end": 540.46, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது அம்மியூதின் குமாரனாகிய எலிஷாமாவின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Elishama the son of Ammihud."}, {"verse": 54, "start": 540.46, "end": 548.78, "ta": "எட்டாம் நாளில் பெதாசூரின் குமாரனாகிய கமாலியேல் என்னும் மனாசே புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the eighth day offered Gamaliel the son of Pedahzur, prince of the children of Manasseh:"}, {"verse": 55, "start": 548.78, "end": 568.58, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெய் பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger of the weight of an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 56, "start": 568.58, "end": 574.85, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 57, "start": 574.85, "end": 581.96, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 58, "start": 581.96, "end": 585.21, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 59, "start": 585.21, "end": 599.79, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது பெதாசூரின் குமாரனாகிய கமாலியேலின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Gamaliel the son of Pedahzur."}, {"verse": 60, "start": 599.79, "end": 608.33, "ta": "ஒன்பதாம் நாளில் கீதெயோனின் குமாரனாகிய அபீதான் என்னும் பென்யமீன் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the ninth day Abidan the son of Gideoni, prince of the children of Benjamin, offered:"}, {"verse": 61, "start": 608.33, "end": 628.28, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 62, "start": 628.28, "end": 634.56, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 63, "start": 634.56, "end": 641.66, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 64, "start": 641.66, "end": 644.91, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 65, "start": 644.91, "end": 659.35, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது கீதெயோனின் குமாரனாகிய அபீதானின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Abidan the son of Gideoni."}, {"verse": 66, "start": 659.35, "end": 667.73, "ta": "பத்தாம் நாளில் அம்மிஷதாயின் குமாரனாகிய அகியேசேர் என்னும் தாண் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the tenth day Ahiezer the son of Ammishaddai, prince of the children of Dan, offered:"}, {"verse": 67, "start": 667.73, "end": 687.69, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 68, "start": 687.69, "end": 693.96, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 69, "start": 693.96, "end": 701.06, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 70, "start": 701.06, "end": 704.31, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 71, "start": 704.31, "end": 719.05, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது அம்மிஷதாயின் குமாரனாகிய அகியேசேரின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Ahiezer the son of Ammishaddai."}, {"verse": 72, "start": 719.05, "end": 727.36, "ta": "பதினோராம் நாளில் ஓகிரானின் குமாரனாகிய பாகியேல் என்னும் ஆசேர் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the eleventh day Pagiel the son of Ocran, prince of the children of Asher, offered:"}, {"verse": 73, "start": 727.36, "end": 747.32, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 74, "start": 747.32, "end": 753.59, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 75, "start": 753.59, "end": 760.69, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 76, "start": 760.69, "end": 763.94, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 77, "start": 763.94, "end": 778.38, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது ஓகிரானின் குமாரனாகிய பாகியேலின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Pagiel the son of Ocran."}, {"verse": 78, "start": 778.38, "end": 786.62, "ta": "பன்னிரண்டாம் நாளில் ஏனானின் குமாரனாகிய அகீரா என்னும் நப்தலி புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the twelfth day Ahira the son of Enan, prince of the children of Naphtali, offered:"}, {"verse": 79, "start": 786.62, "end": 806.57, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரρ வெӠύளிՠύகலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 80, "start": 806.57, "end": 812.84, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 81, "start": 812.84, "end": 819.64, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 82, "start": 819.64, "end": 822.89, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 83, "start": 822.89, "end": 837.1, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது ஏனானின் குமாரனாகிய அகீராவின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Ahira the son of Enan."}, {"verse": 84, "start": 837.1, "end": 851.16, "ta": "பலிபீடம் அபிஷேகம்பண்ணப்பட்டபோது, இஸ்ரவேல் பிரபுக்களால் செய்யப்பட்ட பிரதிஷ்டையாவது வெள்ளித்தாலங்கள் பன்னிரண்டு, வெள்ளிக்கலங்கள் பன்னிரண்டு, பொன் தூபகரண்டிகள் பன்னிரண்டு.", "en": "This was the dedication of the altar, in the day when it was anointed, by the princes of Israel: twelve chargers of silver, twelve silver bowls, twelve spoons of gold:"}, {"verse": 85, "start": 851.16, "end": 868.54, "ta": "ஒவ்வொரு வெள்ளித்தாலம் நூற்றுமுப்பது சேக்கல் நிறையும், ஒவ்வொரு கலம் எழுபது சேக்கல் நிறையுமாக, இந்தப் பாத்திரங்களின் வெள்ளியெல்லாம் பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்கின்படி இரண்டாயிரத்து நானூறு சேக்கல் நிறையாயிருந்தது.", "en": "Each charger of silver weighing an hundred and thirty shekels , each bowl seventy: all the silver vessels weighed two thousand and four hundred shekels , after the shekel of the sanctuary:"}, {"verse": 86, "start": 868.54, "end": 883.88, "ta": "தூபவர்க்கம் நிறைந்த பொன் தூபகரண்டிகள் பன்னிரண்டு, ஒவ்வொன்று பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்கின்படி பத்துச்சேக்கல் நிறையாக, தூபகரண்டிகளின் பொன்னெல்லாம் நூற்றிருபது சேக்கல் நிறையாயிருந்தது.", "en": "The golden spoons were twelve, full of incense, weighing ten shekels apiece, after the shekel of the sanctuary: all the gold of the spoons was an hundred and twenty shekels ."}, {"verse": 87, "start": 883.88, "end": 903.98, "ta": "சர்வாங்க தகனபலியாகச் செலுத்தப்பட்ட காளைகளெல்லாம் பன்னிரண்டு, ஆட்டுக்கடாக்கள் பன்னிரண்டு, ஒரு வயதான ஆட்டுக்குட்டிகள் பன்னிரண்டு, அவைகளுக்கடுத்த போஜனபலிகளும்கூடச் செலுத்தப்பட்டது; பாவநிவாரணபலியாகச் செலுத்தப்பட்ட வெள்ளாட்டுக்கடாக்கள் பன்னிரண்டு.", "en": "All the oxen for the burnt offering were twelve bullocks, the rams twelve, the lambs of the first year twelve, with their meat offering: and the kids of the goats for sin offering twelve."}, {"verse": 88, "start": 903.98, "end": 922.35, "ta": "சமாதான பலியாகச் செலுத்தப்பட்ட காளைகளெல்லாம் இருபத்துநான்கு; ஆட்டுக்கடாக்கள் அறுபது, வெள்ளாட்டுக்கடாக்கள் அறுபது, ஒரு வயதானஆட்டுக்குட்டிகள் அறுபது; பலிபீடம் அபிஷேகம்பண்ணப்பட்ட பின்பு செய்யப்பட்ட அதின் பிரதிஷ்டை இதுவே.", "en": "And all the oxen for the sacrifice of the peace offerings were twenty and four bullocks, the rams sixty, the he goats sixty, the lambs of the first year sixty. This was the dedication of the altar, after that it was anointed."}, {"verse": 89, "start": 922.35, "end": 940.11, "ta": "மோசே தேவனோடே பேசும்படி ஆசரிப்புக் கூடாரத்திற்குள் பிரவேசிக்கும்போது, தன்னோடே பேசுகிறவரின் சத்தம் சாட்சிப்பெட்டியின்மேலுள்ள கிருபாசனமான இரண்டு கேருபீன்களின் நடுவிலிருந்துண்டாகக் கேட்பான்; அங்கே இருந்து அவனோடே பேசுவார்.", "en": "And when Moses was gone into the tabernacle of the congregation to speak with him, then he heard the voice of one speaking unto him from off the mercy seat that was upon the ark of testimony, from between the two cherubims: and he spake unto him."}]}, "8": {"chapter": 8, "duration": 316.62, "audio_url": "audio_ot/OT04_08.mp3", "total_verses": 26, "verses": [{"verse": 1, "start": 3.8, "end": 5.58, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.58, "end": 17.01, "ta": "நீ ஆரோனோடே சொல்லவேண்டியது என்னவென்றால்: நீ விளக்குகளை ஏற்றும்போது ஏழு விளக்குகளும் விளக்குத்தண்டிற்கு நேரே எரியவேண்டும் என்று சொல் என்றார்.", "en": "Speak unto Aaron, and say unto him, When thou lightest the lamps, the seven lamps shall give light over against the candlestick."}, {"verse": 3, "start": 17.01, "end": 26.75, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபிரகாரம் ஆரோன் செய்து, விளக்குத்தண்டிற்கு நேரே ஒழுங்காக அதின் விளக்குகளை ஏற்றினான்.", "en": "And Aaron did so; he lighted the lamps thereof over against the candlestick, as the LORD commanded Moses."}, {"verse": 4, "start": 26.75, "end": 42.28, "ta": "இந்தக் குத்துவிளக்கு, அதின் பாதமுதல் பூக்கள்வரைக்கும் பொன்னினால் அடிப்புவேலையாய்ச் செய்யப்பட்டிருந்தது; கர்த்தர் மோசேக்குக் காண்பித்த மாதிரியின்படியே அவன் குத்துவிளக்கை உண்டாக்கினான்.", "en": "And this work of the candlestick was of beaten gold, unto the shaft thereof, unto the flowers thereof, was beaten work: according unto the pattern which the LORD had shewed Moses, so he made the candlestick."}, {"verse": 5, "start": 42.28, "end": 44.75, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 6, "start": 44.75, "end": 52.02, "ta": "நீ இஸ்ரவேல் சந்ததியாரினின்று லேவியரைப் பிரித்தெடுத்து, அவர்களைச் சுத்திகரிப்பாயாக.", "en": "Take the Levites from among the children of Israel, and cleanse them."}, {"verse": 7, "start": 52.02, "end": 69.56, "ta": "அவர்களைச் சுத்திரிக்கும்படி அவர்களுக்குச் செய்யவேண்டியதாவது: அவர்கள்மேல் சுத்திகரிக்கும் ஜலத்தைத் தெளிப்பாயாக; பின்பு அவர்கள் சர்வாங்க சவரம்பண்ணி தங்கள் வஸ்திரங்களைத் தோய்த்து, தங்களைச் சுத்திகரிக்கக்கடவர்கள்.", "en": "And thus shalt thou do unto them, to cleanse them: Sprinkle water of purifying upon them, and let them shave all their flesh, and let them wash their clothes, and so make themselves clean."}, {"verse": 8, "start": 69.56, "end": 81.92, "ta": "அப்பொழுது ஒரு காளையையும், அதற்கேற்ற எண்ணெயிலே பிசைந்த மெல்லிய மாவாகிய போஜனபலியையும் கொண்டுவரக்கடவர்கள்; பாவநிவாரணபலியாக வேறொரு காளையையும் நீ வாங்கி,", "en": "Then let them take a young bullock with his meat offering, even fine flour mingled with oil, and another young bullock shalt thou take for a sin offering."}, {"verse": 9, "start": 81.92, "end": 91.27, "ta": "லேவியரை ஆசரிப்புக் கூடாரத்துக்குமுன் வரச்செய்து, இஸ்ரவேல் புத்திரரின் சபையார் எல்லாரையும் கூடிவரப்பண்ணுவாயாக.", "en": "And thou shalt bring the Levites before the tabernacle of the congregation: and thou shalt gather the whole assembly of the children of Israel together:"}, {"verse": 10, "start": 91.27, "end": 100.93, "ta": "நீ லேவியரைக் கர்த்தருடைய சந்நிதியில் வரப்பண்ணினபோது, இஸ்ரவேல் புத்திரர் தங்கள் கைகளை லேவியர்மேல் வைக்கக்கடவர்கள்.", "en": "And thou shalt bring the Levites before the LORD : and the children of Israel shall put their hands upon the Levites:"}, {"verse": 11, "start": 100.93, "end": 114.53, "ta": "லேவியர் கர்த்தருக்குரிய பணிவிடை செய்யும்பொருட்டு, ஆரோன் அவர்களை இஸ்ரவேல் புத்திரரின் காணிக்கையாகக் கர்த்தருக்கு முன்பாக அசைவாட்டப்படும் காணிக்கையாய் நிறுத்தக்கடவன்.", "en": "And Aaron shall offer the Levites before the LORD for an offering of the children of Israel, that they may execute the service of the LORD ."}, {"verse": 12, "start": 114.53, "end": 132.84, "ta": "அதன்பின் லேவியர் தங்கள் கைகளைக் காளைகளுடைய தலையின்மேல் வைப்பார்களாக; பின்பு நீ லேவியருக்காகப் பாவநிவிர்த்தி செய்யும்பொருட்டு, கர்த்தருக்கு அவைகளில் ஒன்றைப் பாவநிவாரண பலியாகவும், மற்றொன்றைச் சர்வாங்க தகனபலியாகவும் செலுத்தி,", "en": "And the Levites shall lay their hands upon the heads of the bullocks: and thou shalt offer the one for a sin offering, and the other for a burnt offering, unto the LORD , to make an atonement for the Levites."}, {"verse": 13, "start": 132.84, "end": 141.88, "ta": "லேவியரை ஆரோனுக்கும் அவன் குமாரனுக்கும் முன்பாக நிறுத்தி, அவர்களைக் கர்த்தருக்கு அசைவாட்டப்படும் காணிக்கையாக்கி,", "en": "And thou shalt set the Levites before Aaron, and before his sons, and offer them for an offering unto the LORD ."}, {"verse": 14, "start": 141.88, "end": 151.08, "ta": "இப்படி நீ லேவியரை இஸ்ரவேல் புத்திரரிலிருந்து பிரித்தெடுக்கக்கடவாய்; லேவியர் என்னுடையவர்களாயிருப்பார்கள்.", "en": "Thus shalt thou separate the Levites from among the children of Israel: and the Levites shall be mine."}, {"verse": 15, "start": 151.08, "end": 164.37, "ta": "இப்படி அவர்களைச் சுத்திகரித்து, அவர்களை அசைவாட்டும் காணிக்கையாக்கக்கடவாய்; அதன்பின்பு லேவியர் ஆசரிப்புக் கூடாரத்தில் பணிவிடை செய்யப் பிரவேசிக்கக்கடவர்கள்.", "en": "And after that shall the Levites go in to do the service of the tabernacle of the congregation: and thou shalt cleanse them, and offer them for an offering."}, {"verse": 16, "start": 164.37, "end": 180.83, "ta": "இஸ்ரவேல் புத்திரரிலிருந்து அவர்கள் எனக்கு முற்றிலும் கொடுக்கப்பட்டிருக்கிறார்கள்; இஸ்ரவேல் புத்திரர் எல்லாரிலும் கர்ப்பந்திறந்து பிறக்கிற சகல முதற்பேறுக்கும் பதிலாக அவர்களை எனக்கு எடுத்துக்கொண்டேன்.", "en": "For they are wholly given unto me from among the children of Israel; instead of such as open every womb, even instead of the firstborn of all the children of Israel, have I taken them unto me."}, {"verse": 17, "start": 180.83, "end": 195.12, "ta": "இஸ்ரவேல் புத்திரரில் மனிதரிலும் மிருகஜீவன்களிலும் முதற்பேறானதெல்லாம் என்னுடையது; நான் எகிப்துதேசத்திலே முதற்பேறான யாவையும் சங்கரித்த நாளிலே அவைகளை எனக்கென்று பரிசுத்தப்படுத்தி,", "en": "For all the firstborn of the children of Israel are mine, both man and beast: on the day that I smote every firstborn in the land of Egypt I sanctified them for myself."}, {"verse": 18, "start": 195.12, "end": 202.0, "ta": "பின்பு லேவியரை இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறு சகலத்திற்கும் பதிலாக எடுத்துக்கொண்டு,", "en": "And I have taken the Levites for all the firstborn of the children of Israel."}, {"verse": 19, "start": 202.0, "end": 229.81, "ta": "லேவியர் இஸ்ரவேல் புத்திரருடைய பணிவிடையை ஆசரிப்புக் கூடாரத்தில் செய்யும்படிக்கும், இஸ்ரவேல் புத்திரருக்காகப் பாவநிவிர்த்தி செய்யும்படிக்கும், இஸ்ரவேல் புத்திரர் தாங்களே பரிசுத்தஸ்தலத்தில் சேருகிறதினால் இஸ்ரவேல் புத்திரரில் வாதையுண்டாகாதபடிக்கும், லேவியரை அவர்களிலிருந்து எடுத்து, ஆரோனுக்கும் அவன் குமாரருக்கும் தத்தமாகக் கொடுத்தேன் என்றார்.", "en": "And I have given the Levites as a gift to Aaron and to his sons from among the children of Israel, to do the service of the children of Israel in the tabernacle of the congregation, and to make an atonement for the children of Israel: that there be no plague among the children of Israel, when the children of Israel come nigh unto the sanctuary."}, {"verse": 20, "start": 229.81, "end": 242.18, "ta": "அப்பொழுது மோசேயும் ஆரோனும் இஸ்ரவேல் புத்திரரின் சபையார் யாவரும் கர்த்தர் லேவியரைக்குறித்து மோசேக்குக் கட்டளையிட்டபடியெல்லாம் லேவியருக்குச் செய்தார்கள்.", "en": "And Moses, and Aaron, and all the congregation of the children of Israel, did to the Levites according unto all that the LORD commanded Moses concerning the Levites, so did the children of Israel unto them."}, {"verse": 21, "start": 242.18, "end": 259.56, "ta": "லேவியர் சுத்திகரிக்கப்பட்டு, தங்கள் வஸ்திரங்களைத் தோய்த்தார்கள்; பின்பு ஆரோன் அவர்களைக் கர்த்தருக்கு முன்பாக அசைவாட்டும் காணிக்கையாக நிறுத்தி, அவர்களைச் சுத்திகரிக்க அவர்களுக்காகப் பாவநிவிர்த்தி செய்தான்.", "en": "And the Levites were purified, and they washed their clothes; and Aaron offered them as an offering before the LORD ; and Aaron made an atonement for them to cleanse them."}, {"verse": 22, "start": 259.56, "end": 277.34, "ta": "அதற்குப்பின்பு லேவியர் ஆரோனுக்கும் அவன் குமாரருக்கும் முன்பாக ஆசரிப்புக் கூடாரத்தில் தங்கள் பணிவிடையைச் செய்யும்படி பிரவேசித்தார்கள்; கர்த்தர் லேவியரைக்குறித்து மோசேக்குக் கட்டளையிட்டபடியே அவர்களுக்குச் செய்தார்கள்.", "en": "And after that went the Levites in to do their service in the tabernacle of the congregation before Aaron, and before his sons: as the LORD had commanded Moses concerning the Levites, so did they unto them."}, {"verse": 23, "start": 277.34, "end": 279.81, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 24, "start": 279.81, "end": 293.1, "ta": "லேவியருக்குரிய கட்டளை என்னவென்றால்: இருபத்தைந்து வயதுமுதல் அதற்கு மேற்பட்ட வயதுள்ள யாவரும் ஆசரிப்புக் கூடாரத்தின் பணிவிடையைச் செய்யும் சேனையிலே சேவிக்க வரவேண்டும்.", "en": "This is it that belongeth unto the Levites: from twenty and five years old and upward they shall go in to wait upon the service of the tabernacle of the congregation:"}, {"verse": 25, "start": 293.1, "end": 298.66, "ta": "ஐம்பது வயதுக்கு மேற்பட்டவர்கள் வேலைசெய்யாமல் திருப்பணி சேனையை விட்டு,", "en": "And from the age of fifty years they shall cease waiting upon the service thereof , and shall serve no more:"}, {"verse": 26, "start": 298.66, "end": 315.12, "ta": "ஆசரிப்புக் கூடாரத்தின் காவலைக் காக்கிறதற்குத் தங்கள் சகோதரரோடே ஊழியஞ்செய்வதேயன்றி, வேறொரு சேவகமும் செய்யவேண்டியதில்லை; இப்படி லேவியர் செய்யவேண்டிய வேலைகளைக்குறித்துத் திட்டம்பண்ணக்கடவாய் என்றார்.", "en": "But shall minister with their brethren in the tabernacle of the congregation, to keep the charge, and shall do no service. Thus shalt thou do unto the Levites touching their charge."}]}, "9": {"chapter": 9, "duration": 285.05, "audio_url": "audio_ot/OT04_09.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 12.48, "ta": "அவர்கள் எகிப்துதேசத்திலிருந்து புறப்பட்ட இரண்டாம் வருஷம் முதலாம் மாதத்தில் கர்த்தர் சீனாய் வனாந்தரத்தில் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the wilderness of Sinai, in the first month of the second year after they were come out of the land of Egypt, saying,"}, {"verse": 2, "start": 12.48, "end": 17.73, "ta": "குறித்த காலத்தில் இஸ்ரவேல் புத்திரர் பஸ்காவை ஆசரிக்கக்கடவர்கள்.", "en": "Let the children of Israel also keep the passover at his appointed season."}, {"verse": 3, "start": 17.73, "end": 31.88, "ta": "இந்த மாதம் பதினாலாந்தேதி அந்திநேரமான வேளையாகிய குறித்த காலத்தில் அதை ஆசரிக்கக்கடவீர்கள்; அதற்குரிய எல்லாக் கட்டளையின்படியேயும் முறைமைகளின்படியேயும் அதை ஆசரிக்கக்கடவீர்கள் என்றார்.", "en": "In the fourteenth day of this month, at even, ye shall keep it in his appointed season: according to all the rites of it, and according to all the ceremonies thereof, shall ye keep it."}, {"verse": 4, "start": 31.88, "end": 38.08, "ta": "அப்படியே பஸ்காவை ஆசரிக்கும்படி மோசே இஸ்ரவேல் புத்திரருக்குக் கட்டளையிட்டான்.", "en": "And Moses spake unto the children of Israel, that they should keep the passover."}, {"verse": 5, "start": 38.08, "end": 52.44, "ta": "அதினால் முதலாம் மாதம் பதினான்காம் தேதி அந்திநேரமான வேளையில், சீனாய் வனாந்தரத்தில் பஸ்காவை ஆசரித்தார்கள்; கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியெல்லாம் இஸ்ரவேல் புத்திரர் செய்தார்கள்.", "en": "And they kept the passover on the fourteenth day of the first month at even in the wilderness of Sinai: according to all that the LORD commanded Moses, so did the children of Israel."}, {"verse": 6, "start": 52.44, "end": 64.11, "ta": "அந்நாளில் சிலர் மனித பிரேதத்தினால் தீட்டுப்பட்டபடியினால் பஸ்காவை ஆசரிக்கத்தகாதவர்களாயிருந்தார்கள்; அவர்கள் அந்நாளிலே மோசேக்கும் ஆரோனுக்கும் முன்பாக வந்து:", "en": "And there were certain men, who were defiled by the dead body of a man, that they could not keep the passover on that day: and they came before Moses and before Aaron on that day:"}, {"verse": 7, "start": 64.11, "end": 78.92, "ta": "நாங்கள் மனித பிரேதத்தினால் தீட்டுப்பட்டவர்கள்; குறித்த காலத்தில் இஸ்ரவேல் புத்திரரோடேகூடக் கர்த்தருக்குக் காணிக்கையைச் செலுΤ்தாĠΪடߠΕ்கl நாங்களύ விலக்ՠΪ்ʠΟ்ߠοருக்கவேண்டியது என்ன என்றார்கள்.", "en": "And those men said unto him, We are defiled by the dead body of a man: wherefore are we kept back, that we may not offer an offering of the LORD in his appointed season among the children of Israel?"}, {"verse": 8, "start": 78.92, "end": 87.45, "ta": "மோசே அவர்களை நோக்கி: பொறுங்கள்; கர்த்தர் உங்களைக்குறித்துக் கட்டளையிடுவது என்ன என்று கேட்பேன் என்றான்.", "en": "And Moses said unto them, Stand still, and I will hear what the LORD will command concerning you."}, {"verse": 9, "start": 87.45, "end": 89.13, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 10, "start": 89.13, "end": 105.32, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: உங்களிலாகிலும் உங்கள் சந்ததியாரிலாகிலும் ஒருவன் பிரேதத்தினால் தீட்டுப்பட்டாலும், பிரயாணமாய்த் தூரம்போயிருந்தாலும், கர்த்தருக்குப் பஸ்காவை ஆசரிக்கவேண்டும்.", "en": "Speak unto the children of Israel, saying, If any man of you or of your posterity shall be unclean by reason of a dead body, or be in a journey afar off, yet he shall keep the passover unto the LORD ."}, {"verse": 11, "start": 105.32, "end": 115.6, "ta": "அவர்கள் அதை இரண்டாம் மாதம் பதினாலாந்தேதி அந்திநேரமான வேளையில் ஆசரித்து, அதைப் புளிப்பில்லாத அப்பங்களோடும் கசப்பான கீரைகளோடும் புசித்து,", "en": "The fourteenth day of the second month at even they shall keep it, and eat it with unleavened bread and bitter herbs ."}, {"verse": 12, "start": 115.6, "end": 127.63, "ta": "விடியற்காலம்மட்டும் அதில் ஒன்றும் மீதியாக வைக்காமலும், அதில் ஒரு எலும்பையும் முறிக்காமலும், பஸ்காவினுடைய சகல முறைமைகளின்படியும் அதை ஆசரிக்கக்கடவர்கள்.", "en": "They shall leave none of it unto the morning, nor break any bone of it: according to all the ordinances of the passover they shall keep it."}, {"verse": 13, "start": 127.63, "end": 145.94, "ta": "ஒருவன் சுத்தமுள்ளவனுமாய்ப் பிரயாணம் போகாதவனுமாயிருந்தும், பஸ்காவை ஆசரிக்காதேபோனால், அந்த ஆத்துமா குறித்த காலத்தில் கர்த்தரின் பலியைச் செலுத்தாதபடியினால் தன் ஜனத்தாரில் இராமல் அறுப்புண்டுபோவான்; அந்த மனிதன் தன் பாவத்தைச் சுமப்பான்.", "en": "But the man that is clean, and is not in a journey, and forbeareth to keep the passover, even the same soul shall be cut off from among his people: because he brought not the offering of the LORD in his appointed season, that man shall bear his sin."}, {"verse": 14, "start": 145.94, "end": 163.8, "ta": "ஒரு பரதேசி உங்களிடத்திலே தங்கி, கர்த்தருக்குப் பஸ்காவை ஆசரிக்கவேண்டுமானால், அவன் அதைப் பஸ்காவின் கட்டளைப்படியும் அதின் முறைமையின்படியும் ஆசரிக்கக்கடவன்; பரதேசிக்கும் சுதேசிக்கும் ஒரே கட்டளை இருக்கவேண்டும் என்று சொல் என்றார்.", "en": "And if a stranger shall sojourn among you, and will keep the passover unto the LORD ; according to the ordinance of the passover, and according to the manner thereof, so shall he do: ye shall have one ordinance, both for the stranger, and for him that was born in the land."}, {"verse": 15, "start": 163.8, "end": 179.85, "ta": "வாசஸ்தலம் ஸ்தாபனஞ்செய்யப்பட்ட நாளிலே, மேகமானது சாட்சியின் கூடாரமாகிய வாசஸ்தலத்தை மூடிற்று; சாயங்காலமானபோது, வாசஸ்தலத்தின்மேல் அக்கினிமயமான ஒரு தோற்றமுண்டாயிற்று; அது விடியற்காலமட்டும் இருந்தது.", "en": "And on the day that the tabernacle was reared up the cloud covered the tabernacle, namely , the tent of the testimony: and at even there was upon the tabernacle as it were the appearance of fire, until the morning."}, {"verse": 16, "start": 179.85, "end": 187.94, "ta": "இப்படி நித்தமும் இருந்தது; பகலில் மேகமும், இரவில் அக்கினித்தோற்றமும் அதை மூடிக்கொண்டிருந்தது.", "en": "So it was alway: the cloud covered it by day , and the appearance of fire by night."}, {"verse": 17, "start": 187.94, "end": 199.46, "ta": "மேகம் கூடாரத்திலிருந்து மேலே எழும்பும்போது இஸ்ரவேல் புத்திரர் பிரயாணம்பண்ணுவார்கள்; மேகம் தங்குமிடத்தில் இஸ்ரவேல் புத்திரர் பாளயமிறங்குவார்கள்.", "en": "And when the cloud was taken up from the tabernacle, then after that the children of Israel journeyed: and in the place where the cloud abode, there the children of Israel pitched their tents."}, {"verse": 18, "start": 199.46, "end": 215.8, "ta": "கர்த்தருடைய கட்டளையின்படியே இஸ்ரவேல் புத்திரர் பிரயாணப்படுவர்கள்; கர்த்தருடைய கட்டளையின்படியே பாளயமிறங்குவார்கள்; மேகம் வாசஸ்தலத்தின்மேல் தங்கியிருக்கும் நாளெல்லாம் அவர்கள் பாளயத்தில் தங்கியிருப்பார்கள்.", "en": "At the commandment of the LORD the children of Israel journeyed, and at the commandment of the LORD they pitched: as long as the cloud abode upon the tabernacle they rested in their tents."}, {"verse": 19, "start": 215.8, "end": 226.37, "ta": "மேகம் நெடுநாள் வாசஸ்தலத்தின்மேல் தங்கியிருக்கும்போது, இஸ்ரவேல் புத்திரர் பிரயாணப்படாமல் கர்த்தரின் காவலைக் காத்துக்கொண்டிருப்பார்கள்.", "en": "And when the cloud tarried long upon the tabernacle many days, then the children of Israel kept the charge of the LORD , and journeyed not."}, {"verse": 20, "start": 226.37, "end": 239.06, "ta": "மேகம் சிலநாள் மாத்திரம் வாசஸ்தலத்தின்மேல் தங்கியிருக்கும்போது, கர்த்தருடைய கட்டளையின்படியே பாளயமிறங்கியிருந்து, கர்த்தருடைய கட்டளையின்படியே பிரயாணப்படுவார்கள்.", "en": "And so it was, when the cloud was a few days upon the tabernacle; according to the commandment of the LORD they abode in their tents, and according to the commandment of the LORD they journeyed."}, {"verse": 21, "start": 239.06, "end": 253.5, "ta": "மேகம் சாயங்காலந்தொடங்கி விடியற்காலமட்டும் இருந்து, விடியற்காலத்தில் உயர எழும்பும்போது, உடனே பிரயாணப்படுவார்கள்; பகலிலாகிலும் இரவிலாகிலும் மேகம் எழும்பும்போது பிரயாணப்படுவார்கள்.", "en": "And so it was, when the cloud abode from even unto the morning, and that the cloud was taken up in the morning, then they journeyed: whether it was by day or by night that the cloud was taken up, they journeyed."}, {"verse": 22, "start": 253.5, "end": 268.82, "ta": "மேகமானது இரண்டுநாளாவது ஒரு மாதமாவது ஒரு வருஷமாவது வாசஸ்தலத்தின்மேல் தங்கியிருக்கும்போது, இஸ்ரவேல் புத்திரர் பிரயாணம்பண்ணாமல் பாளயமிறங்கியிருப்பார்கள்; அது உயர எழும்பும்போதோ பிரயாணப்படுவார்கள்.", "en": "Or whether it were two days, or a month, or a year, that the cloud tarried upon the tabernacle, remaining thereon, the children of Israel abode in their tents, and journeyed not: but when it was taken up, they journeyed."}, {"verse": 23, "start": 268.82, "end": 283.55, "ta": "கர்த்தருடைய கட்டளையின்படியே பாளயமிறங்குவார்கள்; கர்த்தருடைய கட்டளையின்படியே பிரயாணம்பண்ணுவார்கள்; கர்த்தர் மோசேயைக்கொண்டு கட்டளையிடுகிறபடியே கர்த்தருடைய காவலைக் காத்துக்கொள்வார்கள்.", "en": "At the commandment of the LORD they rested in the tents, and at the commandment of the LORD they journeyed: they kept the charge of the LORD , at the commandment of the LORD by the hand of Moses."}]}, "10": {"chapter": 10, "duration": 392.56, "audio_url": "audio_ot/OT04_10.mp3", "total_verses": 36, "verses": [{"verse": 1, "start": 3.8, "end": 5.56, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.56, "end": 19.21, "ta": "சபையைக் கூடிவரவழைப்பதற்கும் பாளயங்களைப் பிரயாணப்படுத்துவதற்கும் உபயோகமாக இரண்டு வெள்ளிப்பூரிகைகளைச் செய்துகொள்வாயாக; அவைகள் ஒரே வெள்ளித்தகட்டால் செய்யப்படவேண்டும்.", "en": "Make thee two trumpets of silver; of a whole piece shalt thou make them: that thou mayest use them for the calling of the assembly, and for the journeying of the camps."}, {"verse": 3, "start": 19.21, "end": 26.73, "ta": "அவைகளை ஊதும்போது, சபையாரெல்லாரும் ஆசரிப்புக் கூடாரவாசலில் உன்னிடத்தில் கூடிவரவேண்டும்.", "en": "And when they shall blow with them, all the assembly shall assemble themselves to thee at the door of the tabernacle of the congregation."}, {"verse": 4, "start": 26.73, "end": 35.24, "ta": "ஒன்றைமாத்திரம் ஊதினால் இஸ்ரவேலில் ஆயிரவர்களுக்குத் தலைவராகிய பிரபுக்கள் உன்னிடத்தில் கூடிவரக்கடவர்கள்.", "en": "And if they blow but with one trumpet , then the princes, which are heads of the thousands of Israel, shall gather themselves unto thee."}, {"verse": 5, "start": 35.24, "end": 43.75, "ta": "நீங்கள் அவைகளைப் பெருந்தொனியாய் முழக்கும்போது, கிழக்கே இறங்கியிருக்கிற பாளயங்கள் பிரயாணப்படக்கடவது.", "en": "When ye blow an alarm, then the camps that lie on the east parts shall go forward."}, {"verse": 6, "start": 43.75, "end": 58.48, "ta": "அவைகளை நீங்கள் இரண்டாந்தரம் பெருந்தொனியாய் முழக்கும்போது, தெற்கே இறங்கியிருக்கிற பாளயங்கள் பிரயாணப்படக்கடவது; அவர்களைப் பிரயாணப்படுத்துவதற்குப் பெருந்தொனியாய் முழக்கவேண்டும்.", "en": "When ye blow an alarm the second time, then the camps that lie on the south side shall take their journey: they shall blow an alarm for their journeys."}, {"verse": 7, "start": 58.48, "end": 65.15, "ta": "சபையைக் கூட்டுகிறதற்கு நீங்கள் ஊதவேண்டியதேயன்றி பெருந்தொனியாய் முழக்கவேண்டாம்.", "en": "But when the congregation is to be gathered together, ye shall blow, but ye shall not sound an alarm."}, {"verse": 8, "start": 65.15, "end": 75.42, "ta": "ஆரோனின் குமாரராகிய ஆசாரியர் பூரிகைகளை ஊதக்கடவர்கள்; உங்கள் தலைமுறைதோறும் இது உங்களுக்கு நித்திய கட்டளையாயிருக்கக்கடவது.", "en": "And the sons of Aaron, the priests, shall blow with the trumpets; and they shall be to you for an ordinance for ever throughout your generations."}, {"verse": 9, "start": 75.42, "end": 97.43, "ta": "உங்கள் தேசத்தில் உங்களைத் துன்பப்படுத்துகிற சத்துருவுக்கு விரோதமாக யுத்தத்துக்குப் போகும்போது, பூரிகைகளைப் பெருந்தொனியாய் முழக்கக்கடவீர்கள்; அப்பொழுது உங்கள் தேவனாகிய கர்த்தருடைய சமுகத்திலே நீங்கள் நினைவுகூரப்பட்டு, உங்கள் பகைஞருக்கு நீங்கலாகி இரட்சிக்கப்படுவீர்கள்.", "en": "And if ye go to war in your land against the enemy that oppresseth you, then ye shall blow an alarm with the trumpets; and ye shall be remembered before the LORD your God, and ye shall be saved from your enemies."}, {"verse": 10, "start": 97.43, "end": 120.74, "ta": "உங்கள் மகிழ்ச்சியின் நாளிலும், உங்கள் பண்டிகைகளிலும், மாதப்பிறப்புகளிலும், உங்கள் சர்வாங்க தகனபலிகளும் சமாதானபலிகளும் செலுத்தப்படும்போது பூரிகைகளை ஊதவேண்டும்; அப்பொழுது அவைகள் உங்கள் தேவனுடைய சமுகத்தில் உங்களுக்கு ஞாபகக்குறியாயிக்கும்; நான் உங்கள் தேவனாகிய கர்த்தர் என்றார்.", "en": "Also in the day of your gladness, and in your solemn days, and in the beginnings of your months, ye shall blow with the trumpets over your burnt offerings, and over the sacrifices of your peace offerings; that they may be to you for a memorial before your God: I am the LORD your God."}, {"verse": 11, "start": 120.74, "end": 130.02, "ta": "இரண்டாம் வருஷம் இரண்டாம் மாதம் இருபதாம் தேதியில் மேகம் சாட்சியினுடைய வாசஸ்தலத்தின் மீதிலிருந்து உயர எழும்பிற்று.", "en": "And it came to pass on the twentieth day of the second month, in the second year, that the cloud was taken up from off the tabernacle of the testimony."}, {"verse": 12, "start": 130.02, "end": 141.68, "ta": "அப்பொழுது இஸ்ரவேல் புத்திரர் சீனாய் வனாந்தரத்திலிருந்து தங்கள் பிரயாண வரிசைகளாய்ப் புறப்பட்டார்கள்; மேகம் பாரான் வனாந்தரத்தில் தங்கிற்று.", "en": "And the children of Israel took their journeys out of the wilderness of Sinai; and the cloud rested in the wilderness of Paran."}, {"verse": 13, "start": 141.68, "end": 148.12, "ta": "இப்படியே கர்த்தர் மோசேயைக்கொண்டு கட்டளையிட்டபடி முதல் பிரயாணம்பண்ணினார்கள்.", "en": "And they first took their journey according to the commandment of the LORD by the hand of Moses."}, {"verse": 14, "start": 148.12, "end": 159.55, "ta": "யூதா சந்ததியாருடைய பாளயத்தின் கொடி அவர்கள் சேனைகளோடே முதல் புறப்பட்டது; அவனுடைய சேனைக்கு அம்மினதாபின் குமாரன் நகசோன் தலைவனாயிருந்தான்.", "en": "In the first place went the standard of the camp of the children of Judah according to their armies: and over his host was Nahshon the son of Amminadab."}, {"verse": 15, "start": 159.55, "end": 167.29, "ta": "இசக்கார் சந்ததியாருடைய கோத்திரத்தின் சேனைக்குச் சூவாரின் குமாரன் நெதனெயேல் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Issachar was Nethaneel the son of Zuar."}, {"verse": 16, "start": 167.29, "end": 174.65, "ta": "செபுலோன் சந்ததியாருடைய கோத்திரத்தின் சேனைக்கு ஏலோனின் குமாரன் எலியாப் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Zebulun was Eliab the son of Helon."}, {"verse": 17, "start": 174.65, "end": 184.78, "ta": "அப்பொழுது வாசஸ்தலம் இறக்கிவைக்கப்பட்டது; அதைக் கெர்சோன் புத்திரரும் மெராரி புத்திரரும் சுமந்துகொண்டு புறப்பட்டார்கள்.", "en": "And the tabernacle was taken down; and the sons of Gershon and the sons of Merari set forward, bearing the tabernacle."}, {"verse": 18, "start": 184.78, "end": 196.89, "ta": "அதற்குபின்பு ரூபன் சந்ததியாருடைய பாளயத்தின் கொடி அவர்கள் சேனைகளோடே புறப்பட்டது; அவனுடைய சேனைக்குச் சேதேயூரின் குமாரன் எலிசூர் தலைவனாயிருந்தான்.", "en": "And the standard of the camp of Reuben set forward according to their armies: and over his host was Elizur the son of Shedeur."}, {"verse": 19, "start": 196.89, "end": 205.02, "ta": "சிமியோன் சந்ததியாருடைய கோத்திரத்தின் சேனைக்குச் சூரிஷதாயின் குமாரன் செலுூமியேல் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Simeon was Shelumiel the son of Zurishaddai."}, {"verse": 20, "start": 205.02, "end": 212.61, "ta": "காத் சந்ததியாருடைய கோத்திரத்தின் சேனைக்குத் தேகுவேலின் குமாரன் எலியாசாப் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Gad was Eliasaph the son of Deuel."}, {"verse": 21, "start": 212.61, "end": 223.66, "ta": "கோகாத்தியர் பரிசுத்தமானவைகளைச் சுமந்துகொண்டு புறப்பட்டார்கள்; இவர்கள் வந்து சேருமுன் மற்றவர்கள் வாசஸ்தலத்தை ஸ்தாபனம்பண்ணுவார்கள்.", "en": "And the Kohathites set forward, bearing the sanctuary: and the other did set up the tabernacle against they came."}, {"verse": 22, "start": 223.66, "end": 236.62, "ta": "அதற்குப்பின்பு, எப்பிராயீம் சந்ததியாருடைய பாளயத்தின் கொடி அவர்கள் சேனைகளோடே புறப்பட்டது; அவனுடைய சேனைக்கு அம்மியூதின் குமாரன் எலிஷாமா தலைவனாயிருந்தான்.", "en": "And the standard of the camp of the children of Ephraim set forward according to their armies: and over his host was Elishama the son of Ammihud."}, {"verse": 23, "start": 236.62, "end": 244.28, "ta": "மனாசே சந்ததியாருடைய கோத்திரத்தின் சேனைக்குப் பெதாசூரின் குமாரன் கமாலியேல் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Manasseh was Gamaliel the son of Pedahzur."}, {"verse": 24, "start": 244.28, "end": 252.11, "ta": "பென்யமீன் சந்ததியாருடைய கோத்திரத்தின் சேனைக்குக் கீதெயோனின் குமாரன் அபீதான் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Benjamin was Abidan the son of Gideoni."}, {"verse": 25, "start": 252.11, "end": 266.91, "ta": "அதற்குப்பின்பு, தாண் சந்ததியாருடைய பாளயத்தின் கொடி சகல பாளயங்களுக்கும் பின்னாக அவர்கள் சேனைகளோடே புறப்பட்டது; அவனுடைய சேனைக்கு அம்மிஷதாயின் குமாரன் அகியேசேர் தலைவனாயிருந்தான்.", "en": "And the standard of the camp of the children of Dan set forward, which was the rereward of all the camps throughout their hosts: and over his host was Ahiezer the son of Ammishaddai."}, {"verse": 26, "start": 266.91, "end": 274.27, "ta": "ஆசேர் சந்ததியாருடைய கோத்திரத்தின் சேனைக்கு ஓகிரானின் குமாரன் பாகியேல் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Asher was Pagiel the son of Ocran."}, {"verse": 27, "start": 274.27, "end": 281.32, "ta": "நப்தலி சந்ததியாருடைய கோத்திரத்தின் சேனைக்கு ஏனானின் குமாரன் அகீரா தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Naphtali was Ahira the son of Enan."}, {"verse": 28, "start": 281.32, "end": 289.68, "ta": "இஸ்ரவேல் புத்திரர் புறப்பட்டபோது, இவ்விதமாய்த் தங்கள் தங்கள் சேனைகளின்படியே பிரயாணம்பண்ணினார்கள்.", "en": "Thus were the journeyings of the children of Israel according to their armies, when they set forward."}, {"verse": 29, "start": 289.68, "end": 312.61, "ta": "அப்பொழுது மோசே தன் மாமனாகிய ரெகுவேல் என்னும் மீதியானனுடைய குமாரனான ஓபாவை நோக்கி: உங்களுக்குத் தருவேன் என்று கர்த்தர் சொன்ன ஸ்தலத்துக்கு நாங்கள் பிரயாணம்போகிறோம்; நீயும் எங்களோடேகூட வா, உனக்கு நன்மைசெய்வோம்; கர்த்தர் இஸ்ரவேலுக்கு நல்ல வாக்குத்தத்தம் பண்ணியிருக்கிறார் என்றான்.", "en": "And Moses said unto Hobab, the son of Raguel the Midianite, Moses’ father in law, We are journeying unto the place of which the LORD said, I will give it you: come thou with us, and we will do thee good: for the LORD hath spoken good concerning Israel."}, {"verse": 30, "start": 312.61, "end": 320.89, "ta": "அதற்கு அவன்: நான் வரக் கூடாது; என் தேசத்துக்கும் என் இனத்தாரிடத்துக்கும் போகவேண்டும் என்றான்.", "en": "And he said unto him, I will not go; but I will depart to mine own land, and to my kindred."}, {"verse": 31, "start": 320.89, "end": 334.08, "ta": "அப்பொழுது மோசே: நீ எங்களைவிட்டுப் போகவேண்டாம்; வனாந்தரத்திலே நாங்கள் பாளயமிறங்கும் இடங்களை நீ அறிந்திருக்கிறபடியினால், எங்களுக்குக் கண்களைப்போல இருப்பாய்.", "en": "And he said, Leave us not, I pray thee; forasmuch as thou knowest how we are to encamp in the wilderness, and thou mayest be to us instead of eyes."}, {"verse": 32, "start": 334.08, "end": 342.98, "ta": "நீ எங்களோடேகூட வந்தால், கர்த்தர் எங்களுக்குச் செய்தருளும் நன்மையின்படியே உனக்கும் நன்மைசெய்வோம் என்றான்.", "en": "And it shall be, if thou go with us, yea, it shall be, that what goodness the LORD shall do unto us, the same will we do unto thee."}, {"verse": 33, "start": 342.98, "end": 359.93, "ta": "அவர்கள் கர்த்தருடைய பர்வதத்தைவிட்டு, மூன்றுநாள் பிரயாணம்போனார்கள்; மூன்றுநாள் பிரயாணத்திலும் கர்த்தருடைய உடன்படிக்கைப்பெட்டி அவர்களுக்கு இளைப்பாறும் ஸ்தலத்தைத் தேடிக் காட்டும்படிக்கு அவர்கள்முன் சென்றது.", "en": "And they departed from the mount of the LORD three days’ journey: and the ark of the covenant of the LORD went before them in the three days’ journey, to search out a resting place for them."}, {"verse": 34, "start": 359.93, "end": 368.21, "ta": "அவர்கள் பாளயத்திலிருந்து பிரயாணம்போகிறபோது, கர்த்தருடைய மேகம் பகலில் அவர்கள்மேல் தங்கியிருந்தது.", "en": "And the cloud of the LORD was upon them by day, when they went out of the camp."}, {"verse": 35, "start": 368.21, "end": 382.85, "ta": "பெட்டியானது புறப்படும்போது, மோசே: கர்த்தாவே, எழுந்தருளும், உம்முடைய சத்துருக்கள் சிதறடிக்கப்படுவார்களாக; உம்மைப் பகைக்கிறவர்கள் உமக்கு முன்பாக ஓடிப்போவார்களாக என்பான்.", "en": "And it came to pass, when the ark set forward, that Moses said, Rise up, LORD , and let thine enemies be scattered; and let them that hate thee flee before thee."}, {"verse": 36, "start": 382.85, "end": 391.06, "ta": "அது தங்கும்போது: கர்த்தாவே, அநேக ஆயிரவர்களாகிய இஸ்ரவேலரிடத்தில் திரும்புவீராக என்று சொல்லுவான்.", "en": "And when it rested, he said, Return, O LORD , unto the many thousands of Israel."}]}, "11": {"chapter": 11, "duration": 463.1, "audio_url": "audio_ot/OT04_11.mp3", "total_verses": 35, "verses": [{"verse": 1, "start": 3.8, "end": 23.41, "ta": "பின்பு, ஜனங்கள் முறையிட்டுக்கொண்டிருந்தார்கள்; அது கர்த்தருடைய செவிகளில் பொல்லாப்பாயிருந்தது; கர்த்தர் அதைக் கேட்டபோது, அவருடைய கோபம் மூண்டது; கர்த்தருடைய அக்கினி அவர்களுக்குள்ளே பற்றியெரிந்து, பாளயத்தின் கடைசியிலிருந்த சிலரைப் பட்சித்தது.", "en": "And when the people complained, it displeased the LORD : and the LORD heard it; and his anger was kindled; and the fire of the LORD burnt among them, and consumed them that were in the uttermost parts of the camp."}, {"verse": 2, "start": 23.41, "end": 33.61, "ta": "அப்பொழுது ஜனங்கள் மோசேயை நோக்கிக் கூப்பிட்டார்கள்; மோசே கர்த்தரை நோக்கி விண்ணப்பம்பண்ணினான்; உடனே அக்கினி அவிந்துபோயிற்று.", "en": "And the people cried unto Moses; and when Moses prayed unto the LORD , the fire was quenched."}, {"verse": 3, "start": 33.61, "end": 41.31, "ta": "கர்த்தருடைய அக்கினி அவர்களுக்குள்ளே பற்றியெரிந்ததினால், அவ்விடத்துக்குத் தபேரா என்று பேரிட்டான்.", "en": "And he called the name of the place Taberah: because the fire of the LORD burnt among them."}, {"verse": 4, "start": 41.31, "end": 54.44, "ta": "பின்பு அவர்களுக்குள் இருந்த பலஜாதியான அந்நிய ஜனங்கள் மிகுந்த இச்சையுள்ளவர்களானார்கள்; இஸ்ரவேல் புத்திரரும் திரும்ப அழுது, நமக்கு இறைச்சியைப் புசிக்கக்கொடுப்பவர் யார்?", "en": "And the mixt multitude that was among them fell a lusting: and the children of Israel also wept again, and said, Who shall give us flesh to eat?"}, {"verse": 5, "start": 54.44, "end": 67.99, "ta": "நாம் எகிப்திலே கிரயமில்லாமல் சாப்பிட்ட மச்சங்களையும், வெள்ளரிக்காய்களையும், கொம்மட்டிக்காய்களையும், கீரைகளையும், வெண்காயங்களையும், வெள்ளைப்பூண்டுகளையும் நினைக்கிறோம்.", "en": "We remember the fish, which we did eat in Egypt freely; the cucumbers, and the melons, and the leeks, and the onions, and the garlick:"}, {"verse": 6, "start": 67.99, "end": 78.26, "ta": "இப்பொழுது நம்முடைய உள்ளம் வாடிப்போகிறது; இந்த மன்னாவைத்தவிர, நம்முடைய கண்களுக்கு முன்பாக வேறொன்றும் இல்லையே என்று சொன்னார்கள்.", "en": "But now our soul is dried away: there is nothing at all, beside this manna, before our eyes."}, {"verse": 7, "start": 78.26, "end": 84.82, "ta": "அந்த மன்னா கொத்துமல்லி விதையம்மாத்திரமும், அதின் நிறம் முத்துப்போலவும் இருந்தது.", "en": "And the manna was as coriander seed, and the colour thereof as the colour of bdellium."}, {"verse": 8, "start": 84.82, "end": 100.44, "ta": "ஜனங்கள் போய் அதைப் பொறுக்கிக்கொண்டுவந்து, ஏந்திரங்களில் அரைத்தாவது உரல்களில் இடித்தாவது, பானைகளில் சமைப்பார்கள்; அதை அப்பங்களுமாகச் சுடுவார்கள்; அதின் ருசி புது ஒலிவ எண்ணெயின் ருசிபோலிருந்தது.", "en": "And the people went about, and gathered it , and ground it in mills, or beat it in a mortar, and baked it in pans, and made cakes of it: and the taste of it was as the taste of fresh oil."}, {"verse": 9, "start": 100.44, "end": 106.0, "ta": "இரவிலே பாளயத்தின்மேல் பனிபெய்யும்போது, மன்னாவும் அதின்மேல் விழும்.", "en": "And when the dew fell upon the camp in the night, the manna fell upon it."}, {"verse": 10, "start": 106.0, "end": 120.05, "ta": "அந்தந்த வம்சங்களைச் சேர்ந்த ஜனங்கள் தங்கள் தங்கள் கூடாரவாசலில் நின்று அழுகிறதை மோசே கேட்டான்; கர்த்தருக்கு மிகவும் கோபம் மூண்டது; மோசேயின் பார்வைக்கும் அது பொல்லாப்பாயிருந்தது.", "en": "Then Moses heard the people weep throughout their families, every man in the door of his tent: and the anger of the LORD was kindled greatly; Moses also was displeased."}, {"verse": 11, "start": 120.05, "end": 135.38, "ta": "அப்பொழுது மோசே கர்த்தரை நோக்கி: நீர் இந்த ஜனங்கள் எல்லாருடைய பாரத்தையும் என்மேல் சுமத்தினதினால், உமது அடியானுக்கு உபத்திரவம் வரப்பண்ணினதென்ன? உம்முடைய கண்களில் எனக்குக் கிருபை கிடையாதே போனதென்ன?", "en": "And Moses said unto the LORD , Wherefore hast thou afflicted thy servant? and wherefore have I not found favour in thy sight, that thou layest the burden of all this people upon me?"}, {"verse": 12, "start": 135.38, "end": 154.64, "ta": "இவர்களுடைய பிதாக்களுக்கு நான் ஆணையிட்டுக்கொடுத்த தேசத்துக்கு நீ இவர்களை முலையுண்கிற பாலகனைத் தகப்பன் சுமந்துகொண்டுபோவதுபோல, உன் மார்பிலே அணைத்துக்கொண்டுபோ என்று நீர் என்னோடே சொல்லும்படி இந்த ஜனங்களையெல்லாம் கர்ப்பந்தரித்தேனோ? இவர்களைப் பெற்றது நானோ?", "en": "Have I conceived all this people? have I begotten them, that thou shouldest say unto me, Carry them in thy bosom, as a nursing father beareth the sucking child, unto the land which thou swarest unto their fathers?"}, {"verse": 13, "start": 154.64, "end": 165.41, "ta": "இந்த ஜனங்கள் எல்லாருக்கும் கொடுக்கிறதற்கு எனக்கு இறைச்சி எங்கேயிருந்து வரும்? எனக்கு இறைச்சிகொடு என்று என்னைப் பார்த்து அழுகிறார்களே.", "en": "Whence should I have flesh to give unto all this people? for they weep unto me, saying, Give us flesh, that we may eat."}, {"verse": 14, "start": 165.41, "end": 172.97, "ta": "இந்த ஜனங்களெல்லாரையும் நான் ஒருவனாய்த் தாங்கக் கூடாது; எனக்கு இது மிஞ்சின பாரமாயிருக்கிறது.", "en": "I am not able to bear all this people alone, because it is too heavy for me."}, {"verse": 15, "start": 172.97, "end": 185.81, "ta": "உம்முடைய கண்களிலே எனக்குக் கிருபை கிடைத்ததானால், இப்படி எனக்குச் செய்யாமல், என் உபத்திரவத்தை நான் காணாதபடிக்கு இப்பொழுதே என்னைக் கொன்றுபோடும் என்று வேண்டிக்கொண்டான்.", "en": "And if thou deal thus with me, kill me, I pray thee, out of hand, if I have found favour in thy sight; and let me not see my wretchedness."}, {"verse": 16, "start": 185.81, "end": 203.35, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி: இஸ்ரவேல் ஜனங்களுக்கு மூப்பரும் தலைவருமானவர்கள் இன்னார் என்று நீ அறிந்திருக்கிறாயே, அந்த மூப்பரில் எழுபதுபேரைக் கூட்டி, அவர்களை ஆசரிப்புக் கூடாரத்தினிடத்தில் அங்கே உன்னோடேகூட வந்து நிற்கும்படி செய்.", "en": "And the LORD said unto Moses, Gather unto me seventy men of the elders of Israel, whom thou knowest to be the elders of the people, and officers over them; and bring them unto the tabernacle of the congregation, that they may stand there with thee."}, {"verse": 17, "start": 203.35, "end": 217.62, "ta": "அப்பொழுது நான் இறங்கிவந்து அங்கே உன்னோடே பேசி, நீ ஒருவன் மாத்திரம் ஜனங்களின் பாரத்தைச் சுமக்காமல், உன்னோடேகூட அவர்களும் அதைச் சுமப்பதற்காக உன்மேல் இருக்கிற ஆவியை அவர்கள்மேலும் வைப்பேன்.", "en": "And I will come down and talk with thee there: and I will take of the spirit which is upon thee, and will put it upon them; and they shall bear the burden of the people with thee, that thou bear it not thyself alone."}, {"verse": 18, "start": 217.62, "end": 242.08, "ta": "நீ ஜனங்களை நோக்கி: நாளைக்காக உங்களைப் பரிசுத்தம்பண்ணுங்கள்; நீங்கள் இறைச்சி சாப்பிடுவீர்கள்; எங்களுக்கு இறைச்சி சாப்பிடக் கொடுப்பவர் யார் என்றும், எகிப்திலே எங்களுக்குச் செளக்கியமாயிருந்தது என்றும், கர்த்தருடைய செவிகள் கேட்க அழுதீர்களே; ஆகையால், நீங்கள் சாப்பிடும்படி கர்த்தர் உங்களுக்கு இறைச்சி கொடுப்பார்.", "en": "And say thou unto the people, Sanctify yourselves against to morrow, and ye shall eat flesh: for ye have wept in the ears of the LORD , saying, Who shall give us flesh to eat? for it was well with us in Egypt: therefore the LORD will give you flesh, and ye shall eat."}, {"verse": 19, "start": 242.08, "end": 248.43, "ta": "நீங்கள் ஒருநாள், இரண்டுநாள், ஐந்துநாள், பத்துநாள், இருபதுநாள் மாத்திரமல்ல,", "en": "Ye shall not eat one day, nor two days, nor five days, neither ten days, nor twenty days;"}, {"verse": 20, "start": 248.43, "end": 268.18, "ta": "ஒரு மாதம்வரைக்கும் புசிப்பீர்கள், அது உங்கள் மூக்காலே புறப்பட்டு, உங்களுக்குத் தெவிட்டிப்போகுமட்டும் புசிப்பீர்கள், உங்களுக்குள்ளே இருக்கிற கர்த்தரை அசட்டைபண்ணி, நாங்கள் ஏன் எகிப்திலிருந்து புறப்பட்டோம் என்று அவருக்கு முன்பாக அழுதீர்களே என்று சொல் என்றார்.", "en": "But even a whole month, until it come out at your nostrils, and it be loathsome unto you: because that ye have despised the LORD which is among you, and have wept before him, saying, Why came we forth out of Egypt?"}, {"verse": 21, "start": 268.18, "end": 278.67, "ta": "அதற்கு மோசே: என்னோடிருக்கிற காலாட்கள் ஆறுலட்சம்பேர்; ஒருமாதம் முழுவதும் புசிக்கும்படி அவர்களுக்கு இறைச்சி கொடுப்பேன் என்று சொன்னீரே.", "en": "And Moses said, The people, among whom I am , are six hundred thousand footmen; and thou hast said, I will give them flesh, that they may eat a whole month."}, {"verse": 22, "start": 278.67, "end": 290.36, "ta": "ஆடுமாடுகளை அவர்களுக்காக அடித்தாலும் அவர்களுக்குப் போதுமா? சமுத்திரத்து மச்சங்களையெல்லாம் அவர்களுக்காகச் சேர்த்தாலும் அவர்களுக்குப் போதுமா என்றான்.", "en": "Shall the flocks and the herds be slain for them, to suffice them? or shall all the fish of the sea be gathered together for them, to suffice them?"}, {"verse": 23, "start": 290.36, "end": 302.49, "ta": "அதற்குக் கர்த்தர் மோசேயை நோக்கி: கர்த்தருடய கை குறுகியிருக்கிறதோ? என் வார்த்தையின்படி நடக்குமோ? நடவாதோ என்று, நீ இப்பொழுது காண்பாய் என்றார்.", "en": "And the LORD said unto Moses, Is the LORD’s hand waxed short? thou shalt see now whether my word shall come to pass unto thee or not."}, {"verse": 24, "start": 302.49, "end": 315.04, "ta": "அப்பொழுது மோசே புறப்பட்டு, கர்த்தருடைய வார்த்தைகளை ஜனங்களுக்குச் சொல்லி, ஜனங்களின் மூப்பரில் எழுபதுபேரைக் கூட்டி, கூடாரத்தைச் சுற்றிலும் அவர்களை நிறுத்தினான்.", "en": "And Moses went out, and told the people the words of the LORD , and gathered the seventy men of the elders of the people, and set them round about the tabernacle."}, {"verse": 25, "start": 315.04, "end": 331.37, "ta": "கர்த்தர் மேகத்தில் இறங்கி, அவனோடே பேசி, அவன்மேலிருந்த ஆவியை மூப்பராகிய அந்த எழுபதுபேர்மேலும் வைத்தார் அந்த ஆவி அவர்கள்மேல் வந்து தங்கினமாத்திரத்தில் தீர்க்கதரிசனஞ் சொன்னார்கள்; சொல்லி, பின்பு ஓய்ந்தார்கள்.", "en": "And the LORD came down in a cloud, and spake unto him, and took of the spirit that was upon him, and gave it unto the seventy elders: and it came to pass, that , when the spirit rested upon them, they prophesied, and did not cease."}, {"verse": 26, "start": 331.37, "end": 352.2, "ta": "அப்பொழுது இரண்டுபேர் பாளயத்தில் இருந்துவிட்டார்கள்; ஒருவன்பேர் எல்தாத், மற்றவன்பேர் மேதாத்; அவர்களும் பேர்வழியில் எழுதப்பட்டிருந்தும், கூடாரத்துக்குப் போகப் புறப்படாதிருந்தார்கள்; அவர்கள்மேலும் ஆவி வந்து தங்கினதினால், பாளயத்தில் தீர்க்கதரிசனஞ் சொன்னார்கள்.", "en": "But there remained two of the men in the camp, the name of the one was Eldad, and the name of the other Medad: and the spirit rested upon them; and they were of them that were written, but went not out unto the tabernacle: and they prophesied in the camp."}, {"verse": 27, "start": 352.2, "end": 361.4, "ta": "ஒரு பிள்ளையாண்டான் ஓடிவந்து, எல்தாதும் மேதாதும் பாளயத்தில் தீர்க்கதரிசனஞ் சொல்லுகிறார்கள் என்று மோசேக்கு அறிவித்தான்.", "en": "And there ran a young man, and told Moses, and said, Eldad and Medad do prophesy in the camp."}, {"verse": 28, "start": 361.4, "end": 373.81, "ta": "உடனே மோசேயினிடத்தில் உள்ள வாலிபரில் ஒருவனும் அவனுடைய ஊழியக்காரனும் நூனின் குமாரனுமாகிய யோசுவா பிரதியுத்தரமாக: என் ஆண்டவனாகிய மோசேயே, அவர்களைத் தடைபண்ணும் என்றான்.", "en": "And Joshua the son of Nun, the servant of Moses, one of his young men, answered and said, My lord Moses, forbid them."}, {"verse": 29, "start": 373.81, "end": 388.78, "ta": "அதற்கு மோசே: நீ எனக்காக வைராக்கியம் காண்பிக்கிறாயோ? கர்த்தருடைய ஜனங்கள் எல்லாரும் தீர்க்கதரிசனஞ் சொல்லத்தக்கதாக, கர்த்தர் தம்முடைய ஆவியை அவர்கள்மேல் இறங்கப்பண்ணினால் நலமாயிருக்குமே என்றான்.", "en": "And Moses said unto him, Enviest thou for my sake? would God that all the LORD’s people were prophets, and that the LORD would put his spirit upon them!"}, {"verse": 30, "start": 388.78, "end": 394.56, "ta": "பின்பு, மோசேயும் இஸ்ரவேலின் மூப்பரும் பாளயத்திலே வந்து சேர்ந்தார்கள்.", "en": "And Moses gat him into the camp, he and the elders of Israel."}, {"verse": 31, "start": 394.56, "end": 414.67, "ta": "அப்பொழுது கர்த்தரிடத்திலிருந்து புறப்பட்ட ஒரு காற்று சமுத்திரத்திலிருந்து காடைகளை அடித்துக்கொண்டுவந்து, பாளயத்திலும் பாளயத்தைச் சுற்றிலும், இந்தப்பக்கம் ஒருநாள் பிரயாணமட்டும் அந்தப்பக்கம் ஒருநாள் பிரயாணமட்டும், தரையின்மேல் இரண்டுமுழ உயரம் விழுந்துகிடக்கச் செய்தது.", "en": "And there went forth a wind from the LORD , and brought quails from the sea, and let them fall by the camp, as it were a day’s journey on this side, and as it were a day’s journey on the other side, round about the camp, and as it were two cubits high upon the face of the earth."}, {"verse": 32, "start": 414.67, "end": 432.29, "ta": "அப்பொழுது ஜனங்கள் எழும்பி அன்று பகல்முழுவதும், இராமுழுவதும், மறுநாள் முழுவதும் காடைகளைச் சேர்த்தார்கள்; கொஞ்சமாய்ச் சேர்த்தவன் பத்து ஓமர் அளவு சேர்த்தான்; அவைகளைப் பாளயத்தைச் சுற்றிலும் தங்களுக்காகக் குவித்துவைத்தார்கள்.", "en": "And the people stood up all that day, and all that night, and all the next day, and they gathered the quails: he that gathered least gathered ten homers: and they spread them all abroad for themselves round about the camp."}, {"verse": 33, "start": 432.29, "end": 444.63, "ta": "தங்கள் பற்கள் நடுவே இருக்கும் இறைச்சியை அவர்கள் மென்று தின்னுமுன்னே கர்த்தருடைய கோபம் ஜனங்களுக்குள்ளே மூண்டது; கர்த்தர் ஜனங்களை மகா பெரிய வாதையால் வாதித்தார்.", "en": "And while the flesh was yet between their teeth, ere it was chewed, the wrath of the LORD was kindled against the people, and the LORD smote the people with a very great plague."}, {"verse": 34, "start": 444.63, "end": 452.47, "ta": "இச்சித்த ஜனங்களை அங்கே அடக்கம்பண்ணினதினால், அந்த ஸ்தலத்துக்குக் கிப்ரோத் அத்தாவா என்று பேரிட்டான்.", "en": "And he called the name of that place Kibroth-hattaavah: because there they buried the people that lusted."}, {"verse": 35, "start": 452.47, "end": 461.6, "ta": "பின்பு, ஜனங்கள் கிப்ரோத் அத்தாவா என்னும் இடத்தை விட்டு, ஆஸரோத்துக்குப் பிரயாணம்பண்ணி, ஆஸரோத்திலே தங்கினார்கள்.", "en": "And the people journeyed from Kibroth-hattaavah unto Hazeroth; and abode at Hazeroth."}]}, "12": {"chapter": 12, "duration": 177.91, "audio_url": "audio_ot/OT04_12.mp3", "total_verses": 16, "verses": [{"verse": 1, "start": 3.8, "end": 16.64, "ta": "எத்தியோப்பியா தேசத்து ஸ்திரீயை மோசே விவாகம்பண்ணியிருந்தபடியினால், மிரியாமும் ஆரோனும் அவன் விவாகம்பண்ணின எத்தியோப்பியா தேசத்து ஸ்திரீயினிமித்தம் அவனுக்கு விரோதமாய்ப் பேசி:", "en": "And Miriam and Aaron spake against Moses because of the Ethiopian woman whom he had married: for he had married an Ethiopian woman."}, {"verse": 2, "start": 16.64, "end": 26.81, "ta": "கர்த்தர் மோசேயைக் கொண்டுமாத்திரம் பேசினாரோ, எங்களைக்கொண்டும் அவர் பேசினதில்லையோ என்றார்கள். கர்த்தர் அதைக் கேட்டார்.", "en": "And they said, Hath the LORD indeed spoken only by Moses? hath he not spoken also by us? And the LORD heard it ."}, {"verse": 3, "start": 26.81, "end": 32.9, "ta": "மோசேயானவன் பூமியிலுள்ள சகல மனிதரிலும் மிகுந்த சாந்தகுணமுள்ளவனாயிருந்தான்.", "en": "(Now the man Moses was very meek, above all the men which were upon the face of the earth.)"}, {"verse": 4, "start": 32.9, "end": 45.97, "ta": "சடுதியிலே கர்த்தர் மோசேயையும் ஆரோனையும் மிரியாமையும் நோக்கி: நீங்கள் மூன்றுபேரும் ஆசரிப்புக் கூடாரத்துக்குப் புறப்பட்டுவாருங்கள் என்றார்; மூன்றுபேரும் போனார்கள்.", "en": "And the LORD spake suddenly unto Moses, and unto Aaron, and unto Miriam, Come out ye three unto the tabernacle of the congregation. And they three came out."}, {"verse": 5, "start": 45.97, "end": 55.99, "ta": "கர்த்தர் மேகத்தூணில் இறங்கி, கூடாரவாசலிலே நின்று, ஆரோனையும் மிரியாமையும் கூப்பிட்டார்; அவர்கள் இருவரும் போனார்கள்.", "en": "And the LORD came down in the pillar of the cloud, and stood in the door of the tabernacle, and called Aaron and Miriam: and they both came forth."}, {"verse": 6, "start": 55.99, "end": 70.99, "ta": "அப்பொழுது அவர்: என் வார்த்தைகளைக் கேளுங்கள்; உங்களுக்குள்ளே ஒருவன் தீர்க்கதரிசியாயிருந்தால், கர்த்தராகிய நான் தரிசனத்தில் என்னை அவனுக்கு வெளிப்படுத்தி, சொப்பனத்தில் அவனோடே பேசுவேன்.", "en": "And he said, Hear now my words: If there be a prophet among you, I the LORD will make myself known unto him in a vision, and will speak unto him in a dream."}, {"verse": 7, "start": 70.99, "end": 77.97, "ta": "என் தாசனாகிய மோசேயோ அப்படிப்பட்டவன் அல்ல, என் வீட்டில் எங்கும் அவன் உண்மையுள்ளவன்.", "en": "My servant Moses is not so, who is faithful in all mine house."}, {"verse": 8, "start": 77.97, "end": 96.08, "ta": "நான் அவனுடன் மறைபொருளாக அல்ல, முகமுகமாகவும் பிரத்தியட்சமாகவும் பேசுகிறேன்; அவன் கர்த்தரின் சாயலைக் காண்கிறான்; இப்படியிருக்க, நீங்கள் என் தாசனாகிய மோசேக்கு விரோதமாய்ப் பேச, உங்களுக்குப் பயமில்லாமற்போனதென்ன என்றார்.", "en": "With him will I speak mouth to mouth, even apparently, and not in dark speeches; and the similitude of the LORD shall he behold: wherefore then were ye not afraid to speak against my servant Moses?"}, {"verse": 9, "start": 96.08, "end": 101.43, "ta": "கர்த்தருடைய கோபம் அவர்கள்மேல் மூண்டது; அவர் போய்விட்டார்.", "en": "And the anger of the LORD was kindled against them; and he departed."}, {"verse": 10, "start": 101.43, "end": 114.94, "ta": "மேகம் கூடாரத்தை விட்டு நீங்கிப்போயிற்று; மிரியாம் உறைந்த மழையின் வெண்மைபோன்ற குஷ்டரோகியானாள்; ஆரோன் மிரியாமைப் பார்த்தபோது, அவள் குஷ்டரோகியாயிருக்கக் கண்டான்.", "en": "And the cloud departed from off the tabernacle; and, behold, Miriam became leprous, white as snow: and Aaron looked upon Miriam, and, behold, she was leprous."}, {"verse": 11, "start": 114.94, "end": 124.74, "ta": "அப்பொழுது ஆரோன் மோசேயை நோக்கி: ஆ, என் ஆண்டவனே, நாங்கள் புத்தியீனமாய்ச் செய்த இந்தப் பாவத்தை எங்கள்மேல் சுமத்தாதிரும்.", "en": "And Aaron said unto Moses, Alas, my lord, I beseech thee, lay not the sin upon us, wherein we have done foolishly, and wherein we have sinned."}, {"verse": 12, "start": 124.74, "end": 132.9, "ta": "தன் தாயின் கர்ப்பத்தில் பாதி மாம்சம் அழுகிச் செத்துவிழுந்த பிள்ளையைப்போல அவள் ஆகாதிருப்பாளாக என்றான்.", "en": "Let her not be as one dead, of whom the flesh is half consumed when he cometh out of his mother’s womb."}, {"verse": 13, "start": 132.9, "end": 139.66, "ta": "அப்பொழுது மோசே கர்த்தரை நோக்கி: என் தேவனே, அவளைக் குணமாக்கும் என்று கெஞ்சினான்.", "en": "And Moses cried unto the LORD , saying, Heal her now, O God, I beseech thee."}, {"verse": 14, "start": 139.66, "end": 157.18, "ta": "கர்த்தர் மோசேயை நோக்கி: அவள் தகப்பன் அவள் முகத்திலே காறித் துப்பினதுண்டானால், அவள் ஏழுநாள் வெட்கப்படவேண்டாமோ, அதுபோலவே அவள் ஏழுநாள் பாளயத்துக்குப் புறம்பே விலக்கப்பட்டிருந்து, பின்பு சேர்த்துக்கொள்ளப்படக்கடவள் என்றார்.", "en": "And the LORD said unto Moses, If her father had but spit in her face, should she not be ashamed seven days? let her be shut out from the camp seven days, and after that let her be received in again ."}, {"verse": 15, "start": 157.18, "end": 168.99, "ta": "அப்படியே மிரியாம் ஏழுநாள் பாளயத்துக்குப் புறம்பே விலக்கப்பட்டிருந்தாள்; மிரியாம் சேர்த்துக்கொள்ளப்படுமட்டும் ஜனங்கள் பிரயாணம்பண்ணாதிருந்தார்கள்.", "en": "And Miriam was shut out from the camp seven days: and the people journeyed not till Miriam was brought in again ."}, {"verse": 16, "start": 168.99, "end": 176.41, "ta": "பின்பு, ஜனங்கள் ஆஸரோத்திலிருந்து புறப்பட்டு, பாரான் வனாந்தரத்திலே பாளயமிறங்கினார்கள்.", "en": "And afterward the people removed from Hazeroth, and pitched in the wilderness of Paran."}]}, "13": {"chapter": 13, "duration": 321.87, "audio_url": "audio_ot/OT04_13.mp3", "total_verses": 33, "verses": [{"verse": 1, "start": 3.8, "end": 5.48, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.48, "end": 19.98, "ta": "நான் இஸ்ரவேல் புத்திரருக்குக் கொடுக்கும் கானான்தேசத்தைச் சுற்றிப்பார்ப்பதற்கு நீ மனிதரை அனுப்பு; ஒவ்வொரு பிதாக்களின் கோத்திரத்திலும் ஒவ்வொரு பிரபுவாகிய புருஷனை அனுப்பவேண்டும் என்றார்.", "en": "Send thou men, that they may search the land of Canaan, which I give unto the children of Israel: of every tribe of their fathers shall ye send a man, every one a ruler among them."}, {"verse": 3, "start": 19.98, "end": 30.67, "ta": "மோசே கர்த்தருடைய வாக்கின்படியே அவர்களைப் பாரான் வனாந்தரத்தலிருந்து அனுப்பினான்; அந்த மனிதர் யாவரும் இஸ்ரவேல் புத்திரரின் தலைவர்கள்.", "en": "And Moses by the commandment of the LORD sent them from the wilderness of Paran: all those men were heads of the children of Israel."}, {"verse": 4, "start": 30.67, "end": 36.38, "ta": "அவர்களுடைய நாமங்களாவன: ரூபன் கோத்திரத்தில் சக்கூரின் குமாரன் சம்முவா.", "en": "And these were their names: of the tribe of Reuben, Shammua the son of Zaccur."}, {"verse": 5, "start": 36.38, "end": 40.55, "ta": "சிமியோன் கோத்திரத்தில் ஓரியின் குமாரன் சாப்பாத்.", "en": "Of the tribe of Simeon, Shaphat the son of Hori."}, {"verse": 6, "start": 40.55, "end": 44.73, "ta": "யூதா கோத்திரத்தில் எப்புன்னேயின் குமாரன் காலேப்.", "en": "Of the tribe of Judah, Caleb the son of Jephunneh."}, {"verse": 7, "start": 44.73, "end": 48.9, "ta": "இசக்கார் கோத்திரத்தில் யோசேப்பின் குமாரன் ஈகால்.", "en": "Of the tribe of Issachar, Igal the son of Joseph."}, {"verse": 8, "start": 48.9, "end": 53.0, "ta": "எப்பிராயீம் கோத்திரத்தில் நூனின் குமாரன் ஓசேயா.", "en": "Of the tribe of Ephraim, Oshea the son of Nun."}, {"verse": 9, "start": 53.0, "end": 57.32, "ta": "பென்யமீன் கோத்திரத்தில் ரப்பூவின் குமாரன் பல்த்தி.", "en": "Of the tribe of Benjamin, Palti the son of Raphu."}, {"verse": 10, "start": 57.32, "end": 61.56, "ta": "செபுலோன் கோத்திரத்தில் சோதியின் குமாரன் காதியேல்.", "en": "Of the tribe of Zebulun, Gaddiel the son of Sodi."}, {"verse": 11, "start": 61.56, "end": 67.57, "ta": "யோசேப்பின் கோத்திரத்தைச் சேர்ந்த மனாசே கோத்திரத்தில் சூசின் குமாரன் காதி.", "en": "Of the tribe of Joseph, namely , of the tribe of Manasseh, Gaddi the son of Susi."}, {"verse": 12, "start": 67.57, "end": 71.81, "ta": "தாண் கோத்திரத்தில் கெமல்லியின் குமாரன் அம்மியேல்.", "en": "Of the tribe of Dan, Ammiel the son of Gemalli."}, {"verse": 13, "start": 71.81, "end": 75.99, "ta": "ஆசேர் கோத்திரத்தில் மிகாவேலின் குமாரன் சேத்தூர்.", "en": "Of the tribe of Asher, Sethur the son of Michael."}, {"verse": 14, "start": 75.99, "end": 80.09, "ta": "நப்தலி கோத்திரத்தில் ஒப்பேசியின் குமாரன் நாகபி.", "en": "Of the tribe of Naphtali, Nahbi the son of Vophsi."}, {"verse": 15, "start": 80.09, "end": 83.89, "ta": "காத் கோத்திரத்தில் மாகியின் குமாரன் கூவேல்.", "en": "Of the tribe of Gad, Geuel the son of Machi."}, {"verse": 16, "start": 83.89, "end": 95.02, "ta": "தேசத்தைச் சுற்றிப்பார்க்கும்படி மோசே அனுப்பின மனிதரின் நாமங்கள் இவைகளே; நூனின் குமாரனாகிய ஓசேயாவுக்கு யோசுவா என்று மோசே பேரிட்டிருந்தான்.", "en": "These are the names of the men which Moses sent to spy out the land. And Moses called Oshea the son of Nun Jehoshua."}, {"verse": 17, "start": 95.02, "end": 104.76, "ta": "அவர்களை மோசே கானான்தேசத்தைச் சுற்றிப்பார்க்கும்படி அனுப்புகையில், அவர்களை நோக்கி: நீங்கள் இப்படித் தெற்கே போய், மலையில் ஏறி,", "en": "And Moses sent them to spy out the land of Canaan, and said unto them, Get you up this way southward, and go up into the mountain:"}, {"verse": 18, "start": 104.76, "end": 112.96, "ta": "தேசம் எப்படிப்பட்டதென்றும், குடியிருக்கிற ஜனங்கள் பலவான்களோ பலவீனர்களோ, கொஞ்சம்பேரோ அநேகம்பேரோ என்றும்,", "en": "And see the land, what it is; and the people that dwelleth therein, whether they be strong or weak, few or many;"}, {"verse": 19, "start": 112.96, "end": 128.04, "ta": "அவர்கள் குடியிருக்கிற தேசம் எப்படிப்பட்டது, அது நல்லதோ கெட்டதோ என்றும், அவர்கள் பட்டணங்கள் எப்படிப்பட்டதென்றும், அவர்கள் கூடாரங்களில் குடியிருக்கிறவர்களோ கோட்டைகளில் குடியிருக்கிறவர்களோ என்றும்,", "en": "And what the land is that they dwell in, whether it be good or bad; and what cities they be that they dwell in, whether in tents, or in strong holds;"}, {"verse": 20, "start": 128.04, "end": 147.96, "ta": "நிலம் எப்படிப்பட்டது, அது வளப்பமானதோ இளப்பமானதோ என்றும், அதில் விருட்சங்கள் உண்டோ இல்லையோ என்றும் பாருங்கள், தைரியங்கொண்டிருந்து, தேசத்தின் கனிகளிலே சிலவற்றைக் கொண்டுவாருங்கள் என்றான். அக்காலம் திராட்சச்செடி முதற்பழம் பழுக்கிற காலமாயிருந்தது.", "en": "And what the land is , whether it be fat or lean, whether there be wood therein, or not. And be ye of good courage, and bring of the fruit of the land. Now the time was the time of the firstripe grapes."}, {"verse": 21, "start": 147.96, "end": 156.74, "ta": "அவர்கள் போய், சீன் வனாந்தரந்தொடங்கி, ஆமாத்துக்குப் போகிற வழியாகிய ரேகொப்மட்டும், தேசத்தைச் சுற்றிப்பார்த்து,", "en": "So they went up, and searched the land from the wilderness of Zin unto Rehob, as men come to Hamath."}, {"verse": 22, "start": 156.74, "end": 172.04, "ta": "தெற்கேயும் சென்று, எபிரோன்மட்டும் போனார்கள்; அங்கே ஏனாக்கின் குமாரராகிய அகீமானும் சேசாயும் தல்மாயும் இருந்தார்கள். எபிரோன் எகிப்திலுள்ள சோவானுக்கு ஏழுவருஷத்திற்குமுன்னே கட்டப்பட்டது.", "en": "And they ascended by the south, and came unto Hebron; where Ahiman, Sheshai, and Talmai, the children of Anak, were . (Now Hebron was built seven years before Zoan in Egypt.)"}, {"verse": 23, "start": 172.04, "end": 190.13, "ta": "பின்பு, அவர்கள் எஸ்கோல் பள்ளத்தாக்குமட்டும் போய், அங்கே ஒரே குலையுள்ள திராட்சக்கொடியை அறுத்தார்கள்; அதை ஒரு தடியிலே இரண்டுபேர் கட்டித் தூக்கிக்கொண்டுவந்தார்கள்: மாதளம்பழங்களிலும் அத்திப்பழங்களிலும் சிலவற்றைக் கொண்டுவந்தார்கள்.", "en": "And they came unto the brook of Eshcol, and cut down from thence a branch with one cluster of grapes, and they bare it between two upon a staff; and they brought of the pomegranates, and of the figs."}, {"verse": 24, "start": 190.13, "end": 198.4, "ta": "இஸ்ரவேல் புத்திரர் அங்கே அறுத்த திராட்சக்குலையினிமித்தம், அவ்விடம் எஸ்கோல் பள்ளத்தாக்கு என்னப்பட்டது.", "en": "The place was called the brook Eshcol, because of the cluster of grapes which the children of Israel cut down from thence."}, {"verse": 25, "start": 198.4, "end": 204.84, "ta": "அவர்கள் தேசத்தைச் சுற்றிப்பார்த்து, நாற்பதுநாள் சென்றபின்பு திரும்பினார்கள்.", "en": "And they returned from searching of the land after forty days."}, {"verse": 26, "start": 204.84, "end": 224.1, "ta": "அவர்கள் பாரான் வனாந்தரத்தில் இருக்கிற காதேசுக்கு வந்து, மோசே ஆரோன் என்பவர்களிடத்திலும் இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரிடத்திலும் சேர்ந்து, அவர்களுக்கும் சபையாரனைவருக்கும் சமாசாரத்தை அறிவித்து, தேசத்தின் கனிகளை அவர்களுக்குக் காண்பித்தார்கள்.", "en": "And they went and came to Moses, and to Aaron, and to all the congregation of the children of Israel, unto the wilderness of Paran, to Kadesh; and brought back word unto them, and unto all the congregation, and shewed them the fruit of the land."}, {"verse": 27, "start": 224.1, "end": 235.15, "ta": "அவர்கள் மோசேயை நோக்கி: நீர் எங்களை அனுப்பின தேசத்துக்கு நாங்கள் போய்வந்தோம்; அது பாலும் தேனும் ஓடுகிற தேசந்தான்; இது அதினுடைய கனி.", "en": "And they told him, and said, We came unto the land whither thou sentest us, and surely it floweth with milk and honey; and this is the fruit of it."}, {"verse": 28, "start": 235.15, "end": 248.33, "ta": "ஆனாலும், அந்த தேசத்திலே குடியிருக்கிற ஜனங்கள் பலவான்கள்; பட்டணங்கள் அரணிப்பானவைகளும் மிகவும் பெரியவைகளுமாய் இருக்கிறது; அங்கே ஏனாக்கின் குமாரரையும் கண்டோம்.", "en": "Nevertheless the people be strong that dwell in the land, and the cities are walled, and very great: and moreover we saw the children of Anak there."}, {"verse": 29, "start": 248.33, "end": 264.66, "ta": "அமலேக்கியர் தென்புறமான தேசத்தில் குடியிருக்கிறார்கள்; ஏத்தியரும், எபூசியரும், எமோரியரும் மலைநாட்டில் குடியிருக்கிறார்கள்; கானானியர் கடல் அருகேயும் யோர்தானண்டையிலும் குடியிருக்கிறார்கள் என்றார்கள்.", "en": "The Amalekites dwell in the land of the south: and the Hittites, and the Jebusites, and the Amorites, dwell in the mountains: and the Canaanites dwell by the sea, and by the coast of Jordan."}, {"verse": 30, "start": 264.66, "end": 276.15, "ta": "அப்பொழுது காலேப் மோசேக்கு முன்பாக ஜனங்களை அமர்த்தி: நாம் உடனே போய் அதைச் சுதந்தரித்துக்கொள்வோம்; நாம் அதை எளிதாய் ஜெயித்துக்கொள்ளலாம் என்றான்.", "en": "And Caleb stilled the people before Moses, and said, Let us go up at once, and possess it; for we are well able to overcome it."}, {"verse": 31, "start": 276.15, "end": 286.55, "ta": "அவனோடேகூடப் போய்வந்த மனிதரோ நாம் போய் அந்த ஜனங்களோடே எதிர்க்க நம்மாலே கூடாது; அவர்கள் நம்மைப்பார்க்கிலும் பலவான்கள் என்றார்கள்.", "en": "But the men that went up with him said, We be not able to go up against the people; for they are stronger than we."}, {"verse": 32, "start": 286.55, "end": 297.23, "ta": "நாங்கள் போய்ச் சுற்றிப் பார்த்துவந்த அந்த தேசம் தன் குடிகளைப் பட்சிக்கிற தேசம் நாங்கள் அதிலே கண்ட ஜனங்கள் எல்லாரும் மிகவும் பெரிய ஆட்கள்.", "en": "And they brought up an evil report of the land which they had searched unto the children of Israel, saying, The land, through which we have gone to search it, is a land that eateth up the inhabitants thereof; and all the people that we saw in it are men of a great stature."}, {"verse": 33, "start": 297.23, "end": 320.37, "ta": "அங்கே இராட்சதப் பிறவியான ஏனாக்கின் குமாரராகிய இராட்சதரையும் கண்டோம்; நாங்கள் எங்கள் பார்வைக்கு வெட்டுக்கிளிகளைப்போல் இருந்தோம், அவர்கள் பார்வைக்கும் அப்படியே இருந்தோம் என்று சொல்லி, இப்படி இஸ்ரவேல் புத்திரருக்குள்ளே தாங்கள் சுற்றிப்பார்த்துவந்த தேசத்தைக்குறித்து துர்ச்செய்தி பரம்பச்செய்தார்கள்.", "en": "And there we saw the giants, the sons of Anak, which come of the giants: and we were in our own sight as grasshoppers, and so we were in their sight."}]}, "14": {"chapter": 14, "duration": 528.47, "audio_url": "audio_ot/OT04_14.mp3", "total_verses": 45, "verses": [{"verse": 1, "start": 3.8, "end": 12.52, "ta": "அப்பொழுது சபையார் எல்லாரும் கூக்குரலிட்டுப் புலம்பினார்கள்; ஜனங்கள் அன்று இராமுழுதும் அழுதுகொண்டிருந்தார்கள்.", "en": "And all the congregation lifted up their voice, and cried; and the people wept that night."}, {"verse": 2, "start": 12.52, "end": 28.91, "ta": "இஸ்ரவேல் புத்திரர் எல்லாரும் மோசேக்கும் ஆரோனுக்கும் விரோதமாக முறுமுறுத்தார்கள். சபையார் எல்லாரும் அவர்களை நோக்கி: எகிப்துதேசத்திலே செத்துப்போனோமானால் நலமாயிருக்கும்; இந்த வனாந்தரத்திலே நாங்கள் செத்தாலும் நலம்.", "en": "And all the children of Israel murmured against Moses and against Aaron: and the whole congregation said unto them, Would God that we had died in the land of Egypt! or would God we had died in this wilderness!"}, {"verse": 3, "start": 28.91, "end": 46.0, "ta": "நாங்கள் பட்டயத்தால் மடியும்படிக்கும், எங்கள் பெண்ஜாதிகளும் பிள்ளைகளையும் கொள்ளையாகும்படிக்கும், கர்த்தர் எங்களை இந்த தேசத்துக்குக் கொண்டுவந்தது என்ன? எகிப்துக்குத் திரும்பிப்போகிறதே எங்களுக்கு உத்தமம் அல்லவோ என்றார்கள்.", "en": "And wherefore hath the LORD brought us unto this land, to fall by the sword, that our wives and our children should be a prey? were it not better for us to return into Egypt?"}, {"verse": 4, "start": 46.0, "end": 55.91, "ta": "பின்பு அவர்கள்: நாம் ஒரு தலைவனை ஏற்படுத்திக்கொண்டு எகிப்துக்குத் திரும்பிப்போவோம் வாருங்கள் என்று ஒருவரோடொருவர் சொல்லிக்கொண்டார்கள்.", "en": "And they said one to another, Let us make a captain, and let us return into Egypt."}, {"verse": 5, "start": 55.91, "end": 65.13, "ta": "அப்பொழுது மோசேயும் ஆரோனும் இஸ்ரவேல் புத்திரரின் சபையாராகிய எல்லாக் கூட்டத்தாருக்கு முன்பாகவும் முகங்குப்புற விழுந்தார்கள்.", "en": "Then Moses and Aaron fell on their faces before all the assembly of the congregation of the children of Israel."}, {"verse": 6, "start": 65.13, "end": 75.39, "ta": "தேசத்தைச் சுற்றிப்பார்த்தவர்களில் நூனின் குமாரனாகிய யோசுவாவும், எப்புன்னேயின் குமாரனாகிய காலேபும், தங்கள் வஸ்திரங்களைக் கிழித்துக்கொண்டு,", "en": "And Joshua the son of Nun, and Caleb the son of Jephunneh, which were of them that searched the land, rent their clothes:"}, {"verse": 7, "start": 75.39, "end": 83.41, "ta": "இஸ்ரவேல் புத்திரரின் சமஸ்த சபையையும் நோக்கி: நாங்கள் போய்ச் சுற்றிப்பார்த்து சோதித்த தேசம் மகா நல்லதேசம்.", "en": "And they spake unto all the company of the children of Israel, saying, The land, which we passed through to search it, is an exceeding good land."}, {"verse": 8, "start": 83.41, "end": 93.54, "ta": "கர்த்தர் நம்மேல் பிரியமாயிருந்தால், அந்தத் தேசத்திலே நம்மைக் கொண்டுபோய், பாலும் தேனும் ஓடுகிற அந்தத் தேசத்தை நமக்குக் கொடுப்பார்.", "en": "If the LORD delight in us, then he will bring us into this land, and give it us; a land which floweth with milk and honey."}, {"verse": 9, "start": 93.54, "end": 115.06, "ta": "கர்த்தருக்கு விரோதமாகமாத்திரம் கலகம்பபண்ணாதிருங்கள்; அந்த தேசத்தின் ஜனங்களுக்கு நீங்கள் பயப்படவேண்டியதில்லை; அவர்கள் நமக்கு இரையாவார்கள்; அவர்களைக் காத்த நிழல் அவர்களை விட்டு விலகிப்போயிற்று; கர்த்தர் நம்மோடே இருக்கிறார்; அவர்களுக்குப் பயப்படவேண்டியதில்லை என்றார்கள்.", "en": "Only rebel not ye against the LORD , neither fear ye the people of the land; for they are bread for us: their defence is departed from them, and the LORD is with us: fear them not."}, {"verse": 10, "start": 115.06, "end": 128.56, "ta": "அப்பொழுது அவர்கள்மேல் கல்லெறியவேண்டும் என்று சபையார் எல்லாரும் சொன்னார்கள்; உடனே கர்த்தருடைய மகிமை ஆசரிப்புக் கூடாரத்தில் இஸ்ரவேல் புத்திரர் எல்லாருக்கும் முன்பாகக் காணப்பட்டது.", "en": "But all the congregation bade stone them with stones. And the glory of the LORD appeared in the tabernacle of the congregation before all the children of Israel."}, {"verse": 11, "start": 128.56, "end": 143.47, "ta": "கர்த்தர் மோசேயை நோக்கி: எதுவரைக்கும் இந்த ஜனங்கள் எனக்குக் கோபம் உண்டாக்குவார்கள்? தங்களுக்குள்ளே நான் காட்டின சகல அடையாளங்களையும் அவர்கள் கண்டும், எதுவரைக்கும் என்னை விசுவாசியாதிருப்பார்கள்?", "en": "And the LORD said unto Moses, How long will this people provoke me? and how long will it be ere they believe me, for all the signs which I have shewed among them?"}, {"verse": 12, "start": 143.47, "end": 155.29, "ta": "நான் அவர்களைக் கொள்ளை நோயினால் வாதித்து, சுதந்தரத்துக்குப் புறம்பாக்கிப்போட்டு, அவர்களைப்பார்க்கிலும் உன்னைப் பெரிதும் பலத்ததுமான ஜாதியாக்குவேன் என்றார்.", "en": "I will smite them with the pestilence, and disinherit them, and will make of thee a greater nation and mightier than they."}, {"verse": 13, "start": 155.29, "end": 165.13, "ta": "மோசே கர்த்தரை நோக்கி: எகிப்தியர் இதைக் கேட்பார்கள்; அவர்கள் நடுவிலிருந்து உம்முடைய வல்லமையினாலே இந்த ஜனங்களைக் கொண்டுவந்தீரே.", "en": "And Moses said unto the LORD , Then the Egyptians shall hear it , (for thou broughtest up this people in thy might from among them;)"}, {"verse": 14, "start": 165.13, "end": 187.71, "ta": "கர்த்தராகிய நீர் இந்த ஜனங்களின் நடுவே இருக்கிறதையும், கர்த்தராகிய நீர் முகமுகமாய்த் தரிசனமாகிறதையும், உம்முடைய மேகம் இவர்கள்மேல் நிற்கிறதையும், பகலில் மேகத்தூணிலும், இரவில் அக்கினித்தூணிலும், நீர் இவர்களுக்கு முன் செல்லுகிறதையும் கேட்டிருக்கிறார்கள், இந்த தேசத்தின் குடிகளுக்கும் சொல்லுவார்கள்.", "en": "And they will tell it to the inhabitants of this land: for they have heard that thou LORD art among this people, that thou LORD art seen face to face, and that thy cloud standeth over them, and that thou goest before them, by day time in a pillar of a cloud, and in a pillar of fire by night."}, {"verse": 15, "start": 187.71, "end": 196.85, "ta": "ஒரே மனிதனைக் கொல்லுகிறதுபோல இந்த ஜனங்களையெல்லாம் நீர் கொல்வீரானால், அப்பொழுது உம்முடைய கீர்த்தியைக் கேட்டிருக்கும் புறஜாதியார்:", "en": "Now if thou shalt kill all this people as one man, then the nations which have heard the fame of thee will speak, saying,"}, {"verse": 16, "start": 196.85, "end": 209.3, "ta": "கர்த்தர் அந்த ஜனங்களுக்குக் கொடுப்போம் என்று ஆணையிட்டிருந்த தேசத்திலே அவர்களைக் கொண்டுபோய் விடக் கூடாதேபோனபடியினால், அவர்களை வனாந்தரத்திலே கொன்றுபோட்டார் என்பார்களே.", "en": "Because the LORD was not able to bring this people into the land which he sware unto them, therefore he hath slain them in the wilderness."}, {"verse": 17, "start": 209.3, "end": 230.82, "ta": "ஆகையால் கர்த்தர் நீடிய சாந்தமும் மிகுந்த கிருபையுமுள்ளவர் என்றும், அக்கிரமத்தையும் மீறுதலையும் மன்னிக்கிறவரென்றும், குற்றமுள்ளவர்களைக் குற்றமற்றவர்களாக விடாமல், பிதாக்கள் செய்த அக்கிரமத்தைப் பிள்ளைகளிடத்தில் மூன்றாம் நான்காம் தலைமுறைமட்டும் விசாரிக்கிறவர் என்றும், நீர் சொல்லியிருக்கிறபடியே,", "en": "And now, I beseech thee, let the power of my Lord be great, according as thou hast spoken, saying,"}, {"verse": 18, "start": 230.82, "end": 234.48, "ta": "என் ஆண்டவருடைய வல்லமை பெரிதாய் விளங்குவதாக.", "en": "The LORD is longsuffering, and of great mercy, forgiving iniquity and transgression, and by no means clearing the guilty , visiting the iniquity of the fathers upon the children unto the third and fourth generation ."}, {"verse": 19, "start": 234.48, "end": 247.91, "ta": "உமது கிருபையினுடைய மகத்துவத்தின்படியேயும், எகிப்தை விட்டதுமுதல் இந்நாள்வரைக்கும் இந்த ஜனங்களுக்கு மன்னித்துவந்ததின்படியேயும், இந்த ஜனங்களின் அக்கிரமத்தை மன்னித்தருளும் என்றான்.", "en": "Pardon, I beseech thee, the iniquity of this people according unto the greatness of thy mercy, and as thou hast forgiven this people, from Egypt even until now."}, {"verse": 20, "start": 247.91, "end": 252.34, "ta": "அப்பொழுது கர்த்தர்: உன் வார்த்தையின்படியே மன்னித்தேன்.", "en": "And the LORD said, I have pardoned according to thy word:"}, {"verse": 21, "start": 252.34, "end": 259.72, "ta": "பூமியெல்லாம் கர்த்தருடைய மகிமையினால் நிறைந்திருக்கும் என்று என்னுடைய ஜீவனைக்கொண்டு சொல்லுகிறேன்.", "en": "But as truly as I live, all the earth shall be filled with the glory of the LORD ."}, {"verse": 22, "start": 259.72, "end": 273.37, "ta": "என் மகிமையையும், நான் எகிப்திலும் வனாந்தரத்திலும் செய்த என் அடையாளங்களையும் கண்டிருந்தும், என் சத்தத்துக்குச் செவிகொடாமல், இதனோடே பத்துமுறை என்னைப் பரீட்சை பார்த்த மனிதரில் ஒருவரும்,", "en": "Because all those men which have seen my glory, and my miracles, which I did in Egypt and in the wilderness, and have tempted me now these ten times, and have not hearkened to my voice;"}, {"verse": 23, "start": 273.37, "end": 283.92, "ta": "அவர்கள் பிதாக்களுக்கு நான் ஆணையிட்டுக்கொடுத்த தேசத்தைக் காணமாட்டார்கள்; எனக்குக் கோபம் உண்டாக்கினவர்களில் ஒருவரும் அதைக்காணமாட்டார்கள்.", "en": "Surely they shall not see the land which I sware unto their fathers, neither shall any of them that provoked me see it:"}, {"verse": 24, "start": 283.92, "end": 299.81, "ta": "என்னுடைய தாசனாகிய காலேப் வேறே ஆவியை உடையவனாயிருக்கிறபடியினாலும், உத்தமமாய் என்னைப் பின்பற்றிவந்தபடியினாலும், அவன் போய்வந்ததேசத்திலே அவனைச் சேரப்பண்ணுவேன்; அவன் சந்ததியார் அதைச் சுதந்தரித்துக்கொள்ளுவார்கள்.", "en": "But my servant Caleb, because he had another spirit with him, and hath followed me fully, him will I bring into the land whereinto he went; and his seed shall possess it."}, {"verse": 25, "start": 299.81, "end": 313.03, "ta": "அமலேக்கியரும் கானானியரும் பள்ளத்தாக்கிலே குடியிருக்கிறபடியினால், நாளைக்கு நீங்கள் திரும்பி சிவந்த சமுத்திரத்துக்குப் போகிற வழியாய் வனாந்தரத்துக்குப் பிரயாணம்பண்ணுங்கள் என்றார்.", "en": "(Now the Amalekites and the Canaanites dwelt in the valley.) To morrow turn you, and get you into the wilderness by the way of the Red sea."}, {"verse": 26, "start": 313.03, "end": 316.27, "ta": "பின்னும் கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 27, "start": 316.27, "end": 327.52, "ta": "எனக்கு விரோதமாய் முறுமுறுக்கிற இந்தப் பொல்லாத சபையாரை எதுவரைக்கும் பொறுப்பேன்? இஸ்ரவேல் புத்திரர் எனக்கு விரோதமாய் முறுமுறுக்கிறதைக் கேட்டேன்.", "en": "How long shall I bear with this evil congregation, which murmur against me? I have heard the murmurings of the children of Israel, which they murmur against me."}, {"verse": 28, "start": 327.52, "end": 340.18, "ta": "நீ அவர்களோடே சொல்லவேண்டியது என்னவென்றால்: நீங்கள் என் செவிகள் கேட்கச் சொன்னபிரகாரம் உங்களுக்குச் செய்வேன் என்பதை என் ஜீவனைக்கொண்டு சொல்லுகிறேன் என்று கர்த்தர் உரைக்கிறார்.", "en": "Say unto them, As truly as I live, saith the LORD , as ye have spoken in mine ears, so will I do to you:"}, {"verse": 29, "start": 340.18, "end": 356.64, "ta": "இந்த வனாந்தரத்தில் உங்கள் பிரேதங்கள் விழும்; உங்களில் இருபது வயதுமுதல் அதற்கு மேற்பட்டவர்களாக எண்ணப்பட்டு, உங்கள் தொகைக்கு உட்பட்டவர்களும் எனக்கு விரோதமாய் முறுமுறுத்திருக்கிறவர்களுமாகிய அனைவரின் பிரேதங்களும் விழும்.", "en": "Your carcases shall fall in this wilderness; and all that were numbered of you, according to your whole number, from twenty years old and upward, which have murmured against me,"}, {"verse": 30, "start": 356.64, "end": 369.44, "ta": "எப்புன்னேயின் குமாரன் காலேபும், நூனின் குமாரன் யோசுவாவும் தவிர, மற்றவர்களாகிய நீங்கள் நான் உங்களைக் குடியேற்றுவேன் என்று ஆணையிட்டுக்கொடுத்த தேசத்தில் பிரவேசிப்பதில்லை.", "en": "Doubtless ye shall not come into the land, concerning which I sware to make you dwell therein, save Caleb the son of Jephunneh, and Joshua the son of Nun."}, {"verse": 31, "start": 369.44, "end": 380.55, "ta": "கொள்ளையாவார்கள் என்று நீங்கள் சொன்ன உங்கள் குழந்தைகளையோ நான் அதில் பிரவேசிக்கச் செய்வேன்; நீங்கள் அசட்டைப்பண்ணின தேசத்தை அவர்கள் கண்டறிவார்கள்.", "en": "But your little ones, which ye said should be a prey, them will I bring in, and they shall know the land which ye have despised."}, {"verse": 32, "start": 380.55, "end": 384.27, "ta": "உங்கள் பிரேதங்களோ இந்த வனாந்தரத்திலே விழும்.", "en": "But as for you, your carcases, they shall fall in this wilderness."}, {"verse": 33, "start": 384.27, "end": 395.1, "ta": "அவைகள் வனாந்தரத்திலே விழுந்து தீருமட்டும், உங்கள் பிள்ளைகள் நாற்பதுவருஷம் வனாந்தரத்திலே திரிந்து, நீங்கள் சோரம்போன பாதகத்தைச் சுமப்பார்கள்.", "en": "And your children shall wander in the wilderness forty years, and bear your whoredoms, until your carcases be wasted in the wilderness."}, {"verse": 34, "start": 395.1, "end": 409.8, "ta": "நீங்கள் தேசத்தை சுற்றிப்பார்த்த நாற்பதுநாள் இலக்கத்தின்படியே, ஒவ்வொரு நாள் ஒவ்வொரு வருஷமாக, நீங்கள் நாற்பது வருஷம் உங்கள் அக்கிரமங்களைச் சுமந்து, என் உடன்படிக்கைக்கு வந்த மாறுதலை உணருவீர்கள்.", "en": "After the number of the days in which ye searched the land, even forty days, each day for a year, shall ye bear your iniquities, even forty years, and ye shall know my breach of promise."}, {"verse": 35, "start": 409.8, "end": 424.5, "ta": "கர்த்தராகிய நான் இதைச் சொன்னேன்; எனக்கு விரோதமாய்க் கூட்டங்கூடின இந்தப் பொல்லாத சபையார் யாவருக்கும் இப்படியே செய்வேன்; இந்த வனாந்தரத்திலே அழிவார்கள், இங்கே சாவார்கள் என்று சொல் என்றார்.", "en": "I the LORD have said, I will surely do it unto all this evil congregation, that are gathered together against me: in this wilderness they shall be consumed, and there they shall die."}, {"verse": 36, "start": 424.5, "end": 433.64, "ta": "அந்த தேசத்தைச் சோதித்துப்பார்க்கும்படி மோசேயால் அனுப்பப்பட்டுத் திரும்பி, அந்த தேசத்தைக்குறித்துத் துர்ச்செய்தி கொண்டுவந்து,", "en": "And the men, which Moses sent to search the land, who returned, and made all the congregation to murmur against him, by bringing up a slander upon the land,"}, {"verse": 37, "start": 433.64, "end": 445.04, "ta": "சபையார் எல்லாரும் அவனுக்கு விரோதமாய் முறுமுறுக்கும்படி அந்தத் துர்ச்செய்தியைச் சொன்னவர்களாகிய அந்த மனிதர் கர்த்தருடைய சந்நிதியில் வாதையினால் செத்தார்கள்.", "en": "Even those men that did bring up the evil report upon the land, died by the plague before the LORD ."}, {"verse": 38, "start": 445.04, "end": 455.52, "ta": "தேசத்தைச் சுற்றிப்பார்க்கப்போன அந்த மனிதரில் நூனின் குமாரனாகிய யோசுவாவும், எப்புன்னேயின் குமாரனாகிய காலேபும்மாத்திரம் உயிரோடிருந்தார்கள்.", "en": "But Joshua the son of Nun, and Caleb the son of Jephunneh, which were of the men that went to search the land, lived still ."}, {"verse": 39, "start": 455.52, "end": 463.04, "ta": "மோசே இந்த வார்த்தைகளை இஸ்ரவேல் புத்திரர் அனைவரோடும் சொன்னபோது, ஜனங்கள் மிகவும் துக்கித்தார்கள்.", "en": "And Moses told these sayings unto all the children of Israel: and the people mourned greatly."}, {"verse": 40, "start": 463.04, "end": 475.14, "ta": "அதிகாலமே அவர்கள் எழுந்திருந்து: நாங்கள் பாவஞ்செய்தோம், கர்த்தர் வாக்குத்தத்தம்பண்ணின இடத்துக்கு நாங்கள் போவோம் என்று சொல்லி மலையின் உச்சியில் ஏறத்துணிந்தார்கள்.", "en": "And they rose up early in the morning, and gat them up into the top of the mountain, saying, Lo, we be here , and will go up unto the place which the LORD hath promised: for we have sinned."}, {"verse": 41, "start": 475.14, "end": 483.16, "ta": "மோசே அவர்களை நோக்கி: நீங்கள் இப்படி கர்த்தரின் கட்டளையை மீறுகிறதென்ன? அது உங்களுக்கு வாய்க்காது.", "en": "And Moses said, Wherefore now do ye transgress the commandment of the LORD ? but it shall not prosper."}, {"verse": 42, "start": 483.16, "end": 492.37, "ta": "நீங்கள் உங்கள் சத்துருக்களுக்கு முன்பாக முறிய அடிக்கப்படாதபடிக்கு ஏறிப்போகாதிருங்கள்; கர்த்தர் உங்கள் நடுவில் இரார்.", "en": "Go not up, for the LORD is not among you; that ye be not smitten before your enemies."}, {"verse": 43, "start": 492.37, "end": 506.65, "ta": "அமலேக்கியரும் கானானியரும் அங்கே உங்களுக்குமுன்னே இருக்கிறார்கள்; பட்டயத்தினால் விழுவீர்கள்; நீங்கள் கர்த்தரை விட்டுப் பின்வாங்கினபடியால், கர்த்தர் உங்களோடே இருக்கமாட்டார் என்றான்.", "en": "For the Amalekites and the Canaanites are there before you, and ye shall fall by the sword: because ye are turned away from the LORD , therefore the LORD will not be with you."}, {"verse": 44, "start": 506.65, "end": 516.84, "ta": "ஆனாலும் அவர்கள் மலையின் உச்சியில் ஏறத் துணிந்தார்கள்; கர்த்தருடைய உடன்படிக்கையின் பெட்டியும் மோசேயும் பாளயத்தை விட்டுப் போகவில்லை.", "en": "But they presumed to go up unto the hill top: nevertheless the ark of the covenant of the LORD , and Moses, departed not out of the camp."}, {"verse": 45, "start": 516.84, "end": 526.97, "ta": "அப்பொழுது அமலேக்கியரும் கானானியரும் அந்த மலையிலே இருந்து இறங்கிவந்து, அவர்களை முறிய அடித்து, அவர்களை ஓர்மாமட்டும் துரத்தினார்கள்.", "en": "Then the Amalekites came down, and the Canaanites which dwelt in that hill, and smote them, and discomfited them, even unto Hormah."}]}, "15": {"chapter": 15, "duration": 459.15, "audio_url": "audio_ot/OT04_15.mp3", "total_verses": 41, "verses": [{"verse": 1, "start": 3.8, "end": 5.49, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.49, "end": 16.49, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நீங்கள் குடியிருக்கும்படி நான் உங்களுக்குக் கொடுக்கும் தேசத்தில் நீங்கள் போய்ச் சேர்ந்தபின்பு,", "en": "Speak unto the children of Israel, and say unto them, When ye be come into the land of your habitations, which I give unto you,"}, {"verse": 3, "start": 16.49, "end": 34.54, "ta": "விசேஷித்த பொருத்தனையாயாவது, உற்சாக பலியாயாவது, உங்கள் பண்டிகைகளில் செலுத்தும் பலியாயாவது, கர்த்தருக்கு மாடுகளிலாகிலும் ஆடுகளிலாகிலும் சர்வாங்க தகனபலியையாவது மற்ற யாதொரு பலியையாவது கர்த்தருக்குச் சுகந்த வாசனையான தகனமாகப் பலியிடும்போது,", "en": "And will make an offering by fire unto the LORD , a burnt offering, or a sacrifice in performing a vow, or in a freewill offering, or in your solemn feasts, to make a sweet savour unto the LORD , of the herd, or of the flock:"}, {"verse": 4, "start": 34.54, "end": 51.77, "ta": "தன் படைப்பைக் கர்த்தருக்குச் செலுத்துகிறவன் சர்வாங்க தகனபலிக்காகிலும் மற்றப் பலிக்காகிலும் ஒரு ஆட்டுக்குட்டியுடனே, ஒரு மரக்காலிலே பத்தில் ஒரு பங்கும் காற்படி எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவின் போஜனபலியைச் செலுத்தக்கடவன்.", "en": "Then shall he that offereth his offering unto the LORD bring a meat offering of a tenth deal of flour mingled with the fourth part of an hin of oil."}, {"verse": 5, "start": 51.77, "end": 56.18, "ta": "பானபலியாக காற்படி திராட்சரசத்தையும் படைக்கவேண்டும்.", "en": "And the fourth part of an hin of wine for a drink offering shalt thou prepare with the burnt offering or sacrifice, for one lamb."}, {"verse": 6, "start": 56.18, "end": 67.25, "ta": "ஆட்டுக்கடாவாயிருந்ததேயாகில், பத்தில் இரண்டு பங்கானதும், ஒரு படியில் மூன்றில் ஒரு பங்காகிய எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவின் போஜனபலியையும்,", "en": "Or for a ram, thou shalt prepare for a meat offering two tenth deals of flour mingled with the third part of an hin of oil."}, {"verse": 7, "start": 67.25, "end": 76.28, "ta": "பானபலியாக ஒரு படியில் மூன்றிலொரு பங்கு திராட்சரசத்தையும் கர்த்தருக்குச் சுகந்த வாசனையான படைப்பாகப் படைக்கவேண்டும்.", "en": "And for a drink offering thou shalt offer the third part of an hin of wine, for a sweet savour unto the LORD ."}, {"verse": 8, "start": 76.28, "end": 87.72, "ta": "நீ சர்வாங்க தகனபலிக்காகிலும், விசேஷித்த பொருத்தனை பலிக்காகிலும், சமாதான பலிக்காகிலும், ஒரு காளையைக் கர்த்தருக்குச் செலுத்த ஆயத்தப்படுத்தும்போது,", "en": "And when thou preparest a bullock for a burnt offering, or for a sacrifice in performing a vow, or peace offerings unto the LORD :"}, {"verse": 9, "start": 87.72, "end": 95.13, "ta": "அதனோடே பத்தில் மூன்று பங்கானதும், அரைப்படி எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவின் போஜனபலியையும்,", "en": "Then shall he bring with a bullock a meat offering of three tenth deals of flour mingled with half an hin of oil."}, {"verse": 10, "start": 95.13, "end": 103.05, "ta": "பானபலியாக அரைப்படி திராட்ச ரசத்தையும், கர்த்தருக்குச் சுகந்தவாசனையான தகனபலியாகப் படைக்கவேண்டும்.", "en": "And thou shalt bring for a drink offering half an hin of wine, for an offering made by fire, of a sweet savour unto the LORD ."}, {"verse": 11, "start": 103.05, "end": 115.67, "ta": "இந்தப்பிரகாரமாகவே ஒவ்வொரு மாட்டுக்காகிலும், ஆட்டுக்கடாவுக்காகிலும், செம்மறியாட்டுக் குட்டிக்காகிலும், வெள்ளாட்டுக் குட்டிக்காகிலும் செய்து படைக்கவேண்டும்.", "en": "Thus shall it be done for one bullock, or for one ram, or for a lamb, or a kid."}, {"verse": 12, "start": 115.67, "end": 123.37, "ta": "நீங்கள் படைக்கிறவைகளின் இலக்கத்திற்குத்தக்கதாய் ஒவ்வொன்றிற்காகவும் இந்தப்பிரகாரம் செய்யவேண்டும்.", "en": "According to the number that ye shall prepare, so shall ye do to every one according to their number."}, {"verse": 13, "start": 123.37, "end": 132.54, "ta": "சுதேசத்தில் பிறந்தவர்கள் யாவரும் கர்த்தருக்குச் சுகந்த வாசனையான தகனபலியைச் செலுத்தும்போது இவ்விதமாகவே செய்யவேண்டும்.", "en": "All that are born of the country shall do these things after this manner, in offering an offering made by fire, of a sweet savour unto the LORD ."}, {"verse": 14, "start": 132.54, "end": 148.53, "ta": "உங்களிடத்திலே தங்கியிருக்கிற அந்நியனாவது, உங்கள் நடுவிலே உங்கள் தலைமுறைதோறும் குடியிருக்கிறவனாவது, கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி செலுத்தவேண்டுமானால், நீங்கள் செய்கிறபடியே அவனும் செய்யவேண்டும்.", "en": "And if a stranger sojourn with you, or whosoever be among you in your generations, and will offer an offering made by fire, of a sweet savour unto the LORD ; as ye do, so he shall do."}, {"verse": 15, "start": 148.53, "end": 165.04, "ta": "சபையாராகிய உங்களுக்கும் உங்களிடத்தில் தங்குகிற அந்நியனுக்கும் ஒரே பிரமாணம் இருக்கவேண்டும் என்பது உங்கள் தலைமுறைகளில் நித்திய கட்டளையாயிருக்கக்கடவது; கர்த்தருக்கு முன்பாக அந்நியனும் உங்களைப்போலவே இருக்கவேண்டும்.", "en": "One ordinance shall be both for you of the congregation, and also for the stranger that sojourneth with you , an ordinance for ever in your generations: as ye are , so shall the stranger be before the LORD ."}, {"verse": 16, "start": 165.04, "end": 174.06, "ta": "உங்களுக்கும் உங்களிடத்தில் தங்குகிற அந்நியனுக்கும் ஒரே பிரமாணமும் ஒரே முறைமையும் இருக்கக்கடவது என்று சொல் என்றார்.", "en": "One law and one manner shall be for you, and for the stranger that sojourneth with you."}, {"verse": 17, "start": 174.06, "end": 176.41, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 18, "start": 176.41, "end": 184.91, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நான் உங்களை அழைத்துக்கொண்டுபோகிற தேசத்தில் நீங்கள் சேர்ந்து,", "en": "Speak unto the children of Israel, and say unto them, When ye come into the land whither I bring you,"}, {"verse": 19, "start": 184.91, "end": 193.42, "ta": "தேசத்தின் ஆகாரத்தைப் புசிக்கும்போது, கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் காணிக்கையைச் செலுத்தக்கடவீர்கள்.", "en": "Then it shall be, that, when ye eat of the bread of the land, ye shall offer up an heave offering unto the LORD ."}, {"verse": 20, "start": 193.42, "end": 206.92, "ta": "உங்கள் பிசைந்த மாவினால் செய்த முதற்பலனாகிய அதிரசத்தை ஏறெடுத்துப் படைப்பீர்களாக; போரடிக்கிற களத்தின் படைப்பை ஏறெடுத்துப் படைக்கிறதுபோல அதையும் ஏறெடுத்துப் படைக்கவேண்டும்.", "en": "Ye shall offer up a cake of the first of your dough for an heave offering: as ye do the heave offering of the threshingfloor, so shall ye heave it."}, {"verse": 21, "start": 206.92, "end": 216.02, "ta": "இப்படி உங்கள் தலைமுறைதோறும் உங்கள் பிசைந்த மாவின் முதற்பலனிலே கர்த்தருக்குப் படைப்பை ஏறெடுத்துப் படைக்கக்கடவீர்கள்.", "en": "Of the first of your dough ye shall give unto the LORD an heave offering in your generations."}, {"verse": 22, "start": 216.02, "end": 221.23, "ta": "கர்த்தர் மோசேயினிடத்தில் சொன்ன இந்தக் கற்பனைகள் எல்லாவற்றின்படியும்,", "en": "And if ye have erred, and not observed all these commandments, which the LORD hath spoken unto Moses,"}, {"verse": 23, "start": 221.23, "end": 232.01, "ta": "கர்த்தர் மோசேயைக்கொண்டு கட்டளைகொடுத்த நாள்முதற்கொண்டு அவர் உங்களுக்கும் உங்கள் சந்ததிகளுக்கும் நியமித்த எல்லாவற்றின்படியேயும் நீங்கள் செய்யாமல்,", "en": "Even all that the LORD hath commanded you by the hand of Moses, from the day that the LORD commanded Moses , and henceforward among your generations;"}, {"verse": 24, "start": 232.01, "end": 252.99, "ta": "அறியாமல் தவறி நடந்தாலும், சபையாருக்குத் தெரியாமல் யாதொரு தப்பிதம் செய்தாலும், சபையார் எல்லாரும் கர்த்தருக்குச் சுகந்த வாசனையான தகனபலியாக ஒரு காளையையும், முறைமைப்படி அதற்கேற்ற போஜனபலியையும், பானபலியையும், பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தவேண்டும்.", "en": "Then it shall be, if ought be committed by ignorance without the knowledge of the congregation, that all the congregation shall offer one young bullock for a burnt offering, for a sweet savour unto the LORD , with his meat offering, and his drink offering, according to the manner, and one kid of the goats for a sin offering."}, {"verse": 25, "start": 252.99, "end": 274.19, "ta": "அதினால் ஆசாரியன் இஸ்ரவேல் புத்திரரின் சபையனைத்திற்காகவும் பாவநிவிர்த்தி செய்யக்கடவன்; அது அறியாமையில் செய்யப்பட்டபடியாலும், அதினிமித்தம் அவர்கள் கர்த்தருக்குத் தகனபலியையும் பாவநிவாரணபலியையும் கர்த்தருடைய சந்நிதியில் கொண்டுவந்ததினாலும், அது அவர்களுக்கு மன்னிக்கப்படும்.", "en": "And the priest shall make an atonement for all the congregation of the children of Israel, and it shall be forgiven them; for it is ignorance: and they shall bring their offering, a sacrifice made by fire unto the LORD , and their sin offering before the LORD , for their ignorance:"}, {"verse": 26, "start": 274.19, "end": 286.0, "ta": "அது அறியாமையினாலே ஜனங்கள் யாவருக்கும் வந்தபடியால், அது இஸ்ரவேல் புத்திரரின் சபையனைத்திற்கும் அவர்களுக்குள்ளே தங்குகிற அந்நியனுக்கும் மன்னிக்கப்படும்.", "en": "And it shall be forgiven all the congregation of the children of Israel, and the stranger that sojourneth among them; seeing all the people were in ignorance."}, {"verse": 27, "start": 286.0, "end": 293.92, "ta": "ஒருவன் அறியாமையினால் பாவஞ்செய்தானாகில், ஒரு வயதான வெள்ளாட்டைப் பாவநிவாரணபலியாகச் செலுத்தக்கடவன்.", "en": "And if any soul sin through ignorance, then he shall bring a she goat of the first year for a sin offering."}, {"verse": 28, "start": 293.92, "end": 306.9, "ta": "அப்பொழுது அறியாமையினால் பாவஞ்செய்தவனுக்காக ஆசாரியன் பாவநிவிர்த்தி செய்யும்படி கர்த்தருடைய சந்நிதியில் பாவநிவிர்த்தி செய்யக்கடவன், அப்பொழுது அவனுக்கு மன்னிக்கப்படும்.", "en": "And the priest shall make an atonement for the soul that sinneth ignorantly, when he sinneth by ignorance before the LORD , to make an atonement for him; and it shall be forgiven him."}, {"verse": 29, "start": 306.9, "end": 319.01, "ta": "இஸ்ரவேல் புத்திரராகிய உங்களில் பிறந்தவனுக்கும் உங்களுக்குள்ளே தங்கும் அந்நியனுக்கும், அறியாமையினால் பாவஞ்செய்தவனிமித்தம், ஒரே பிரமாணம் இருக்கவேண்டும்.", "en": "Ye shall have one law for him that sinneth through ignorance, both for him that is born among the children of Israel, and for the stranger that sojourneth among them."}, {"verse": 30, "start": 319.01, "end": 334.85, "ta": "அன்றியும் தேசத்திலே பிறந்தவர்களிலாகிலும் அந்நியர்களிலாகிலும், எவனாவது துணிகரமாய் யாதொன்றைச் செய்தால், அவன் கர்த்தரை நிந்திக்கிறான்; அந்த ஆத்துமா தன் ஜனத்தாரில் இராதபடிக்கு அறுப்புண்டுபோகவேண்டும்.", "en": "But the soul that doeth ought presumptuously, whether he be born in the land, or a stranger, the same reproacheth the LORD ; and that soul shall be cut off from among his people."}, {"verse": 31, "start": 334.85, "end": 347.98, "ta": "அவன் கர்த்தரின் வார்த்தையை அசட்டைபண்ணி, அவர் கற்பனையை மீறினபடியால், அந்த ஆத்துமா அறுப்புண்டுபோகவேண்டும்; அவன் அக்கிரமம் அவன்மேல் இருக்கும் என்று சொல் என்றார்.", "en": "Because he hath despised the word of the LORD , and hath broken his commandment, that soul shall utterly be cut off; his iniquity shall be upon him."}, {"verse": 32, "start": 347.98, "end": 357.89, "ta": "இஸ்ரவேல் புத்திரர் வனாந்தரத்தில் இருக்கையில், ஓய்வுநாளில் விறகுகளைப் பொறுக்கிக்கொண்டிருந்த ஒரு மனிதனைக் கண்டுபிடித்தார்கள்.", "en": "And while the children of Israel were in the wilderness, they found a man that gathered sticks upon the sabbath day."}, {"verse": 33, "start": 357.89, "end": 368.74, "ta": "விறகுகளைப் பொறுக்கின அந்த மனிதனைக் கண்டுபிடித்தவர்கள், அவனை மோசே ஆரோன் என்பவர்களிடத்துக்கும் சபையார் அனைவரிடத்துக்கும் கொண்டுவந்தார்கள்.", "en": "And they that found him gathering sticks brought him unto Moses and Aaron, and unto all the congregation."}, {"verse": 34, "start": 368.74, "end": 376.96, "ta": "அவனுக்குச் செய்யவேண்டியது இன்னதென்று தீர்க்கமான உத்தரவு இல்லாதபடியினால், அவனைக் காவலில் வைத்தார்கள்.", "en": "And they put him in ward, because it was not declared what should be done to him."}, {"verse": 35, "start": 376.96, "end": 388.84, "ta": "கர்த்தர் மோசேயை நோக்கி: அந்த மனிதன் நிச்சயமாய்க் கொலைசெய்யப்படவேண்டும்; சபையார் எல்லாரும் அவனைப் பாளயத்திற்குப் புறம்பே கல்லெறியக்கடவர்கள் என்றார்.", "en": "And the LORD said unto Moses, The man shall be surely put to death: all the congregation shall stone him with stones without the camp."}, {"verse": 36, "start": 388.84, "end": 400.51, "ta": "அப்பொழுது சபையார் எல்லாரும் கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, அவனைப் பாளயத்திற்குப் புறம்பே கொண்டுபோய்க் கல்லெறிந்தார்கள்; அவன் செத்தான்.", "en": "And all the congregation brought him without the camp, and stoned him with stones, and he died; as the LORD commanded Moses."}, {"verse": 37, "start": 400.51, "end": 402.85, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 38, "start": 402.85, "end": 417.6, "ta": "நீ இஸ்ரவேல் புத்திரரிடத்தில் பேசி, அவர்கள் தங்கள் தலைமுறைதோறும் தங்கள் வஸ்திரங்களின் ஓரங்களிலே தொங்கல்களை உண்டாக்கி, ஓரத்தின் தொங்கலிலே இளநீலநாடாவைக் கட்டவேண்டுமென்று அவர்களுக்குச் சொல்.", "en": "Speak unto the children of Israel, and bid them that they make them fringes in the borders of their garments throughout their generations, and that they put upon the fringe of the borders a ribband of blue:"}, {"verse": 39, "start": 417.6, "end": 434.62, "ta": "நீங்கள் பின்பற்றிச் சோரம்போகிற உங்கள் இருதயத்துக்கும் உங்கள் கண்களுக்கும் ஏற்க நடவாமல், அதைப்பார்த்து, கர்த்தரின் கற்பனைகளையெல்லாம் நினைத்து அவைகளின்படியே செய்யும்படிக்கு, அது உங்களுக்குத் தொங்கலாய் இருக்கவேண்டும்.", "en": "And it shall be unto you for a fringe, that ye may look upon it, and remember all the commandments of the LORD , and do them; and that ye seek not after your own heart and your own eyes, after which ye use to go a whoring:"}, {"verse": 40, "start": 434.62, "end": 444.96, "ta": "நீங்கள் என் கற்பனைகளையெல்லாம் நினைத்து, அவைகளின்படியே செய்து, உங்கள் தேவனுக்குப் பரிசுத்தராயிருக்கும்படி அதைப் பார்ப்பீர்களாக.", "en": "That ye may remember, and do all my commandments, and be holy unto your God."}, {"verse": 41, "start": 444.96, "end": 457.65, "ta": "நான் உங்களுக்குத் தேவனாயிருக்கும்படி உங்களை எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணின உங்கள் தேவனாகிய கர்த்தர்; நானே உங்கள் தேவனாகிய கர்த்தர் என்று சொல் என்றார்.", "en": "I am the LORD your God, which brought you out of the land of Egypt, to be your God: I am the LORD your God."}]}, "16": {"chapter": 16, "duration": 611.48, "audio_url": "audio_ot/OT04_16.mp3", "total_verses": 50, "verses": [{"verse": 1, "start": 3.8, "end": 17.49, "ta": "லேவிக்குப் பிறந்த கோகாத்தின் குமாரனாகிய இத்சேயாரின் மகன் கோராகு என்பவன் ரூபன் வம்சத்திலுள்ள எலியாபின் குமாரராகிய தாத்தானையும் அபிராமையும் பேலேத்தின் குமாரனாகிய ஓனையும் கூட்டிக்கொண்டு,", "en": "Now Korah, the son of Izhar, the son of Kohath, the son of Levi, and Dathan and Abiram, the sons of Eliab, and On, the son of Peleth, sons of Reuben, took men:"}, {"verse": 2, "start": 17.49, "end": 28.97, "ta": "இஸ்ரவேல் புத்திரரில் சபைக்குத் தலைவர்களும் சங்கத்துக்கு அழைக்கப்பட்டவர்களும் பிரபலமானவர்களுமாகிய இருநூற்று ஐம்பது பேர்களோடும்கூட மோசேக்குமுன்பாக எழும்பி,", "en": "And they rose up before Moses, with certain of the children of Israel, two hundred and fifty princes of the assembly, famous in the congregation, men of renown:"}, {"verse": 3, "start": 28.97, "end": 49.65, "ta": "மோசேக்கும் ஆரோனுக்கும் விரோதமாகக் கூட்டங்கூடி, அவர்களை நோக்கி: நீங்கள் மிஞ்சிப்போகிறீர்கள்; சபையார் எல்லாரும் பரிசுத்தமானவர்கள்; கர்த்தர் அவர்கள் நடுவில் இருக்கிறாரே; இப்படியிருக்க, கர்த்தருடைய சபைக்கு மேலாக உங்களை ஏன் உயர்த்துகிறீர்கள் என்றார்கள்.", "en": "And they gathered themselves together against Moses and against Aaron, and said unto them, Ye take too much upon you, seeing all the congregation are holy, every one of them, and the LORD is among them: wherefore then lift ye up yourselves above the congregation of the LORD ?"}, {"verse": 4, "start": 49.65, "end": 53.92, "ta": "மோசே அதைக் கேட்டபோது, முகங்குப்புற விழுந்தான்.", "en": "And when Moses heard it , he fell upon his face:"}, {"verse": 5, "start": 53.92, "end": 74.96, "ta": "பின்பு அவன் கோராகையும் அவனுடைய எல்லாக் கூட்டத்தையும் நோக்கி: நாளைக்குக் கர்த்தர் தம்முடையவன் இன்னான் என்றும், தம்மண்டையிலே சேரத் தாம் கட்டளையிட்ட பரிசுத்தவான் இன்னான் என்றும் காண்பிப்பார்; அப்பொழுது எவனைத் தெரிந்துகொள்வாரோ, அவனைத் தம்மிடத்தில் சேரக் கட்டளையிடுவார்.", "en": "And he spake unto Korah and unto all his company, saying, Even to morrow the LORD will shew who are his, and who is holy; and will cause him to come near unto him: even him whom he hath chosen will he cause to come near unto him."}, {"verse": 6, "start": 74.96, "end": 83.28, "ta": "ஒன்று செய்யுங்கள்; கோராகே, கோராகின் கூட்டத்தார்களே, நீங்கள் எல்லாரும் தூபகலசங்களை எடுத்துக்கொண்டு,", "en": "This do; Take you censers, Korah, and all his company;"}, {"verse": 7, "start": 83.28, "end": 100.72, "ta": "நாளைக்கு அவைகளில் அக்கினிபோட்டு, கர்த்தருடைய சந்நிதியில் தூபவர்க்கம் இடுங்கள்; அப்பொழுது கர்த்தர் எவனைத் தெரிந்துகொள்வாரோ, அவன் பரிசுத்தவானாயிருப்பான்; லேவியின் புத்திரராகிய நீங்களே மிஞ்சிப்போகிறீர்கள் என்றான்.", "en": "And put fire therein, and put incense in them before the LORD to morrow: and it shall be that the man whom the LORD doth choose, he shall be holy: ye take too much upon you, ye sons of Levi."}, {"verse": 8, "start": 100.72, "end": 105.73, "ta": "பின்னும் மோசே கோராகை நோக்கி: லேவியின் புத்திரரே, கேளுங்கள்;", "en": "And Moses said unto Korah, Hear, I pray you, ye sons of Levi:"}, {"verse": 9, "start": 105.73, "end": 122.65, "ta": "கர்த்தருடைய வாசஸ்தலத்தின் பணிவிடைகளைச் செய்யவும், சபையாரின் முன் நின்று அவர்கள் செய்யவேண்டிய வேலைகளைச் செய்யவும், உங்களைத் தம்மண்டையிலே சேரப்பண்ணும்படி இஸ்ரவேலின் தேவன் இஸ்ரவேல் சபையாரிலிருந்து உங்களைப் பிரித்தெடுத்ததும்,", "en": "Seemeth it but a small thing unto you, that the God of Israel hath separated you from the congregation of Israel, to bring you near to himself to do the service of the tabernacle of the LORD , and to stand before the congregation to minister unto them?"}, {"verse": 10, "start": 122.65, "end": 136.19, "ta": "அவர் உன்னையும் உன்னோடேகூட லேவியின் புத்திரராகிய உன்னுடைய எல்லாச் சகோதரரையும் சேரப்பண்ணினதும், உங்களுக்கு அற்பகாரியமோ? இப்பொழுது ஆசாரியப்பட்டத்தையும் தேடுகிறீர்களோ?", "en": "And he hath brought thee near to him , and all thy brethren the sons of Levi with thee: and seek ye the priesthood also?"}, {"verse": 11, "start": 136.19, "end": 148.78, "ta": "இதற்காக நீயும் உன் கூட்டத்தார் அனைவரும் கர்த்தருக்கு விரோதமாகவே கூட்டங்கூடினீர்கள்; ஆரோனுக்கு விரோதமாக நீங்கள் முறுமுறுக்கிறதற்கு அவன் எம்மாத்திரம் என்றான்.", "en": "For which cause both thou and all thy company are gathered together against the LORD : and what is Aaron, that ye murmur against him?"}, {"verse": 12, "start": 148.78, "end": 157.68, "ta": "பின்பு மோசே எலியாபின் குமாரராகிய தாத்தானையும் அபிராமையும் அழைத்தனுப்பினான். அவர்கள்: நாங்கள் வருகிறதில்லை;", "en": "And Moses sent to call Dathan and Abiram, the sons of Eliab: which said, We will not come up:"}, {"verse": 13, "start": 157.68, "end": 170.56, "ta": "இந்த வனாந்தரத்தில் எங்களைக் கொன்றுபோடும்படி, பாலும் தேனும் ஓடுகிற தேசத்திலிருந்து எங்களைக் கொண்டுவந்தது அற்பகாரியமோ, எங்கள்மேல் துரைத்தனமும் பண்ணப்பார்க்கிறாயோ?", "en": "Is it a small thing that thou hast brought us up out of a land that floweth with milk and honey, to kill us in the wilderness, except thou make thyself altogether a prince over us?"}, {"verse": 14, "start": 170.56, "end": 189.77, "ta": "மேலும் நீ எங்களைப் பாலும் தேனும் ஓடுகிற தேசத்துக்குக் கொண்டுவந்ததும் இல்லை, எங்களுக்கு வயல்களையும் திராட்சத்தோட்டங்களையும் சுதந்தரமாகக் கொடுத்ததும் இல்லை; இந்த மனிதருடைய கண்களைப் பிடுங்கப்பார்க்கிறாயோ? நாங்கள் வருகிறதில்லை என்றார்கள்.", "en": "Moreover thou hast not brought us into a land that floweth with milk and honey, or given us inheritance of fields and vineyards: wilt thou put out the eyes of these men? we will not come up."}, {"verse": 15, "start": 189.77, "end": 209.64, "ta": "அப்பொழுது மோசேக்குக் கடுங்கோபம் மூண்டது; அவன் கர்த்தரை நோக்கி: அவர்கள் செலுத்துங் காணிக்கையை அங்கிகரியாதிருப்பீராக; நான் அவர்களிடத்தில் ஒரு கழுதையை முதலாய் எடுத்துக்கொள்ளவில்லை; அவர்களில் ஒருவனுக்கும் யாதொரு பொல்லாப்பு செய்யவும் இல்லை என்றான்.", "en": "And Moses was very wroth, and said unto the LORD , Respect not thou their offering: I have not taken one ass from them, neither have I hurt one of them."}, {"verse": 16, "start": 209.64, "end": 221.19, "ta": "பின்பு மோசே கோராகை நோக்கி: நீயும் உன் கூட்டத்தார் யாவரும் நாளைக்குக் கர்த்தருடைய சந்நிதியில் வாருங்கள்; நீயும் அவர்களும் ஆரோனும் வந்திருங்கள்.", "en": "And Moses said unto Korah, Be thou and all thy company before the LORD , thou, and they, and Aaron, to morrow:"}, {"verse": 17, "start": 221.19, "end": 241.43, "ta": "உங்களில் ஒவ்வொருவரும் தங்கள் தங்கள் தூபகலசங்களை எடுத்து, அவைகளில் தூபவர்க்கத்தைப் போட்டு, தங்கள் தங்கள் தூபகலசங்களாகிய இருநூற்று ஐம்பது தூபகலசங்களையும் கர்த்தருடைய சந்நிதியில் கொண்டுவரவேண்டும்; நீயும் ஆரோனும் தன் தன் தூபகலசத்தைக் கொண்டுவாருங்கள் என்றான்.", "en": "And take every man his censer, and put incense in them, and bring ye before the LORD every man his censer, two hundred and fifty censers; thou also, and Aaron, each of you his censer."}, {"verse": 18, "start": 241.43, "end": 256.81, "ta": "அப்படியே அவரவர் தங்கள் தங்கள் தூபகலசங்களை எடுத்து, அவைகளில் அக்கினியையும் தூபவர்க்கத்தையும் போட்டு, ஆசரிப்புக் கூடாரவாசலுக்கு முன்பாக வந்து நின்றார்கள்; மோசேயும் ஆரோனும் அங்கே நின்றார்கள்.", "en": "And they took every man his censer, and put fire in them, and laid incense thereon, and stood in the door of the tabernacle of the congregation with Moses and Aaron."}, {"verse": 19, "start": 256.81, "end": 269.39, "ta": "அவர்களுக்கு விரோதமாகக் கோராகு சபையையெல்லாம் ஆசரிப்புக் கூடரவாசலுக்கு முன்பாகக் கூடிவரும்படி செய்தான்; அப்பொழுது கர்த்தருடைய மகிமை சபைக்கெல்லாம் காணப்பட்டது.", "en": "And Korah gathered all the congregation against them unto the door of the tabernacle of the congregation: and the glory of the LORD appeared unto all the congregation."}, {"verse": 20, "start": 269.39, "end": 271.97, "ta": "கர்த்தர் மோசேயோடும் ஆரோனோடும் பேசி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 21, "start": 271.97, "end": 279.26, "ta": "இந்தச் சபையை விட்டுப் பிரிந்துபோங்கள்; ஒரு நிமிஷத்திலே அவர்களை அதமாக்குவேன் என்றார்.", "en": "Separate yourselves from among this congregation, that I may consume them in a moment."}, {"verse": 22, "start": 279.26, "end": 292.72, "ta": "அப்பொழுது அவர்கள் முகங்குப்புறவிழுந்து: தேவனே, மாம்சமான யாவருடைய ஆவிகளுக்கும் தேவனே, ஒரு மனிதன் பாவம் செய்திருக்கச் சபையார் எல்லார்மேலும் கடுங்கோபங்கொள்வீரோ என்றார்கள்.", "en": "And they fell upon their faces, and said, O God, the God of the spirits of all flesh, shall one man sin, and wilt thou be wroth with all the congregation?"}, {"verse": 23, "start": 292.72, "end": 295.15, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 24, "start": 295.15, "end": 303.54, "ta": "கோராகு தாத்தான் அபிராம் என்பவர்களுடைய வாசஸ்தலத்தை விட்டு விலகிப்போங்கள் என்று சபையாருக்குச் சொல் என்றார்.", "en": "Speak unto the congregation, saying, Get you up from about the tabernacle of Korah, Dathan, and Abiram."}, {"verse": 25, "start": 303.54, "end": 313.48, "ta": "உடனே மோசே எழுந்திருந்து, தாத்தான் அபிராம் என்பவர்களிடத்தில் போனான்; இஸ்ரவேலின் மூப்பரும் அவனைப் பின்சென்று போனார்கள்.", "en": "And Moses rose up and went unto Dathan and Abiram; and the elders of Israel followed him."}, {"verse": 26, "start": 313.48, "end": 328.05, "ta": "அவன் சபையாரை நோக்கி இந்தத் துஷ்டமனிதரின் சகல பாவங்களிலும் நீங்கள் வாரிக்கொள்ளப்படாதபடிக்கு, அவர்கள் கூடாரங்களை விட்டு விலகி, அவர்களுக்கு உண்டானவைகளில் ஒன்றையும் தொடாதிருங்கள் என்றான்.", "en": "And he spake unto the congregation, saying, Depart, I pray you, from the tents of these wicked men, and touch nothing of theirs, lest ye be consumed in all their sins."}, {"verse": 27, "start": 328.05, "end": 344.31, "ta": "அப்படியே அவர்கள் கோராகு தாத்தான் அபிராம் என்பவர்களுடைய வாசஸ்தலத்தை விட்டு விலகிப்போனார்கள்; தாத்தானும் அபிராமும் வெளியே வந்து, தங்கள் பெண்ஜாதிகள் பிள்ளைகள் குழந்தைகளோடும் தங்கள் கூடாரவாசலிலே நின்றார்கள்.", "en": "So they gat up from the tabernacle of Korah, Dathan, and Abiram, on every side: and Dathan and Abiram came out, and stood in the door of their tents, and their wives, and their sons, and their little children."}, {"verse": 28, "start": 344.31, "end": 357.78, "ta": "அப்பொழுது மோசே: இந்தக் கிரியைகளையெல்லாம் செய்கிறதற்குக் கர்த்தர் என்னை அனுப்பினார் என்றும், அவைகளை நான் என் மனதின்படியே செய்யவில்லை என்றும், நீங்கள் எதினாலே அறிவீர்களென்றால்,", "en": "And Moses said, Hereby ye shall know that the LORD hath sent me to do all these works; for I have not done them of mine own mind."}, {"verse": 29, "start": 357.78, "end": 369.26, "ta": "சகல மனிதரும் சாகிறபடி இவர்கள் செத்து, சகல மனிதருக்கும் நேரிடுகிறதுபோல இவர்களுக்கும் நேரிட்டால், கர்த்தர் என்னை அனுப்பவில்லை என்று அறிவீர்கள்.", "en": "If these men die the common death of all men, or if they be visited after the visitation of all men; then the LORD hath not sent me."}, {"verse": 30, "start": 369.26, "end": 388.98, "ta": "கர்த்தர் ஒரு புதிய காரியத்தை நேரிடச்செய்வதால், பூமி தன் வாயைத் திறந்து, இவர்கள் உயிரோடே பாதாளத்தில் இறங்கத்தக்கதாக இவர்களையும் இவர்களுக்கு உண்டான யாவையும் விழுங்கிப்போட்டதேயானால், இந்த மனிதர் கர்த்தரை அவமதித்தார்கள் என்பதை அறிந்துகொள்வீர்கள் என்றான்.", "en": "But if the LORD make a new thing, and the earth open her mouth, and swallow them up, with all that appertain unto them, and they go down quick into the pit; then ye shall understand that these men have provoked the LORD ."}, {"verse": 31, "start": 388.98, "end": 395.97, "ta": "அவன் இந்த வார்த்தைகளையெல்லாம் சொல்லி முடித்தவுடனே, அவர்கள் நின்றிருந்த நிலம் பிளந்தது;", "en": "And it came to pass, as he had made an end of speaking all these words, that the ground clave asunder that was under them:"}, {"verse": 32, "start": 395.97, "end": 407.97, "ta": "பூமி தன் வாயைத் திறந்து, அவர்களையும் அவர்கள் வீடுகளையும், கோராகுக்குரிய எல்லா மனிதரையும், அவர்களுக்கு உண்டான சகல பொருள்களையும் விழுங்கிப்போட்டது.", "en": "And the earth opened her mouth, and swallowed them up, and their houses, and all the men that appertained unto Korah, and all their goods."}, {"verse": 33, "start": 407.97, "end": 420.85, "ta": "அவர்கள் தங்களுக்கு உண்டானவை எல்லாவற்றோடும் உயிரோடே பாதாளத்தில் இறங்கினார்கள்; பூமி அவர்களை மூடிக்கொண்டது; இப்படிச் சபையின் நடுவிலிருந்து அழிந்துபோனார்கள்.", "en": "They, and all that appertained to them, went down alive into the pit, and the earth closed upon them: and they perished from among the congregation."}, {"verse": 34, "start": 420.85, "end": 431.22, "ta": "அவர்களைச் சுற்றிலும் இருந்த இஸ்ரவேலர் யாவரும் அவர்கள் கூக்குரலைக்கேட்டு, பூமி நம்மையும் விழுங்கிப்போடும் என்று சொல்லி ஓடினார்கள்.", "en": "And all Israel that were round about them fled at the cry of them: for they said, Lest the earth swallow us up also ."}, {"verse": 35, "start": 431.22, "end": 440.06, "ta": "அக்கினி கர்த்தருடைய சந்நிதியிலிருந்து புறப்பட்டு, தூபங்காட்டின இருநூற்று ஐம்பது பேரையும் பட்சித்துப்போட்டது.", "en": "And there came out a fire from the LORD , and consumed the two hundred and fifty men that offered incense."}, {"verse": 36, "start": 440.06, "end": 442.26, "ta": "பின்பு கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 37, "start": 442.26, "end": 456.76, "ta": "அக்கினிக்குள் அகப்பட்ட தூபகலசங்களை எடுத்து, அவைகளிலிருக்கிற அக்கினியை அப்பாலே கொட்டிப்போடும்படி ஆசாரியனாகிய ஆரோனின் குமாரன் எலெயாசாருக்குச் சொல்; அந்தத் தூபகலசங்கள் பரிசுத்தமாயின.", "en": "Speak unto Eleazar the son of Aaron the priest, that he take up the censers out of the burning, and scatter thou the fire yonder; for they are hallowed."}, {"verse": 38, "start": 456.76, "end": 478.03, "ta": "தங்கள் ஆத்துமாக்களுக்கே கேடுண்டாக்கின அந்தப் பாவிகளின் தூபகலசங்களைப் பலிபீடத்தை மூடத்தக்க தட்டையான தகடுகளாய் அடிக்கக்கடவர்கள்; அவர்கள் கர்த்தருடைய சந்நிதியில் அவைகளைக் கொண்டுவந்ததினால் அவைகள் பரிசுத்தமாயின; அவைகள் இஸ்ரவேல் புத்திரருக்கு ஒரு அடையாளமாயிருக்கும் என்றார்.", "en": "The censers of these sinners against their own souls, let them make them broad plates for a covering of the altar: for they offered them before the LORD , therefore they are hallowed: and they shall be a sign unto the children of Israel."}, {"verse": 39, "start": 478.03, "end": 485.68, "ta": "அப்படியே ஆசாரியனாகிய எலெயாசார் சுட்டெரிக்கப்பட்டவர்கள் கொண்டுவந்திருந்த வெண்கலத் தூபகலசங்களை எடுத்து,", "en": "And Eleazar the priest took the brasen censers, wherewith they that were burnt had offered; and they were made broad plates for a covering of the altar:"}, {"verse": 40, "start": 485.68, "end": 508.86, "ta": "ஆரோனின் புத்திரராய் இராத அந்நியன் ஒருவனும் கர்த்தருடைய சந்நிதியில் தூபங்காட்ட வராதபடிக்கும், கோராகைப்போலும் அவன் கூட்டத்தாரைப்போலும் இராதபடிக்கும், இஸ்ரவேல் புத்திரருக்கு ஞாபகக்குறியாயிருக்கும்பொருட்டு, கர்த்தர் மோசேயைக்கொண்டு தனக்குச் சொன்னபடியே அவைகளைப் பலிபீடத்தை மூடும் தகடுகளாக அடிப்பித்தான்.", "en": "To be a memorial unto the children of Israel, that no stranger, which is not of the seed of Aaron, come near to offer incense before the LORD ; that he be not as Korah, and as his company: as the LORD said to him by the hand of Moses."}, {"verse": 41, "start": 508.86, "end": 520.79, "ta": "மறுநாளில் இஸ்ரவேல் புத்திரரின் சபையார் எல்லாரும் மோசேக்கும் ஆரோனுக்கும் விரோதமாக முறுமுறுத்து: நீங்கள் கர்த்தரின் ஜனங்களைக் கொன்றுபோட்டீர்கள் என்றார்கள்.", "en": "But on the morrow all the congregation of the children of Israel murmured against Moses and against Aaron, saying, Ye have killed the people of the LORD ."}, {"verse": 42, "start": 520.79, "end": 532.19, "ta": "சபையார் மோசேக்கும் ஆரோனுக்கும் விரோதமாகக் கூடி ஆசரிப்புக் கூடாரத்துக்கு நேரே பார்க்கிறபோது, மேகம் அதை மூடினது, கர்த்தரின் மகிமை காணப்பட்டது.", "en": "And it came to pass, when the congregation was gathered against Moses and against Aaron, that they looked toward the tabernacle of the congregation: and, behold, the cloud covered it, and the glory of the LORD appeared."}, {"verse": 43, "start": 532.19, "end": 537.34, "ta": "மோசேயும் ஆரோனும் ஆசரிப்புக் கூடாரத்துக்கு முன்பாக வந்தார்கள்.", "en": "And Moses and Aaron came before the tabernacle of the congregation."}, {"verse": 44, "start": 537.34, "end": 539.77, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 45, "start": 539.77, "end": 550.08, "ta": "இந்தச் சபையாரை விட்டு விலகிப்போங்கள்; ஒரு நிமிஷத்தில் அவர்களை அதமாக்குவேன் என்றார்; அவர்கள் முகங்குப்புற விழுந்தார்கள்.", "en": "Get you up from among this congregation, that I may consume them as in a moment. And they fell upon their faces."}, {"verse": 46, "start": 550.08, "end": 571.71, "ta": "மோசே ஆரோனை நோக்கி: நீ தூபகலசத்தை எடுத்து, பலிபீடத்திலிருக்கிற அக்கினியை அதில் போட்டு, அதின்மேல் தூபவர்க்கம் இட்டு, சீக்கிரமாய்ச் சபையினிடத்தில் போய், அவர்களுக்காகப் பாவநிவிர்த்தி செய்; கர்த்தருடைய சந்நிதியிலிருந்து கடுங்கோபம் புறப்பட்டது, வாதை தொடங்கிற்று என்றான்.", "en": "And Moses said unto Aaron, Take a censer, and put fire therein from off the altar, and put on incense, and go quickly unto the congregation, and make an atonement for them: for there is wrath gone out from the LORD ; the plague is begun."}, {"verse": 47, "start": 571.71, "end": 585.18, "ta": "மோசே சொன்னபடி ஆரோன் அதை எடுத்துக்கொண்டு சபையின் நடுவில் ஓடினான்; ஜனங்களுக்குள்ளே வாதை தொடங்கியிருந்தது; அவன் தூபவர்க்கம் போட்டு, ஜனங்களுக்காகப் பாவநிவிர்த்தி செய்து,", "en": "And Aaron took as Moses commanded, and ran into the midst of the congregation; and, behold, the plague was begun among the people: and he put on incense, and made an atonement for the people."}, {"verse": 48, "start": 585.18, "end": 593.05, "ta": "செத்தவர்களுக்கும் உயிரோடிருக்கிறவர்களுக்கும் நடுவே நின்றான்; அப்பொழுது வாதை நிறுத்தப்பட்டது.", "en": "And he stood between the dead and the living; and the plague was stayed."}, {"verse": 49, "start": 593.05, "end": 601.81, "ta": "கோராகின் காரியத்தினிமித்தம் செத்தவர்கள் தவிர, அந்த வாதையினால் செத்துப்போனவர்கள் பதினாலாயிரத்து எழுநூறுபேர்.", "en": "Now they that died in the plague were fourteen thousand and seven hundred, beside them that died about the matter of Korah."}, {"verse": 50, "start": 601.81, "end": 609.98, "ta": "வாதை நிறுத்தப்பட்டது; அப்பொழுது ஆரோன் ஆசரிப்புக் கூடாரவாசலுக்கு மோசேயினிடத்தில் திரும்பிவந்தான்.", "en": "And Aaron returned unto Moses unto the door of the tabernacle of the congregation: and the plague was stayed."}]}, "17": {"chapter": 17, "duration": 152.71, "audio_url": "audio_ot/OT04_17.mp3", "total_verses": 13, "verses": [{"verse": 1, "start": 3.8, "end": 5.96, "ta": "பின்பு கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.96, "end": 20.24, "ta": "நீ இஸ்ரவேல் புத்திரரோடே பேசி, அவர்கள் பிதாக்களின் வம்சங்களாகிய ஒவ்வொரு வம்சத்தினுடைய பிரபுவினிடத்தில், ஒவ்வொரு கோலாகப் பன்னிரண்டு கோலை வாங்கி, அவனவன் கோலில் அவனவன் பேரை எழுதுவாயாக.", "en": "Speak unto the children of Israel, and take of every one of them a rod according to the house of their fathers, of all their princes according to the house of their fathers twelve rods: write thou every man’s name upon his rod."}, {"verse": 3, "start": 20.24, "end": 30.77, "ta": "லேவியினுடைய கோலின்மேல் ஆரோனின் பேரை எழுதக்கடவாய்; அவர்களுடைய பிதாக்களின் ஒவ்வொரு வம்சத்தலைவனுக்காகவும் ஒவ்வொரு கோல் இருக்கவேண்டும்.", "en": "And thou shalt write Aaron’s name upon the rod of Levi: for one rod shall be for the head of the house of their fathers."}, {"verse": 4, "start": 30.77, "end": 39.14, "ta": "அவைகளை ஆசரிப்புக் கூடாரத்திலே நான் உங்களைச் சந்திக்கும் ஸ்தானமாகிய சாட்சிப்பெட்டிக்கு முன்னே வைக்கக்கடவாய்.", "en": "And thou shalt lay them up in the tabernacle of the congregation before the testimony, where I will meet with you."}, {"verse": 5, "start": 39.14, "end": 52.91, "ta": "அப்பொழுது நான் தெரிந்துகொள்ளுகிறவனுடைய கோல் துளிர்க்கும்; இப்படி இஸ்ரவேல் புத்திரர் உங்களுக்கு விரோதமாய் முறுமுறுக்கிற அவர்கள் முறுமுறுப்பை என்னைவிட்டு ஒழியப்பண்ணுவேன் என்றார்.", "en": "And it shall come to pass, that the man’s rod, whom I shall choose, shall blossom: and I will make to cease from me the murmurings of the children of Israel, whereby they murmur against you."}, {"verse": 6, "start": 52.91, "end": 72.1, "ta": "இதை மோசே இஸ்ரவேல் புத்திரரோடே சொன்னான்; அப்பொழுது அவர்களுடைய பிரபுக்கள் எல்லாரும் தங்கள் பிதாக்களுடைய வம்சத்தின்படி ஒε்வெξரு பοரபுவுக்கு ஒவ்வொரு கோலாகப் பன்னிரண்டு கோல்களை அவனிடத்தில் கொடுத்தார்கள்; ஆரோனின் கோலும் அவர்களுடைய கோல்களுடனே இருந்தது.", "en": "And Moses spake unto the children of Israel, and every one of their princes gave him a rod apiece, for each prince one, according to their fathers’ houses, even twelve rods: and the rod of Aaron was among their rods."}, {"verse": 7, "start": 72.1, "end": 78.15, "ta": "அந்தக் கோல்களை மோசே சாட்சியின் கூடாரத்திலே கர்த்தருடைய சமுகத்தில் வைத்தான்.", "en": "And Moses laid up the rods before the LORD in the tabernacle of witness."}, {"verse": 8, "start": 78.15, "end": 93.44, "ta": "மறுநாள் மோசே சாட்சியின் கூடாரத்துக்குள் பிரவேசித்தபோது, இதோ, லேவியின் குடும்பத்தாருக்கு இருந்த ஆரோனின் கோல் துளிர்த்திருந்தது; அது துளிர்விட்டு, பூப்பூத்து, வாதுமைப்பழங்களைக் கொடுத்தது.", "en": "And it came to pass, that on the morrow Moses went into the tabernacle of witness; and, behold, the rod of Aaron for the house of Levi was budded, and brought forth buds, and bloomed blossoms, and yielded almonds."}, {"verse": 9, "start": 93.44, "end": 108.95, "ta": "அப்பொழுது மோசே கர்த்தருடைய சமுகத்திலிருந்த அந்தக் கோல்களையெல்லாம் எடுத்து, இஸ்ரவேல் புத்திரர் எல்லாரும் காண வெளியே கொண்டுவந்தான்; அவர்கள் கண்டு, அவரவர் தங்கள் தங்கள் கோல்களை வாங்கிக்கொண்டார்கள்.", "en": "And Moses brought out all the rods from before the LORD unto all the children of Israel: and they looked, and took every man his rod."}, {"verse": 10, "start": 108.95, "end": 129.43, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி: ஆரோனின் கோல் அந்தக் கலகக்காரருக்கு விரோதமான அடையாளமாகும்பொருட்டு, அதைத் திரும்பவும் சாட்சிப்பெட்டிக்கு முன்னே கொண்டுபோய் வை; இப்படி அவர்கள் எனக்கு விரோதமாய் முறுமுறுப்பதை ஒழியப்பண்ணுவாய், அப்பொழுது அவர்கள் சாகமாட்டார்கள் என்றார்.", "en": "And the LORD said unto Moses, Bring Aaron’s rod again before the testimony, to be kept for a token against the rebels; and thou shalt quite take away their murmurings from me, that they die not."}, {"verse": 11, "start": 129.43, "end": 133.61, "ta": "கர்த்தர் தனக்குக் கட்டளையிட்டபடியே மோசே செய்தான்.", "en": "And Moses did so: as the LORD commanded him, so did he."}, {"verse": 12, "start": 133.61, "end": 142.63, "ta": "அப்பொழுது இஸ்ரவேல் புத்திரர் மோசேயை நோக்கி: இதோ, செத்து அழிந்துபோகிறோம்; நாங்கள் எல்லாரும் அழிந்துபோகிறோம்.", "en": "And the children of Israel spake unto Moses, saying, Behold, we die, we perish, we all perish."}, {"verse": 13, "start": 142.63, "end": 151.21, "ta": "கர்த்தரின் வாசஸ்தலத்தின் கிட்டேவருகிற எவனும் சாகிறான்; நாங்கள் எல்லாரும் செத்துத்தான் தீருமோ என்றார்கள்.", "en": "Whosoever cometh any thing near unto the tabernacle of the LORD shall die: shall we be consumed with dying?"}]}, "18": {"chapter": 18, "duration": 465.75, "audio_url": "audio_ot/OT04_18.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 21.5, "ta": "பின்பு கர்த்தர் ஆரோனை நோக்கி: நீயும் உன்னோடேகூட உன் குமாரரும் உன் தகப்பன் வம்சத்தாரும் பரிசுத்த ஸ்தலத்தைப்பற்றிய அக்கிரமத்தைச் சுமக்கவேண்டும்; நீயும் உன்னோடேகூட உன் குமாரரும் உங்கள் ஆசாரிய ஊழியத்தைப்பற்றிய அக்கிரமத்தைச் சுமக்கவேண்டும்.", "en": "And the LORD said unto Aaron, Thou and thy sons and thy father’s house with thee shall bear the iniquity of the sanctuary: and thou and thy sons with thee shall bear the iniquity of your priesthood."}, {"verse": 2, "start": 21.5, "end": 37.0, "ta": "உன் தகப்பனாகிய லேவியின் கோத்திரத்தாரான உன் சகோதரரையும் உன்னோடே கூடியிருக்கவும் உன்னிடத்திலே சேவிக்கவும் அவர்களைச் சேர்த்துக்கொள்; நீயும் உன் குமாரருமோ சாட்சியின் கூடாரத்துக்குமுன் ஊழியம் செய்யக்கடவீர்கள்.", "en": "And thy brethren also of the tribe of Levi, the tribe of thy father, bring thou with thee, that they may be joined unto thee, and minister unto thee: but thou and thy sons with thee shall minister before the tabernacle of witness."}, {"verse": 3, "start": 37.0, "end": 51.08, "ta": "அவர்கள் உன் காவலையும் கூடாரம் அனைத்தின் காவலையும் காக்கக்கடவர்கள்; ஆகிலும் அவர்களும் நீங்களும் சாகாதபடிக்கு, அவர்கள் பரிசுத்த ஸ்தலத்தின் பணிமுட்டுகளண்டையிலும் பலிபீடத்தண்டையிலும் சேராமல்,", "en": "And they shall keep thy charge, and the charge of all the tabernacle: only they shall not come nigh the vessels of the sanctuary and the altar, that neither they, nor ye also, die."}, {"verse": 4, "start": 51.08, "end": 63.97, "ta": "உன்னோடே கூடிக்கொண்டு, கூடாரத்துக்கடுத்த எல்லாப் பணிவிடையையும் செய்ய, ஆசரிப்புக் கூடாரத்தின் காவலைக்காக்கக்கடவர்கள்; அந்நியன் ஒருவனும் உங்களிடத்தில் சேரக் கூடாது.", "en": "And they shall be joined unto thee, and keep the charge of the tabernacle of the congregation, for all the service of the tabernacle: and a stranger shall not come nigh unto you."}, {"verse": 5, "start": 63.97, "end": 74.09, "ta": "இஸ்ரவேல் புத்திரர்மேல் இனிக் கடுங்கோபம் வராதபடிக்கு, நீங்கள் பரிசுத்த ஸ்தலத்தின் காவலையும் பலிபீடத்தின் காவலையும் காக்கக்கடவீர்கள்.", "en": "And ye shall keep the charge of the sanctuary, and the charge of the altar: that there be no wrath any more upon the children of Israel."}, {"verse": 6, "start": 74.09, "end": 87.4, "ta": "ஆசரிப்புக் கூடாரத்தின் பணிவிடையைச் செய்ய, கர்த்தருக்குக் கொடுக்கப்பட்ட உங்கள் சகோதரராகிய லேவியரை நான் இஸ்ரவேல் புத்திரரிலிருந்து பிரித்து, உங்களுக்குத் தத்தமாகக் கொடுத்தேன்.", "en": "And I, behold, I have taken your brethren the Levites from among the children of Israel: to you they are given as a gift for the LORD , to do the service of the tabernacle of the congregation."}, {"verse": 7, "start": 87.4, "end": 109.83, "ta": "ஆகையால் நீயும் உன்னோடேகூட உன் குமாரரும் பலிபீடத்துக்கும் திரைக்கு உட்புறத்துக்கும் அடுத்த எல்லாவற்றையும் செய்யும்பொருட்டு, உங்கள் ஆசாரிய ஊழியத்தைக் காத்துச் சேவிக்கக்கடவீர்கள்; உங்கள் ஆசாரிய ஊழியத்தை உங்களுக்கு தத்தமாக அருளினேன்; அதைச்செய்யும்படி சேருகிற அந்நியன் கொலைசெய்யப்படக்கடவன் என்றார்.", "en": "Therefore thou and thy sons with thee shall keep your priest’s office for every thing of the altar, and within the vail; and ye shall serve: I have given your priest’s office unto you as a service of gift: and the stranger that cometh nigh shall be put to death."}, {"verse": 8, "start": 109.83, "end": 130.36, "ta": "பின்னும் கர்த்தர் ஆரோனை நோக்கி: இஸ்ரவேல் புத்திரர் பரிசுத்தப்படுத்துகிறவைகளிலெல்லாம் எனக்கு ஏறெடுத்துப்படைக்கப்படும் படைப்புகளைக் காத்துக்கொண்டிருக்கிறீர்களே, அவைகளை உனக்குக் கொடுத்தேன்; அபிஷேகத்தினிமித்தம் அவைகளை உனக்கும் உன் குமாரருக்கும் நித்திய கட்டளையாகக் கொடுத்தேன்.", "en": "And the LORD spake unto Aaron, Behold, I also have given thee the charge of mine heave offerings of all the hallowed things of the children of Israel; unto thee have I given them by reason of the anointing, and to thy sons, by an ordinance for ever."}, {"verse": 9, "start": 130.36, "end": 150.25, "ta": "மகா பரிசுத்தமானவைகளிலே, அக்கினிக்கு உட்படுத்தப்படாமல் உன்னுடையதாயிருப்பது எவையெனில், அவர்கள் எனக்குப் படைக்கும் எல்லாப் படைப்பும், எல்லாப் போஜனபலியும், எல்லாப் பாவநிவாரணபலியும், எல்லாக் குற்றநிவாரணபலியும், உனக்கும் உன் குமாரருக்கும் பரிசுத்தமாயிருக்கும்.", "en": "This shall be thine of the most holy things, reserved from the fire: every oblation of theirs, every meat offering of theirs, and every sin offering of theirs, and every trespass offering of theirs, which they shall render unto me, shall be most holy for thee and for thy sons."}, {"verse": 10, "start": 150.25, "end": 160.45, "ta": "பரிசுத்த ஸ்தலத்திலே அவைகளைப் புசிக்கவேண்டும்; ஆண்மக்கள் யாவரும் அவைகளைப் புசிக்கலாம்; அவைகள் உனக்குப் பரிசுத்தமாயிருப்பதாக.", "en": "In the most holy place shalt thou eat it; every male shall eat it: it shall be holy unto thee."}, {"verse": 11, "start": 160.45, "end": 181.54, "ta": "இஸ்ரவேல் புத்திரர் ஏறெடுத்துப்டைக்கிறதும் அசைவாட்டுகிறதுமான அவர்களுடைய எல்லாக் காணிக்கைகளின் படைப்பும் உன்னுடையவைகளாயிருக்கும். அவைகளை உனக்கும் உன் குமாரருக்கும் உன் குமாரத்திகளுக்கும் நித்திய நியமமாகக் கொடுத்தேன்; உன் வீட்டிலே சுத்தமானவர்கள் எல்லாரும் அவைகளைப் புசிக்கலாம்.", "en": "And this is thine; the heave offering of their gift, with all the wave offerings of the children of Israel: I have given them unto thee, and to thy sons and to thy daughters with thee, by a statute for ever: every one that is clean in thy house shall eat of it."}, {"verse": 12, "start": 181.54, "end": 193.57, "ta": "அவர்கள் கர்த்தருக்குக் கொடுக்கும் அவர்களுடைய முதற்பலன்களாகிய உச்சிதமான எண்ணெயையும், உச்சிதமான திராட்சரசத்தையும், தானியத்தையும் உனக்கு உரியதாகக் கொடுத்தேன்.", "en": "All the best of the oil, and all the best of the wine, and of the wheat, the firstfruits of them which they shall offer unto the LORD , them have I given thee."}, {"verse": 13, "start": 193.57, "end": 206.03, "ta": "தங்கள் தேசத்தில் முதற்பழுத்த பலனில் அவர்கள் கர்த்தருக்குக் கொண்டு வருவதெல்லாம் உனக்கு உரியதாகும்; உன் வீட்டிலே சுத்தமாயிருப்பவர்கள் யாவரும் அவைகளைப் புசிக்கலாம்.", "en": "And whatsoever is first ripe in the land, which they shall bring unto the LORD , shall be thine; every one that is clean in thine house shall eat of it."}, {"verse": 14, "start": 206.03, "end": 211.9, "ta": "இஸ்ரவேலிலே சாபத்தீடாக நேர்ந்துகொள்ளப்பட்டதெல்லாம் உனக்கு உரியதாயிருக்கும்.", "en": "Every thing devoted in Israel shall be thine."}, {"verse": 15, "start": 211.9, "end": 230.88, "ta": "மனிதரிலும் மிருகங்களிலும் அவர்கள் கர்த்தருக்குச் செலுத்தும் சமஸ்த பிராணிகளுக்குள்ளே கர்ப்பந்திறந்து பிறக்கும் யாவும் உனக்கு உரியதாயிருக்கும்; ஆனாலும் மனிதரின் முதற்பேற்றை அகத்தியமாய் மீட்கவேண்டும்; தீட்டான மிருகஜீவனின் தலையீற்றையும் மீட்கவேண்டும்.", "en": "Every thing that openeth the matrix in all flesh, which they bring unto the LORD , whether it be of men or beasts, shall be thine: nevertheless the firstborn of man shalt thou surely redeem, and the firstling of unclean beasts shalt thou redeem."}, {"verse": 16, "start": 230.88, "end": 244.82, "ta": "மீட்கவேண்டியவைகள் ஒரு மாதத்திற்கு மேற்பட்டதனால், உன் மதிப்புக்கு இசைய பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்கின்படி ஐந்து சேக்கல் பணத்தாலே அவைகளை மீட்கவேண்டும்; ஒரு சேக்கல் இருபது கேரா.", "en": "And those that are to be redeemed from a month old shalt thou redeem, according to thine estimation, for the money of five shekels, after the shekel of the sanctuary, which is twenty gerahs."}, {"verse": 17, "start": 244.82, "end": 264.21, "ta": "மாட்டின் தலையீற்றும், செம்மறியாட்டின் தலையீற்றும், வெள்ளாட்டின் தலையீற்றுமோ மீட்கப்படவேண்டாம்; அவைகள் பரிசுத்தமானவைகள்; அவைகளின் இரத்தத்தைப் பலிபீடத்தின்மேல் தெளித்து, அவைகளின் கொழுப்பைக் கர்த்தருக்குச் சுகந்த வாசனையான தகனமாகத் தகனிக்கவேண்டும்.", "en": "But the firstling of a cow, or the firstling of a sheep, or the firstling of a goat, thou shalt not redeem; they are holy: thou shalt sprinkle their blood upon the altar, and shalt burn their fat for an offering made by fire, for a sweet savour unto the LORD ."}, {"verse": 18, "start": 264.21, "end": 271.65, "ta": "அசைவாட்டும் மார்க்கண்டத்தைப்போலும் வலது முன்னந்தொடையைப்போலும் அவைகளின் மாம்சமும் உன்னுடையதாகும்.", "en": "And the flesh of them shall be thine, as the wave breast and as the right shoulder are thine."}, {"verse": 19, "start": 271.65, "end": 291.4, "ta": "இஸ்ரவேல் புத்திரர் கர்த்தருக்கு ஏறெடுத்துப் படைக்கிற பரிசுத்த படைப்புகளையெல்லாம் உனக்கும் உன் குமாரருக்கும் உன் குமாரத்திகளுக்கும் நித்திய கட்டளையாகக் கொடுத்தேன்; கர்த்தருடைய சந்நிதியில் இது உனக்கும் உன் சந்ததிக்கும் என்றைக்கும் செல்லும் மாறாத உடன்படிக்கை என்றார்.", "en": "All the heave offerings of the holy things, which the children of Israel offer unto the LORD , have I given thee, and thy sons and thy daughters with thee, by a statute for ever: it is a covenant of salt for ever before the LORD unto thee and to thy seed with thee."}, {"verse": 20, "start": 291.4, "end": 308.6, "ta": "பின்னும் கர்த்தர் ஆரோனை நோக்கி: அவர்களுடைய தேசத்தில் நீ ஒன்றையும் சுதந்தரித்துக்கொள்ளவேண்டாம், அவர்கள் நடுவே உனக்குப் பங்கு உண்டாயிருக்கவும் வேண்டாம்; இஸ்ரவேல் புத்திரர் நடுவில் நானே உன் பங்கும் உன் சுதந்தரமுமாய் இருக்கிறேன்.", "en": "And the LORD spake unto Aaron, Thou shalt have no inheritance in their land, neither shalt thou have any part among them: I am thy part and thine inheritance among the children of Israel."}, {"verse": 21, "start": 308.6, "end": 321.83, "ta": "இதோ, லேவியின் புத்திரர் ஆசரிப்புக் கூடாரத்தின் பணிவிடையைச் செய்கிற அவர்களுடைய வேலைக்காக, இஸ்ரவேலருக்குள்ளவை எல்லாவற்றிலும் தசமபாகத்தை அவர்களுக்குச் சுதந்தரமாகக் கொடுத்தேன்.", "en": "And, behold, I have given the children of Levi all the tenth in Israel for an inheritance, for their service which they serve, even the service of the tabernacle of the congregation."}, {"verse": 22, "start": 321.83, "end": 329.69, "ta": "இஸ்ரவேல் புத்திரர் குற்றஞ்சுமந்து சாகாதபடிக்கு, இனி ஆசரிப்புக் கூடாரத்தைக் கிட்டாதிருக்கக்கடவர்கள்.", "en": "Neither must the children of Israel henceforth come nigh the tabernacle of the congregation, lest they bear sin, and die."}, {"verse": 23, "start": 329.69, "end": 347.03, "ta": "லேவியர்மாத்திரம் ஆசரிப்புக் கூடாரத்துக்கடுத்த வேலைகளைச் செய்யவேண்டும்; அவர்கள் தங்கள் அக்கிரமத்தைச் சுமப்பார்கள்; இஸ்ரவேல் புத்திரர் நடுவே அவர்களுக்குச் சுதந்தரம் இல்லை என்பது உங்கள் தலைமுறைதோறும் நித்திய கட்டளையாயிருக்கும்.", "en": "But the Levites shall do the service of the tabernacle of the congregation, and they shall bear their iniquity: it shall be a statute for ever throughout your generations, that among the children of Israel they have no inheritance."}, {"verse": 24, "start": 347.03, "end": 363.31, "ta": "இஸ்ரவேல் புத்திரர் கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் படைப்பாகிய தசமபாகத்தை லேவியருக்குச் சுதந்தரமாகக் கொடுத்தேன்; ஆகையால் இஸ்ரவேல் புத்திரரின் நடுவே அவர்களுக்குச் சுதந்தரமில்லையென்று அவர்களுக்குச் சொன்னேன் என்றார்.", "en": "But the tithes of the children of Israel, which they offer as an heave offering unto the LORD , I have given to the Levites to inherit: therefore I have said unto them, Among the children of Israel they shall have no inheritance."}, {"verse": 25, "start": 363.31, "end": 365.58, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 26, "start": 365.58, "end": 385.47, "ta": "நீ லேவியரோடே சொல்லவேண்டியது என்னவென்றால்: இஸ்ரவேல் புத்திரர் கையில் வாங்கிக்கொள்ளும்படி நான் உங்களுக்குச் சுதந்தரமாகக் கொடுத்த தசமபாகத்தை நீங்கள் அவர்கள் கையில் வாங்கும்போது, தசமபாகத்தில் பத்தில் ஒரு பங்கைக் கர்த்தருக்கு ஏறெடுத்துப்படைக்கும் படைப்பாகச் செலுத்தவேண்டும்.", "en": "Thus speak unto the Levites, and say unto them, When ye take of the children of Israel the tithes which I have given you from them for your inheritance, then ye shall offer up an heave offering of it for the LORD , even a tenth part of the tithe."}, {"verse": 27, "start": 385.47, "end": 394.81, "ta": "நீங்கள் ஏறெடுத்துப் படைக்கும் இந்தப் படைப்பு களத்தின் தானியத்தைப்போலும், ஆலையின் இரசத்தைப்போலும் உங்களுக்கு எண்ணப்படும்.", "en": "And this your heave offering shall be reckoned unto you, as though it were the corn of the threshingfloor, and as the fulness of the winepress."}, {"verse": 28, "start": 394.81, "end": 410.17, "ta": "இப்படியே நீங்கள் இஸ்ரவேல் புத்திரர் கையில் வாங்கும் தசமபாகமாகிய உங்கள் பங்குகளிலெல்லாம் நீங்களும் கர்த்தருக்கு என்று ஒரு படைப்பை ஏறெடுத்துப் படைத்து, அந்தப் படைப்பை ஆசாரியனாகிய ஆரோனுக்குக் கொடுக்கவேண்டும்.", "en": "Thus ye also shall offer an heave offering unto the LORD of all your tithes, which ye receive of the children of Israel; and ye shall give thereof the LORD’s heave offering to Aaron the priest."}, {"verse": 29, "start": 410.17, "end": 421.43, "ta": "உங்களுக்குக் கொடுக்கப்படுகிற ஒவ்வொரு காணிக்கையிலுமுள்ள உச்சிதமான பரிசுத்த பங்கையெல்லாம் கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் படைப்பாகச் செலுத்தவேண்டும்.", "en": "Out of all your gifts ye shall offer every heave offering of the LORD , of all the best thereof, even the hallowed part thereof out of it."}, {"verse": 30, "start": 421.43, "end": 436.72, "ta": "ஆதலால் நீ அவர்களோடே சொல்லவேண்டியது என்னவென்றால்: அதில் உச்சிதமானதை நீங்கள் ஏறெடுத்துப் படைக்கும்போது, அது களத்தின் வரத்திலும் ஆலையின் வரத்திலும் இருந்து எடுத்துச் செலுத்துகிறதுபோல லேவியருக்கு எண்ணப்படும்.", "en": "Therefore thou shalt say unto them, When ye have heaved the best thereof from it, then it shall be counted unto the Levites as the increase of the threshingfloor, and as the increase of the winepress."}, {"verse": 31, "start": 436.72, "end": 447.76, "ta": "அதை நீங்களும் உங்கள் குடும்பத்தாரும் எவ்விடத்திலும் புசிக்கலாம்; அது நீங்கள் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடைக்கு ஈடான உங்கள் சம்பளம்.", "en": "And ye shall eat it in every place, ye and your households: for it is your reward for your service in the tabernacle of the congregation."}, {"verse": 32, "start": 447.76, "end": 464.25, "ta": "இப்படி அதில் உச்சிதமானதை ஏறெடுத்துப் படைத்தீர்களானால், நீங்கள் அதினிமித்தம் பாவம் சுமக்கமாட்டீர்கள்; நீங்கள் சாகாதிருக்கும்படிக்கு, இஸ்ரவேல் புத்திரரின் பரிசுத்தமானவைகளைத் தீட்டுப்படுத்தலாகாது என்று சொல் என்றார்.", "en": "And ye shall bear no sin by reason of it, when ye have heaved from it the best of it: neither shall ye pollute the holy things of the children of Israel, lest ye die."}]}, "19": {"chapter": 19, "duration": 294.1, "audio_url": "audio_ot/OT04_19.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 6.46, "ta": "கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 2, "start": 6.46, "end": 19.93, "ta": "கர்த்தர் கற்பித்த நியமப்பிரமாணமாவது: பழுதற்றதும் ஊனமில்லாததும் நுகத்தடிக்கு உட்படாததுமாகிய சிவப்பான ஒரு கிடாரியை உன்னிடத்தில் கொண்டுவரும்படி இஸ்ரவேல் புத்திரருக்குச் சொல்லுங்கள்.", "en": "This is the ordinance of the law which the LORD hath commanded, saying, Speak unto the children of Israel, that they bring thee a red heifer without spot, wherein is no blemish, and upon which never came yoke:"}, {"verse": 3, "start": 19.93, "end": 32.32, "ta": "அதை எலெயாசார் என்னும் ஆசாரியனிடத்தில் ஒப்புக்கொடுங்கள்; அவன் அதைப் பாளயத்துக்கு வெளியே கொண்டுபோகக்கடவன்; அங்கே அது அவனுக்கு முன்பாகக் கொல்லப்படக்கடவது.", "en": "And ye shall give her unto Eleazar the priest, that he may bring her forth without the camp, and one shall slay her before his face:"}, {"verse": 4, "start": 32.32, "end": 42.91, "ta": "அப்பொழுது ஆசாரியனξகிய Πβெயξசார͠தன் வߠΰலߠΩாலύ அதοΩ் இΰத்ĠΤ்தில் கொஞ்சம் எடுத்து, ஆசரிப்புக் கூடாரத்துக்கு எதிராக ஏழுதரம் தெளிக்கக்கடவன்.", "en": "And Eleazar the priest shall take of her blood with his finger, and sprinkle of her blood directly before the tabernacle of the congregation seven times:"}, {"verse": 5, "start": 42.91, "end": 54.93, "ta": "பின்பு கிடாரியை அவன் கண்களுக்கு முன்பாக ஒருவன் சுட்டெரிக்கவேண்டும்; அதின் தோலும் அதின் மாம்சமும் அதின் இரத்தமும் அதின் சாணியும் சுட்டெரிக்கப்படவேண்டும்.", "en": "And one shall burn the heifer in his sight; her skin, and her flesh, and her blood, with her dung, shall he burn:"}, {"verse": 6, "start": 54.93, "end": 65.02, "ta": "அப்பொழுது ஆசாரியன் கேதுருக்கட்டையையும் ஈசோப்பையும் சிவப்புநூலையும் எடுத்து, கிடாரி எரிக்கப்படுகிற நெருப்பின் நடுவிலே போடக்கடவன்.", "en": "And the priest shall take cedar wood, and hyssop, and scarlet, and cast it into the midst of the burning of the heifer."}, {"verse": 7, "start": 65.02, "end": 77.76, "ta": "பின்பு ஆசாரியன் தன் வஸ்திரங்களைத் தோய்த்து, ஜலத்திலே ஸ்நானம்பண்ணி, அதின்பின்பு பாளயத்தில் பிரவேசிக்கக்கடவன்; ஆசாரியன் சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்.", "en": "Then the priest shall wash his clothes, and he shall bathe his flesh in water, and afterward he shall come into the camp, and the priest shall be unclean until the even."}, {"verse": 8, "start": 77.76, "end": 87.42, "ta": "அதைச் சுட்டெரித்தவனும் தன் வஸ்திரங்களை ஜலத்தில் தோய்த்து, ஜலத்திலே ஸ்நானம்பண்ணி, சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்.", "en": "And he that burneth her shall wash his clothes in water, and bathe his flesh in water, and shall be unclean until the even."}, {"verse": 9, "start": 87.42, "end": 106.72, "ta": "சுத்தமாயிருக்கிற ஒருவன் அந்தக் கிடாரியின் சாம்பலை வாரிக்கொண்டு பாளயத்திற்குப் புறம்பே சுத்தமான ஒரு இடத்திலே கொட்டி வைக்கக்கடவன், அது இஸ்ரவேல் புத்திரரின் சபைக்காகத் தீட்டுக்கழிக்கும் ஜலத்துக்கென்று காத்துவைக்கப்படவேண்டும்; அது பாவத்தைப் பரிகரிக்கும்.", "en": "And a man that is clean shall gather up the ashes of the heifer, and lay them up without the camp in a clean place, and it shall be kept for the congregation of the children of Israel for a water of separation: it is a purification for sin."}, {"verse": 10, "start": 106.72, "end": 122.78, "ta": "கிடாரியின் சாம்பலை வாரினவன் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்; அவன் சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்; இது இஸ்ரவேல் புத்திரருக்கும் அவர்கள் நடுவிலே தங்குகிற அந்நியனுக்கும் நித்திய கட்டளையாயிருப்பதாக.", "en": "And he that gathereth the ashes of the heifer shall wash his clothes, and be unclean until the even: and it shall be unto the children of Israel, and unto the stranger that sojourneth among them, for a statute for ever."}, {"verse": 11, "start": 122.78, "end": 128.39, "ta": "செத்துப்போனவனுடைய பிரேதத்தைத் தொட்டவன் ஏழுநாள் தீட்டுப்பட்டிருப்பான்.", "en": "He that toucheth the dead body of any man shall be unclean seven days."}, {"verse": 12, "start": 128.39, "end": 144.38, "ta": "அவன் மூன்றாம் நாளிலும் ஏழாம் நாளிலும் தீட்டுக்கழிக்கும் ஜலத்தினால் தன்னைச் சுத்திகரிக்கக்கடவன்; அப்பொழுது சுத்தமாவான்; மூன்றாம் நாளிலும் ஏழாம் நாளிலும் தன்னைச் சுத்திகரிக்காமலிருப்பானாகில் சுத்தமாகான்.", "en": "He shall purify himself with it on the third day, and on the seventh day he shall be clean: but if he purify not himself the third day, then the seventh day he shall not be clean."}, {"verse": 13, "start": 144.38, "end": 167.36, "ta": "செத்தவனுடைய பிரேதத்தைத் தொட்டும், தன்னைச் சுத்திகரித்துக்கொள்ளாதவன் கர்த்தரின் வாசஸ்தலத்தைத் தீட்டுப்படுத்துகிறான்; அந்த ஆத்துமா இஸ்ரவேலில் இராமல் அறுப்புண்டுபோவான்; தீட்டுக்கழிக்கும் ஜலம் அவன்மேல் தெளிக்கப்படாததினால், அவன் தீட்டுப்பட்டிருப்பான்; அவன் தீட்டு இன்னும் அவன்மேல் இருக்கும்.", "en": "Whosoever toucheth the dead body of any man that is dead, and purifieth not himself, defileth the tabernacle of the LORD ; and that soul shall be cut off from Israel: because the water of separation was not sprinkled upon him, he shall be unclean; his uncleanness is yet upon him."}, {"verse": 14, "start": 167.36, "end": 179.53, "ta": "கூடாரத்தில் ஒரு மனிதன் செத்தால், அதற்கடுத்த நியமமாவது: அந்தக் கூடாரத்தில் பிரவேசிக்கிற யாவரும் கூடாரத்தில் இருக்கிற யாவரும் ஏழுநாள் தீட்டுப்பட்டிருப்பார்கள்.", "en": "This is the law, when a man dieth in a tent: all that come into the tent, and all that is in the tent, shall be unclean seven days."}, {"verse": 15, "start": 179.53, "end": 185.87, "ta": "மூடிக் கட்டப்படாமல் திறந்திருக்கும் பாத்திரங்கள் எல்லாம் தீட்டுப்பட்டிருக்கும்.", "en": "And every open vessel, which hath no covering bound upon it, is unclean."}, {"verse": 16, "start": 185.87, "end": 197.46, "ta": "வெளியிலே பட்டயத்தால் வெட்டுண்டவனையாவது, செத்தவனையாவது, மனித எலும்பையாவது, பிரேதக்குழியையாவது, தொட்டவன் எவனும் ஏழுநாள் தீட்டுப்பட்டிருப்பான்.", "en": "And whosoever toucheth one that is slain with a sword in the open fields, or a dead body, or a bone of a man, or a grave, shall be unclean seven days."}, {"verse": 17, "start": 197.46, "end": 209.85, "ta": "ஆகையால் தீட்டுப்பட்டவனுக்காக, பாவத்தைப் பரிகரிக்கும் கிடாரியின் சாம்பலிலே கொஞ்சம் எடுத்து, ஒரு பாத்திரத்தில் போட்டு, அதின்மேல் ஊற்று ஜலம் வார்க்கவேண்டும்.", "en": "And for an unclean person they shall take of the ashes of the burnt heifer of purification for sin, and running water shall be put thereto in a vessel:"}, {"verse": 18, "start": 209.85, "end": 230.37, "ta": "சுத்தமான ஒருவன் ஈசோப்பை எடுத்து, அந்த ஜலத்திலே தோய்த்து, கூடாரத்தின்மேலும் அதிலுள்ள சகல பணிமுட்டுகளின்மேலும் அங்கேயிருக்கிற ஜனங்களின்மேலும் தெளிக்கிறதுமல்லாமல், எலும்பையாகிலும் வெட்டுண்டவனையாகிலும் செத்தவனையாகிலும் பிரேதக்குழியையாகிலும் தொட்டவன்மேலும் தெளிக்கக்கடவன்.", "en": "And a clean person shall take hyssop, and dip it in the water, and sprinkle it upon the tent, and upon all the vessels, and upon the persons that were there, and upon him that touched a bone, or one slain, or one dead, or a grave:"}, {"verse": 19, "start": 230.37, "end": 247.59, "ta": "சுத்தமாயிருக்கிறவன் தீட்டுப்பட்டவன்மேல் மூன்றாம் நாளிலும் ஏழாம் நாளிலும் தெளிக்கவேண்டும்; ஏழாம் நாளில் இவன் தன்னைச் சுத்திகரித்து, தன் வஸ்திரங்களைத் தோய்த்து, ஜலத்தில் ஸ்நானம்பண்ணி, சாயங்காலத்திலே சுத்தமாயிருப்பான்.", "en": "And the clean person shall sprinkle upon the unclean on the third day, and on the seventh day: and on the seventh day he shall purify himself, and wash his clothes, and bathe himself in water, and shall be clean at even."}, {"verse": 20, "start": 247.59, "end": 267.18, "ta": "தீட்டுப்பட்டிருக்கிறவன் தன்னைச் சுத்திகரித்துக் கொள்ளாதிருந்தால், அவன் சபையில் இராதபடிக்கு அறுப்புண்டுபோவான்; அவன் கர்த்தரின் பரிசுத்த ஸ்தலத்தைத் தீட்டுப்படுத்தினான்; தீட்டுக்கழிக்கும் ஜலம் அவன்மேல் தெளிக்கப்படாததினால் அவன் தீட்டுப்பட்டிருக்கிறான்.", "en": "But the man that shall be unclean, and shall not purify himself, that soul shall be cut off from among the congregation, because he hath defiled the sanctuary of the LORD : the water of separation hath not been sprinkled upon him; he is unclean."}, {"verse": 21, "start": 267.18, "end": 279.13, "ta": "தீட்டுக்கழிக்கும் ஜலத்தைத் தெளிக்கிறவனும் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்; தீட்டுக்கழிக்கும் ஜலத்தைத்தொட்டவனும் சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்.", "en": "And it shall be a perpetual statute unto them, that he that sprinkleth the water of separation shall wash his clothes; and he that toucheth the water of separation shall be unclean until even."}, {"verse": 22, "start": 279.13, "end": 292.6, "ta": "தீட்டுப்பட்டிருக்கிறவன் தொடுகிறவைகளெல்லாம் தீட்டுப்படும், அவைகளைத் தொடுகிறவனும் சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்; இது உங்களுக்கு நித்திய கட்டளையாயிருக்கும் என்றார்.", "en": "And whatsoever the unclean person toucheth shall be unclean; and the soul that toucheth it shall be unclean until even."}]}, "20": {"chapter": 20, "duration": 376.65, "audio_url": "audio_ot/OT04_20.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 17.53, "ta": "இஸ்ரவேல் புத்திரரின் சபையார் எல்லாரும் முதலாம் மாதத்தில் சீன்வனாந்தரத்திலே சேர்ந்து, ஜனங்கள் காதேசிலே தங்கியிருக்கையில், மிரியாம் மரணமடைந்து, அங்கே அடக்கம்பண்ணப்பட்டாள்.", "en": "Then came the children of Israel, even the whole congregation, into the desert of Zin in the first month: and the people abode in Kadesh; and Miriam died there, and was buried there."}, {"verse": 2, "start": 17.53, "end": 26.64, "ta": "ஜனங்களுக்குத் தண்ணீர் இல்லாதிருந்தது; அப்பொழுது அவர்கள் மோசேக்கும் ஆரோனுக்கும் விரோதமாகக் கூட்டங்கூடினார்கள்.", "en": "And there was no water for the congregation: and they gathered themselves together against Moses and against Aaron."}, {"verse": 3, "start": 26.64, "end": 36.77, "ta": "ஜனங்கள் மோசேயோடே வாக்குவாதம் பண்ணி: எங்கள் சகோதரர் கர்த்தருடைய சந்நிதியில் மாண்டபோது நாங்களும் மாண்டுபோயிருந்தால் நலமாயிருக்கும்.", "en": "And the people chode with Moses, and spake, saying, Would God that we had died when our brethren died before the LORD !"}, {"verse": 4, "start": 36.77, "end": 45.51, "ta": "நாங்களும் எங்கள் மிருகங்களும் இங்கே சாகும்படி, நீங்கள் கர்த்தரின் சபையை இந்த வனாந்தரத்திலே கொண்டு வந்தது என்ன;", "en": "And why have ye brought up the congregation of the LORD into this wilderness, that we and our cattle should die there?"}, {"verse": 5, "start": 45.51, "end": 61.44, "ta": "விதைப்பும் அத்திமரமும், திராட்சச்செடியும், மாதளஞ்செடியும், குடிக்கத் தண்ணீரும் இல்லாத இந்த கெட்ட இடத்தில் எங்களைக் கொண்டுவரும்படி, நீங்கள் எங்களை எகிப்திலிருந்து புறப்படப்பண்ணினது என்ன என்றார்கள்.", "en": "And wherefore have ye made us to come up out of Egypt, to bring us in unto this evil place? it is no place of seed, or of figs, or of vines, or of pomegranates; neither is there any water to drink."}, {"verse": 6, "start": 61.44, "end": 73.63, "ta": "அப்பொழுது மோசேயும் ஆரோனும் சபையாரை விட்டு, ஆசரிப்புக் கூடாரவாசலில் போய், முகங்குப்புற விழுந்தார்கள்; கர்த்தருடைய மகிமை அவர்களுக்குக் காணப்பட்டது.", "en": "And Moses and Aaron went from the presence of the assembly unto the door of the tabernacle of the congregation, and they fell upon their faces: and the glory of the LORD appeared unto them."}, {"verse": 7, "start": 73.63, "end": 75.32, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 8, "start": 75.32, "end": 101.32, "ta": "நீ கோலை எடுத்துக்கொண்டு, நீயும் உன் சகோதரனாகிய ஆரோனும் சபையாரைக் கூடிவரச்செய்து, அவர்கள் கண்களுக்குமுன்னே கன்மலையைப் பார்த்துப் பேசுங்கள்; அப்பொழுது அது தன்னிடத்திலுள்ள தண்ணீரைக் கொடுக்கும்; இப்படி நீ அவர்களுக்குக் கன்மலையிலிருந்து தண்ணீர் புறப்படப்பண்ணி, சபையாருக்கும் அவர்கள் மிருகங்களுக்கும் குடிக்கக் கொடுப்பாய் என்றார்.", "en": "Take the rod, and gather thou the assembly together, thou, and Aaron thy brother, and speak ye unto the rock before their eyes; and it shall give forth his water, and thou shalt bring forth to them water out of the rock: so thou shalt give the congregation and their beasts drink."}, {"verse": 9, "start": 101.32, "end": 108.88, "ta": "அப்பொழுது மோசே தனக்குக் கர்த்தர் கட்டளையிட்டபடியே கர்த்தருடைய சந்நிதியிலிருந்த கோலை எடுத்தான்.", "en": "And Moses took the rod from before the LORD , as he commanded him."}, {"verse": 10, "start": 108.88, "end": 124.96, "ta": "மோசேயும் ஆரோனும் சபையாரைக் கன்மலைக்கு முன்பாக கூடிவரச்செய்தார்கள்; அப்பொழுது மோசே அவர்களை நோக்கி: கலகக்காரரே, கேளுங்கள், உங்களுக்கு இந்தக் கன்மலையிலிருந்து நாங்கள் தண்ணீர் புறப்படப்பண்ணுவோமோ என்று சொல்லி,", "en": "And Moses and Aaron gathered the congregation together before the rock, and he said unto them, Hear now, ye rebels; must we fetch you water out of this rock?"}, {"verse": 11, "start": 124.96, "end": 138.18, "ta": "தன் கையை ஓங்கி, கன்மலையைத் தன் கோலினால் இரண்டுதரம் அடித்தான்; உடனே தண்ணீர் ஏராளமாய்ப் புறப்பட்டது, சபையார் குடித்தார்கள்; அவர்கள் மிருகங்களும் குடித்தது.", "en": "And Moses lifted up his hand, and with his rod he smote the rock twice: and the water came out abundantly, and the congregation drank, and their beasts also ."}, {"verse": 12, "start": 138.18, "end": 156.76, "ta": "பின்பு கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி: இஸ்ரவேல் புத்திரரின் கண்களுக்கு முன்பாக என்னைப் பரிசுத்தம் பண்ணும்படி, நீங்கள் என்னை விசுவாசியாமற் போனபடியினால், இந்தச் சபையாருக்கு நான் கொடுத்த தேசத்திற்குள் அவர்களைக் கொண்டுபோவதில்லை என்றார்.", "en": "And the LORD spake unto Moses and Aaron, Because ye believed me not, to sanctify me in the eyes of the children of Israel, therefore ye shall not bring this congregation into the land which I have given them."}, {"verse": 13, "start": 156.76, "end": 168.73, "ta": "இங்கே இஸ்ரவேல் புத்திரர் கர்த்தரோடே வாக்குவாதம்பண்ணினதினாலும், அவர்களுக்குள்ளே அவருடைய பரிசுத்தம் விளங்கினதினாலும் இது மேரிபாவின் தண்ணீர் என்னப்பட்டது.", "en": "This is the water of Meribah; because the children of Israel strove with the LORD , and he was sanctified in them."}, {"verse": 14, "start": 168.73, "end": 174.16, "ta": "பின்பு மோசே காதேசிலிருந்து ஏதோமின் ராஜாவினிடத்துக்கு ஸ்தானாபதிகளை அனுப்பி:", "en": "And Moses sent messengers from Kadesh unto the king of Edom, Thus saith thy brother Israel, Thou knowest all the travail that hath befallen us:"}, {"verse": 15, "start": 174.16, "end": 191.71, "ta": "எங்கள் பிதாக்கள் எகிப்துக்குப் போனதும், நாங்கள் எகிப்திலே நெடுநாள் வாசம்பண்ணினதும், எகிப்தியர் எங்களை எங்கள் பிதாக்களையும் உபத்திரவப்படுத்தினதும், இவைகளினால் எங்களுக்கு நேரிட்ட எல்லா வருத்தமும் உமக்குத் தெரிந்திருக்கிறது.", "en": "How our fathers went down into Egypt, and we have dwelt in Egypt a long time; and the Egyptians vexed us, and our fathers:"}, {"verse": 16, "start": 191.71, "end": 208.46, "ta": "கர்த்தரை நோக்கி நாங்கள் மன்றாடினோம்; அவர் எங்களுக்குச் செவிகொடுத்து, ஒரு தூதனை அனுப்பி, எங்களை எகிப்திலிருந்து புறப்படப்பண்ணினார்; இப்பொழுது நாங்கள் உமது எல்லைக்கு உட்பட்ட காதேஸ் ஊரில் வந்திருக்கிறோம்.", "en": "And when we cried unto the LORD , he heard our voice, and sent an angel, and hath brought us forth out of Egypt: and, behold, we are in Kadesh, a city in the uttermost of thy border:"}, {"verse": 17, "start": 208.46, "end": 236.58, "ta": "நாங்கள் உமது தேசத்தின் வழியாய்க் கடந்துபோகும்படி உத்தரவு கொடுக்கவேண்டும்; வயல்வெளிகள் வழியாகவும், திராட்சத்தோட்டங்கள் வழியாகவும் நாங்கள் போகாமலும், துரவுகளின் தண்ணீரை குடியாமலும், ராஜபாதையாகவே நடந்து, உமது எல்லையைக் கடந்துபோகுமட்டும், வலதுபுறமும் இடதுபுறமும் சாயாதிருப்போம் என்று, உமது சகோதரனாகிய இஸ்ரவேல் சொல்லி அனுப்புகிறான் என்று சொல்லச் சொன்னான்.", "en": "Let us pass, I pray thee, through thy country: we will not pass through the fields, or through the vineyards, neither will we drink of the water of the wells: we will go by the king’s high way, we will not turn to the right hand nor to the left, until we have passed thy borders."}, {"verse": 18, "start": 236.58, "end": 248.26, "ta": "அதற்கு ஏதோம்: நீ என் தேசத்தின் வழியாய்க் கடந்துபோகக் கூடாது; போனால் பட்டயத்தோடே உன்னை எதிர்க்கப் புறப்படுவேன் என்று அவனுக்குச் சொல்லச் சொன்னான்.", "en": "And Edom said unto him, Thou shalt not pass by me, lest I come out against thee with the sword."}, {"verse": 19, "start": 248.26, "end": 266.54, "ta": "அப்பொழுது இஸ்ரவேல் புத்திரர் அவனை நோக்கி: நடப்பான பாதையின் வழியாய் போவோம்; நாங்களும் எங்கள் மிருகங்களும் உன் தண்ணீரைக் குடித்தால் அதற்குக் கிரயங்கொடுப்போம்; வேறொன்றும் செய்யாமல், கால்நடையாய் மாத்திரம் கடந்துபோவோம் என்றார்கள்.", "en": "And the children of Israel said unto him, We will go by the high way: and if I and my cattle drink of thy water, then I will pay for it: I will only, without doing any thing else , go through on my feet."}, {"verse": 20, "start": 266.54, "end": 275.72, "ta": "அதற்கு அவன்: நீ கடந்துபோகக் கூடாது என்று சொல்லி, வெகு ஜனங்களோடும் பலத்த கையோடும் அவர்களை எதிர்க்கப் புறப்பட்டான்.", "en": "And he said, Thou shalt not go through. And Edom came out against him with much people, and with a strong hand."}, {"verse": 21, "start": 275.72, "end": 286.52, "ta": "இப்படி ஏதோம் தன் எல்லைவழியாய்க் கடந்துபோகும்படி இஸ்ரவேலருக்கு உத்தரவு கொடுக்கவில்லை; ஆகையால் இஸ்ரவேலர் அவனை விட்டு விலகிப்போனார்கள்.", "en": "Thus Edom refused to give Israel passage through his border: wherefore Israel turned away from him."}, {"verse": 22, "start": 286.52, "end": 294.81, "ta": "இஸ்ரவேல் புத்திரரான சபையார் எல்லாரும் காதேசை விட்டுப் பிரயாணப்பட்டு, ஓர் என்னும் மலைக்குப் போனார்கள்.", "en": "And the children of Israel, even the whole congregation, journeyed from Kadesh, and came unto mount Hor."}, {"verse": 23, "start": 294.81, "end": 301.42, "ta": "ஏதோம் தேசத்தின் எல்லைக்கு அருகான ஓர் என்னும் மலையிலே கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and Aaron in mount Hor, by the coast of the land of Edom, saying,"}, {"verse": 24, "start": 301.42, "end": 317.87, "ta": "ஆரோன் தன் ஜனத்தாரோடே சேர்க்கப்படுவான். மேரிபாவின் தண்ணீரைப்பற்றிய காரியத்தில் நீங்கள் என் வாக்குக்குக் கீழ்ப்படியாமற்போனபடியினால், நான் இஸ்ரவேல் புத்திரருக்குக் கொடுக்கிற தேசத்தில் அவன் பிரவேசிப்பதில்லை.", "en": "Aaron shall be gathered unto his people: for he shall not enter into the land which I have given unto the children of Israel, because ye rebelled against my word at the water of Meribah."}, {"verse": 25, "start": 317.87, "end": 325.44, "ta": "நீ ஆரோனையும் அவன் குமாரனாகிய எலெயாசாரையும் கூட்டிக்கொண்டு, அவர்களை ஓர் என்னும் மலையில் ஏறப்பண்ணி,", "en": "Take Aaron and Eleazar his son, and bring them up unto mount Hor:"}, {"verse": 26, "start": 325.44, "end": 338.36, "ta": "ஆரோன் உடுத்திருக்கிற வஸ்திரங்களைக் கழற்றி, அவைகளை அவன் குமாரனாகிய எலெயாசாருக்கு உடுத்துவாயாக; ஆரோன் அங்கே மரித்து, தன் ஜனத்தாரோடே சேர்க்கப்படுவான் என்றார்.", "en": "And strip Aaron of his garments, and put them upon Eleazar his son: and Aaron shall be gathered unto his people , and shall die there."}, {"verse": 27, "start": 338.36, "end": 347.25, "ta": "கர்த்தர் கட்டளையிட்டபடியே மோசே செய்தான்; சபையார் எல்லாரும் பார்க்க அவர்கள் ஓர் என்னும் மலையில் ஏறினார்கள்.", "en": "And Moses did as the LORD commanded: and they went up into mount Hor in the sight of all the congregation."}, {"verse": 28, "start": 347.25, "end": 364.21, "ta": "அங்கே ஆரோன் உடுத்திருந்த வஸ்திரங்களை மோசே கழற்றி, அவைகளை அவன் குமாரனாகிய எலெயாசாருக்கு உடுத்தினான்; அப்பொழுது ஆரோன் அங்கே மலையின் உச்சியிலே மரித்தான்; பின்பு மோசேயும் எலெயாசாரும் மலையிலிருந்து இறங்கினார்கள்.", "en": "And Moses stripped Aaron of his garments, and put them upon Eleazar his son; and Aaron died there in the top of the mount: and Moses and Eleazar came down from the mount."}, {"verse": 29, "start": 364.21, "end": 375.15, "ta": "ஆரோன் ஜீவித்துப்போனான் என்பதைச் சபையார் எல்லோரும் கண்டபோது, இஸ்ரவேல் வம்சத்தார் எல்லாரும் ஆரோனுக்காக முப்பது நாள் துக்கங்கொண்டாடினார்கள்.", "en": "And when all the congregation saw that Aaron was dead, they mourned for Aaron thirty days, even all the house of Israel."}]}, "21": {"chapter": 21, "duration": 431.25, "audio_url": "audio_ot/OT04_21.mp3", "total_verses": 35, "verses": [{"verse": 1, "start": 3.8, "end": 19.34, "ta": "வேவுகாரர் காண்பித்த வழியாக இஸ்ரவேலர் வருகிறார்கள் என்று தெற்கே வாசம்பண்ணுகிற கானானியனாகிய ஆராத் ராஜா கேள்விப்பட்டபோது, அவன் இஸ்ரவேலருக்கு விரோதமாக யுத்தம் பண்ணி, அவர்களில் சிலரை சிறைபிடித்துக்கொண்டுபோனான்.", "en": "And when king Arad the Canaanite, which dwelt in the south, heard tell that Israel came by the way of the spies; then he fought against Israel, and took some of them prisoners."}, {"verse": 2, "start": 19.34, "end": 31.83, "ta": "அப்பொழுது இஸ்ரவேலர் கர்த்தரை நோக்கி: தேவரீர் இந்த ஜனங்களை எங்கள் கையில் ஒப்புக்கொடுத்தால், அவர்களுடைய பட்டணங்களைச் சங்காரம் பண்ணுவோம் என்று பிரதிக்கினை பண்ணினார்கள்.", "en": "And Israel vowed a vow unto the LORD , and said, If thou wilt indeed deliver this people into my hand, then I will utterly destroy their cities."}, {"verse": 3, "start": 31.83, "end": 46.95, "ta": "கர்த்தர் இஸ்ரவேலின் சத்தத்துக்குச் செவிகொடுத்து, அவர்களுக்குக் கானானியரை ஒப்புக்கொடுத்தார்; அப்பொழுது அவர்களையும் அவர்கள் பட்டணங்களையும் சங்காரம்பண்ணி, அவ்விடத்திற்கு ஓர்மா என்று பேரிட்டார்கள்.", "en": "And the LORD hearkened to the voice of Israel, and delivered up the Canaanites; and they utterly destroyed them and their cities: and he called the name of the place Hormah."}, {"verse": 4, "start": 46.95, "end": 60.22, "ta": "அவர்கள் ஏதோம் தேசத்தைச் சுற்றிப்போகும்படிக்கு, ஓர் என்னும் மலையைவிட்டு, சிவந்த சமுத்திரத்தின் வழியாய்ப் பிரயாணம்பண்ணினார்கள்; வழியினிமித்தம் ஜனங்கள் மனமடிவடைந்தார்கள்.", "en": "And they journeyed from mount Hor by the way of the Red sea, to compass the land of Edom: and the soul of the people was much discouraged because of the way."}, {"verse": 5, "start": 60.22, "end": 79.08, "ta": "ஜனங்கள் தேவனுக்கும் மோசேக்கும் விரோதமாகப் பேசி: நாங்கள் வனாந்தரத்திலே சாகும்படி நீங்கள் எங்களை எகிப்து தேசத்திலிருந்து வரப்பண்ணினதென்ன? இங்கே அப்பமும் இல்லை, தண்ணீரும் இல்லை; இந்த அற்பமான உணவு எங்கள் மனதுக்கு வெறுப்பாயிருக்கிறது என்றார்கள்.", "en": "And the people spake against God, and against Moses, Wherefore have ye brought us up out of Egypt to die in the wilderness? for there is no bread, neither is there any water; and our soul loatheth this light bread."}, {"verse": 6, "start": 79.08, "end": 90.37, "ta": "அப்பொழுது கர்த்தர் கொள்ளிவாய்ச்சர்ப்பங்களை ஜனங்களுக்குள்ளே அனுப்பினார்; அவைகள் ஜனங்களைக் கடித்ததினால் இஸ்ரவேலருக்குள்ளே அநேக ஜனங்கள் செத்தார்கள்.", "en": "And the LORD sent fiery serpents among the people, and they bit the people; and much people of Israel died."}, {"verse": 7, "start": 90.37, "end": 108.59, "ta": "அதினால் ஜனங்கள் மோசேயினிடத்தில் போய்: நாங்கள் கர்த்தருக்கும் உமக்கும் விரோதமாய்ப் பேசினதினால் பாவஞ்செய்தோம்; சர்ப்பங்கள் எங்களைவிட்டு நீங்கும்படி கர்த்தரை நோக்கி விண்ணப்பம் பண்ணவேண்டும் என்றார்கள்; மோசே ஜனங்களுக்காக விண்ணப்பம் பண்ணினான்.", "en": "Therefore the people came to Moses, and said, We have sinned, for we have spoken against the LORD , and against thee; pray unto the LORD , that he take away the serpents from us. And Moses prayed for the people."}, {"verse": 8, "start": 108.59, "end": 123.07, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ ஒரு கொள்ளிவாய்ச் சர்ப்பத்தின் உருவத்தைச் செய்து, அதை ஒரு கம்பத்தின்மேல் தூக்கிவை; கடிக்கப்பட்டவன் எவனோ அவன் அதை நோக்கிப்பார்த்தால் பிழைப்பான் என்றார்.", "en": "And the LORD said unto Moses, Make thee a fiery serpent, and set it upon a pole: and it shall come to pass, that every one that is bitten, when he looketh upon it, shall live."}, {"verse": 9, "start": 123.07, "end": 137.12, "ta": "அப்படியே மோசே ஒரு வெண்கலச் சர்ப்பத்தை உண்டாக்கி, அதை ஒரு கம்பத்தின்மேல் தூக்கிவைத்தான்; சர்ப்பம் ஒருவனைக் கடித்தபோது, அவன் அந்த வெண்கலச் சர்ப்பத்தை நோக்கிப்பார்த்துப் பிழைப்பான்.", "en": "And Moses made a serpent of brass, and put it upon a pole, and it came to pass, that if a serpent had bitten any man, when he beheld the serpent of brass, he lived."}, {"verse": 10, "start": 137.12, "end": 142.84, "ta": "இஸ்ரவேல் புத்திரர் பிரயாணப்பட்டுப்போய், ஓபோத்தில் பாளயமிறங்கினார்கள்.", "en": "And the children of Israel set forward, and pitched in Oboth."}, {"verse": 11, "start": 142.84, "end": 152.87, "ta": "ஓபோத்திலிருந்து பிரயாணம் பண்ணி, சூரியோதயத்திற்கு நேராய் மோவாபுக்கு எதிரான வனாந்தரத்திலுள்ள அபாரீமின் மேடுகளில் பாளயமிறங்கினார்கள்.", "en": "And they journeyed from Oboth, and pitched at Ije-abarim, in the wilderness which is before Moab, toward the sunrising."}, {"verse": 12, "start": 152.87, "end": 159.15, "ta": "அங்கேயிருந்து பிரயாணப்பட்டுப் போய், சாரேத் பள்ளத்தாக்கிலே பாளயமிறங்கினார்கள்.", "en": "From thence they removed, and pitched in the valley of Zared."}, {"verse": 13, "start": 159.15, "end": 175.82, "ta": "அங்கேயிருந்து பிரயாணப்பட்டுப் போய், எமோரியரின் எல்லையிலிருந்து வருகிறதும் வனாந்தரத்தில் ஓடுகிறதுமான அர்னோன் ஆற்றுக்கு இப்புறம் பாளயமிறங்கினார்கள்; அந்த அர்னோன் மோவாபுக்கும் எமோரியருக்கும் நடுவே இருக்கிற மோவாபின் எல்லை.", "en": "From thence they removed, and pitched on the other side of Arnon, which is in the wilderness that cometh out of the coasts of the Amorites: for Arnon is the border of Moab, between Moab and the Amorites."}, {"verse": 14, "start": 175.82, "end": 180.41, "ta": "அதினால் சூப்பாவிலுள்ள வாகேபும், அர்னோனின் ஆற்றுக்கால்களும்,", "en": "Wherefore it is said in the book of the wars of the LORD , What he did in the Red sea, and in the brooks of Arnon,"}, {"verse": 15, "start": 180.41, "end": 191.21, "ta": "ஆர் என்னும் ஸ்தலத்துக்குப் பாயும் நீரோடையும் மோவாபின் எல்லையைச் சார்ந்திருக்கிறது என்னும் வசனம் கர்த்தருடைய யுத்த புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "And at the stream of the brooks that goeth down to the dwelling of Ar, and lieth upon the border of Moab."}, {"verse": 16, "start": 191.21, "end": 203.43, "ta": "அங்கேயிருந்து பேயேருக்குப் போனார்கள்; ஜனங்களைக் கூடிவரச்செய், அவர்களுக்குத் தண்ணீர் கொடுப்பேன் என்று கர்த்தர் மோசேக்குச் சொன்ன ஊற்று இருக்கிற இடம் அதுதான்.", "en": "And from thence they went to Beer: that is the well whereof the LORD spake unto Moses, Gather the people together, and I will give them water."}, {"verse": 17, "start": 203.43, "end": 211.69, "ta": "அப்பொழுது இஸ்ரவேலர் பாடின பாட்டாவது: ஊற்றுத் தண்ணீரே, பொங்கிவா; அதைக்குறித்துப் பாடுவோம் வாருங்கள்.", "en": "Then Israel sang this song, Spring up, O well; sing ye unto it:"}, {"verse": 18, "start": 211.69, "end": 223.13, "ta": "நியாயப்பிரமாணிக்கனின் ஏவுதலால் அதிபதிகள் கிணற்றைத் தோண்டினார்கள்; ஜனத்தில் மேன்மக்கள் தங்கள் தண்டாயுதங்களைக்கொண்டு தோண்டினார்கள் என்று பாடினார்கள்.", "en": "The princes digged the well, the nobles of the people digged it, by the direction of the lawgiver, with their staves. And from the wilderness they went to Mattanah:"}, {"verse": 19, "start": 223.13, "end": 231.53, "ta": "அந்த வனாந்தரத்திலிருந்து மாத்தனாவுக்கும், மாத்தனாவிலிருந்து நகாலியேலுக்கும், நகாலியேலிலிருந்து பாமோத்துக்கும்,", "en": "And from Mattanah to Nahaliel: and from Nahaliel to Bamoth:"}, {"verse": 20, "start": 231.53, "end": 240.08, "ta": "பள்ளத்தாக்கிலுள்ள மோவாபின் வெளியில் இருக்கிற பாமோத்திலிருந்து எஷிமோனை நோக்கும் பிஸ்காவின் உச்சிக்கும் போனார்கள்.", "en": "And from Bamoth in the valley, that is in the country of Moab, to the top of Pisgah, which looketh toward Jeshimon."}, {"verse": 21, "start": 240.08, "end": 245.44, "ta": "அப்பொழுது இஸ்ரவேலர் எமோரியரின் ராஜாவாகிய சீகோனிடத்தில் ஸ்தானாபதிகளை அனுப்பி:", "en": "And Israel sent messengers unto Sihon king of the Amorites, saying,"}, {"verse": 22, "start": 245.44, "end": 264.09, "ta": "உமது தேசத்தின் வழியாய்க் கடந்துபோகும்படி உத்தரவு கொடுக்க வேண்டும்; நாங்கள் வயல்களிலும், திராட்சத்தோட்டங்களிலும் போகாமலும், துரவுகளின் தண்ணீரைக் குடியாமலும், உமது எல்லையைக் கடந்துபோகுமட்டும் ராஜபாதையில் நடந்துபோவோம் என்று சொல்லச்சொன்னார்கள்.", "en": "Let me pass through thy land: we will not turn into the fields, or into the vineyards; we will not drink of the waters of the well: but we will go along by the king’s high way, until we be past thy borders."}, {"verse": 23, "start": 264.09, "end": 279.69, "ta": "சீகோன் தன் எல்லைவழியாய்க் கடந்துபோக இஸ்ரவேலுக்கு உத்தரவு கொடாமல், தன் ஜனங்களெல்லாரையும் கூட்டிக்கொண்டு, இஸ்ரவேலருக்கு விரோதமாக வனாந்தரத்திலே புறப்பட்டு, யாகாசுக்கு வந்து, இஸ்ரவேலரோடே யுத்தம்பண்ணினான்.", "en": "And Sihon would not suffer Israel to pass through his border: but Sihon gathered all his people together, and went out against Israel into the wilderness: and he came to Jahaz, and fought against Israel."}, {"verse": 24, "start": 279.69, "end": 295.44, "ta": "இஸ்ரவேலர் அவனைப் பட்டயக்கருக்கினால் வெட்டி, அர்னோன் தொடங்கி அம்மோன் புத்திரரின் தேசத்தைச்சார்ந்த யாப்போக்குவரைக்குமுள்ள அவனுடைய தேசத்தைக் கட்டிக்கொண்டார்கள்; அம்மோன் புத்திரரின் எல்லை அரணிப்பானதாயிருந்தது.", "en": "And Israel smote him with the edge of the sword, and possessed his land from Arnon unto Jabbok, even unto the children of Ammon: for the border of the children of Ammon was strong."}, {"verse": 25, "start": 295.44, "end": 306.74, "ta": "இஸ்ரவேலர் அந்தப் பட்டணங்கள் யாவையும் பிடித்து, எஸ்போனிலும் அதைச் சார்ந்த எல்லாக் கிராமங்களிலும் எமோரியருடைய எல்லாப்பட்டணங்களிலும் குடியிருந்தார்கள்.", "en": "And Israel took all these cities: and Israel dwelt in all the cities of the Amorites, in Heshbon, and in all the villages thereof."}, {"verse": 26, "start": 306.74, "end": 322.13, "ta": "எஸ்போனானது எமோரியரின் ராஜாவாகிய சீகோனின் பட்டணமாயிருந்தது; அவன் மோவாபியரின் முந்தின ராஜாவுக்கு விரோதமாக யுத்தம்பண்ணி, அர்னோன் வரைக்கும் இருந்த அவன் தேசத்தையெல்லாம் அவன் கையிலிருந்து பறித்துக்கொண்டான்.", "en": "For Heshbon was the city of Sihon the king of the Amorites, who had fought against the former king of Moab, and taken all his land out of his hand, even unto Arnon."}, {"verse": 27, "start": 322.13, "end": 329.76, "ta": "அதினாலே கவிகட்டுகிறவர்கள்: எஸ்போனுக்கு வாருங்கள்; சீகோனின் பட்டணம் ஸ்திரமாய்க் கட்டப்படுவதாக.", "en": "Wherefore they that speak in proverbs say, Come into Heshbon, let the city of Sihon be built and prepared:"}, {"verse": 28, "start": 329.76, "end": 342.26, "ta": "எஸ்போனிலிருந்து அக்கினியும் சீகோனுடைய பட்டணத்திலிருந்து ஜுவாலையும் புறப்பட்டு, மோவாபுடைய ஆர் என்னும் ஊரையும், அர்னோனுடைய மேடுகளிலுள்ள ஆண்டவமார்களையும் பட்சித்தது.", "en": "For there is a fire gone out of Heshbon, a flame from the city of Sihon: it hath consumed Ar of Moab, and the lords of the high places of Arnon."}, {"verse": 29, "start": 342.26, "end": 355.04, "ta": "ஐயோ, மோவாபே, கேமோஷ் தேவனின் ஜனமே, நீ நாசமானாய்; தப்பி ஓடின தன் குமாரரையும் தன் குமாரத்திகளையும் எமோரியரின் ராஜாவாகிய சீகோனுக்குச் சிறைகளாக ஒப்புக்கொடுத்தான்.", "en": "Woe to thee, Moab! thou art undone, O people of Chemosh: he hath given his sons that escaped, and his daughters, into captivity unto Sihon king of the Amorites."}, {"verse": 30, "start": 355.04, "end": 367.68, "ta": "அவர்களை எய்துபோட்டோம்; எஸ்போன் பட்டணம் தீபோன் ஊர்வரைக்கும் நாசமாயிற்று; மேதேபாவுக்குச் சமீபமான நோப்பா பட்டணபரியந்தம் அவர்களைப் பாழாக்கினோம் என்று பாடினார்கள்.", "en": "We have shot at them; Heshbon is perished even unto Dibon, and we have laid them waste even unto Nophah, which reacheth unto Medeba."}, {"verse": 31, "start": 367.68, "end": 372.41, "ta": "இஸ்ரவேலர் இப்படியே எமோரியரின் தேசத்திலே குடியிருந்தார்கள்.", "en": "Thus Israel dwelt in the land of the Amorites."}, {"verse": 32, "start": 372.41, "end": 385.19, "ta": "பின்பு, மோசே யாசேர் பட்டணத்துக்கு வேவு பார்க்கிறவர்களை அனுப்பினான்; அவர்கள் அதைச்சேர்ந்த கிராமங்களைக் கட்டிக்கொண்டு, அங்கே இருந்த எமோரியரைத் துரத்திவிட்டார்கள்.", "en": "And Moses sent to spy out Jaazer, and they took the villages thereof, and drove out the Amorites that were there."}, {"verse": 33, "start": 385.19, "end": 400.09, "ta": "பின்பு பாசானுக்குப் போகிற வழியாய்த் திரும்பிவிட்டார்கள்; அப்பொழுது பாசான் ராஜாவாகிய ஓக் என்பவன் தன் சமஸ்த ஜன்ங்களோடும் அவர்களை எதிர்த்து யுத்தம்பண்ணும்படிக்கு, எத்ரேயுக்குப் புறப்பட்டு வந்தான்.", "en": "And they turned and went up by the way of Bashan: and Og the king of Bashan went out against them, he, and all his people, to the battle at Edrei."}, {"verse": 34, "start": 400.09, "end": 418.03, "ta": "கர்த்தர் மோசேயை நோக்கி: அவனுக்குப் பயப்படவேண்டாம்; அவனையும் அவன் ஜனங்கள் எல்லாரையும், அவன் தேசத்தையும் உன் கையில் ஒப்புக்கொடுத்தேன்; எஸ்போனிலே வாசமாயிருந்த எமோரியரின் ராஜாவாகிய சீகோனுக்கு நீ செய்தபடியே இவனுக்கும் செய்வாய் என்றார்.", "en": "And the LORD said unto Moses, Fear him not: for I have delivered him into thy hand, and all his people, and his land; and thou shalt do to him as thou didst unto Sihon king of the Amorites, which dwelt at Heshbon."}, {"verse": 35, "start": 418.03, "end": 429.75, "ta": "அப்படியே ஒருவரும் உயிருடன் மீதியாயிராதபடிக்கு அவனையும், அவன் குமாரரையும், அவனுடைய சகல ஜனங்களையும் வெட்டிப்போட்டு, அவன் தேசத்தைக் கட்டிக்கொண்டார்கள்.", "en": "So they smote him, and his sons, and all his people, until there was none left him alive: and they possessed his land."}]}, "22": {"chapter": 22, "duration": 504.44, "audio_url": "audio_ot/OT04_22.mp3", "total_verses": 41, "verses": [{"verse": 1, "start": 3.8, "end": 14.37, "ta": "பின்பு இஸ்ரவேல் புத்திரர் பிரயாணம் பண்ணி, எரிகோவின் கிட்ட இருக்கும் யோர்தானுக்கு இக்கரையிலே மோவாபின் சமனான வெளிகளில் பாளயமிறங்கினார்கள்.", "en": "And the children of Israel set forward, and pitched in the plains of Moab on this side Jordan by Jericho."}, {"verse": 2, "start": 14.37, "end": 20.52, "ta": "இஸ்ரவேலர் எமோரியருக்குச் செய்த யாவையும் சிப்போரின் குமாரனாகிய பாலாக் கண்டான்.", "en": "And Balak the son of Zippor saw all that Israel had done to the Amorites."}, {"verse": 3, "start": 20.52, "end": 28.02, "ta": "ஜனங்கள் ஏராளமாயிருந்தபடியினால், மோவாப் மிகவும் பயந்து, இஸ்ரவேல் புத்திரரினிமித்தம் கலக்கமடைந்து,", "en": "And Moab was sore afraid of the people, because they were many: and Moab was distressed because of the children of Israel."}, {"verse": 4, "start": 28.02, "end": 44.38, "ta": "மீதியானரின் மூப்பரை நோக்கி: மாடு வெளியின் புல்லை மேய்கிறதுபோல, இப்பொழுது இந்தக் கூட்டம் நம்மைச் சுற்றியிருக்கிற யாவையும் மேய்ந்துபோடும் என்றான் அக்காலத்திலே சிப்போரின் குமாரனாகிய பாலாக் மோவாபியருக்கு ராஜாவாயிருந்தான்.", "en": "And Moab said unto the elders of Midian, Now shall this company lick up all that are round about us, as the ox licketh up the grass of the field. And Balak the son of Zippor was king of the Moabites at that time."}, {"verse": 5, "start": 44.38, "end": 63.32, "ta": "அவன் பேயோரின் குமாரனாகிய பிலேயாமை அழைத்துவரும்படி, தன் சந்ததியாருடைய தேசத்தில் நதியருகேயுள்ள பெத்தூருக்கு ஸ்தானாபதிகளை அனுப்பி: எகிப்திலிருந்து ஒரு ஜனக்கூட்டம் வந்திருக்கிறது; அவர்கள் பூமியின் விசாலத்தை மூடி, எனக்கு எதிரே இறங்கியிருக்கிறார்கள்.", "en": "He sent messengers therefore unto Balaam the son of Beor to Pethor, which is by the river of the land of the children of his people, to call him, saying, Behold, there is a people come out from Egypt: behold, they cover the face of the earth, and they abide over against me:"}, {"verse": 6, "start": 63.32, "end": 87.61, "ta": "அவர்கள் என்னிலும் பலவான்கள்; ஆகிலும், நீர் ஆசீர்வதிக்கிறவன் ஆசீர்வதிக்கப்பட்டவன், நீர் சபிக்கிறவன் சபிக்கப்பட்டவன் என்று அறிவேன்; ஆதலால், நீர் வந்து, எனக்காக அந்த ஜனத்தைச் சபிக்கவேண்டும்; அப்பொழுது ஒருவேளை நான் அவர்களை முறிய அடித்து, அவர்களை இத்தேசத்திலிருந்து துரத்திவிடலாம் என்று சொல்லச்சொன்னான்.", "en": "Come now therefore, I pray thee, curse me this people; for they are too mighty for me: peradventure I shall prevail, that we may smite them, and that I may drive them out of the land: for I wot that he whom thou blessest is blessed, and he whom thou cursest is cursed."}, {"verse": 7, "start": 87.61, "end": 102.04, "ta": "அப்படியே மோவாபின் மூப்பரும் மீதியானின் மூப்பரும் குறிசொல்லுதலுக்குரிய கூலியைத் தங்கள் கையில் எடுத்துக்கொண்டு புறப்பட்டு, பிலேயாமிடத்தில் போய், பாலாகின் வார்த்தைகளை அவனுக்குச் சொன்னார்கள்.", "en": "And the elders of Moab and the elders of Midian departed with the rewards of divination in their hand; and they came unto Balaam, and spake unto him the words of Balak."}, {"verse": 8, "start": 102.04, "end": 116.9, "ta": "அவன் அவர்களை நோக்கி: இராத்திரிக்கு இங்கே தங்கியிருங்கள்; கர்த்தர் எனக்குச் சொல்லுகிறபடியே உங்களுக்கு உத்தரவு கொடுப்பேன் என்றான்; அப்படியே மோவாபின் பிரபுக்கள் பிலேயாமிடத்தில் தங்கினார்கள்.", "en": "And he said unto them, Lodge here this night, and I will bring you word again, as the LORD shall speak unto me: and the princes of Moab abode with Balaam."}, {"verse": 9, "start": 116.9, "end": 122.83, "ta": "தேவன் பிலேயாமிடத்தில் வந்து: உன்னிடத்திலிருக்கிற இந்த மனிதர் யார் என்றார்.", "en": "And God came unto Balaam, and said, What men are these with thee?"}, {"verse": 10, "start": 122.83, "end": 130.34, "ta": "பிலேயாம் தேவனை நோக்கி: சிப்போரின் குமாரனாகிய பாலாக் என்னும் மோவாபின் ராஜா அவர்களை என்னிடத்துக்கு அனுப்பி:", "en": "And Balaam said unto God, Balak the son of Zippor, king of Moab, hath sent unto me, saying ,"}, {"verse": 11, "start": 130.34, "end": 148.7, "ta": "பூமியின் விசாலத்தை மூடுகிற ஒரு ஜனக்கூட்டம் எகிப்திலிருந்து வந்திருக்கிறது; ஆகையால், நீ வந்து எனக்காக அவர்களைச் சபிக்கவேண்டும்; அப்பொழுது நான் அவர்களோடே யுத்தம் பண்ணி, ஒருவேளை அவர்களைத் துரத்திவிடலாம் என்று சொல்லச்சொன்னான் என்றான்.", "en": "Behold, there is a people come out of Egypt, which covereth the face of the earth: come now, curse me them; peradventure I shall be able to overcome them, and drive them out."}, {"verse": 12, "start": 148.7, "end": 159.77, "ta": "அதற்குத் தேவன் பிலேயாமை நோக்கி: நீ அவர்களோடே போகவேண்டாம்; அந்த ஜனங்களைச் சபிக்கவும் வேண்டாம்; அவர்கள் ஆசீர்வதிக்கப்பட்டவர்கள் என்றார்.", "en": "And God said unto Balaam, Thou shalt not go with them; thou shalt not curse the people: for they are blessed."}, {"verse": 13, "start": 159.77, "end": 174.78, "ta": "பிலேயாம் காலமே எழுந்து, பாலாகின் பிரபுக்களை நோக்கி: நீங்கள் உங்கள் தேசத்திற்குப் போய்விடுங்கள்; நான் உங்களோடேகூட வருகிறதற்குக் கர்த்தர் எனக்கு உத்தரவு கொடுக்கமாட்டோம் என்கிறார் என்று சொன்னான்.", "en": "And Balaam rose up in the morning, and said unto the princes of Balak, Get you into your land: for the LORD refuseth to give me leave to go with you."}, {"verse": 14, "start": 174.78, "end": 184.14, "ta": "அப்படியே மோவாபியருடைய பிரபுக்கள் எழுந்து, பாலாகினிடத்தில் போய்: பிலேயாம் எங்களோடே வரமாட்டேன் என்று சொன்னான் என்றார்கள்.", "en": "And the princes of Moab rose up, and they went unto Balak, and said, Balaam refuseth to come with us."}, {"verse": 15, "start": 184.14, "end": 189.71, "ta": "பாலாக் மறுபடியும் அவர்களிலும் கனவான்களான அதிக பிரபுக்களை அனுப்பினான்.", "en": "And Balak sent yet again princes, more, and more honourable than they."}, {"verse": 16, "start": 189.71, "end": 199.93, "ta": "அவர்கள் பிலேயாமிடத்தில் போய், அவனை நோக்கி: சிப்போரின் குமாரனாகிய பாலாக் எங்களை அனுப்பி: நீர் என்னிடத்தில் வருகிறதற்குத் தடைபடவேண்டாம்;", "en": "And they came to Balaam, and said to him, Thus saith Balak the son of Zippor, Let nothing, I pray thee, hinder thee from coming unto me:"}, {"verse": 17, "start": 199.93, "end": 211.57, "ta": "உம்மை மிகவும் கனம்பண்ணுவேன்; நீர் சொல்வதையெல்லாம் செய்வேன்; நீர் வந்து எனக்காக அந்த ஜனங்களைச் சபிக்கவேண்டும் என்று சொல்லச்சொன்னார் என்றார்கள்.", "en": "For I will promote thee unto very great honour, and I will do whatsoever thou sayest unto me: come therefore, I pray thee, curse me this people."}, {"verse": 18, "start": 211.57, "end": 228.36, "ta": "பிலேயாம் பாலாகின் ஊழியக்காரருக்கு பிரதியுத்தரமாக: பாலாக் எனக்குத் தன் வீடு நிறைய வெள்ளியும் பொன்னும் தந்தாலும், சிறிய காரியமானாலும் பெரியகாரியமானாலும் செய்யும்பொருட்டு, என் தேவனாகிய கர்த்தரின் கட்டளையை நான் மீறக் கூடாது.", "en": "And Balaam answered and said unto the servants of Balak, If Balak would give me his house full of silver and gold, I cannot go beyond the word of the LORD my God, to do less or more."}, {"verse": 19, "start": 228.36, "end": 238.51, "ta": "ஆகிலும், கர்த்தர் இனிமேல் எனக்கு என்ன சொல்லுவார் என்பதை நான் அறியும்படிக்கு நீங்களும் இந்த இராத்திரி இங்கே தங்கியிருங்கள் என்றான்.", "en": "Now therefore, I pray you, tarry ye also here this night, that I may know what the LORD will say unto me more."}, {"verse": 20, "start": 238.51, "end": 252.8, "ta": "இரவிலே தேவன் பிலேயாமிடத்தில் வந்து: அந்த மனிதர் உன்னைக் கூப்பிட வந்திருந்தால், நீ அவர்களோடே கூடப்போ; ஆனாலும் நான் உனக்குச் சொல்லும் வார்த்தையின்படிமாத்திரம் நீ செய்யவேண்டும் என்றார்.", "en": "And God came unto Balaam at night, and said unto him, If the men come to call thee, rise up, and go with them; but yet the word which I shall say unto thee, that shalt thou do."}, {"verse": 21, "start": 252.8, "end": 260.16, "ta": "பிலேயாம் காலமே எழுந்து, தன் கழுதையின்மேல் சேணங்கட்டி, மோவாபின் பிரபுக்களோடேகூடப் போனான்.", "en": "And Balaam rose up in the morning, and saddled his ass, and went with the princes of Moab."}, {"verse": 22, "start": 260.16, "end": 275.95, "ta": "அவன் போகிறதினாலே தேவனுக்குக் கோபம் மூண்டது; கர்த்தருடைய தூதனானவர் வழியிலே அவனுக்கு எதிராளியாக நின்றார். அவன் தன் கழுதையின் மேல் ஏறிப்போனான்; அவன் வேலைக்காரர் இரண்டுபேரும் அவனோடே இருந்தார்கள்.", "en": "And God’s anger was kindled because he went: and the angel of the LORD stood in the way for an adversary against him. Now he was riding upon his ass, and his two servants were with him."}, {"verse": 23, "start": 275.95, "end": 290.88, "ta": "கர்த்தருடைய தூதனானவர் உருவின பட்டயத்தைத் தம்முடைய கையிலே பிடித்துக்கொண்டு வழியிலே நிற்கிறதைக் கழுதை கண்டு, வழியை விட்டு வயலிலே விலகிப்போயிற்று; கழுதையை வழியில் திருப்ப பிலேயாம் அதை அடித்தான்.", "en": "And the ass saw the angel of the LORD standing in the way, and his sword drawn in his hand: and the ass turned aside out of the way, and went into the field: and Balaam smote the ass, to turn her into the way."}, {"verse": 24, "start": 290.88, "end": 298.74, "ta": "கர்த்தருடைய தூதனானவர் இருபுறத்திலும் சுவர் வைத்திருந்த திராட்சத் தோட்டங்களின் பாதையிலே போய் நின்றார்.", "en": "But the angel of the LORD stood in a path of the vineyards, a wall being on this side, and a wall on that side."}, {"verse": 25, "start": 298.74, "end": 308.81, "ta": "கழுதை கர்த்தருடைய தூதனைக்கண்டு, சுவர் ஓரமாய் ஒதுங்கி, பிலேயாமின் காலைச் சுவரோடே நெருக்கிற்று; திரும்பவும் அதை அடித்தான்.", "en": "And when the ass saw the angel of the LORD , she thrust herself unto the wall, and crushed Balaam’s foot against the wall: and he smote her again."}, {"verse": 26, "start": 308.81, "end": 317.32, "ta": "அப்பொழுது கர்த்தருடைய தூதன் அப்புறம் போய், வலதுபுறம் இடதுபுறம் விலக வழியில்லாத இடுக்கமான இடத்திலே நின்றார்.", "en": "And the angel of the LORD went further, and stood in a narrow place, where was no way to turn either to the right hand or to the left."}, {"verse": 27, "start": 317.32, "end": 327.82, "ta": "கழுதை கர்த்தருடைய தூதனைக் கண்டு, பிலேயாமின் கீழ்ப் படுத்துக்கொண்டது; பிலேயாம் கோபம் மூண்டவனாகி, கழுதையைத் தடியினால் அடித்தான்.", "en": "And when the ass saw the angel of the LORD , she fell down under Balaam: and Balaam’s anger was kindled, and he smote the ass with a staff."}, {"verse": 28, "start": 327.82, "end": 339.32, "ta": "உடனே கர்த்தர் கழுதையின் வாயைத் திறந்தார்; அது பிலேயாமைப் பார்த்து: நீர் என்னை இப்பொழுது மூன்று தரம் அடிக்கும்படி நான் உமக்கு என்ன செய்தேன் என்றது.", "en": "And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?"}, {"verse": 29, "start": 339.32, "end": 352.33, "ta": "அப்பொழுது பிலேயாம் கழுதையைப் பார்த்து: நீ என்னைப் பரியாசம் பண்ணிக்கொண்டு வருகிறாய்; என் கையில் ஒரு பட்டயம்மாத்திரம் இருந்தால் இப்பொழுதே உன்னைக் கொன்றுபோடுவேன் என்றான்.", "en": "And Balaam said unto the ass, Because thou hast mocked me: I would there were a sword in mine hand, for now would I kill thee."}, {"verse": 30, "start": 352.33, "end": 367.33, "ta": "கழுதை பிலேயாமை நோக்கி: நீர் என்னைக் கைக்கொண்ட காலமுதல் இந்நாள்வரைக்கும் நீர் ஏறின கழுதை நான் அல்லவா? இப்படி உமக்கு எப்போதாகிலும் நான் செய்தது உண்டா என்றது. அதற்கு அவன்: இல்லை என்றான்.", "en": "And the ass said unto Balaam, Am not I thine ass, upon which thou hast ridden ever since I was thine unto this day? was I ever wont to do so unto thee? And he said, Nay."}, {"verse": 31, "start": 367.33, "end": 381.05, "ta": "அப்பொழுது கர்த்தர் பிலேயாமின் கண்களைத் திறந்தார்; வழியிலே நின்று உருவின பட்டத்தைத் தம்முடைய கையிலே பிடித்திருக்கிற தூதனைக் கண்டு, தலைகுனிந்து முகங்குப்புற விழுந்து பணிந்தான்.", "en": "Then the LORD opened the eyes of Balaam, and he saw the angel of the LORD standing in the way, and his sword drawn in his hand: and he bowed down his head, and fell flat on his face."}, {"verse": 32, "start": 381.05, "end": 394.2, "ta": "கர்த்தருடைய தூதனானவர் அவனை நோக்கி: நீ உன் கழுதையை இதனோடே மூன்றுதரம் அடித்ததென்ன? உன் வழி எனக்கு மாறுபாடாயிருக்கிறதினால், நான் உனக்கு எதிரியாகப் புறப்பட்டு வந்தேன்.", "en": "And the angel of the LORD said unto him, Wherefore hast thou smitten thine ass these three times? behold, I went out to withstand thee, because thy way is perverse before me:"}, {"verse": 33, "start": 394.2, "end": 406.91, "ta": "கழுதை என்னைக் கண்டு, இந்த மூன்று தரம் எனக்கு விலகிற்று; எனக்கு விலகாமல் இருந்ததானால், இப்பொழுது நான் உன்னை கொன்றுபோட்டு, கழுதையை உயிரோடே வைப்பேன் என்றார்.", "en": "And the ass saw me, and turned from me these three times: unless she had turned from me, surely now also I had slain thee, and saved her alive."}, {"verse": 34, "start": 406.91, "end": 423.77, "ta": "அப்பொழுது பிலேயாம் கர்த்தருடைய தூதனை நோக்கி: நான் பாவஞ்செய்தேன்; வழியிலே நீர் எனக்கு எதிராக நிற்கிறதை அறியாதிருந்தேன்; இப்பொழுதும் உமது பார்வைக்கு இது தகாததாயிருக்குமானால், நான் திரும்பிப் போய்விடுகிறேன் என்றான்.", "en": "And Balaam said unto the angel of the LORD , I have sinned; for I knew not that thou stoodest in the way against me: now therefore, if it displease thee, I will get me back again."}, {"verse": 35, "start": 423.77, "end": 438.28, "ta": "கர்த்தருடைய தூதனானவர் பிலேயாமை நோக்கி: அந்த மனிதரோடே கூடப்போ; நான் உன்னோடே சொல்லும் வார்த்தையைமாத்திரம் நீ சொல்லக்கடவாய் என்றார்; அப்படியே பிலேயாம் பாலாகின் பிரபுக்களோடேகூடப் போனான்.", "en": "And the angel of the LORD said unto Balaam, Go with the men: but only the word that I shall speak unto thee, that thou shalt speak. So Balaam went with the princes of Balak."}, {"verse": 36, "start": 438.28, "end": 449.14, "ta": "பிலேயாம் வருகிறதைப் பாலாக் கேட்டமாத்திரத்தில், கடைசி எல்லையான அர்னோன் நதியின் ஓரத்திலுள்ள மோவாபின் பட்டணமட்டும் அவனுக்கு எதிர்கொண்டு போனான்.", "en": "And when Balak heard that Balaam was come, he went out to meet him unto a city of Moab, which is in the border of Arnon, which is in the utmost coast."}, {"verse": 37, "start": 449.14, "end": 463.5, "ta": "பாலாக் பிலேயாமை நோக்கி: உம்மை அழைக்கும்படி நான் ஆவலோடே உம்மிடத்தில் ஆள் அனுப்பவில்லையா? என்னிடத்திற்கு வராமல் இருந்ததென்ன? ஏற்றபிரகாரமாக உம்மை நான் கனம் பண்ணமாட்டேனா என்றான்.", "en": "And Balak said unto Balaam, Did I not earnestly send unto thee to call thee? wherefore camest thou not unto me? am I not able indeed to promote thee to honour?"}, {"verse": 38, "start": 463.5, "end": 476.93, "ta": "அப்பொழுது பிலேயாம் பாலாகை நோக்கி: இதோ, உம்மிடத்திற்கு வந்தேன்; ஆனாலும் ஏதாகிலும் சொல்லுகிறதற்கு என்னாலே ஆகுமோ: தேவன் என் வாயிலே அளிக்கும் வார்த்தையையே சொல்லுவேன் என்றான்.", "en": "And Balaam said unto Balak, Lo, I am come unto thee: have I now any power at all to say any thing? the word that God putteth in my mouth, that shall I speak."}, {"verse": 39, "start": 476.93, "end": 483.22, "ta": "பிலேயாம் பாலாகுடனேகூடப் போனான்; அவர்கள் கீரியாத் ஊசோத்தில் சேர்ந்தார்கள்.", "en": "And Balaam went with Balak, and they came unto Kirjath-huzoth."}, {"verse": 40, "start": 483.22, "end": 490.44, "ta": "அங்கே பாலாக் ஆடுமாடுகளை அடித்து, பிலேயாமுக்கும் அவனோடிருந்த பிரபுக்களுக்கும் அனுப்பினான்.", "en": "And Balak offered oxen and sheep, and sent to Balaam, and to the princes that were with him."}, {"verse": 41, "start": 490.44, "end": 502.94, "ta": "மறுநாள் காலமே பாலாக் பிலேயாமைக் கூட்டிக்கொண்டு, அவனைப் பாகாலுடைய மேடுகளில் ஏறப்பண்ணினான்; அவ்விடத்திலிருந்து பிலேயாம் ஜனத்தின் கடைசிப் பாளயத்தைப் பார்த்தான்.", "en": "And it came to pass on the morrow, that Balak took Balaam, and brought him up into the high places of Baal, that thence he might see the utmost part of the people."}]}, "23": {"chapter": 23, "duration": 346.13, "audio_url": "audio_ot/OT04_23.mp3", "total_verses": 30, "verses": [{"verse": 1, "start": 3.8, "end": 14.77, "ta": "பிலேயாம் பாலாகை நோக்கி: நீர் இங்கே எனக்கு ஏழு பலிபீடங்களைக் கட்டி, ஏழு காளைகளையும் ஏழு ஆட்டுக்கடாக்களையும் இங்கே எனக்கு ஆயத்தப்படுத்தும் என்றான்.", "en": "And Balaam said unto Balak, Build me here seven altars, and prepare me here seven oxen and seven rams."}, {"verse": 2, "start": 14.77, "end": 25.19, "ta": "பிலேயாம் சொன்னபடியே பாலாக் செய்தான்; பாலாகும் பிலேயாமும் ஒவ்வொரு பீடத்தில் ஒவ்வொரு காளையையும் ஒவ்வொரு ஆட்டுக்கடாவையும் பலியிட்டார்கள்.", "en": "And Balak did as Balaam had spoken; and Balak and Balaam offered on every altar a bullock and a ram."}, {"verse": 3, "start": 25.19, "end": 43.08, "ta": "பின்பு பிலேயாம் பாலாகை நோக்கி: உம்முடைய சர்வாங்க தகனபலியண்டையில் நில்லும், நான் போய்வருகிறேன்; கர்த்தர் வந்து என்னைச் சந்திக்கிறதாயிருக்கும்; அவர் எனக்கு வெளிப்படுத்துவதை உமக்கு அறிவிப்பேன் என்று சொல்லி, ஒரு மேட்டின்மேல் ஏறினான்.", "en": "And Balaam said unto Balak, Stand by thy burnt offering, and I will go: peradventure the LORD will come to meet me: and whatsoever he sheweth me I will tell thee. And he went to an high place."}, {"verse": 4, "start": 43.08, "end": 56.85, "ta": "தேவன் பிலேயாமைச் சந்தித்தார்; அப்பொழுது அவன் அவரை நோக்கி: நான் ஏழு பலிபீடங்களை ஆயத்தம் பண்ணி, ஒவ்வொரு பலிபீடத்தில் ஒவ்வொரு காளையையும் ஒவ்வொரு ஆட்டுக்கடாவையும் பலியிட்டேன் என்றான்.", "en": "And God met Balaam: and he said unto him, I have prepared seven altars, and I have offered upon every altar a bullock and a ram."}, {"verse": 5, "start": 56.85, "end": 65.45, "ta": "கர்த்தர் பிலேயாமின் வாயிலே வாக்கு அருளி: நீ பாலாகினிடத்தில் திரும்பிப்போய், இவ்விதமாய்ச் சொல்லக்கடவாய் என்றார்.", "en": "And the LORD put a word in Balaam’s mouth, and said, Return unto Balak, and thus thou shalt speak."}, {"verse": 6, "start": 65.45, "end": 75.31, "ta": "அவனிடத்துக்கு அவன் திரும்பிபோனான்; பாலாக் மோவாபுடைய சகல பிரபுக்களோடுங்கூடத் தன் சர்வாங்க தகனபலியண்டையிலே நின்றுகொண்டிருந்தான்.", "en": "And he returned unto him, and, lo, he stood by his burnt sacrifice, he, and all the princes of Moab."}, {"verse": 7, "start": 75.31, "end": 91.94, "ta": "அப்பொழுது அவன் தன் வாக்கியத்தை எடுத்துரைத்து: மோவாபின் ராஜாவாகிய பாலாக் என்னைக் கிழக்கு மலைகளிலுள்ள ஆராமிலிருந்து வரவழைத்து: நீ வந்து எனக்காக யாக்கோபைச் சபிக்கவேண்டும்; நீ வந்து இஸ்ரவேலை வெறுத்து விடவேண்டும் என்று சொன்னான்.", "en": "And he took up his parable, and said, Balak the king of Moab hath brought me from Aram, out of the mountains of the east, saying , Come, curse me Jacob, and come, defy Israel."}, {"verse": 8, "start": 91.94, "end": 98.79, "ta": "தேவன் சபிக்காதவனை நான் சபிப்பதெப்படி? கர்த்தர் வெறுக்காதவனை நான் வெறுப்பதெப்படி?", "en": "How shall I curse, whom God hath not cursed? or how shall I defy, whom the LORD hath not defied?"}, {"verse": 9, "start": 98.79, "end": 109.63, "ta": "கன்மலையுச்சியிலிருந்து நான் அவனைக் கண்டு, குன்றுகளிலிருந்து அவனைப் பார்க்கிறேன்; அந்த ஜனங்கள் ஜாதிகளோடே கலவாமல் தனியே வாசமாயிருப்பார்கள்.", "en": "For from the top of the rocks I see him, and from the hills I behold him: lo, the people shall dwell alone, and shall not be reckoned among the nations."}, {"verse": 10, "start": 109.63, "end": 122.91, "ta": "யாக்கோபின் தூளை எண்ணத்தக்கவன் யார்? இஸ்ரவேலின் காற்பங்கை எண்ணுகிறவன் யார்? நீதிமான் மரிப்பது போல் நான் மரிப்பேனாக, என் முடிவு அவன் முடிவுபோல் இருப்பதாக என்றான்.", "en": "Who can count the dust of Jacob, and the number of the fourth part of Israel? Let me die the death of the righteous, and let my last end be like his!"}, {"verse": 11, "start": 122.91, "end": 135.77, "ta": "அப்பொழுது பாலாக் பிலேயாமை நோக்கி: நீர் எனக்கு என்னசெய்தீர்; என் சத்துருக்களைச் சபிக்கும்படி உம்மை அழைப்பித்தேன்; நீர் அவர்களை ஆசீர்வதிக்கவே ஆசீர்வதித்தீர் என்றான்.", "en": "And Balak said unto Balaam, What hast thou done unto me? I took thee to curse mine enemies, and, behold, thou hast blessed them altogether."}, {"verse": 12, "start": 135.77, "end": 141.64, "ta": "அதற்கு அவன்: கர்த்தர் என் வாயில் அருளினதையே சொல்வது என் கடமையல்லவா என்றான்.", "en": "And he answered and said, Must I not take heed to speak that which the LORD hath put in my mouth?"}, {"verse": 13, "start": 141.64, "end": 159.47, "ta": "பின்பு பாலாக் அவனை நோக்கி: நீர் அவர்களைப் பார்க்கத்தக்க வேறொரு இடத்திற்கு என்னோடேகூட வாரும்; அங்கே அவர்கள் எல்லாரையும் பாராமல், அவர்களுடைய கடைசிப் பாளயத்தைமாத்திரம் பார்ப்பீர்; அங்கேயிருந்து எனக்காக அவர்களைச் சபிக்கவேண்டும் என்று சொல்லி,", "en": "And Balak said unto him, Come, I pray thee, with me unto another place, from whence thou mayest see them: thou shalt see but the utmost part of them, and shalt not see them all: and curse me them from thence."}, {"verse": 14, "start": 159.47, "end": 173.17, "ta": "அவனைப் பிஸ்காவின் கொடுமுடியில் இருக்கிற சோப்பீமீன் வெளியிலே அழைத்துக்கொண்டுபோய், ஏழு பலி பீடங்களைக் கட்டி, ஒவ்வொரு பீடத்தில் ஒவ்வொரு காளையையும் ஒவ்வொரு ஆட்டுக்கடாவையும் பலியிட்டான்.", "en": "And he brought him into the field of Zophim, to the top of Pisgah, and built seven altars, and offered a bullock and a ram on every altar."}, {"verse": 15, "start": 173.17, "end": 184.0, "ta": "அப்பொழுது பிலேயாம் பாலாகை நோக்கி: இங்கே உம்முடைய சர்வாங்க தகனபலியண்டையில் நில்லும்; நான் அங்கே போய்க் கர்த்தரைச் சந்தித்துவருகிறேன் என்றான்.", "en": "And he said unto Balak, Stand here by thy burnt offering, while I meet the Lord yonder."}, {"verse": 16, "start": 184.0, "end": 194.14, "ta": "கர்த்தர் பிலேயாமைச் சந்தித்து, அவன் வாயிலே வசனத்தை அருளி: நீ பாலாகினிடத்திற்குத் திரும்பிபோய், இவ்விதமாய்ச் சொல்லக்கடவாய் என்றார்.", "en": "And the LORD met Balaam, and put a word in his mouth, and said, Go again unto Balak, and say thus."}, {"verse": 17, "start": 194.14, "end": 207.84, "ta": "அவனிடத்திற்கு அவன் வருகிறபோது, அவன் மோவாபின் பிரபுக்களோடுங்கூடத் தன்னுடைய சர்வாங்கதகனபலியண்டையிலே நின்றுகொண்டிருந்தான்; பாலாக் அவனை நோக்கி: கர்த்தர் என்ன சொன்னார் என்று கேட்டான்.", "en": "And when he came to him, behold, he stood by his burnt offering, and the princes of Moab with him. And Balak said unto him, What hath the LORD spoken?"}, {"verse": 18, "start": 207.84, "end": 217.41, "ta": "அப்பொழுது அவன் தன் வாக்கியத்தை எடுத்துரைத்து: பாலாகே, எழுந்திருந்து கேளும்; சிப்போரின் குமாரனே, எனக்குச் செவிகொடும்.", "en": "And he took up his parable, and said, Rise up, Balak, and hear; hearken unto me, thou son of Zippor:"}, {"verse": 19, "start": 217.41, "end": 229.51, "ta": "பொய் சொல்ல தேவன் ஒரு மனிதன் அல்ல; மனம்மாற அவர் ஒரு மனுபுத்திரனும் அல்ல; அவர் சொல்லியும் செய்யாதிருப்பாரா? அவர் வசனித்தும் நிறைவேற்றாதிருப்பாரா?", "en": "God is not a man, that he should lie; neither the son of man, that he should repent: hath he said, and shall he not do it ? or hath he spoken, and shall he not make it good?"}, {"verse": 20, "start": 229.51, "end": 236.84, "ta": "இதோ, ஆசீர்வதிக்கக் கட்டளைபெற்றேன்; அவர் ஆசீர்வதிக்கிறார், அதை நான் திருப்பக் கூடாது.", "en": "Behold, I have received commandment to bless: and he hath blessed; and I cannot reverse it."}, {"verse": 21, "start": 236.84, "end": 251.73, "ta": "அவர் யாக்கோபிலே அக்கிரமத்தைக் காண்கிறதும் இல்லை, இஸ்ரவேலிலே குற்றம் பார்க்கிறதும் இல்லை; அவர்களுடைய தேவனாகிய கர்த்தர் அவர்களோடே இருக்கிறார்; ராஜாவின் ஜயகெம்பீரம் அவர்களுக்குள்ளே இருக்கிறது.", "en": "He hath not beheld iniquity in Jacob, neither hath he seen perverseness in Israel: the LORD his God is with him, and the shout of a king is among them."}, {"verse": 22, "start": 251.73, "end": 259.56, "ta": "தேவன் அவர்களை எகிப்திலிருந்து புறப்படப்பண்ணினார்; காண்டாமிருகத்துக்கொத்த பெலன் அவர்களுக்கு உண்டு.", "en": "God brought them out of Egypt; he hath as it were the strength of an unicorn."}, {"verse": 23, "start": 259.56, "end": 273.68, "ta": "யாக்கோபுக்கு விரோதமான மந்திரவாதம் இல்லை, இஸ்ரவேலுக்கு விரோதமான குறிசொல்லுதலும் இல்லை; தேவன் என்னென்ன செய்தார் என்று கொஞ்சக் காலத்திலே யாக்கோபையும் இஸ்ரவேலையும் குறித்துச் சொல்லப்படும்.", "en": "Surely there is no enchantment against Jacob, neither is there any divination against Israel: according to this time it shall be said of Jacob and of Israel, What hath God wrought!"}, {"verse": 24, "start": 273.68, "end": 288.08, "ta": "அந்த ஜனம் துஷ்ட சிங்கம்போல எழும்பும், பால சிங்கம்போல நிமிர்ந்து நிற்கும்; அது தான் பிடித்த இரையைப் பட்சித்து, வெட்டுண்டவர்களின் இரத்தத்தைக் குடிக்குமட்டும் படுத்துக்கொள்வதில்லை என்றான்.", "en": "Behold, the people shall rise up as a great lion, and lift up himself as a young lion: he shall not lie down until he eat of the prey, and drink the blood of the slain."}, {"verse": 25, "start": 288.08, "end": 296.68, "ta": "அப்பொழுது பாலாக் பிலேயாமை நோக்கி: நீர் அவர்களைச் சபிக்கவும் வேண்டாம், அவர்களை ஆசீர்வதிக்கவும் வேண்டாம் என்றான்.", "en": "And Balak said unto Balaam, Neither curse them at all, nor bless them at all."}, {"verse": 26, "start": 296.68, "end": 305.49, "ta": "அதற்குப் பிலேயாம் பாலாகைப் பார்த்து: கர்த்தர் சொல்லுகிறபடியெல்லாம் செய்வேன் என்று உம்மோடே நான் சொல்லவில்லையா என்றான்.", "en": "But Balaam answered and said unto Balak, Told not I thee, saying, All that the LORD speaketh, that I must do?"}, {"verse": 27, "start": 305.49, "end": 319.05, "ta": "அப்பொழுது பாலாக் பிலேயாமை நோக்கி: வாரும் வேறொரு இடத்திற்கு உம்மை அழைத்துக்கொண்டு போகிறேன்; நீர் அங்கேயிருந்தாவது எனக்காக அவர்களைச் சபிக்கிறது தேவனுக்குப் பிரியமாயிருக்கும் என்று சொல்லி,", "en": "And Balak said unto Balaam, Come, I pray thee, I will bring thee unto another place; peradventure it will please God that thou mayest curse me them from thence."}, {"verse": 28, "start": 319.05, "end": 325.06, "ta": "அவனை எஷிமோனுக்கு எதிராயிருக்கிற பேயோரின் கொடுமுடிக்கு அழைத்துக்கொண்டு போனான்.", "en": "And Balak brought Balaam unto the top of Peor, that looketh toward Jeshimon."}, {"verse": 29, "start": 325.06, "end": 336.31, "ta": "அப்பொழுது பிலேயாம் பாலாகை நோக்கி: இங்கே எனக்கு ஏழு பலிபீடங்களைக் கட்டி, இங்கே எனக்கு ஏழு காளைகளையும் ஏழு ஆட்டுக் கடாக்களையும் ஆயத்தம்பண்ணும் என்றான்.", "en": "And Balaam said unto Balak, Build me here seven altars, and prepare me here seven bullocks and seven rams."}, {"verse": 30, "start": 336.31, "end": 344.63, "ta": "பிலேயாம் சொன்னபடி பாலாக் செய்து, ஒவ்வொரு பீடத்தில் ஒவ்வொரு காளையையும் ஒவ்வொரு ஆட்டுக்கடாவையும் பலியிட்டான்.", "en": "And Balak did as Balaam had said, and offered a bullock and a ram on every altar."}]}, "24": {"chapter": 24, "duration": 281.28, "audio_url": "audio_ot/OT04_24.mp3", "total_verses": 25, "verses": [{"verse": 1, "start": 3.8, "end": 16.81, "ta": "இஸ்ரவேலை ஆசீர்வதிப்பதே கர்த்தருக்குப் பிரியம் என்று பிலேயாம் கண்ட போது, அவன் முந்திச் செய்துவந்தது போல நிமித்தம்பார்க்கப் போகாமல், வனாந்தரத்திற்கு நேராக தன் முகத்தைத் திருப்பி,", "en": "And when Balaam saw that it pleased the LORD to bless Israel, he went not, as at other times, to seek for enchantments, but he set his face toward the wilderness."}, {"verse": 2, "start": 16.81, "end": 26.23, "ta": "தன் கண்களை ஏறெடுத்து, இஸ்ரவேல் தன் கோத்திரங்களின்படியே பாளயமிறங்கியிருக்கிறதைப் பார்த்தான்; தேவ ஆவி அவன்மேல் வந்தது.", "en": "And Balaam lifted up his eyes, and he saw Israel abiding in his tents according to their tribes; and the spirit of God came upon him."}, {"verse": 3, "start": 26.23, "end": 35.44, "ta": "அப்பொழுது அவன் தன் வாக்கியத்தை எடுத்துரைத்து: பேயோரின் குமாரனாகிய பிலேயாம் சொல்லுகிறதாவது, கண் திறக்கப்பட்டவன் உரைக்கிறதாவது,", "en": "And he took up his parable, and said, Balaam the son of Beor hath said, and the man whose eyes are open hath said:"}, {"verse": 4, "start": 35.44, "end": 44.51, "ta": "தேவன் அருளும் வார்த்தைகளைக் கேட்டு, சர்வவல்லவரின் தரிசனத்தைக் கண்டு தாழ விழும் போது, கண்திறக்கப்பட்டவன் விளம்புகிறதாவது,", "en": "He hath said, which heard the words of God, which saw the vision of the Almighty, falling into a trance , but having his eyes open:"}, {"verse": 5, "start": 44.51, "end": 50.49, "ta": "யாக்கோபே, உன் கூடாரங்களும், இஸ்ரவேலே, உன் வாசஸ்தலங்களும் எவ்வளவு அழகானவைகள்!", "en": "How goodly are thy tents, O Jacob, and thy tabernacles, O Israel!"}, {"verse": 6, "start": 50.49, "end": 63.92, "ta": "அவைகள் பரவிப்போகிற ஆறுகளைப் போலவும், நதியோரத்திலுள்ள தோட்டங்களைப்போலவும், கர்த்தர் நாட்டின சந்தனமரங்களைப்போலவும், தண்ணீர் அருகே உள்ள கேதுரு விருட்சங்களைப்போலவும் இருக்கிறது.", "en": "As the valleys are they spread forth, as gardens by the river’s side, as the trees of lign aloes which the LORD hath planted, and as cedar trees beside the waters."}, {"verse": 7, "start": 63.92, "end": 77.7, "ta": "அவர்களுடைய நீர்ச்சால்களிலிருந்து தண்ணீர் பாயும்; அவர்கள் வித்து திரளான தண்ணீர்களில் பரவும்; அவர்களுடைய ராஜா ஆகாகைப் பார்க்கிலும் உயருவான்; அவர்கள் ராஜ்யம் மேன்மையடையும்.", "en": "He shall pour the water out of his buckets, and his seed shall be in many waters, and his king shall be higher than Agag, and his kingdom shall be exalted."}, {"verse": 8, "start": 77.7, "end": 94.93, "ta": "தேவன் அவர்களை எகிப்திலிருந்து புறப்படப்பண்ணினார்; காண்டாமிருகத்துக்கொத்த பெலன் அவர்களுக்கு உண்டு; அவர்கள் தங்கள் சத்துருக்களாகிய ஜாதிகளைப் பட்சித்து, அவர்கள் எலும்புகளை நொறுக்கி, அவர்களைத் தங்கள் அம்புகளாலே எய்வார்கள்.", "en": "God brought him forth out of Egypt; he hath as it were the strength of an unicorn: he shall eat up the nations his enemies, and shall break their bones, and pierce them through with his arrows."}, {"verse": 9, "start": 94.93, "end": 110.47, "ta": "சிங்கம்போலவும் துஷ்ட சிங்கம்போலவும் மடங்கிப் படுத்துக்கொண்டிருக்கிறார்கள்; அவர்களை எழுப்புகிறவன் யார்? உங்களை ஆசீர்வதிக்கிறவன் ஆசீர்வதிக்கப்பட்டவன், உங்களைச் சபிக்கிறவன் சபிக்கப்பட்டவன் என்றான்.", "en": "He couched, he lay down as a lion, and as a great lion: who shall stir him up? Blessed is he that blesseth thee, and cursed is he that curseth thee."}, {"verse": 10, "start": 110.47, "end": 125.93, "ta": "அப்பொழுது பாலாக் பிலேயாமின் மேல் கோபம் மூண்டவனாகி, கையோடே கைதட்டி, பிலேயாமை நோக்கி: என் சத்துருக்களைச் சபிக்க உன்னை அழைத்தனுப்பினேன். நீயோ இந்த மூன்றுமுறையும் அவர்களை ஆசீர்வதிக்கவே ஆசீர்வதித்தாய்.", "en": "And Balak’s anger was kindled against Balaam, and he smote his hands together: and Balak said unto Balaam, I called thee to curse mine enemies, and, behold, thou hast altogether blessed them these three times."}, {"verse": 11, "start": 125.93, "end": 135.64, "ta": "ஆகையால் உன் இடத்துக்கு ஓடிப்போ; உன்னை மிகவும் கனம்பண்ணுவேன் என்றேன்; நீ கனமடையாதபடிக்குக் கர்த்தர் தடுத்தார் என்றான்.", "en": "Therefore now flee thou to thy place: I thought to promote thee unto great honour; but, lo, the LORD hath kept thee back from honour."}, {"verse": 12, "start": 135.64, "end": 152.16, "ta": "அப்பொழுது பிலேயாம் பாலாகை நோக்கி: பாலாக் எனக்கு தன் வீடு நிறைய வெள்ளியும் பொன்னும் கொடுத்தாலும், நான் என் மனதாய் நன்மையாகிலும் தீமையாகிலும் செய்கிறதற்குக் கர்த்தரின் கட்டளையை மீறக் கூடாது; கர்த்தர் சொல்வதையே சொல்வேன் என்று,", "en": "And Balaam said unto Balak, Spake I not also to thy messengers which thou sentest unto me, saying,"}, {"verse": 13, "start": 152.16, "end": 157.58, "ta": "நீர் என்னிடத்திற்கு அனுப்பின ஸ்தானாபதிகளிடத்தில் நான் சொல்லவில்லையா?", "en": "If Balak would give me his house full of silver and gold, I cannot go beyond the commandment of the LORD , to do either good or bad of mine own mind; but what the LORD saith, that will I speak?"}, {"verse": 14, "start": 157.58, "end": 169.32, "ta": "இதோ, நான் என் ஜனத்தாரிடத்திற்குப் போகிறேன்; பிற்காலத்திலே இந்த ஜனங்கள் உம்முடைய ஜனங்களுக்குச் செய்வது இன்னதென்று உமக்குத் தெரிவிப்பேன் வாரும் என்று சொல்லி,", "en": "And now, behold, I go unto my people: come therefore, and I will advertise thee what this people shall do to thy people in the latter days."}, {"verse": 15, "start": 169.32, "end": 177.61, "ta": "அவன் தன் வாக்கியத்தை எடுத்துரைத்து: பேயோரின் குமாரன் பிலேயாம் சொல்லுகிறதாவது, கண் திறக்கப்பட்டவன் உரைக்கிறதாவது,", "en": "And he took up his parable, and said, Balaam the son of Beor hath said, and the man whose eyes are open hath said:"}, {"verse": 16, "start": 177.61, "end": 189.36, "ta": "தேவன் அருளும் வார்த்தைகளைக் கேட்டு, உன்னதமானவர் அளித்த அறிவை அறிந்து, சர்வவல்லவரின் தரிசனத்தைக் கண்டு தாழவிழும்போது, கண்திறக்கப்பட்டவன் விளம்புகிறதாவது;", "en": "He hath said, which heard the words of God, and knew the knowledge of the most High, which saw the vision of the Almighty, falling into a trance , but having his eyes open:"}, {"verse": 17, "start": 189.36, "end": 208.06, "ta": "அவரைக் காண்பேன், இப்பொழுது அல்ல; அவரைத் தரிசிப்பேன், சமீபமாய் அல்ல; ஒரு நட்சத்திரம் யாக்கோபிலிருந்து உதிக்கும், ஒரு செங்கோல் இஸ்ரவேலிலிருந்து எழும்பும்; அது மோவாபின் எல்லைகளை நொறுக்கி, சேத்புத்திரர் எல்லாரையும் நிர்மூலமாக்கும்.", "en": "I shall see him, but not now: I shall behold him, but not nigh: there shall come a Star out of Jacob, and a Sceptre shall rise out of Israel, and shall smite the corners of Moab, and destroy all the children of Sheth."}, {"verse": 18, "start": 208.06, "end": 216.01, "ta": "ஏதோம் சுதந்தரமாகும், சேயீர் தன் சத்துருக்களுக்குச் சுதந்தரமாகும்; இஸ்ரவேல் பராக்கிரமஞ்செய்யும்.", "en": "And Edom shall be a possession, Seir also shall be a possession for his enemies; and Israel shall do valiantly."}, {"verse": 19, "start": 216.01, "end": 223.67, "ta": "யாக்கோபிலிருந்து தோன்றும் ஒருவர் ஆளுகை செய்வார்; பட்டணங்களில் மீதியானவர்களை அழிப்பார் என்றான்.", "en": "Out of Jacob shall come he that shall have dominion, and shall destroy him that remaineth of the city."}, {"verse": 20, "start": 223.67, "end": 235.41, "ta": "மேலும், அவன் அமலேக்கைப் பார்த்து, தன் வாக்கியத்தை எடுத்துரைத்து: அமலேக்கு முந்தியெழும்பினவன்; ஆனாலும் அவன் முடிவிலே முற்றிலும் நாசமடைவான் என்றான்.", "en": "And when he looked on Amalek, he took up his parable, and said, Amalek was the first of the nations; but his latter end shall be that he perish for ever."}, {"verse": 21, "start": 235.41, "end": 245.61, "ta": "அன்றியும் அவன் கேனியனைப் பார்த்து, தன் வாக்கியத்தை எடுத்துரைத்து: உன் வாசஸ்தலம் அரணிப்பானது; உன் கூட்டைக் கன்மலையில் கட்டினாய்.", "en": "And he looked on the Kenites, and took up his parable, and said, Strong is thy dwellingplace, and thou puttest thy nest in a rock."}, {"verse": 22, "start": 245.61, "end": 253.55, "ta": "ஆகிலும் கேனியன் அழிந்துபோவான்; அசூர் உன்னைச் சிறைபிடித்துக் கொண்டுபோக எத்தனைநாள் செல்லும் என்றான்.", "en": "Nevertheless the Kenite shall be wasted, until Asshur shall carry thee away captive."}, {"verse": 23, "start": 253.55, "end": 260.58, "ta": "பின்னும் அவன் தன் வாக்கியத்தை எடுத்துரைத்து: ஐயோ, தேவன் இதைச் செய்யும்போது யார் பிழைப்பான்;", "en": "And he took up his parable, and said, Alas, who shall live when God doeth this!"}, {"verse": 24, "start": 260.58, "end": 271.98, "ta": "சித்தீமின் கரைதுறையிலிருந்து கப்பல்கள் வந்து, அசூரைச் சிறுமைப் படுத்தி, ஏபேரையும் வருத்தப்படுத்தும்; அவனும் முற்றிலும் அழிந்துபோவான் என்றான்.", "en": "And ships shall come from the coast of Chittim, and shall afflict Asshur, and shall afflict Eber, and he also shall perish for ever."}, {"verse": 25, "start": 271.98, "end": 279.78, "ta": "பின்பு பிலேயாம் எழுந்து புறப்பட்டு, தன் இடத்திற்குத் திரும்பினான்; பாலாகும் தன் வழியே போனான்.", "en": "And Balaam rose up, and went and returned to his place: and Balak also went his way."}]}, "25": {"chapter": 25, "duration": 208.98, "audio_url": "audio_ot/OT04_25.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 12.33, "ta": "இஸ்ரவேல் சித்தீமிலே தங்கியிருக்கையில், ஜனங்கள் மோவாபின் குமாரத்திகளோடே வேசித்தனம் பண்ணத்தொடங்கினார்கள்.", "en": "And Israel abode in Shittim, and the people began to commit whoredom with the daughters of Moab."}, {"verse": 2, "start": 12.33, "end": 24.27, "ta": "அவர்கள் தங்கள் தேவர்களுக்கு இட்ட பலிகளை விருந்துண்ணும்படி ஜனங்களை அழைத்தார்கள்; ஜனங்கள் போய் புசித்து, அவர்கள் தேவர்களைப் பணிந்துக்கொண்டார்கள்.", "en": "And they called the people unto the sacrifices of their gods: and the people did eat, and bowed down to their gods."}, {"verse": 3, "start": 24.27, "end": 32.8, "ta": "இப்படி இஸ்ரவேலர் பாகால்பேயோரைப் பற்றிக்கொண்டார்கள்; அதனால் இஸ்ரவேலர் மேல் கர்த்தருடைய கோபம் மூண்டது.", "en": "And Israel joined himself unto Baal-peor: and the anger of the LORD was kindled against Israel."}, {"verse": 4, "start": 32.8, "end": 50.53, "ta": "கர்த்தர் மோசேயை நோக்கி: கர்த்தருடைய உக்கிரமான கோபம் இஸ்ரவேலை விட்டு நீங்கும்படி நீ ஜனங்களின் தலைவர் எல்லாரையும் கூட்டிக்கொண்டு, அப்படிச் செய்தவர்களைச் சூரியனுக்கு எதிரே கர்த்தருடைய சந்நிதானத்தில் தூக்கிப்போடும்படி செய் என்றார்.", "en": "And the LORD said unto Moses, Take all the heads of the people, and hang them up before the LORD against the sun, that the fierce anger of the LORD may be turned away from Israel."}, {"verse": 5, "start": 50.53, "end": 60.91, "ta": "அப்படியே மோசே இஸ்ரவேலின் நியாயாதிபதிகளை நோக்கி: நீங்கள் அவரவர் பாகால்பேயோரைப் பற்றிக்கொண்ட உங்கள் மனிதரைக் கொன்றுபோடுங்கள் என்றான்.", "en": "And Moses said unto the judges of Israel, Slay ye every one his men that were joined unto Baal-peor."}, {"verse": 6, "start": 60.91, "end": 79.53, "ta": "அப்பொழுது மோசேயும் இஸ்ரவேல் புத்திரராகிய சபையார் அனைவரும் ஆசரிப்புக் கூடாரவாசலுக்கு முன்பாக அழுதுகொண்டு நிற்கையில், அவர்கள் கண்களுக்கு முன்பாக இஸ்ரவேல் புத்திரரில் ஒருவன் ஒரு மீதியானிய ஸ்திரீயைத் தன் சகோதரரிடத்தில் அழைத்துக் கொண்டுவந்தான்.", "en": "And, behold, one of the children of Israel came and brought unto his brethren a Midianitish woman in the sight of Moses, and in the sight of all the congregation of the children of Israel, who were weeping before the door of the tabernacle of the congregation."}, {"verse": 7, "start": 79.53, "end": 90.29, "ta": "அதை ஆசாரியனாகிய ஆரோனின் குமாரனான எலெயாசாரின் மகன் பினெகாஸ் கண்டபோது, அவன் நடுச்சபையிலிருந்து எழுந்து, ஒரு ஈட்டியைத் தன் கையிலே பிடித்து,", "en": "And when Phinehas, the son of Eleazar, the son of Aaron the priest, saw it , he rose up from among the congregation, and took a javelin in his hand;"}, {"verse": 8, "start": 90.29, "end": 108.9, "ta": "இஸ்ரவேலனாகிய அந்த மனிதன் வேசித்தனம்பண்ணும் அறையிலே அவன் பின்னாலே போய், இஸ்ரவேல் மனிதனும் அந்த ஸ்திரீயுமாகிய இருவருடைய வயிற்றிலும் ஈட்டி உருவிப்போக அவர்களைக் குத்திப்போட்டான்; அப்பொழுது இஸ்ரவேல் புத்திரரில் உண்டான வாதை நின்றுபோயிற்று.", "en": "And he went after the man of Israel into the tent, and thrust both of them through, the man of Israel, and the woman through her belly. So the plague was stayed from the children of Israel."}, {"verse": 9, "start": 108.9, "end": 113.21, "ta": "அந்த வாதையால் செத்தவர்கள் இருபத்துநாலாயிரம் பேர்.", "en": "And those that died in the plague were twenty and four thousand."}, {"verse": 10, "start": 113.21, "end": 114.91, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 11, "start": 114.91, "end": 134.27, "ta": "நான் என் எரிச்சலில் இஸ்ரவேல் புத்திரரை நிர்மூலமாக்காதபடிக்கு, ஆசாரியனாகிய ஆரோனின் குமாரனான எலெயாசாரின் மகன் பினெகாஸ், என் நிமித்தம் அவர்கள் நடுவில் பக்திவைராக்கியம் காண்பித்ததினால், இஸ்ரவேல் புத்திரர் மேல் உண்டான என் உக்கிரத்தைத் திருப்பினான்.", "en": "Phinehas, the son of Eleazar, the son of Aaron the priest, hath turned my wrath away from the children of Israel, while he was zealous for my sake among them, that I consumed not the children of Israel in my jealousy."}, {"verse": 12, "start": 134.27, "end": 140.8, "ta": "ஆகையால், இதோ, அவனுக்கு என் சமாதானத்தின் உடன்படிக்கையைக் கட்டளையிடுகிறேன்.", "en": "Wherefore say, Behold, I give unto him my covenant of peace:"}, {"verse": 13, "start": 140.8, "end": 158.9, "ta": "அவன் தன் தேவனுக்காக பக்திவைராக்கியம் காண்பித்து, இஸ்ரவேல் புத்திரருக்காகப் பாவநிவர்த்தி செய்தபடியினால், அவனுக்கும் அவனுக்குப் பின்பு அவன் சந்ததிக்கும் நித்திய ஆசாரிய பட்டத்திற்குரிய உடன்படிக்கை உண்டாயிருக்கும் என்று சொல் என்றார்.", "en": "And he shall have it, and his seed after him, even the covenant of an everlasting priesthood; because he was zealous for his God, and made an atonement for the children of Israel."}, {"verse": 14, "start": 158.9, "end": 171.65, "ta": "மீதியானிய ஸ்திரீயோடே குத்துண்டு செத்த இஸ்ரவேல் மனிதனுடைய பேர் சிம்ரி; அவன் சல்லுூவின் குமாரனும், சிமியோனியரின் தகப்பன் வம்சத்தில் ஒரு பிரபுவுமாயிருந்தான்.", "en": "Now the name of the Israelite that was slain, even that was slain with the Midianitish woman, was Zimri, the son of Salu, a prince of a chief house among the Simeonites."}, {"verse": 15, "start": 171.65, "end": 182.93, "ta": "குத்துண்ட மீதியானிய ஸ்திரீயின் பேர் கஸ்பி, அவள் சூரின் குமாரத்தி, அவன் மீதியானியருடைய தகப்பன் வம்சத்தாரான ஜனங்களுக்குத் தலைவனாயிருந்தான்.", "en": "And the name of the Midianitish woman that was slain was Cozbi, the daughter of Zur; he was head over a people, and of a chief house in Midian."}, {"verse": 16, "start": 182.93, "end": 184.63, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 17, "start": 184.63, "end": 188.79, "ta": "மீதியானியரை நெருக்கி அவர்களை வெட்டிப்போடுங்கள்.", "en": "Vex the Midianites, and smite them:"}, {"verse": 18, "start": 188.79, "end": 207.48, "ta": "பேயோரின் சங்கதியிலும் பேயோரின் நிமித்தம் வாதையுண்டான நாளிலே குத்துண்ட அவர்கள் சகோதரியாகிய கஸ்பி என்னும் மீதியான் பிரபுவினுடைய குமாரத்தியின் சங்கதியிலும், அவர்கள் உங்களுக்குச் செய்த சர்ப்பனைகளினால் உங்களை மோசம்போக்கி நெருக்கினார்களே என்றார்.", "en": "For they vex you with their wiles, wherewith they have beguiled you in the matter of Peor, and in the matter of Cozbi, the daughter of a prince of Midian, their sister, which was slain in the day of the plague for Peor’s sake."}]}, "26": {"chapter": 26, "duration": 670.3, "audio_url": "audio_ot/OT04_26.mp3", "total_verses": 65, "verses": [{"verse": 1, "start": 3.8, "end": 11.7, "ta": "அந்த வாதை தீர்ந்தபின்பு, கர்த்தர் மோசேயையும் ஆரோனின் குமாரனும் ஆசாரியனுமாகிய எலெயாசாரையும் நோக்கி:", "en": "And it came to pass after the plague, that the LORD spake unto Moses and unto Eleazar the son of Aaron the priest, saying,"}, {"verse": 2, "start": 11.7, "end": 26.72, "ta": "இஸ்ரவேல் புத்திரரின் சமஸ்த சபையாரையும் அவர்கள் பிதாக்களுடைய வம்சத்தின்படி இருபது வயதுமுதல் அதற்கு மேற்பட்ட இஸ்ரவேலிலே யுத்ததிற்குப் புறப்படத்தக்கவர்கள் எல்லாரையும் எண்ணுங்கள் என்றார்.", "en": "Take the sum of all the congregation of the children of Israel, from twenty years old and upward, throughout their fathers’ house, all that are able to go to war in Israel."}, {"verse": 3, "start": 26.72, "end": 36.89, "ta": "அப்பொழுது மோசேயும் ஆசாரியனாகிய எலெயாசாரும் எரிகோவின் அருகே இருக்கும் யோர்தானுக்கு இப்பாலே மோவாபின் சமனான வெளிகளிலே அவர்களோடே பேசி:", "en": "And Moses and Eleazar the priest spake with them in the plains of Moab by Jordan near Jericho, saying,"}, {"verse": 4, "start": 36.89, "end": 50.5, "ta": "கர்த்தர் மோசேக்கும் எகிப்துதேசத்திலிருந்து புறப்பட்ட இஸ்ரவேல் புத்திரருக்கும் கட்டளையிட்டிருக்கிறபடியே, இருபது வயதுமுதற்கொண்டிருக்கிறவர்களை எண்ணுங்கள் என்றார்கள்.", "en": "Take the sum of the people , from twenty years old and upward; as the LORD commanded Moses and the children of Israel, which went forth out of the land of Egypt."}, {"verse": 5, "start": 50.5, "end": 63.32, "ta": "ரூபன் இஸ்ரவேலின் மூத்த குமாரன்; ரூபனுடைய குமாரர், ஆனாக்கியர் குடும்பத்துக்குத் தகப்பனான ஆனோக்கும், பல்லுூவியர் குடும்பத்துக்குத் தகப்பனான பல்லுூவும்,", "en": "Reuben, the eldest son of Israel: the children of Reuben; Hanoch, of whom cometh the family of the Hanochites: of Pallu, the family of the Palluites:"}, {"verse": 6, "start": 63.32, "end": 71.69, "ta": "எஸ்ரோனியர் குடும்பத்துக்குத் தகப்பனான எஸ்ரோனும், கர்மீயர் குடும்பத்துக்குத் தகப்பனான கர்மீயுமே.", "en": "Of Hezron, the family of the Hezronites: of Carmi, the family of the Carmites."}, {"verse": 7, "start": 71.69, "end": 80.92, "ta": "இவைகளே ரூபனியரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் நாற்பத்து மூவாயிரத்து எழுநூற்று முப்பதுபேர்.", "en": "These are the families of the Reubenites: and they that were numbered of them were forty and three thousand and seven hundred and thirty."}, {"verse": 8, "start": 80.92, "end": 83.74, "ta": "பல்லுூவின் குமாரன் எலியாப்.", "en": "And the sons of Pallu; Eliab."}, {"verse": 9, "start": 83.74, "end": 105.09, "ta": "எலியாபின் குமாரர் நேமுவேல், தாத்தான், அபிராம் என்பவர்கள்; இந்தத் தாத்தான் அபிராம் என்பவர்களே சபையில் பேர்பெற்றவர்களாயிருந்து, கர்த்தருக்கு விரோதமாகப் போராட்டம் பண்ணி, கோராகின் கூட்டாளிகளாகி, மோசேக்கும் ஆரோனுக்கும் விரோதமாக விவாதம்பண்ணினவர்கள்.", "en": "And the sons of Eliab; Nemuel, and Dathan, and Abiram. This is that Dathan and Abiram, which were famous in the congregation, who strove against Moses and against Aaron in the company of Korah, when they strove against the LORD :"}, {"verse": 10, "start": 105.09, "end": 119.56, "ta": "பூமி தன் வாயைத் திறந்து, அவர்களையும் கோராகையும் விழுங்கினதினாலும், அக்கினி இருநூற்று ஐம்பது பேரைப் பட்சித்ததினாலும், அந்தக் கூட்டத்தார் செத்து, ஒரு அடையாளமானார்கள்.", "en": "And the earth opened her mouth, and swallowed them up together with Korah, when that company died, what time the fire devoured two hundred and fifty men: and they became a sign."}, {"verse": 11, "start": 119.56, "end": 122.38, "ta": "கோராகின் குமாரரோ சாகவில்லை.", "en": "Notwithstanding the children of Korah died not."}, {"verse": 12, "start": 122.38, "end": 136.46, "ta": "சிமியோனுடைய குமாரரின் குடும்பங்களாவன: நேமுவேலின் சந்ததியான நேமுவேலரின் குடும்பமும், யாமினின் சந்ததியான யாமினியரின் குடும்பமும், யாகீனின் சந்ததியான யாகீனியரின் குடும்பமும்,", "en": "The sons of Simeon after their families: of Nemuel, the family of the Nemuelites: of Jamin, the family of the Jaminites: of Jachin, the family of the Jachinites:"}, {"verse": 13, "start": 136.46, "end": 144.04, "ta": "சேராகின் சந்ததியான சேராகியரின் குடும்பமும், சவுலின் சந்ததியான சவுலியரின் குடும்பமுமே.", "en": "Of Zerah, the family of the Zarhites: of Shaul, the family of the Shaulites."}, {"verse": 14, "start": 144.04, "end": 150.93, "ta": "இவைகளே சிமியோனியரின் குடும்பங்கள்; அவர்கள் இருபத்தீராயிரத்து இருநூறுபேர்.", "en": "These are the families of the Simeonites, twenty and two thousand and two hundred."}, {"verse": 15, "start": 150.93, "end": 164.61, "ta": "காத்துடைய குமாரரின் குடும்பங்களாவன: சிப்போனின் சந்ததியான சிப்போனியரின் குடும்பமும், ஆகியின் சந்ததியான ஆகியரின் குடும்பமும், சூனியின் சந்ததியான் சூனியரின் குடும்பமும்,", "en": "The children of Gad after their families: of Zephon, the family of the Zephonites: of Haggi, the family of the Haggites: of Shuni, the family of the Shunites:"}, {"verse": 16, "start": 164.61, "end": 171.58, "ta": "ஒஸ்னியின் சந்ததியான ஒஸ்னியரின் குடும்பமும், ஏரியின் சந்ததியான ஏரியரின் குடும்பமும்,", "en": "Of Ozni, the family of the Oznites: of Eri, the family of the Erites:"}, {"verse": 17, "start": 171.58, "end": 179.16, "ta": "ஆரோதின் சந்ததியான ஆரோதியரின் குடும்பமும், அரேலியின் சந்ததியான அரேலியரின் குடும்பமுமே.", "en": "Of Arod, the family of the Arodites: of Areli, the family of the Arelites."}, {"verse": 18, "start": 179.16, "end": 187.69, "ta": "இவைகளே காத் புத்திரரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் நாற்பதினாயிரத்து ஐந்நூறுபேர்.", "en": "These are the families of the children of Gad according to those that were numbered of them, forty thousand and five hundred."}, {"verse": 19, "start": 187.69, "end": 195.27, "ta": "யூதாவின் குமாரர் ஏர் ஓனான் என்பவர்கள்; ஏரும் ஓனானும் கானான் தேசத்தில் செத்தார்கள்.", "en": "The sons of Judah were Er and Onan: and Er and Onan died in the land of Canaan."}, {"verse": 20, "start": 195.27, "end": 210.06, "ta": "யூதாவுடைய மற்றக் குமாரரின் குடும்பங்களாவன: சேலாவின் சந்ததியான சேலாவியரின் குடும்பமும், பாரேசின் சந்ததியான பாரேசியரின் குடும்பமும், சேராவின் சந்ததியான சேராவியரின் குடும்பமுமே.", "en": "And the sons of Judah after their families were; of Shelah, the family of the Shelanites: of Pharez, the family of the Pharzites: of Zerah, the family of the Zarhites."}, {"verse": 21, "start": 210.06, "end": 220.62, "ta": "பாரேசுடைய குமாரரின் குடும்பங்களாவன: எஸ்ரோனின் சந்ததியான எஸ்ரோனியரின் குடும்பமும், ஆமூலின் சந்ததியான ஆமூலியரின் குடும்பமுமே.", "en": "And the sons of Pharez were; of Hezron, the family of the Hezronites: of Hamul, the family of the Hamulites."}, {"verse": 22, "start": 220.62, "end": 228.6, "ta": "இவைகளே யூதாவின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் எழுபத்தாறாயிரத்து ஐந்நூறுபேர்.", "en": "These are the families of Judah according to those that were numbered of them, threescore and sixteen thousand and five hundred."}, {"verse": 23, "start": 228.6, "end": 238.84, "ta": "இசக்காருடைய குமாரரின் குடும்பங்களாவன: தோலாவின் சந்ததியான தோலாவியரின் குடும்பமும், பூவாவின் சந்ததியான பூவாவியரின் குடும்பமும்,", "en": "Of the sons of Issachar after their families: of Tola, the family of the Tolaites: of Pua, the family of the Punites:"}, {"verse": 24, "start": 238.84, "end": 246.9, "ta": "யாசூபின் சந்ததியான யாசூபியரின் குடும்பமும், சிம்ரோனின் சந்ததியான சிம்ரோனியரின் குடும்பமுமே.", "en": "Of Jashub, the family of the Jashubites: of Shimron, the family of the Shimronites."}, {"verse": 25, "start": 246.9, "end": 255.35, "ta": "இவைகளே இசக்காரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் அறுபத்து நாலாயிரத்து முந்நூறுபேர்.", "en": "These are the families of Issachar according to those that were numbered of them, threescore and four thousand and three hundred."}, {"verse": 26, "start": 255.35, "end": 270.21, "ta": "செபுலோனுடைய குமாரரின் குடும்பங்களாவன: சேரேத்தின் சந்ததியான சேரேத்தியரின் குடும்பமும், ஏலோனின் சந்ததியான ஏலோனியரின் குடும்பமும், யாலேயேலின் சந்ததியான யாலேயேலியரின் குடும்பமுமே.", "en": "Of the sons of Zebulun after their families: of Sered, the family of the Sardites: of Elon, the family of the Elonites: of Jahleel, the family of the Jahleelites."}, {"verse": 27, "start": 270.21, "end": 278.42, "ta": "இவைகளே செபுலோனியரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் அறுபதினாயிரத்து ஐந்நூறுபேர்.", "en": "These are the families of the Zebulunites according to those that were numbered of them, threescore thousand and five hundred."}, {"verse": 28, "start": 278.42, "end": 283.66, "ta": "யோசேப்புடைய குமாரரான மனாசே எப்பிராயீம் என்பவர்களின் குடும்பங்களாவன:", "en": "The sons of Joseph after their families were Manasseh and Ephraim."}, {"verse": 29, "start": 283.66, "end": 295.16, "ta": "மனாசேயினுடைய குமாரரின் குடும்பங்கள்: மாகீரின் சந்ததியான மாகீரியரின் குடும்பமும், மாகீர் பெற்ற கிலெயாதின் சந்ததியான கிலெயாதியரின் குடும்பமும்,", "en": "Of the sons of Manasseh: of Machir, the family of the Machirites: and Machir begat Gilead: of Gilead come the family of the Gileadites."}, {"verse": 30, "start": 295.16, "end": 303.76, "ta": "கிலெயாத் பெற்ற ஈயேசேரின் சந்ததியான ஈயேசேயரின் குடும்பமும், ஏலேக்கின் சந்ததியான ஏலேக்கியரின் குடும்பமும்,", "en": "These are the sons of Gilead: of Jeezer, the family of the Jeezerites: of Helek, the family of the Helekites:"}, {"verse": 31, "start": 303.76, "end": 311.35, "ta": "அஸ்ரியேலின் சந்ததியான அஸ்ரியேலரின் குடும்பமும், சேகேமின் சந்ததியான சேகேமியரின் குடும்பமும்,", "en": "And of Asriel, the family of the Asrielites: and of Shechem, the family of the Shechemites:"}, {"verse": 32, "start": 311.35, "end": 319.56, "ta": "செமீதாவின் சந்ததியான செமீதாவியரின் குடும்பமும், ஏப்பேரின் சந்ததியான ஏப்பேரியரின் குடும்பமுமே.", "en": "And of Shemida, the family of the Shemidaites: and of Hepher, the family of the Hepherites."}, {"verse": 33, "start": 319.56, "end": 335.99, "ta": "ஏப்பேரின் குமாரனான செலொப்பியாத்திற்குக் குமாரர் இல்லாமல் இருந்தார்கள், குமாரத்திகள் மாத்திரம் இருந்தார்கள்; இவர்கள் நாமங்கள் மக்லாள், நோவாள், ஒக்லாள், மில்காள், திர்சாள் என்பவைகள்.", "en": "And Zelophehad the son of Hepher had no sons, but daughters: and the names of the daughters of Zelophehad were Mahlah, and Noah, Hoglah, Milcah, and Tirzah."}, {"verse": 34, "start": 335.99, "end": 344.04, "ta": "இவைகளே மனாசேயின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் ஐம்பத்தீராயிரத்து எழுநூறுபேர்.", "en": "These are the families of Manasseh, and those that were numbered of them, fifty and two thousand and seven hundred."}, {"verse": 35, "start": 344.04, "end": 358.83, "ta": "எப்பிராயீமுடைய குமாரரின் குடும்பங்களாவன: சுத்தெலாகின் சந்ததியான சுத்தெலாகியரின் குடும்பமும், பெகேரின் சந்ததியான பெகேரியரின் குடும்பமும், தாகானின் சந்ததியான தாகானியரின் குடும்பமும்,", "en": "These are the sons of Ephraim after their families: of Shuthelah, the family of the Shuthalhites: of Becher, the family of the Bachrites: of Tahan, the family of the Tahanites."}, {"verse": 36, "start": 358.83, "end": 364.07, "ta": "சுத்தெலாக் பெற்ற ஏரானின் சந்ததியான ஏரானியரின் குடும்பமுமே.", "en": "And these are the sons of Shuthelah: of Eran, the family of the Eranites."}, {"verse": 37, "start": 364.07, "end": 377.13, "ta": "இவைகளே எப்பிராயீம் புத்திரரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் முப்பத்தீராயிரத்து ஐந்நூறுபேர்; இவர்களே யோசேப்பு புத்திரரின் குடும்பங்கள்.", "en": "These are the families of the sons of Ephraim according to those that were numbered of them, thirty and two thousand and five hundred. These are the sons of Joseph after their families."}, {"verse": 38, "start": 377.13, "end": 391.44, "ta": "பென்யமீனுடைய குமாரரின் குடும்பங்களாவன: பேலாவின் சந்ததியான பேலாவியரின் குடும்பமும், அஸ்பேலின் சந்ததியான அஸ்பேலியரின் குடும்பமும், அகிராமின் சந்ததியான அகிராமியரின் குடும்பமும்,", "en": "The sons of Benjamin after their families: of Bela, the family of the Belaites: of Ashbel, the family of the Ashbelites: of Ahiram, the family of the Ahiramites:"}, {"verse": 39, "start": 391.44, "end": 399.19, "ta": "சுப்பாமின் சந்ததியான சுப்பாமியரின் குடும்பமும், உப்பாமின் சந்ததியான உப்பாமியரின் குடும்பமும்,", "en": "Of Shupham, the family of the Shuphamites: of Hupham, the family of the Huphamites."}, {"verse": 40, "start": 399.19, "end": 407.79, "ta": "பேலா பெற்ற ஆரேதின் சந்ததியான ஆரேதியரின் குடும்பமும், நாகமானின் சந்ததியான நாகமானியரின் குடும்பமுமே.", "en": "And the sons of Bela were Ard and Naaman: of Ard , the family of the Ardites: and of Naaman, the family of the Naamites."}, {"verse": 41, "start": 407.79, "end": 416.94, "ta": "இவைகளே பென்யமீன் புத்திரரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் நாற்பத்தையாயிரத்து அறுநூறு பேர்.", "en": "These are the sons of Benjamin after their families: and they that were numbered of them were forty and five thousand and six hundred."}, {"verse": 42, "start": 416.94, "end": 426.09, "ta": "தாணுடைய குமாரரின் குடும்பங்களாவன: சூகாமின் சந்ததியான சூகாமியரின் குடும்பமுமே; இவைகள் தாணின் குடும்பம்.", "en": "These are the sons of Dan after their families: of Shuham, the family of the Shuhamites. These are the families of Dan after their families."}, {"verse": 43, "start": 426.09, "end": 433.37, "ta": "சூகாமியரின் வம்சங்களில் எண்ணப்பட்டவர்கள் எல்லோரும் அறுபத்து நாலாயிரத்து நானூறு பேர்.", "en": "All the families of the Shuhamites, according to those that were numbered of them, were threescore and four thousand and four hundred."}, {"verse": 44, "start": 433.37, "end": 447.52, "ta": "ஆசேருடைய குமாரரின் குடும்பங்களாவன: இம்னாவின் சந்ததியான இம்னாவியரின் குடும்பமும், இஸ்வியின் சந்ததியான இஸ்வியரின் குடும்பமும், பெரீயாவின் சந்ததியான பெரீயாவியரின் குடும்பமும்,", "en": "Of the children of Asher after their families: of Jimna, the family of the Jimnites: of Jesui, the family of the Jesuites: of Beriah, the family of the Beriites."}, {"verse": 45, "start": 447.52, "end": 456.13, "ta": "பெரீயா பெற்ற ஏபேரின் சந்ததியான ஏபேரியரின் குடும்பமும், மல்கியேலின் சந்ததியான மல்கியேலியரின் குடும்பமுமே,", "en": "Of the sons of Beriah: of Heber, the family of the Heberites: of Malchiel, the family of the Malchielites."}, {"verse": 46, "start": 456.13, "end": 459.57, "ta": "ஆசேருடைய குமாரத்தியின் பேர் சாராள்.", "en": "And the name of the daughter of Asher was Sarah."}, {"verse": 47, "start": 459.57, "end": 468.49, "ta": "இவைகளே ஆசேர் புத்திரரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் ஐம்பத்து மூவாயிரத்து நானூறு பேர்.", "en": "These are the families of the sons of Asher according to those that were numbered of them; who were fifty and three thousand and four hundred."}, {"verse": 48, "start": 468.49, "end": 479.36, "ta": "நப்தலியினுடைய குமாரரின் குடும்பங்களாவன: யாத்சியேலின் சந்ததியான யாத்சியேலியரின் குடும்பமும், கூனியின் சந்ததியான கூனியரின் குடும்பமும்,", "en": "Of the sons of Naphtali after their families: of Jahzeel, the family of the Jahzeelites: of Guni, the family of the Gunites:"}, {"verse": 49, "start": 479.36, "end": 487.57, "ta": "எத்செரின் சந்ததியான எத்செரியரின் குடும்பமும், சில்லேமின் சந்ததியான சில்லேமியரின் குடும்பமுமே.", "en": "Of Jezer, the family of the Jezerites: of Shillem, the family of the Shillemites."}, {"verse": 50, "start": 487.57, "end": 495.78, "ta": "இவைகளே நப்தலியின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் நாற்பத்தையாயிரத்து நானூறு பேர்.", "en": "These are the families of Naphtali according to their families: and they that were numbered of them were forty and five thousand and four hundred."}, {"verse": 51, "start": 495.78, "end": 503.84, "ta": "இஸ்ரவேல் புத்திரரில் எண்ணப்பட்டவர்கள் ஆறுலட்சத்தோராயிரத்து எழுநூற்று முப்பதுபேராயிருந்தார்கள்.", "en": "These were the numbered of the children of Israel, six hundred thousand and a thousand seven hundred and thirty."}, {"verse": 52, "start": 503.84, "end": 505.64, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 53, "start": 505.64, "end": 513.93, "ta": "இவர்களுடைய பேர்களின் இலக்கத்திற்குத்தக்கதாய் தேசம் இவர்களுக்குச் சுதந்தரமாகப் பங்கிடப்படவேண்டும்.", "en": "Unto these the land shall be divided for an inheritance according to the number of names."}, {"verse": 54, "start": 513.93, "end": 528.56, "ta": "அநேகம்பேருக்கு அதிக சுதந்திரமும் கொஞ்சம்பேருக்கு கொஞ்ச சுதந்தரமும் கொடுப்பாயாக; அவர்களில் எண்ணப்பட்ட இலக்கத்திற்குத் தக்கதாக அவரவர்களுக்குச் சுதந்திரம் கொடுக்கப்படவேண்டும்.", "en": "To many thou shalt give the more inheritance, and to few thou shalt give the less inheritance: to every one shall his inheritance be given according to those that were numbered of him."}, {"verse": 55, "start": 528.56, "end": 540.6, "ta": "ஆனாலும் சீட்டுப்போட்டு, தேசத்தைப் பங்கிடவேண்டும்; தங்கள் பிதாக்களுடைய கோத்திரங்களுக்குரிய நாமங்களின்படியே சுதந்தரித்துக்கொள்ளக்கடவர்கள்.", "en": "Notwithstanding the land shall be divided by lot: according to the names of the tribes of their fathers they shall inherit."}, {"verse": 56, "start": 540.6, "end": 550.22, "ta": "அநேகம்பேர்களாயினும் கொஞ்சம்பேர்களாயினும் சீட்டு விழுந்தபடியே அவரவர்களுடைய சுதந்தரங்கள் பங்கிடப்படவேண்டும் என்றார்.", "en": "According to the lot shall the possession thereof be divided between many and few."}, {"verse": 57, "start": 550.22, "end": 565.08, "ta": "எண்ணப்பட்ட லேவியரின் குடும்பங்களாவன: கெர்சோனின் சந்ததியான கெர்சோனியரின் குடும்பமும், கோகாத்தின் சந்ததியான கோகாத்தியரின் குடும்பமும், மெராரியின் சந்ததியான மெராரியரின் குடும்பமும்;", "en": "And these are they that were numbered of the Levites after their families: of Gershon, the family of the Gershonites: of Kohath, the family of the Kohathites: of Merari, the family of the Merarites."}, {"verse": 58, "start": 565.08, "end": 581.51, "ta": "லேவியின் மற்றக் குடும்பங்களாகிய லிப்னீயரின் குடும்பமும், எப்ரோனியரின் குடும்பமும், மகலியரின் குடும்பமும், மூசியரின் குடும்பமும், கோராகியரின் குடும்பமுமே. கோகாத் அம்ராமைப் பெற்றான்.", "en": "These are the families of the Levites: the family of the Libnites, the family of the Hebronites, the family of the Mahlites, the family of the Mushites, the family of the Korathites. And Kohath begat Amram."}, {"verse": 59, "start": 581.51, "end": 595.98, "ta": "அம்ராமுடைய மனைவிக்கு யோகெபேத் என்று பேர்; அவள் எகிப்திலே லேவிக்குப் பிறந்த குமாரத்தி; அவள் அம்ராமுக்கு ஆரோனையும் மோசேயையும் அவர்கள் சகோதரியான மிரியாமையும் பெற்றாள்.", "en": "And the name of Amram’s wife was Jochebed, the daughter of Levi, whom her mother bare to Levi in Egypt: and she bare unto Amram Aaron and Moses, and Miriam their sister."}, {"verse": 60, "start": 595.98, "end": 601.85, "ta": "ஆரோனுக்கு நாதாபும் அபியூவும் எலெயாசாரும் இத்தாமாரும் பிறந்தார்கள்.", "en": "And unto Aaron was born Nadab, and Abihu, Eleazar, and Ithamar."}, {"verse": 61, "start": 601.85, "end": 610.29, "ta": "நாதாபும் அபியூவும் கர்த்தருடைய சந்நிதியில் அந்நிய அக்கினியைக் கொண்டுவந்தபோது, செத்துப்போனார்கள்.", "en": "And Nadab and Abihu died, when they offered strange fire before the LORD ."}, {"verse": 62, "start": 610.29, "end": 628.13, "ta": "அவர்களில் ஒரு மாதத்து ஆண்பிள்ளை முதலாக எண்ணப்பட்டவர்கள் இருபத்து மூவாயிரம்பேர்; இஸ்ரவேல் புத்திரரின் நடுவே அவர்களுக்குச் சுதந்தரம் கொடுக்கப்படாதபடியினால், அவர்கள் இஸ்ரவேல் புத்திரரின் இலக்கத்திற்கு உட்படவில்லை.", "en": "And those that were numbered of them were twenty and three thousand, all males from a month old and upward: for they were not numbered among the children of Israel, because there was no inheritance given them among the children of Israel."}, {"verse": 63, "start": 628.13, "end": 641.11, "ta": "மோசேயும் ஆசாரியனாகிய எலெயாசரும் எரிகோவின் அருகேயிருக்கும் யோர்தானுக்கு இப்பாலே மோவாபின் சமனான வெளிகளில் இஸ்ரவேல் புத்திரரை எண்ணுகிறபோது இருந்தவர்கள் இவர்களே.", "en": "These are they that were numbered by Moses and Eleazar the priest, who numbered the children of Israel in the plains of Moab by Jordan near Jericho."}, {"verse": 64, "start": 641.11, "end": 652.14, "ta": "முன்பு மோசேயும் ஆசாரியனாகிய ஆரோனும் சீனாய் வனாந்தரத்தில் இஸ்ரவேல் புத்திரரை எண்ணும்போது இருந்தவர்களில் ஒருவரும் இவர்களுக்குள் இல்லை.", "en": "But among these there was not a man of them whom Moses and Aaron the priest numbered, when they numbered the children of Israel in the wilderness of Sinai."}, {"verse": 65, "start": 652.14, "end": 668.8, "ta": "வனாந்தரத்தில் சாகவே சாவார்கள் என்று கர்த்தர் அவர்களைக் குறித்துச் சொல்லியிருந்தார்; எப்புன்னேயின் குமாரனாகிய காலேபும் நூனின் குமாரனாகிய யோசுவாவும் தவிர, வேறொருவரும் அவர்களில் மீதியாயிருக்கவில்லை.", "en": "For the LORD had said of them, They shall surely die in the wilderness. And there was not left a man of them, save Caleb the son of Jephunneh, and Joshua the son of Nun."}]}, "27": {"chapter": 27, "duration": 266.85, "audio_url": "audio_ot/OT04_27.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 22.07, "ta": "யோசேப்பின் குமாரனாகிய மனாசேயின் குடும்பங்களில், மனாசேயின் குமாரனாகிய மாகீரின் மகனான கிலெயாத்துக்குப் பிறந்த ஏபேருக்குப் புத்திரனாயிருந்த செலோப்பியாத்தின் குமாரத்திகளாகிய மக்லாள், நோவாள், ஒக்லாள், மில்காள், திர்சாள் என்பவர்கள் வந்து,", "en": "Then came the daughters of Zelophehad, the son of Hepher, the son of Gilead, the son of Machir, the son of Manasseh, of the families of Manasseh the son of Joseph: and these are the names of his daughters; Mahlah, Noah, and Hoglah, and Milcah, and Tirzah."}, {"verse": 2, "start": 22.07, "end": 31.13, "ta": "ஆசரிப்புக் கூடாரவாசலிலே மோசேக்கும், ஆசாரியனாகிய எலெயாசாருக்கும், பிரபுக்களுக்கும், சபையனைத்திற்கும் முன்பாக நின்று:", "en": "And they stood before Moses, and before Eleazar the priest, and before the princes and all the congregation, by the door of the tabernacle of the congregation, saying,"}, {"verse": 3, "start": 31.13, "end": 45.67, "ta": "எங்கள் தகப்பன் வனாந்தரத்தில் மரணமடைந்தார்; அவர் கர்த்தருக்கு விரோதமாகக் கூடின கோராகின் கூட்டத்தாரில் சேர்ந்தவர் அல்ல, தம்முடைய பாவத்தினாலே மரித்தார்; அவருக்குக் குமாரர் இல்லை.", "en": "Our father died in the wilderness, and he was not in the company of them that gathered themselves together against the LORD in the company of Korah; but died in his own sin, and had no sons."}, {"verse": 4, "start": 45.67, "end": 60.73, "ta": "எங்கள் தகப்பனுக்குக் குமாரன் இல்லாததினாலே, அவருடைய பேர் அவருடைய வம்சத்தில் இல்லாமல் அற்றுப்போகலாமா? எங்கள் தகப்பனுடைய சகோதரருக்குள்ளே எங்களுக்குக் காணியாட்சி கொடுக்கவேண்டும் என்றார்கள்.", "en": "Why should the name of our father be done away from among his family, because he hath no son? Give unto us therefore a possession among the brethren of our father."}, {"verse": 5, "start": 60.73, "end": 66.14, "ta": "மோசே அவர்களுடைய நியாயத்தைக் கர்த்தருடைய சந்நிதியில் கொண்டுபோனான்.", "en": "And Moses brought their cause before the LORD ."}, {"verse": 6, "start": 66.14, "end": 68.55, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 7, "start": 68.55, "end": 85.06, "ta": "செலோப்பியாத்தின் குமாரத்திகள் சொல்லுகிறது சரிதான்; அவர்களுக்கு அவர்கள் தகப்பனுடைய சகோதரருக்குள்ளே சுதந்தரம் கொடுக்கப்படவேண்டும்; அவர்கள் தகப்பன் பின்வைத்த சுதந்தரத்தை அவர்களுக்குக் கிடைக்கும்படி செய்வாயாக.", "en": "The daughters of Zelophehad speak right: thou shalt surely give them a possession of an inheritance among their father’s brethren; and thou shalt cause the inheritance of their father to pass unto them."}, {"verse": 8, "start": 85.06, "end": 95.66, "ta": "மேலும் நீ இஸ்ரவேல் புத்திரரை நோக்கி: ஒருவன் குமாரன் இல்லாமல் மரித்தால், அவனுக்குரிய சுதந்தரத்தை அவன் குமாரத்திக்குக் கொடுக்கவேண்டும்.", "en": "And thou shalt speak unto the children of Israel, saying, If a man die, and have no son, then ye shall cause his inheritance to pass unto his daughter."}, {"verse": 9, "start": 95.66, "end": 103.77, "ta": "அவனுக்கு குமாரத்தியும் இல்லாதிருந்தால், அவனுக்குரிய சுதந்தரத்தை அவன் சகோதரருக்குக் கொடுக்கவேண்டும்.", "en": "And if he have no daughter, then ye shall give his inheritance unto his brethren."}, {"verse": 10, "start": 103.77, "end": 112.25, "ta": "அவனுக்குச் சகோதரரும் இல்லாதிருந்தால் அவனுக்குரிய சுதந்தரத்தை அவன் தகப்பனுடைய சகோதரருக்குக் கொடுக்கவேண்டும்.", "en": "And if he have no brethren, then ye shall give his inheritance unto his father’s brethren."}, {"verse": 11, "start": 112.25, "end": 134.1, "ta": "அவன் தகப்பனுக்குச் சகோதரர் இல்லாதிருந்தால், அவனுக்குரிய சுதந்தரத்தை அவன் வம்சத்திலே அவனுக்குக் கிட்டின உறவின்முறையானுக்குக் சுதந்தரமாகக் கொடுக்கவேண்டும்; இது, கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, இஸ்ரவேல் புத்திரருக்கு நியாயவிதிப்பிரமாணமாய் இருக்கக்கடவது என்று சொல் என்றார்.", "en": "And if his father have no brethren, then ye shall give his inheritance unto his kinsman that is next to him of his family, and he shall possess it: and it shall be unto the children of Israel a statute of judgment, as the LORD commanded Moses."}, {"verse": 12, "start": 134.1, "end": 143.23, "ta": "பின்பு கர்த்தர் மோசேயை நோக்கி: நீ இந்த அபாரீம் மலையில் ஏறி, நான் இஸ்ரவேல் புத்திரருக்குக் கொடுத்த தேசத்தைப் பார்.", "en": "And the LORD said unto Moses, Get thee up into this mount Abarim, and see the land which I have given unto the children of Israel."}, {"verse": 13, "start": 143.23, "end": 152.15, "ta": "நீ அதைப் பார்த்தபின்பு, உன் சகோதரனாகிய ஆரோன் சேர்க்கப்பட்டது போல, நீயும் உன் ஜனத்தாரிடத்தில் சேர்க்கப்படுவாய்;", "en": "And when thou hast seen it, thou also shalt be gathered unto thy people, as Aaron thy brother was gathered."}, {"verse": 14, "start": 152.15, "end": 171.95, "ta": "சபையார் வாக்குவாதம்பண்ணின சீன் வனாந்தரத்தில் தண்ணீருக்கடுத்த விஷயத்தில் அவர்கள் கண்களுக்கு முன்பாக என்னைப் பரிசுத்தம்பண்ணவேண்டிய நீங்கள் என் கட்டளையை மீறினீர்களே என்றார். இது சீன் வனாந்தரத்தில் காதேஸ் ஊர் அருகே உண்டான மேரிபாவின் தண்ணீருக்கடுத்த காரியமே.", "en": "For ye rebelled against my commandment in the desert of Zin, in the strife of the congregation, to sanctify me at the water before their eyes: that is the water of Meribah in Kadesh in the wilderness of Zin."}, {"verse": 15, "start": 171.95, "end": 174.22, "ta": "அப்பொழுது மோசே கர்த்தரை நோக்கி:", "en": "And Moses spake unto the LORD , saying,"}, {"verse": 16, "start": 174.22, "end": 178.75, "ta": "கர்த்தருடைய சபை மேய்ப்பன் இல்லாத மந்தையைப்போல் இராதபடிக்கு,", "en": "Let the LORD , the God of the spirits of all flesh, set a man over the congregation,"}, {"verse": 17, "start": 178.75, "end": 195.78, "ta": "அந்தச் சபைக்கு முன்பாகப் போக்கும் வரத்துமாய் இருக்கும்படிக்கும், அவர்களைப் போகவும் வரவும் பண்ணும்படிக்கும், மாம்சமான யாவருடைய ஆவிகளுக்கும் தேவனாகிய கர்த்தர் ஒரு புருஷனை அவர்கள்மேல் அதிகாரியாக ஏற்படுத்தவேண்டும் என்றான்.", "en": "Which may go out before them, and which may go in before them, and which may lead them out, and which may bring them in; that the congregation of the LORD be not as sheep which have no shepherd."}, {"verse": 18, "start": 195.78, "end": 205.79, "ta": "கர்த்தர் மோசேயை நோக்கி: ஆவியைப் பெற்றிருக்கிற புருஷனாகிய யோசுவா என்னும் நூனின் குமாரனை நீ தெரிந்துகொண்டு, அவன்மேல் உன் கையை வைத்து,", "en": "And the LORD said unto Moses, Take thee Joshua the son of Nun, a man in whom is the spirit, and lay thine hand upon him;"}, {"verse": 19, "start": 205.79, "end": 214.93, "ta": "அவனை ஆசாரியனாகிய எலெயாசாருக்கும் சபையனைத்திற்கும் முன்பாக நிறுத்தி, அவர்கள் கண்களுக்கு முன்பாக அவனுக்கு கட்டளைகொடுத்து,", "en": "And set him before Eleazar the priest, and before all the congregation; and give him a charge in their sight."}, {"verse": 20, "start": 214.93, "end": 223.84, "ta": "இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரும் அவனுக்குக் கீழ்ப்படியும்படிக்கு, உன் கனத்தில் கொஞ்சம் அவனுக்குக் கொடு.", "en": "And thou shalt put some of thine honour upon him, that all the congregation of the children of Israel may be obedient."}, {"verse": 21, "start": 223.84, "end": 247.81, "ta": "அவன் ஆசாரியனாகிய எலெயாசாருக்கு முன்பாக நிற்கக்கடவன்; அவனிமித்தம் அந்த ஆசாரியன் கர்த்தருடைய சந்நிதானத்தில் வந்து, ஊரீம் என்னும் நியாயத்தினாலே ஆலோசனை கேட்கக்கடவன்; அவருடைய கட்டளையின்படியே, அவனும் அவனோடேகூட இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரும் போகவும் அவருடைய கட்டளையின்படியே வரவும் வேண்டியது என்றார்.", "en": "And he shall stand before Eleazar the priest, who shall ask counsel for him after the judgment of Urim before the LORD : at his word shall they go out, and at his word they shall come in, both he, and all the children of Israel with him, even all the congregation."}, {"verse": 22, "start": 247.81, "end": 258.26, "ta": "மோசே தனக்குக் கர்த்தர் கட்டளையிட்டபடியே யோசுவாவை அழைத்துக்கொண்டுபோய், அவனை ஆசாரியனாகிய எலெயாசாருக்கும் சபையனைத்திற்கும் முன்பாக நிறுத்தி,", "en": "And Moses did as the LORD commanded him: and he took Joshua, and set him before Eleazar the priest, and before all the congregation:"}, {"verse": 23, "start": 258.26, "end": 265.35, "ta": "அவன் மேல் தன் கைகளை வைத்து, கர்த்தர் தனக்குச் சொன்னபடியே அவனுக்குக் கட்டளைகொடுத்தான்.", "en": "And he laid his hands upon him, and gave him a charge, as the LORD commanded by the hand of Moses."}]}, "28": {"chapter": 28, "duration": 335.62, "audio_url": "audio_ot/OT04_28.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 5.54, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.54, "end": 21.07, "ta": "எனக்குச் சுகந்தவாசனையாக, தகனபலிகளுக்கு அடுத்த காணிக்கையையும் அப்பத்தையும், குறித்தகாலத்தில் எனக்குச் செலுத்தும்படிக்குக் கவனமாயிருக்கக்கடவீர்கள் என்று நீ இஸ்ரவேல் புத்திரருக்குக் கட்டளையிடு.", "en": "Command the children of Israel, and say unto them, My offering, and my bread for my sacrifices made by fire, for a sweet savour unto me, shall ye observe to offer unto me in their due season."}, {"verse": 3, "start": 21.07, "end": 35.39, "ta": "மேலும் நீ அவர்களை நோக்கி: நீங்கள் கர்த்தருக்குச் செலுத்தவேண்டிய தகனபலி என்னவென்றால்: நித்திய சர்வாங்க தகனபலியாக நாடோறும் ஒரு வயதான பழுதற்ற இரண்டு ஆட்டுக்குட்டிகளைப் பலியிடவேண்டும்.", "en": "And thou shalt say unto them, This is the offering made by fire which ye shall offer unto the LORD ; two lambs of the first year without spot day by day, for a continual burnt offering."}, {"verse": 4, "start": 35.39, "end": 41.68, "ta": "காலையில் ஒரு ஆட்டுக்குட்டியையும், மாலையில் ஒரு ஆட்டுக்குட்டியையும் பலியிட்டு,", "en": "The one lamb shalt thou offer in the morning, and the other lamb shalt thou offer at even;"}, {"verse": 5, "start": 41.68, "end": 52.74, "ta": "போஜனபலியாக ஒரு மரக்காலிலே பத்தில் ஒரு பங்கானதும் இடித்துப் பிழிந்த காற்படி எண்ணெயிலே பிசைந்ததுமாகிய மெல்லிய மாவையும் செலுத்தக் கடவீர்கள்.", "en": "And a tenth part of an ephah of flour for a meat offering, mingled with the fourth part of an hin of beaten oil."}, {"verse": 6, "start": 52.74, "end": 61.76, "ta": "இது சீனாய் மலையிலே கட்டளையிடப்பட்ட நித்திய சர்வாங்க தகனபலி; இது கர்த்தருக்குச் சுகந்த வாசனைக்கான தகனபலி.", "en": "It is a continual burnt offering, which was ordained in mount Sinai for a sweet savour, a sacrifice made by fire unto the LORD ."}, {"verse": 7, "start": 61.76, "end": 72.74, "ta": "காற்படி திராட்சரசம் ஒரு ஆட்டுக்குட்டிக்கு அடுத்த பானபலி; பரிசுத்த ஸ்தலத்திலே கர்த்தருக்கு அந்த இரசம் பானபலியாக வார்க்கப்படக்கடவது.", "en": "And the drink offering thereof shall be the fourth part of an hin for the one lamb: in the holy place shalt thou cause the strong wine to be poured unto the LORD for a drink offering."}, {"verse": 8, "start": 72.74, "end": 84.56, "ta": "காலையின் போஜனபலிக்கும் அதின் பானபலிக்கும் ஒப்பாகவே மாலையில் மற்ற ஆட்டுக்குட்டியையும் கர்த்தருக்குச் சுகந்த வாசனையான தகனபலியாகச் செலுத்தக்கடவீர்கள்.", "en": "And the other lamb shalt thou offer at even: as the meat offering of the morning, and as the drink offering thereof, thou shalt offer it , a sacrifice made by fire, of a sweet savour unto the LORD ."}, {"verse": 9, "start": 84.56, "end": 99.11, "ta": "ஓய்வுநாளிலோ போஜனபலிக்காக ஒரு வயதான பழுதற்ற இரண்டு ஆட்டுக்குட்டிகளையும், பத்தில் இரண்டு பங்கானதும் எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவையும், அதின் பானபலியையும் செலுத்தக்கடவீர்கள்.", "en": "And on the sabbath day two lambs of the first year without spot, and two tenth deals of flour for a meat offering, mingled with oil, and the drink offering thereof:"}, {"verse": 10, "start": 99.11, "end": 109.87, "ta": "நித்தமும் செலுத்தும் சர்வாங்க தகனபலியும் அதின் பானபலியும் அன்றி ஒவ்வொரு ஒய்வுநாளிலும் இந்தச் சர்வாங்க தகனபலியும் செலுத்தப்படவேண்டும்.", "en": "This is the burnt offering of every sabbath, beside the continual burnt offering, and his drink offering."}, {"verse": 11, "start": 109.87, "end": 123.96, "ta": "உங்கள் மாதப்பிறப்புகளில் நீங்கள் கர்த்தருக்குச் சர்வாங்க தகனபலியாக இரண்டு காளைகளையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும் செலுத்தக்கடவீர்கள்.", "en": "And in the beginnings of your months ye shall offer a burnt offering unto the LORD ; two young bullocks, and one ram, seven lambs of the first year without spot;"}, {"verse": 12, "start": 123.96, "end": 138.66, "ta": "போஜனபலியாக ஒவ்வொரு காளைக்குப் பத்தில் மூன்றுபங்கானதும் எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவையும், போஜனபலியாக ஒரு ஆட்டுக்கடாவுக்குப் பத்தில் இரண்டு பங்கானதும் எண்ணெயிலே பிசைந்ததுமான மாவையும்,", "en": "And three tenth deals of flour for a meat offering, mingled with oil, for one bullock; and two tenth deals of flour for a meat offering, mingled with oil, for one ram;"}, {"verse": 13, "start": 138.66, "end": 151.84, "ta": "போஜனபலியாக ஒவ்வொரு ஆட்டுக்குட்டிக்குப் பத்தில் ஒரு பங்கானதும் எண்ணெயிலே பிசைந்ததுமான மாவையும் கர்த்தருக்குச் சுகந்த வாசனையான சர்வாங்க தகனபலியாகச் செலுத்தக்கடவீர்கள்.", "en": "And a several tenth deal of flour mingled with oil for a meat offering unto one lamb; for a burnt offering of a sweet savour, a sacrifice made by fire unto the LORD ."}, {"verse": 14, "start": 151.84, "end": 170.78, "ta": "அவைகளுக்கேற்ற பானபலிகள் திராட்சரசத்தில் காளைக்கு அரைப்படியும், ஆட்டுக்கடாவுக்குப் படியில் மூன்றில் ஒரு பங்கும், ஆட்டுக்குட்டிக்குக் காற்படி ரசமுமாயிருக்கவேண்டும்; இது வருஷ முழுவதும் மாதந்தோறும் செலுத்தப்படவேண்டிய சர்வாங்க தகனபலி.", "en": "And their drink offerings shall be half an hin of wine unto a bullock, and the third part of an hin unto a ram, and a fourth part of an hin unto a lamb: this is the burnt offering of every month throughout the months of the year."}, {"verse": 15, "start": 170.78, "end": 182.29, "ta": "நித்தமும் இடப்படும் சர்வாங்க தகனபலியும் அதின் பானபலியும் அன்றி, பாவநிவாரண பலியாகக் கர்த்தருக்கு ஒரு வெள்ளாட்டுக்கடாவும் செலுத்தப்படவேண்டும்.", "en": "And one kid of the goats for a sin offering unto the LORD shall be offered, beside the continual burnt offering, and his drink offering."}, {"verse": 16, "start": 182.29, "end": 186.99, "ta": "முதலாம் மாதம் பதினாலாம் தேதி கர்த்தருக்கு உரிய பஸ்கா.", "en": "And in the fourteenth day of the first month is the passover of the LORD ."}, {"verse": 17, "start": 186.99, "end": 194.95, "ta": "அந்த மாதம் பதினைந்தாம் தேதி பண்டிகைநாள்; ஏழுநாளளவும் புளிப்பில்லாத அப்பம் புசிக்கவேண்டும்.", "en": "And in the fifteenth day of this month is the feast: seven days shall unleavened bread be eaten."}, {"verse": 18, "start": 194.95, "end": 203.89, "ta": "முதலாம் நாளிலே பரிசுத்த சபை கூடுதல் இருக்கவேண்டும்; அன்றைத்தினம் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது.", "en": "In the first day shall be an holy convocation; ye shall do no manner of servile work therein:"}, {"verse": 19, "start": 203.89, "end": 214.95, "ta": "அப்பொழுது நீங்கள் கர்த்தருக்குச் சர்வாங்க தகனபலியாக இரண்டு காளைகளையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும்,", "en": "But ye shall offer a sacrifice made by fire for a burnt offering unto the LORD ; two young bullocks, and one ram, and seven lambs of the first year: they shall be unto you without blemish:"}, {"verse": 20, "start": 214.95, "end": 226.08, "ta": "அவைகளுக்கேற்ற போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவிலே காளைக்காகப் பத்தில் மூன்று பங்கையும், ஆட்டுக்கடாவுக்காகப் பத்தில் இரண்டு பங்கையும்,", "en": "And their meat offering shall be of flour mingled with oil: three tenth deals shall ye offer for a bullock, and two tenth deals for a ram;"}, {"verse": 21, "start": 226.08, "end": 231.01, "ta": "ஏழு ஆட்டுக்குட்டிகளில் ஒவ்வொன்றிற்காகப் பத்தில் ஒரு பங்கையும்,", "en": "A several tenth deal shalt thou offer for every lamb, throughout the seven lambs:"}, {"verse": 22, "start": 231.01, "end": 238.43, "ta": "உங்கள் பாவநிவர்த்திக்கென்று பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering, to make an atonement for you."}, {"verse": 23, "start": 238.43, "end": 245.78, "ta": "காலையிலே நித்தமும் செலுத்தும் சர்வாங்க தகனபலியையும் அன்றி இவைகளையும் செலுத்தக்கடவீர்கள்.", "en": "Ye shall offer these beside the burnt offering in the morning, which is for a continual burnt offering."}, {"verse": 24, "start": 245.78, "end": 261.62, "ta": "இந்தப்பிரகாரம் ஏழுநாளளவும் நாடோறும் கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி செலுத்தக்கடவீர்கள்; நித்தமும் செலுத்தப்படும் சர்வாங்க தகனபலியையும் அதின் பானபலியையும் அன்றி, இதையும் செலுத்தவேண்டும்.", "en": "After this manner ye shall offer daily, throughout the seven days, the meat of the sacrifice made by fire, of a sweet savour unto the LORD : it shall be offered beside the continual burnt offering, and his drink offering."}, {"verse": 25, "start": 261.62, "end": 270.56, "ta": "ஏழாம் நாளிலே பரிசுத்த சபைகூடுதல் இருக்கவேண்டும்; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது..", "en": "And on the seventh day ye shall have an holy convocation; ye shall do no servile work."}, {"verse": 26, "start": 270.56, "end": 285.78, "ta": "அந்த வாரங்களுக்குப்பின் நீங்கள் கர்த்தருக்குப் புதிய போஜனபலியாக முதற்கனிகளைச் செலுத்தும் பண்டிகை நாளிலும் பரிசுத்த சபைகூடுதல் இருக்கவேண்டும்; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது.", "en": "Also in the day of the firstfruits, when ye bring a new meat offering unto the LORD , after your weeks be out , ye shall have an holy convocation; ye shall do no servile work:"}, {"verse": 27, "start": 285.78, "end": 297.91, "ta": "அப்பொழுது நீங்கள் கர்த்தருக்குச் சுகந்த வாசனையான சர்வாங்க தகனபலியாக இரண்டு காளைகளையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான ஏழு ஆட்டுக்குட்டிகளையும்.", "en": "But ye shall offer the burnt offering for a sweet savour unto the LORD ; two young bullocks, one ram, seven lambs of the first year;"}, {"verse": 28, "start": 297.91, "end": 309.65, "ta": "அவைகளின் போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவில் ஒரு காளைக்காகப் பத்தில் மூன்று பங்கையும், அந்த ஒரு ஆட்டுக்கடாவுக்காகப் பத்தில் இரண்டு பங்கையும்,", "en": "And their meat offering of flour mingled with oil, three tenth deals unto one bullock, two tenth deals unto one ram,"}, {"verse": 29, "start": 309.65, "end": 314.57, "ta": "ஏழு ஆட்டுக்குட்டிகளில் ஒவ்வொன்றிற்காகப் பத்தில் ஒரு பங்கையும்,", "en": "A several tenth deal unto one lamb, throughout the seven lambs;"}, {"verse": 30, "start": 314.57, "end": 321.92, "ta": "உங்களுக்காகப் பாவநிவர்த்தி செய்யும்படிக்கு ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one kid of the goats, to make an atonement for you."}, {"verse": 31, "start": 321.92, "end": 334.12, "ta": "நித்திய சர்வாங்க தகன பலியையும் அதின் போஜனபலியையும் அதின் பானபலியையும் அன்றி, இவைகளையும் செலுத்தக்கடவீர்கள்; இவைகள் பழுதற்றவைகளாயிருக்கவேண்டும்.", "en": "Ye shall offer them beside the continual burnt offering, and his meat offering, (they shall be unto you without blemish) and their drink offerings."}]}, "29": {"chapter": 29, "duration": 448.13, "audio_url": "audio_ot/OT04_29.mp3", "total_verses": 40, "verses": [{"verse": 1, "start": 3.8, "end": 17.01, "ta": "ஏழாம் மாதம் முதல்தேதி பரிசுத்த சபைகூடும் நாளாயிருக்கக்கடவது; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது; அது உங்களுக்கு எக்காளமூதும் நாளாயிருக்கவேண்டும்.", "en": "And in the seventh month, on the first day of the month, ye shall have an holy convocation; ye shall do no servile work: it is a day of blowing the trumpets unto you."}, {"verse": 2, "start": 17.01, "end": 28.94, "ta": "அப்பொழுது நீங்கள் கர்த்தருக்குச் சுகந்த வாசனையான சர்வாங்க தகனபலியாக ஒரு காளையையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும்,", "en": "And ye shall offer a burnt offering for a sweet savour unto the LORD ; one young bullock, one ram, and seven lambs of the first year without blemish:"}, {"verse": 3, "start": 28.94, "end": 39.59, "ta": "அவைகளுக்கு அடுத்த போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவிலே காளைக்காகப் பத்தில் மூன்று பங்கையும், ஆட்டுக்கடாவுக்காக இரண்டு பங்கையும்,", "en": "And their meat offering shall be of flour mingled with oil, three tenth deals for a bullock, and two tenth deals for a ram,"}, {"verse": 4, "start": 39.59, "end": 43.74, "ta": "ஏழு ஆட்டுக்குட்டிகளில் ஒவ்வொன்றிற்காக ஒரு பங்கையும்,", "en": "And one tenth deal for one lamb, throughout the seven lambs:"}, {"verse": 5, "start": 43.74, "end": 49.03, "ta": "உங்கள் பாவநிவர்த்திக்கான பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தி,", "en": "And one kid of the goats for a sin offering, to make an atonement for you:"}, {"verse": 6, "start": 49.03, "end": 68.58, "ta": "மாதப்பிறப்பின் சர்வாங்க தகனபலியையும் அதின் போஜனபலியையும் தினந்தோறும் இடும் சர்வாங்க தகன பலியையும் அதன் போஜனபலியையும், அவைகளின் முறைமைக்கேற்ற பானபலிகளையும் அன்றி, இவைகளையும் கர்த்தருக்குச் சுகந்த வாசனையான சர்வாங்க தகனபலியாகச் செலுத்தக்கடவீர்கள்.", "en": "Beside the burnt offering of the month, and his meat offering, and the daily burnt offering, and his meat offering, and their drink offerings, according unto their manner, for a sweet savour, a sacrifice made by fire unto the LORD ."}, {"verse": 7, "start": 68.58, "end": 81.64, "ta": "இந்த ஏழாம் மாதம் பத்தாம் தேதி உங்களுக்குப் பரிசுத்த சபைகூடும் நாளாயிருக்கக்கடவது; அதிலே நீங்கள் யாதொரு வேலையும் செய்யாமல், உங்கள் ஆத்துமாக்களைத் தாழ்மைப்படுத்தο,", "en": "And ye shall have on the tenth day of this seventh month an holy convocation; and ye shall afflict your souls: ye shall not do any work therein:"}, {"verse": 8, "start": 81.64, "end": 91.76, "ta": "ர்த்தக்க`் சுகந்த சனையான சர்வξங்க தகனபலியாக ஒரு காளையையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும்,", "en": "But ye shall offer a burnt offering unto the LORD for a sweet savour; one young bullock, one ram, and seven lambs of the first year; they shall be unto you without blemish:"}, {"verse": 9, "start": 91.76, "end": 102.41, "ta": "அவைகளின் போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவிலே காளைக்காகப் பத்தில் மூன்று பங்கையும், அந்த ஒரு ஆட்டுக்கடாவுக்காக இரண்டு பங்கையும்,", "en": "And their meat offering shall be of flour mingled with oil, three tenth deals to a bullock, and two tenth deals to one ram,"}, {"verse": 10, "start": 102.41, "end": 107.32, "ta": "ஏழு ஆட்டுக்குட்டிகளில் ஒவ்வொன்றிற்காகப் பத்தில் ஒரு பங்கையும்,", "en": "A several tenth deal for one lamb, throughout the seven lambs:"}, {"verse": 11, "start": 107.32, "end": 123.02, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தி, பாவநிவாரனபலியையும், நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அவைகளின் பானபலிகளையும் அன்றி, இவைகளையும் செலுத்தக்கடவீர்கள்.", "en": "One kid of the goats for a sin offering; beside the sin offering of atonement, and the continual burnt offering, and the meat offering of it, and their drink offerings."}, {"verse": 12, "start": 123.02, "end": 137.89, "ta": "ஏழாம் மாதம் பதினைந்தாம் தேதி உங்களுக்குப் பரிசுத்த சபைகூடும் நாளாயிருக்கக்கடவது; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது; ஏழுநாள் கர்த்தருக்குப் பண்டிகை ஆசரிக்கக்கடவீர்கள்.", "en": "And on the fifteenth day of the seventh month ye shall have an holy convocation; ye shall do no servile work, and ye shall keep a feast unto the LORD seven days:"}, {"verse": 13, "start": 137.89, "end": 150.81, "ta": "நீங்கள் கர்த்தருக்குச் சுகந்த வாசனையுள்ள சர்வாங்க தகனபலியாக பதின்மூன்று காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And ye shall offer a burnt offering, a sacrifice made by fire, of a sweet savour unto the LORD ; thirteen young bullocks, two rams, and fourteen lambs of the first year; they shall be without blemish:"}, {"verse": 14, "start": 150.81, "end": 165.38, "ta": "அவைகளின் போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவிலே அந்தப் பதின்மூன்று காளைகளில் ஒவ்வொன்றிற்காகப் பத்தில் மூன்று பங்கையும், அந்த இரண்டு ஆட்டுக்கடாக்களில் ஒவ்வொன்றிற்காக இரண்டு பங்கையும்,", "en": "And their meat offering shall be of flour mingled with oil, three tenth deals unto every bullock of the thirteen bullocks, two tenth deals to each ram of the two rams,"}, {"verse": 15, "start": 165.38, "end": 170.44, "ta": "பதினான்கு ஆட்டுக்குட்டிகளின் ஒவ்வொன்றிற்காக ஒரு பங்கையும்.", "en": "And a several tenth deal to each lamb of the fourteen lambs:"}, {"verse": 16, "start": 170.44, "end": 181.61, "ta": "நித்திய தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one kid of the goats for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering."}, {"verse": 17, "start": 181.61, "end": 191.13, "ta": "இரண்டாம் நாளிலே பன்னிரண்டு காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the second day ye shall offer twelve young bullocks, two rams, fourteen lambs of the first year without spot:"}, {"verse": 18, "start": 191.13, "end": 202.22, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத் தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 19, "start": 202.22, "end": 214.38, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அவைகளின் பானபலிகளையும் அன்றி, பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one kid of the goats for a sin offering; beside the continual burnt offering, and the meat offering thereof, and their drink offerings."}, {"verse": 20, "start": 214.38, "end": 223.67, "ta": "மூன்றாம் நாளிலே பதினொரு காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the third day eleven bullocks, two rams, fourteen lambs of the first year without blemish;"}, {"verse": 21, "start": 223.67, "end": 234.69, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 22, "start": 234.69, "end": 246.54, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, and his meat offering, and his drink offering."}, {"verse": 23, "start": 246.54, "end": 255.83, "ta": "நான்காம் நாளிலே பத்துக் காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the fourth day ten bullocks, two rams, and fourteen lambs of the first year without blemish:"}, {"verse": 24, "start": 255.83, "end": 266.86, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "Their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 25, "start": 266.86, "end": 278.78, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one kid of the goats for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering."}, {"verse": 26, "start": 278.78, "end": 287.92, "ta": "ஐந்தாம் நாளிலே ஒன்பது காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the fifth day nine bullocks, two rams, and fourteen lambs of the first year without spot:"}, {"verse": 27, "start": 287.92, "end": 298.94, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 28, "start": 298.94, "end": 310.87, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, and his meat offering, and his drink offering."}, {"verse": 29, "start": 310.87, "end": 319.93, "ta": "ஆறாம் நாளிலே எட்டுக் காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the sixth day eight bullocks, two rams, and fourteen lambs of the first year without blemish:"}, {"verse": 30, "start": 319.93, "end": 330.96, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 31, "start": 330.96, "end": 342.96, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலிகளையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering."}, {"verse": 32, "start": 342.96, "end": 351.72, "ta": "ஏழாம் நாளிலே ஏழு காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the seventh day seven bullocks, two rams, and fourteen lambs of the first year without blemish:"}, {"verse": 33, "start": 351.72, "end": 362.75, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 34, "start": 362.75, "end": 374.67, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering."}, {"verse": 35, "start": 374.67, "end": 383.89, "ta": "எட்டாம் நாள் உங்களுக்கு விசேஷித்த ஆசரிப்பு நாளாயிருக்கக்கடவது; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது.", "en": "On the eighth day ye shall have a solemn assembly: ye shall do no servile work therein:"}, {"verse": 36, "start": 383.89, "end": 396.5, "ta": "அப்பொழுது நீங்கள் கர்த்தருக்குச் சுகந்த வாசனையுள்ள தகனமான சர்வாங்க தகனபலியாக ஒரு காளையையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும்,", "en": "But ye shall offer a burnt offering, a sacrifice made by fire, of a sweet savour unto the LORD : one bullock, one ram, seven lambs of the first year without blemish:"}, {"verse": 37, "start": 396.5, "end": 407.22, "ta": "காளையும் ஆட்டுக்கடாவும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "Their meat offering and their drink offerings for the bullock, for the ram, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 38, "start": 407.22, "end": 419.15, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, and his meat offering, and his drink offering."}, {"verse": 39, "start": 419.15, "end": 439.76, "ta": "உங்கள் பொருத்தனைகளையும், உங்கள் உற்சாகபலிகளையும், உங்கள் சர்வாங்க தகனபலிகளையும், உங்கள் போஜனபலிகளையும், உங்கள் பானபலிகளையும், உங்கள் சமாதானபலிகளையும் அன்றி, நீங்கள் உங்கள் பண்டிகைகளிலே கர்த்தருக்குச் செலுத்தவேண்டியவைகள் இவைகளே என்று சொல் என்றார்.", "en": "These things ye shall do unto the LORD in your set feasts, beside your vows, and your freewill offerings, for your burnt offerings, and for your meat offerings, and for your drink offerings, and for your peace offerings."}, {"verse": 40, "start": 439.76, "end": 446.63, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியெல்லாம் மோசே இஸ்ரவேல் புத்திரருக்குச் சொன்னான்.", "en": "And Moses told the children of Israel according to all that the LORD commanded Moses."}]}, "30": {"chapter": 30, "duration": 235.91, "audio_url": "audio_ot/OT04_30.mp3", "total_verses": 16, "verses": [{"verse": 1, "start": 3.8, "end": 10.48, "ta": "மோசே இஸ்ரவேல் புத்திரருடைய கோத்திரங்களின் தலைவரை நோக்கி: கர்த்தர் கட்டளையிடுவது என்னவென்றால்:", "en": "And Moses spake unto the heads of the tribes concerning the children of Israel, saying, This is the thing which the LORD hath commanded."}, {"verse": 2, "start": 10.48, "end": 27.78, "ta": "ஒருவன் கர்த்தருக்கு யாதொரு பொருத்தனை பண்ணினாலும், அல்லது யாதொரு காரியத்தைச் செய்யும்படி ஆணையிட்டுத் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்டாலும், அவன் சொல்தவறாமல் தன் வாயிலிருந்து புறப்பட்ட வாக்கின்படியெல்லாம் செய்யக்கடவன்.", "en": "If a man vow a vow unto the LORD , or swear an oath to bind his soul with a bond; he shall not break his word, he shall do according to all that proceedeth out of his mouth."}, {"verse": 3, "start": 27.78, "end": 39.91, "ta": "தன் தகப்பன் வீட்டிலிருக்கிற ஒரு பெண் பிள்ளை தன் சிறுவயதிலே கர்த்தருக்குப் பொருத்தனைபண்ணி யாதொரு காரியத்தைச் செய்யும்படி தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்டால்,", "en": "If a woman also vow a vow unto the LORD , and bind herself by a bond, being in her father’s house in her youth;"}, {"verse": 4, "start": 39.91, "end": 57.93, "ta": "அவள் செய்த பொருத்தனையையும், அவள் பண்ணிக்கொண்ட நிபந்தனையையும் அவளுடைய தகப்பன் கேட்டும் அவளுக்கு ஒன்றும் சொல்லாதிருப்பானானால், அவள் செய்த எல்லாப் பொருத்தனைகளும் அவள் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்ட நிபந்தனையும் நிறைவேறவேண்டும்.", "en": "And her father hear her vow, and her bond wherewith she hath bound her soul, and her father shall hold his peace at her: then all her vows shall stand, and every bond wherewith she hath bound her soul shall stand."}, {"verse": 5, "start": 57.93, "end": 78.76, "ta": "அவள் செய்த பொருத்தனைகளையும், அவள் செய்யும்படி தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்தின நிபந்தனையையும் அவளுடைய தகப்பன் கேட்கிற நாளிலே அவன் வேண்டாம் என்று தடுத்தால், அது நிறைவேறவேண்டியதில்லை; அவளுடைய தகப்பன் வேண்டாம் என்று தடுத்தபடியால், கர்த்தர் அதை அவளுக்கு மன்னிப்பார்.", "en": "But if her father disallow her in the day that he heareth; not any of her vows, or of her bonds wherewith she hath bound her soul, shall stand: and the LORD shall forgive her, because her father disallowed her."}, {"verse": 6, "start": 78.76, "end": 89.02, "ta": "அவள் பொருத்தனை பண்ணும்போதும், தன் உதடுகளைத் திறந்து தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொள்ளும்போதும், அவளுக்குப் புருஷன் இருந்தால்,", "en": "And if she had at all an husband, when she vowed, or uttered ought out of her lips, wherewith she bound her soul;"}, {"verse": 7, "start": 89.02, "end": 104.82, "ta": "அப்பொழுது அவளுடைய புருஷன் அதைக் கேட்டிருந்தும், அதைக் கேள்விப்படுகிற நாளிலே அவளுக்கு ஒன்றும் சொல்லாதிருந்தால், அவளுடைய பொருத்தனைகளும் அவள் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்தின நிபந்தனையும் நிறைவேறவேண்டும்.", "en": "And her husband heard it , and held his peace at her in the day that he heard it: then her vows shall stand, and her bonds wherewith she bound her soul shall stand."}, {"verse": 8, "start": 104.82, "end": 121.91, "ta": "அவளுடைய புருஷன் அதைக் கேட்கிற நாளில் அவன் வேண்டாம் என்று தடுத்து, அவள் செய்த பொருத்தனையும் அவள் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்ட நிபந்தனையும் செல்லாதபடி செய்தானேயானால், அப்பொழுது கர்த்தர் அதை அவளுக்கு மன்னிப்பார்.", "en": "But if her husband disallowed her on the day that he heard it; then he shall make her vow which she vowed, and that which she uttered with her lips, wherewith she bound her soul, of none effect: and the LORD shall forgive her."}, {"verse": 9, "start": 121.91, "end": 132.39, "ta": "ஒரு விதவையாவது, தள்ளப்பட்டுப்போன ஒரு ஸ்திரீயாவது தன் ஆத்துமாவை எந்த நிபந்தனைக்குட்படுத்திக்கொள்ளுகிறாளோ அந்த நிபந்தனை நிறைவேறவேண்டும்.", "en": "But every vow of a widow, and of her that is divorced, wherewith they have bound their souls, shall stand against her."}, {"verse": 10, "start": 132.39, "end": 144.09, "ta": "அவள் தன் புருஷனுடைய வீட்டில் யாதொரு பொருத்தனை பண்ணினாலும், அல்லது யாதொரு காரியத்தைச் செய்யும்படி ஆணையிட்டுத் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்டாலும்,", "en": "And if she vowed in her husband’s house, or bound her soul by a bond with an oath;"}, {"verse": 11, "start": 144.09, "end": 159.45, "ta": "அவளுடைய புருஷன் அதைக் கேட்டும் அவளுக்கு அதை வேண்டாமென்று தடுக்காமல் மவுனமாயிருந்தால், அவள் செய்த எல்லாப் பொருத்தனைகளும், அவள் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்தின எல்லா நிபந்தனைகளும் நிறைவேறவேண்டும்.", "en": "And her husband heard it , and held his peace at her, and disallowed her not: then all her vows shall stand, and every bond wherewith she bound her soul shall stand."}, {"verse": 12, "start": 159.45, "end": 182.36, "ta": "அவளுடைய புருஷன் அவைகளைக்கேட்ட நாளில் அவைகளைச் செல்லாதபடி பண்ணினால், அப்பொழுது அவள் செய்த பொருத்தனைகளும், அவள் தன் ஆத்துமாவையுட்படுத்தின நிபந்தனையைக்குறித்து அவள் வாயிலிருந்து புறப்பட்டதொன்றும் நிறைவேறவேண்டியதில்லை; அவளுடைய புருஷன் அவைகளைச் செல்லாதபடி பண்ணினதினாலே கர்த்தர் அதை அவளுக்கு மன்னிப்பார்.", "en": "But if her husband hath utterly made them void on the day he heard them; then whatsoever proceeded out of her lips concerning her vows, or concerning the bond of her soul, shall not stand: her husband hath made them void; and the LORD shall forgive her."}, {"verse": 13, "start": 182.36, "end": 194.35, "ta": "எந்தப் பொருத்தனையையும் ஆத்துமாவைத் தாழ்மைப்படுத்தும்படி செய்யப்பட்ட எந்த ஆணையையும், அவளுடைய புருஷன் ஸ்திரப்படுத்தவுங்கூடும், செல்லாதபடி பண்ணவும் கூடும்.", "en": "Every vow, and every binding oath to afflict the soul, her husband may establish it, or her husband may make it void."}, {"verse": 14, "start": 194.35, "end": 215.02, "ta": "அவளுடைய புருஷன் ஒருநாளும் அவளுக்கு ஒன்றும் சொல்லாதிருந்தானாகில், அவன் அவளுடைய எல்லாப் பொருத்தனைகளையும், அவள்பேரிலிருக்கிற அவளுடைய எல்லா நிபந்தனைகளையும் ஸ்திரப்படுத்துகிறான்; அவன் அதைக் கேட்ட நாளிலே அவளுக்கு ஒன்றும் சொல்லாமற் போனதினால், அவைகளை ஸ்திரப்படுத்துகிறான்.", "en": "But if her husband altogether hold his peace at her from day to day; then he establisheth all her vows, or all her bonds, which are upon her: he confirmeth them, because he held his peace at her in the day that he heard them ."}, {"verse": 15, "start": 215.02, "end": 222.42, "ta": "அவன் அவைகளைக் கேட்டபின்பு செல்லாதபடி பண்ணினால், அவளுடைய அக்கிரமத்தை அவன் சுமப்பான் என்றார்.", "en": "But if he shall any ways make them void after that he hath heard them; then he shall bear her iniquity."}, {"verse": 16, "start": 222.42, "end": 234.41, "ta": "புருஷனையும் ஸ்திரீயையும், தகப்பனையும் தகப்பனுடைய வீட்டில் சிறுவயதில் இருக்கிற அவன் குமாரத்தியையும் குறித்து, கர்த்தர் மோசேக்கு விதித்த கட்டளைகள் இவைகளே.", "en": "These are the statutes, which the LORD commanded Moses, between a man and his wife, between the father and his daughter, being yet in her youth in her father’s house."}]}, "31": {"chapter": 31, "duration": 537.59, "audio_url": "audio_ot/OT04_31.mp3", "total_verses": 54, "verses": [{"verse": 1, "start": 3.8, "end": 5.53, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.53, "end": 15.7, "ta": "இஸ்ரவேல் புத்திரர் நிமித்தம் மீதியானியரிடத்தில் பழிவாங்குவாயாக; அதன்பின்பு உன் ஜனத்தாரிடத்தில் சேர்க்கப்படுவாய் என்றார்.", "en": "Avenge the children of Israel of the Midianites: afterward shalt thou be gathered unto thy people."}, {"verse": 3, "start": 15.7, "end": 29.03, "ta": "அப்பொழுது மோசே ஜனங்களை நோக்கி: கர்த்தர் நிமித்தம் மீதியானியரிடத்தில் பழிவாங்கும்பொருட்டு, உங்களில் அவர்கள்மேல் யுத்தத்திற்குப் போகத்தக்கதாக மனிதரைப் பிரித்தெடுங்கள்.", "en": "And Moses spake unto the people, saying, Arm some of yourselves unto the war, and let them go against the Midianites, and avenge the LORD of Midian."}, {"verse": 4, "start": 29.03, "end": 37.77, "ta": "இஸ்ரவேலுடைய எல்லாக் கோத்திரங்களிலும் ஒவ்வொரு கோத்திரத்தில் ஆயிரம்பேரை யுத்தத்திற்கு அனுப்பவேண்டும் என்றான்.", "en": "Of every tribe a thousand, throughout all the tribes of Israel, shall ye send to the war."}, {"verse": 5, "start": 37.77, "end": 49.07, "ta": "அப்படியே இஸ்ரவேலராகிய அநேகம் ஆயிரங்களில், ஒவ்வொரு கோத்திரத்தில் ஆயிரமாயிரம் பேராகப் பன்னீராயிரம்பேர் யுத்தசன்னத்தராய் நிறுத்தப்பட்டார்கள்.", "en": "So there were delivered out of the thousands of Israel, a thousand of every tribe, twelve thousand armed for war."}, {"verse": 6, "start": 49.07, "end": 63.53, "ta": "மோசே அவர்களையும் ஆசாரியனாகிய எலெயாசரின் குமாரன் பினெகாசையும் யுத்தத்திற்கு அனுப்புகையில், அவன் கையிலே பரிசுத்த தட்டுமுட்டுகளையும், தொனிக்கும் பூரிகைகளையும் கொடுத்து அனுப்பினான்.", "en": "And Moses sent them to the war, a thousand of every tribe, them and Phinehas the son of Eleazar the priest, to the war, with the holy instruments, and the trumpets to blow in his hand."}, {"verse": 7, "start": 63.53, "end": 72.94, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே அவர்கள் மீதியானியருடன் யுத்தம்பண்ணி, புருஷர்கள் யாவரையும் கொன்றுபோட்டார்கள்.", "en": "And they warred against the Midianites, as the LORD commanded Moses; and they slew all the males."}, {"verse": 8, "start": 72.94, "end": 89.97, "ta": "அவர்களைக் கொன்றுபோட்டதுமன்றி, மீதியானியரின் ஐந்து ராஜாக்களாகிய ஏவி, ரேக்கேம், சூர், ஊர், ரேபா என்பவர்களையும் கொன்றுபோட்டார்கள். பேயோரின் குமாரனாகிய பிலேயாமையும் பட்டயத்தினாலே கொன்றுபோட்டார்கள்.", "en": "And they slew the kings of Midian, beside the rest of them that were slain; namely , Evi, and Rekem, and Zur, and Hur, and Reba, five kings of Midian: Balaam also the son of Beor they slew with the sword."}, {"verse": 9, "start": 89.97, "end": 103.52, "ta": "அன்றியும் இஸ்ரவேல் புத்திரர் மீதியானியரின் ஸ்திரீகளையும் குழந்தைகளையும் சிறைபிடித்து, அவர்களுடைய மிருகஜீவன்களாகிய ஆடுமாடுகள் யாவையும், மற்ற ஆஸ்திகள் யாவையும் கொள்ளையிட்டு,", "en": "And the children of Israel took all the women of Midian captives, and their little ones, and took the spoil of all their cattle, and all their flocks, and all their goods."}, {"verse": 10, "start": 103.52, "end": 109.1, "ta": "அவர்கள் குடியிருந்த ஊர்கள் கோட்டைகள் யாவையும் அக்கினியால் சுட்டெரித்து,", "en": "And they burnt all their cities wherein they dwelt, and all their goodly castles, with fire."}, {"verse": 11, "start": 109.1, "end": 115.88, "ta": "தாங்கள் கொள்ளையிட்ட பொருளையும் தாங்கள் பிடித்த நரஜீவன் மிருகஜீவன் அனைத்தையும் சேர்த்து,", "en": "And they took all the spoil, and all the prey, both of men and of beasts."}, {"verse": 12, "start": 115.88, "end": 138.25, "ta": "சிறைபிடிக்கப்பட்ட மனிதரையும், மிருகங்களையும், கொள்ளையிட்ட பொருள்களையும் எரிகோவின் அருகேயுள்ள யோர்தானுக்கு இக்கரையில் மோவாபின் சமனான வெளிகளிலுள்ள பாளயத்திலிருந்த மோசேயினிடத்துக்கும், ஆசாரியனாகிய எலெயாசாரினிடத்துக்கும், இஸ்ரவேல் புத்திரராகிய சபையாரிடத்துக்கும் கொண்டுவந்தார்கள்.", "en": "And they brought the captives, and the prey, and the spoil, unto Moses, and Eleazar the priest, and unto the congregation of the children of Israel, unto the camp at the plains of Moab, which are by Jordan near Jericho."}, {"verse": 13, "start": 138.25, "end": 148.34, "ta": "மோசேயும் ஆசாரியனாகிய எலெயாசாரும் சபையின் பிரபுக்கள் எல்லாரும் அவர்களைச் சந்திக்கப் பாளயத்திற்கு வெளியே புறப்பட்டுப்போனார்கள்.", "en": "And Moses, and Eleazar the priest, and all the princes of the congregation, went forth to meet them without the camp."}, {"verse": 14, "start": 148.34, "end": 157.76, "ta": "அப்பொழுது மோசே யுத்தத்திலிருந்து வந்த ஆயிரம்பேருக்குத் தலைவரும், நூறுபேருக்குத் தலைவருமாகிய சேனாபதிகள்மேல் கோபங்கொண்டு,", "en": "And Moses was wroth with the officers of the host, with the captains over thousands, and captains over hundreds, which came from the battle."}, {"verse": 15, "start": 157.76, "end": 163.25, "ta": "அவர்களை நோக்கி: ஸ்திரீகள் எல்லாரையும் உயிரோடே விட்டுவிட்டீர்களா?", "en": "And Moses said unto them, Have ye saved all the women alive?"}, {"verse": 16, "start": 163.25, "end": 178.02, "ta": "பேயோரின் சங்கதியிலே பிலேயாமின் ஆலோசனையினால் இஸ்ரவேல் புத்திரர் கர்த்தருக்கு விரோதமாய்த் துரோகம்பண்ணக் காரணமாயிருந்தவர்கள் இவர்கள்தானே; அதினால் கர்த்தரின் சபையிலே வாதையும் நேரிட்டதே.", "en": "Behold, these caused the children of Israel, through the counsel of Balaam, to commit trespass against the LORD in the matter of Peor, and there was a plague among the congregation of the LORD ."}, {"verse": 17, "start": 178.02, "end": 186.75, "ta": "ஆகையால் குழந்தைகளில் எல்லா ஆண்பிள்ளைகளையும், புருஷசம்யோகத்தை அறிந்த எல்லா ஸ்திரீகளையும் கொன்றுபோடுங்கள்.", "en": "Now therefore kill every male among the little ones, and kill every woman that hath known man by lying with him."}, {"verse": 18, "start": 186.75, "end": 194.29, "ta": "ஸ்திரீகளில் புருஷசம்யோகத்தை அறியாத எல்லாப் பெண்பிள்ளைகளையும் உங்களுக்காக உயிரோடே வையுங்கள்.", "en": "But all the women children, that have not known a man by lying with him, keep alive for yourselves."}, {"verse": 19, "start": 194.29, "end": 212.36, "ta": "பின்பு நீங்கள் ஏழுநாள் பாளயத்திற்குப் புறம்பே தங்குங்கள்; நரஜீவனைக் கொன்றவர்களும், வெட்டுண்டவர்ளைத் தொட்டவர்களுமாகிய நீங்கள் யாவரும் மூன்றாம் நாளிலும் ஏழாம் நாளிலும் உங்களையும் உங்களால் சிறைபிடிக்கப்பட்டவர்களையும் சுத்திகரித்து,", "en": "And do ye abide without the camp seven days: whosoever hath killed any person, and whosoever hath touched any slain, purify both yourselves and your captives on the third day, and on the seventh day."}, {"verse": 20, "start": 212.36, "end": 224.79, "ta": "அந்தப்படியே எல்லா வஸ்திரத்தையும், தோலால் செய்த கருவிகளையும், வெள்ளாட்டுமயிரினால் நெய்தவைகளையும், மரச்சாமான்களையும் சுத்திகரிக்கக்கடவீர்கள் என்றான்.", "en": "And purify all your raiment, and all that is made of skins, and all work of goats’ hair , and all things made of wood."}, {"verse": 21, "start": 224.79, "end": 234.28, "ta": "ஆசாரியனாகிய எலெயாசாரும் யுத்தத்திற்குப் போய்வந்த படைவீரரை நோக்கி: கர்த்தர் மோசேக்குக் கட்டளையிட்ட விதிப்பிரமாணம் என்னவென்றால்:", "en": "And Eleazar the priest said unto the men of war which went to the battle, This is the ordinance of the law which the LORD commanded Moses;"}, {"verse": 22, "start": 234.28, "end": 244.22, "ta": "அக்கினிக்கு நிற்கத்தக்கவைகளாகிய பொன், வெள்ளி, வெண்கலம், இரும்பு, தகரம், ஈயம் ஆகிய இவைகளெல்லாம் சுத்தமாகும்படிக்கு,", "en": "Only the gold, and the silver, the brass, the iron, the tin, and the lead,"}, {"verse": 23, "start": 244.22, "end": 259.21, "ta": "அவைகளை அக்கினியிலே போட்டெடுக்கக்கடவீர்கள்; தீட்டுக்கழிக்கும் தண்ணீராலும் அவைகள் சுத்திகரிக்கப்படவேண்டும்; அக்கினிக்கு நிற்கத்தகாதவைகளையெல்லாம் தண்ணீரினால் சுத்தம்பண்ணக்கடவீர்கள்.", "en": "Every thing that may abide the fire, ye shall make it go through the fire, and it shall be clean: nevertheless it shall be purified with the water of separation: and all that abideth not the fire ye shall make go through the water."}, {"verse": 24, "start": 259.21, "end": 270.43, "ta": "ஏழாம் நாளில் உங்கள் வஸ்திரங்களைத் தோய்க்கவேண்டும்; அப்பொழுது சுத்தமாயிருப்பீர்கள்; பின்பு நீங்கள் பாளயத்திற்குள் வரலாம் என்றான்.", "en": "And ye shall wash your clothes on the seventh day, and ye shall be clean, and afterward ye shall come into the camp."}, {"verse": 25, "start": 270.43, "end": 272.17, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 26, "start": 272.17, "end": 282.11, "ta": "பிடித்துக்கொண்டு வரப்பட்ட மனிதரையும் மிருகங்களையும் நீயும் ஆசாரியனாகிய எலெயாசாரும் சபையினுடைய பிதாக்களாகிய தலைவரும் தொகைபார்த்து,", "en": "Take the sum of the prey that was taken, both of man and of beast, thou, and Eleazar the priest, and the chief fathers of the congregation:"}, {"verse": 27, "start": 282.11, "end": 291.83, "ta": "கொள்ளையிடப்பட்டதை இரண்டு பங்காகப் பங்கிட்டு, யுத்தத்திற்குப் படையெடுத்துப்போனவர்களுக்கும் சபையனைத்திற்கும் கொடுங்கள்.", "en": "And divide the prey into two parts; between them that took the war upon them, who went out to battle, and between all the congregation:"}, {"verse": 28, "start": 291.83, "end": 303.2, "ta": "மேலும் யுத்தத்திற்குப்போன படைவீரரிடத்தில் கர்த்தருக்காக மனிதரிலும் மாடுகளிலும் கழுதைகளிலும் ஆடுகளிலும் ஐந்நூற்றிற்கு ஒரு பிராணி வீதமாக பகுதி வாங்கி,", "en": "And levy a tribute unto the LORD of the men of war which went out to battle: one soul of five hundred, both of the persons, and of the beeves, and of the asses, and of the sheep:"}, {"verse": 29, "start": 303.2, "end": 313.29, "ta": "அவர்களுடைய பாதிப்பங்கில் எடுத்து, கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் படைப்பாக ஆசாரியனாகிய எலெயாசாருக்குக் கொடுக்கவேண்டும்.", "en": "Take it of their half, and give it unto Eleazar the priest, for an heave offering of the LORD ."}, {"verse": 30, "start": 313.29, "end": 330.84, "ta": "இஸ்ரவேல் புத்திரரின் பாதிப்பங்கிலோ மனிதரிலும், மாடுகள் கழுதைகள் ஆடுகளாகிய சகலவித மிருகங்களிலும், ஐம்பதிற்கு ஒன்று வீதமாய் வாங்கி அவைகளைக் கர்த்தருடைய வாசஸ்தலத்தின் காவலைக்காக்கும் லேவியருக்குக் கொடுக்கவேண்டும் என்றார்.", "en": "And of the children of Israel’s half, thou shalt take one portion of fifty, of the persons, of the beeves, of the asses, and of the flocks, of all manner of beasts, and give them unto the Levites, which keep the charge of the tabernacle of the LORD ."}, {"verse": 31, "start": 330.84, "end": 338.0, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, மோசேயும் ஆசாரியனாகிய எலெயாசாரும் செய்தார்கள்.", "en": "And Moses and Eleazar the priest did as the LORD commanded Moses."}, {"verse": 32, "start": 338.0, "end": 343.57, "ta": "படைவீரர் கொள்ளையிட்ட பொருளில், ஆறுலட்சத்து எழுபத்தையாயிரம் ஆடுகளும்,", "en": "And the booty, being the rest of the prey which the men of war had caught, was six hundred thousand and seventy thousand and five thousand sheep,"}, {"verse": 33, "start": 343.57, "end": 345.76, "ta": "எழுபத்தீராயிரம் மாடுகளும்,", "en": "And threescore and twelve thousand beeves,"}, {"verse": 34, "start": 345.76, "end": 349.67, "ta": "அறுபத்தோராயிரம் கழுதைகளும் மீதியாயிருந்தது.", "en": "And threescore and one thousand asses,"}, {"verse": 35, "start": 349.67, "end": 355.55, "ta": "புருஷசம்யோகத்தை அறியாத ஸ்திரீகளில் முப்பத்தீராயிரம்பேர் இருந்தார்கள்.", "en": "And thirty and two thousand persons in all, of women that had not known man by lying with him."}, {"verse": 36, "start": 355.55, "end": 364.74, "ta": "யுத்தஞ்செய்யப் போனவர்களுக்குக் கிடைத்த பாதிப்பங்கின் தொகையாவது: ஆடுகள் மூன்றுலட்சத்து முப்பத்தேழாயிரத்து ஐந்நூறு.", "en": "And the half, which was the portion of them that went out to war, was in number three hundred thousand and seven and thirty thousand and five hundred sheep:"}, {"verse": 37, "start": 364.74, "end": 370.54, "ta": "இந்த ஆடுகளிலே கர்த்தருக்குப் பகுதியாக வந்தது அறுநூற்று எழுபத்தைந்து.", "en": "And the LORD’s tribute of the sheep was six hundred and threescore and fifteen."}, {"verse": 38, "start": 370.54, "end": 377.69, "ta": "மாடுகள் முப்பத்தாறாயிரம்; அவைகளில் கர்த்தருக்குப் பகுதியாக வந்தது எழுபத்திரண்டு.", "en": "And the beeves were thirty and six thousand; of which the LORD’s tribute was threescore and twelve."}, {"verse": 39, "start": 377.69, "end": 385.45, "ta": "கழுதைகள் முப்பதினாயிரத்து ஐந்நூறு; அவைகளில் கர்த்தருக்குப் பகுதியாக வந்தது அறுபத்தொன்று.", "en": "And the asses were thirty thousand and five hundred; of which the LORD’s tribute was threescore and one."}, {"verse": 40, "start": 385.45, "end": 393.66, "ta": "நரஜீவன்கள் பதினாறாயிரம் பேர்; அவர்களில் கர்த்தருக்குப் பகுதியாக வந்தவர்கள் முப்பத்திரண்டுபேர்.", "en": "And the persons were sixteen thousand; of which the LORD’s tribute was thirty and two persons."}, {"verse": 41, "start": 393.66, "end": 404.73, "ta": "கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் அந்தப் பகுதியை, மோசே கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, ஆசாரியனாகிய எலெயாசாரிடத்தில் கொடுத்தான்.", "en": "And Moses gave the tribute, which was the LORD’s heave offering, unto Eleazar the priest, as the LORD commanded Moses."}, {"verse": 42, "start": 404.73, "end": 413.92, "ta": "யுத்தம்பண்ணின பேர்களுக்கும் இஸ்ரவேல் புத்திரருக்கும் மோசே பாதிபாதியாகப் பங்கிட்டதின்படியே சபையாருக்கு வந்த பாதிப்பங்காவது:", "en": "And of the children of Israel’s half, which Moses divided from the men that warred,"}, {"verse": 43, "start": 413.92, "end": 417.99, "ta": "ஆடுகளில் முன்றுலட்சத்து முப்பத்தேழாயிரத்து ஐந்நூறு,", "en": "(Now the half that pertained unto the congregation was three hundred thousand and thirty thousand and seven thousand and five hundred sheep,"}, {"verse": 44, "start": 417.99, "end": 420.25, "ta": "மாடுகளில் முப்பத்தாறாயிரம்,", "en": "And thirty and six thousand beeves,"}, {"verse": 45, "start": 420.25, "end": 423.18, "ta": "கழுதைகளில் முப்பதினாயிரத்து ஐந்நூறு,", "en": "And thirty thousand asses and five hundred,"}, {"verse": 46, "start": 423.18, "end": 426.2, "ta": "நரஜீவன்களில் பதினாயிரம் பேருமே.", "en": "And sixteen thousand persons;)"}, {"verse": 47, "start": 426.2, "end": 444.42, "ta": "இஸ்ரவேல் புத்திரரின் பாதிப்பங்குக்கு வந்த இந்த நரஜீவன்களிலும் மிருகங்களிலும் மோசே ஐம்பதுக்கு ஒன்று வீதமாக எடுத்து, அவைகளைக் கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, கர்த்தருடைய வாசஸ்தலத்தின் காவலைக் காக்கிற லேவியருக்குக் கொடுத்தான்.", "en": "Even of the children of Israel’s half, Moses took one portion of fifty, both of man and of beast, and gave them unto the Levites, which kept the charge of the tabernacle of the LORD ; as the LORD commanded Moses."}, {"verse": 48, "start": 444.42, "end": 451.51, "ta": "பின்பு ஆயிரம்பேருக்குத் தலைவரும் நூறுபேருக்குத் தலைவருமான சேனாபதிகள் மோசேயினிடத்தில் வந்து,", "en": "And the officers which were over thousands of the host, the captains of thousands, and captains of hundreds, came near unto Moses:"}, {"verse": 49, "start": 451.51, "end": 461.45, "ta": "ஊழியக்காரராகிய நாங்கள் எங்கள் கையின் கீழிருக்கிற யுத்தமனிதரைத் தொகைபார்த்தோம்; அவர்களுக்குள்ளே ஒரு ஆளும் குறையவில்லை.", "en": "And they said unto Moses, Thy servants have taken the sum of the men of war which are under our charge, and there lacketh not one man of us."}, {"verse": 50, "start": 461.45, "end": 482.99, "ta": "ஆகையால், கர்த்தருடைய சந்நிதியில் எங்கள் ஆத்துமாக்களுக்காகப் பாவநிவிர்த்தி செய்யும்பொருட்டு, எங்களுக்குக் கிடைத்த பொற்பணிகளாகிய பாதசரங்களையும், அஸ்தகடகங்களையும், மோதிரங்களையும், காதணிகளையும், காப்புகளையும் கர்த்தருக்குக் காணிக்கையாகக் கொண்டுவந்தோம் என்றார்கள்.", "en": "We have therefore brought an oblation for the LORD , what every man hath gotten, of jewels of gold, chains, and bracelets, rings, earrings, and tablets, to make an atonement for our souls before the LORD ."}, {"verse": 51, "start": 482.99, "end": 492.93, "ta": "அப்பொழுது மோசேயும் ஆசாரியனாகிய எலெயாசாரும் சகலவித வேலைப்பாடான பணிதிகளான அந்தப் பொன்னாபரணங்களை அவர்களிடத்தில் வாங்கினார்கள்.", "en": "And Moses and Eleazar the priest took the gold of them, even all wrought jewels."}, {"verse": 52, "start": 492.93, "end": 509.35, "ta": "இப்படி ஆயிரம்பேருக்குத் தலைவரானவர்களாலும் நூறுபேருக்குத் தலைவரானவர்களாலும் கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் காணிக்கையாகச் செலுத்தப்பட்ட பொன் முழுவதும் பதினாறாயிரத்து எழுநூற்று ஐம்பது சேக்கல் நிறையாயிருந்தது.", "en": "And all the gold of the offering that they offered up to the LORD , of the captains of thousands, and of the captains of hundreds, was sixteen thousand seven hundred and fifty shekels."}, {"verse": 53, "start": 509.35, "end": 516.43, "ta": "யுத்தத்திற்குப் போன மனிதர் ஒவ்வொருவரும் தங்கள் தங்களுக்காகக் கொள்ளையிட்டிருந்தார்கள்.", "en": "( For the men of war had taken spoil, every man for himself.)"}, {"verse": 54, "start": 516.43, "end": 536.09, "ta": "அந்தப் பொன்னை மோசேயும் ஆசாரியனாகிய எலெயாசாரும் ஆயிரம்பேருக்குத் தலைவரானவர்களின் கையிலும், நூறுபேருக்குத் தலைவரானவர்களின் கையிலும் வாங்கி, இஸ்ரவேல் புத்திரருக்கு ஞாபகக்குறியாக ஆசரிப்புக் கூடாரத்திலே கர்த்தருடைய சந்நிதியில் கொண்டுவந்து வைத்தார்கள்.", "en": "And Moses and Eleazar the priest took the gold of the captains of thousands and of hundreds, and brought it into the tabernacle of the congregation, for a memorial for the children of Israel before the LORD ."}]}, "32": {"chapter": 32, "duration": 471.6, "audio_url": "audio_ot/OT04_32.mp3", "total_verses": 42, "verses": [{"verse": 1, "start": 3.8, "end": 18.41, "ta": "ரூபன் புத்திரருக்கும் காத் புத்திரருக்கும் ஆடுமாடுகள் மிகவும் திரளாயிருந்தது; அவர்கள் யாசேர் தேசத்தையும் கீலேயாத் தேசத்தையும் பார்த்தபோது, அது ஆடுமாடுகளுக்குத் தகுந்த இடமென்று கண்டார்கள்.", "en": "Now the children of Reuben and the children of Gad had a very great multitude of cattle: and when they saw the land of Jazer, and the land of Gilead, that, behold, the place was a place for cattle;"}, {"verse": 2, "start": 18.41, "end": 26.96, "ta": "ஆகையால் ரூபன் புத்திரரும் காத் புத்திரரும் வந்து, மோசேயையும் ஆசாரியனாகிய எலெயாசாரையும் சபையின் பிரபுக்களையும் நோக்கி:", "en": "The children of Gad and the children of Reuben came and spake unto Moses, and to Eleazar the priest, and unto the princes of the congregation, saying,"}, {"verse": 3, "start": 26.96, "end": 42.43, "ta": "கர்த்தர் இஸ்ரவேல் சபைக்கு முன்பாக முறிய அடித்த அதரோத், தீபோன், யாசேர், நிம்ரா, எஸ்போன், எலெயாலெ, சேபாம், நேபோ, பெயோன் என்னும் பட்டணங்களைச் சேர்ந்த நாடானது ஆடுமாடுகளுக்குத் தகுந்த இடம்.", "en": "Ataroth, and Dibon, and Jazer, and Nimrah, and Heshbon, and Elealeh, and Shebam, and Nebo, and Beon,"}, {"verse": 4, "start": 42.43, "end": 45.49, "ta": "உமது அடியாருக்கு ஆடுமாடுகள் உண்டு.", "en": "Even the country which the LORD smote before the congregation of Israel, is a land for cattle, and thy servants have cattle:"}, {"verse": 5, "start": 45.49, "end": 59.46, "ta": "உம்முடைய கண்களில் எங்களுக்குத் தயை கிடைத்ததானால், எங்களை யோர்தான் நதிக்கு அப்புறம் கடந்துபோகப்பண்ணீராக; இந்த நாட்டை உமது அடியாருக்குக் காணியாட்சியாகக் கொடுக்கவேண்டும் என்றார்கள்.", "en": "Wherefore, said they, if we have found grace in thy sight, let this land be given unto thy servants for a possession, and bring us not over Jordan."}, {"verse": 6, "start": 59.46, "end": 69.58, "ta": "அப்பொழுது மோசே காத் புத்திரரையும் ரூபன் புத்திரரையும் நோக்கி: உங்கள் சகோதரர் யுத்தத்திற்குப் போகையில், நீங்கள் இங்கே இருப்பீர்களோ?", "en": "And Moses said unto the children of Gad and to the children of Reuben, Shall your brethren go to war, and shall ye sit here?"}, {"verse": 7, "start": 69.58, "end": 79.91, "ta": "கர்த்தர் இஸ்ரவேல் புத்திரருக்குக் கொடுத்த தேசத்திற்கு அவர்கள் போகாதபடிக்கு, நீங்கள் அவர்கள் இருதயத்தைத் திடனற்றுப்போகப்பண்ணுகிறதென்ன?", "en": "And wherefore discourage ye the heart of the children of Israel from going over into the land which the LORD hath given them?"}, {"verse": 8, "start": 79.91, "end": 89.11, "ta": "அந்த தேசத்தைப் பார்ப்பதற்கு நான் உங்கள் பிதாக்களைக் காதேஸ்பர்னேயாவிலிருந்து அனுப்பினபோது அவர்களும் இப்படியே செய்தார்கள்.", "en": "Thus did your fathers, when I sent them from Kadesh-barnea to see the land."}, {"verse": 9, "start": 89.11, "end": 104.0, "ta": "அவர்கள் எஸ்கோல் பள்ளத்தாக்குமட்டும் போய், அத்தேசத்தைப் பார்த்துவந்து, இஸ்ரவேல் புத்திரர் கர்த்தர் தங்களுக்குக் கொடுத்த தேசத்திற்குப் போகாதபடிக்கு அவர்கள் இருதயத்தைத் திடனற்றுப்போகப்பண்ணினார்கள்.", "en": "For when they went up unto the valley of Eshcol, and saw the land, they discouraged the heart of the children of Israel, that they should not go into the land which the LORD had given them."}, {"verse": 10, "start": 104.0, "end": 107.14, "ta": "அதினால் கர்த்தர் அந்நாளிலே கோபம் மூண்டவராகி:", "en": "And the LORD’s anger was kindled the same time, and he sware, saying,"}, {"verse": 11, "start": 107.14, "end": 114.91, "ta": "உத்தமமாய் என்னைப் பின்பற்றின கேனேசியனான எப்புன்னேயின் குமாரன் காலேபும், நூனின் குமாரன் யோசுவாவும் தவிர,", "en": "Surely none of the men that came up out of Egypt, from twenty years old and upward, shall see the land which I sware unto Abraham, unto Isaac, and unto Jacob; because they have not wholly followed me:"}, {"verse": 12, "start": 114.91, "end": 133.08, "ta": "எகிப்திலிருந்து வந்தவர்களில் இருபது வயதுமுதல் அதற்கு மேற்பட்டமனிதர்களில் ஒருவரும் என்னை உத்தமமாய்ப் பின்பற்றாதபடியால், அவர்கள் நான் ஆபிரகாமுக்கும் ஈசாக்குக்கும் யாக்கோபுக்கும் ஆணையிட்டுக்கொடுத்த தேசத்தைக் காண்பதில்லை என்று ஆணையிட்டிருக்கிறார்.", "en": "Save Caleb the son of Jephunneh the Kenezite, and Joshua the son of Nun: for they have wholly followed the LORD ."}, {"verse": 13, "start": 133.08, "end": 147.47, "ta": "அப்படியே கர்த்தருடைய கோபம் இஸ்ரவேலின்மேல் மூண்டது; கர்த்தருடைய சமுகத்தில் பொல்லாப்புச் செய்த அந்தச் சந்ததியெல்லாம் நிர்மூலமாகுமட்டும் அவர்களை வனாந்தரத்திலே நாற்பது வருஷம் அலையப்பண்ணினார்.", "en": "And the LORD’s anger was kindled against Israel, and he made them wander in the wilderness forty years, until all the generation, that had done evil in the sight of the LORD , was consumed."}, {"verse": 14, "start": 147.47, "end": 161.8, "ta": "இப்பொழுதும் இதோ இஸ்ரவேலர்மேலிருக்கும் கர்த்தருடைய கோபத்தின் உக்கிரத்தை இன்னும் அதிகரிக்கப்பண்ணும்படி, நீங்கள் உங்கள் பிதாக்களின் ஸ்தானத்திலே பாவமுள்ள பெருங்கூட்டமாய் எழும்பியிருக்கிறீர்கள்.", "en": "And, behold, ye are risen up in your fathers’ stead, an increase of sinful men, to augment yet the fierce anger of the LORD toward Israel."}, {"verse": 15, "start": 161.8, "end": 174.06, "ta": "நீங்கள் அவரைவிட்டுப் பின்வாங்கினால், அவர் இன்னும் அவர்களை வனாந்தரத்தில் இருக்கப்பண்ணுவார்; இப்படி நீங்கள் இந்த ஜனங்களையெல்லாம் அழியப்பண்ணுவீர்கள் என்றான்.", "en": "For if ye turn away from after him, he will yet again leave them in the wilderness; and ye shall destroy all this people."}, {"verse": 16, "start": 174.06, "end": 184.68, "ta": "அப்பொழுது அவர்கள் அவன் சமீபத்தில் வந்து: எங்கள் ஆடுமாடுகளுக்காகத் தொழுவங்களையும், எங்கள் பிள்ளைகளுக்காகப் பட்டணங்களையும் இங்கே கட்டுவோம்.", "en": "And they came near unto him, and said, We will build sheepfolds here for our cattle, and cities for our little ones:"}, {"verse": 17, "start": 184.68, "end": 202.92, "ta": "நாங்களோ இஸ்ரவேல் புத்திரரை அவர்கள் ஸ்தானத்திலே கொண்டுபோய்ச் சேர்க்குமளவும், யுத்தசன்னத்தாரய்த் தீவிரத்தோடே அவர்களுக்கு முன்பாக நடப்போம்; எங்கள் பிள்ளைகள் இத்தேசத்துக் குடிகளினிமித்தம் அரணான பட்டணங்களிலே குடியிருக்கக் கேட்டுக்கொள்ளுகிறோம்.", "en": "But we ourselves will go ready armed before the children of Israel, until we have brought them unto their place: and our little ones shall dwell in the fenced cities because of the inhabitants of the land."}, {"verse": 18, "start": 202.92, "end": 213.32, "ta": "இஸ்ரவேல் புத்திரர் யாவரும் தங்கள் தங்கள் சுதந்தரத்தைச் சுதந்தரித்துக் கொள்ளும்வரைக்கும், நாங்கள் எங்கள் வீடுகளுக்குத் திரும்புவதில்லை.", "en": "We will not return unto our houses, until the children of Israel have inherited every man his inheritance."}, {"verse": 19, "start": 213.32, "end": 227.15, "ta": "யோர்தானுக்கு இப்புறத்தில் கிழக்கே எங்களுக்குச் சுதந்தரம் உண்டானபடியினாலே, நாங்கள் அவர்களோடேகூட யோர்தானுக்கு அக்கரையிலும், அதற்கு அப்புறத்திலும் சுதந்தரம் வாங்கமாட்டோம் என்றார்கள்.", "en": "For we will not inherit with them on yonder side Jordan, or forward; because our inheritance is fallen to us on this side Jordan eastward."}, {"verse": 20, "start": 227.15, "end": 235.42, "ta": "அப்பொழுது மோசே அவர்களை நோக்கி: நீங்கள் இந்த வார்த்தையின்படியே செய்து, கர்த்தருடைய சமுகத்தில் யுத்தசன்னத்தராகி,", "en": "And Moses said unto them, If ye will do this thing, if ye will go armed before the LORD to war,"}, {"verse": 21, "start": 235.42, "end": 247.68, "ta": "கர்த்தர் தம்முடைய சத்துருக்களைத் தம்முடைய முகத்திற்கு முன்னின்று துரத்திவிடுமளவும், நீங்கள் யாவரும் அவருடைய சமுகத்தில் யுத்தசன்னத்தராய் யோர்தானைக் கடந்துபோவீர்களனால்,", "en": "And will go all of you armed over Jordan before the LORD , until he hath driven out his enemies from before him,"}, {"verse": 22, "start": 247.68, "end": 265.71, "ta": "அத்தேசம் கர்த்தருக்கு முன்பாக வசப்படுத்தப்பட்டபின்பு நீங்கள் திரும்பிவந்து, கர்த்தருக்கு முன்பாகவும், இஸ்ரவேலருக்கு முன்பாகவும், குற்றமில்லாதிருப்பீர்கள்; அதற்குப்பின்பு இந்த தேசம் கர்த்தருக்கு முன்பாக உங்களுக்குச் சுதந்தரமாகும்.", "en": "And the land be subdued before the LORD : then afterward ye shall return, and be guiltless before the LORD , and before Israel; and this land shall be your possession before the LORD ."}, {"verse": 23, "start": 265.71, "end": 278.39, "ta": "நீங்கள் இப்படிச் செய்யாமற்போனால், கர்த்தருக்கு விரோதமாகப் பாவம் செய்தவர்களாயிருப்பீர்கள்; உங்கள் பாவம் உங்களைத் தொடர்ந்துபிடிக்கும் என்று நிச்சயமாய் அறியுங்கள்.", "en": "But if ye will not do so, behold, ye have sinned against the LORD : and be sure your sin will find you out."}, {"verse": 24, "start": 278.39, "end": 288.87, "ta": "உங்கள் பிள்ளைகளுக்காகப் பட்டணங்களையும், உங்கள் ஆடுமாடுகளுக்காகத் தொழுவங்களையும் கட்டி, உங்கள் வாய்மொழியின்படியே செய்யுங்கள் என்றான்.", "en": "Build you cities for your little ones, and folds for your sheep; and do that which hath proceeded out of your mouth."}, {"verse": 25, "start": 288.87, "end": 298.7, "ta": "அப்பொழுது காத் புத்திரரும் ரூபன் புத்திரரும் மோசேயை நோக்கி: எங்கள் ஆண்டவன் கட்டளையிட்டபடியே உமது ஊழியக்காரராகிய நாங்கள் செய்வோம்.", "en": "And the children of Gad and the children of Reuben spake unto Moses, saying, Thy servants will do as my lord commandeth."}, {"verse": 26, "start": 298.7, "end": 309.61, "ta": "எங்கள் பிள்ளைகளையும் எங்கள் மனைவிகளும், எங்கள் ஆடுமாடு முதலான எங்களுடைய எல்லா மிருகஜீவன்களோடும் இங்கே கீலேயாத்தின் பட்டணங்களில் இருப்பார்கள்.", "en": "Our little ones, our wives, our flocks, and all our cattle, shall be there in the cities of Gilead:"}, {"verse": 27, "start": 309.61, "end": 320.87, "ta": "உமது ஊழியக்காரராகிய நாங்களோ எங்கள் ஆண்டவன் சொன்னபடியே, ஒவ்வொருவரும் யுத்தசன்னத்தராய், கர்த்தருடைய சமுகத்தில் யுத்தத்திற்குப் போவோம் என்றார்கள்.", "en": "But thy servants will pass over, every man armed for war, before the LORD to battle, as my lord saith."}, {"verse": 28, "start": 320.87, "end": 332.91, "ta": "அப்பொழுது மோசே அவர்களுக்காக ஆசாரியனாகிய எலெயாசாருக்கும், நூனின் குமாரனாகிய யோசுவாவுக்கும், இஸ்ரவேல் புத்திரருடைய கோத்திர பிதாக்களாகிய தலைவர்களுக்கும் கட்டளையிட்டு:", "en": "So concerning them Moses commanded Eleazar the priest, and Joshua the son of Nun, and the chief fathers of the tribes of the children of Israel:"}, {"verse": 29, "start": 332.91, "end": 349.73, "ta": "காத் புத்திரரும் ரூபன் புத்திரரும் அவரவர் கர்த்தருடைய சமுகத்தில் யுத்தசன்னத்தாராய் உங்களோடேகூட யோர்தானைக் கடந்துபோனால், அத்தேசம் உங்களுக்கு வசப்பட்டபின்பு, அவர்களுக்குக் கீலேயாத் தேசத்தைச் சுதந்தரமாகக் கொடுக்கக்கடவீர்கள்.", "en": "And Moses said unto them, If the children of Gad and the children of Reuben will pass with you over Jordan, every man armed to battle, before the LORD , and the land shall be subdued before you; then ye shall give them the land of Gilead for a possession:"}, {"verse": 30, "start": 349.73, "end": 360.06, "ta": "உங்களோடேகூட யுத்தசன்னத்தராய்க் கடந்துபோகாதிருந்தார்களேயானால், அவர்கள் உங்கள் நடுவே கானான் தேசத்திலே சுதந்தரம் அடையக்கடவர்கள் என்றான்.", "en": "But if they will not pass over with you armed, they shall have possessions among you in the land of Canaan."}, {"verse": 31, "start": 360.06, "end": 369.61, "ta": "காத் புத்திரரும் ரூபன் புத்திரரும் பிரதியுத்தரமாக: உம்முடைய ஊழியக்காரராகிய நாங்கள் கர்த்தர் எங்களுக்குச் சொன்னபடியே செய்வோம்.", "en": "And the children of Gad and the children of Reuben answered, saying, As the LORD hath said unto thy servants, so will we do."}, {"verse": 32, "start": 369.61, "end": 382.37, "ta": "யோர்தானுக்கு இக்கரையிலே எங்கள் சுதந்தரத்தின் காணியாட்சி எங்களுக்கு உரியதாகும்படி நாங்கள் கர்த்தருடைய சமுகத்தில் யுத்தசன்னத்தாராய்க் கானான்தேசத்திற்குப் போவோம் என்றார்கள்.", "en": "We will pass over armed before the LORD into the land of Canaan, that the possession of our inheritance on this side Jordan may be ours."}, {"verse": 33, "start": 382.37, "end": 405.18, "ta": "அப்பொழுது மோசே காத் புத்திரருக்கும், ரூபன் புத்திரருக்கும், யோசேப்பின் குமாரனாகிய மனாசேயின் பாதிக் கோத்திரத்தாருக்கும், எமோரியருடைய ராஜாவாகிய சீகோனின் ராஜ்யத்தையும், பாசானுடைய ராஜாவாகிய ஓகின் ராஜ்யத்தையும், அவைகளைச் சேர்ந்த தேசங்களையும் அவைகளின் எல்லையைச் சுற்றிலுமுள்ள பட்டணங்களையும் கொடுத்தான்.", "en": "And Moses gave unto them, even to the children of Gad, and to the children of Reuben, and unto half the tribe of Manasseh the son of Joseph, the kingdom of Sihon king of the Amorites, and the kingdom of Og king of Bashan, the land, with the cities thereof in the coasts, even the cities of the country round about."}, {"verse": 34, "start": 405.18, "end": 409.31, "ta": "பின்பு காத் சந்ததியார் தீபோன், அதரோத் ஆரோவேர்.", "en": "And the children of Gad built Dibon, and Ataroth, and Aroer,"}, {"verse": 35, "start": 409.31, "end": 412.59, "ta": "ஆத்ரோத், சோபான், யாசேர், யொகிபேயா,", "en": "And Atroth, Shophan, and Jaazer, and Jogbehah,"}, {"verse": 36, "start": 412.59, "end": 419.57, "ta": "பெத்நிம்ரா, பெத்தாரன் என்னும் அரணான பட்டணங்களையும் ஆட்டுத்தொழுவங்களையும் கட்டினார்கள்.", "en": "And Beth-nimrah, and Beth-haran, fenced cities: and folds for sheep."}, {"verse": 37, "start": 419.57, "end": 423.71, "ta": "ரூபன் சந்ததியார் எஸ்போன், எலெயாலெ, கீரியத்தாயீம்,", "en": "And the children of Reuben built Heshbon, and Elealeh, and Kirjathaim,"}, {"verse": 38, "start": 423.71, "end": 433.83, "ta": "பேர்கள் மற்றப்பட்ட நேபோ, பாகால்மெயோன், சீப்மா என்பவைகளைக் கட்டி, தாங்கள் கட்டின பட்டணங்களுக்கு வேறே பேர்களைக் கொடுத்தார்கள்.", "en": "And Nebo, and Baal-meon, (their names being changed,) and Shibmah: and gave other names unto the cities which they builded."}, {"verse": 39, "start": 433.83, "end": 443.8, "ta": "மனாசேயின் குமாரனாகிய மாகீரின் புத்திரர் கீலேயாத்திற்குப் போய், அதைக் கட்டிக்கொண்டு, அதிலிருந்த எமோரியரைத் துரத்திவிட்டார்கள்.", "en": "And the children of Machir the son of Manasseh went to Gilead, and took it, and dispossessed the Amorite which was in it."}, {"verse": 40, "start": 443.8, "end": 452.14, "ta": "அப்பொழுது மோசே கீலேயாத்தை மனாசேயின் குமாரனாகிய மாகீருக்குக் கொடுத்தான்; அவர்கள் அதிலே குடியேறினார்கள்.", "en": "And Moses gave Gilead unto Machir the son of Manasseh; and he dwelt therein."}, {"verse": 41, "start": 452.14, "end": 460.91, "ta": "மனாசேயின் குமாரனாகிய யாவீர் போய், அவர்களுடைய கிராமங்களைக் கட்டிக்கொண்டு, அவைகளுக்கு யாவீர் என்று பேரிட்டான்.", "en": "And Jair the son of Manasseh went and took the small towns thereof, and called them Havoth-jair."}, {"verse": 42, "start": 460.91, "end": 470.1, "ta": "நோபாக் போய், கேனாத்தையும் அதின் கிராமங்களையும் கட்டிக்கொண்டு, அதற்குத் தன் நாமத்தின்படியே நோபாக் என்று பேரிட்டான்.", "en": "And Nobah went and took Kenath, and the villages thereof, and called it Nobah, after his own name."}]}, "33": {"chapter": 33, "duration": 438.56, "audio_url": "audio_ot/OT04_33.mp3", "total_verses": 56, "verses": [{"verse": 1, "start": 3.8, "end": 13.41, "ta": "மோசே ஆரோன் என்பவர்களுடைய கையின்கீழ்த் தங்கள் தங்கள் சேனைகளின்படியே எகிப்துதேசத்திலிருந்து புறப்பட்ட இஸ்ரவேல் புத்திரருடைய பிரயாணங்களின் விபரம்:", "en": "These are the journeys of the children of Israel, which went forth out of the land of Egypt with their armies under the hand of Moses and Aaron."}, {"verse": 2, "start": 13.41, "end": 24.96, "ta": "மோசே தனக்குக் கர்த்தர் கட்டளையிட்டபடியே அவர்கள் புறப்பட்டபிரகாரமாக அவர்களுடைய பிரயாணங்களை எழுதினான்; அவர்கள் ஒவ்வொரு இடங்களிலிருந்து புறப்பட்டுப்பண்ணின பிரயாணங்களாவன:", "en": "And Moses wrote their goings out according to their journeys by the commandment of the LORD : and these are their journeys according to their goings out."}, {"verse": 3, "start": 24.96, "end": 38.6, "ta": "முதலாம் மாதத்தின் பதினைந்தாம் தேதியிலே அவர்கள் ராமசேசை விட்டுப்புறப்பட்டார்கள்; பஸ்காவுக்கு மறுநாளிலே, எகிப்தியர் எல்லாரும் பார்க்க, இஸ்ரவேல் புத்திரர் பெலத்தகையுடன் புறப்பட்டார்கள்.", "en": "And they departed from Rameses in the first month, on the fifteenth day of the first month; on the morrow after the passover the children of Israel went out with an high hand in the sight of all the Egyptians."}, {"verse": 4, "start": 38.6, "end": 50.01, "ta": "அப்பொழுது எகிப்தியர் கர்த்தர் தங்களுக்குள்ளே சங்கரித்த தலைச்சன்பிள்ளைகளையெல்லாம் அடக்கம்பண்ணினார்கள்; அவர்கள் தேவர்களின்பேரிலும் கர்த்தர் நீதிசெலுத்தினார்.", "en": "For the Egyptians buried all their firstborn, which the LORD had smitten among them: upon their gods also the LORD executed judgments."}, {"verse": 5, "start": 50.01, "end": 57.0, "ta": "பின்பு இஸ்ரவேல் புத்திரர் ராமசேசிலிருந்து புறப்பட்டுப்போய், சுக்கோத்திலே பாளயமிறங்கினார்கள்.", "en": "And the children of Israel removed from Rameses, and pitched in Succoth."}, {"verse": 6, "start": 57.0, "end": 64.32, "ta": "சுக்கோத்திலிருந்து புறப்பட்டுப்போய், வனாந்தரத்தின் எல்லையிலிருக்கிற ஏத்தாமிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Succoth, and pitched in Etham, which is in the edge of the wilderness."}, {"verse": 7, "start": 64.32, "end": 75.61, "ta": "ஏத்தாமிலிருந்து புறப்பட்டுப்போய், பாகால்செபோனுக்கு எதிராக இருக்கிற ஈரோத் பள்ளத்தாக்கின் முன்னடிக்குத்திரும்பி, மிக்தோலுக்கு முன்பாகப் பாளயமிறங்கினார்கள்.", "en": "And they removed from Etham, and turned again unto Pi-hahiroth, which is before Baal-zephon: and they pitched before Migdol."}, {"verse": 8, "start": 75.61, "end": 87.36, "ta": "ஈரோத்தை விட்டுப் புறப்பட்டு, சமுத்திரத்தை நடுவாகக் கடந்து வனாந்தரத்திற்குப்போய், ஏத்தாம் வனாந்தரத்திலே மூன்றுநாள் பிரயாணம்பண்ணி, மாராவிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from before Pi-hahiroth, and passed through the midst of the sea into the wilderness, and went three days’ journey in the wilderness of Etham, and pitched in Marah."}, {"verse": 9, "start": 87.36, "end": 98.31, "ta": "மாராவிலிருந்து புறப்பட்டு, ஏலிமுக்குப் போனார்கள்; ஏலிமிலே பன்னிரண்டு நீரூற்றுகளும் எழுபது பேரீச்சமரங்களும் இருந்தது, அங்கே பாளயமிறங்கினார்கள்.", "en": "And they removed from Marah, and came unto Elim: and in Elim were twelve fountains of water, and threescore and ten palm trees; and they pitched there."}, {"verse": 10, "start": 98.31, "end": 104.02, "ta": "ஏலிமிலிருந்து புறப்பட்டு, சிவந்த சமுத்திரத்தின் அருகே பாளயமிறங்கினார்கள்.", "en": "And they removed from Elim, and encamped by the Red sea."}, {"verse": 11, "start": 104.02, "end": 110.47, "ta": "சிவந்த சமுத்திரத்தை விட்டுப் புறப்பட்டுப்போய், சீன்வனாந்தரத்திலே பாளயமிறங்கினார்கள்.", "en": "And they removed from the Red sea, and encamped in the wilderness of Sin."}, {"verse": 12, "start": 110.47, "end": 116.11, "ta": "சீன்வனாந்தரத்திலிருந்து புறப்பட்டுப்போய், தொப்காவிலே பாளயமிறங்கினார்கள்.", "en": "And they took their journey out of the wilderness of Sin, and encamped in Dophkah."}, {"verse": 13, "start": 116.11, "end": 121.15, "ta": "தொப்காவிலிருந்து புறப்பட்டுப்போய், ஆலுூசிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Dophkah, and encamped in Alush."}, {"verse": 14, "start": 121.15, "end": 130.22, "ta": "ஆலுூசிலிருந்து புறப்பட்டுப்போய், ரெவிதீமிலே பாளயமிறங்கினார்கள்; அங்கே ஜனங்களுக்குக் குடிக்கத் தண்ணீர் இல்லாதிருந்தது.", "en": "And they removed from Alush, and encamped at Rephidim, where was no water for the people to drink."}, {"verse": 15, "start": 130.22, "end": 136.06, "ta": "ரெவிதீமிலிருந்து புறப்பட்டுப்போய், சீனாய் வனாந்தரத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Rephidim, and pitched in the wilderness of Sinai."}, {"verse": 16, "start": 136.06, "end": 142.44, "ta": "சீனாய் வனாந்தரத்திலிருந்து புறப்பட்டுப்போய், கிப்ரோத் அத்தாவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from the desert of Sinai, and pitched at Kibroth-hattaavah."}, {"verse": 17, "start": 142.44, "end": 148.15, "ta": "கிப்ரோத் அத்தாவிலிருந்து புறப்பட்டுப்போய், ஆஸரோத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Kibroth-hattaavah, and encamped at Hazeroth."}, {"verse": 18, "start": 148.15, "end": 153.33, "ta": "ஆஸரோத்திலிருந்து புறப்பட்டுப்போய், ரித்மாவிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Hazeroth, and pitched in Rithmah."}, {"verse": 19, "start": 153.33, "end": 158.9, "ta": "ரித்மாவிலிருந்து புறப்பட்டுப்போய், ரிம்மோன்பேரேசிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Rithmah, and pitched at Rimmon-parez."}, {"verse": 20, "start": 158.9, "end": 164.48, "ta": "ரிம்மோன்பேரேசிலிருந்து புறப்பட்டுப்போய், லிப்னாவிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Rimmon-parez, and pitched in Libnah."}, {"verse": 21, "start": 164.48, "end": 169.51, "ta": "லிப்னாவிலிருந்து புறப்பட்டுப்போய், ரீசாவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Libnah, and pitched at Rissah."}, {"verse": 22, "start": 169.51, "end": 174.62, "ta": "ரீசாவிலிருந்து புறப்பட்டுப்போய், கேலத்தாவிலே பாளயமிறங்கினார்கள்.", "en": "And they journeyed from Rissah, and pitched in Kehelathah."}, {"verse": 23, "start": 174.62, "end": 180.26, "ta": "கேலத்தாவிலிருந்து புறப்பட்டுப்போய், சாப்பேர் மலையிலே பாளயமிறங்கினார்கள்.", "en": "And they went from Kehelathah, and pitched in mount Shapher."}, {"verse": 24, "start": 180.26, "end": 185.7, "ta": "சாப்பேர் மலையிலிருந்து புறப்பட்டுப்போய், ஆரதாவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from mount Shapher, and encamped in Haradah."}, {"verse": 25, "start": 185.7, "end": 190.94, "ta": "ஆரதாவிலிருந்து புறப்பட்டுப்போய், மக்கெலோத்திலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Haradah, and pitched in Makheloth."}, {"verse": 26, "start": 190.94, "end": 196.32, "ta": "மக்கெலோத்திலிருந்து புறப்பட்டுப்போய், தாகாத்திலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Makheloth, and encamped at Tahath."}, {"verse": 27, "start": 196.32, "end": 201.35, "ta": "தாகாத்திலிருந்து புறப்பட்டுப்போய், தாராகிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Tahath, and pitched at Tarah."}, {"verse": 28, "start": 201.35, "end": 206.39, "ta": "தாராகிலிருந்து புறப்பட்டுப்போய், மித்காவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Tarah, and pitched in Mithcah."}, {"verse": 29, "start": 206.39, "end": 211.63, "ta": "மித்காவிலிருந்து புறப்பட்டுப்போய், அஸ்மோனாவிலே பாளயமிறங்கினார்கள்.", "en": "And they went from Mithcah, and pitched in Hashmonah."}, {"verse": 30, "start": 211.63, "end": 217.0, "ta": "அஸ்மோனாவிலிருந்து புறப்பட்டுப்போய், மோசெரோத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Hashmonah, and encamped at Moseroth."}, {"verse": 31, "start": 217.0, "end": 222.58, "ta": "மோசெரோத்திலிருந்து புறப்பட்டுப்போய், பெனெயாக்கானிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Moseroth, and pitched in Bene-jaakan."}, {"verse": 32, "start": 222.58, "end": 228.42, "ta": "பெனெயாக்கானிலிருந்து புறப்பட்டுப்போய், கித்காத் மலையிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Bene-jaakan, and encamped at Hor-hagidgad."}, {"verse": 33, "start": 228.42, "end": 234.27, "ta": "கித்காத் மலையிலிருந்து புறப்பட்டுப்போய், யோத்பாத்தாவிலே பாளயமிறங்கினார்கள்.", "en": "And they went from Hor-hagidgad, and pitched in Jotbathah."}, {"verse": 34, "start": 234.27, "end": 239.78, "ta": "யோத்பாத்தாவிலிருந்து புறப்பட்டுப்போய், எப்ரோனாவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Jotbathah, and encamped at Ebronah."}, {"verse": 35, "start": 239.78, "end": 245.42, "ta": "எப்ரோனாவிலிருந்து புறப்பட்டுப்போய், எசியோன் கேபேரிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Ebronah, and encamped at Ezion-gaber."}, {"verse": 36, "start": 245.42, "end": 252.14, "ta": "எசியோன் கேபேரிலிருந்து புறப்பட்டுப்போய், காதேசாகிய சீன்வனாந்தரத்திலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Ezion-gaber, and pitched in the wilderness of Zin, which is Kadesh."}, {"verse": 37, "start": 252.14, "end": 259.99, "ta": "காதேசிலிருந்து புறப்பட்டுப்போய், ஏதோம் தேசத்தின் எல்லையிலிருக்கிற ஓர் என்னும் மலையிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Kadesh, and pitched in mount Hor, in the edge of the land of Edom."}, {"verse": 38, "start": 259.99, "end": 274.37, "ta": "அப்பொழுது ஆசாரியனாகிய ஆரோன் கர்த்தருடைய கட்டளையின்படியே ஓர் என்னும் மலையின்மேல் ஏறி, அங்கே இஸ்ரவேல் புத்திரர் எகிப்துதேசத்திலிருந்து புறப்பட்ட நாற்பதாம் வருஷம் ஐந்தாம் மாதம் முதல் தேதியிலே மரணமடைந்தான்.", "en": "And Aaron the priest went up into mount Hor at the commandment of the LORD , and died there, in the fortieth year after the children of Israel were come out of the land of Egypt, in the first day of the fifth month."}, {"verse": 39, "start": 274.37, "end": 280.28, "ta": "ஆரோன் ஓர் என்னும் மலையிலே மரணமடைந்தபோது, நூற்றிருபத்துமூன்று வயதாயிருந்தான்.", "en": "And Aaron was an hundred and twenty and three years old when he died in mount Hor."}, {"verse": 40, "start": 280.28, "end": 289.82, "ta": "அந்நாட்களிலே கானான் தேசத்தின் தென்திசையில் குடியிருந்த கானானியனாகிய ஆராத் என்னும் ராஜா இஸ்ரவேல் புத்திரர் வருகிறதைக் கேள்விப்பட்டான்.", "en": "And king Arad the Canaanite, which dwelt in the south in the land of Canaan, heard of the coming of the children of Israel."}, {"verse": 41, "start": 289.82, "end": 295.73, "ta": "ஓர் என்னும் மலையை விட்டுப் புறப்பட்டுப்போய், சல்மோனாவிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from mount Hor, and pitched in Zalmonah."}, {"verse": 42, "start": 295.73, "end": 300.83, "ta": "சல்மோனாவிலிருந்து புறப்பட்டுப்போய், பூனோனிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Zalmonah, and pitched in Punon."}, {"verse": 43, "start": 300.83, "end": 305.81, "ta": "பூனோனிலிருந்து புறப்பட்டுப்போய், ஓபோத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Punon, and pitched in Oboth."}, {"verse": 44, "start": 305.81, "end": 312.99, "ta": "ஒபோத்திலிருந்து புறப்பட்டுப்போய், மோவாபின் எல்லையிலுள்ள அபாரீமின் மேடுகளிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Oboth, and pitched in Ije-abarim, in the border of Moab."}, {"verse": 45, "start": 312.99, "end": 318.77, "ta": "அந்த மேடுகளை விட்டுப் புறப்பட்டுப்போய், தீபோன்காத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Iim, and pitched in Dibon-gad."}, {"verse": 46, "start": 318.77, "end": 325.08, "ta": "தீபோன்காத்திலிருந்து புறப்பட்டுப்போய், அல்மோன் திப்லத்தாயிமிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Dibon-gad, and encamped in Almon-diblathaim."}, {"verse": 47, "start": 325.08, "end": 332.74, "ta": "அல்மோன் திப்லத்தாயிமிலிருந்து புறப்பட்டுப்போய், நேபோவுக்கு எதிரான அபாரீம் மலைகளிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Almon-diblathaim, and pitched in the mountains of Abarim, before Nebo."}, {"verse": 48, "start": 332.74, "end": 341.54, "ta": "அபாரீம் மலைகளிலிருந்து புறப்பட்டுப்போய், எரிகோவின் அருகே யோர்தானைச்சார்ந்த மோவாபின் சமனான வெளிகளிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from the mountains of Abarim, and pitched in the plains of Moab by Jordan near Jericho."}, {"verse": 49, "start": 341.54, "end": 350.68, "ta": "யோர்தானைச் சார்ந்த மோவாபின் சமனான வெளிகளில் அவர்கள் பெத்யெசிமோத்தைத் தொடங்கி, ஆபேல்சித்தீம்மட்டும் பாளயமிறங்கியிருந்தார்கள்.", "en": "And they pitched by Jordan, from Beth-jesimoth even unto Abel-shittim in the plains of Moab."}, {"verse": 50, "start": 350.68, "end": 356.25, "ta": "எரிகோவின் அருகே யோர்தானைச் சார்ந்த மோவாபின் சமனான வெளிகளிலே கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the plains of Moab by Jordan near Jericho, saying,"}, {"verse": 51, "start": 356.25, "end": 364.31, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நீங்கள் யோர்தானைக் கடந்து, கானான்தேசத்தில் போய்ச் சேரும்போது,", "en": "Speak unto the children of Israel, and say unto them, When ye are passed over Jordan into the land of Canaan;"}, {"verse": 52, "start": 364.31, "end": 378.08, "ta": "அத்தேசத்துக் குடிகளையெல்லாம் உங்களுக்கு முன்பாகத் துரத்திவிட்டு, அவர்களுடைய எல்லாச் சிலைகளையும் வார்ப்பிக்கப்பட்ட அவர்களுடைய எல்லா விக்கிரகங்களையும் அழித்து, அவர்கள் மேடைகளையெல்லாம் நிர்மூலமாக்கி,", "en": "Then ye shall drive out all the inhabitants of the land from before you, and destroy all their pictures, and destroy all their molten images, and quite pluck down all their high places:"}, {"verse": 53, "start": 378.08, "end": 388.49, "ta": "தேசத்திலுள்ளவர்களைத் துரத்திவிட்டு, அதிலே குடியிருக்கக்கடவீர்கள்; அந்தத் தேசத்தைச் சுதந்தரித்துக்கொள்ளும்படி அதை உங்களுக்குக் கொடுத்தேன்.", "en": "And ye shall dispossess the inhabitants of the land, and dwell therein: for I have given you the land to possess it."}, {"verse": 54, "start": 388.49, "end": 412.07, "ta": "சீட்டுப்போட்டு, தேசத்தை உங்கள் குடும்பங்களுக்குச் சுதந்தரங்களாகப் பங்கிட்டு, அதிக ஜனங்களுக்கு அதிக சுதந்தரமும், கொஞ்ச ஜனங்களுக்குக் கொஞ்சச் சுதந்தரமும் கொடுக்கக்கடவீர்கள்; அவரவர்க்குச் சீட்டு விழும் இடம் எதுவோ, அவ்விடம் அவரவர்க்கு உரியதாகும்; உங்கள் பிதாக்களுடைய கோத்திரங்களின்படியே சுதந்தரம் பெற்றுக்கொள்ளக்கடவீர்கள்.", "en": "And ye shall divide the land by lot for an inheritance among your families: and to the more ye shall give the more inheritance, and to the fewer ye shall give the less inheritance: every man’s inheritance shall be in the place where his lot falleth; according to the tribes of your fathers ye shall inherit."}, {"verse": 55, "start": 412.07, "end": 430.41, "ta": "நீங்கள் தேசத்தின் குடிகளை உங்களுக்கு முன்பாகத் துரத்திவிடாமலிருப்பீர்களானால், அப்பொழுது அவர்களில் நீங்கள் மீதியாக வைக்கிறவர்கள் உங்கள் கண்களில் முள்ளுகளும் உங்கள் விலாக்களிலே கூர்களுமாயிருந்து, நீங்கள் குடியிருக்கிற தேசத்திலே உங்களை உபத்திரவப்படுத்துவார்கள்.", "en": "But if ye will not drive out the inhabitants of the land from before you; then it shall come to pass, that those which ye let remain of them shall be pricks in your eyes, and thorns in your sides, and shall vex you in the land wherein ye dwell."}, {"verse": 56, "start": 430.41, "end": 437.06, "ta": "அன்றியும், நான் அவர்களுக்குச் செய்ய நினைத்ததை உங்களுக்குச் செய்வேன் என்று சொல் என்றார்.", "en": "Moreover it shall come to pass, that I shall do unto you, as I thought to do unto them."}]}, "34": {"chapter": 34, "duration": 254.84, "audio_url": "audio_ot/OT04_34.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 5.5, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.5, "end": 19.76, "ta": "நீ இஸ்ரவேல் புத்திரருக்குக் கட்டளையிட்டுச் சொல்லவேண்டியது என்னவென்றால்: கானான்தேசம் அதின் எல்லைகள் உட்பட உங்களுக்குச் சுதந்தரமாகக் கிடைக்கப்போகிறது; நீங்கள் கானான்தேசத்தில் சேரும்போது,", "en": "Command the children of Israel, and say unto them, When ye come into the land of Canaan; (this is the land that shall fall unto you for an inheritance, even the land of Canaan with the coasts thereof:)"}, {"verse": 3, "start": 19.76, "end": 31.95, "ta": "உங்கள் தென்புறம் சீன்வனாந்தரம்தொடங்கி ஏதோம் தேசத்தின் ஓரமட்டும் இருக்கும்; கிழக்கே இருக்கிற உப்புக்கடலின் கடைசி தொடங்கி உங்கள் தென் எல்லையாயிருக்கும்.", "en": "Then your south quarter shall be from the wilderness of Zin along by the coast of Edom, and your south border shall be the outmost coast of the salt sea eastward:"}, {"verse": 4, "start": 31.95, "end": 46.79, "ta": "உங்கள் எல்லை தெற்கிலிருந்து அக்கராபீம் மேடுகளைச் சுற்றி, சீன்வனாந்தரம்வரையில் போய், தெற்கிலே காதேஸ்பர்னேயாவுக்கும், அங்கேயிருந்து ஆத்சார் அதாருக்கும், அங்கேயிருந்து அஸ்மோனாவுக்கும் போய்,", "en": "And your border shall turn from the south to the ascent of Akrabbim, and pass on to Zin: and the going forth thereof shall be from the south to Kadesh-barnea, and shall go on to Hazar-addar, and pass on to Azmon:"}, {"verse": 5, "start": 46.79, "end": 52.78, "ta": "அஸ்மோனாவிலிருந்து எகிப்தின் நதிவரைக்கும் சுற்றிப்போய்க் கடலில் முடியும்.", "en": "And the border shall fetch a compass from Azmon unto the river of Egypt, and the goings out of it shall be at the sea."}, {"verse": 6, "start": 52.78, "end": 60.61, "ta": "மேற்றிசைக்குப் பெருங்கடலே உங்களுக்கு எல்லை; அதுவே உங்களுக்கு மேற்புறத்து எல்லையாயிருக்கும்.", "en": "And as for the western border, ye shall even have the great sea for a border: this shall be your west border."}, {"verse": 7, "start": 60.61, "end": 67.85, "ta": "உங்களுக்கு வடதிசை எல்லை பெருங்கடல் தொடங்கி, ஓர் என்னும் மலையை உங்களுக்குக் குறிப்பாக வைத்து,", "en": "And this shall be your north border: from the great sea ye shall point out for you mount Hor:"}, {"verse": 8, "start": 67.85, "end": 77.01, "ta": "ஓர் என்னும் மலை தொடங்கி, ஆமாத்திற்குப் போகிற வழியைக் குறிப்பாகவைத்து, அங்கேயிருந்து அந்த எல்லை சேதாத்திற்குப் போய்,", "en": "From mount Hor ye shall point out your border unto the entrance of Hamath; and the goings forth of the border shall be to Zedad:"}, {"verse": 9, "start": 77.01, "end": 86.39, "ta": "அங்கேயிருந்து அது சிப்ரோனுக்குப்போய், ஆத்சார் ஏனானிலே முடியும்; அதுவே உங்களுக்கு வடபுறத்து எல்லையாயிருக்கும்.", "en": "And the border shall go on to Ziphron, and the goings out of it shall be at Hazar-enan: this shall be your north border."}, {"verse": 10, "start": 86.39, "end": 92.82, "ta": "உங்களுக்குக் கீழ்த்திசை எல்லைக்கு ஆத்சார் ஏனானிலிருந்து சேப்பாமைக் குறிப்பாக வைத்து,", "en": "And ye shall point out your east border from Hazar-enan to Shepham:"}, {"verse": 11, "start": 92.82, "end": 103.23, "ta": "சேப்பாமிலிருந்து எல்லையானது ஆயினுக்குக் கிழக்கிலுள்ள ரிப்லாபரியந்தமும், அங்கேயிருந்து கின்னரேத் கடல்பரியந்தமும் அதின் கீழ்க்கரையோரமாய்,", "en": "And the coast shall go down from Shepham to Riblah, on the east side of Ain; and the border shall descend, and shall reach unto the side of the sea of Chinnereth eastward:"}, {"verse": 12, "start": 103.23, "end": 114.53, "ta": "அங்கேயிருந்து யோர்தான்பரியந்தமும் போய், உப்புக்கடலில் முடியும்; இந்தச் சுற்றெல்லைகளையுடைய தேசமே உங்களுக்குரிய தேசம் என்று சொல் என்றார்.", "en": "And the border shall go down to Jordan, and the goings out of it shall be at the salt sea: this shall be your land with the coasts thereof round about."}, {"verse": 13, "start": 114.53, "end": 128.79, "ta": "அப்பொழுது மோசே இஸ்ரவேல் புத்திரரை நோக்கி: ஒன்பதரைக் கோத்திரத்தாருக்குக் கொடுக்கும்படி கர்த்தர் கட்டளையிட்டதும், நீங்கள் சீட்டுப்போட்டுச் சுதந்தரித்துக்கொள்ளவேண்டியதுமான தேசம் இதுவே.", "en": "And Moses commanded the children of Israel, saying, This is the land which ye shall inherit by lot, which the LORD commanded to give unto the nine tribes, and to the half tribe:"}, {"verse": 14, "start": 128.79, "end": 147.26, "ta": "ரூபன் புத்திரர் தங்கள் பிதாக்களுடைய வம்சத்தின்படியும், காத் புத்திரர் தங்கள் பிதாக்களுடைய வம்சத்தின்படியும், தங்கள் சுதந்தரத்தைப் பெற்றுக்கொண்டதும் அல்லாமல், மனாசேயின் பாதிக் கோத்திரத்தாரும் தங்கள் சுதந்தரத்தைப் பெற்றுக்கொண்டார்கள்.", "en": "For the tribe of the children of Reuben according to the house of their fathers, and the tribe of the children of Gad according to the house of their fathers, have received their inheritance; and half the tribe of Manasseh have received their inheritance:"}, {"verse": 15, "start": 147.26, "end": 159.23, "ta": "இந்த இரண்டரைக் கோத்திரத்தாரும் சூரியோதய திசையாகிய கிழக்கே எரிகோவின் அருகேயுள்ள யோர்தானுக்கு இப்புறத்திலே தங்கள் சுதந்தரத்தப் பெற்றுக்கொண்டார்கள் என்றான்.", "en": "The two tribes and the half tribe have received their inheritance on this side Jordan near Jericho eastward, toward the sunrising."}, {"verse": 16, "start": 159.23, "end": 161.44, "ta": "மேலும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 17, "start": 161.44, "end": 171.05, "ta": "உங்களுக்கு தேசத்தைப் பங்கிட்டுக்கொடுக்கும் மனிதரின் நாமங்களாவன: ஆசாரியனாகிய எலெயாசாரும், நூனின் குமாரனாகிய யோசுவாவுமே.", "en": "These are the names of the men which shall divide the land unto you: Eleazar the priest, and Joshua the son of Nun."}, {"verse": 18, "start": 171.05, "end": 178.95, "ta": "அன்றியும், தேசத்தைப் பங்கிடும்படி ஒவ்வொரு கோத்திரத்தில் ஒவ்வொரு தலைவனையும் தெரிந்துகொள்ளுங்கள்.", "en": "And ye shall take one prince of every tribe, to divide the land by inheritance."}, {"verse": 19, "start": 178.95, "end": 185.23, "ta": "அந்த மனிதருடைய நாமங்களாவன: யூதா கோத்திரத்துக்கு எப்புன்னேயின் குமாரனாகிய காலேபும்,", "en": "And the names of the men are these: Of the tribe of Judah, Caleb the son of Jephunneh."}, {"verse": 20, "start": 185.23, "end": 190.7, "ta": "சிமியோன் புத்திரரின் கோத்திரத்துக்கு அம்மியூதின் குமாரனாகிய சாமுவேலும்,", "en": "And of the tribe of the children of Simeon, Shemuel the son of Ammihud."}, {"verse": 21, "start": 190.7, "end": 195.35, "ta": "பென்யமீன் கோத்திரத்துக்குக் கிஸ்லோனின் குமாரனாகிய எலிதாதும்,", "en": "Of the tribe of Benjamin, Elidad the son of Chislon."}, {"verse": 22, "start": 195.35, "end": 201.48, "ta": "தாண் புத்திரரின் கோத்திரத்துக்கு யொக்லியின் குமாரனாகிய புக்கி என்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Dan, Bukki the son of Jogli."}, {"verse": 23, "start": 201.48, "end": 209.31, "ta": "யோசேப்பின் குமாரனாகிய மனாசே புத்திரரின் கோத்திரத்துக்கு எபோதின் குமாரனாகிய அன்னியேல் என்னும் பிரபுவும்,", "en": "The prince of the children of Joseph, for the tribe of the children of Manasseh, Hanniel the son of Ephod."}, {"verse": 24, "start": 209.31, "end": 216.26, "ta": "எப்பிராயீம் புத்திரரின் கோத்திரத்துக்குச் சிப்தானின் குமாரனாகிய கேமுவேல் என்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Ephraim, Kemuel the son of Shiphtan."}, {"verse": 25, "start": 216.26, "end": 223.13, "ta": "செபுலோன் புத்திரரின் கோத்திரத்துக்குப் பர்னாகின் குமாரனாகிய எலிசாப்பான் என்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Zebulun, Elizaphan the son of Parnach."}, {"verse": 26, "start": 223.13, "end": 229.7, "ta": "இசக்கார் புத்திரரின் கோத்திரத்துக்கு ஆசானின் குமாரனாகிய பல்த்தியேல் என்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Issachar, Paltiel the son of Azzan."}, {"verse": 27, "start": 229.7, "end": 236.13, "ta": "ஆசேர் புத்திரரின் கோத்திரத்துக்குச் செலோமியின் குமாரனாகிய அகியூத்தென்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Asher, Ahihud the son of Shelomi."}, {"verse": 28, "start": 236.13, "end": 243.81, "ta": "நப்தலி புத்திரரின் கோத்திரத்துக்கு அம்மியூதின் குமாரனாகிய பெதாக்கேல் என்னும் பிரபுவுமே என்றார்.", "en": "And the prince of the tribe of the children of Naphtali, Pedahel the son of Ammihud."}, {"verse": 29, "start": 243.81, "end": 253.34, "ta": "கானான்தேசத்திலே இஸ்ரவேல் புத்திரருக்குச் சுதந்தரங்களைப் பங்கிட்டுக் கொடுக்கிறதற்குக் கர்த்தர் கட்டளையிட்டவர்கள் இவர்களே.", "en": "These are they whom the LORD commanded to divide the inheritance unto the children of Israel in the land of Canaan."}]}, "35": {"chapter": 35, "duration": 382.97, "audio_url": "audio_ot/OT04_35.mp3", "total_verses": 34, "verses": [{"verse": 1, "start": 3.8, "end": 9.33, "ta": "எரிகோவின் அருகே யோர்தானைச் சேர்ந்த மோவாபின் சமனான வெளிகளிலே கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the plains of Moab by Jordan near Jericho, saying,"}, {"verse": 2, "start": 9.33, "end": 25.78, "ta": "இஸ்ரவேல் புத்திரர் தங்கள் காணியாட்சியாகிய சுதந்தரத்திலே லேவியருக்குக் குடியிருக்கும்படி பட்டணங்களைக் கொடுக்கவேண்டும் என்று அவர்களுக்குக் கட்டளையிடு; அந்தப் பட்டணங்களைச் சூழ்ந்திருக்கிற வெளிநிலங்களையும் லேவியருக்குக் கொடுக்கவேண்டும்.", "en": "Command the children of Israel, that they give unto the Levites of the inheritance of their possession cities to dwell in; and ye shall give also unto the Levites suburbs for the cities round about them."}, {"verse": 3, "start": 25.78, "end": 39.5, "ta": "அந்தப் பட்டணங்கள் அவர்கள் குடியிருப்பதற்கும், அவைகளைச் சூழ்ந்த வெளிநிலங்கள் அவர்களுடைய ஆடுமாடுகளுக்கும், அவர்களுடைய ஆஸ்திகளுக்கும், அவர்களுடைய சகல மிருக ஜீவன்களுக்கும் குறிக்கப்படவேண்டும்.", "en": "And the cities shall they have to dwell in; and the suburbs of them shall be for their cattle, and for their goods, and for all their beasts."}, {"verse": 4, "start": 39.5, "end": 50.03, "ta": "நீங்கள் லேவியருக்குக் கொடுக்கும் பட்டணங்களைச் சூழ்ந்த வெளிநிலங்கள் பட்டணத்தின் மதில்தொடங்கி, வெளியிலே சுற்றிலும் ஆயிரமுழ தூரத்துக்கு எட்டவேண்டும்.", "en": "And the suburbs of the cities, which ye shall give unto the Levites, shall reach from the wall of the city and outward a thousand cubits round about."}, {"verse": 5, "start": 50.03, "end": 67.34, "ta": "பட்டணம் மத்தியில் இருக்க, பட்டணத்தின் வெளிப்புறந்தொடங்கி, கிழக்கே இரண்டாயிரமுழமும், தெற்கே இரண்டாயிரமுழமும், மேற்கே இரண்டாயிரமுழமும், வடக்கே இரண்டாயிரமுழமும் அளந்துவிடக்கடவீர்கள்; இது அவர்கள் பட்டணங்களுக்கு வெளிநிலங்களாயிருப்பதாக.", "en": "And ye shall measure from without the city on the east side two thousand cubits, and on the south side two thousand cubits, and on the west side two thousand cubits, and on the north side two thousand cubits; and the city shall be in the midst: this shall be to them the suburbs of the cities."}, {"verse": 6, "start": 67.34, "end": 84.66, "ta": "நீங்கள் லேவியருக்குக் கொடுக்கும் பட்டணங்களில் அடைக்கலத்துக்காக ஆறு பட்டணங்கள் இருக்கவேண்டும்; கொலைசெய்தவன் அங்கே தப்பி ஓடிப்போகிறதற்கு அவைகளைக் குறிக்கக்கடவீர்கள்; அவைகளையல்லாமல், நாற்பத்திரண்டு பட்டணங்களை அவர்களுக்குக் கொடுக்கவேண்டும்.", "en": "And among the cities which ye shall give unto the Levites there shall be six cities for refuge, which ye shall appoint for the manslayer, that he may flee thither: and to them ye shall add forty and two cities."}, {"verse": 7, "start": 84.66, "end": 92.92, "ta": "நீங்கள் லேவியருக்குக் கொடுக்கவேண்டிய பட்டணங்களெல்லாம் நாற்பத்தெட்டுப் பட்டணங்களும் அவைகளைச் சூழ்ந்த வெளிநிலங்களுமே.", "en": "So all the cities which ye shall give to the Levites shall be forty and eight cities: them shall ye give with their suburbs."}, {"verse": 8, "start": 92.92, "end": 114.77, "ta": "நீங்கள் இஸ்ரவேல் புத்திரரின் சுதந்தரத்திலிருந்து அந்தப் பட்டணங்களைப்பிரித்துக் கொடுக்கும்போது, அதிகமுள்ளவர்களிடத்திலிருந்து அதிகமும், கொஞ்சமுள்ளவர்களிடத்திலிருந்து கொஞ்சமும் பிரித்துக்கொடுக்கவேண்டும்; அவரவர் சுதந்தரித்துக்கொண்ட சுதந்தரத்தின்படியே தங்கள் பட்டணங்களில் லேவியருக்குக் கொடுக்கக்கடவர்கள் என்றார்.", "en": "And the cities which ye shall give shall be of the possession of the children of Israel: from them that have many ye shall give many; but from them that have few ye shall give few: every one shall give of his cities unto the Levites according to his inheritance which he inheriteth."}, {"verse": 9, "start": 114.77, "end": 116.9, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 10, "start": 116.9, "end": 124.89, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நீங்கள் யோர்தானைக் கடந்து, கானான்தேசத்தில் பிரவேசிக்கும்போது,", "en": "Speak unto the children of Israel, and say unto them, When ye be come over Jordan into the land of Canaan;"}, {"verse": 11, "start": 124.89, "end": 133.29, "ta": "கைப்பிசகாய் ஒருவனைக் கொன்று போட்டவன் ஓடிப்போயிருக்கத்தக்க அடைக்கலப்பட்டணங்களாகச் சில பட்டணங்களைக் குறிக்கக்கடவீர்கள்.", "en": "Then ye shall appoint you cities to be cities of refuge for you; that the slayer may flee thither, which killeth any person at unawares."}, {"verse": 12, "start": 133.29, "end": 145.28, "ta": "கொலைசெய்தவன் நியாயசபையிலே நியாயம் விசாரிக்கப்படுமுன் சாகாமல், பழிவாங்குகிறவன் கைக்குத் தப்பிப்போயிருக்கும்படி, அவைகள் உங்களுக்கு அடைக்கலப்பட்டணங்களாய் இருக்கக்கடவது.", "en": "And they shall be unto you cities for refuge from the avenger; that the manslayer die not, until he stand before the congregation in judgment."}, {"verse": 13, "start": 145.28, "end": 151.14, "ta": "நீங்கள் கொடுக்கும் பட்டணங்களில் ஆறு பட்டணங்கள் அடைக்கலத்துக்காக இருக்கவேண்டும்.", "en": "And of these cities which ye shall give six cities shall ye have for refuge."}, {"verse": 14, "start": 151.14, "end": 161.0, "ta": "யோர்தானுக்கு இப்புறத்தில் மூன்று பட்டணங்களையும், கானான்தேசத்தில் மூன்று பட்டணங்களையும் கொடுக்கவேண்டும், அவைகள் அடைக்கலப்பட்டணங்களாம்.", "en": "Ye shall give three cities on this side Jordan, and three cities shall ye give in the land of Canaan, which shall be cities of refuge."}, {"verse": 15, "start": 161.0, "end": 175.85, "ta": "கைப்பிசகாய் ஒருவனைக் கொன்றவன் எவனோ, அவன் அங்கே ஓடிப்போயிருக்கும்படிக்கு, அந்த ஆறு பட்டணங்களும் இஸ்ரவேல் புத்திரருக்கும் உங்கள் நடுவே இருக்கும் பரதேசிக்கும் அந்நியனுக்கும் அடைக்கலப்பட்டணங்களாய் இருக்கவேண்டும்.", "en": "These six cities shall be a refuge, both for the children of Israel, and for the stranger, and for the sojourner among them: that every one that killeth any person unawares may flee thither."}, {"verse": 16, "start": 175.85, "end": 186.24, "ta": "ஒருவன் இருப்பு ஆயுதத்தினால் ஒருவனை வெட்டினதினால் அவன் செத்துப்போனால், வெட்டினவன் கொலைபாதகனாயிருக்கிறான்; கொலைபாதகன் கொலைசெய்யப்படவேண்டும்.", "en": "And if he smite him with an instrument of iron, so that he die, he is a murderer: the murderer shall surely be put to death."}, {"verse": 17, "start": 186.24, "end": 197.36, "ta": "ஒருவன் ஒரு கல்லை எடுத்து, சாகத்தக்கதாக ஒருவன்மேல் எறிகிறதினாலே அவன் செத்துப்போனால், கல்லெறிந்தவன் கொலைபாதகனாயிருக்கிறான், அவன் கொலைசெய்யப்படவேண்டும்.", "en": "And if he smite him with throwing a stone, wherewith he may die, and he die, he is a murderer: the murderer shall surely be put to death."}, {"verse": 18, "start": 197.36, "end": 209.69, "ta": "ஒருவன் தன் கையில் ஒரு மர ஆயுதத்தை எடுத்து, சாகத்தக்கதாக ஒருவனை அடித்ததினால் அவன் செத்துப்போனால், அடித்தவன் கொலைபாதகனாயிருக்கிறான்; கொலைபாதகன் கொலைசெய்யப்படவேண்டும்.", "en": "Or if he smite him with an hand weapon of wood, wherewith he may die, and he die, he is a murderer: the murderer shall surely be put to death."}, {"verse": 19, "start": 209.69, "end": 216.88, "ta": "பழிவாங்கவேண்டியவனே கொலைபாதகனைக் கொல்லவேண்டும்; அவனைக் கண்டமாத்திரத்தில் அவனைக் கொன்றுபோடலாம்.", "en": "The revenger of blood himself shall slay the murderer: when he meeteth him, he shall slay him."}, {"verse": 20, "start": 216.88, "end": 225.41, "ta": "ஒருவன் பகையினால் ஒருவனை விழத்தள்ளினதினாலாயினும், பதுங்கியிருந்து அவன் சாகத்தக்கதாய் அவன்மேல் ஏதாகிலும் எறிந்ததினாலாயினும்,", "en": "But if he thrust him of hatred, or hurl at him by laying of wait, that he die;"}, {"verse": 21, "start": 225.41, "end": 238.99, "ta": "அவனைப் பகைத்து, தன் கையினால் அடித்ததினாலாயினும், அவன் செத்துப்போனால், அடித்தவன் கொலைபாதகன்; அவன் கொலைசெய்யப்படவேண்டும் பழிவாங்குகிறவன் கொலைபாதகனைக் கண்டமாத்திரத்தில் கொன்றுபோடலாம்.", "en": "Or in enmity smite him with his hand, that he die: he that smote him shall surely be put to death; for he is a murderer: the revenger of blood shall slay the murderer, when he meeteth him."}, {"verse": 22, "start": 238.99, "end": 248.72, "ta": "ஒருவன் பகையொன்றும் இல்லாமல் சடுதியில் ஒருவனைத் தள்ளி விழப்பண்ணினதினாலாயினும், பதுங்கியிராமல் யாதொரு ஆயுதத்தை அவன்மேல் பட எறிந்ததினாலாயினும்,", "en": "But if he thrust him suddenly without enmity, or have cast upon him any thing without laying of wait,"}, {"verse": 23, "start": 248.72, "end": 261.77, "ta": "அவனுக்குப் பகைஞனாயிராமலும் அவனுக்குத் தீங்கு செய்ய நினையாமலுமிருக்கையில், ஒருவனைக் கொன்றுபோடத்தக்க ஒரு கல்லினால் அவனைக்காணாமல் எறிய, அது அவன்மேல் பட்டதினாலாயினும், அவன் செத்துப்போனால்,", "en": "Or with any stone, wherewith a man may die, seeing him not, and cast it upon him, that he die, and was not his enemy, neither sought his harm:"}, {"verse": 24, "start": 261.77, "end": 267.44, "ta": "அப்பொழுது கொலைசெய்தவனையும் பழிவாங்குகிறவனையும் சபையார் இந்த நியாயப்படி விசாரித்து,", "en": "Then the congregation shall judge between the slayer and the revenger of blood according to these judgments:"}, {"verse": 25, "start": 267.44, "end": 284.35, "ta": "கொலைசெய்தவனைப் பழிவாங்குகிறவனுடைய கைக்குத் தப்புவித்து, அவன் ஓடிப்போயிருந்த அடைக்கலப்பட்டணத்துக்கு அவனைத் திரும்பப் போகும்படி செய்யக்கடவர்கள்; பரிசுத்த தைலத்தினால் அபிஷேகம் பெற்ற பிரதான ஆசாரியன் மரணமடையுமட்டும் அவன் அதிலே இருக்கக்கடவன்.", "en": "And the congregation shall deliver the slayer out of the hand of the revenger of blood, and the congregation shall restore him to the city of his refuge, whither he was fled: and he shall abide in it unto the death of the high priest, which was anointed with the holy oil."}, {"verse": 26, "start": 284.35, "end": 291.42, "ta": "ஆனாலும் கொலைசெய்தவன் தான் ஓடிப்போயிருக்கிற அடைக்கலப்பட்டணத்தின் எல்லையை விட்டு வெளிப்பட்டிருக்கும்போது,", "en": "But if the slayer shall at any time come without the border of the city of his refuge, whither he was fled;"}, {"verse": 27, "start": 291.42, "end": 300.07, "ta": "பழிவாங்குகிறவன் கொலை செய்தவனை அடைக்கலப்பட்டணத்துக்கு வெளியே கண்டுபிடித்துக் கொன்றுபோட்டால், அவன்மேல் இரத்தப்பழி இல்லை.", "en": "And the revenger of blood find him without the borders of the city of his refuge, and the revenger of blood kill the slayer; he shall not be guilty of blood:"}, {"verse": 28, "start": 300.07, "end": 312.2, "ta": "கொலைசெய்தவன் பிரதான ஆசாரியன் மரணமடையுமட்டும் அடைக்கலப் பட்டணத்திலிருக்கவேண்டும்; பிரதான ஆசாரியன் மரணமடைந்தபின்பு, தன் சுதந்தரமான காணியாட்சிக்குத் திரும்பிப்போகலாம்.", "en": "Because he should have remained in the city of his refuge until the death of the high priest: but after the death of the high priest the slayer shall return into the land of his possession."}, {"verse": 29, "start": 312.2, "end": 319.59, "ta": "இவைகள் உங்கள் வாசஸ்தலங்களிலெங்கும் உங்கள் தலைமுறைதோறும் உங்களுக்கு நியாயவிதிப் பிரமாணமாயிருக்கக்கடவது.", "en": "So these things shall be for a statute of judgment unto you throughout your generations in all your dwellings."}, {"verse": 30, "start": 319.59, "end": 334.24, "ta": "எவனாகிலும், ஒரு மனிதனைக் கொன்றுபோட்டால், அப்பொழுது சாட்சிகளுடைய வாக்குமூலத்தின்படியே அந்தக் கொலைபாதகனைக் கொலைசெய்யக்கடவர்கள்; ஒரே சாட்சியைக்கொண்டுமாத்திரம் ஒரு மனிதன் சாகும்படி தீர்ப்புச்செய்யலாகாது.", "en": "Whoso killeth any person, the murderer shall be put to death by the mouth of witnesses: but one witness shall not testify against any person to cause him to die."}, {"verse": 31, "start": 334.24, "end": 343.77, "ta": "சாகிறதற்கேற்ற குற்றஞ்சுமந்த கொலைபாதகனுடைய ஜீவனுக்காக நீங்கள் மீட்கும்பொருளை வாங்கக் கூடாது; அவன் தப்பாமல் கொலைசெய்யப்படவேண்டும்.", "en": "Moreover ye shall take no satisfaction for the life of a murderer, which is guilty of death: but he shall be surely put to death."}, {"verse": 32, "start": 343.77, "end": 354.49, "ta": "தன் அடைக்கலப்பட்டணத்துக்கு ஓடிப்போனவன் ஆசாரியன் மரணமடையாததற்கு முன்னே தன் நாட்டிற்குத் திரும்பிவரும்படி நீங்கள் அவனுக்காக மீட்கும்பொருளை வாங்கக் கூடாது.", "en": "And ye shall take no satisfaction for him that is fled to the city of his refuge, that he should come again to dwell in the land, until the death of the priest."}, {"verse": 33, "start": 354.49, "end": 370.35, "ta": "நீங்கள் இருக்கும் தேசத்தைப் பரிசுத்தக் குலைச்சலாக்காதிருங்கள்; இரத்தம் தேசத்தைத் தீட்டுப்படுத்தும்; இரத்தம் சிந்தினவனுடைய இரத்தத்தினாலேயொழிய, வேறொன்றினாலும் தேசத்திலே சிந்துண்ட இரத்தத்திற்காகப் பாவநிவிர்த்தியில்லை.", "en": "So ye shall not pollute the land wherein ye are: for blood it defileth the land: and the land cannot be cleansed of the blood that is shed therein, but by the blood of him that shed it."}, {"verse": 34, "start": 370.35, "end": 381.47, "ta": "நீங்கள் குடியிருக்கும் என் வாசஸ்தலமாகிய தேசத்தைத் தீட்டுப்படுத்தவேண்டாம்; கர்த்தராகிய நான் இஸ்ரவேல் புத்திரர் நடுவே வாசம்பண்ணுகிறேன் என்று சொல் என்றார்.", "en": "Defile not therefore the land which ye shall inhabit, wherein I dwell: for I the LORD dwell among the children of Israel."}]}, "36": {"chapter": 36, "duration": 203.52, "audio_url": "audio_ot/OT04_36.mp3", "total_verses": 13, "verses": [{"verse": 1, "start": 3.8, "end": 20.51, "ta": "யோசேப்பின் குமாரனுடைய வம்சத்தாரில் மனாசேயின் குமாரனாகிய மாகீருக்குப் பிறந்த கீலேயாத்தின் வம்ச பிதாக்களான தலைவர் சேர்ந்து, மோசேக்கும் இஸ்ரவேல் புத்திரருடைய பிதாக்களில் தலைவராகிய பிரபுக்களுக்கும் முன்பாகவந்து, அவர்களை நோக்கி:", "en": "And the chief fathers of the families of the children of Gilead, the son of Machir, the son of Manasseh, of the families of the sons of Joseph, came near, and spake before Moses, and before the princes, the chief fathers of the children of Israel:"}, {"verse": 2, "start": 20.51, "end": 42.33, "ta": "சீட்டுப்போட்டு, தேசத்தை இஸ்ரவேல் புத்திரருக்குச் சுதந்தரமாகக் கொடுக்கும்படி எங்கள் ஆண்டவனுக்குக் கர்த்தர் கட்டளையிட்டாரே; அன்றியும், எங்கள் சகோதரனாகிய செலொப்பியாத்தின் சுதந்தரத்தை அவன் குமாரத்திகளுக்குக் கொடுக்கவேண்டும் என்றும் எங்கள் ஆண்டவனுக்குக் கர்த்தராலே கட்டளையிடப்பட்டதே.", "en": "And they said, The LORD commanded my lord to give the land for an inheritance by lot to the children of Israel: and my lord was commanded by the LORD to give the inheritance of Zelophehad our brother unto his daughters."}, {"verse": 3, "start": 42.33, "end": 67.22, "ta": "இப்படியிருக்க, இவர்கள் இஸ்ரவேல் புத்திரருடைய வேறொரு கோத்திரத்தின் புத்திரருக்கு மனைவிகளானால், அந்தக் குமாரத்திகளுடைய சுதந்தரம் எங்கள் பிதாக்களுடைய சுதந்தரத்திலிருந்து நீங்கி, அவர்கள் உட்படுகிற கோத்திரத்தின் சுதந்தரத்தோடே சேர்ந்துபோகும்; இப்படி எங்கள் சுதந்தரத்துக்குச் சீட்டினால் விழுந்த பங்கில் இராமல் அற்றுப்போகுமே.", "en": "And if they be married to any of the sons of the other tribes of the children of Israel, then shall their inheritance be taken from the inheritance of our fathers, and shall be put to the inheritance of the tribe whereunto they are received: so shall it be taken from the lot of our inheritance."}, {"verse": 4, "start": 67.22, "end": 85.03, "ta": "இஸ்ரவேல் புத்திரருக்கு யூபிலி வருஷம் வந்தாலும், அவர்களுடைய சுதந்தரம் அவர்கள் உட்பட்டுப்போன கோத்திரத்தின் சுதந்தரத்தோடே சேர்ந்துபோகும்; இப்படி எங்கள் பிதாக்களுடைய கோத்திரத்தின் சுதந்தரத்திலிருந்து அது நீங்கிப்போகுமே என்றார்கள்.", "en": "And when the jubile of the children of Israel shall be, then shall their inheritance be put unto the inheritance of the tribe whereunto they are received: so shall their inheritance be taken away from the inheritance of the tribe of our fathers."}, {"verse": 5, "start": 85.03, "end": 94.66, "ta": "அப்பொழுது மோசே கர்த்தருடைய கட்டளையின்படியே இஸ்ரவேல் புத்திரரை நோக்கி: யோசேப்பு புத்திரரின் கோத்திரத்தார் சொல்லுகிறது சரியே.", "en": "And Moses commanded the children of Israel according to the word of the LORD , saying, The tribe of the sons of Joseph hath said well."}, {"verse": 6, "start": 94.66, "end": 111.74, "ta": "கர்த்தர் செலொப்பியாத்தின் குமாரத்திகளைக் குறித்த காரியத்தில் கட்டளையிடுகிறதாவது: அவர்கள் தங்களுக்கு இஷ்டமானவர்களை விவாகஞ்செய்யலாம்; ஆனாலும், தங்கள் பிதாவின் கோத்திரவம்சத்தாரில் மாத்திரம் அவர்கள் விவாகஞ்செய்யவேண்டும்.", "en": "This is the thing which the LORD doth command concerning the daughters of Zelophehad, saying, Let them marry to whom they think best; only to the family of the tribe of their father shall they marry."}, {"verse": 7, "start": 111.74, "end": 128.16, "ta": "இப்படியே இஸ்ரவேல் புத்திரரின் சுதந்தரம் ஒரு கோத்திரத்தைவிட்டு, வேறு கோத்திரத்துக்குப் போகாதிருக்கும்; இஸ்ரவேல் புத்திரர் அவரவர் தங்கள் தங்கள் பிதாக்களுடைய கோத்திரத்தின் சுதந்தரத்திலே நிலைகொண்டிருக்கவேண்டும்.", "en": "So shall not the inheritance of the children of Israel remove from tribe to tribe: for every one of the children of Israel shall keep himself to the inheritance of the tribe of his fathers."}, {"verse": 8, "start": 128.16, "end": 145.75, "ta": "இஸ்ரவேல் புத்திரர் அவரவர் தங்கள் தங்கள் பிதாக்களின் சுதந்தரத்தை அநுபவிக்கும்படி, இஸ்ரவேல் புத்திரருடைய ஒரு கோத்திரத்திலே சுதந்தரம் அடைந்திருக்கிற எந்தக் குமாரத்தியும் தன் பிதாவின் கோத்திர வம்சத்தாரில் ஒருவனுக்கு மனைவியாகவேண்டும்.", "en": "And every daughter, that possesseth an inheritance in any tribe of the children of Israel, shall be wife unto one of the family of the tribe of her father, that the children of Israel may enjoy every man the inheritance of his fathers."}, {"verse": 9, "start": 145.75, "end": 160.86, "ta": "சுதந்தரமானது ஒரு கோத்திரத்தைவிட்டு வேறொரு கோத்திரத்தைச் சேரக் கூடாது; இஸ்ரவேல் புத்திரருடைய ஒவ்வொரு கோத்திரமும் தன்தன் சுதந்தரத்திலே நிலைகொண்டிருக்கவேண்டுமென்று கட்டளையிட்டிருக்கிறார் என்றான்.", "en": "Neither shall the inheritance remove from one tribe to another tribe; but every one of the tribes of the children of Israel shall keep himself to his own inheritance."}, {"verse": 10, "start": 160.86, "end": 167.28, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே செலொப்பியாத்தின் குமாரத்திகள் செய்தார்கள்.", "en": "Even as the LORD commanded Moses, so did the daughters of Zelophehad:"}, {"verse": 11, "start": 167.28, "end": 184.21, "ta": "செலொப்பியாத்தின் குமாரத்திகளாகிய மக்லாள் திர்சாள் ஒக்லாள் மில்காள் நோவாள் என்பவர்கள் தங்கள் பிதாவின் சகோதரருடைய புத்திரரை விவாகம்பண்ணினார்கள்; அவர்கள் யோசேப்பின் குமாரனாகிய மனாசே புத்திரரின் வம்சத்தாரை விவாகம்பண்ணினபடியால்,", "en": "For Mahlah, Tirzah, and Hoglah, and Milcah, and Noah, the daughters of Zelophehad, were married unto their father’s brothers’ sons:"}, {"verse": 12, "start": 184.21, "end": 189.9, "ta": "அவர்களுடைய சுதந்தரம் அவர்கள் பிதாவின் வம்சமான கோத்திரத்தோடே இருந்தது.", "en": "And they were married into the families of the sons of Manasseh the son of Joseph, and their inheritance remained in the tribe of the family of their father."}, {"verse": 13, "start": 189.9, "end": 202.02, "ta": "எரிகோவின் அருகே யோர்தானுக்கு இப்புறத்திலுள்ள மோவாபின் சமனான வெளிகளில் கர்த்தர் மோசேயைக்கொண்டு இஸ்ரவேல் புத்திரருக்கு விதித்த கட்டளைகளும் நியாயங்களும் இவைகளே.", "en": "These are the commandments and the judgments, which the LORD commanded by the hand of Moses unto the children of Israel in the plains of Moab by Jordan near Jericho."}]}}});
} else {
  window.BIBLE_CACHE = window.BIBLE_CACHE || {};
  window.BIBLE_CACHE['4'] = {"id": 4, "testament": "OT", "code": "NUM", "name_en": "Numbers", "name_ta": "எண்ணாகமம்", "category": "Law", "category_ta": "மோசேயின் ஆகமங்கள்", "total_chapters": 36, "chapters": {"1": {"chapter": 1, "duration": 452.81, "audio_url": "audio_ot/OT04_01.mp3", "total_verses": 54, "verses": [{"verse": 1, "start": 4.8, "end": 16.55, "ta": "இஸ்ரவேலர் எகிப்துதேசத்திலிருந்து புறப்பட்ட இரண்டாம் வருஷம் இரண்டாம் மாதம் முதல் தேதியில், கர்த்தர் சீனாய் வனாந்தரத்திலிருக்கிற ஆசரிப்புக் கூடாரத்திலே மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the wilderness of Sinai, in the tabernacle of the congregation, on the first day of the second month, in the second year after they were come out of the land of Egypt, saying,"}, {"verse": 2, "start": 16.55, "end": 28.15, "ta": "நீங்கள் இஸ்ரவேல் புத்திரரின் முழுச்சபையாயிருக்கிற அவர்கள் பிதாக்களுடைய வீட்டு வம்சங்களிலுள்ள புருஷர்களாகிய சகல தலைகளையும் பேர்பேராக எண்ணித் தொகையேற்றுங்கள்.", "en": "Take ye the sum of all the congregation of the children of Israel, after their families, by the house of their fathers, with the number of their names, every male by their polls;"}, {"verse": 3, "start": 28.15, "end": 38.98, "ta": "இஸ்ரவேலிலே இருபது வயதுள்ளவர்கள் முதல் யுத்தத்துக்குப் புறப்படத்தக்கவர்கள் எல்லாரையும் அவர்கள் சேனைகளின்படி நீயும் ஆரோனும் எண்ணிப் பார்ப்பீர்களாக.", "en": "From twenty years old and upward, all that are able to go forth to war in Israel: thou and Aaron shall number them by their armies."}, {"verse": 4, "start": 38.98, "end": 48.34, "ta": "ஒவ்வொரு கோத்திரத்துக்கு ஒவ்வொரு மனிதன் உங்களோடே இருப்பானாக; அவன் தன் பிதாக்களின் வம்சத்துக்குத் தலைவனாயிருக்கவேண்டும்.", "en": "And with you there shall be a man of every tribe; every one head of the house of his fathers."}, {"verse": 5, "start": 48.34, "end": 55.44, "ta": "உங்களோடே நிற்கவேண்டிய மனிதருடைய நாமங்களாவன: ரூபன் கோத்திரத்தில் சேதேயூருடைய குமாரன் எலிசூர்.", "en": "And these are the names of the men that shall stand with you: of the tribe of Reuben; Elizur the son of Shedeur."}, {"verse": 6, "start": 55.44, "end": 59.95, "ta": "சிமியோன் கோத்திரத்தில் சூரிஷதாயின் குமாரன் செலுூமியேல்.", "en": "Of Simeon; Shelumiel the son of Zurishaddai."}, {"verse": 7, "start": 59.95, "end": 63.88, "ta": "யூதா கோத்திரத்தில் அம்மினதாபின் குமாரன் நகசோன்.", "en": "Of Judah; Nahshon the son of Amminadab."}, {"verse": 8, "start": 63.88, "end": 68.03, "ta": "இசக்கார் கோத்திரத்தில் சூவாரின் குமாரன் நெதனெயேல்.", "en": "Of Issachar; Nethaneel the son of Zuar."}, {"verse": 9, "start": 68.03, "end": 71.97, "ta": "செபுலோன் கோத்திரத்தில் ஏலோனின் குமாரன் எலியாப்.", "en": "Of Zebulun; Eliab the son of Helon."}, {"verse": 10, "start": 71.97, "end": 81.89, "ta": "யோசேப்பின் குமாரராகிய எப்பிராயீம் கோத்திரத்தில் அம்மியூதின் குமாரன் எலிஷாமா; மனாசே கோத்திரத்தில் பெதாசூரின் குமாரன் கமாலியேல்.", "en": "Of the children of Joseph: of Ephraim; Elishama the son of Ammihud: of Manasseh; Gamaliel the son of Pedahzur."}, {"verse": 11, "start": 81.89, "end": 86.11, "ta": "பென்யமீன் கோத்திரத்தில் கீதெயோனின் குமாரன் அபீதான்.", "en": "Of Benjamin; Abidan the son of Gideoni."}, {"verse": 12, "start": 86.11, "end": 90.26, "ta": "தாண் கோத்திரத்தில் அம்மிஷதாயின் குமாரன் அகியேசேர்.", "en": "Of Dan; Ahiezer the son of Ammishaddai."}, {"verse": 13, "start": 90.26, "end": 94.2, "ta": "ஆசேர் கோத்திரத்தில் ஓகிரானின் குமாரன் பாகியேல்.", "en": "Of Asher; Pagiel the son of Ocran."}, {"verse": 14, "start": 94.2, "end": 98.21, "ta": "காத் கோத்திரத்தில் தேகுவேலின் குமாரன் எலியாசாப்.", "en": "Of Gad; Eliasaph the son of Deuel."}, {"verse": 15, "start": 98.21, "end": 101.87, "ta": "நப்தலி கோத்திரத்தில் ஏனானின் குமாரன் அகீரா.", "en": "Of Naphtali; Ahira the son of Enan."}, {"verse": 16, "start": 101.87, "end": 111.86, "ta": "இவர்களே சபையில் ஏற்படுத்தப்பட்டவர்களும், தங்கள் தங்கள் பிரபுக்களும், இஸ்ரவேலில் ஆயிரவர்களுக்குத் தலைவருமாயிருப்பவர்கள் என்றார்.", "en": "These were the renowned of the congregation, princes of the tribes of their fathers, heads of thousands in Israel."}, {"verse": 17, "start": 111.86, "end": 117.76, "ta": "அப்படியே மோசேயும் ஆரோனும் பேர்பேராகக் குறிக்கப்பட்ட இந்த மனிதரைக் கூட்டிக்கொண்டு,", "en": "And Moses and Aaron took these men which are expressed by their names:"}, {"verse": 18, "start": 117.76, "end": 138.3, "ta": "இரண்டாம் மாதம் முதல் தேதியில் சபையார் எல்லாரையும் கூடிவரச்செய்தார்கள். அப்பொழுது அவர்கள் தங்கள் தங்கள் குடும்பத்தின்படிக்குή், பߠΤாக்கγுடைί வή்சத்தߠΩ்படοக்கும், நாமத்தொகையின்படிக்கும், இருபது வயதுள்ளவர்கள் முதல் தலைதலையாகத் தங்கள் வம்ச உற்பத்தியைத் தெரிவித்தார்கள்.", "en": "And they assembled all the congregation together on the first day of the second month, and they declared their pedigrees after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, by their polls."}, {"verse": 19, "start": 138.3, "end": 145.48, "ta": "இப்படிக் கர்த்தர் கட்டளையிட்டபடியே, மோசே அவர்களைச் சீனாய் வனாந்தரத்தில் எண்ணிப்பார்த்தான்.", "en": "As the LORD commanded Moses, so he numbered them in the wilderness of Sinai."}, {"verse": 20, "start": 145.48, "end": 158.28, "ta": "இஸ்ரவேலின் மூத்தகுமாரனாகிய ரூபன் புத்திரருடைய பிதாக்களின் வீட்டுவம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் தலைதலையாக எண்ணப்பட்டபோது,", "en": "And the children of Reuben, Israel’s eldest son, by their generations, after their families, by the house of their fathers, according to the number of the names, by their polls, every male from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 21, "start": 158.28, "end": 163.98, "ta": "ரூபன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பத்தாறாயிரத்து ஐந்நூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Reuben, were forty and six thousand and five hundred."}, {"verse": 22, "start": 163.98, "end": 175.23, "ta": "சிமியோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் தலைதலையாக எண்ணப்பட்டபோது,", "en": "Of the children of Simeon, by their generations, after their families, by the house of their fathers, those that were numbered of them, according to the number of the names, by their polls, every male from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 23, "start": 175.23, "end": 181.49, "ta": "சிமியோன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்தொன்பதினாயிரத்து முந்நூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Simeon, were fifty and nine thousand and three hundred."}, {"verse": 24, "start": 181.49, "end": 191.83, "ta": "காத் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Gad, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 25, "start": 191.83, "end": 198.09, "ta": "காத் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பத்தையாயிரத்து அறுநூற்று ஐம்பதுபேர்.", "en": "Those that were numbered of them, even of the tribe of Gad, were forty and five thousand six hundred and fifty."}, {"verse": 26, "start": 198.09, "end": 208.36, "ta": "யூதா புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Judah, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 27, "start": 208.36, "end": 214.13, "ta": "யூதா கோத்திரத்தில் எண்ணப்பட்டவர்கள், எழுபத்து நாலாயிரத்து அறுநூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Judah, were threescore and fourteen thousand and six hundred."}, {"verse": 28, "start": 214.13, "end": 224.68, "ta": "இசக்கார் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Issachar, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 29, "start": 224.68, "end": 230.66, "ta": "இசக்கார் கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்து நாலாயிரத்து நானூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Issachar, were fifty and four thousand and four hundred."}, {"verse": 30, "start": 230.66, "end": 241.21, "ta": "செபுலோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Zebulun, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 31, "start": 241.21, "end": 246.98, "ta": "செபுலோன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்தேழாயிரத்து நானூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Zebulun, were fifty and seven thousand and four hundred."}, {"verse": 32, "start": 246.98, "end": 259.22, "ta": "யோசேப்பின் குமாரரில் எப்பிராயீம் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Joseph, namely , of the children of Ephraim, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 33, "start": 259.22, "end": 265.19, "ta": "எப்பிராயீம் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பதினாயிரத்து ஐந்நூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Ephraim, were forty thousand and five hundred."}, {"verse": 34, "start": 265.19, "end": 275.53, "ta": "மனாசே புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Manasseh, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 35, "start": 275.53, "end": 281.23, "ta": "மனாசே கோத்திரத்தில் எண்ணப்பட்டவர்கள், முப்பத்தீராயிரத்து இருநூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Manasseh, were thirty and two thousand and two hundred."}, {"verse": 36, "start": 281.23, "end": 291.85, "ta": "பென்யமீன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Benjamin, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 37, "start": 291.85, "end": 297.76, "ta": "பென்யமீன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், முப்பத்தையாயிரத்து நானூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Benjamin, were thirty and five thousand and four hundred."}, {"verse": 38, "start": 297.76, "end": 308.03, "ta": "தாண் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Dan, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 39, "start": 308.03, "end": 313.59, "ta": "தாண் கோத்திரத்தில் எண்ணப்பட்டவர்கள், அறுபத்தீராயிரத்து எழுநூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Dan, were threescore and two thousand and seven hundred."}, {"verse": 40, "start": 313.59, "end": 323.93, "ta": "ஆசேர் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Asher, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 41, "start": 323.93, "end": 329.62, "ta": "ஆசேர் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பத்தோராயிரத்து ஐந்நூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Asher, were forty and one thousand and five hundred."}, {"verse": 42, "start": 329.62, "end": 340.03, "ta": "நப்தலி புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,", "en": "Of the children of Naphtali, throughout their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;"}, {"verse": 43, "start": 340.03, "end": 345.87, "ta": "நப்தலி கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்து மூவாயிரத்து நானூறுபேர்.", "en": "Those that were numbered of them, even of the tribe of Naphtali, were fifty and three thousand and four hundred."}, {"verse": 44, "start": 345.87, "end": 357.34, "ta": "எண்ணப்பட்டவர்கள் இவர்களே; மோசேயும் ஆரோனும் இஸ்ரவேலுடைய பிதாக்களின் வம்சத்தில் ஒவ்வொரு வம்சத்துக்கு ஒவ்வொரு பிரபுவாகிய பன்னிரண்டுபேரும் எண்ணினார்கள்.", "en": "These are those that were numbered, which Moses and Aaron numbered, and the princes of Israel, being twelve men: each one was for the house of his fathers."}, {"verse": 45, "start": 357.34, "end": 368.38, "ta": "இஸ்ரவேல் புத்திரருடைய பிதாக்களின் வம்சத்தில் இருபது வயதுள்ளவர்கள்முதல், இஸ்ரவேலில் யுத்தத்திற்குப் புறப்படத்தக்கவர்களாகிய எண்ணப்பட்ட பேர்கள் எல்லாரும்,", "en": "So were all those that were numbered of the children of Israel, by the house of their fathers, from twenty years old and upward, all that were able to go forth to war in Israel;"}, {"verse": 46, "start": 368.38, "end": 373.16, "ta": "ஆறுலட்சத்து மூவாயிரத்து ஐந்நூற்று ஐம்பது பேராயிருந்தார்கள்.", "en": "Even all they that were numbered were six hundred thousand and three thousand and five hundred and fifty."}, {"verse": 47, "start": 373.16, "end": 379.42, "ta": "லேவியர் தங்கள் பிதாக்களுடைய கோத்திரத்தின்படியே, மற்றவர்களுடனே எண்ணப்படவில்லை.", "en": "But the Levites after the tribe of their fathers were not numbered among them."}, {"verse": 48, "start": 379.42, "end": 381.04, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "For the LORD had spoken unto Moses, saying,"}, {"verse": 49, "start": 381.04, "end": 388.22, "ta": "நீ லேவி கோத்திரத்தாரைமாத்திரம் எண்ணாமலும், இஸ்ரவேல் புத்திரருக்குள்ளே அவர்கள் தொகையை ஏற்றாமலும்,", "en": "Only thou shalt not number the tribe of Levi, neither take the sum of them among the children of Israel:"}, {"verse": 50, "start": 388.22, "end": 409.6, "ta": "லேவியரைச் சாட்சியின் வாசஸ்தலத்திற்கும், அதினுடைய சகல பணிமுட்டுகளுக்கும், அதிலுள்ள சமஸ்த பொருள்களுக்கும் விசாரிப்புக்காரராக ஏற்படுத்து; அவர்கள் வாசஸ்தலத்தையும் அதின் சகல பணிமுட்டுகளையும் சுமப்பார்களாக; அதினிடத்தில் ஊழியம்செய்து, வாசஸ்தலத்தைச் சுற்றிலும் பாளயமிறங்கக்கடவர்கள்.", "en": "But thou shalt appoint the Levites over the tabernacle of testimony, and over all the vessels thereof, and over all things that belong to it: they shall bear the tabernacle, and all the vessels thereof; and they shall minister unto it, and shall encamp round about the tabernacle."}, {"verse": 51, "start": 409.6, "end": 423.88, "ta": "வாசஸ்தலம் புறப்படும்போது, லேவியர் அதை இறக்கிவைத்து, அது ஸ்தாபனம் பண்ணப்படும்போது, லேவியர் அதை எடுத்து நிறுத்தக்கடவர்கள்; அந்நியன் அதற்குச் சமீபத்தில் வந்தால் கொலைசெய்யப்படக்கடவன்.", "en": "And when the tabernacle setteth forward, the Levites shall take it down: and when the tabernacle is to be pitched, the Levites shall set it up: and the stranger that cometh nigh shall be put to death."}, {"verse": 52, "start": 423.88, "end": 431.97, "ta": "இஸ்ரவேல் புத்திரர் தங்கள் தங்கள் பாளயத்தோடும், தங்கள் தங்கள் சேனையின் கொடியோடும் கூடாரம் போடக்கடவர்கள்.", "en": "And the children of Israel shall pitch their tents, every man by his own camp, and every man by his own standard, throughout their hosts."}, {"verse": 53, "start": 431.97, "end": 444.98, "ta": "இஸ்ரவேல் புத்திரராகிய சபையின்மேல் கடுங்கோபம் வராதபடிக்கு லேவியர் சாட்சியின் வாசஸ்தலத்தைச் சுற்றிலும் பாளயமிறங்கி, லேவியர் சாட்சியின் வாசஸ்தலத்தைக் காவல்காப்பார்களாக என்றார்.", "en": "But the Levites shall pitch round about the tabernacle of testimony, that there be no wrath upon the congregation of the children of Israel: and the Levites shall keep the charge of the tabernacle of testimony."}, {"verse": 54, "start": 444.98, "end": 451.31, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடி எல்லாவற்றையும் இஸ்ரவேல் புத்திரர் செய்தார்கள்.", "en": "And the children of Israel did according to all that the LORD commanded Moses, so did they."}]}, "2": {"chapter": 2, "duration": 323.12, "audio_url": "audio_ot/OT04_02.mp3", "total_verses": 34, "verses": [{"verse": 1, "start": 3.8, "end": 6.49, "ta": "கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 2, "start": 6.49, "end": 21.61, "ta": "இஸ்ரவேல் புத்திரர் அவரவர் தங்கள் தங்கள் பிதாக்களுடைய வம்சத்தின் விருதாகிய தங்கள் தங்கள் கொடியண்டையிலே தங்கள் கூடாரங்களைப் போட்டு, ஆசரிப்புக் கூடாரத்திற்கு எதிராகச் சுற்றிலும் பாளயமிறங்கக்கடவர்கள்.", "en": "Every man of the children of Israel shall pitch by his own standard, with the ensign of their father’s house: far off about the tabernacle of the congregation shall they pitch."}, {"verse": 3, "start": 21.61, "end": 34.83, "ta": "யூதாவின் பாளயத்துக் கொடியையுடைய சேனைகள் சூரியன் உதிக்கும் கீழ்ப்புறத்திலே பாளயமிறங்கவேண்டும்; அம்மினதாபின் குமாரனாகிய நகசோன் யூதா சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And on the east side toward the rising of the sun shall they of the standard of the camp of Judah pitch throughout their armies: and Nahshon the son of Amminadab shall be captain of the children of Judah."}, {"verse": 4, "start": 34.83, "end": 39.63, "ta": "எண்ணப்பட்ட அவனுடைய சேனை எழுபத்து நாலாயிரத்து அறுநூறுபேர்.", "en": "And his host, and those that were numbered of them, were threescore and fourteen thousand and six hundred."}, {"verse": 5, "start": 39.63, "end": 49.95, "ta": "அவன் அருகே இசக்கார் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; சூவாரின் குமாரன் நெதனெயேல் இசக்கார் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And those that do pitch next unto him shall be the tribe of Issachar: and Nethaneel the son of Zuar shall be captain of the children of Issachar."}, {"verse": 6, "start": 49.95, "end": 54.67, "ta": "எண்ணப்பட்ட அவனுடைய சேனை ஐம்பத்து நாலாயிரத்து நானூறுபேர்.", "en": "And his host, and those that were numbered thereof, were fifty and four thousand and four hundred."}, {"verse": 7, "start": 54.67, "end": 64.99, "ta": "அவன் அருகே செபுலோன் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; ஏலோனின் குமாரனாகிய எலியாப் செபுலோன் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "Then the tribe of Zebulun: and Eliab the son of Helon shall be captain of the children of Zebulun."}, {"verse": 8, "start": 64.99, "end": 70.23, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் ஐம்பத்தேழாயிரத்து நானூறுபேர்.", "en": "And his host, and those that were numbered thereof, were fifty and seven thousand and four hundred."}, {"verse": 9, "start": 70.23, "end": 82.66, "ta": "எண்ணப்பட்ட யூதாவின் பாளயத்தார் எல்லாரும் தங்கள் சேனைகளின்படியே இலட்சத்து எண்பத்து ஆறாயிரத்து நானூறுபேர்; இவர்கள் பிரயாணத்திலே முதற்பாளயமாய்ப் போகக்கடவர்கள்.", "en": "All that were numbered in the camp of Judah were an hundred thousand and fourscore thousand and six thousand and four hundred, throughout their armies. These shall first set forth."}, {"verse": 10, "start": 82.66, "end": 94.72, "ta": "ரூபனுடைய பாளயத்துக் கொடியையுடைய சேனைகள் தென்புறத்தில் பாளயமிறங்கவேண்டும்; சேதேயூரின் குமாரனாகிய எலிசூர் ரூபன் சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "On the south side shall be the standard of the camp of Reuben according to their armies: and the captain of the children of Reuben shall be Elizur the son of Shedeur."}, {"verse": 11, "start": 94.72, "end": 100.1, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பத்தாறாயிரத்து ஐந்நூறுபேர்.", "en": "And his host, and those that were numbered thereof, were forty and six thousand and five hundred."}, {"verse": 12, "start": 100.1, "end": 111.29, "ta": "அவன் அருகே சிமியோன் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; சூரிஷதாயின் குமாரனாகிய செலுூமியேல் சிமியோன் சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And those which pitch by him shall be the tribe of Simeon: and the captain of the children of Simeon shall be Shelumiel the son of Zurishaddai."}, {"verse": 13, "start": 111.29, "end": 117.03, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் ஐம்பத்தொன்பதினாயிரத்து முந்நூறுபேர்.", "en": "And his host, and those that were numbered of them, were fifty and nine thousand and three hundred."}, {"verse": 14, "start": 117.03, "end": 127.42, "ta": "அவன் அருகே காத் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; தேகுவேலின் குமாரனாகிய எலியாசாப் காத் சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "Then the tribe of Gad: and the captain of the sons of Gad shall be Eliasaph the son of Reuel."}, {"verse": 15, "start": 127.42, "end": 133.46, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பத்தையாயிரத்து அறுநூற்று ஐம்பதுபேர்.", "en": "And his host, and those that were numbered of them, were forty and five thousand and six hundred and fifty."}, {"verse": 16, "start": 133.46, "end": 146.76, "ta": "எண்ணப்பட்ட ரூபனின் பாளயத்தார் எல்லாரும் தங்கள் சேனைகளின்படியே இலட்சத்து ஐம்பத்து ஓராயிரத்து நானூற்று ஐம்பதுபேர்; இவர்கள் பிரயாணத்தில் இரண்டாம் பாளயமாய்ப் போகக்கடவர்கள்.", "en": "All that were numbered in the camp of Reuben were an hundred thousand and fifty and one thousand and four hundred and fifty, throughout their armies. And they shall set forth in the second rank."}, {"verse": 17, "start": 146.76, "end": 162.6, "ta": "பின்பு ஆசரிப்புக் கூடாரம் லேவியரின் சேனையோடே பாளயங்களின் நடுவே பிரயாணப்பட்டுப் போகவேண்டும்; எப்படிப் பாளயமிறங்குகிறார்களோ, அப்படியே அவரவர் தங்கள் வரிசையிலே தங்கள் கொடிகளோடே பிரயாணமாய்ப் போகக்கடவர்கள்.", "en": "Then the tabernacle of the congregation shall set forward with the camp of the Levites in the midst of the camp: as they encamp, so shall they set forward, every man in his place by their standards."}, {"verse": 18, "start": 162.6, "end": 175.1, "ta": "எப்பிராயீமுடைய பாளயத்துக் கொடியையுடைய சேனைகள் மேல்புறத்தில் இறங்கவேண்டும்; அம்மியூதின் குமாரனாகிய எலிஷாமா எப்பிராயீமின் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "On the west side shall be the standard of the camp of Ephraim according to their armies: and the captain of the sons of Ephraim shall be Elishama the son of Ammihud."}, {"verse": 19, "start": 175.1, "end": 180.33, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பதினாயிரத்து ஐந்நூறுபேர்.", "en": "And his host, and those that were numbered of them, were forty thousand and five hundred."}, {"verse": 20, "start": 180.33, "end": 190.58, "ta": "அவன் அருகே மனாசே கோத்திரத்தார் பாளயமிறங்கவேண்டும்; பெதாசூரின் குமாரனாகிய கமாலியேல் மனாசே சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And by him shall be the tribe of Manasseh: and the captain of the children of Manasseh shall be Gamaliel the son of Pedahzur."}, {"verse": 21, "start": 190.58, "end": 195.96, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் முப்பத்தீராயிரத்து இருநூறுபேர்.", "en": "And his host, and those that were numbered of them, were thirty and two thousand and two hundred."}, {"verse": 22, "start": 195.96, "end": 206.64, "ta": "அவன் அருகே பென்யமீன் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; கீதெயோனின் குமாரனாகிய அபீதான் பென்யமீன் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "Then the tribe of Benjamin: and the captain of the sons of Benjamin shall be Abidan the son of Gideoni."}, {"verse": 23, "start": 206.64, "end": 211.95, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் முப்பத்தையாயிரத்து நானூறுபேர்.", "en": "And his host, and those that were numbered of them, were thirty and five thousand and four hundred."}, {"verse": 24, "start": 211.95, "end": 224.38, "ta": "எண்ணப்பட்ட எப்பிராயீமின் பாளயத்தார் எல்லாரும் தங்கள் சேனைகளின்படியே இலட்சத்து எண்ணாயிரத்து நூறுபேர்; இவர்கள் பிரயாணத்தில் மூன்றாம் பாளயமாய்ப் போகக்கடவர்கள்.", "en": "All that were numbered of the camp of Ephraim were an hundred thousand and eight thousand and an hundred, throughout their armies. And they shall go forward in the third rank."}, {"verse": 25, "start": 224.38, "end": 235.93, "ta": "தாணுடைய பாளயத்துக் கொடியையுடைய சேனைகள் வடபுறத்தில் இறங்கவேண்டும்; அம்மிஷதாயின் குமாரனாகிய அகியேசேர் தாண் வம்சத்திற்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "The standard of the camp of Dan shall be on the north side by their armies: and the captain of the children of Dan shall be Ahiezer the son of Ammishaddai."}, {"verse": 26, "start": 235.93, "end": 241.24, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் அறுபத்தீராயிரத்து எழுநூறுபேர்.", "en": "And his host, and those that were numbered of them, were threescore and two thousand and seven hundred."}, {"verse": 27, "start": 241.24, "end": 251.34, "ta": "அவன் அருகே ஆசேர் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; ஓகிரானின் குமாரனாகிய பாகியேல் ஆசேர் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "And those that encamp by him shall be the tribe of Asher: and the captain of the children of Asher shall be Pagiel the son of Ocran."}, {"verse": 28, "start": 251.34, "end": 256.72, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பத்தோராயிரத்து ஐந்நூறுபேர்.", "en": "And his host, and those that were numbered of them, were forty and one thousand and five hundred."}, {"verse": 29, "start": 256.72, "end": 266.89, "ta": "அவன் அருகே நப்தலி கோத்திரத்தார் பாளயமிறங்கவேண்டும்; ஏனானின் குமாரனாகிய அகீரா நப்தலி சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.", "en": "Then the tribe of Naphtali: and the captain of the children of Naphtali shall be Ahira the son of Enan."}, {"verse": 30, "start": 266.89, "end": 272.34, "ta": "அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் ஐம்பத்து மூவாயிரத்து நானூறுபேர்.", "en": "And his host, and those that were numbered of them, were fifty and three thousand and four hundred."}, {"verse": 31, "start": 272.34, "end": 283.17, "ta": "எண்ணப்பட்ட தாணின் பாளயத்தார் எல்லாரும் இலட்சத்து ஐம்பத்தேழாயிரத்து அறுநூறுபேர்; இவர்கள் தங்கள் கொடிகளோடே பின்பாளயமாய்ப் போகக்கடவர்கள்.", "en": "All they that were numbered in the camp of Dan were an hundred thousand and fifty and seven thousand and six hundred. They shall go hindmost with their standards."}, {"verse": 32, "start": 283.17, "end": 300.03, "ta": "இவர்களே தங்கள் தங்கள் பிதாக்களின் வம்சத்தின்படி இஸ்ரவேல் புத்திரரில் எண்ணப்பட்டவர்கள். பாளயங்களிலே தங்கள் தங்கள் சேனைகளின்படியே எண்ணப்பட்டவர்கள் எல்லாரும் ஆறுலட்சத்து மூவாயிரத்து ஐந்நூற்று ஐம்பது பேராயிருந்தார்கள்.", "en": "These are those which were numbered of the children of Israel by the house of their fathers: all those that were numbered of the camps throughout their hosts were six hundred thousand and three thousand and five hundred and fifty."}, {"verse": 33, "start": 300.03, "end": 307.45, "ta": "லேவியரோ, கர்த்தர் மோசேக்குக் கட்டளையிட்டபடி, இஸ்ரவேல் புத்திரருக்குள்ளே எண்ணப்படவில்லை.", "en": "But the Levites were not numbered among the children of Israel; as the LORD commanded Moses."}, {"verse": 34, "start": 307.45, "end": 321.62, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியெல்லாம் இஸ்ரவேல் புத்திரர் செய்து, தங்கள் தங்கள் கொடிகளின்கீழ் பாளயமிறங்கி, தங்கள் தங்கள் பிதாக்களுடைய வம்சங்களின்படியே பிரயாணப்பட்டுப்போனார்கள்.", "en": "And the children of Israel did according to all that the LORD commanded Moses: so they pitched by their standards, and so they set forward, every one after their families, according to the house of their fathers."}]}, "3": {"chapter": 3, "duration": 552.41, "audio_url": "audio_ot/OT04_03.mp3", "total_verses": 51, "verses": [{"verse": 1, "start": 3.8, "end": 10.57, "ta": "சீனாய் மலையில் கர்த்தர் மோசேயோடே பேசின நாளிலே, ஆரோன் மோசே என்பவர்களுடைய வம்சவரலாறாவது:", "en": "These also are the generations of Aaron and Moses in the day that the LORD spake with Moses in mount Sinai."}, {"verse": 2, "start": 10.57, "end": 18.55, "ta": "ஆரோனுடைய குமாரர், முதல் பிறந்தவனாகிய நாதாப், அபியூ, எலெயாசார், இத்தாமார் என்பவர்களே.", "en": "And these are the names of the sons of Aaron; Nadab the firstborn, and Abihu, Eleazar, and Ithamar."}, {"verse": 3, "start": 18.55, "end": 27.98, "ta": "ஆசாரிய ஊழியம்செய்கிறதற்கு அவனால் பிரதிஷ்டை செய்யப்பட்டு அபிஷேகம்பெற்ற ஆசாரியரான ஆரோனுடைய குமாரரின் நாமங்கள் இவைகளே.", "en": "These are the names of the sons of Aaron, the priests which were anointed, whom he consecrated to minister in the priest’s office."}, {"verse": 4, "start": 27.98, "end": 49.57, "ta": "நாதாபும் அபியூவும் சீனாய் வனாந்தரத்தில் அந்நிய அக்கினியைக் கர்த்தருடைய சந்நிதியில் கொண்டுவந்தபோது, கர்த்தருடைய சந்நிதியில் மரித்துப்போனார்கள்; அவர்களுக்குப் பிள்ளைகள் இல்லை; எலெயாசாரும் இத்தாமாருமே தங்கள் தகப்பனாகிய ஆரோனுக்கு முன்பாக ஆசாரிய ஊழியம் செய்தார்கள்.", "en": "And Nadab and Abihu died before the LORD , when they offered strange fire before the LORD , in the wilderness of Sinai, and they had no children: and Eleazar and Ithamar ministered in the priest’s office in the sight of Aaron their father."}, {"verse": 5, "start": 49.57, "end": 51.32, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 6, "start": 51.32, "end": 59.91, "ta": "நீ லேவிகோத்திரத்தாரைச் சேர்த்து, அவர்கள் ஆசாரியனாகிய ஆரோனுக்குப் பணிவிடைசெய்யும்படி அவர்களை நிறுத்து.", "en": "Bring the tribe of Levi near, and present them before Aaron the priest, that they may minister unto him."}, {"verse": 7, "start": 59.91, "end": 71.54, "ta": "அவர்கள் ஆசரிப்புக் கூடாரத்துக்கு முன்பாக அவனுடைய காவலையும் எல்லாச் சபையின் காவலையும் காத்து, வாசஸ்தலத்தின் பணிவிடை வேலைகளைச் செய்யக்கடவர்கள்.", "en": "And they shall keep his charge, and the charge of the whole congregation before the tabernacle of the congregation, to do the service of the tabernacle."}, {"verse": 8, "start": 71.54, "end": 83.48, "ta": "அவர்கள் ஆசரிப்புக் கூடாரத்தின் தட்டுமுட்டு முதலானவைகளையும், இஸ்ரவேல் புத்திரரின் காவலையும் காத்து, வாசஸ்தலத்தின் பணிவிடைகளைச் செய்யக்கடவர்கள்.", "en": "And they shall keep all the instruments of the tabernacle of the congregation, and the charge of the children of Israel, to do the service of the tabernacle."}, {"verse": 9, "start": 83.48, "end": 96.56, "ta": "ஆகையால் லேவியரை ஆரோனிடத்திலும் அவன் குமாரரிடத்திலும் ஒப்புக்கொடுப்பாயாக; இஸ்ரவேல் புத்திரரில் இவர்கள் முற்றிலும் அவனுக்கு ஒப்புக்கொடுக்கப்பட்டிருக்கிறார்கள்.", "en": "And thou shalt give the Levites unto Aaron and to his sons: they are wholly given unto him out of the children of Israel."}, {"verse": 10, "start": 96.56, "end": 109.63, "ta": "ஆரோனையும் அவன் குமாரரையுமோ, தங்கள் ஆசாரிய ஊழியத்தைச் செய்வதற்காக நியமிக்கக்கடவாய், அந்த ஊழியத்தைச் செய்யும்படி சேருகிற அந்நியன் கொலைசெய்யப்படக்கடவன் என்றார்.", "en": "And thou shalt appoint Aaron and his sons, and they shall wait on their priest’s office: and the stranger that cometh nigh shall be put to death."}, {"verse": 11, "start": 109.63, "end": 112.07, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 12, "start": 112.07, "end": 126.59, "ta": "இஸ்ரவேல் புத்திரரில் கர்ப்பந்திறந்து பிறக்கிற முதற்பேறான யாவுக்கும் பதிலாக, நான் லேவியரை இஸ்ரவேல் புத்திரரிலிருந்து எடுத்துக்கொண்டேன்; அவர்கள் என்னுடையவர்களாயிருக்கிறார்கள்.", "en": "And I, behold, I have taken the Levites from among the children of Israel instead of all the firstborn that openeth the matrix among the children of Israel: therefore the Levites shall be mine;"}, {"verse": 13, "start": 126.59, "end": 147.5, "ta": "முதற்பேறானவையெல்லாம் என்னுடையவை; நான் எகிப்துதேசத்தில் முதற்பேறான யாவையும் சங்கரித்த நாளில், இஸ்ரவேலில் மனிதர்முதல் மிருகஜீவன்மட்டுமுள்ள முதற்பேறான யாவையும் எனக்கென்று பரிசுத்தப்படுத்தினதினாலே, அவைகள் என்னுடையவைகளாயிருக்கும்; நான் கர்த்தர் என்றார்.", "en": "Because all the firstborn are mine; for on the day that I smote all the firstborn in the land of Egypt I hallowed unto me all the firstborn in Israel, both man and beast: mine shall they be: I am the LORD ."}, {"verse": 14, "start": 147.5, "end": 151.53, "ta": "பின்னும் கர்த்தர் சீனாய் வனாந்தரத்தில் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the wilderness of Sinai, saying,"}, {"verse": 15, "start": 151.53, "end": 164.3, "ta": "லேவிபுத்திரரை அவர்கள் பிதாக்களின் வம்சங்களின்படியே எண்ணுவாயாக; அவர்களில் ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளையெல்லாம் எண்ணுவாயாக என்றார்.", "en": "Number the children of Levi after the house of their fathers, by their families: every male from a month old and upward shalt thou number them."}, {"verse": 16, "start": 164.3, "end": 172.13, "ta": "அப்பொழுது கர்த்தருடைய வாக்கின்படி, மோசே தனக்குக் கற்பிக்கப்பட்ட பிரகாரம் அவர்களை எண்ணினான்.", "en": "And Moses numbered them according to the word of the LORD , as he was commanded."}, {"verse": 17, "start": 172.13, "end": 179.35, "ta": "லேவியின் குமாரர் தங்கள் நாமங்களின்படியே, கெர்சோன், கோகாத், மெராரி என்பவர்கள்.", "en": "And these were the sons of Levi by their names; Gershon, and Kohath, and Merari."}, {"verse": 18, "start": 179.35, "end": 186.58, "ta": "தங்கள் வம்சத்தின்படியே கெர்சோனுடைய குமாரரின் நாமங்கள், லிப்னி, சீமேயி என்பவைகள்.", "en": "And these are the names of the sons of Gershon by their families; Libni, and Shimei."}, {"verse": 19, "start": 186.58, "end": 195.24, "ta": "தங்கள் வம்சங்களின்படியே கோகாத்துடைய குமாரர், அம்ராம், இத்சேயார், எப்ரோன், ஊசியேல் என்பவர்கள்.", "en": "And the sons of Kohath by their families; Amram, and Izehar, Hebron, and Uzziel."}, {"verse": 20, "start": 195.24, "end": 205.43, "ta": "தங்கள் வம்சங்களின்படியே மெராரியினுடைய குமாரர், மகேலி, மூசி என்பவர்கள்; இவர்களே லேவியருடைய பிதாக்களின் வம்சத்தார்.", "en": "And the sons of Merari by their families; Mahli, and Mushi. These are the families of the Levites according to the house of their fathers."}, {"verse": 21, "start": 205.43, "end": 214.1, "ta": "கெர்சோனின் வழியாய் லிப்னீயரின் வம்சமும் சீமேயியர் வம்சமும் தோன்றின; இவைகளே கெர்சோனியரின் வம்சங்கள்.", "en": "Of Gershon was the family of the Libnites, and the family of the Shimites: these are the families of the Gershonites."}, {"verse": 22, "start": 214.1, "end": 225.5, "ta": "அவர்களில் ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளெல்லாம் எண்ணப்பட்டபோது, எண்ணப்பட்டவர்கள் ஏழாயிரத்து ஐந்நூறுபேராயிருந்தார்கள்.", "en": "Those that were numbered of them, according to the number of all the males, from a month old and upward, even those that were numbered of them were seven thousand and five hundred."}, {"verse": 23, "start": 225.5, "end": 232.12, "ta": "கெர்சோனியரின் வம்சங்கள் வாசஸ்தலத்தின் பின்புறத்தில் மேற்கே பாளயமிறங்கவேண்டும்.", "en": "The families of the Gershonites shall pitch behind the tabernacle westward."}, {"verse": 24, "start": 232.12, "end": 239.11, "ta": "கெர்சோனியருடைய தகப்பன் வம்சத்துக்குத் தலைவன் லாயேலின் குமாரனாகிய எலியாசாப் என்பவன்.", "en": "And the chief of the house of the father of the Gershonites shall be Eliasaph the son of Lael."}, {"verse": 25, "start": 239.11, "end": 249.45, "ta": "ஆசரிப்புக் கூடாரத்திலே கெர்சோன் புத்திரரின் காவலாவது: வாசஸ்தலமும், கூடாரமும், அதின் மூடியும், ஆசரிப்புக் கூடாரவாசல் மறைவும்,", "en": "And the charge of the sons of Gershon in the tabernacle of the congregation shall be the tabernacle, and the tent, the covering thereof, and the hanging for the door of the tabernacle of the congregation,"}, {"verse": 26, "start": 249.45, "end": 263.59, "ta": "வாசஸ்தலத்தண்டையிலும் பலிபீடத்தண்டையிலும் சுற்றிலும் இருக்கிற பிராகாரத்தின் தொங்குதிரைகளும், பிராகாரவாசல் மூடுதிரையும், அவைகளின் வேலைகளுக்கெல்லாம் உரிய அவைகளின் கயிறுகளுமே.", "en": "And the hangings of the court, and the curtain for the door of the court, which is by the tabernacle, and by the altar round about, and the cords of it for all the service thereof."}, {"verse": 27, "start": 263.59, "end": 275.68, "ta": "கோகாத்தின் வழியாய் அம்ராமியரின் வம்சமும் இத்சேயாரின் வம்சமும் எப்ரோனியரின் வம்சமும் ஊசியேலரின் வம்சமும் தோன்றின; இவைகளே கோகாத்தியரின் வம்சங்கள்.", "en": "And of Kohath was the family of the Amramites, and the family of the Izeharites, and the family of the Hebronites, and the family of the Uzzielites: these are the families of the Kohathites."}, {"verse": 28, "start": 275.68, "end": 288.76, "ta": "ஒரு மாதம்முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளெல்லாம் எண்ணப்பட்டபோது, பரிசுத்த ஸ்தலத்துக்குரியவைகளைக் காப்பவர்கள், எண்ணாயிரத்து அறுநூறுபேராயிருந்தார்கள்.", "en": "In the number of all the males, from a month old and upward, were eight thousand and six hundred, keeping the charge of the sanctuary."}, {"verse": 29, "start": 288.76, "end": 295.83, "ta": "கோகாத் புத்திரரின் வம்சங்கள் வாசஸ்தலத்தின் தென்புறமான பக்கத்திலே பாளயமிறங்கவேண்டும்.", "en": "The families of the sons of Kohath shall pitch on the side of the tabernacle southward."}, {"verse": 30, "start": 295.83, "end": 300.47, "ta": "அவர்களின் தலைவன், ஊசியேலின் குமாரனாகிய எல்சாபான்.", "en": "And the chief of the house of the father of the families of the Kohathites shall be Elizaphan the son of Uzziel."}, {"verse": 31, "start": 300.47, "end": 316.05, "ta": "அவர்களுடைய காவலாவது: பெட்டியும், மேஜையும், குத்துவிளக்கும், பீடங்களும், ஆராதனைக்கேற்ற பரிசுத்தஸ்தலத்தின் பணிமுட்டுகளும், தொங்குதிரையும், அதினுடைய எல்லா வேலைகளுக்கும் ஏற்றவைகளுமே.", "en": "And their charge shall be the ark, and the table, and the candlestick, and the altars, and the vessels of the sanctuary wherewith they minister, and the hanging, and all the service thereof."}, {"verse": 32, "start": 316.05, "end": 328.9, "ta": "ஆசாரியனாகிய ஆரோனின் குமாரன் எலெயாசார் என்பவன் லேவியருடைய தலைவர்களுக்குத் தலைவனாய்ப் பரிசுத்த ஸ்தலத்தைக் காவல்காக்கிறவர்களுக்கு விசாரிப்புக்காரனாயிருக்கவேண்டும்.", "en": "And Eleazar the son of Aaron the priest shall be chief over the chief of the Levites, and have the oversight of them that keep the charge of the sanctuary."}, {"verse": 33, "start": 328.9, "end": 337.27, "ta": "மெராரியின் வழியாய் மகேலியரின் வம்சமும் மூசியரின் வம்சமும் தோன்றின; இவைகளே மெராரியின் வம்சங்கள்.", "en": "Of Merari was the family of the Mahlites, and the family of the Mushites: these are the families of Merari."}, {"verse": 34, "start": 337.27, "end": 348.59, "ta": "அவர்களில் ஒரு மாதம்முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளெல்லாம் எண்ணப்பட்டபோது, எண்ணப்பட்டவர்கள் ஆறாயிரத்து இருநூறுபேராயிருந்தார்கள்.", "en": "And those that were numbered of them, according to the number of all the males, from a month old and upward, were six thousand and two hundred."}, {"verse": 35, "start": 348.59, "end": 359.85, "ta": "அபியாயேலின் குமாரனாகிய சூரியேல் என்பவன் அவர்களுக்குத் தலைவனாயிருந்தான்; இவர்கள் வாசஸ்தலத்தின் வடபுறமான பக்கத்தில் பாளயமிறங்கவேண்டும்.", "en": "And the chief of the house of the father of the families of Merari was Zuriel the son of Abihail: these shall pitch on the side of the tabernacle northward."}, {"verse": 36, "start": 359.85, "end": 372.77, "ta": "அவர்களுடைய காவல் விசாரிப்பாவது: வாசஸ்தலத்தின் பலகைகளும், தாழ்ப்பாள்களும், தூண்களும், பாதங்களும் அதினுடைய எல்லாப் பணிமுட்டுகளும், அதற்கடுத்தவைகள் அனைத்தும்,", "en": "And under the custody and charge of the sons of Merari shall be the boards of the tabernacle, and the bars thereof, and the pillars thereof, and the sockets thereof, and all the vessels thereof, and all that serveth thereto,"}, {"verse": 37, "start": 372.77, "end": 379.92, "ta": "சுற்றுப்பிராகாரத்தின் தூண்களும், அவைகளின் பாதங்களும், முளைகளும், கயிறுகளுமே.", "en": "And the pillars of the court round about, and their sockets, and their pins, and their cords."}, {"verse": 38, "start": 379.92, "end": 402.73, "ta": "ஆசரிப்புக் கூடாரமாகிய வாசஸ்தலத்துக்கு முன்பாக, சூரியன் உதிக்கும் கீழ்ப்புறத்திலே மோசேயும் ஆரோனும் அவன் குமாரரும் கூடாரங்களைப் போட்டு இறங்கி, இஸ்ரவேல் புத்திரரின் காவலுக்குப் பதிலாகப் பரிசுத்த ஸ்தலத்தைக் காவல் காக்கவேண்டும். வாசஸ்தலத்தில் சேருகிற அந்நியன் கொலைசெய்யப்படக்கடவன்.", "en": "But those that encamp before the tabernacle toward the east, even before the tabernacle of the congregation eastward, shall be Moses, and Aaron and his sons, keeping the charge of the sanctuary for the charge of the children of Israel; and the stranger that cometh nigh shall be put to death."}, {"verse": 39, "start": 402.73, "end": 419.15, "ta": "மோசேயும் ஆரோனும், கர்த்தருடைய வாக்கின்படி, லேவியரில் ஒரு மாதம்முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளையெல்லாம் அவர்களுடைய வம்சங்களின்படி எண்ணினார்கள்; அவர்கள் இருபத்தீராயிரம் பேராயிருந்தார்கள்.", "en": "All that were numbered of the Levites, which Moses and Aaron numbered at the commandment of the LORD , throughout their families, all the males from a month old and upward, were twenty and two thousand."}, {"verse": 40, "start": 419.15, "end": 432.3, "ta": "அதன்பின்பு கர்த்தர் மோசேயை நோக்கி: நீ இஸ்ரவேல் புத்திரரில் ஒருமாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள முதற்பேறான ஆண்பிள்ளைகளையெல்லாம் எண்ணி, அவர்கள் நாமங்களைத் தொகையேற்றி,", "en": "And the LORD said unto Moses, Number all the firstborn of the males of the children of Israel from a month old and upward, and take the number of their names."}, {"verse": 41, "start": 432.3, "end": 449.49, "ta": "இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறான யாவுக்கும் பதிலாக லேவியரையும், இஸ்ரவேல் புத்திரரின் மிருகஜீவன்களிலுள்ள தலையீற்றான யாவுக்கும் பதிலாக லேவியரின் மிருகஜீவன்களையும் எனக்கென்று பிரித்தெடு; நான் கர்த்தர் என்றார்.", "en": "And thou shalt take the Levites for me (I am the LORD ) instead of all the firstborn among the children of Israel; and the cattle of the Levites instead of all the firstlings among the cattle of the children of Israel."}, {"verse": 42, "start": 449.49, "end": 458.76, "ta": "அப்பொழுது மோசே, கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறான யாவரையும் எண்ணினான்.", "en": "And Moses numbered, as the LORD commanded him, all the firstborn among the children of Israel."}, {"verse": 43, "start": 458.76, "end": 471.69, "ta": "ஒரு மாதம்முதல் அதற்கு மேற்பட்ட வயதுள்ள முதற்பேறான ஆண்பிள்ளைகளெல்லாரும் பேர்பேராக எண்ணப்பட்டபோது, இருபத்தீராயிரத்து இருநூற்று எழுபத்துமூன்று பேராயிருந்தார்கள்.", "en": "And all the firstborn males by the number of names, from a month old and upward, of those that were numbered of them, were twenty and two thousand two hundred and threescore and thirteen."}, {"verse": 44, "start": 471.69, "end": 474.2, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 45, "start": 474.2, "end": 491.07, "ta": "நீ இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறான யாவருக்கும் பதிலாக லேவியரையும், அவர்களுடைய மிருகஜீவன்களுக்குப்பதிலாக லேவியரின் மிருகஜீவன்களையும் பிரித்தெடு; லேவியர் என்னுடையவர்களாயிருப்பார்கள்; நான் கர்த்தர்.", "en": "Take the Levites instead of all the firstborn among the children of Israel, and the cattle of the Levites instead of their cattle; and the Levites shall be mine: I am the LORD ."}, {"verse": 46, "start": 491.07, "end": 501.19, "ta": "இஸ்ரவேல் புத்திரருடைய முதற்பேறுகளில் லேவியரின் தொகைக்கு அதிகமாயிருந்து, மீட்கப்படவேண்டிய இருநூற்று எழுபத்துமூன்றுபேரிடத்திலும்,", "en": "And for those that are to be redeemed of the two hundred and threescore and thirteen of the firstborn of the children of Israel, which are more than the Levites;"}, {"verse": 47, "start": 501.19, "end": 510.39, "ta": "நீ தலைக்கு ஐந்து சேக்கல் வீதமாகப் பரிசுத்த சேக்கல் கணக்கின்படி வாங்குவாயாக; அந்தச் சேக்கலானது இருபது கேரா.", "en": "Thou shalt even take five shekels apiece by the poll, after the shekel of the sanctuary shalt thou take them: (the shekel is twenty gerahs:)"}, {"verse": 48, "start": 510.39, "end": 519.36, "ta": "லேவியருடைய தொகைக்கு அதிகமானவர்கள் மீட்கப்படும் திரவியத்தை ஆரோனுக்கும் அவன் குமாரருக்கும் கொடுப்பாயாக என்றார்.", "en": "And thou shalt give the money, wherewith the odd number of them is to be redeemed, unto Aaron and to his sons."}, {"verse": 49, "start": 519.36, "end": 531.6, "ta": "அப்படியே லேவியரால் மீட்கப்பட்டவர்களின் தொகைக்கு அதிகமாயிருந்து, இன்னும் மீட்கப்படவேண்டியவர்களுக்கு ஈடாக மோசே இஸ்ரவேல் புத்திரருடைய முதற்பேறானவர்களிடத்தில்,", "en": "And Moses took the redemption money of them that were over and above them that were redeemed by the Levites:"}, {"verse": 50, "start": 531.6, "end": 539.89, "ta": "ஆயிரத்து முந்நூற்று அறுபத்தைந்து சேக்கலாகிய திரவியத்தை, பரிசுத்த ஸ்தலத்துச் சேக்கல் கணக்கின்படி வாங்கி,", "en": "Of the firstborn of the children of Israel took he the money; a thousand three hundred and threescore and five shekels , after the shekel of the sanctuary:"}, {"verse": 51, "start": 539.89, "end": 550.91, "ta": "கர்த்தருடைய வாக்கின்படியே மீட்கப்பட்டவர்களின் கிரயத்தை ஆரோனுக்கும் அவன் குமாரருக்கும், கர்த்தர் தனக்குக் கட்டளையிட்டபடியே கொடுத்தான்.", "en": "And Moses gave the money of them that were redeemed unto Aaron and to his sons, according to the word of the LORD , as the LORD commanded Moses."}]}, "4": {"chapter": 4, "duration": 540.76, "audio_url": "audio_ot/OT04_04.mp3", "total_verses": 49, "verses": [{"verse": 1, "start": 3.8, "end": 6.63, "ta": "கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 2, "start": 6.63, "end": 13.52, "ta": "லேவியின் புத்திரருக்குள்ளே இருக்கிற கோகாத் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களில்,", "en": "Take the sum of the sons of Kohath from among the sons of Levi, after their families, by the house of their fathers,"}, {"verse": 3, "start": 13.52, "end": 24.54, "ta": "ஆசரிப்புக் கூடாரத்திலே வேலைசெய்யும் சேனைக்கு உட்படத்தக்க முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணி, தொகையிடுவாயாக.", "en": "From thirty years old and upward even until fifty years old, all that enter into the host, to do the work in the tabernacle of the congregation."}, {"verse": 4, "start": 24.54, "end": 31.36, "ta": "ஆசரிப்புக் கூடாரத்திலே கோகாத் புத்திரரின் பணிவிடை மகா பரிசுத்தமானவைகளுக்குரியது.", "en": "This shall be the service of the sons of Kohath in the tabernacle of the congregation, about the most holy things:"}, {"verse": 5, "start": 31.36, "end": 41.08, "ta": "பாளயம் புறப்படும்போது, ஆரோனும் அவன் குமாரரும் வந்து, மறைவின் திரைச்சீலையை இறக்கி, அதினாலே சாட்சியின் பெட்டியை மூடி,", "en": "And when the camp setteth forward, Aaron shall come, and his sons, and they shall take down the covering vail, and cover the ark of testimony with it:"}, {"verse": 6, "start": 41.08, "end": 50.42, "ta": "அதின்மேல் தகசுத்தோல் மூடியைப்போட்டு, அதின்மேல் முற்றிலும் நீலமான துப்பட்டியை விரித்து, அதின் தண்டுகளைப் பாய்ச்சி,", "en": "And shall put thereon the covering of badgers’ skins, and shall spread over it a cloth wholly of blue, and shall put in the staves thereof."}, {"verse": 7, "start": 50.42, "end": 65.96, "ta": "சமுகத்தப்ப மேஜையின்மேல் நீலத் துப்பட்டியை விரித்து, தட்டுகளையும் தூபக்கரண்டிகளையும் கிண்ணங்களையும் மூடுகிற தட்டுகளையும் அதின்மேல் வைப்பார்களாக; நித்திய அப்பமும் அதின்மேல் இருக்கக்கடவது.", "en": "And upon the table of shewbread they shall spread a cloth of blue, and put thereon the dishes, and the spoons, and the bowls, and covers to cover withal: and the continual bread shall be thereon:"}, {"verse": 8, "start": 65.96, "end": 75.14, "ta": "அவைகளின்மேல் அவர்கள் சிவப்புத் துப்பட்டியை விரித்து, அதைத் தகசுத்தோல் மூடியால் மூடி, அதின் தண்டுகளைப் பாய்ச்சி,", "en": "And they shall spread upon them a cloth of scarlet, and cover the same with a covering of badgers’ skins, and shall put in the staves thereof."}, {"verse": 9, "start": 75.14, "end": 89.0, "ta": "இளநீலத் துப்பட்டியை எடுத்து, குத்துவிளக்குத்தண்டையும், அதின் அகல்களையும், அதின் கத்தரிகளையும், சாம்பல் பாத்திரங்களையும், அதற்குரிய எண்ணெய்ப் பாத்திரங்களையும் மூடி,", "en": "And they shall take a cloth of blue, and cover the candlestick of the light, and his lamps, and his tongs, and his snuffdishes, and all the oil vessels thereof, wherewith they minister unto it:"}, {"verse": 10, "start": 89.0, "end": 96.88, "ta": "அதையும் அதற்கடுத்த தட்டுமுட்டுகள் யாவையும் தகசுத்தோல் மூடிக்குள்ளே போட்டு, அதை ஒரு தண்டிலே கட்டி,", "en": "And they shall put it and all the vessels thereof within a covering of badgers’ skins, and shall put it upon a bar."}, {"verse": 11, "start": 96.88, "end": 105.69, "ta": "பொற்பீடத்தின்மேல் இளநீலத் துப்பட்டியை விரித்து, அதைத் தகசுத்தோல் மூடியால் மூடி, அதின் தண்டுகளைப் பாய்ச்சி,", "en": "And upon the golden altar they shall spread a cloth of blue, and cover it with a covering of badgers’ skins, and shall put to the staves thereof:"}, {"verse": 12, "start": 105.69, "end": 118.16, "ta": "பரிசுத்த ஸ்தலத்தில் வழங்கும் ஆராதனைக்கேற்ற சகல தட்டுமுட்டுகளையும் எடுத்து, இளநீலத் துப்பட்டியிலே போட்டு, தகசுத்தோல் மூடியினால் மூடி, தண்டின்மேல் கட்டி,", "en": "And they shall take all the instruments of ministry, wherewith they minister in the sanctuary, and put them in a cloth of blue, and cover them with a covering of badgers’ skins, and shall put them on a bar:"}, {"verse": 13, "start": 118.16, "end": 124.29, "ta": "பலிபீடத்தைச் சாம்பலற விளக்கி, அதின்மேல் இரத்தாம்பரத் துப்பட்டியை விரித்து,", "en": "And they shall take away the ashes from the altar, and spread a purple cloth thereon:"}, {"verse": 14, "start": 124.29, "end": 146.41, "ta": "அதின்மேல் ஆராதனைக்கேற்ற சகல பணிமுட்டுகளாகிய கலசங்களையும், முள்துறடுகளையும், சாம்பல் எடுக்கும் கரண்டிகளையும், கலசங்களையும், பலிபீடத்திற்கடுத்த எல்லாப் பாத்திரங்களையும், அதின்மேல் வைத்து, அதின்மேல் தகசுத்தோல் மூடியை விரித்து, அதின் தண்டுகளைப் பாய்ச்சக்கடவர்கள்.", "en": "And they shall put upon it all the vessels thereof, wherewith they minister about it, even the censers, the fleshhooks, and the shovels, and the basons, all the vessels of the altar; and they shall spread upon it a covering of badgers’ skins, and put to the staves of it."}, {"verse": 15, "start": 146.41, "end": 171.75, "ta": "பாளயம் புறப்படும்போது, ஆரோனும் அவன் குமாரரும் பரிசுத்த ஸ்தலத்தையும் அதினுடைய சகல பணிமுட்டுகளையும் மூடித் தீர்ந்தபின்பு, கோகாத் புத்திரர் அதை எடுத்துக்கொண்டுபோகிறதற்கு வரக்கடவர்கள்; அவர்கள் சாகாதபடிக்குப் பரிசுத்தமானதைத் தொடாதிருக்கக்கடவர்கள்; ஆசரிப்புக் கூடாரத்திலே கோகாத் புத்திரர் சுமக்கும் சுமை இதுவே.", "en": "And when Aaron and his sons have made an end of covering the sanctuary, and all the vessels of the sanctuary, as the camp is to set forward; after that, the sons of Kohath shall come to bear it: but they shall not touch any holy thing, lest they die. These things are the burden of the sons of Kohath in the tabernacle of the congregation."}, {"verse": 16, "start": 171.75, "end": 193.79, "ta": "ஆசாரியனாகிய ஆரோனின் குமாரன் எலெயாசார், விளக்குக்கு எண்ணெயையும், சுகந்த தூபவர்க்கத்தையும், தினந்தோறும் இடும் போஜனபலியையும், அபிஷேக தைலத்தையும், வாசஸ்தலம் முழுவதையும், அதிலுள்ள யாவையும், பரிசுத்தஸ்தலத்தையும் அதின் பணிமுட்டுகளையும், விசாரிக்கக்கடவன் என்றார்.", "en": "And to the office of Eleazar the son of Aaron the priest pertaineth the oil for the light, and the sweet incense, and the daily meat offering, and the anointing oil, and the oversight of all the tabernacle, and of all that therein is , in the sanctuary, and in the vessels thereof."}, {"verse": 17, "start": 193.79, "end": 196.63, "ta": "கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 18, "start": 196.63, "end": 202.9, "ta": "லேவியருக்குள்ளே கோகாத் வம்சமாகிய கோத்திரத்தார் அழிந்துபோகாதபடி பாருங்கள்.", "en": "Cut ye not off the tribe of the families of the Kohathites from among the Levites:"}, {"verse": 19, "start": 202.9, "end": 212.4, "ta": "அவர்கள் மகா பரிசுத்தமானவைகளைக் கிட்டுகையில், சாகாமல் உயிரோடிருக்கும்படிக்கு, நீங்கள் அவர்களுக்காகச் செய்யவேண்டியதாவது:", "en": "But thus do unto them, that they may live, and not die, when they approach unto the most holy things: Aaron and his sons shall go in, and appoint them every one to his service and to his burden:"}, {"verse": 20, "start": 212.4, "end": 231.38, "ta": "ஆரோனும் அவன் குமாரரும் வந்து, அவர்களில் அவனவனை அவனவன் செய்யும் வேலைக்கும் அவனவன் சுமக்கும் சுமைக்கும் நியமிக்கக்கடவர்கள்; அவர்களோ சாகாதபடிக்குப் பரிசுத்தமானவைகள் மூடப்படும்போது பார்க்கிறதற்கு உட்பிரவேசியாமல் இருப்பார்களாக என்றார்.", "en": "But they shall not go in to see when the holy things are covered, lest they die."}, {"verse": 21, "start": 231.38, "end": 234.14, "ta": "பின்னும், கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 22, "start": 234.14, "end": 243.55, "ta": "கெர்சோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை வேலைசெய்யும் சேனைக்கு உட்படத்தக்க,", "en": "Take also the sum of the sons of Gershon, throughout the houses of their fathers, by their families;"}, {"verse": 23, "start": 243.55, "end": 250.36, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணி, தொகை ஏற்றுவாயாக.", "en": "From thirty years old and upward until fifty years old shalt thou number them; all that enter in to perform the service, to do the work in the tabernacle of the congregation."}, {"verse": 24, "start": 250.36, "end": 255.65, "ta": "பணிவிடை செய்கிறதிலும் சுமக்கிறதிலும் கெர்சோன் வம்சத்தாரின் வேலையாவது:", "en": "This is the service of the families of the Gershonites, to serve, and for burdens:"}, {"verse": 25, "start": 255.65, "end": 269.2, "ta": "அவர்கள் வாசஸ்தலத்துக்கும் ஆசரிப்புக் கூடாரத்துக்கும் உரிய தொங்குதிரையையும், மூடியையும், அவைகளின்மேல் இருக்கிற தகசுத்தோல் மூடியையும், ஆசரிப்புக் கூடாரவாசல் மறைவையும்,", "en": "And they shall bear the curtains of the tabernacle, and the tabernacle of the congregation, his covering, and the covering of the badgers’ skins that is above upon it, and the hanging for the door of the tabernacle of the congregation,"}, {"verse": 26, "start": 269.2, "end": 290.63, "ta": "பிராகாரத்தின் தொங்குதிரைகளையும், வாசஸ்தலத்தண்டையிலும் பலிபீடத்தண்டையிலும் சுற்றிலும் இருக்கிற பிராகாரத்தினுடைய வாசல் தொங்குதிரையையும், அவைகளின் கயிறுகளையும், அவைகளின் வேலைக்கடுத்த கருவிகள் யாவையும் சுமந்து, அவைகளுக்காகச் செய்யவேண்டிய யாவையும் செய்யக்கடவர்கள்.", "en": "And the hangings of the court, and the hanging for the door of the gate of the court, which is by the tabernacle and by the altar round about, and their cords, and all the instruments of their service, and all that is made for them: so shall they serve."}, {"verse": 27, "start": 290.63, "end": 308.92, "ta": "கெர்சோன் புத்திரர் சுமக்கவேண்டிய சுமைகளும் செய்யவேண்டிய பணிவிடைகளாகிய சகல வேலைகளும் ஆரோனும் அவன் குமாரரும் சொல்லுகிறபடியே செய்யவேண்டும், அவர்கள் சுமக்கவேண்டிய சகல சுமைகளையும் நீங்கள் நியமித்து, அவர்களிடத்தில் ஒப்புவியுங்கள்.", "en": "At the appointment of Aaron and his sons shall be all the service of the sons of the Gershonites, in all their burdens, and in all their service: and ye shall appoint unto them in charge all their burdens."}, {"verse": 28, "start": 308.92, "end": 323.77, "ta": "கெர்சோன் புத்திரரின் வம்சத்தார் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடை இதுதான்; அவர்களை வேலைகொள்ளும் விசாரணை, ஆசாரியனாகிய ஆரோரின் குமாரன் இத்தாமாருடைய கைக்குள் இருக்கவேண்டும்.", "en": "This is the service of the families of the sons of Gershon in the tabernacle of the congregation: and their charge shall be under the hand of Ithamar the son of Aaron the priest."}, {"verse": 29, "start": 323.77, "end": 333.04, "ta": "மெராரி புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை வேலைசெய்யும் சேனைக்கு உட்படத்தக்க,", "en": "As for the sons of Merari, thou shalt number them after their families, by the house of their fathers;"}, {"verse": 30, "start": 333.04, "end": 338.85, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணக்கடவாய்.", "en": "From thirty years old and upward even unto fifty years old shalt thou number them, every one that entereth into the service, to do the work of the tabernacle of the congregation."}, {"verse": 31, "start": 338.85, "end": 351.56, "ta": "ஆசரிப்புக் கூடாரத்தில் அவர்கள் செய்யும் எல்லாப் பணிவிடைக்கும் அடுத்த காவல் விசாரிப்பாவது: வாசஸ்தலத்தின் பலகைகளும், தாழ்ப்பாள்களும், தூண்களும், பாதங்களும்,", "en": "And this is the charge of their burden, according to all their service in the tabernacle of the congregation; the boards of the tabernacle, and the bars thereof, and the pillars thereof, and sockets thereof,"}, {"verse": 32, "start": 351.56, "end": 372.31, "ta": "சுற்றிலும் இருக்கிற பிராகாரத்தின் தூண்களும், அவைகளின் பாதங்களும், முளைகளும், கயிறுகளும், அவைகளின் சகல கருவிகளும், அவற்றிற்கு அடுத்த மற்றெல்லா வேலையும்தானே; அவர்கள் சுமந்து காவல்காக்கும்படி ஒப்புவிக்கப்படுகிறவைகளைப் பேர்பேராக எண்ணக்கடவீர்கள்.", "en": "And the pillars of the court round about, and their sockets, and their pins, and their cords, with all their instruments, and with all their service: and by name ye shall reckon the instruments of the charge of their burden."}, {"verse": 33, "start": 372.31, "end": 385.7, "ta": "ஆசாரியனாகிய ஆரோனுடைய குமாரனான இத்தாமாருடைய கைக்குள்ளாக மெராரி புத்திரரின் வம்சத்தாரர் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடைக்கு அடுத்த எல்லா வேலையும் இதுவே என்றார்.", "en": "This is the service of the families of the sons of Merari, according to all their service, in the tabernacle of the congregation, under the hand of Ithamar the son of Aaron the priest."}, {"verse": 34, "start": 385.7, "end": 398.33, "ta": "அப்படியே மோசேயும் ஆரோனும் சபையின் பிரபுக்களும் கோகாத் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களின்படி ஆசரிப்புக் கூடாரத்திலே பணிவிடை செய்யும் சேனைக்கு உட்படத்தக்க,", "en": "And Moses and Aaron and the chief of the congregation numbered the sons of the Kohathites after their families, and after the house of their fathers,"}, {"verse": 35, "start": 398.33, "end": 404.15, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணினார்கள்.", "en": "From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation:"}, {"verse": 36, "start": 404.15, "end": 410.35, "ta": "அவர்கள் வம்சங்களில் எண்ணப்பட்டவர்கள் இரண்டாயிரத்து எழுநூற்று ஐம்பதுபேர்.", "en": "And those that were numbered of them by their families were two thousand seven hundred and fifty."}, {"verse": 37, "start": 410.35, "end": 424.51, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, மோசேயினாலும் ஆரோனாலும் கோகாத் வம்சத்தாரில் ஆசரிப்புக் கூடாரத்தில் வேலை செய்கிறதற்காக, எண்ணித் தொகையிடப்பட்டவர்கள் எல்லாரும் இவர்களே.", "en": "These were they that were numbered of the families of the Kohathites, all that might do service in the tabernacle of the congregation, which Moses and Aaron did number according to the commandment of the LORD by the hand of Moses."}, {"verse": 38, "start": 424.51, "end": 433.62, "ta": "கெர்சோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை செய்யும் சேனைக்கு உட்படத்தக்க,", "en": "And those that were numbered of the sons of Gershon, throughout their families, and by the house of their fathers,"}, {"verse": 39, "start": 433.62, "end": 439.59, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரும் எண்ணப்பட்டார்கள்.", "en": "From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,"}, {"verse": 40, "start": 439.59, "end": 450.23, "ta": "அவர்களில் எண்ணப்பட்டவர்கள் அவரவர் குடும்பத்தின்படிக்கும், பிதாக்களுடைய வம்சத்தின்படிக்கும் இரண்டாயிரத்து அறுநூற்று முப்பதுபேர்.", "en": "Even those that were numbered of them, throughout their families, by the house of their fathers, were two thousand and six hundred and thirty."}, {"verse": 41, "start": 450.23, "end": 463.32, "ta": "மோசேயினாலும் ஆரோனாலும் கர்த்தர் கட்டளையிட்டபடியே கெர்சோன் புத்திரரின் வம்சத்தாரில் ஆசரிப்புக் கூடாரத்தில் வேலைசெய்ய எண்ணித் தொகையிடப்பட்டவர்கள் எல்லாரும் இவர்களே.", "en": "These are they that were numbered of the families of the sons of Gershon, of all that might do service in the tabernacle of the congregation, whom Moses and Aaron did number according to the commandment of the LORD ."}, {"verse": 42, "start": 463.32, "end": 472.28, "ta": "மெராரி புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை செய்யும் சேனைக்கு உட்படத்தக்க,", "en": "And those that were numbered of the families of the sons of Merari, throughout their families, by the house of their fathers,"}, {"verse": 43, "start": 472.28, "end": 478.02, "ta": "முப்பது வயதுமுதல் ஐம்பது வயதுள்ளவர்கள் எல்லாரும் எண்ணப்பட்டார்கள்.", "en": "From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,"}, {"verse": 44, "start": 478.02, "end": 484.68, "ta": "அவர்களில் எண்ணப்பட்டவர்கள் தங்கள் குடும்பங்களின்படியே மூவாயிரத்து இருநூறுபேர்.", "en": "Even those that were numbered of them after their families, were three thousand and two hundred."}, {"verse": 45, "start": 484.68, "end": 496.16, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே மோசேயினாலும் ஆரோனாலும் மெராரி புத்திரரின் குடும்பத்தாரில் எண்ணித் தொகையிடப்பட்டவர்கள் எல்லாரும் இவர்களே.", "en": "These be those that were numbered of the families of the sons of Merari, whom Moses and Aaron numbered according to the word of the LORD by the hand of Moses."}, {"verse": 46, "start": 496.16, "end": 510.17, "ta": "லேவியருடைய பிதாக்களின் வீட்டு வம்சங்களில் முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ளவர்கள் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடைவேலைக்கும் சுமையின் வேலைக்கும் உட்படத்தக்கவர்களும்,", "en": "All those that were numbered of the Levites, whom Moses and Aaron and the chief of Israel numbered, after their families, and after the house of their fathers,"}, {"verse": 47, "start": 510.17, "end": 516.75, "ta": "மோசேயினாலும் ஆரோனாலும் இஸ்ரவேலின் பிரபுக்களாலும் எண்ணப்பட்டவர்களும் ஆகிய எல்லாரும்,", "en": "From thirty years old and upward even unto fifty years old, every one that came to do the service of the ministry, and the service of the burden in the tabernacle of the congregation,"}, {"verse": 48, "start": 516.75, "end": 521.04, "ta": "எண்ணாயிரத்து ஐந்நூற்று எண்பதுபேராயிருந்தார்கள்.", "en": "Even those that were numbered of them, were eight thousand and five hundred and fourscore."}, {"verse": 49, "start": 521.04, "end": 539.26, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, அவர்கள் தங்கள் தங்கள் பணிவிடைக்கென்றும் தங்கள் தங்கள் சுமைக்கென்றும் மோசேயினால் எண்ணப்பட்டார்கள்; இவ்விதமாய், கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே அவர்கள் அவனால் எண்ணப்பட்டார்கள்.", "en": "According to the commandment of the LORD they were numbered by the hand of Moses, every one according to his service, and according to his burden: thus were they numbered of him, as the LORD commanded Moses."}]}, "5": {"chapter": 5, "duration": 393.34, "audio_url": "audio_ot/OT04_05.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 5.54, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.54, "end": 18.59, "ta": "குஷ்டரோகிகள் யாவரையும், பிரமியமுள்ளவர்கள் யாவரையும், சவத்தினால் தீட்டுப்பட்டவர்கள் யாவரையும் பாளயத்திலிருந்து விலக்கிவிட இஸ்ரவேல் புத்திரருக்குக் கட்டளையிடு.", "en": "Command the children of Israel, that they put out of the camp every leper, and every one that hath an issue, and whosoever is defiled by the dead:"}, {"verse": 3, "start": 18.59, "end": 35.57, "ta": "ஆண்பிள்ளையானாலும் பெண்பிள்ளையானாலும் அப்படிப்பட்டவர்களை நீங்கள் விலக்கி, நான் வாசம்பண்ணுகிற தங்கள் பாளயங்களை அவர்கள் தீட்டுப்படுத்தாதபடிக்கு, நீங்கள் அவர்களைப் பாளயத்திற்குப் புறம்பாக்கிவிடக்கடவீர்கள் என்றார்.", "en": "Both male and female shall ye put out, without the camp shall ye put them; that they defile not their camps, in the midst whereof I dwell."}, {"verse": 4, "start": 35.57, "end": 44.83, "ta": "கர்த்தர் மோசேக்குச் சொன்னபடியே, இஸ்ரவேல் புத்திரர் செய்து, அவர்களைப் பாளயத்திற்குப் புறம்பாக்கிவிட்டார்கள்.", "en": "And the children of Israel did so, and put them out without the camp: as the LORD spake unto Moses, so did the children of Israel."}, {"verse": 5, "start": 44.83, "end": 47.1, "ta": "மேலும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 6, "start": 47.1, "end": 60.98, "ta": "இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: ஒரு புருஷனானாலும் ஸ்திரீயானாலும், கர்த்தருடைய கட்டளையை மீறி மனிதர் செய்யும் பாவங்களில் யாதொரு பாவத்தைச் செய்து குற்றவாளியானால்,", "en": "Speak unto the children of Israel, When a man or woman shall commit any sin that men commit, to do a trespass against the LORD , and that person be guilty;"}, {"verse": 7, "start": 60.98, "end": 76.45, "ta": "அவர்கள் தாங்கள் செய்த பாவத்தை அறிக்கையிடக்கடவர்கள்; அப்படிப்பட்டவன் தான் செய்த குற்றத்தினிமித்தம் அபராதத்தின் முதலோடே ஐந்தில் ஒருபங்கை அதிகமாய்க் கூட்டி, தான் குற்றஞ்செய்தவனுக்குச் செலுத்தக்கடவன்", "en": "Then they shall confess their sin which they have done: and he shall recompense his trespass with the principal thereof, and add unto it the fifth part thereof, and give it unto him against whom he hath trespassed."}, {"verse": 8, "start": 76.45, "end": 94.19, "ta": "அதைக் கேட்டு வாங்குகிறதற்கு இனத்தான் ஒருவனும் இல்லாதிருந்தால், அப்பொழுது அவனுக்காகப் பாவநிவிர்த்தி செய்யும்படி ஆட்டுக்கடா செலுத்தப்படுவதுமல்லாமல், கர்த்தருக்கு அந்த அபராதம் செலுத்தப்பட்டு, அது ஆசாரியனைச் சேரவேண்டும்.", "en": "But if the man have no kinsman to recompense the trespass unto, let the trespass be recompensed unto the LORD , even to the priest; beside the ram of the atonement, whereby an atonement shall be made for him."}, {"verse": 9, "start": 94.19, "end": 104.2, "ta": "இஸ்ரவேல் புத்திரர் ஏறெடுத்துப் படைக்கும்படி ஆசாரியனிடத்தில் கொண்டுவருகிற எல்லாப் பரிசுத்தமான படைப்பும் அவனுடையதாயிருக்கும்.", "en": "And every offering of all the holy things of the children of Israel, which they bring unto the priest, shall be his."}, {"verse": 10, "start": 104.2, "end": 116.26, "ta": "ஒவ்வொருவரும் படைக்கும் பரிசுத்தமான வஸ்துக்கள் அவனுடையதாயிருக்கும்; ஒருவன் ஆசாரியனுக்குக் கொடுக்கிறது எதுவும் அவனுக்கே உரியது என்று சொல் என்றார்.", "en": "And every man’s hallowed things shall be his: whatsoever any man giveth the priest, it shall be his."}, {"verse": 11, "start": 116.26, "end": 118.01, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 12, "start": 118.01, "end": 127.64, "ta": "நீ இஸ்ரவேல் புத்திரருக்குச் சொல்லவேண்டியது என்னவென்றால்: ஒருவனுடைய மனைவி பிறர்முகம் பார்த்து, புருஷனுக்குத் துரோகம்பண்ணி,", "en": "Speak unto the children of Israel, and say unto them, If any man’s wife go aside, and commit a trespass against him,"}, {"verse": 13, "start": 127.64, "end": 145.68, "ta": "ஒருவனோடே சம்யோகமாய்ச் சயனித்திருந்த விஷயத்தில் அவள் தீட்டுப்பட்டவளாயிருந்தும், அவளுடைய புருஷன் கண்களுக்கு அது மறைக்கப்பட்டு வெளிக்கு வராமல் இருக்கிறபோதும், சாட்சியில்லாமலும் அவள் கையும் களவுமாகப் பிடிக்கப்படாமலும் இருக்கிறபோதும்,", "en": "And a man lie with her carnally, and it be hid from the eyes of her husband, and be kept close, and she be defiled, and there be no witness against her, neither she be taken with the manner;"}, {"verse": 14, "start": 145.68, "end": 166.61, "ta": "எரிச்சலின் ஆவி அவன்மேல் வந்து, அவன் தன்னுடைய மனைவி தீட்டுப்படுத்தப்பட்டிருக்க, தீட்டுப்படுத்தப்பட்ட தன் மனைவியின்மேல் குரோதங்கொண்டிருந்தாலும், அல்லது அவன் மனைவி தீட்டுப்படுத்தப்படாதிருக்க, எரிச்சலின் ஆவி அவன்மேல் வந்து, அவன் அவள்மேல் குரோதங்கொண்டிருந்தாலும்,", "en": "And the spirit of jealousy come upon him, and he be jealous of his wife, and she be defiled: or if the spirit of jealousy come upon him, and he be jealous of his wife, and she be not defiled:"}, {"verse": 15, "start": 166.61, "end": 191.72, "ta": "அந்தப் புருஷன் தன் மனைவியை ஆசாரியனிடத்தில் அழைத்துக்கொண்டு வந்து, அவள் நிமித்தம் ஒரு எப்பா அளவான வாற்கோதுமை மாவிலே பத்தில் ஒரு பங்கைப் படைப்பாகக் கொடுக்கக்கடவன்; அது எரிச்சலின் காணிக்கையும் அக்கிரமத்தை நினைப்பூட்டும் காணிக்கையுமாய் இருப்பதினால், அதின்மேல் எண்ணெய் வார்க்காமலும் தூபவர்க்கம்போடாமலும் இருப்பானாக.", "en": "Then shall the man bring his wife unto the priest, and he shall bring her offering for her, the tenth part of an ephah of barley meal; he shall pour no oil upon it, nor put frankincense thereon; for it is an offering of jealousy, an offering of memorial, bringing iniquity to remembrance."}, {"verse": 16, "start": 191.72, "end": 197.33, "ta": "ஆசாரின் அவளைச் சமீபத்தில் அழைத்து, கர்த்தருடைய சந்நிதியில் நிறுத்தி,", "en": "And the priest shall bring her near, and set her before the LORD :"}, {"verse": 17, "start": 197.33, "end": 207.26, "ta": "ஒரு மண்பாண்டத்திலே பரிசுத்த ஜலம் வார்த்து, வாசஸ்தலத்தின் தரையிலிருக்கும் புழுதியிலே கொஞ்சம் எடுத்து, அந்த ஜலத்திலே போட்டு,", "en": "And the priest shall take holy water in an earthen vessel; and of the dust that is in the floor of the tabernacle the priest shall take, and put it into the water:"}, {"verse": 18, "start": 207.26, "end": 223.94, "ta": "ஸ்திரீயைக் கர்த்தருடைய சந்நிதியில் நிறுத்தி, அவள் முக்காட்டை நீக்கி, எரிச்சலின் காணிக்கையாகிய நினைப்பூட்டுதலின் காணிக்கையை அவள் உள்ளங்கையிலே வைப்பானாக; சாபகாரணமான கசப்பான ஜலம் ஆசாரியன் கையிலிருக்கவேண்டும்,", "en": "And the priest shall set the woman before the LORD , and uncover the woman’s head, and put the offering of memorial in her hands, which is the jealousy offering: and the priest shall have in his hand the bitter water that causeth the curse:"}, {"verse": 19, "start": 223.94, "end": 241.77, "ta": "பின்பு ஆசாரியன் அவளை ஆணையிடுவித்து ஒருவனும் உன்னோடே சயனியாமலும், உன் புருஷனுக்கு உட்பட்டிருக்கிற நீ தீட்டுப்படத்தக்கதாய்ப் பிறர்முகம் பாராமலும் இருந்தால், சாபகாரணமான இந்தக் கசப்பான ஜலத்தின் தோஷத்துக்கு நீங்கலாயிருப்பாய்.", "en": "And the priest shall charge her by an oath, and say unto the woman, If no man have lain with thee, and if thou hast not gone aside to uncleanness with another instead of thy husband, be thou free from this bitter water that causeth the curse:"}, {"verse": 20, "start": 241.77, "end": 252.38, "ta": "உன் புருஷனுக்கு உட்பட்டிருக்கிற நீ பிறர்முகம் பார்த்து, உன் புருஷனோடேயன்றி அந்நியனோடே சம்யோகமாய் சயனித்துத் தீட்டுப்பட்டிருப்பாயானால்,", "en": "But if thou hast gone aside to another instead of thy husband, and if thou be defiled, and some man have lain with thee beside thine husband:"}, {"verse": 21, "start": 252.38, "end": 262.7, "ta": "கர்த்தர் உன் இடுப்பு சூம்பவும், உன் வயிறு வீங்கவும்பண்ணி, உன்னை உன் ஜனங்களுக்குள்ளே சாபமும் ஆணையிடுங்குறியுமாக வைப்பாராக.", "en": "Then the priest shall charge the woman with an oath of cursing, and the priest shall say unto the woman, The LORD make thee a curse and an oath among thy people, when the LORD doth make thy thigh to rot, and thy belly to swell;"}, {"verse": 22, "start": 262.7, "end": 281.2, "ta": "சாபகாரணமான இந்த ஜலம் உன் வயிறு வீங்கவும் இடுப்பு சூம்பவும் பண்ணும்படி, உன் குடலுக்குள் பிரவேசிக்கக்கடவது என்கிற சாபவார்த்தையாலே ஸ்திரீயை ஆணையிடுவித்துச் சொல்வானாக. அதற்கு அந்த ஸ்திரீ: ஆமென், ஆமென், என்று சொல்லக்கடவள்.", "en": "And this water that causeth the curse shall go into thy bowels, to make thy belly to swell, and thy thigh to rot: And the woman shall say, Amen, amen."}, {"verse": 23, "start": 281.2, "end": 289.31, "ta": "பின்பு ஆசாரியன் இந்தச் சாப வார்த்தைகளை ஒரு சீட்டில் எழுதி, அவைகளைக் கசப்பான ஜலத்தினால் கழுவிப்போட்டு,", "en": "And the priest shall write these curses in a book, and he shall blot them out with the bitter water:"}, {"verse": 24, "start": 289.31, "end": 299.93, "ta": "சாபகாரணமான அந்தக் கசப்பான ஜலத்தை அவள் குடிக்கும்படி பண்ணுவான்; அப்பொழுது சாபகாரணமான அந்த ஜலம் அவளுக்குள் இறங்கிக் கசப்பாகும்.", "en": "And he shall cause the woman to drink the bitter water that causeth the curse: and the water that causeth the curse shall enter into her, and become bitter."}, {"verse": 25, "start": 299.93, "end": 311.15, "ta": "பின்பு ஆசாரியன் எரிச்சலின் காணிக்கையை அந்த ஸ்திரீயின் கையிலிருந்து வாங்கி, அதைக் கர்த்தருடைய சந்நிதியில் அசைவாட்டி, பீடத்தின்மேல் செலுத்தி,", "en": "Then the priest shall take the jealousy offering out of the woman’s hand, and shall wave the offering before the LORD , and offer it upon the altar:"}, {"verse": 26, "start": 311.15, "end": 322.38, "ta": "ஞாபகக்குறியாக அதிலே ஒரு கைப்பிடி நிறைய எடுத்து, பீடத்தின்மேல் தகனித்து, பின்பு ஸ்திரீக்கு அந்த ஜலத்தைக் குடிக்கும்படி கொடுக்கக்கடவன்.", "en": "And the priest shall take an handful of the offering, even the memorial thereof, and burn it upon the altar, and afterward shall cause the woman to drink the water."}, {"verse": 27, "start": 322.38, "end": 345.58, "ta": "அந்த ஜலத்தைக் குடிக்கச் செய்தபின்பு சம்பவிப்பதாவது: அவள் தீட்டுப்பட்டு, தன் புருஷனுக்குத் துரோகம்பண்ணியிருந்தால், சாபகாரணமான அந்த ஜலம் அவளுக்குள் பிரவேசித்துக் கசப்புண்டானதினால், அவள் வயிறு வீங்கி, அவள் இடுப்பு சூம்பும்; இப்படியே அந்த ஸ்திரீ தன் ஜனங்களுக்குள்ளே சாபமாக இருப்பாள்.", "en": "And when he hath made her to drink the water, then it shall come to pass, that , if she be defiled, and have done trespass against her husband, that the water that causeth the curse shall enter into her, and become bitter, and her belly shall swell, and her thigh shall rot: and the woman shall be a curse among her people."}, {"verse": 28, "start": 345.58, "end": 354.53, "ta": "அந்த ஸ்திரீ தீட்டுப்படாமல் சுத்தமாயிருந்தால், அவள் அதற்கு நீங்கலாகி, கர்ப்பந்தரிக்கத்தக்கவளாயிருப்பாள்.", "en": "And if the woman be not defiled, but be clean; then she shall be free, and shall conceive seed."}, {"verse": 29, "start": 354.53, "end": 362.11, "ta": "ஒரு ஸ்திரீ தன் புருஷனோடேயன்றி அந்நிய புருஷனோடே சேர்ந்து தீட்டுப்பட்டதினால் உண்டான எரிச்சலுக்கும்,", "en": "This is the law of jealousies, when a wife goeth aside to another instead of her husband, and is defiled;"}, {"verse": 30, "start": 362.11, "end": 381.6, "ta": "புருஷன்மேல் எரிச்சலின் ஆவி வருகிறதினால், அவன் தன் மனைவியின்மேல் அடைந்த சமுசயத்துக்கும் அடுத்த பிரமாணம் இதுவே. அவன் கர்த்தருடைய சந்நிதியில் தன் மனைவியை நிறுத்துவானாக; ஆசாரியன் இந்தப் பிரமாணத்தின்படியெல்லாம் அவளுக்குச் செய்யக்கடவன்.", "en": "Or when the spirit of jealousy cometh upon him, and he be jealous over his wife, and shall set the woman before the LORD , and the priest shall execute upon her all this law."}, {"verse": 31, "start": 381.6, "end": 391.84, "ta": "புருஷனானவன் அக்கிரமத்திற்கு நீங்கலாயிருப்பான்; அப்படிப்பட்ட ஸ்திரீயோ, தன் அக்கிரமத்தைச் சுமப்பாள் என்று சொல் என்றார்.", "en": "Then shall the man be guiltless from iniquity, and this woman shall bear her iniquity."}]}, "6": {"chapter": 6, "duration": 342.46, "audio_url": "audio_ot/OT04_06.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 5.6, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.6, "end": 20.84, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: புருஷனாகிலும் ஸ்திரீயாகிலும் கர்த்தருக்கென்று விரதம் பண்ணிக்கொண்டவர்களாயிருக்கும்படி நசரேய விரதமாகிய ஒரு விசேஷித்த பொருத்தனையைப் பண்ணினால்,", "en": "Speak unto the children of Israel, and say unto them, When either man or woman shall separate themselves to vow a vow of a Nazarite, to separate themselves unto the LORD :"}, {"verse": 3, "start": 20.84, "end": 40.92, "ta": "அப்படிப்பட்டவன் திராட்சரசத்தையும் மதுபானத்தையும் விலக்கக்கடவன்; அவன் திராட்சரசத்தின் காடியையும் மற்ற மதுபானத்தின் காடியையும், திராட்சரசத்தினால் செய்த எவ்விதமான பானத்தையும் குடியாமலும், திராட்சப்பழங்களையாவது திராட்ச வற்றல்களையாவது புசியாமலும்,", "en": "He shall separate himself from wine and strong drink, and shall drink no vinegar of wine, or vinegar of strong drink, neither shall he drink any liquor of grapes, nor eat moist grapes, or dried."}, {"verse": 4, "start": 40.92, "end": 52.02, "ta": "தான் நசரேயனாயிருக்கும் நாளெல்லாம் திராட்சச்செடி விதைமுதல் தோல்வரையிலுள்ளவைகளினால் செய்யப்பட்ட யாதொன்றையும் புசியாமலும் இருக்கக்கடவன்.", "en": "All the days of his separation shall he eat nothing that is made of the vine tree, from the kernels even to the husk."}, {"verse": 5, "start": 52.02, "end": 67.65, "ta": "அவன் நசரேய விரதங்காக்கும் நாளெல்லாம் சவரகன் கத்தி அவன் தலையின்மேல் படலாகாது; அவன் கர்த்தருக்கென்று விரதங்காக்கும் காலம் நிறைவேறுமளவும் பரிசுத்தமாயிருந்து, தன் தலைமயிரை வளரவிடக்கடவன்.", "en": "All the days of the vow of his separation there shall no razor come upon his head: until the days be fulfilled, in the which he separateth himself unto the LORD , he shall be holy, and shall let the locks of the hair of his head grow."}, {"verse": 6, "start": 67.65, "end": 75.0, "ta": "அவன் கர்த்தருக்கென்று விரதங்காக்கும் நாளெல்லாம் யாதொரு பிரேதத்தண்டையில் போகக் கூடாது.", "en": "All the days that he separateth himself unto the LORD he shall come at no dead body."}, {"verse": 7, "start": 75.0, "end": 90.08, "ta": "அவன் தன் தேவனுக்கென்று செய்த நசரேய விரதம் அவன் தலைமேல் இருக்கிறபடியால், மரணமடைந்த தன் தகப்பனாலாகிலும் தாயினாலாகிலும் சகோதரனாலாகிலும் சகோதரியினாலாகிலும் தன்னைத் தீட்டுப்படுத்தலாகாது.", "en": "He shall not make himself unclean for his father, or for his mother, for his brother, or for his sister, when they die: because the consecration of his God is upon his head."}, {"verse": 8, "start": 90.08, "end": 96.26, "ta": "அவன் நசரேயனாயிருக்கும் நாளெல்லாம் கர்த்தருக்குப் பரிசுத்தமாயிருப்பான்.", "en": "All the days of his separation he is holy unto the LORD ."}, {"verse": 9, "start": 96.26, "end": 110.48, "ta": "அவனண்டையிலே ஒருவன் சடுதியில் மரணமடைந்ததினால், நசரேயவிரதமுள்ள அவனுடைய தலை தீட்டுப்பட்டதேயாகில், அவன் தன் சுத்திகரிப்பின் நாளாகிய ஏழாம் நாளில் தன் தலைமயிரைச் சிரைத்துக்கொண்டு,", "en": "And if any man die very suddenly by him, and he hath defiled the head of his consecration; then he shall shave his head in the day of his cleansing, on the seventh day shall he shave it."}, {"verse": 10, "start": 110.48, "end": 121.27, "ta": "எட்டாம் நாளில் இரண்டு காட்டுப்புறாக்களையாவது இரண்டு புறாக்குஞ்சுகளையாவது ஆசரிப்புக் கூடாரவாசலில் ஆசாரியனிடத்தில் கொண்டுவரக்கடவன்.", "en": "And on the eighth day he shall bring two turtles, or two young pigeons, to the priest, to the door of the tabernacle of the congregation:"}, {"verse": 11, "start": 121.27, "end": 137.44, "ta": "அப்பொழுது ஆசாரியன் ஒன்றைப் பாவநிவரணபலியாகவும், மற்றொன்றைச் சர்வாங்க தகனபலியாகவும் செலுத்தி, பிணத்தினால் அவனுக்கு உண்டான தீட்டை நிவிர்த்திசெய்து, அவன் தலையை அந்நாளில் பரிசுத்தப்படுத்துவானாக.", "en": "And the priest shall offer the one for a sin offering, and the other for a burnt offering, and make an atonement for him, for that he sinned by the dead, and shall hallow his head that same day."}, {"verse": 12, "start": 137.44, "end": 154.09, "ta": "அவன் திரும்பவும் தன் விரதநாட்களைக் கர்த்தருக்கென்று காத்து, ஒரு வருஷத்து ஆட்டுக்குட்டியைக் குற்றநிவாரணபலியாகக் கொண்டுவரக்கடவன்; அவனுடைய நசரேய விரதம் தீட்டுப்பட்டதினால் சென்ற நாட்கள் விருதாவாகும்.", "en": "And he shall consecrate unto the LORD the days of his separation, and shall bring a lamb of the first year for a trespass offering: but the days that were before shall be lost, because his separation was defiled."}, {"verse": 13, "start": 154.09, "end": 163.0, "ta": "நசரேயனுக்குரிய பிரமாணமாவது: அவன் விரதங்காக்கும் நாட்கள் நிறைவேறின அன்றே, அவன் ஆசரிப்புக் கூடாரவாசலிலே வந்து,", "en": "And this is the law of the Nazarite, when the days of his separation are fulfilled: he shall be brought unto the door of the tabernacle of the congregation:"}, {"verse": 14, "start": 163.0, "end": 176.99, "ta": "சர்வாங்க தகனபலியாக ஒரு வருஷத்து பழுதற்ற ஒரு ஆட்டுக்குட்டியையும் பாவநிவாரணபலியாக ஒரு வருஷத்து பழுதற்ற ஒரு பெண்ணாட்டுக்குட்டியையும், சமாதானபலியாக பழுதற்ற ஒரு ஆட்டுக்கடாவையும்,", "en": "And he shall offer his offering unto the LORD , one he lamb of the first year without blemish for a burnt offering, and one ewe lamb of the first year without blemish for a sin offering, and one ram without blemish for peace offerings,"}, {"verse": 15, "start": 176.99, "end": 195.83, "ta": "ஒரு கூடையில் எண்ணெயிலே பிசைந்த புளிப்பில்லாத மெல்லிய மாவினால் செய்த அதிரசங்களையும், எண்ணெய் தடவப்பட்ட புளிப்பில்லாத அடைகளையும், அவைகளுக்கு அடுத்த போஜனபலியையும், பானபலிகளையும் கர்த்தருக்குத் தன் காணிக்கையாகச் செலுத்தக்கடவன்.", "en": "And a basket of unleavened bread, cakes of fine flour mingled with oil, and wafers of unleavened bread anointed with oil, and their meat offering, and their drink offerings."}, {"verse": 16, "start": 195.83, "end": 205.67, "ta": "அவைகளை ஆசாரியன் கர்த்தருடைய சந்நிதியில் கொண்டுவந்து, அவனுடைய பாவநிவாரண பலியையும் அவனுடைய சர்வாங்க தகனபலியையும் செலுத்தி,", "en": "And the priest shall bring them before the LORD , and shall offer his sin offering, and his burnt offering:"}, {"verse": 17, "start": 205.67, "end": 218.41, "ta": "ஆட்டுக்கடாவைக் கூடையிலிருக்கும் புளிப்பில்லாத அப்பங்களோடுங்கூடக் கர்த்தருக்குச் சமாதானபலியாகச் செலுத்தி, அவனுடைய போஜனபலியையும் பானபலியையும் படைப்பானாக.", "en": "And he shall offer the ram for a sacrifice of peace offerings unto the LORD , with the basket of unleavened bread: the priest shall offer also his meat offering, and his drink offering."}, {"verse": 18, "start": 218.41, "end": 233.81, "ta": "அப்பொழுது நசரேயன் ஆசரிப்புக் கூடாரவாசலிலே, பொருத்தனை செய்யப்பட்ட தன் தலையைச் சிரைத்து, பொருத்தனை செய்யப்பட்ட தன் தலைமயிரை எடுத்து, சமாதானபலியின்கீழ் எரிகிற அக்கினியில் போடக்கடவன்.", "en": "And the Nazarite shall shave the head of his separation at the door of the tabernacle of the congregation, and shall take the hair of the head of his separation, and put it in the fire which is under the sacrifice of the peace offerings."}, {"verse": 19, "start": 233.81, "end": 254.68, "ta": "நசரேயன் பொருத்தனை செய்யப்பட்ட தன் தலைமயிரைச் சிரைத்துக்கொண்டபின்பு, ஆசாரியன் ஆட்டுக்கடாவினுடைய வேவிக்கப்பட்ட ஒரு முன்னந்தொடையையும், கூடையில் இருக்கிறவைகளிலே புளிப்பில்லாத ஒரு அதிரசத்தையும் புளிப்பில்லாத ஒரு அடையையும் எடுத்து, அவனுடைய உள்ளங்கைகளில் வைத்து,", "en": "And the priest shall take the sodden shoulder of the ram, and one unleavened cake out of the basket, and one unleavened wafer, and shall put them upon the hands of the Nazarite, after the hair of his separation is shaven:"}, {"verse": 20, "start": 254.68, "end": 273.12, "ta": "அவைகளைக் கர்த்தருடைய சந்நிதியில் அசைவாட்டக்கடவன்; அது அசைவாட்டப்பட்ட மார்க்கண்டத்தோடும், ஏறெடுத்துப் படைக்கப்பட்ட முன்னந்தொடையோடும், ஆசாரியனைச் சேரும்; அது பரிசுத்தமானது பின்பு நசரேயன் திராட்சரசம் குடிக்கலாம்.", "en": "And the priest shall wave them for a wave offering before the LORD : this is holy for the priest, with the wave breast and heave shoulder: and after that the Nazarite may drink wine."}, {"verse": 21, "start": 273.12, "end": 295.47, "ta": "பொருத்தனைபண்ணின நசரேயனுக்கும், அவன் தன் கைக்கு உதவுகிறதையல்லாமல், தன் நசரேய விரதத்தினிமித்தம் கர்த்தருக்குச் செலுத்தும் காணிக்கைக்கும் அடுத்த பிரமாணம் இதுவே. அவன் செய்த பொருத்தனையின்படியே தன் பொருத்தனையின் பிரமாணத்துக்கேற்க செய்து தீரவேண்டும் என்று சொல் என்றார்.", "en": "This is the law of the Nazarite who hath vowed, and of his offering unto the LORD for his separation, beside that that his hand shall get: according to the vow which he vowed, so he must do after the law of his separation."}, {"verse": 22, "start": 295.47, "end": 297.97, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 23, "start": 297.97, "end": 309.54, "ta": "நீ ஆரோனோடும் அவன் குமாரரோடும் சொல்லவேண்டியது என்னவென்றால்: நீங்கள் இஸ்ரவேல் புத்திரரை ஆசீர்வதிக்கும்போது, அவர்களைப் பார்த்துச் சொல்லவேண்டியதாவது:", "en": "Speak unto Aaron and unto his sons, saying, On this wise ye shall bless the children of Israel, saying unto them,"}, {"verse": 24, "start": 309.54, "end": 314.39, "ta": "கர்த்தர் உன்னை ஆசீர்வதித்து, உன்னைக் காக்கக்கடவர்.", "en": "The LORD bless thee, and keep thee:"}, {"verse": 25, "start": 314.39, "end": 321.89, "ta": "கர்த்தர் தம்முடைய முகத்தை உன்மேல் பிரகாசிக்கப்பண்ணி, உன்மேல் கிருபையாயிருக்கக்கடவர்.", "en": "The LORD make his face shine upon thee, and be gracious unto thee:"}, {"verse": 26, "start": 321.89, "end": 329.94, "ta": "கர்த்தர் தம்முடைய முகத்தை உன்மேல் பிரசன்னமாக்கி, உனக்குச் சமாதானம் கட்டளையிடக்கடவர் என்பதே.", "en": "The LORD lift up his countenance upon thee, and give thee peace."}, {"verse": 27, "start": 329.94, "end": 340.96, "ta": "இவ்விதமாய் அவர்கள் என் நாமத்தை இஸ்ரவேல் புத்திரர்மேல் கூறக்கடவர்கள்; அப்பொழுது நான் அவர்களை ஆசீர்வதிப்பேன் என்று சொல் என்றார்.", "en": "And they shall put my name upon the children of Israel; and I will bless them."}]}, "7": {"chapter": 7, "duration": 941.61, "audio_url": "audio_ot/OT04_07.mp3", "total_verses": 89, "verses": [{"verse": 1, "start": 3.8, "end": 17.18, "ta": "மோசே வாசஸ்தலத்தை ஸ்தாபனம்பண்ணி, அதையும் அதின் எல்லாப் பணிமுட்டுகளையும், பலிபீடத்தையும் அதின் எல்லாப் பணிமுட்டுகளையும் அபிஷேகம்பண்ணி, பரிசுத்தப்படுத்தி முடித்தநாளில்,", "en": "And it came to pass on the day that Moses had fully set up the tabernacle, and had anointed it, and sanctified it, and all the instruments thereof, both the altar and all the vessels thereof, and had anointed them, and sanctified them;"}, {"verse": 2, "start": 17.18, "end": 30.18, "ta": "தங்கள் பிதாக்களுடைய வம்சத்தலைவரும், எண்ணப்பட்டவர்களின் விசாரிப்புக்கு வைக்கப்பட்ட கோத்திரப் பிரபுக்களுமாகிய இஸ்ரவேலின் பிரபுக்கள் காணிக்கைகளைச் செலுத்தினார்கள்.", "en": "That the princes of Israel, heads of the house of their fathers, who were the princes of the tribes, and were over them that were numbered, offered:"}, {"verse": 3, "start": 30.18, "end": 48.16, "ta": "தங்கள் காணிக்கையாக, ஆறு கூண்டு வண்டில்களையும், பன்னிரண்டு மாடுகளையும் இரண்டிரண்டு பிரபுக்களுக்கு ஒவ்வொரு வண்டிலும், ஒவ்வொரு பிரபுக்கு ஒவ்வொரு மாடுமாக, கர்த்தருக்குச் செலுத்த வாசஸ்தலத்திற்கு முன்பாகக் கொண்டுவந்தார்கள்.", "en": "And they brought their offering before the LORD , six covered wagons, and twelve oxen; a wagon for two of the princes, and for each one an ox: and they brought them before the tabernacle."}, {"verse": 4, "start": 48.16, "end": 50.66, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 5, "start": 50.66, "end": 61.92, "ta": "நீ அவர்களிடத்தில் ஆசரிப்புக் கூடாரத்தின் ஊழியத்திற்காக அவைகளை வாங்கி, லேவியருக்கு அவரவர் வேலைக்குத்தக்கவைகளாகப் பங்கிட்டுக் கொடு என்றார்.", "en": "Take it of them, that they may be to do the service of the tabernacle of the congregation; and thou shalt give them unto the Levites, to every man according to his service."}, {"verse": 6, "start": 61.92, "end": 68.87, "ta": "அப்பொழுது மோசே அந்த வண்டில்களையும் மாடுகளையும் வாங்கி, லேவியருக்குக் கொடுத்தான்.", "en": "And Moses took the wagons and the oxen, and gave them unto the Levites."}, {"verse": 7, "start": 68.87, "end": 77.94, "ta": "இரண்டு வண்டில்களையும் நான்கு மாடுகளையும் கெர்சோன் புத்திரருக்கு, அவர்கள் வேலைக்குத்தக்க பங்காகக் கொடுத்தான்.", "en": "Two wagons and four oxen he gave unto the sons of Gershon, according to their service:"}, {"verse": 8, "start": 77.94, "end": 91.85, "ta": "நான்கு வண்டில்களையும் எட்டு மாடுகளையும் மெராரியின் புத்திரருக்கு, ஆசாரியனாகிய ஆரோனின் குமாரர் இத்தாமாருடைய கையின் கீழிருக்கிற அவர்களுடைய வேலைக்குத்தக்க பங்காகக் கொடுத்தான்.", "en": "And four wagons and eight oxen he gave unto the sons of Merari, according unto their service, under the hand of Ithamar the son of Aaron the priest."}, {"verse": 9, "start": 91.85, "end": 101.82, "ta": "கோகாத்தின் புத்திரருக்கோ ஒன்றும் கொடுக்கவில்லை; தோள்மேல் சுமப்பதே அவர்களுக்குரிய பரிசுத்த ஸ்தலத்தின் வேலையாயிருந்தது.", "en": "But unto the sons of Kohath he gave none: because the service of the sanctuary belonging unto them was that they should bear upon their shoulders."}, {"verse": 10, "start": 101.82, "end": 114.82, "ta": "பலிபீடம் அபிஷேகம்பண்ணப்பட்ட நாளிலே, பிரபுக்கள் அதின் பிரதிஷ்டைக்காகக் காணிக்கைகளைச் செலுத்தி, பலிபீடத்துக்கு முன்பாகத் தங்கள் காணிக்கைகளைக் கொண்டுவந்தார்கள்.", "en": "And the princes offered for dedicating of the altar in the day that it was anointed, even the princes offered their offering before the altar."}, {"verse": 11, "start": 114.82, "end": 126.16, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி: பலிபீடத்தின் பிரதிஷ்டைக்காக, ஒவ்வொரு பிரபுவும் தன்தன் நாளில் தன்தன் காணிக்கையைச் செலுத்தக்கடவன் என்றார்.", "en": "And the LORD said unto Moses, They shall offer their offering, each prince on his day, for the dedicating of the altar."}, {"verse": 12, "start": 126.16, "end": 134.7, "ta": "அப்படியே முதலாம் நாளில் தன் காணிக்கையைச் செலுத்தினவன் யூதா கோத்திரத்தானாகிய அம்மினதாபின் குமாரன் நகசோன்.", "en": "And he that offered his offering the first day was Nahshon the son of Amminadab, of the tribe of Judah:"}, {"verse": 13, "start": 134.7, "end": 154.5, "ta": "அவன் காணிக்கையாவது: போஜனபலியாக படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "And his offering was one silver charger, the weight thereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them were full of fine flour mingled with oil for a meat offering:"}, {"verse": 14, "start": 154.5, "end": 160.77, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One spoon of ten shekels of gold, full of incense:"}, {"verse": 15, "start": 160.77, "end": 167.88, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 16, "start": 167.88, "end": 171.13, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 17, "start": 171.13, "end": 185.64, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது அம்மினதாபின் குமாரனாகிய நகசோனின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Nahshon the son of Amminadab."}, {"verse": 18, "start": 185.64, "end": 192.89, "ta": "இரண்டாம் நாளில் இசக்காரின் பிரபுவாகிய சூவாரின் குமாரன் நெதனெயேல் காணிக்கை செலுத்தினான்.", "en": "On the second day Nethaneel the son of Zuar, prince of Issachar, did offer:"}, {"verse": 19, "start": 192.89, "end": 212.84, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "He offered for his offering one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 20, "start": 212.84, "end": 219.12, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One spoon of gold of ten shekels , full of incense:"}, {"verse": 21, "start": 219.12, "end": 225.92, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 22, "start": 225.92, "end": 229.17, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 23, "start": 229.17, "end": 243.6, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது சூவாரின் குமாரனாகிய நெதனெயேலின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Nethaneel the son of Zuar."}, {"verse": 24, "start": 243.6, "end": 251.84, "ta": "மூன்றாம் நாளில் ஏலோனின் குமாரனாகிய எலியாப் என்னும் செபுலோன் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the third day Eliab the son of Helon, prince of the children of Zebulun, did offer:"}, {"verse": 25, "start": 251.84, "end": 271.72, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல்நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 26, "start": 271.72, "end": 277.99, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 27, "start": 277.99, "end": 285.09, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 28, "start": 285.09, "end": 288.34, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 29, "start": 288.34, "end": 302.55, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது ஏலோனின் குமாரனாகிய எலியாபின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Eliab the son of Helon."}, {"verse": 30, "start": 302.55, "end": 311.09, "ta": "நான்காம் நாளில் சேதேயூரின் குமாரனாகிய எலிசூர் என்னும் ரூபன் புத்திரரின் பிரபு காணிக்கை, செலுத்தினான்.", "en": "On the fourth day Elizur the son of Shedeur, prince of the children of Reuben, did offer:"}, {"verse": 31, "start": 311.09, "end": 330.74, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும் பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger of the weight of an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 32, "start": 330.74, "end": 337.01, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 33, "start": 337.01, "end": 344.12, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 34, "start": 344.12, "end": 347.37, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 35, "start": 347.37, "end": 361.8, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது சேதேயூரின் குமாரனாகிய எலிசூரின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Elizur the son of Shedeur."}, {"verse": 36, "start": 361.8, "end": 370.57, "ta": "ஐந்தாம் நாளில் சூரிஷதாயின் குமாரனாகிய செலுூமியேல் என்னும் சிமியோன் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the fifth day Shelumiel the son of Zurishaddai, prince of the children of Simeon, did offer:"}, {"verse": 37, "start": 370.57, "end": 390.52, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 38, "start": 390.52, "end": 396.79, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 39, "start": 396.79, "end": 403.9, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 40, "start": 403.9, "end": 407.15, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 41, "start": 407.15, "end": 421.96, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது சூரிஷதாயின் குமாரனாகிய செலுூமியேலின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Shelumiel the son of Zurishaddai."}, {"verse": 42, "start": 421.96, "end": 430.05, "ta": "ஆறாம் நாளில் தேகுவேலின் குமாரனாகிய எலியாசாப் என்னும் காத் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the sixth day Eliasaph the son of Deuel, prince of the children of Gad, offered:"}, {"verse": 43, "start": 430.05, "end": 450.0, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger of the weight of an hundred and thirty shekels , a silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 44, "start": 450.0, "end": 456.27, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 45, "start": 456.27, "end": 463.38, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 46, "start": 463.38, "end": 466.63, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 47, "start": 466.63, "end": 480.61, "ta": "சமாதானபலியாக இரண்டு மாடுகளும் ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும் ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது தேகுவேலின் குமாரனாகிய எலியாசாபின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Eliasaph the son of Deuel."}, {"verse": 48, "start": 480.61, "end": 489.15, "ta": "ஏழாம் நாளில் அம்மியூதின் குமாரனாகிய எலிஷாமா என்னும் எப்பிராயீம் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the seventh day Elishama the son of Ammihud, prince of the children of Ephraim, offered:"}, {"verse": 49, "start": 489.15, "end": 509.1, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 50, "start": 509.1, "end": 515.37, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 51, "start": 515.37, "end": 522.48, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 52, "start": 522.48, "end": 525.8, "ta": "பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 53, "start": 525.8, "end": 540.46, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது அம்மியூதின் குமாரனாகிய எலிஷாமாவின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Elishama the son of Ammihud."}, {"verse": 54, "start": 540.46, "end": 548.78, "ta": "எட்டாம் நாளில் பெதாசூரின் குமாரனாகிய கமாலியேல் என்னும் மனாசே புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the eighth day offered Gamaliel the son of Pedahzur, prince of the children of Manasseh:"}, {"verse": 55, "start": 548.78, "end": 568.58, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெய் பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger of the weight of an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 56, "start": 568.58, "end": 574.85, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 57, "start": 574.85, "end": 581.96, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 58, "start": 581.96, "end": 585.21, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 59, "start": 585.21, "end": 599.79, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது பெதாசூரின் குமாரனாகிய கமாலியேலின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Gamaliel the son of Pedahzur."}, {"verse": 60, "start": 599.79, "end": 608.33, "ta": "ஒன்பதாம் நாளில் கீதெயோனின் குமாரனாகிய அபீதான் என்னும் பென்யமீன் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the ninth day Abidan the son of Gideoni, prince of the children of Benjamin, offered:"}, {"verse": 61, "start": 608.33, "end": 628.28, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 62, "start": 628.28, "end": 634.56, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 63, "start": 634.56, "end": 641.66, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 64, "start": 641.66, "end": 644.91, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 65, "start": 644.91, "end": 659.35, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது கீதெயோனின் குமாரனாகிய அபீதானின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Abidan the son of Gideoni."}, {"verse": 66, "start": 659.35, "end": 667.73, "ta": "பத்தாம் நாளில் அம்மிஷதாயின் குமாரனாகிய அகியேசேர் என்னும் தாண் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the tenth day Ahiezer the son of Ammishaddai, prince of the children of Dan, offered:"}, {"verse": 67, "start": 667.73, "end": 687.69, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 68, "start": 687.69, "end": 693.96, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 69, "start": 693.96, "end": 701.06, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 70, "start": 701.06, "end": 704.31, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 71, "start": 704.31, "end": 719.05, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது அம்மிஷதாயின் குமாரனாகிய அகியேசேரின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Ahiezer the son of Ammishaddai."}, {"verse": 72, "start": 719.05, "end": 727.36, "ta": "பதினோராம் நாளில் ஓகிரானின் குமாரனாகிய பாகியேல் என்னும் ஆசேர் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the eleventh day Pagiel the son of Ocran, prince of the children of Asher, offered:"}, {"verse": 73, "start": 727.36, "end": 747.32, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 74, "start": 747.32, "end": 753.59, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 75, "start": 753.59, "end": 760.69, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஒரு ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 76, "start": 760.69, "end": 763.94, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 77, "start": 763.94, "end": 778.38, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது ஓகிரானின் குமாரனாகிய பாகியேலின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Pagiel the son of Ocran."}, {"verse": 78, "start": 778.38, "end": 786.62, "ta": "பன்னிரண்டாம் நாளில் ஏனானின் குமாரனாகிய அகீரா என்னும் நப்தலி புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.", "en": "On the twelfth day Ahira the son of Enan, prince of the children of Naphtali, offered:"}, {"verse": 79, "start": 786.62, "end": 806.57, "ta": "அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரρ வெӠύளிՠύகலமும் ஆகிய இவ்விரண்டும்,", "en": "His offering was one silver charger, the weight whereof was an hundred and thirty shekels , one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:"}, {"verse": 80, "start": 806.57, "end": 812.84, "ta": "தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,", "en": "One golden spoon of ten shekels , full of incense:"}, {"verse": 81, "start": 812.84, "end": 819.64, "ta": "சர்வாங்க தகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒரு வயதான ஆட்டுக்குட்டியும்,", "en": "One young bullock, one ram, one lamb of the first year, for a burnt offering:"}, {"verse": 82, "start": 819.64, "end": 822.89, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,", "en": "One kid of the goats for a sin offering:"}, {"verse": 83, "start": 822.89, "end": 837.1, "ta": "சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒரு வயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது ஏனானின் குமாரனாகிய அகீராவின் காணிக்கை.", "en": "And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Ahira the son of Enan."}, {"verse": 84, "start": 837.1, "end": 851.16, "ta": "பலிபீடம் அபிஷேகம்பண்ணப்பட்டபோது, இஸ்ரவேல் பிரபுக்களால் செய்யப்பட்ட பிரதிஷ்டையாவது வெள்ளித்தாலங்கள் பன்னிரண்டு, வெள்ளிக்கலங்கள் பன்னிரண்டு, பொன் தூபகரண்டிகள் பன்னிரண்டு.", "en": "This was the dedication of the altar, in the day when it was anointed, by the princes of Israel: twelve chargers of silver, twelve silver bowls, twelve spoons of gold:"}, {"verse": 85, "start": 851.16, "end": 868.54, "ta": "ஒவ்வொரு வெள்ளித்தாலம் நூற்றுமுப்பது சேக்கல் நிறையும், ஒவ்வொரு கலம் எழுபது சேக்கல் நிறையுமாக, இந்தப் பாத்திரங்களின் வெள்ளியெல்லாம் பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்கின்படி இரண்டாயிரத்து நானூறு சேக்கல் நிறையாயிருந்தது.", "en": "Each charger of silver weighing an hundred and thirty shekels , each bowl seventy: all the silver vessels weighed two thousand and four hundred shekels , after the shekel of the sanctuary:"}, {"verse": 86, "start": 868.54, "end": 883.88, "ta": "தூபவர்க்கம் நிறைந்த பொன் தூபகரண்டிகள் பன்னிரண்டு, ஒவ்வொன்று பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்கின்படி பத்துச்சேக்கல் நிறையாக, தூபகரண்டிகளின் பொன்னெல்லாம் நூற்றிருபது சேக்கல் நிறையாயிருந்தது.", "en": "The golden spoons were twelve, full of incense, weighing ten shekels apiece, after the shekel of the sanctuary: all the gold of the spoons was an hundred and twenty shekels ."}, {"verse": 87, "start": 883.88, "end": 903.98, "ta": "சர்வாங்க தகனபலியாகச் செலுத்தப்பட்ட காளைகளெல்லாம் பன்னிரண்டு, ஆட்டுக்கடாக்கள் பன்னிரண்டு, ஒரு வயதான ஆட்டுக்குட்டிகள் பன்னிரண்டு, அவைகளுக்கடுத்த போஜனபலிகளும்கூடச் செலுத்தப்பட்டது; பாவநிவாரணபலியாகச் செலுத்தப்பட்ட வெள்ளாட்டுக்கடாக்கள் பன்னிரண்டு.", "en": "All the oxen for the burnt offering were twelve bullocks, the rams twelve, the lambs of the first year twelve, with their meat offering: and the kids of the goats for sin offering twelve."}, {"verse": 88, "start": 903.98, "end": 922.35, "ta": "சமாதான பலியாகச் செலுத்தப்பட்ட காளைகளெல்லாம் இருபத்துநான்கு; ஆட்டுக்கடாக்கள் அறுபது, வெள்ளாட்டுக்கடாக்கள் அறுபது, ஒரு வயதானஆட்டுக்குட்டிகள் அறுபது; பலிபீடம் அபிஷேகம்பண்ணப்பட்ட பின்பு செய்யப்பட்ட அதின் பிரதிஷ்டை இதுவே.", "en": "And all the oxen for the sacrifice of the peace offerings were twenty and four bullocks, the rams sixty, the he goats sixty, the lambs of the first year sixty. This was the dedication of the altar, after that it was anointed."}, {"verse": 89, "start": 922.35, "end": 940.11, "ta": "மோசே தேவனோடே பேசும்படி ஆசரிப்புக் கூடாரத்திற்குள் பிரவேசிக்கும்போது, தன்னோடே பேசுகிறவரின் சத்தம் சாட்சிப்பெட்டியின்மேலுள்ள கிருபாசனமான இரண்டு கேருபீன்களின் நடுவிலிருந்துண்டாகக் கேட்பான்; அங்கே இருந்து அவனோடே பேசுவார்.", "en": "And when Moses was gone into the tabernacle of the congregation to speak with him, then he heard the voice of one speaking unto him from off the mercy seat that was upon the ark of testimony, from between the two cherubims: and he spake unto him."}]}, "8": {"chapter": 8, "duration": 316.62, "audio_url": "audio_ot/OT04_08.mp3", "total_verses": 26, "verses": [{"verse": 1, "start": 3.8, "end": 5.58, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.58, "end": 17.01, "ta": "நீ ஆரோனோடே சொல்லவேண்டியது என்னவென்றால்: நீ விளக்குகளை ஏற்றும்போது ஏழு விளக்குகளும் விளக்குத்தண்டிற்கு நேரே எரியவேண்டும் என்று சொல் என்றார்.", "en": "Speak unto Aaron, and say unto him, When thou lightest the lamps, the seven lamps shall give light over against the candlestick."}, {"verse": 3, "start": 17.01, "end": 26.75, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபிரகாரம் ஆரோன் செய்து, விளக்குத்தண்டிற்கு நேரே ஒழுங்காக அதின் விளக்குகளை ஏற்றினான்.", "en": "And Aaron did so; he lighted the lamps thereof over against the candlestick, as the LORD commanded Moses."}, {"verse": 4, "start": 26.75, "end": 42.28, "ta": "இந்தக் குத்துவிளக்கு, அதின் பாதமுதல் பூக்கள்வரைக்கும் பொன்னினால் அடிப்புவேலையாய்ச் செய்யப்பட்டிருந்தது; கர்த்தர் மோசேக்குக் காண்பித்த மாதிரியின்படியே அவன் குத்துவிளக்கை உண்டாக்கினான்.", "en": "And this work of the candlestick was of beaten gold, unto the shaft thereof, unto the flowers thereof, was beaten work: according unto the pattern which the LORD had shewed Moses, so he made the candlestick."}, {"verse": 5, "start": 42.28, "end": 44.75, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 6, "start": 44.75, "end": 52.02, "ta": "நீ இஸ்ரவேல் சந்ததியாரினின்று லேவியரைப் பிரித்தெடுத்து, அவர்களைச் சுத்திகரிப்பாயாக.", "en": "Take the Levites from among the children of Israel, and cleanse them."}, {"verse": 7, "start": 52.02, "end": 69.56, "ta": "அவர்களைச் சுத்திரிக்கும்படி அவர்களுக்குச் செய்யவேண்டியதாவது: அவர்கள்மேல் சுத்திகரிக்கும் ஜலத்தைத் தெளிப்பாயாக; பின்பு அவர்கள் சர்வாங்க சவரம்பண்ணி தங்கள் வஸ்திரங்களைத் தோய்த்து, தங்களைச் சுத்திகரிக்கக்கடவர்கள்.", "en": "And thus shalt thou do unto them, to cleanse them: Sprinkle water of purifying upon them, and let them shave all their flesh, and let them wash their clothes, and so make themselves clean."}, {"verse": 8, "start": 69.56, "end": 81.92, "ta": "அப்பொழுது ஒரு காளையையும், அதற்கேற்ற எண்ணெயிலே பிசைந்த மெல்லிய மாவாகிய போஜனபலியையும் கொண்டுவரக்கடவர்கள்; பாவநிவாரணபலியாக வேறொரு காளையையும் நீ வாங்கி,", "en": "Then let them take a young bullock with his meat offering, even fine flour mingled with oil, and another young bullock shalt thou take for a sin offering."}, {"verse": 9, "start": 81.92, "end": 91.27, "ta": "லேவியரை ஆசரிப்புக் கூடாரத்துக்குமுன் வரச்செய்து, இஸ்ரவேல் புத்திரரின் சபையார் எல்லாரையும் கூடிவரப்பண்ணுவாயாக.", "en": "And thou shalt bring the Levites before the tabernacle of the congregation: and thou shalt gather the whole assembly of the children of Israel together:"}, {"verse": 10, "start": 91.27, "end": 100.93, "ta": "நீ லேவியரைக் கர்த்தருடைய சந்நிதியில் வரப்பண்ணினபோது, இஸ்ரவேல் புத்திரர் தங்கள் கைகளை லேவியர்மேல் வைக்கக்கடவர்கள்.", "en": "And thou shalt bring the Levites before the LORD : and the children of Israel shall put their hands upon the Levites:"}, {"verse": 11, "start": 100.93, "end": 114.53, "ta": "லேவியர் கர்த்தருக்குரிய பணிவிடை செய்யும்பொருட்டு, ஆரோன் அவர்களை இஸ்ரவேல் புத்திரரின் காணிக்கையாகக் கர்த்தருக்கு முன்பாக அசைவாட்டப்படும் காணிக்கையாய் நிறுத்தக்கடவன்.", "en": "And Aaron shall offer the Levites before the LORD for an offering of the children of Israel, that they may execute the service of the LORD ."}, {"verse": 12, "start": 114.53, "end": 132.84, "ta": "அதன்பின் லேவியர் தங்கள் கைகளைக் காளைகளுடைய தலையின்மேல் வைப்பார்களாக; பின்பு நீ லேவியருக்காகப் பாவநிவிர்த்தி செய்யும்பொருட்டு, கர்த்தருக்கு அவைகளில் ஒன்றைப் பாவநிவாரண பலியாகவும், மற்றொன்றைச் சர்வாங்க தகனபலியாகவும் செலுத்தி,", "en": "And the Levites shall lay their hands upon the heads of the bullocks: and thou shalt offer the one for a sin offering, and the other for a burnt offering, unto the LORD , to make an atonement for the Levites."}, {"verse": 13, "start": 132.84, "end": 141.88, "ta": "லேவியரை ஆரோனுக்கும் அவன் குமாரனுக்கும் முன்பாக நிறுத்தி, அவர்களைக் கர்த்தருக்கு அசைவாட்டப்படும் காணிக்கையாக்கி,", "en": "And thou shalt set the Levites before Aaron, and before his sons, and offer them for an offering unto the LORD ."}, {"verse": 14, "start": 141.88, "end": 151.08, "ta": "இப்படி நீ லேவியரை இஸ்ரவேல் புத்திரரிலிருந்து பிரித்தெடுக்கக்கடவாய்; லேவியர் என்னுடையவர்களாயிருப்பார்கள்.", "en": "Thus shalt thou separate the Levites from among the children of Israel: and the Levites shall be mine."}, {"verse": 15, "start": 151.08, "end": 164.37, "ta": "இப்படி அவர்களைச் சுத்திகரித்து, அவர்களை அசைவாட்டும் காணிக்கையாக்கக்கடவாய்; அதன்பின்பு லேவியர் ஆசரிப்புக் கூடாரத்தில் பணிவிடை செய்யப் பிரவேசிக்கக்கடவர்கள்.", "en": "And after that shall the Levites go in to do the service of the tabernacle of the congregation: and thou shalt cleanse them, and offer them for an offering."}, {"verse": 16, "start": 164.37, "end": 180.83, "ta": "இஸ்ரவேல் புத்திரரிலிருந்து அவர்கள் எனக்கு முற்றிலும் கொடுக்கப்பட்டிருக்கிறார்கள்; இஸ்ரவேல் புத்திரர் எல்லாரிலும் கர்ப்பந்திறந்து பிறக்கிற சகல முதற்பேறுக்கும் பதிலாக அவர்களை எனக்கு எடுத்துக்கொண்டேன்.", "en": "For they are wholly given unto me from among the children of Israel; instead of such as open every womb, even instead of the firstborn of all the children of Israel, have I taken them unto me."}, {"verse": 17, "start": 180.83, "end": 195.12, "ta": "இஸ்ரவேல் புத்திரரில் மனிதரிலும் மிருகஜீவன்களிலும் முதற்பேறானதெல்லாம் என்னுடையது; நான் எகிப்துதேசத்திலே முதற்பேறான யாவையும் சங்கரித்த நாளிலே அவைகளை எனக்கென்று பரிசுத்தப்படுத்தி,", "en": "For all the firstborn of the children of Israel are mine, both man and beast: on the day that I smote every firstborn in the land of Egypt I sanctified them for myself."}, {"verse": 18, "start": 195.12, "end": 202.0, "ta": "பின்பு லேவியரை இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறு சகலத்திற்கும் பதிலாக எடுத்துக்கொண்டு,", "en": "And I have taken the Levites for all the firstborn of the children of Israel."}, {"verse": 19, "start": 202.0, "end": 229.81, "ta": "லேவியர் இஸ்ரவேல் புத்திரருடைய பணிவிடையை ஆசரிப்புக் கூடாரத்தில் செய்யும்படிக்கும், இஸ்ரவேல் புத்திரருக்காகப் பாவநிவிர்த்தி செய்யும்படிக்கும், இஸ்ரவேல் புத்திரர் தாங்களே பரிசுத்தஸ்தலத்தில் சேருகிறதினால் இஸ்ரவேல் புத்திரரில் வாதையுண்டாகாதபடிக்கும், லேவியரை அவர்களிலிருந்து எடுத்து, ஆரோனுக்கும் அவன் குமாரருக்கும் தத்தமாகக் கொடுத்தேன் என்றார்.", "en": "And I have given the Levites as a gift to Aaron and to his sons from among the children of Israel, to do the service of the children of Israel in the tabernacle of the congregation, and to make an atonement for the children of Israel: that there be no plague among the children of Israel, when the children of Israel come nigh unto the sanctuary."}, {"verse": 20, "start": 229.81, "end": 242.18, "ta": "அப்பொழுது மோசேயும் ஆரோனும் இஸ்ரவேல் புத்திரரின் சபையார் யாவரும் கர்த்தர் லேவியரைக்குறித்து மோசேக்குக் கட்டளையிட்டபடியெல்லாம் லேவியருக்குச் செய்தார்கள்.", "en": "And Moses, and Aaron, and all the congregation of the children of Israel, did to the Levites according unto all that the LORD commanded Moses concerning the Levites, so did the children of Israel unto them."}, {"verse": 21, "start": 242.18, "end": 259.56, "ta": "லேவியர் சுத்திகரிக்கப்பட்டு, தங்கள் வஸ்திரங்களைத் தோய்த்தார்கள்; பின்பு ஆரோன் அவர்களைக் கர்த்தருக்கு முன்பாக அசைவாட்டும் காணிக்கையாக நிறுத்தி, அவர்களைச் சுத்திகரிக்க அவர்களுக்காகப் பாவநிவிர்த்தி செய்தான்.", "en": "And the Levites were purified, and they washed their clothes; and Aaron offered them as an offering before the LORD ; and Aaron made an atonement for them to cleanse them."}, {"verse": 22, "start": 259.56, "end": 277.34, "ta": "அதற்குப்பின்பு லேவியர் ஆரோனுக்கும் அவன் குமாரருக்கும் முன்பாக ஆசரிப்புக் கூடாரத்தில் தங்கள் பணிவிடையைச் செய்யும்படி பிரவேசித்தார்கள்; கர்த்தர் லேவியரைக்குறித்து மோசேக்குக் கட்டளையிட்டபடியே அவர்களுக்குச் செய்தார்கள்.", "en": "And after that went the Levites in to do their service in the tabernacle of the congregation before Aaron, and before his sons: as the LORD had commanded Moses concerning the Levites, so did they unto them."}, {"verse": 23, "start": 277.34, "end": 279.81, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 24, "start": 279.81, "end": 293.1, "ta": "லேவியருக்குரிய கட்டளை என்னவென்றால்: இருபத்தைந்து வயதுமுதல் அதற்கு மேற்பட்ட வயதுள்ள யாவரும் ஆசரிப்புக் கூடாரத்தின் பணிவிடையைச் செய்யும் சேனையிலே சேவிக்க வரவேண்டும்.", "en": "This is it that belongeth unto the Levites: from twenty and five years old and upward they shall go in to wait upon the service of the tabernacle of the congregation:"}, {"verse": 25, "start": 293.1, "end": 298.66, "ta": "ஐம்பது வயதுக்கு மேற்பட்டவர்கள் வேலைசெய்யாமல் திருப்பணி சேனையை விட்டு,", "en": "And from the age of fifty years they shall cease waiting upon the service thereof , and shall serve no more:"}, {"verse": 26, "start": 298.66, "end": 315.12, "ta": "ஆசரிப்புக் கூடாரத்தின் காவலைக் காக்கிறதற்குத் தங்கள் சகோதரரோடே ஊழியஞ்செய்வதேயன்றி, வேறொரு சேவகமும் செய்யவேண்டியதில்லை; இப்படி லேவியர் செய்யவேண்டிய வேலைகளைக்குறித்துத் திட்டம்பண்ணக்கடவாய் என்றார்.", "en": "But shall minister with their brethren in the tabernacle of the congregation, to keep the charge, and shall do no service. Thus shalt thou do unto the Levites touching their charge."}]}, "9": {"chapter": 9, "duration": 285.05, "audio_url": "audio_ot/OT04_09.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 12.48, "ta": "அவர்கள் எகிப்துதேசத்திலிருந்து புறப்பட்ட இரண்டாம் வருஷம் முதலாம் மாதத்தில் கர்த்தர் சீனாய் வனாந்தரத்தில் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the wilderness of Sinai, in the first month of the second year after they were come out of the land of Egypt, saying,"}, {"verse": 2, "start": 12.48, "end": 17.73, "ta": "குறித்த காலத்தில் இஸ்ரவேல் புத்திரர் பஸ்காவை ஆசரிக்கக்கடவர்கள்.", "en": "Let the children of Israel also keep the passover at his appointed season."}, {"verse": 3, "start": 17.73, "end": 31.88, "ta": "இந்த மாதம் பதினாலாந்தேதி அந்திநேரமான வேளையாகிய குறித்த காலத்தில் அதை ஆசரிக்கக்கடவீர்கள்; அதற்குரிய எல்லாக் கட்டளையின்படியேயும் முறைமைகளின்படியேயும் அதை ஆசரிக்கக்கடவீர்கள் என்றார்.", "en": "In the fourteenth day of this month, at even, ye shall keep it in his appointed season: according to all the rites of it, and according to all the ceremonies thereof, shall ye keep it."}, {"verse": 4, "start": 31.88, "end": 38.08, "ta": "அப்படியே பஸ்காவை ஆசரிக்கும்படி மோசே இஸ்ரவேல் புத்திரருக்குக் கட்டளையிட்டான்.", "en": "And Moses spake unto the children of Israel, that they should keep the passover."}, {"verse": 5, "start": 38.08, "end": 52.44, "ta": "அதினால் முதலாம் மாதம் பதினான்காம் தேதி அந்திநேரமான வேளையில், சீனாய் வனாந்தரத்தில் பஸ்காவை ஆசரித்தார்கள்; கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியெல்லாம் இஸ்ரவேல் புத்திரர் செய்தார்கள்.", "en": "And they kept the passover on the fourteenth day of the first month at even in the wilderness of Sinai: according to all that the LORD commanded Moses, so did the children of Israel."}, {"verse": 6, "start": 52.44, "end": 64.11, "ta": "அந்நாளில் சிலர் மனித பிரேதத்தினால் தீட்டுப்பட்டபடியினால் பஸ்காவை ஆசரிக்கத்தகாதவர்களாயிருந்தார்கள்; அவர்கள் அந்நாளிலே மோசேக்கும் ஆரோனுக்கும் முன்பாக வந்து:", "en": "And there were certain men, who were defiled by the dead body of a man, that they could not keep the passover on that day: and they came before Moses and before Aaron on that day:"}, {"verse": 7, "start": 64.11, "end": 78.92, "ta": "நாங்கள் மனித பிரேதத்தினால் தீட்டுப்பட்டவர்கள்; குறித்த காலத்தில் இஸ்ரவேல் புத்திரரோடேகூடக் கர்த்தருக்குக் காணிக்கையைச் செலுΤ்தாĠΪடߠΕ்கl நாங்களύ விலக்ՠΪ்ʠΟ்ߠοருக்கவேண்டியது என்ன என்றார்கள்.", "en": "And those men said unto him, We are defiled by the dead body of a man: wherefore are we kept back, that we may not offer an offering of the LORD in his appointed season among the children of Israel?"}, {"verse": 8, "start": 78.92, "end": 87.45, "ta": "மோசே அவர்களை நோக்கி: பொறுங்கள்; கர்த்தர் உங்களைக்குறித்துக் கட்டளையிடுவது என்ன என்று கேட்பேன் என்றான்.", "en": "And Moses said unto them, Stand still, and I will hear what the LORD will command concerning you."}, {"verse": 9, "start": 87.45, "end": 89.13, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 10, "start": 89.13, "end": 105.32, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: உங்களிலாகிலும் உங்கள் சந்ததியாரிலாகிலும் ஒருவன் பிரேதத்தினால் தீட்டுப்பட்டாலும், பிரயாணமாய்த் தூரம்போயிருந்தாலும், கர்த்தருக்குப் பஸ்காவை ஆசரிக்கவேண்டும்.", "en": "Speak unto the children of Israel, saying, If any man of you or of your posterity shall be unclean by reason of a dead body, or be in a journey afar off, yet he shall keep the passover unto the LORD ."}, {"verse": 11, "start": 105.32, "end": 115.6, "ta": "அவர்கள் அதை இரண்டாம் மாதம் பதினாலாந்தேதி அந்திநேரமான வேளையில் ஆசரித்து, அதைப் புளிப்பில்லாத அப்பங்களோடும் கசப்பான கீரைகளோடும் புசித்து,", "en": "The fourteenth day of the second month at even they shall keep it, and eat it with unleavened bread and bitter herbs ."}, {"verse": 12, "start": 115.6, "end": 127.63, "ta": "விடியற்காலம்மட்டும் அதில் ஒன்றும் மீதியாக வைக்காமலும், அதில் ஒரு எலும்பையும் முறிக்காமலும், பஸ்காவினுடைய சகல முறைமைகளின்படியும் அதை ஆசரிக்கக்கடவர்கள்.", "en": "They shall leave none of it unto the morning, nor break any bone of it: according to all the ordinances of the passover they shall keep it."}, {"verse": 13, "start": 127.63, "end": 145.94, "ta": "ஒருவன் சுத்தமுள்ளவனுமாய்ப் பிரயாணம் போகாதவனுமாயிருந்தும், பஸ்காவை ஆசரிக்காதேபோனால், அந்த ஆத்துமா குறித்த காலத்தில் கர்த்தரின் பலியைச் செலுத்தாதபடியினால் தன் ஜனத்தாரில் இராமல் அறுப்புண்டுபோவான்; அந்த மனிதன் தன் பாவத்தைச் சுமப்பான்.", "en": "But the man that is clean, and is not in a journey, and forbeareth to keep the passover, even the same soul shall be cut off from among his people: because he brought not the offering of the LORD in his appointed season, that man shall bear his sin."}, {"verse": 14, "start": 145.94, "end": 163.8, "ta": "ஒரு பரதேசி உங்களிடத்திலே தங்கி, கர்த்தருக்குப் பஸ்காவை ஆசரிக்கவேண்டுமானால், அவன் அதைப் பஸ்காவின் கட்டளைப்படியும் அதின் முறைமையின்படியும் ஆசரிக்கக்கடவன்; பரதேசிக்கும் சுதேசிக்கும் ஒரே கட்டளை இருக்கவேண்டும் என்று சொல் என்றார்.", "en": "And if a stranger shall sojourn among you, and will keep the passover unto the LORD ; according to the ordinance of the passover, and according to the manner thereof, so shall he do: ye shall have one ordinance, both for the stranger, and for him that was born in the land."}, {"verse": 15, "start": 163.8, "end": 179.85, "ta": "வாசஸ்தலம் ஸ்தாபனஞ்செய்யப்பட்ட நாளிலே, மேகமானது சாட்சியின் கூடாரமாகிய வாசஸ்தலத்தை மூடிற்று; சாயங்காலமானபோது, வாசஸ்தலத்தின்மேல் அக்கினிமயமான ஒரு தோற்றமுண்டாயிற்று; அது விடியற்காலமட்டும் இருந்தது.", "en": "And on the day that the tabernacle was reared up the cloud covered the tabernacle, namely , the tent of the testimony: and at even there was upon the tabernacle as it were the appearance of fire, until the morning."}, {"verse": 16, "start": 179.85, "end": 187.94, "ta": "இப்படி நித்தமும் இருந்தது; பகலில் மேகமும், இரவில் அக்கினித்தோற்றமும் அதை மூடிக்கொண்டிருந்தது.", "en": "So it was alway: the cloud covered it by day , and the appearance of fire by night."}, {"verse": 17, "start": 187.94, "end": 199.46, "ta": "மேகம் கூடாரத்திலிருந்து மேலே எழும்பும்போது இஸ்ரவேல் புத்திரர் பிரயாணம்பண்ணுவார்கள்; மேகம் தங்குமிடத்தில் இஸ்ரவேல் புத்திரர் பாளயமிறங்குவார்கள்.", "en": "And when the cloud was taken up from the tabernacle, then after that the children of Israel journeyed: and in the place where the cloud abode, there the children of Israel pitched their tents."}, {"verse": 18, "start": 199.46, "end": 215.8, "ta": "கர்த்தருடைய கட்டளையின்படியே இஸ்ரவேல் புத்திரர் பிரயாணப்படுவர்கள்; கர்த்தருடைய கட்டளையின்படியே பாளயமிறங்குவார்கள்; மேகம் வாசஸ்தலத்தின்மேல் தங்கியிருக்கும் நாளெல்லாம் அவர்கள் பாளயத்தில் தங்கியிருப்பார்கள்.", "en": "At the commandment of the LORD the children of Israel journeyed, and at the commandment of the LORD they pitched: as long as the cloud abode upon the tabernacle they rested in their tents."}, {"verse": 19, "start": 215.8, "end": 226.37, "ta": "மேகம் நெடுநாள் வாசஸ்தலத்தின்மேல் தங்கியிருக்கும்போது, இஸ்ரவேல் புத்திரர் பிரயாணப்படாமல் கர்த்தரின் காவலைக் காத்துக்கொண்டிருப்பார்கள்.", "en": "And when the cloud tarried long upon the tabernacle many days, then the children of Israel kept the charge of the LORD , and journeyed not."}, {"verse": 20, "start": 226.37, "end": 239.06, "ta": "மேகம் சிலநாள் மாத்திரம் வாசஸ்தலத்தின்மேல் தங்கியிருக்கும்போது, கர்த்தருடைய கட்டளையின்படியே பாளயமிறங்கியிருந்து, கர்த்தருடைய கட்டளையின்படியே பிரயாணப்படுவார்கள்.", "en": "And so it was, when the cloud was a few days upon the tabernacle; according to the commandment of the LORD they abode in their tents, and according to the commandment of the LORD they journeyed."}, {"verse": 21, "start": 239.06, "end": 253.5, "ta": "மேகம் சாயங்காலந்தொடங்கி விடியற்காலமட்டும் இருந்து, விடியற்காலத்தில் உயர எழும்பும்போது, உடனே பிரயாணப்படுவார்கள்; பகலிலாகிலும் இரவிலாகிலும் மேகம் எழும்பும்போது பிரயாணப்படுவார்கள்.", "en": "And so it was, when the cloud abode from even unto the morning, and that the cloud was taken up in the morning, then they journeyed: whether it was by day or by night that the cloud was taken up, they journeyed."}, {"verse": 22, "start": 253.5, "end": 268.82, "ta": "மேகமானது இரண்டுநாளாவது ஒரு மாதமாவது ஒரு வருஷமாவது வாசஸ்தலத்தின்மேல் தங்கியிருக்கும்போது, இஸ்ரவேல் புத்திரர் பிரயாணம்பண்ணாமல் பாளயமிறங்கியிருப்பார்கள்; அது உயர எழும்பும்போதோ பிரயாணப்படுவார்கள்.", "en": "Or whether it were two days, or a month, or a year, that the cloud tarried upon the tabernacle, remaining thereon, the children of Israel abode in their tents, and journeyed not: but when it was taken up, they journeyed."}, {"verse": 23, "start": 268.82, "end": 283.55, "ta": "கர்த்தருடைய கட்டளையின்படியே பாளயமிறங்குவார்கள்; கர்த்தருடைய கட்டளையின்படியே பிரயாணம்பண்ணுவார்கள்; கர்த்தர் மோசேயைக்கொண்டு கட்டளையிடுகிறபடியே கர்த்தருடைய காவலைக் காத்துக்கொள்வார்கள்.", "en": "At the commandment of the LORD they rested in the tents, and at the commandment of the LORD they journeyed: they kept the charge of the LORD , at the commandment of the LORD by the hand of Moses."}]}, "10": {"chapter": 10, "duration": 392.56, "audio_url": "audio_ot/OT04_10.mp3", "total_verses": 36, "verses": [{"verse": 1, "start": 3.8, "end": 5.56, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.56, "end": 19.21, "ta": "சபையைக் கூடிவரவழைப்பதற்கும் பாளயங்களைப் பிரயாணப்படுத்துவதற்கும் உபயோகமாக இரண்டு வெள்ளிப்பூரிகைகளைச் செய்துகொள்வாயாக; அவைகள் ஒரே வெள்ளித்தகட்டால் செய்யப்படவேண்டும்.", "en": "Make thee two trumpets of silver; of a whole piece shalt thou make them: that thou mayest use them for the calling of the assembly, and for the journeying of the camps."}, {"verse": 3, "start": 19.21, "end": 26.73, "ta": "அவைகளை ஊதும்போது, சபையாரெல்லாரும் ஆசரிப்புக் கூடாரவாசலில் உன்னிடத்தில் கூடிவரவேண்டும்.", "en": "And when they shall blow with them, all the assembly shall assemble themselves to thee at the door of the tabernacle of the congregation."}, {"verse": 4, "start": 26.73, "end": 35.24, "ta": "ஒன்றைமாத்திரம் ஊதினால் இஸ்ரவேலில் ஆயிரவர்களுக்குத் தலைவராகிய பிரபுக்கள் உன்னிடத்தில் கூடிவரக்கடவர்கள்.", "en": "And if they blow but with one trumpet , then the princes, which are heads of the thousands of Israel, shall gather themselves unto thee."}, {"verse": 5, "start": 35.24, "end": 43.75, "ta": "நீங்கள் அவைகளைப் பெருந்தொனியாய் முழக்கும்போது, கிழக்கே இறங்கியிருக்கிற பாளயங்கள் பிரயாணப்படக்கடவது.", "en": "When ye blow an alarm, then the camps that lie on the east parts shall go forward."}, {"verse": 6, "start": 43.75, "end": 58.48, "ta": "அவைகளை நீங்கள் இரண்டாந்தரம் பெருந்தொனியாய் முழக்கும்போது, தெற்கே இறங்கியிருக்கிற பாளயங்கள் பிரயாணப்படக்கடவது; அவர்களைப் பிரயாணப்படுத்துவதற்குப் பெருந்தொனியாய் முழக்கவேண்டும்.", "en": "When ye blow an alarm the second time, then the camps that lie on the south side shall take their journey: they shall blow an alarm for their journeys."}, {"verse": 7, "start": 58.48, "end": 65.15, "ta": "சபையைக் கூட்டுகிறதற்கு நீங்கள் ஊதவேண்டியதேயன்றி பெருந்தொனியாய் முழக்கவேண்டாம்.", "en": "But when the congregation is to be gathered together, ye shall blow, but ye shall not sound an alarm."}, {"verse": 8, "start": 65.15, "end": 75.42, "ta": "ஆரோனின் குமாரராகிய ஆசாரியர் பூரிகைகளை ஊதக்கடவர்கள்; உங்கள் தலைமுறைதோறும் இது உங்களுக்கு நித்திய கட்டளையாயிருக்கக்கடவது.", "en": "And the sons of Aaron, the priests, shall blow with the trumpets; and they shall be to you for an ordinance for ever throughout your generations."}, {"verse": 9, "start": 75.42, "end": 97.43, "ta": "உங்கள் தேசத்தில் உங்களைத் துன்பப்படுத்துகிற சத்துருவுக்கு விரோதமாக யுத்தத்துக்குப் போகும்போது, பூரிகைகளைப் பெருந்தொனியாய் முழக்கக்கடவீர்கள்; அப்பொழுது உங்கள் தேவனாகிய கர்த்தருடைய சமுகத்திலே நீங்கள் நினைவுகூரப்பட்டு, உங்கள் பகைஞருக்கு நீங்கலாகி இரட்சிக்கப்படுவீர்கள்.", "en": "And if ye go to war in your land against the enemy that oppresseth you, then ye shall blow an alarm with the trumpets; and ye shall be remembered before the LORD your God, and ye shall be saved from your enemies."}, {"verse": 10, "start": 97.43, "end": 120.74, "ta": "உங்கள் மகிழ்ச்சியின் நாளிலும், உங்கள் பண்டிகைகளிலும், மாதப்பிறப்புகளிலும், உங்கள் சர்வாங்க தகனபலிகளும் சமாதானபலிகளும் செலுத்தப்படும்போது பூரிகைகளை ஊதவேண்டும்; அப்பொழுது அவைகள் உங்கள் தேவனுடைய சமுகத்தில் உங்களுக்கு ஞாபகக்குறியாயிக்கும்; நான் உங்கள் தேவனாகிய கர்த்தர் என்றார்.", "en": "Also in the day of your gladness, and in your solemn days, and in the beginnings of your months, ye shall blow with the trumpets over your burnt offerings, and over the sacrifices of your peace offerings; that they may be to you for a memorial before your God: I am the LORD your God."}, {"verse": 11, "start": 120.74, "end": 130.02, "ta": "இரண்டாம் வருஷம் இரண்டாம் மாதம் இருபதாம் தேதியில் மேகம் சாட்சியினுடைய வாசஸ்தலத்தின் மீதிலிருந்து உயர எழும்பிற்று.", "en": "And it came to pass on the twentieth day of the second month, in the second year, that the cloud was taken up from off the tabernacle of the testimony."}, {"verse": 12, "start": 130.02, "end": 141.68, "ta": "அப்பொழுது இஸ்ரவேல் புத்திரர் சீனாய் வனாந்தரத்திலிருந்து தங்கள் பிரயாண வரிசைகளாய்ப் புறப்பட்டார்கள்; மேகம் பாரான் வனாந்தரத்தில் தங்கிற்று.", "en": "And the children of Israel took their journeys out of the wilderness of Sinai; and the cloud rested in the wilderness of Paran."}, {"verse": 13, "start": 141.68, "end": 148.12, "ta": "இப்படியே கர்த்தர் மோசேயைக்கொண்டு கட்டளையிட்டபடி முதல் பிரயாணம்பண்ணினார்கள்.", "en": "And they first took their journey according to the commandment of the LORD by the hand of Moses."}, {"verse": 14, "start": 148.12, "end": 159.55, "ta": "யூதா சந்ததியாருடைய பாளயத்தின் கொடி அவர்கள் சேனைகளோடே முதல் புறப்பட்டது; அவனுடைய சேனைக்கு அம்மினதாபின் குமாரன் நகசோன் தலைவனாயிருந்தான்.", "en": "In the first place went the standard of the camp of the children of Judah according to their armies: and over his host was Nahshon the son of Amminadab."}, {"verse": 15, "start": 159.55, "end": 167.29, "ta": "இசக்கார் சந்ததியாருடைய கோத்திரத்தின் சேனைக்குச் சூவாரின் குமாரன் நெதனெயேல் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Issachar was Nethaneel the son of Zuar."}, {"verse": 16, "start": 167.29, "end": 174.65, "ta": "செபுலோன் சந்ததியாருடைய கோத்திரத்தின் சேனைக்கு ஏலோனின் குமாரன் எலியாப் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Zebulun was Eliab the son of Helon."}, {"verse": 17, "start": 174.65, "end": 184.78, "ta": "அப்பொழுது வாசஸ்தலம் இறக்கிவைக்கப்பட்டது; அதைக் கெர்சோன் புத்திரரும் மெராரி புத்திரரும் சுமந்துகொண்டு புறப்பட்டார்கள்.", "en": "And the tabernacle was taken down; and the sons of Gershon and the sons of Merari set forward, bearing the tabernacle."}, {"verse": 18, "start": 184.78, "end": 196.89, "ta": "அதற்குபின்பு ரூபன் சந்ததியாருடைய பாளயத்தின் கொடி அவர்கள் சேனைகளோடே புறப்பட்டது; அவனுடைய சேனைக்குச் சேதேயூரின் குமாரன் எலிசூர் தலைவனாயிருந்தான்.", "en": "And the standard of the camp of Reuben set forward according to their armies: and over his host was Elizur the son of Shedeur."}, {"verse": 19, "start": 196.89, "end": 205.02, "ta": "சிமியோன் சந்ததியாருடைய கோத்திரத்தின் சேனைக்குச் சூரிஷதாயின் குமாரன் செலுூமியேல் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Simeon was Shelumiel the son of Zurishaddai."}, {"verse": 20, "start": 205.02, "end": 212.61, "ta": "காத் சந்ததியாருடைய கோத்திரத்தின் சேனைக்குத் தேகுவேலின் குமாரன் எலியாசாப் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Gad was Eliasaph the son of Deuel."}, {"verse": 21, "start": 212.61, "end": 223.66, "ta": "கோகாத்தியர் பரிசுத்தமானவைகளைச் சுமந்துகொண்டு புறப்பட்டார்கள்; இவர்கள் வந்து சேருமுன் மற்றவர்கள் வாசஸ்தலத்தை ஸ்தாபனம்பண்ணுவார்கள்.", "en": "And the Kohathites set forward, bearing the sanctuary: and the other did set up the tabernacle against they came."}, {"verse": 22, "start": 223.66, "end": 236.62, "ta": "அதற்குப்பின்பு, எப்பிராயீம் சந்ததியாருடைய பாளயத்தின் கொடி அவர்கள் சேனைகளோடே புறப்பட்டது; அவனுடைய சேனைக்கு அம்மியூதின் குமாரன் எலிஷாமா தலைவனாயிருந்தான்.", "en": "And the standard of the camp of the children of Ephraim set forward according to their armies: and over his host was Elishama the son of Ammihud."}, {"verse": 23, "start": 236.62, "end": 244.28, "ta": "மனாசே சந்ததியாருடைய கோத்திரத்தின் சேனைக்குப் பெதாசூரின் குமாரன் கமாலியேல் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Manasseh was Gamaliel the son of Pedahzur."}, {"verse": 24, "start": 244.28, "end": 252.11, "ta": "பென்யமீன் சந்ததியாருடைய கோத்திரத்தின் சேனைக்குக் கீதெயோனின் குமாரன் அபீதான் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Benjamin was Abidan the son of Gideoni."}, {"verse": 25, "start": 252.11, "end": 266.91, "ta": "அதற்குப்பின்பு, தாண் சந்ததியாருடைய பாளயத்தின் கொடி சகல பாளயங்களுக்கும் பின்னாக அவர்கள் சேனைகளோடே புறப்பட்டது; அவனுடைய சேனைக்கு அம்மிஷதாயின் குமாரன் அகியேசேர் தலைவனாயிருந்தான்.", "en": "And the standard of the camp of the children of Dan set forward, which was the rereward of all the camps throughout their hosts: and over his host was Ahiezer the son of Ammishaddai."}, {"verse": 26, "start": 266.91, "end": 274.27, "ta": "ஆசேர் சந்ததியாருடைய கோத்திரத்தின் சேனைக்கு ஓகிரானின் குமாரன் பாகியேல் தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Asher was Pagiel the son of Ocran."}, {"verse": 27, "start": 274.27, "end": 281.32, "ta": "நப்தலி சந்ததியாருடைய கோத்திரத்தின் சேனைக்கு ஏனானின் குமாரன் அகீரா தலைவனாயிருந்தான்.", "en": "And over the host of the tribe of the children of Naphtali was Ahira the son of Enan."}, {"verse": 28, "start": 281.32, "end": 289.68, "ta": "இஸ்ரவேல் புத்திரர் புறப்பட்டபோது, இவ்விதமாய்த் தங்கள் தங்கள் சேனைகளின்படியே பிரயாணம்பண்ணினார்கள்.", "en": "Thus were the journeyings of the children of Israel according to their armies, when they set forward."}, {"verse": 29, "start": 289.68, "end": 312.61, "ta": "அப்பொழுது மோசே தன் மாமனாகிய ரெகுவேல் என்னும் மீதியானனுடைய குமாரனான ஓபாவை நோக்கி: உங்களுக்குத் தருவேன் என்று கர்த்தர் சொன்ன ஸ்தலத்துக்கு நாங்கள் பிரயாணம்போகிறோம்; நீயும் எங்களோடேகூட வா, உனக்கு நன்மைசெய்வோம்; கர்த்தர் இஸ்ரவேலுக்கு நல்ல வாக்குத்தத்தம் பண்ணியிருக்கிறார் என்றான்.", "en": "And Moses said unto Hobab, the son of Raguel the Midianite, Moses’ father in law, We are journeying unto the place of which the LORD said, I will give it you: come thou with us, and we will do thee good: for the LORD hath spoken good concerning Israel."}, {"verse": 30, "start": 312.61, "end": 320.89, "ta": "அதற்கு அவன்: நான் வரக் கூடாது; என் தேசத்துக்கும் என் இனத்தாரிடத்துக்கும் போகவேண்டும் என்றான்.", "en": "And he said unto him, I will not go; but I will depart to mine own land, and to my kindred."}, {"verse": 31, "start": 320.89, "end": 334.08, "ta": "அப்பொழுது மோசே: நீ எங்களைவிட்டுப் போகவேண்டாம்; வனாந்தரத்திலே நாங்கள் பாளயமிறங்கும் இடங்களை நீ அறிந்திருக்கிறபடியினால், எங்களுக்குக் கண்களைப்போல இருப்பாய்.", "en": "And he said, Leave us not, I pray thee; forasmuch as thou knowest how we are to encamp in the wilderness, and thou mayest be to us instead of eyes."}, {"verse": 32, "start": 334.08, "end": 342.98, "ta": "நீ எங்களோடேகூட வந்தால், கர்த்தர் எங்களுக்குச் செய்தருளும் நன்மையின்படியே உனக்கும் நன்மைசெய்வோம் என்றான்.", "en": "And it shall be, if thou go with us, yea, it shall be, that what goodness the LORD shall do unto us, the same will we do unto thee."}, {"verse": 33, "start": 342.98, "end": 359.93, "ta": "அவர்கள் கர்த்தருடைய பர்வதத்தைவிட்டு, மூன்றுநாள் பிரயாணம்போனார்கள்; மூன்றுநாள் பிரயாணத்திலும் கர்த்தருடைய உடன்படிக்கைப்பெட்டி அவர்களுக்கு இளைப்பாறும் ஸ்தலத்தைத் தேடிக் காட்டும்படிக்கு அவர்கள்முன் சென்றது.", "en": "And they departed from the mount of the LORD three days’ journey: and the ark of the covenant of the LORD went before them in the three days’ journey, to search out a resting place for them."}, {"verse": 34, "start": 359.93, "end": 368.21, "ta": "அவர்கள் பாளயத்திலிருந்து பிரயாணம்போகிறபோது, கர்த்தருடைய மேகம் பகலில் அவர்கள்மேல் தங்கியிருந்தது.", "en": "And the cloud of the LORD was upon them by day, when they went out of the camp."}, {"verse": 35, "start": 368.21, "end": 382.85, "ta": "பெட்டியானது புறப்படும்போது, மோசே: கர்த்தாவே, எழுந்தருளும், உம்முடைய சத்துருக்கள் சிதறடிக்கப்படுவார்களாக; உம்மைப் பகைக்கிறவர்கள் உமக்கு முன்பாக ஓடிப்போவார்களாக என்பான்.", "en": "And it came to pass, when the ark set forward, that Moses said, Rise up, LORD , and let thine enemies be scattered; and let them that hate thee flee before thee."}, {"verse": 36, "start": 382.85, "end": 391.06, "ta": "அது தங்கும்போது: கர்த்தாவே, அநேக ஆயிரவர்களாகிய இஸ்ரவேலரிடத்தில் திரும்புவீராக என்று சொல்லுவான்.", "en": "And when it rested, he said, Return, O LORD , unto the many thousands of Israel."}]}, "11": {"chapter": 11, "duration": 463.1, "audio_url": "audio_ot/OT04_11.mp3", "total_verses": 35, "verses": [{"verse": 1, "start": 3.8, "end": 23.41, "ta": "பின்பு, ஜனங்கள் முறையிட்டுக்கொண்டிருந்தார்கள்; அது கர்த்தருடைய செவிகளில் பொல்லாப்பாயிருந்தது; கர்த்தர் அதைக் கேட்டபோது, அவருடைய கோபம் மூண்டது; கர்த்தருடைய அக்கினி அவர்களுக்குள்ளே பற்றியெரிந்து, பாளயத்தின் கடைசியிலிருந்த சிலரைப் பட்சித்தது.", "en": "And when the people complained, it displeased the LORD : and the LORD heard it; and his anger was kindled; and the fire of the LORD burnt among them, and consumed them that were in the uttermost parts of the camp."}, {"verse": 2, "start": 23.41, "end": 33.61, "ta": "அப்பொழுது ஜனங்கள் மோசேயை நோக்கிக் கூப்பிட்டார்கள்; மோசே கர்த்தரை நோக்கி விண்ணப்பம்பண்ணினான்; உடனே அக்கினி அவிந்துபோயிற்று.", "en": "And the people cried unto Moses; and when Moses prayed unto the LORD , the fire was quenched."}, {"verse": 3, "start": 33.61, "end": 41.31, "ta": "கர்த்தருடைய அக்கினி அவர்களுக்குள்ளே பற்றியெரிந்ததினால், அவ்விடத்துக்குத் தபேரா என்று பேரிட்டான்.", "en": "And he called the name of the place Taberah: because the fire of the LORD burnt among them."}, {"verse": 4, "start": 41.31, "end": 54.44, "ta": "பின்பு அவர்களுக்குள் இருந்த பலஜாதியான அந்நிய ஜனங்கள் மிகுந்த இச்சையுள்ளவர்களானார்கள்; இஸ்ரவேல் புத்திரரும் திரும்ப அழுது, நமக்கு இறைச்சியைப் புசிக்கக்கொடுப்பவர் யார்?", "en": "And the mixt multitude that was among them fell a lusting: and the children of Israel also wept again, and said, Who shall give us flesh to eat?"}, {"verse": 5, "start": 54.44, "end": 67.99, "ta": "நாம் எகிப்திலே கிரயமில்லாமல் சாப்பிட்ட மச்சங்களையும், வெள்ளரிக்காய்களையும், கொம்மட்டிக்காய்களையும், கீரைகளையும், வெண்காயங்களையும், வெள்ளைப்பூண்டுகளையும் நினைக்கிறோம்.", "en": "We remember the fish, which we did eat in Egypt freely; the cucumbers, and the melons, and the leeks, and the onions, and the garlick:"}, {"verse": 6, "start": 67.99, "end": 78.26, "ta": "இப்பொழுது நம்முடைய உள்ளம் வாடிப்போகிறது; இந்த மன்னாவைத்தவிர, நம்முடைய கண்களுக்கு முன்பாக வேறொன்றும் இல்லையே என்று சொன்னார்கள்.", "en": "But now our soul is dried away: there is nothing at all, beside this manna, before our eyes."}, {"verse": 7, "start": 78.26, "end": 84.82, "ta": "அந்த மன்னா கொத்துமல்லி விதையம்மாத்திரமும், அதின் நிறம் முத்துப்போலவும் இருந்தது.", "en": "And the manna was as coriander seed, and the colour thereof as the colour of bdellium."}, {"verse": 8, "start": 84.82, "end": 100.44, "ta": "ஜனங்கள் போய் அதைப் பொறுக்கிக்கொண்டுவந்து, ஏந்திரங்களில் அரைத்தாவது உரல்களில் இடித்தாவது, பானைகளில் சமைப்பார்கள்; அதை அப்பங்களுமாகச் சுடுவார்கள்; அதின் ருசி புது ஒலிவ எண்ணெயின் ருசிபோலிருந்தது.", "en": "And the people went about, and gathered it , and ground it in mills, or beat it in a mortar, and baked it in pans, and made cakes of it: and the taste of it was as the taste of fresh oil."}, {"verse": 9, "start": 100.44, "end": 106.0, "ta": "இரவிலே பாளயத்தின்மேல் பனிபெய்யும்போது, மன்னாவும் அதின்மேல் விழும்.", "en": "And when the dew fell upon the camp in the night, the manna fell upon it."}, {"verse": 10, "start": 106.0, "end": 120.05, "ta": "அந்தந்த வம்சங்களைச் சேர்ந்த ஜனங்கள் தங்கள் தங்கள் கூடாரவாசலில் நின்று அழுகிறதை மோசே கேட்டான்; கர்த்தருக்கு மிகவும் கோபம் மூண்டது; மோசேயின் பார்வைக்கும் அது பொல்லாப்பாயிருந்தது.", "en": "Then Moses heard the people weep throughout their families, every man in the door of his tent: and the anger of the LORD was kindled greatly; Moses also was displeased."}, {"verse": 11, "start": 120.05, "end": 135.38, "ta": "அப்பொழுது மோசே கர்த்தரை நோக்கி: நீர் இந்த ஜனங்கள் எல்லாருடைய பாரத்தையும் என்மேல் சுமத்தினதினால், உமது அடியானுக்கு உபத்திரவம் வரப்பண்ணினதென்ன? உம்முடைய கண்களில் எனக்குக் கிருபை கிடையாதே போனதென்ன?", "en": "And Moses said unto the LORD , Wherefore hast thou afflicted thy servant? and wherefore have I not found favour in thy sight, that thou layest the burden of all this people upon me?"}, {"verse": 12, "start": 135.38, "end": 154.64, "ta": "இவர்களுடைய பிதாக்களுக்கு நான் ஆணையிட்டுக்கொடுத்த தேசத்துக்கு நீ இவர்களை முலையுண்கிற பாலகனைத் தகப்பன் சுமந்துகொண்டுபோவதுபோல, உன் மார்பிலே அணைத்துக்கொண்டுபோ என்று நீர் என்னோடே சொல்லும்படி இந்த ஜனங்களையெல்லாம் கர்ப்பந்தரித்தேனோ? இவர்களைப் பெற்றது நானோ?", "en": "Have I conceived all this people? have I begotten them, that thou shouldest say unto me, Carry them in thy bosom, as a nursing father beareth the sucking child, unto the land which thou swarest unto their fathers?"}, {"verse": 13, "start": 154.64, "end": 165.41, "ta": "இந்த ஜனங்கள் எல்லாருக்கும் கொடுக்கிறதற்கு எனக்கு இறைச்சி எங்கேயிருந்து வரும்? எனக்கு இறைச்சிகொடு என்று என்னைப் பார்த்து அழுகிறார்களே.", "en": "Whence should I have flesh to give unto all this people? for they weep unto me, saying, Give us flesh, that we may eat."}, {"verse": 14, "start": 165.41, "end": 172.97, "ta": "இந்த ஜனங்களெல்லாரையும் நான் ஒருவனாய்த் தாங்கக் கூடாது; எனக்கு இது மிஞ்சின பாரமாயிருக்கிறது.", "en": "I am not able to bear all this people alone, because it is too heavy for me."}, {"verse": 15, "start": 172.97, "end": 185.81, "ta": "உம்முடைய கண்களிலே எனக்குக் கிருபை கிடைத்ததானால், இப்படி எனக்குச் செய்யாமல், என் உபத்திரவத்தை நான் காணாதபடிக்கு இப்பொழுதே என்னைக் கொன்றுபோடும் என்று வேண்டிக்கொண்டான்.", "en": "And if thou deal thus with me, kill me, I pray thee, out of hand, if I have found favour in thy sight; and let me not see my wretchedness."}, {"verse": 16, "start": 185.81, "end": 203.35, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி: இஸ்ரவேல் ஜனங்களுக்கு மூப்பரும் தலைவருமானவர்கள் இன்னார் என்று நீ அறிந்திருக்கிறாயே, அந்த மூப்பரில் எழுபதுபேரைக் கூட்டி, அவர்களை ஆசரிப்புக் கூடாரத்தினிடத்தில் அங்கே உன்னோடேகூட வந்து நிற்கும்படி செய்.", "en": "And the LORD said unto Moses, Gather unto me seventy men of the elders of Israel, whom thou knowest to be the elders of the people, and officers over them; and bring them unto the tabernacle of the congregation, that they may stand there with thee."}, {"verse": 17, "start": 203.35, "end": 217.62, "ta": "அப்பொழுது நான் இறங்கிவந்து அங்கே உன்னோடே பேசி, நீ ஒருவன் மாத்திரம் ஜனங்களின் பாரத்தைச் சுமக்காமல், உன்னோடேகூட அவர்களும் அதைச் சுமப்பதற்காக உன்மேல் இருக்கிற ஆவியை அவர்கள்மேலும் வைப்பேன்.", "en": "And I will come down and talk with thee there: and I will take of the spirit which is upon thee, and will put it upon them; and they shall bear the burden of the people with thee, that thou bear it not thyself alone."}, {"verse": 18, "start": 217.62, "end": 242.08, "ta": "நீ ஜனங்களை நோக்கி: நாளைக்காக உங்களைப் பரிசுத்தம்பண்ணுங்கள்; நீங்கள் இறைச்சி சாப்பிடுவீர்கள்; எங்களுக்கு இறைச்சி சாப்பிடக் கொடுப்பவர் யார் என்றும், எகிப்திலே எங்களுக்குச் செளக்கியமாயிருந்தது என்றும், கர்த்தருடைய செவிகள் கேட்க அழுதீர்களே; ஆகையால், நீங்கள் சாப்பிடும்படி கர்த்தர் உங்களுக்கு இறைச்சி கொடுப்பார்.", "en": "And say thou unto the people, Sanctify yourselves against to morrow, and ye shall eat flesh: for ye have wept in the ears of the LORD , saying, Who shall give us flesh to eat? for it was well with us in Egypt: therefore the LORD will give you flesh, and ye shall eat."}, {"verse": 19, "start": 242.08, "end": 248.43, "ta": "நீங்கள் ஒருநாள், இரண்டுநாள், ஐந்துநாள், பத்துநாள், இருபதுநாள் மாத்திரமல்ல,", "en": "Ye shall not eat one day, nor two days, nor five days, neither ten days, nor twenty days;"}, {"verse": 20, "start": 248.43, "end": 268.18, "ta": "ஒரு மாதம்வரைக்கும் புசிப்பீர்கள், அது உங்கள் மூக்காலே புறப்பட்டு, உங்களுக்குத் தெவிட்டிப்போகுமட்டும் புசிப்பீர்கள், உங்களுக்குள்ளே இருக்கிற கர்த்தரை அசட்டைபண்ணி, நாங்கள் ஏன் எகிப்திலிருந்து புறப்பட்டோம் என்று அவருக்கு முன்பாக அழுதீர்களே என்று சொல் என்றார்.", "en": "But even a whole month, until it come out at your nostrils, and it be loathsome unto you: because that ye have despised the LORD which is among you, and have wept before him, saying, Why came we forth out of Egypt?"}, {"verse": 21, "start": 268.18, "end": 278.67, "ta": "அதற்கு மோசே: என்னோடிருக்கிற காலாட்கள் ஆறுலட்சம்பேர்; ஒருமாதம் முழுவதும் புசிக்கும்படி அவர்களுக்கு இறைச்சி கொடுப்பேன் என்று சொன்னீரே.", "en": "And Moses said, The people, among whom I am , are six hundred thousand footmen; and thou hast said, I will give them flesh, that they may eat a whole month."}, {"verse": 22, "start": 278.67, "end": 290.36, "ta": "ஆடுமாடுகளை அவர்களுக்காக அடித்தாலும் அவர்களுக்குப் போதுமா? சமுத்திரத்து மச்சங்களையெல்லாம் அவர்களுக்காகச் சேர்த்தாலும் அவர்களுக்குப் போதுமா என்றான்.", "en": "Shall the flocks and the herds be slain for them, to suffice them? or shall all the fish of the sea be gathered together for them, to suffice them?"}, {"verse": 23, "start": 290.36, "end": 302.49, "ta": "அதற்குக் கர்த்தர் மோசேயை நோக்கி: கர்த்தருடய கை குறுகியிருக்கிறதோ? என் வார்த்தையின்படி நடக்குமோ? நடவாதோ என்று, நீ இப்பொழுது காண்பாய் என்றார்.", "en": "And the LORD said unto Moses, Is the LORD’s hand waxed short? thou shalt see now whether my word shall come to pass unto thee or not."}, {"verse": 24, "start": 302.49, "end": 315.04, "ta": "அப்பொழுது மோசே புறப்பட்டு, கர்த்தருடைய வார்த்தைகளை ஜனங்களுக்குச் சொல்லி, ஜனங்களின் மூப்பரில் எழுபதுபேரைக் கூட்டி, கூடாரத்தைச் சுற்றிலும் அவர்களை நிறுத்தினான்.", "en": "And Moses went out, and told the people the words of the LORD , and gathered the seventy men of the elders of the people, and set them round about the tabernacle."}, {"verse": 25, "start": 315.04, "end": 331.37, "ta": "கர்த்தர் மேகத்தில் இறங்கி, அவனோடே பேசி, அவன்மேலிருந்த ஆவியை மூப்பராகிய அந்த எழுபதுபேர்மேலும் வைத்தார் அந்த ஆவி அவர்கள்மேல் வந்து தங்கினமாத்திரத்தில் தீர்க்கதரிசனஞ் சொன்னார்கள்; சொல்லி, பின்பு ஓய்ந்தார்கள்.", "en": "And the LORD came down in a cloud, and spake unto him, and took of the spirit that was upon him, and gave it unto the seventy elders: and it came to pass, that , when the spirit rested upon them, they prophesied, and did not cease."}, {"verse": 26, "start": 331.37, "end": 352.2, "ta": "அப்பொழுது இரண்டுபேர் பாளயத்தில் இருந்துவிட்டார்கள்; ஒருவன்பேர் எல்தாத், மற்றவன்பேர் மேதாத்; அவர்களும் பேர்வழியில் எழுதப்பட்டிருந்தும், கூடாரத்துக்குப் போகப் புறப்படாதிருந்தார்கள்; அவர்கள்மேலும் ஆவி வந்து தங்கினதினால், பாளயத்தில் தீர்க்கதரிசனஞ் சொன்னார்கள்.", "en": "But there remained two of the men in the camp, the name of the one was Eldad, and the name of the other Medad: and the spirit rested upon them; and they were of them that were written, but went not out unto the tabernacle: and they prophesied in the camp."}, {"verse": 27, "start": 352.2, "end": 361.4, "ta": "ஒரு பிள்ளையாண்டான் ஓடிவந்து, எல்தாதும் மேதாதும் பாளயத்தில் தீர்க்கதரிசனஞ் சொல்லுகிறார்கள் என்று மோசேக்கு அறிவித்தான்.", "en": "And there ran a young man, and told Moses, and said, Eldad and Medad do prophesy in the camp."}, {"verse": 28, "start": 361.4, "end": 373.81, "ta": "உடனே மோசேயினிடத்தில் உள்ள வாலிபரில் ஒருவனும் அவனுடைய ஊழியக்காரனும் நூனின் குமாரனுமாகிய யோசுவா பிரதியுத்தரமாக: என் ஆண்டவனாகிய மோசேயே, அவர்களைத் தடைபண்ணும் என்றான்.", "en": "And Joshua the son of Nun, the servant of Moses, one of his young men, answered and said, My lord Moses, forbid them."}, {"verse": 29, "start": 373.81, "end": 388.78, "ta": "அதற்கு மோசே: நீ எனக்காக வைராக்கியம் காண்பிக்கிறாயோ? கர்த்தருடைய ஜனங்கள் எல்லாரும் தீர்க்கதரிசனஞ் சொல்லத்தக்கதாக, கர்த்தர் தம்முடைய ஆவியை அவர்கள்மேல் இறங்கப்பண்ணினால் நலமாயிருக்குமே என்றான்.", "en": "And Moses said unto him, Enviest thou for my sake? would God that all the LORD’s people were prophets, and that the LORD would put his spirit upon them!"}, {"verse": 30, "start": 388.78, "end": 394.56, "ta": "பின்பு, மோசேயும் இஸ்ரவேலின் மூப்பரும் பாளயத்திலே வந்து சேர்ந்தார்கள்.", "en": "And Moses gat him into the camp, he and the elders of Israel."}, {"verse": 31, "start": 394.56, "end": 414.67, "ta": "அப்பொழுது கர்த்தரிடத்திலிருந்து புறப்பட்ட ஒரு காற்று சமுத்திரத்திலிருந்து காடைகளை அடித்துக்கொண்டுவந்து, பாளயத்திலும் பாளயத்தைச் சுற்றிலும், இந்தப்பக்கம் ஒருநாள் பிரயாணமட்டும் அந்தப்பக்கம் ஒருநாள் பிரயாணமட்டும், தரையின்மேல் இரண்டுமுழ உயரம் விழுந்துகிடக்கச் செய்தது.", "en": "And there went forth a wind from the LORD , and brought quails from the sea, and let them fall by the camp, as it were a day’s journey on this side, and as it were a day’s journey on the other side, round about the camp, and as it were two cubits high upon the face of the earth."}, {"verse": 32, "start": 414.67, "end": 432.29, "ta": "அப்பொழுது ஜனங்கள் எழும்பி அன்று பகல்முழுவதும், இராமுழுவதும், மறுநாள் முழுவதும் காடைகளைச் சேர்த்தார்கள்; கொஞ்சமாய்ச் சேர்த்தவன் பத்து ஓமர் அளவு சேர்த்தான்; அவைகளைப் பாளயத்தைச் சுற்றிலும் தங்களுக்காகக் குவித்துவைத்தார்கள்.", "en": "And the people stood up all that day, and all that night, and all the next day, and they gathered the quails: he that gathered least gathered ten homers: and they spread them all abroad for themselves round about the camp."}, {"verse": 33, "start": 432.29, "end": 444.63, "ta": "தங்கள் பற்கள் நடுவே இருக்கும் இறைச்சியை அவர்கள் மென்று தின்னுமுன்னே கர்த்தருடைய கோபம் ஜனங்களுக்குள்ளே மூண்டது; கர்த்தர் ஜனங்களை மகா பெரிய வாதையால் வாதித்தார்.", "en": "And while the flesh was yet between their teeth, ere it was chewed, the wrath of the LORD was kindled against the people, and the LORD smote the people with a very great plague."}, {"verse": 34, "start": 444.63, "end": 452.47, "ta": "இச்சித்த ஜனங்களை அங்கே அடக்கம்பண்ணினதினால், அந்த ஸ்தலத்துக்குக் கிப்ரோத் அத்தாவா என்று பேரிட்டான்.", "en": "And he called the name of that place Kibroth-hattaavah: because there they buried the people that lusted."}, {"verse": 35, "start": 452.47, "end": 461.6, "ta": "பின்பு, ஜனங்கள் கிப்ரோத் அத்தாவா என்னும் இடத்தை விட்டு, ஆஸரோத்துக்குப் பிரயாணம்பண்ணி, ஆஸரோத்திலே தங்கினார்கள்.", "en": "And the people journeyed from Kibroth-hattaavah unto Hazeroth; and abode at Hazeroth."}]}, "12": {"chapter": 12, "duration": 177.91, "audio_url": "audio_ot/OT04_12.mp3", "total_verses": 16, "verses": [{"verse": 1, "start": 3.8, "end": 16.64, "ta": "எத்தியோப்பியா தேசத்து ஸ்திரீயை மோசே விவாகம்பண்ணியிருந்தபடியினால், மிரியாமும் ஆரோனும் அவன் விவாகம்பண்ணின எத்தியோப்பியா தேசத்து ஸ்திரீயினிமித்தம் அவனுக்கு விரோதமாய்ப் பேசி:", "en": "And Miriam and Aaron spake against Moses because of the Ethiopian woman whom he had married: for he had married an Ethiopian woman."}, {"verse": 2, "start": 16.64, "end": 26.81, "ta": "கர்த்தர் மோசேயைக் கொண்டுமாத்திரம் பேசினாரோ, எங்களைக்கொண்டும் அவர் பேசினதில்லையோ என்றார்கள். கர்த்தர் அதைக் கேட்டார்.", "en": "And they said, Hath the LORD indeed spoken only by Moses? hath he not spoken also by us? And the LORD heard it ."}, {"verse": 3, "start": 26.81, "end": 32.9, "ta": "மோசேயானவன் பூமியிலுள்ள சகல மனிதரிலும் மிகுந்த சாந்தகுணமுள்ளவனாயிருந்தான்.", "en": "(Now the man Moses was very meek, above all the men which were upon the face of the earth.)"}, {"verse": 4, "start": 32.9, "end": 45.97, "ta": "சடுதியிலே கர்த்தர் மோசேயையும் ஆரோனையும் மிரியாமையும் நோக்கி: நீங்கள் மூன்றுபேரும் ஆசரிப்புக் கூடாரத்துக்குப் புறப்பட்டுவாருங்கள் என்றார்; மூன்றுபேரும் போனார்கள்.", "en": "And the LORD spake suddenly unto Moses, and unto Aaron, and unto Miriam, Come out ye three unto the tabernacle of the congregation. And they three came out."}, {"verse": 5, "start": 45.97, "end": 55.99, "ta": "கர்த்தர் மேகத்தூணில் இறங்கி, கூடாரவாசலிலே நின்று, ஆரோனையும் மிரியாமையும் கூப்பிட்டார்; அவர்கள் இருவரும் போனார்கள்.", "en": "And the LORD came down in the pillar of the cloud, and stood in the door of the tabernacle, and called Aaron and Miriam: and they both came forth."}, {"verse": 6, "start": 55.99, "end": 70.99, "ta": "அப்பொழுது அவர்: என் வார்த்தைகளைக் கேளுங்கள்; உங்களுக்குள்ளே ஒருவன் தீர்க்கதரிசியாயிருந்தால், கர்த்தராகிய நான் தரிசனத்தில் என்னை அவனுக்கு வெளிப்படுத்தி, சொப்பனத்தில் அவனோடே பேசுவேன்.", "en": "And he said, Hear now my words: If there be a prophet among you, I the LORD will make myself known unto him in a vision, and will speak unto him in a dream."}, {"verse": 7, "start": 70.99, "end": 77.97, "ta": "என் தாசனாகிய மோசேயோ அப்படிப்பட்டவன் அல்ல, என் வீட்டில் எங்கும் அவன் உண்மையுள்ளவன்.", "en": "My servant Moses is not so, who is faithful in all mine house."}, {"verse": 8, "start": 77.97, "end": 96.08, "ta": "நான் அவனுடன் மறைபொருளாக அல்ல, முகமுகமாகவும் பிரத்தியட்சமாகவும் பேசுகிறேன்; அவன் கர்த்தரின் சாயலைக் காண்கிறான்; இப்படியிருக்க, நீங்கள் என் தாசனாகிய மோசேக்கு விரோதமாய்ப் பேச, உங்களுக்குப் பயமில்லாமற்போனதென்ன என்றார்.", "en": "With him will I speak mouth to mouth, even apparently, and not in dark speeches; and the similitude of the LORD shall he behold: wherefore then were ye not afraid to speak against my servant Moses?"}, {"verse": 9, "start": 96.08, "end": 101.43, "ta": "கர்த்தருடைய கோபம் அவர்கள்மேல் மூண்டது; அவர் போய்விட்டார்.", "en": "And the anger of the LORD was kindled against them; and he departed."}, {"verse": 10, "start": 101.43, "end": 114.94, "ta": "மேகம் கூடாரத்தை விட்டு நீங்கிப்போயிற்று; மிரியாம் உறைந்த மழையின் வெண்மைபோன்ற குஷ்டரோகியானாள்; ஆரோன் மிரியாமைப் பார்த்தபோது, அவள் குஷ்டரோகியாயிருக்கக் கண்டான்.", "en": "And the cloud departed from off the tabernacle; and, behold, Miriam became leprous, white as snow: and Aaron looked upon Miriam, and, behold, she was leprous."}, {"verse": 11, "start": 114.94, "end": 124.74, "ta": "அப்பொழுது ஆரோன் மோசேயை நோக்கி: ஆ, என் ஆண்டவனே, நாங்கள் புத்தியீனமாய்ச் செய்த இந்தப் பாவத்தை எங்கள்மேல் சுமத்தாதிரும்.", "en": "And Aaron said unto Moses, Alas, my lord, I beseech thee, lay not the sin upon us, wherein we have done foolishly, and wherein we have sinned."}, {"verse": 12, "start": 124.74, "end": 132.9, "ta": "தன் தாயின் கர்ப்பத்தில் பாதி மாம்சம் அழுகிச் செத்துவிழுந்த பிள்ளையைப்போல அவள் ஆகாதிருப்பாளாக என்றான்.", "en": "Let her not be as one dead, of whom the flesh is half consumed when he cometh out of his mother’s womb."}, {"verse": 13, "start": 132.9, "end": 139.66, "ta": "அப்பொழுது மோசே கர்த்தரை நோக்கி: என் தேவனே, அவளைக் குணமாக்கும் என்று கெஞ்சினான்.", "en": "And Moses cried unto the LORD , saying, Heal her now, O God, I beseech thee."}, {"verse": 14, "start": 139.66, "end": 157.18, "ta": "கர்த்தர் மோசேயை நோக்கி: அவள் தகப்பன் அவள் முகத்திலே காறித் துப்பினதுண்டானால், அவள் ஏழுநாள் வெட்கப்படவேண்டாமோ, அதுபோலவே அவள் ஏழுநாள் பாளயத்துக்குப் புறம்பே விலக்கப்பட்டிருந்து, பின்பு சேர்த்துக்கொள்ளப்படக்கடவள் என்றார்.", "en": "And the LORD said unto Moses, If her father had but spit in her face, should she not be ashamed seven days? let her be shut out from the camp seven days, and after that let her be received in again ."}, {"verse": 15, "start": 157.18, "end": 168.99, "ta": "அப்படியே மிரியாம் ஏழுநாள் பாளயத்துக்குப் புறம்பே விலக்கப்பட்டிருந்தாள்; மிரியாம் சேர்த்துக்கொள்ளப்படுமட்டும் ஜனங்கள் பிரயாணம்பண்ணாதிருந்தார்கள்.", "en": "And Miriam was shut out from the camp seven days: and the people journeyed not till Miriam was brought in again ."}, {"verse": 16, "start": 168.99, "end": 176.41, "ta": "பின்பு, ஜனங்கள் ஆஸரோத்திலிருந்து புறப்பட்டு, பாரான் வனாந்தரத்திலே பாளயமிறங்கினார்கள்.", "en": "And afterward the people removed from Hazeroth, and pitched in the wilderness of Paran."}]}, "13": {"chapter": 13, "duration": 321.87, "audio_url": "audio_ot/OT04_13.mp3", "total_verses": 33, "verses": [{"verse": 1, "start": 3.8, "end": 5.48, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.48, "end": 19.98, "ta": "நான் இஸ்ரவேல் புத்திரருக்குக் கொடுக்கும் கானான்தேசத்தைச் சுற்றிப்பார்ப்பதற்கு நீ மனிதரை அனுப்பு; ஒவ்வொரு பிதாக்களின் கோத்திரத்திலும் ஒவ்வொரு பிரபுவாகிய புருஷனை அனுப்பவேண்டும் என்றார்.", "en": "Send thou men, that they may search the land of Canaan, which I give unto the children of Israel: of every tribe of their fathers shall ye send a man, every one a ruler among them."}, {"verse": 3, "start": 19.98, "end": 30.67, "ta": "மோசே கர்த்தருடைய வாக்கின்படியே அவர்களைப் பாரான் வனாந்தரத்தலிருந்து அனுப்பினான்; அந்த மனிதர் யாவரும் இஸ்ரவேல் புத்திரரின் தலைவர்கள்.", "en": "And Moses by the commandment of the LORD sent them from the wilderness of Paran: all those men were heads of the children of Israel."}, {"verse": 4, "start": 30.67, "end": 36.38, "ta": "அவர்களுடைய நாமங்களாவன: ரூபன் கோத்திரத்தில் சக்கூரின் குமாரன் சம்முவா.", "en": "And these were their names: of the tribe of Reuben, Shammua the son of Zaccur."}, {"verse": 5, "start": 36.38, "end": 40.55, "ta": "சிமியோன் கோத்திரத்தில் ஓரியின் குமாரன் சாப்பாத்.", "en": "Of the tribe of Simeon, Shaphat the son of Hori."}, {"verse": 6, "start": 40.55, "end": 44.73, "ta": "யூதா கோத்திரத்தில் எப்புன்னேயின் குமாரன் காலேப்.", "en": "Of the tribe of Judah, Caleb the son of Jephunneh."}, {"verse": 7, "start": 44.73, "end": 48.9, "ta": "இசக்கார் கோத்திரத்தில் யோசேப்பின் குமாரன் ஈகால்.", "en": "Of the tribe of Issachar, Igal the son of Joseph."}, {"verse": 8, "start": 48.9, "end": 53.0, "ta": "எப்பிராயீம் கோத்திரத்தில் நூனின் குமாரன் ஓசேயா.", "en": "Of the tribe of Ephraim, Oshea the son of Nun."}, {"verse": 9, "start": 53.0, "end": 57.32, "ta": "பென்யமீன் கோத்திரத்தில் ரப்பூவின் குமாரன் பல்த்தி.", "en": "Of the tribe of Benjamin, Palti the son of Raphu."}, {"verse": 10, "start": 57.32, "end": 61.56, "ta": "செபுலோன் கோத்திரத்தில் சோதியின் குமாரன் காதியேல்.", "en": "Of the tribe of Zebulun, Gaddiel the son of Sodi."}, {"verse": 11, "start": 61.56, "end": 67.57, "ta": "யோசேப்பின் கோத்திரத்தைச் சேர்ந்த மனாசே கோத்திரத்தில் சூசின் குமாரன் காதி.", "en": "Of the tribe of Joseph, namely , of the tribe of Manasseh, Gaddi the son of Susi."}, {"verse": 12, "start": 67.57, "end": 71.81, "ta": "தாண் கோத்திரத்தில் கெமல்லியின் குமாரன் அம்மியேல்.", "en": "Of the tribe of Dan, Ammiel the son of Gemalli."}, {"verse": 13, "start": 71.81, "end": 75.99, "ta": "ஆசேர் கோத்திரத்தில் மிகாவேலின் குமாரன் சேத்தூர்.", "en": "Of the tribe of Asher, Sethur the son of Michael."}, {"verse": 14, "start": 75.99, "end": 80.09, "ta": "நப்தலி கோத்திரத்தில் ஒப்பேசியின் குமாரன் நாகபி.", "en": "Of the tribe of Naphtali, Nahbi the son of Vophsi."}, {"verse": 15, "start": 80.09, "end": 83.89, "ta": "காத் கோத்திரத்தில் மாகியின் குமாரன் கூவேல்.", "en": "Of the tribe of Gad, Geuel the son of Machi."}, {"verse": 16, "start": 83.89, "end": 95.02, "ta": "தேசத்தைச் சுற்றிப்பார்க்கும்படி மோசே அனுப்பின மனிதரின் நாமங்கள் இவைகளே; நூனின் குமாரனாகிய ஓசேயாவுக்கு யோசுவா என்று மோசே பேரிட்டிருந்தான்.", "en": "These are the names of the men which Moses sent to spy out the land. And Moses called Oshea the son of Nun Jehoshua."}, {"verse": 17, "start": 95.02, "end": 104.76, "ta": "அவர்களை மோசே கானான்தேசத்தைச் சுற்றிப்பார்க்கும்படி அனுப்புகையில், அவர்களை நோக்கி: நீங்கள் இப்படித் தெற்கே போய், மலையில் ஏறி,", "en": "And Moses sent them to spy out the land of Canaan, and said unto them, Get you up this way southward, and go up into the mountain:"}, {"verse": 18, "start": 104.76, "end": 112.96, "ta": "தேசம் எப்படிப்பட்டதென்றும், குடியிருக்கிற ஜனங்கள் பலவான்களோ பலவீனர்களோ, கொஞ்சம்பேரோ அநேகம்பேரோ என்றும்,", "en": "And see the land, what it is; and the people that dwelleth therein, whether they be strong or weak, few or many;"}, {"verse": 19, "start": 112.96, "end": 128.04, "ta": "அவர்கள் குடியிருக்கிற தேசம் எப்படிப்பட்டது, அது நல்லதோ கெட்டதோ என்றும், அவர்கள் பட்டணங்கள் எப்படிப்பட்டதென்றும், அவர்கள் கூடாரங்களில் குடியிருக்கிறவர்களோ கோட்டைகளில் குடியிருக்கிறவர்களோ என்றும்,", "en": "And what the land is that they dwell in, whether it be good or bad; and what cities they be that they dwell in, whether in tents, or in strong holds;"}, {"verse": 20, "start": 128.04, "end": 147.96, "ta": "நிலம் எப்படிப்பட்டது, அது வளப்பமானதோ இளப்பமானதோ என்றும், அதில் விருட்சங்கள் உண்டோ இல்லையோ என்றும் பாருங்கள், தைரியங்கொண்டிருந்து, தேசத்தின் கனிகளிலே சிலவற்றைக் கொண்டுவாருங்கள் என்றான். அக்காலம் திராட்சச்செடி முதற்பழம் பழுக்கிற காலமாயிருந்தது.", "en": "And what the land is , whether it be fat or lean, whether there be wood therein, or not. And be ye of good courage, and bring of the fruit of the land. Now the time was the time of the firstripe grapes."}, {"verse": 21, "start": 147.96, "end": 156.74, "ta": "அவர்கள் போய், சீன் வனாந்தரந்தொடங்கி, ஆமாத்துக்குப் போகிற வழியாகிய ரேகொப்மட்டும், தேசத்தைச் சுற்றிப்பார்த்து,", "en": "So they went up, and searched the land from the wilderness of Zin unto Rehob, as men come to Hamath."}, {"verse": 22, "start": 156.74, "end": 172.04, "ta": "தெற்கேயும் சென்று, எபிரோன்மட்டும் போனார்கள்; அங்கே ஏனாக்கின் குமாரராகிய அகீமானும் சேசாயும் தல்மாயும் இருந்தார்கள். எபிரோன் எகிப்திலுள்ள சோவானுக்கு ஏழுவருஷத்திற்குமுன்னே கட்டப்பட்டது.", "en": "And they ascended by the south, and came unto Hebron; where Ahiman, Sheshai, and Talmai, the children of Anak, were . (Now Hebron was built seven years before Zoan in Egypt.)"}, {"verse": 23, "start": 172.04, "end": 190.13, "ta": "பின்பு, அவர்கள் எஸ்கோல் பள்ளத்தாக்குமட்டும் போய், அங்கே ஒரே குலையுள்ள திராட்சக்கொடியை அறுத்தார்கள்; அதை ஒரு தடியிலே இரண்டுபேர் கட்டித் தூக்கிக்கொண்டுவந்தார்கள்: மாதளம்பழங்களிலும் அத்திப்பழங்களிலும் சிலவற்றைக் கொண்டுவந்தார்கள்.", "en": "And they came unto the brook of Eshcol, and cut down from thence a branch with one cluster of grapes, and they bare it between two upon a staff; and they brought of the pomegranates, and of the figs."}, {"verse": 24, "start": 190.13, "end": 198.4, "ta": "இஸ்ரவேல் புத்திரர் அங்கே அறுத்த திராட்சக்குலையினிமித்தம், அவ்விடம் எஸ்கோல் பள்ளத்தாக்கு என்னப்பட்டது.", "en": "The place was called the brook Eshcol, because of the cluster of grapes which the children of Israel cut down from thence."}, {"verse": 25, "start": 198.4, "end": 204.84, "ta": "அவர்கள் தேசத்தைச் சுற்றிப்பார்த்து, நாற்பதுநாள் சென்றபின்பு திரும்பினார்கள்.", "en": "And they returned from searching of the land after forty days."}, {"verse": 26, "start": 204.84, "end": 224.1, "ta": "அவர்கள் பாரான் வனாந்தரத்தில் இருக்கிற காதேசுக்கு வந்து, மோசே ஆரோன் என்பவர்களிடத்திலும் இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரிடத்திலும் சேர்ந்து, அவர்களுக்கும் சபையாரனைவருக்கும் சமாசாரத்தை அறிவித்து, தேசத்தின் கனிகளை அவர்களுக்குக் காண்பித்தார்கள்.", "en": "And they went and came to Moses, and to Aaron, and to all the congregation of the children of Israel, unto the wilderness of Paran, to Kadesh; and brought back word unto them, and unto all the congregation, and shewed them the fruit of the land."}, {"verse": 27, "start": 224.1, "end": 235.15, "ta": "அவர்கள் மோசேயை நோக்கி: நீர் எங்களை அனுப்பின தேசத்துக்கு நாங்கள் போய்வந்தோம்; அது பாலும் தேனும் ஓடுகிற தேசந்தான்; இது அதினுடைய கனி.", "en": "And they told him, and said, We came unto the land whither thou sentest us, and surely it floweth with milk and honey; and this is the fruit of it."}, {"verse": 28, "start": 235.15, "end": 248.33, "ta": "ஆனாலும், அந்த தேசத்திலே குடியிருக்கிற ஜனங்கள் பலவான்கள்; பட்டணங்கள் அரணிப்பானவைகளும் மிகவும் பெரியவைகளுமாய் இருக்கிறது; அங்கே ஏனாக்கின் குமாரரையும் கண்டோம்.", "en": "Nevertheless the people be strong that dwell in the land, and the cities are walled, and very great: and moreover we saw the children of Anak there."}, {"verse": 29, "start": 248.33, "end": 264.66, "ta": "அமலேக்கியர் தென்புறமான தேசத்தில் குடியிருக்கிறார்கள்; ஏத்தியரும், எபூசியரும், எமோரியரும் மலைநாட்டில் குடியிருக்கிறார்கள்; கானானியர் கடல் அருகேயும் யோர்தானண்டையிலும் குடியிருக்கிறார்கள் என்றார்கள்.", "en": "The Amalekites dwell in the land of the south: and the Hittites, and the Jebusites, and the Amorites, dwell in the mountains: and the Canaanites dwell by the sea, and by the coast of Jordan."}, {"verse": 30, "start": 264.66, "end": 276.15, "ta": "அப்பொழுது காலேப் மோசேக்கு முன்பாக ஜனங்களை அமர்த்தி: நாம் உடனே போய் அதைச் சுதந்தரித்துக்கொள்வோம்; நாம் அதை எளிதாய் ஜெயித்துக்கொள்ளலாம் என்றான்.", "en": "And Caleb stilled the people before Moses, and said, Let us go up at once, and possess it; for we are well able to overcome it."}, {"verse": 31, "start": 276.15, "end": 286.55, "ta": "அவனோடேகூடப் போய்வந்த மனிதரோ நாம் போய் அந்த ஜனங்களோடே எதிர்க்க நம்மாலே கூடாது; அவர்கள் நம்மைப்பார்க்கிலும் பலவான்கள் என்றார்கள்.", "en": "But the men that went up with him said, We be not able to go up against the people; for they are stronger than we."}, {"verse": 32, "start": 286.55, "end": 297.23, "ta": "நாங்கள் போய்ச் சுற்றிப் பார்த்துவந்த அந்த தேசம் தன் குடிகளைப் பட்சிக்கிற தேசம் நாங்கள் அதிலே கண்ட ஜனங்கள் எல்லாரும் மிகவும் பெரிய ஆட்கள்.", "en": "And they brought up an evil report of the land which they had searched unto the children of Israel, saying, The land, through which we have gone to search it, is a land that eateth up the inhabitants thereof; and all the people that we saw in it are men of a great stature."}, {"verse": 33, "start": 297.23, "end": 320.37, "ta": "அங்கே இராட்சதப் பிறவியான ஏனாக்கின் குமாரராகிய இராட்சதரையும் கண்டோம்; நாங்கள் எங்கள் பார்வைக்கு வெட்டுக்கிளிகளைப்போல் இருந்தோம், அவர்கள் பார்வைக்கும் அப்படியே இருந்தோம் என்று சொல்லி, இப்படி இஸ்ரவேல் புத்திரருக்குள்ளே தாங்கள் சுற்றிப்பார்த்துவந்த தேசத்தைக்குறித்து துர்ச்செய்தி பரம்பச்செய்தார்கள்.", "en": "And there we saw the giants, the sons of Anak, which come of the giants: and we were in our own sight as grasshoppers, and so we were in their sight."}]}, "14": {"chapter": 14, "duration": 528.47, "audio_url": "audio_ot/OT04_14.mp3", "total_verses": 45, "verses": [{"verse": 1, "start": 3.8, "end": 12.52, "ta": "அப்பொழுது சபையார் எல்லாரும் கூக்குரலிட்டுப் புலம்பினார்கள்; ஜனங்கள் அன்று இராமுழுதும் அழுதுகொண்டிருந்தார்கள்.", "en": "And all the congregation lifted up their voice, and cried; and the people wept that night."}, {"verse": 2, "start": 12.52, "end": 28.91, "ta": "இஸ்ரவேல் புத்திரர் எல்லாரும் மோசேக்கும் ஆரோனுக்கும் விரோதமாக முறுமுறுத்தார்கள். சபையார் எல்லாரும் அவர்களை நோக்கி: எகிப்துதேசத்திலே செத்துப்போனோமானால் நலமாயிருக்கும்; இந்த வனாந்தரத்திலே நாங்கள் செத்தாலும் நலம்.", "en": "And all the children of Israel murmured against Moses and against Aaron: and the whole congregation said unto them, Would God that we had died in the land of Egypt! or would God we had died in this wilderness!"}, {"verse": 3, "start": 28.91, "end": 46.0, "ta": "நாங்கள் பட்டயத்தால் மடியும்படிக்கும், எங்கள் பெண்ஜாதிகளும் பிள்ளைகளையும் கொள்ளையாகும்படிக்கும், கர்த்தர் எங்களை இந்த தேசத்துக்குக் கொண்டுவந்தது என்ன? எகிப்துக்குத் திரும்பிப்போகிறதே எங்களுக்கு உத்தமம் அல்லவோ என்றார்கள்.", "en": "And wherefore hath the LORD brought us unto this land, to fall by the sword, that our wives and our children should be a prey? were it not better for us to return into Egypt?"}, {"verse": 4, "start": 46.0, "end": 55.91, "ta": "பின்பு அவர்கள்: நாம் ஒரு தலைவனை ஏற்படுத்திக்கொண்டு எகிப்துக்குத் திரும்பிப்போவோம் வாருங்கள் என்று ஒருவரோடொருவர் சொல்லிக்கொண்டார்கள்.", "en": "And they said one to another, Let us make a captain, and let us return into Egypt."}, {"verse": 5, "start": 55.91, "end": 65.13, "ta": "அப்பொழுது மோசேயும் ஆரோனும் இஸ்ரவேல் புத்திரரின் சபையாராகிய எல்லாக் கூட்டத்தாருக்கு முன்பாகவும் முகங்குப்புற விழுந்தார்கள்.", "en": "Then Moses and Aaron fell on their faces before all the assembly of the congregation of the children of Israel."}, {"verse": 6, "start": 65.13, "end": 75.39, "ta": "தேசத்தைச் சுற்றிப்பார்த்தவர்களில் நூனின் குமாரனாகிய யோசுவாவும், எப்புன்னேயின் குமாரனாகிய காலேபும், தங்கள் வஸ்திரங்களைக் கிழித்துக்கொண்டு,", "en": "And Joshua the son of Nun, and Caleb the son of Jephunneh, which were of them that searched the land, rent their clothes:"}, {"verse": 7, "start": 75.39, "end": 83.41, "ta": "இஸ்ரவேல் புத்திரரின் சமஸ்த சபையையும் நோக்கி: நாங்கள் போய்ச் சுற்றிப்பார்த்து சோதித்த தேசம் மகா நல்லதேசம்.", "en": "And they spake unto all the company of the children of Israel, saying, The land, which we passed through to search it, is an exceeding good land."}, {"verse": 8, "start": 83.41, "end": 93.54, "ta": "கர்த்தர் நம்மேல் பிரியமாயிருந்தால், அந்தத் தேசத்திலே நம்மைக் கொண்டுபோய், பாலும் தேனும் ஓடுகிற அந்தத் தேசத்தை நமக்குக் கொடுப்பார்.", "en": "If the LORD delight in us, then he will bring us into this land, and give it us; a land which floweth with milk and honey."}, {"verse": 9, "start": 93.54, "end": 115.06, "ta": "கர்த்தருக்கு விரோதமாகமாத்திரம் கலகம்பபண்ணாதிருங்கள்; அந்த தேசத்தின் ஜனங்களுக்கு நீங்கள் பயப்படவேண்டியதில்லை; அவர்கள் நமக்கு இரையாவார்கள்; அவர்களைக் காத்த நிழல் அவர்களை விட்டு விலகிப்போயிற்று; கர்த்தர் நம்மோடே இருக்கிறார்; அவர்களுக்குப் பயப்படவேண்டியதில்லை என்றார்கள்.", "en": "Only rebel not ye against the LORD , neither fear ye the people of the land; for they are bread for us: their defence is departed from them, and the LORD is with us: fear them not."}, {"verse": 10, "start": 115.06, "end": 128.56, "ta": "அப்பொழுது அவர்கள்மேல் கல்லெறியவேண்டும் என்று சபையார் எல்லாரும் சொன்னார்கள்; உடனே கர்த்தருடைய மகிமை ஆசரிப்புக் கூடாரத்தில் இஸ்ரவேல் புத்திரர் எல்லாருக்கும் முன்பாகக் காணப்பட்டது.", "en": "But all the congregation bade stone them with stones. And the glory of the LORD appeared in the tabernacle of the congregation before all the children of Israel."}, {"verse": 11, "start": 128.56, "end": 143.47, "ta": "கர்த்தர் மோசேயை நோக்கி: எதுவரைக்கும் இந்த ஜனங்கள் எனக்குக் கோபம் உண்டாக்குவார்கள்? தங்களுக்குள்ளே நான் காட்டின சகல அடையாளங்களையும் அவர்கள் கண்டும், எதுவரைக்கும் என்னை விசுவாசியாதிருப்பார்கள்?", "en": "And the LORD said unto Moses, How long will this people provoke me? and how long will it be ere they believe me, for all the signs which I have shewed among them?"}, {"verse": 12, "start": 143.47, "end": 155.29, "ta": "நான் அவர்களைக் கொள்ளை நோயினால் வாதித்து, சுதந்தரத்துக்குப் புறம்பாக்கிப்போட்டு, அவர்களைப்பார்க்கிலும் உன்னைப் பெரிதும் பலத்ததுமான ஜாதியாக்குவேன் என்றார்.", "en": "I will smite them with the pestilence, and disinherit them, and will make of thee a greater nation and mightier than they."}, {"verse": 13, "start": 155.29, "end": 165.13, "ta": "மோசே கர்த்தரை நோக்கி: எகிப்தியர் இதைக் கேட்பார்கள்; அவர்கள் நடுவிலிருந்து உம்முடைய வல்லமையினாலே இந்த ஜனங்களைக் கொண்டுவந்தீரே.", "en": "And Moses said unto the LORD , Then the Egyptians shall hear it , (for thou broughtest up this people in thy might from among them;)"}, {"verse": 14, "start": 165.13, "end": 187.71, "ta": "கர்த்தராகிய நீர் இந்த ஜனங்களின் நடுவே இருக்கிறதையும், கர்த்தராகிய நீர் முகமுகமாய்த் தரிசனமாகிறதையும், உம்முடைய மேகம் இவர்கள்மேல் நிற்கிறதையும், பகலில் மேகத்தூணிலும், இரவில் அக்கினித்தூணிலும், நீர் இவர்களுக்கு முன் செல்லுகிறதையும் கேட்டிருக்கிறார்கள், இந்த தேசத்தின் குடிகளுக்கும் சொல்லுவார்கள்.", "en": "And they will tell it to the inhabitants of this land: for they have heard that thou LORD art among this people, that thou LORD art seen face to face, and that thy cloud standeth over them, and that thou goest before them, by day time in a pillar of a cloud, and in a pillar of fire by night."}, {"verse": 15, "start": 187.71, "end": 196.85, "ta": "ஒரே மனிதனைக் கொல்லுகிறதுபோல இந்த ஜனங்களையெல்லாம் நீர் கொல்வீரானால், அப்பொழுது உம்முடைய கீர்த்தியைக் கேட்டிருக்கும் புறஜாதியார்:", "en": "Now if thou shalt kill all this people as one man, then the nations which have heard the fame of thee will speak, saying,"}, {"verse": 16, "start": 196.85, "end": 209.3, "ta": "கர்த்தர் அந்த ஜனங்களுக்குக் கொடுப்போம் என்று ஆணையிட்டிருந்த தேசத்திலே அவர்களைக் கொண்டுபோய் விடக் கூடாதேபோனபடியினால், அவர்களை வனாந்தரத்திலே கொன்றுபோட்டார் என்பார்களே.", "en": "Because the LORD was not able to bring this people into the land which he sware unto them, therefore he hath slain them in the wilderness."}, {"verse": 17, "start": 209.3, "end": 230.82, "ta": "ஆகையால் கர்த்தர் நீடிய சாந்தமும் மிகுந்த கிருபையுமுள்ளவர் என்றும், அக்கிரமத்தையும் மீறுதலையும் மன்னிக்கிறவரென்றும், குற்றமுள்ளவர்களைக் குற்றமற்றவர்களாக விடாமல், பிதாக்கள் செய்த அக்கிரமத்தைப் பிள்ளைகளிடத்தில் மூன்றாம் நான்காம் தலைமுறைமட்டும் விசாரிக்கிறவர் என்றும், நீர் சொல்லியிருக்கிறபடியே,", "en": "And now, I beseech thee, let the power of my Lord be great, according as thou hast spoken, saying,"}, {"verse": 18, "start": 230.82, "end": 234.48, "ta": "என் ஆண்டவருடைய வல்லமை பெரிதாய் விளங்குவதாக.", "en": "The LORD is longsuffering, and of great mercy, forgiving iniquity and transgression, and by no means clearing the guilty , visiting the iniquity of the fathers upon the children unto the third and fourth generation ."}, {"verse": 19, "start": 234.48, "end": 247.91, "ta": "உமது கிருபையினுடைய மகத்துவத்தின்படியேயும், எகிப்தை விட்டதுமுதல் இந்நாள்வரைக்கும் இந்த ஜனங்களுக்கு மன்னித்துவந்ததின்படியேயும், இந்த ஜனங்களின் அக்கிரமத்தை மன்னித்தருளும் என்றான்.", "en": "Pardon, I beseech thee, the iniquity of this people according unto the greatness of thy mercy, and as thou hast forgiven this people, from Egypt even until now."}, {"verse": 20, "start": 247.91, "end": 252.34, "ta": "அப்பொழுது கர்த்தர்: உன் வார்த்தையின்படியே மன்னித்தேன்.", "en": "And the LORD said, I have pardoned according to thy word:"}, {"verse": 21, "start": 252.34, "end": 259.72, "ta": "பூமியெல்லாம் கர்த்தருடைய மகிமையினால் நிறைந்திருக்கும் என்று என்னுடைய ஜீவனைக்கொண்டு சொல்லுகிறேன்.", "en": "But as truly as I live, all the earth shall be filled with the glory of the LORD ."}, {"verse": 22, "start": 259.72, "end": 273.37, "ta": "என் மகிமையையும், நான் எகிப்திலும் வனாந்தரத்திலும் செய்த என் அடையாளங்களையும் கண்டிருந்தும், என் சத்தத்துக்குச் செவிகொடாமல், இதனோடே பத்துமுறை என்னைப் பரீட்சை பார்த்த மனிதரில் ஒருவரும்,", "en": "Because all those men which have seen my glory, and my miracles, which I did in Egypt and in the wilderness, and have tempted me now these ten times, and have not hearkened to my voice;"}, {"verse": 23, "start": 273.37, "end": 283.92, "ta": "அவர்கள் பிதாக்களுக்கு நான் ஆணையிட்டுக்கொடுத்த தேசத்தைக் காணமாட்டார்கள்; எனக்குக் கோபம் உண்டாக்கினவர்களில் ஒருவரும் அதைக்காணமாட்டார்கள்.", "en": "Surely they shall not see the land which I sware unto their fathers, neither shall any of them that provoked me see it:"}, {"verse": 24, "start": 283.92, "end": 299.81, "ta": "என்னுடைய தாசனாகிய காலேப் வேறே ஆவியை உடையவனாயிருக்கிறபடியினாலும், உத்தமமாய் என்னைப் பின்பற்றிவந்தபடியினாலும், அவன் போய்வந்ததேசத்திலே அவனைச் சேரப்பண்ணுவேன்; அவன் சந்ததியார் அதைச் சுதந்தரித்துக்கொள்ளுவார்கள்.", "en": "But my servant Caleb, because he had another spirit with him, and hath followed me fully, him will I bring into the land whereinto he went; and his seed shall possess it."}, {"verse": 25, "start": 299.81, "end": 313.03, "ta": "அமலேக்கியரும் கானானியரும் பள்ளத்தாக்கிலே குடியிருக்கிறபடியினால், நாளைக்கு நீங்கள் திரும்பி சிவந்த சமுத்திரத்துக்குப் போகிற வழியாய் வனாந்தரத்துக்குப் பிரயாணம்பண்ணுங்கள் என்றார்.", "en": "(Now the Amalekites and the Canaanites dwelt in the valley.) To morrow turn you, and get you into the wilderness by the way of the Red sea."}, {"verse": 26, "start": 313.03, "end": 316.27, "ta": "பின்னும் கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 27, "start": 316.27, "end": 327.52, "ta": "எனக்கு விரோதமாய் முறுமுறுக்கிற இந்தப் பொல்லாத சபையாரை எதுவரைக்கும் பொறுப்பேன்? இஸ்ரவேல் புத்திரர் எனக்கு விரோதமாய் முறுமுறுக்கிறதைக் கேட்டேன்.", "en": "How long shall I bear with this evil congregation, which murmur against me? I have heard the murmurings of the children of Israel, which they murmur against me."}, {"verse": 28, "start": 327.52, "end": 340.18, "ta": "நீ அவர்களோடே சொல்லவேண்டியது என்னவென்றால்: நீங்கள் என் செவிகள் கேட்கச் சொன்னபிரகாரம் உங்களுக்குச் செய்வேன் என்பதை என் ஜீவனைக்கொண்டு சொல்லுகிறேன் என்று கர்த்தர் உரைக்கிறார்.", "en": "Say unto them, As truly as I live, saith the LORD , as ye have spoken in mine ears, so will I do to you:"}, {"verse": 29, "start": 340.18, "end": 356.64, "ta": "இந்த வனாந்தரத்தில் உங்கள் பிரேதங்கள் விழும்; உங்களில் இருபது வயதுமுதல் அதற்கு மேற்பட்டவர்களாக எண்ணப்பட்டு, உங்கள் தொகைக்கு உட்பட்டவர்களும் எனக்கு விரோதமாய் முறுமுறுத்திருக்கிறவர்களுமாகிய அனைவரின் பிரேதங்களும் விழும்.", "en": "Your carcases shall fall in this wilderness; and all that were numbered of you, according to your whole number, from twenty years old and upward, which have murmured against me,"}, {"verse": 30, "start": 356.64, "end": 369.44, "ta": "எப்புன்னேயின் குமாரன் காலேபும், நூனின் குமாரன் யோசுவாவும் தவிர, மற்றவர்களாகிய நீங்கள் நான் உங்களைக் குடியேற்றுவேன் என்று ஆணையிட்டுக்கொடுத்த தேசத்தில் பிரவேசிப்பதில்லை.", "en": "Doubtless ye shall not come into the land, concerning which I sware to make you dwell therein, save Caleb the son of Jephunneh, and Joshua the son of Nun."}, {"verse": 31, "start": 369.44, "end": 380.55, "ta": "கொள்ளையாவார்கள் என்று நீங்கள் சொன்ன உங்கள் குழந்தைகளையோ நான் அதில் பிரவேசிக்கச் செய்வேன்; நீங்கள் அசட்டைப்பண்ணின தேசத்தை அவர்கள் கண்டறிவார்கள்.", "en": "But your little ones, which ye said should be a prey, them will I bring in, and they shall know the land which ye have despised."}, {"verse": 32, "start": 380.55, "end": 384.27, "ta": "உங்கள் பிரேதங்களோ இந்த வனாந்தரத்திலே விழும்.", "en": "But as for you, your carcases, they shall fall in this wilderness."}, {"verse": 33, "start": 384.27, "end": 395.1, "ta": "அவைகள் வனாந்தரத்திலே விழுந்து தீருமட்டும், உங்கள் பிள்ளைகள் நாற்பதுவருஷம் வனாந்தரத்திலே திரிந்து, நீங்கள் சோரம்போன பாதகத்தைச் சுமப்பார்கள்.", "en": "And your children shall wander in the wilderness forty years, and bear your whoredoms, until your carcases be wasted in the wilderness."}, {"verse": 34, "start": 395.1, "end": 409.8, "ta": "நீங்கள் தேசத்தை சுற்றிப்பார்த்த நாற்பதுநாள் இலக்கத்தின்படியே, ஒவ்வொரு நாள் ஒவ்வொரு வருஷமாக, நீங்கள் நாற்பது வருஷம் உங்கள் அக்கிரமங்களைச் சுமந்து, என் உடன்படிக்கைக்கு வந்த மாறுதலை உணருவீர்கள்.", "en": "After the number of the days in which ye searched the land, even forty days, each day for a year, shall ye bear your iniquities, even forty years, and ye shall know my breach of promise."}, {"verse": 35, "start": 409.8, "end": 424.5, "ta": "கர்த்தராகிய நான் இதைச் சொன்னேன்; எனக்கு விரோதமாய்க் கூட்டங்கூடின இந்தப் பொல்லாத சபையார் யாவருக்கும் இப்படியே செய்வேன்; இந்த வனாந்தரத்திலே அழிவார்கள், இங்கே சாவார்கள் என்று சொல் என்றார்.", "en": "I the LORD have said, I will surely do it unto all this evil congregation, that are gathered together against me: in this wilderness they shall be consumed, and there they shall die."}, {"verse": 36, "start": 424.5, "end": 433.64, "ta": "அந்த தேசத்தைச் சோதித்துப்பார்க்கும்படி மோசேயால் அனுப்பப்பட்டுத் திரும்பி, அந்த தேசத்தைக்குறித்துத் துர்ச்செய்தி கொண்டுவந்து,", "en": "And the men, which Moses sent to search the land, who returned, and made all the congregation to murmur against him, by bringing up a slander upon the land,"}, {"verse": 37, "start": 433.64, "end": 445.04, "ta": "சபையார் எல்லாரும் அவனுக்கு விரோதமாய் முறுமுறுக்கும்படி அந்தத் துர்ச்செய்தியைச் சொன்னவர்களாகிய அந்த மனிதர் கர்த்தருடைய சந்நிதியில் வாதையினால் செத்தார்கள்.", "en": "Even those men that did bring up the evil report upon the land, died by the plague before the LORD ."}, {"verse": 38, "start": 445.04, "end": 455.52, "ta": "தேசத்தைச் சுற்றிப்பார்க்கப்போன அந்த மனிதரில் நூனின் குமாரனாகிய யோசுவாவும், எப்புன்னேயின் குமாரனாகிய காலேபும்மாத்திரம் உயிரோடிருந்தார்கள்.", "en": "But Joshua the son of Nun, and Caleb the son of Jephunneh, which were of the men that went to search the land, lived still ."}, {"verse": 39, "start": 455.52, "end": 463.04, "ta": "மோசே இந்த வார்த்தைகளை இஸ்ரவேல் புத்திரர் அனைவரோடும் சொன்னபோது, ஜனங்கள் மிகவும் துக்கித்தார்கள்.", "en": "And Moses told these sayings unto all the children of Israel: and the people mourned greatly."}, {"verse": 40, "start": 463.04, "end": 475.14, "ta": "அதிகாலமே அவர்கள் எழுந்திருந்து: நாங்கள் பாவஞ்செய்தோம், கர்த்தர் வாக்குத்தத்தம்பண்ணின இடத்துக்கு நாங்கள் போவோம் என்று சொல்லி மலையின் உச்சியில் ஏறத்துணிந்தார்கள்.", "en": "And they rose up early in the morning, and gat them up into the top of the mountain, saying, Lo, we be here , and will go up unto the place which the LORD hath promised: for we have sinned."}, {"verse": 41, "start": 475.14, "end": 483.16, "ta": "மோசே அவர்களை நோக்கி: நீங்கள் இப்படி கர்த்தரின் கட்டளையை மீறுகிறதென்ன? அது உங்களுக்கு வாய்க்காது.", "en": "And Moses said, Wherefore now do ye transgress the commandment of the LORD ? but it shall not prosper."}, {"verse": 42, "start": 483.16, "end": 492.37, "ta": "நீங்கள் உங்கள் சத்துருக்களுக்கு முன்பாக முறிய அடிக்கப்படாதபடிக்கு ஏறிப்போகாதிருங்கள்; கர்த்தர் உங்கள் நடுவில் இரார்.", "en": "Go not up, for the LORD is not among you; that ye be not smitten before your enemies."}, {"verse": 43, "start": 492.37, "end": 506.65, "ta": "அமலேக்கியரும் கானானியரும் அங்கே உங்களுக்குமுன்னே இருக்கிறார்கள்; பட்டயத்தினால் விழுவீர்கள்; நீங்கள் கர்த்தரை விட்டுப் பின்வாங்கினபடியால், கர்த்தர் உங்களோடே இருக்கமாட்டார் என்றான்.", "en": "For the Amalekites and the Canaanites are there before you, and ye shall fall by the sword: because ye are turned away from the LORD , therefore the LORD will not be with you."}, {"verse": 44, "start": 506.65, "end": 516.84, "ta": "ஆனாலும் அவர்கள் மலையின் உச்சியில் ஏறத் துணிந்தார்கள்; கர்த்தருடைய உடன்படிக்கையின் பெட்டியும் மோசேயும் பாளயத்தை விட்டுப் போகவில்லை.", "en": "But they presumed to go up unto the hill top: nevertheless the ark of the covenant of the LORD , and Moses, departed not out of the camp."}, {"verse": 45, "start": 516.84, "end": 526.97, "ta": "அப்பொழுது அமலேக்கியரும் கானானியரும் அந்த மலையிலே இருந்து இறங்கிவந்து, அவர்களை முறிய அடித்து, அவர்களை ஓர்மாமட்டும் துரத்தினார்கள்.", "en": "Then the Amalekites came down, and the Canaanites which dwelt in that hill, and smote them, and discomfited them, even unto Hormah."}]}, "15": {"chapter": 15, "duration": 459.15, "audio_url": "audio_ot/OT04_15.mp3", "total_verses": 41, "verses": [{"verse": 1, "start": 3.8, "end": 5.49, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.49, "end": 16.49, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நீங்கள் குடியிருக்கும்படி நான் உங்களுக்குக் கொடுக்கும் தேசத்தில் நீங்கள் போய்ச் சேர்ந்தபின்பு,", "en": "Speak unto the children of Israel, and say unto them, When ye be come into the land of your habitations, which I give unto you,"}, {"verse": 3, "start": 16.49, "end": 34.54, "ta": "விசேஷித்த பொருத்தனையாயாவது, உற்சாக பலியாயாவது, உங்கள் பண்டிகைகளில் செலுத்தும் பலியாயாவது, கர்த்தருக்கு மாடுகளிலாகிலும் ஆடுகளிலாகிலும் சர்வாங்க தகனபலியையாவது மற்ற யாதொரு பலியையாவது கர்த்தருக்குச் சுகந்த வாசனையான தகனமாகப் பலியிடும்போது,", "en": "And will make an offering by fire unto the LORD , a burnt offering, or a sacrifice in performing a vow, or in a freewill offering, or in your solemn feasts, to make a sweet savour unto the LORD , of the herd, or of the flock:"}, {"verse": 4, "start": 34.54, "end": 51.77, "ta": "தன் படைப்பைக் கர்த்தருக்குச் செலுத்துகிறவன் சர்வாங்க தகனபலிக்காகிலும் மற்றப் பலிக்காகிலும் ஒரு ஆட்டுக்குட்டியுடனே, ஒரு மரக்காலிலே பத்தில் ஒரு பங்கும் காற்படி எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவின் போஜனபலியைச் செலுத்தக்கடவன்.", "en": "Then shall he that offereth his offering unto the LORD bring a meat offering of a tenth deal of flour mingled with the fourth part of an hin of oil."}, {"verse": 5, "start": 51.77, "end": 56.18, "ta": "பானபலியாக காற்படி திராட்சரசத்தையும் படைக்கவேண்டும்.", "en": "And the fourth part of an hin of wine for a drink offering shalt thou prepare with the burnt offering or sacrifice, for one lamb."}, {"verse": 6, "start": 56.18, "end": 67.25, "ta": "ஆட்டுக்கடாவாயிருந்ததேயாகில், பத்தில் இரண்டு பங்கானதும், ஒரு படியில் மூன்றில் ஒரு பங்காகிய எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவின் போஜனபலியையும்,", "en": "Or for a ram, thou shalt prepare for a meat offering two tenth deals of flour mingled with the third part of an hin of oil."}, {"verse": 7, "start": 67.25, "end": 76.28, "ta": "பானபலியாக ஒரு படியில் மூன்றிலொரு பங்கு திராட்சரசத்தையும் கர்த்தருக்குச் சுகந்த வாசனையான படைப்பாகப் படைக்கவேண்டும்.", "en": "And for a drink offering thou shalt offer the third part of an hin of wine, for a sweet savour unto the LORD ."}, {"verse": 8, "start": 76.28, "end": 87.72, "ta": "நீ சர்வாங்க தகனபலிக்காகிலும், விசேஷித்த பொருத்தனை பலிக்காகிலும், சமாதான பலிக்காகிலும், ஒரு காளையைக் கர்த்தருக்குச் செலுத்த ஆயத்தப்படுத்தும்போது,", "en": "And when thou preparest a bullock for a burnt offering, or for a sacrifice in performing a vow, or peace offerings unto the LORD :"}, {"verse": 9, "start": 87.72, "end": 95.13, "ta": "அதனோடே பத்தில் மூன்று பங்கானதும், அரைப்படி எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவின் போஜனபலியையும்,", "en": "Then shall he bring with a bullock a meat offering of three tenth deals of flour mingled with half an hin of oil."}, {"verse": 10, "start": 95.13, "end": 103.05, "ta": "பானபலியாக அரைப்படி திராட்ச ரசத்தையும், கர்த்தருக்குச் சுகந்தவாசனையான தகனபலியாகப் படைக்கவேண்டும்.", "en": "And thou shalt bring for a drink offering half an hin of wine, for an offering made by fire, of a sweet savour unto the LORD ."}, {"verse": 11, "start": 103.05, "end": 115.67, "ta": "இந்தப்பிரகாரமாகவே ஒவ்வொரு மாட்டுக்காகிலும், ஆட்டுக்கடாவுக்காகிலும், செம்மறியாட்டுக் குட்டிக்காகிலும், வெள்ளாட்டுக் குட்டிக்காகிலும் செய்து படைக்கவேண்டும்.", "en": "Thus shall it be done for one bullock, or for one ram, or for a lamb, or a kid."}, {"verse": 12, "start": 115.67, "end": 123.37, "ta": "நீங்கள் படைக்கிறவைகளின் இலக்கத்திற்குத்தக்கதாய் ஒவ்வொன்றிற்காகவும் இந்தப்பிரகாரம் செய்யவேண்டும்.", "en": "According to the number that ye shall prepare, so shall ye do to every one according to their number."}, {"verse": 13, "start": 123.37, "end": 132.54, "ta": "சுதேசத்தில் பிறந்தவர்கள் யாவரும் கர்த்தருக்குச் சுகந்த வாசனையான தகனபலியைச் செலுத்தும்போது இவ்விதமாகவே செய்யவேண்டும்.", "en": "All that are born of the country shall do these things after this manner, in offering an offering made by fire, of a sweet savour unto the LORD ."}, {"verse": 14, "start": 132.54, "end": 148.53, "ta": "உங்களிடத்திலே தங்கியிருக்கிற அந்நியனாவது, உங்கள் நடுவிலே உங்கள் தலைமுறைதோறும் குடியிருக்கிறவனாவது, கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி செலுத்தவேண்டுமானால், நீங்கள் செய்கிறபடியே அவனும் செய்யவேண்டும்.", "en": "And if a stranger sojourn with you, or whosoever be among you in your generations, and will offer an offering made by fire, of a sweet savour unto the LORD ; as ye do, so he shall do."}, {"verse": 15, "start": 148.53, "end": 165.04, "ta": "சபையாராகிய உங்களுக்கும் உங்களிடத்தில் தங்குகிற அந்நியனுக்கும் ஒரே பிரமாணம் இருக்கவேண்டும் என்பது உங்கள் தலைமுறைகளில் நித்திய கட்டளையாயிருக்கக்கடவது; கர்த்தருக்கு முன்பாக அந்நியனும் உங்களைப்போலவே இருக்கவேண்டும்.", "en": "One ordinance shall be both for you of the congregation, and also for the stranger that sojourneth with you , an ordinance for ever in your generations: as ye are , so shall the stranger be before the LORD ."}, {"verse": 16, "start": 165.04, "end": 174.06, "ta": "உங்களுக்கும் உங்களிடத்தில் தங்குகிற அந்நியனுக்கும் ஒரே பிரமாணமும் ஒரே முறைமையும் இருக்கக்கடவது என்று சொல் என்றார்.", "en": "One law and one manner shall be for you, and for the stranger that sojourneth with you."}, {"verse": 17, "start": 174.06, "end": 176.41, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 18, "start": 176.41, "end": 184.91, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நான் உங்களை அழைத்துக்கொண்டுபோகிற தேசத்தில் நீங்கள் சேர்ந்து,", "en": "Speak unto the children of Israel, and say unto them, When ye come into the land whither I bring you,"}, {"verse": 19, "start": 184.91, "end": 193.42, "ta": "தேசத்தின் ஆகாரத்தைப் புசிக்கும்போது, கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் காணிக்கையைச் செலுத்தக்கடவீர்கள்.", "en": "Then it shall be, that, when ye eat of the bread of the land, ye shall offer up an heave offering unto the LORD ."}, {"verse": 20, "start": 193.42, "end": 206.92, "ta": "உங்கள் பிசைந்த மாவினால் செய்த முதற்பலனாகிய அதிரசத்தை ஏறெடுத்துப் படைப்பீர்களாக; போரடிக்கிற களத்தின் படைப்பை ஏறெடுத்துப் படைக்கிறதுபோல அதையும் ஏறெடுத்துப் படைக்கவேண்டும்.", "en": "Ye shall offer up a cake of the first of your dough for an heave offering: as ye do the heave offering of the threshingfloor, so shall ye heave it."}, {"verse": 21, "start": 206.92, "end": 216.02, "ta": "இப்படி உங்கள் தலைமுறைதோறும் உங்கள் பிசைந்த மாவின் முதற்பலனிலே கர்த்தருக்குப் படைப்பை ஏறெடுத்துப் படைக்கக்கடவீர்கள்.", "en": "Of the first of your dough ye shall give unto the LORD an heave offering in your generations."}, {"verse": 22, "start": 216.02, "end": 221.23, "ta": "கர்த்தர் மோசேயினிடத்தில் சொன்ன இந்தக் கற்பனைகள் எல்லாவற்றின்படியும்,", "en": "And if ye have erred, and not observed all these commandments, which the LORD hath spoken unto Moses,"}, {"verse": 23, "start": 221.23, "end": 232.01, "ta": "கர்த்தர் மோசேயைக்கொண்டு கட்டளைகொடுத்த நாள்முதற்கொண்டு அவர் உங்களுக்கும் உங்கள் சந்ததிகளுக்கும் நியமித்த எல்லாவற்றின்படியேயும் நீங்கள் செய்யாமல்,", "en": "Even all that the LORD hath commanded you by the hand of Moses, from the day that the LORD commanded Moses , and henceforward among your generations;"}, {"verse": 24, "start": 232.01, "end": 252.99, "ta": "அறியாமல் தவறி நடந்தாலும், சபையாருக்குத் தெரியாமல் யாதொரு தப்பிதம் செய்தாலும், சபையார் எல்லாரும் கர்த்தருக்குச் சுகந்த வாசனையான தகனபலியாக ஒரு காளையையும், முறைமைப்படி அதற்கேற்ற போஜனபலியையும், பானபலியையும், பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தவேண்டும்.", "en": "Then it shall be, if ought be committed by ignorance without the knowledge of the congregation, that all the congregation shall offer one young bullock for a burnt offering, for a sweet savour unto the LORD , with his meat offering, and his drink offering, according to the manner, and one kid of the goats for a sin offering."}, {"verse": 25, "start": 252.99, "end": 274.19, "ta": "அதினால் ஆசாரியன் இஸ்ரவேல் புத்திரரின் சபையனைத்திற்காகவும் பாவநிவிர்த்தி செய்யக்கடவன்; அது அறியாமையில் செய்யப்பட்டபடியாலும், அதினிமித்தம் அவர்கள் கர்த்தருக்குத் தகனபலியையும் பாவநிவாரணபலியையும் கர்த்தருடைய சந்நிதியில் கொண்டுவந்ததினாலும், அது அவர்களுக்கு மன்னிக்கப்படும்.", "en": "And the priest shall make an atonement for all the congregation of the children of Israel, and it shall be forgiven them; for it is ignorance: and they shall bring their offering, a sacrifice made by fire unto the LORD , and their sin offering before the LORD , for their ignorance:"}, {"verse": 26, "start": 274.19, "end": 286.0, "ta": "அது அறியாமையினாலே ஜனங்கள் யாவருக்கும் வந்தபடியால், அது இஸ்ரவேல் புத்திரரின் சபையனைத்திற்கும் அவர்களுக்குள்ளே தங்குகிற அந்நியனுக்கும் மன்னிக்கப்படும்.", "en": "And it shall be forgiven all the congregation of the children of Israel, and the stranger that sojourneth among them; seeing all the people were in ignorance."}, {"verse": 27, "start": 286.0, "end": 293.92, "ta": "ஒருவன் அறியாமையினால் பாவஞ்செய்தானாகில், ஒரு வயதான வெள்ளாட்டைப் பாவநிவாரணபலியாகச் செலுத்தக்கடவன்.", "en": "And if any soul sin through ignorance, then he shall bring a she goat of the first year for a sin offering."}, {"verse": 28, "start": 293.92, "end": 306.9, "ta": "அப்பொழுது அறியாமையினால் பாவஞ்செய்தவனுக்காக ஆசாரியன் பாவநிவிர்த்தி செய்யும்படி கர்த்தருடைய சந்நிதியில் பாவநிவிர்த்தி செய்யக்கடவன், அப்பொழுது அவனுக்கு மன்னிக்கப்படும்.", "en": "And the priest shall make an atonement for the soul that sinneth ignorantly, when he sinneth by ignorance before the LORD , to make an atonement for him; and it shall be forgiven him."}, {"verse": 29, "start": 306.9, "end": 319.01, "ta": "இஸ்ரவேல் புத்திரராகிய உங்களில் பிறந்தவனுக்கும் உங்களுக்குள்ளே தங்கும் அந்நியனுக்கும், அறியாமையினால் பாவஞ்செய்தவனிமித்தம், ஒரே பிரமாணம் இருக்கவேண்டும்.", "en": "Ye shall have one law for him that sinneth through ignorance, both for him that is born among the children of Israel, and for the stranger that sojourneth among them."}, {"verse": 30, "start": 319.01, "end": 334.85, "ta": "அன்றியும் தேசத்திலே பிறந்தவர்களிலாகிலும் அந்நியர்களிலாகிலும், எவனாவது துணிகரமாய் யாதொன்றைச் செய்தால், அவன் கர்த்தரை நிந்திக்கிறான்; அந்த ஆத்துமா தன் ஜனத்தாரில் இராதபடிக்கு அறுப்புண்டுபோகவேண்டும்.", "en": "But the soul that doeth ought presumptuously, whether he be born in the land, or a stranger, the same reproacheth the LORD ; and that soul shall be cut off from among his people."}, {"verse": 31, "start": 334.85, "end": 347.98, "ta": "அவன் கர்த்தரின் வார்த்தையை அசட்டைபண்ணி, அவர் கற்பனையை மீறினபடியால், அந்த ஆத்துமா அறுப்புண்டுபோகவேண்டும்; அவன் அக்கிரமம் அவன்மேல் இருக்கும் என்று சொல் என்றார்.", "en": "Because he hath despised the word of the LORD , and hath broken his commandment, that soul shall utterly be cut off; his iniquity shall be upon him."}, {"verse": 32, "start": 347.98, "end": 357.89, "ta": "இஸ்ரவேல் புத்திரர் வனாந்தரத்தில் இருக்கையில், ஓய்வுநாளில் விறகுகளைப் பொறுக்கிக்கொண்டிருந்த ஒரு மனிதனைக் கண்டுபிடித்தார்கள்.", "en": "And while the children of Israel were in the wilderness, they found a man that gathered sticks upon the sabbath day."}, {"verse": 33, "start": 357.89, "end": 368.74, "ta": "விறகுகளைப் பொறுக்கின அந்த மனிதனைக் கண்டுபிடித்தவர்கள், அவனை மோசே ஆரோன் என்பவர்களிடத்துக்கும் சபையார் அனைவரிடத்துக்கும் கொண்டுவந்தார்கள்.", "en": "And they that found him gathering sticks brought him unto Moses and Aaron, and unto all the congregation."}, {"verse": 34, "start": 368.74, "end": 376.96, "ta": "அவனுக்குச் செய்யவேண்டியது இன்னதென்று தீர்க்கமான உத்தரவு இல்லாதபடியினால், அவனைக் காவலில் வைத்தார்கள்.", "en": "And they put him in ward, because it was not declared what should be done to him."}, {"verse": 35, "start": 376.96, "end": 388.84, "ta": "கர்த்தர் மோசேயை நோக்கி: அந்த மனிதன் நிச்சயமாய்க் கொலைசெய்யப்படவேண்டும்; சபையார் எல்லாரும் அவனைப் பாளயத்திற்குப் புறம்பே கல்லெறியக்கடவர்கள் என்றார்.", "en": "And the LORD said unto Moses, The man shall be surely put to death: all the congregation shall stone him with stones without the camp."}, {"verse": 36, "start": 388.84, "end": 400.51, "ta": "அப்பொழுது சபையார் எல்லாரும் கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, அவனைப் பாளயத்திற்குப் புறம்பே கொண்டுபோய்க் கல்லெறிந்தார்கள்; அவன் செத்தான்.", "en": "And all the congregation brought him without the camp, and stoned him with stones, and he died; as the LORD commanded Moses."}, {"verse": 37, "start": 400.51, "end": 402.85, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 38, "start": 402.85, "end": 417.6, "ta": "நீ இஸ்ரவேல் புத்திரரிடத்தில் பேசி, அவர்கள் தங்கள் தலைமுறைதோறும் தங்கள் வஸ்திரங்களின் ஓரங்களிலே தொங்கல்களை உண்டாக்கி, ஓரத்தின் தொங்கலிலே இளநீலநாடாவைக் கட்டவேண்டுமென்று அவர்களுக்குச் சொல்.", "en": "Speak unto the children of Israel, and bid them that they make them fringes in the borders of their garments throughout their generations, and that they put upon the fringe of the borders a ribband of blue:"}, {"verse": 39, "start": 417.6, "end": 434.62, "ta": "நீங்கள் பின்பற்றிச் சோரம்போகிற உங்கள் இருதயத்துக்கும் உங்கள் கண்களுக்கும் ஏற்க நடவாமல், அதைப்பார்த்து, கர்த்தரின் கற்பனைகளையெல்லாம் நினைத்து அவைகளின்படியே செய்யும்படிக்கு, அது உங்களுக்குத் தொங்கலாய் இருக்கவேண்டும்.", "en": "And it shall be unto you for a fringe, that ye may look upon it, and remember all the commandments of the LORD , and do them; and that ye seek not after your own heart and your own eyes, after which ye use to go a whoring:"}, {"verse": 40, "start": 434.62, "end": 444.96, "ta": "நீங்கள் என் கற்பனைகளையெல்லாம் நினைத்து, அவைகளின்படியே செய்து, உங்கள் தேவனுக்குப் பரிசுத்தராயிருக்கும்படி அதைப் பார்ப்பீர்களாக.", "en": "That ye may remember, and do all my commandments, and be holy unto your God."}, {"verse": 41, "start": 444.96, "end": 457.65, "ta": "நான் உங்களுக்குத் தேவனாயிருக்கும்படி உங்களை எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணின உங்கள் தேவனாகிய கர்த்தர்; நானே உங்கள் தேவனாகிய கர்த்தர் என்று சொல் என்றார்.", "en": "I am the LORD your God, which brought you out of the land of Egypt, to be your God: I am the LORD your God."}]}, "16": {"chapter": 16, "duration": 611.48, "audio_url": "audio_ot/OT04_16.mp3", "total_verses": 50, "verses": [{"verse": 1, "start": 3.8, "end": 17.49, "ta": "லேவிக்குப் பிறந்த கோகாத்தின் குமாரனாகிய இத்சேயாரின் மகன் கோராகு என்பவன் ரூபன் வம்சத்திலுள்ள எலியாபின் குமாரராகிய தாத்தானையும் அபிராமையும் பேலேத்தின் குமாரனாகிய ஓனையும் கூட்டிக்கொண்டு,", "en": "Now Korah, the son of Izhar, the son of Kohath, the son of Levi, and Dathan and Abiram, the sons of Eliab, and On, the son of Peleth, sons of Reuben, took men:"}, {"verse": 2, "start": 17.49, "end": 28.97, "ta": "இஸ்ரவேல் புத்திரரில் சபைக்குத் தலைவர்களும் சங்கத்துக்கு அழைக்கப்பட்டவர்களும் பிரபலமானவர்களுமாகிய இருநூற்று ஐம்பது பேர்களோடும்கூட மோசேக்குமுன்பாக எழும்பி,", "en": "And they rose up before Moses, with certain of the children of Israel, two hundred and fifty princes of the assembly, famous in the congregation, men of renown:"}, {"verse": 3, "start": 28.97, "end": 49.65, "ta": "மோசேக்கும் ஆரோனுக்கும் விரோதமாகக் கூட்டங்கூடி, அவர்களை நோக்கி: நீங்கள் மிஞ்சிப்போகிறீர்கள்; சபையார் எல்லாரும் பரிசுத்தமானவர்கள்; கர்த்தர் அவர்கள் நடுவில் இருக்கிறாரே; இப்படியிருக்க, கர்த்தருடைய சபைக்கு மேலாக உங்களை ஏன் உயர்த்துகிறீர்கள் என்றார்கள்.", "en": "And they gathered themselves together against Moses and against Aaron, and said unto them, Ye take too much upon you, seeing all the congregation are holy, every one of them, and the LORD is among them: wherefore then lift ye up yourselves above the congregation of the LORD ?"}, {"verse": 4, "start": 49.65, "end": 53.92, "ta": "மோசே அதைக் கேட்டபோது, முகங்குப்புற விழுந்தான்.", "en": "And when Moses heard it , he fell upon his face:"}, {"verse": 5, "start": 53.92, "end": 74.96, "ta": "பின்பு அவன் கோராகையும் அவனுடைய எல்லாக் கூட்டத்தையும் நோக்கி: நாளைக்குக் கர்த்தர் தம்முடையவன் இன்னான் என்றும், தம்மண்டையிலே சேரத் தாம் கட்டளையிட்ட பரிசுத்தவான் இன்னான் என்றும் காண்பிப்பார்; அப்பொழுது எவனைத் தெரிந்துகொள்வாரோ, அவனைத் தம்மிடத்தில் சேரக் கட்டளையிடுவார்.", "en": "And he spake unto Korah and unto all his company, saying, Even to morrow the LORD will shew who are his, and who is holy; and will cause him to come near unto him: even him whom he hath chosen will he cause to come near unto him."}, {"verse": 6, "start": 74.96, "end": 83.28, "ta": "ஒன்று செய்யுங்கள்; கோராகே, கோராகின் கூட்டத்தார்களே, நீங்கள் எல்லாரும் தூபகலசங்களை எடுத்துக்கொண்டு,", "en": "This do; Take you censers, Korah, and all his company;"}, {"verse": 7, "start": 83.28, "end": 100.72, "ta": "நாளைக்கு அவைகளில் அக்கினிபோட்டு, கர்த்தருடைய சந்நிதியில் தூபவர்க்கம் இடுங்கள்; அப்பொழுது கர்த்தர் எவனைத் தெரிந்துகொள்வாரோ, அவன் பரிசுத்தவானாயிருப்பான்; லேவியின் புத்திரராகிய நீங்களே மிஞ்சிப்போகிறீர்கள் என்றான்.", "en": "And put fire therein, and put incense in them before the LORD to morrow: and it shall be that the man whom the LORD doth choose, he shall be holy: ye take too much upon you, ye sons of Levi."}, {"verse": 8, "start": 100.72, "end": 105.73, "ta": "பின்னும் மோசே கோராகை நோக்கி: லேவியின் புத்திரரே, கேளுங்கள்;", "en": "And Moses said unto Korah, Hear, I pray you, ye sons of Levi:"}, {"verse": 9, "start": 105.73, "end": 122.65, "ta": "கர்த்தருடைய வாசஸ்தலத்தின் பணிவிடைகளைச் செய்யவும், சபையாரின் முன் நின்று அவர்கள் செய்யவேண்டிய வேலைகளைச் செய்யவும், உங்களைத் தம்மண்டையிலே சேரப்பண்ணும்படி இஸ்ரவேலின் தேவன் இஸ்ரவேல் சபையாரிலிருந்து உங்களைப் பிரித்தெடுத்ததும்,", "en": "Seemeth it but a small thing unto you, that the God of Israel hath separated you from the congregation of Israel, to bring you near to himself to do the service of the tabernacle of the LORD , and to stand before the congregation to minister unto them?"}, {"verse": 10, "start": 122.65, "end": 136.19, "ta": "அவர் உன்னையும் உன்னோடேகூட லேவியின் புத்திரராகிய உன்னுடைய எல்லாச் சகோதரரையும் சேரப்பண்ணினதும், உங்களுக்கு அற்பகாரியமோ? இப்பொழுது ஆசாரியப்பட்டத்தையும் தேடுகிறீர்களோ?", "en": "And he hath brought thee near to him , and all thy brethren the sons of Levi with thee: and seek ye the priesthood also?"}, {"verse": 11, "start": 136.19, "end": 148.78, "ta": "இதற்காக நீயும் உன் கூட்டத்தார் அனைவரும் கர்த்தருக்கு விரோதமாகவே கூட்டங்கூடினீர்கள்; ஆரோனுக்கு விரோதமாக நீங்கள் முறுமுறுக்கிறதற்கு அவன் எம்மாத்திரம் என்றான்.", "en": "For which cause both thou and all thy company are gathered together against the LORD : and what is Aaron, that ye murmur against him?"}, {"verse": 12, "start": 148.78, "end": 157.68, "ta": "பின்பு மோசே எலியாபின் குமாரராகிய தாத்தானையும் அபிராமையும் அழைத்தனுப்பினான். அவர்கள்: நாங்கள் வருகிறதில்லை;", "en": "And Moses sent to call Dathan and Abiram, the sons of Eliab: which said, We will not come up:"}, {"verse": 13, "start": 157.68, "end": 170.56, "ta": "இந்த வனாந்தரத்தில் எங்களைக் கொன்றுபோடும்படி, பாலும் தேனும் ஓடுகிற தேசத்திலிருந்து எங்களைக் கொண்டுவந்தது அற்பகாரியமோ, எங்கள்மேல் துரைத்தனமும் பண்ணப்பார்க்கிறாயோ?", "en": "Is it a small thing that thou hast brought us up out of a land that floweth with milk and honey, to kill us in the wilderness, except thou make thyself altogether a prince over us?"}, {"verse": 14, "start": 170.56, "end": 189.77, "ta": "மேலும் நீ எங்களைப் பாலும் தேனும் ஓடுகிற தேசத்துக்குக் கொண்டுவந்ததும் இல்லை, எங்களுக்கு வயல்களையும் திராட்சத்தோட்டங்களையும் சுதந்தரமாகக் கொடுத்ததும் இல்லை; இந்த மனிதருடைய கண்களைப் பிடுங்கப்பார்க்கிறாயோ? நாங்கள் வருகிறதில்லை என்றார்கள்.", "en": "Moreover thou hast not brought us into a land that floweth with milk and honey, or given us inheritance of fields and vineyards: wilt thou put out the eyes of these men? we will not come up."}, {"verse": 15, "start": 189.77, "end": 209.64, "ta": "அப்பொழுது மோசேக்குக் கடுங்கோபம் மூண்டது; அவன் கர்த்தரை நோக்கி: அவர்கள் செலுத்துங் காணிக்கையை அங்கிகரியாதிருப்பீராக; நான் அவர்களிடத்தில் ஒரு கழுதையை முதலாய் எடுத்துக்கொள்ளவில்லை; அவர்களில் ஒருவனுக்கும் யாதொரு பொல்லாப்பு செய்யவும் இல்லை என்றான்.", "en": "And Moses was very wroth, and said unto the LORD , Respect not thou their offering: I have not taken one ass from them, neither have I hurt one of them."}, {"verse": 16, "start": 209.64, "end": 221.19, "ta": "பின்பு மோசே கோராகை நோக்கி: நீயும் உன் கூட்டத்தார் யாவரும் நாளைக்குக் கர்த்தருடைய சந்நிதியில் வாருங்கள்; நீயும் அவர்களும் ஆரோனும் வந்திருங்கள்.", "en": "And Moses said unto Korah, Be thou and all thy company before the LORD , thou, and they, and Aaron, to morrow:"}, {"verse": 17, "start": 221.19, "end": 241.43, "ta": "உங்களில் ஒவ்வொருவரும் தங்கள் தங்கள் தூபகலசங்களை எடுத்து, அவைகளில் தூபவர்க்கத்தைப் போட்டு, தங்கள் தங்கள் தூபகலசங்களாகிய இருநூற்று ஐம்பது தூபகலசங்களையும் கர்த்தருடைய சந்நிதியில் கொண்டுவரவேண்டும்; நீயும் ஆரோனும் தன் தன் தூபகலசத்தைக் கொண்டுவாருங்கள் என்றான்.", "en": "And take every man his censer, and put incense in them, and bring ye before the LORD every man his censer, two hundred and fifty censers; thou also, and Aaron, each of you his censer."}, {"verse": 18, "start": 241.43, "end": 256.81, "ta": "அப்படியே அவரவர் தங்கள் தங்கள் தூபகலசங்களை எடுத்து, அவைகளில் அக்கினியையும் தூபவர்க்கத்தையும் போட்டு, ஆசரிப்புக் கூடாரவாசலுக்கு முன்பாக வந்து நின்றார்கள்; மோசேயும் ஆரோனும் அங்கே நின்றார்கள்.", "en": "And they took every man his censer, and put fire in them, and laid incense thereon, and stood in the door of the tabernacle of the congregation with Moses and Aaron."}, {"verse": 19, "start": 256.81, "end": 269.39, "ta": "அவர்களுக்கு விரோதமாகக் கோராகு சபையையெல்லாம் ஆசரிப்புக் கூடரவாசலுக்கு முன்பாகக் கூடிவரும்படி செய்தான்; அப்பொழுது கர்த்தருடைய மகிமை சபைக்கெல்லாம் காணப்பட்டது.", "en": "And Korah gathered all the congregation against them unto the door of the tabernacle of the congregation: and the glory of the LORD appeared unto all the congregation."}, {"verse": 20, "start": 269.39, "end": 271.97, "ta": "கர்த்தர் மோசேயோடும் ஆரோனோடும் பேசி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 21, "start": 271.97, "end": 279.26, "ta": "இந்தச் சபையை விட்டுப் பிரிந்துபோங்கள்; ஒரு நிமிஷத்திலே அவர்களை அதமாக்குவேன் என்றார்.", "en": "Separate yourselves from among this congregation, that I may consume them in a moment."}, {"verse": 22, "start": 279.26, "end": 292.72, "ta": "அப்பொழுது அவர்கள் முகங்குப்புறவிழுந்து: தேவனே, மாம்சமான யாவருடைய ஆவிகளுக்கும் தேவனே, ஒரு மனிதன் பாவம் செய்திருக்கச் சபையார் எல்லார்மேலும் கடுங்கோபங்கொள்வீரோ என்றார்கள்.", "en": "And they fell upon their faces, and said, O God, the God of the spirits of all flesh, shall one man sin, and wilt thou be wroth with all the congregation?"}, {"verse": 23, "start": 292.72, "end": 295.15, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 24, "start": 295.15, "end": 303.54, "ta": "கோராகு தாத்தான் அபிராம் என்பவர்களுடைய வாசஸ்தலத்தை விட்டு விலகிப்போங்கள் என்று சபையாருக்குச் சொல் என்றார்.", "en": "Speak unto the congregation, saying, Get you up from about the tabernacle of Korah, Dathan, and Abiram."}, {"verse": 25, "start": 303.54, "end": 313.48, "ta": "உடனே மோசே எழுந்திருந்து, தாத்தான் அபிராம் என்பவர்களிடத்தில் போனான்; இஸ்ரவேலின் மூப்பரும் அவனைப் பின்சென்று போனார்கள்.", "en": "And Moses rose up and went unto Dathan and Abiram; and the elders of Israel followed him."}, {"verse": 26, "start": 313.48, "end": 328.05, "ta": "அவன் சபையாரை நோக்கி இந்தத் துஷ்டமனிதரின் சகல பாவங்களிலும் நீங்கள் வாரிக்கொள்ளப்படாதபடிக்கு, அவர்கள் கூடாரங்களை விட்டு விலகி, அவர்களுக்கு உண்டானவைகளில் ஒன்றையும் தொடாதிருங்கள் என்றான்.", "en": "And he spake unto the congregation, saying, Depart, I pray you, from the tents of these wicked men, and touch nothing of theirs, lest ye be consumed in all their sins."}, {"verse": 27, "start": 328.05, "end": 344.31, "ta": "அப்படியே அவர்கள் கோராகு தாத்தான் அபிராம் என்பவர்களுடைய வாசஸ்தலத்தை விட்டு விலகிப்போனார்கள்; தாத்தானும் அபிராமும் வெளியே வந்து, தங்கள் பெண்ஜாதிகள் பிள்ளைகள் குழந்தைகளோடும் தங்கள் கூடாரவாசலிலே நின்றார்கள்.", "en": "So they gat up from the tabernacle of Korah, Dathan, and Abiram, on every side: and Dathan and Abiram came out, and stood in the door of their tents, and their wives, and their sons, and their little children."}, {"verse": 28, "start": 344.31, "end": 357.78, "ta": "அப்பொழுது மோசே: இந்தக் கிரியைகளையெல்லாம் செய்கிறதற்குக் கர்த்தர் என்னை அனுப்பினார் என்றும், அவைகளை நான் என் மனதின்படியே செய்யவில்லை என்றும், நீங்கள் எதினாலே அறிவீர்களென்றால்,", "en": "And Moses said, Hereby ye shall know that the LORD hath sent me to do all these works; for I have not done them of mine own mind."}, {"verse": 29, "start": 357.78, "end": 369.26, "ta": "சகல மனிதரும் சாகிறபடி இவர்கள் செத்து, சகல மனிதருக்கும் நேரிடுகிறதுபோல இவர்களுக்கும் நேரிட்டால், கர்த்தர் என்னை அனுப்பவில்லை என்று அறிவீர்கள்.", "en": "If these men die the common death of all men, or if they be visited after the visitation of all men; then the LORD hath not sent me."}, {"verse": 30, "start": 369.26, "end": 388.98, "ta": "கர்த்தர் ஒரு புதிய காரியத்தை நேரிடச்செய்வதால், பூமி தன் வாயைத் திறந்து, இவர்கள் உயிரோடே பாதாளத்தில் இறங்கத்தக்கதாக இவர்களையும் இவர்களுக்கு உண்டான யாவையும் விழுங்கிப்போட்டதேயானால், இந்த மனிதர் கர்த்தரை அவமதித்தார்கள் என்பதை அறிந்துகொள்வீர்கள் என்றான்.", "en": "But if the LORD make a new thing, and the earth open her mouth, and swallow them up, with all that appertain unto them, and they go down quick into the pit; then ye shall understand that these men have provoked the LORD ."}, {"verse": 31, "start": 388.98, "end": 395.97, "ta": "அவன் இந்த வார்த்தைகளையெல்லாம் சொல்லி முடித்தவுடனே, அவர்கள் நின்றிருந்த நிலம் பிளந்தது;", "en": "And it came to pass, as he had made an end of speaking all these words, that the ground clave asunder that was under them:"}, {"verse": 32, "start": 395.97, "end": 407.97, "ta": "பூமி தன் வாயைத் திறந்து, அவர்களையும் அவர்கள் வீடுகளையும், கோராகுக்குரிய எல்லா மனிதரையும், அவர்களுக்கு உண்டான சகல பொருள்களையும் விழுங்கிப்போட்டது.", "en": "And the earth opened her mouth, and swallowed them up, and their houses, and all the men that appertained unto Korah, and all their goods."}, {"verse": 33, "start": 407.97, "end": 420.85, "ta": "அவர்கள் தங்களுக்கு உண்டானவை எல்லாவற்றோடும் உயிரோடே பாதாளத்தில் இறங்கினார்கள்; பூமி அவர்களை மூடிக்கொண்டது; இப்படிச் சபையின் நடுவிலிருந்து அழிந்துபோனார்கள்.", "en": "They, and all that appertained to them, went down alive into the pit, and the earth closed upon them: and they perished from among the congregation."}, {"verse": 34, "start": 420.85, "end": 431.22, "ta": "அவர்களைச் சுற்றிலும் இருந்த இஸ்ரவேலர் யாவரும் அவர்கள் கூக்குரலைக்கேட்டு, பூமி நம்மையும் விழுங்கிப்போடும் என்று சொல்லி ஓடினார்கள்.", "en": "And all Israel that were round about them fled at the cry of them: for they said, Lest the earth swallow us up also ."}, {"verse": 35, "start": 431.22, "end": 440.06, "ta": "அக்கினி கர்த்தருடைய சந்நிதியிலிருந்து புறப்பட்டு, தூபங்காட்டின இருநூற்று ஐம்பது பேரையும் பட்சித்துப்போட்டது.", "en": "And there came out a fire from the LORD , and consumed the two hundred and fifty men that offered incense."}, {"verse": 36, "start": 440.06, "end": 442.26, "ta": "பின்பு கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 37, "start": 442.26, "end": 456.76, "ta": "அக்கினிக்குள் அகப்பட்ட தூபகலசங்களை எடுத்து, அவைகளிலிருக்கிற அக்கினியை அப்பாலே கொட்டிப்போடும்படி ஆசாரியனாகிய ஆரோனின் குமாரன் எலெயாசாருக்குச் சொல்; அந்தத் தூபகலசங்கள் பரிசுத்தமாயின.", "en": "Speak unto Eleazar the son of Aaron the priest, that he take up the censers out of the burning, and scatter thou the fire yonder; for they are hallowed."}, {"verse": 38, "start": 456.76, "end": 478.03, "ta": "தங்கள் ஆத்துமாக்களுக்கே கேடுண்டாக்கின அந்தப் பாவிகளின் தூபகலசங்களைப் பலிபீடத்தை மூடத்தக்க தட்டையான தகடுகளாய் அடிக்கக்கடவர்கள்; அவர்கள் கர்த்தருடைய சந்நிதியில் அவைகளைக் கொண்டுவந்ததினால் அவைகள் பரிசுத்தமாயின; அவைகள் இஸ்ரவேல் புத்திரருக்கு ஒரு அடையாளமாயிருக்கும் என்றார்.", "en": "The censers of these sinners against their own souls, let them make them broad plates for a covering of the altar: for they offered them before the LORD , therefore they are hallowed: and they shall be a sign unto the children of Israel."}, {"verse": 39, "start": 478.03, "end": 485.68, "ta": "அப்படியே ஆசாரியனாகிய எலெயாசார் சுட்டெரிக்கப்பட்டவர்கள் கொண்டுவந்திருந்த வெண்கலத் தூபகலசங்களை எடுத்து,", "en": "And Eleazar the priest took the brasen censers, wherewith they that were burnt had offered; and they were made broad plates for a covering of the altar:"}, {"verse": 40, "start": 485.68, "end": 508.86, "ta": "ஆரோனின் புத்திரராய் இராத அந்நியன் ஒருவனும் கர்த்தருடைய சந்நிதியில் தூபங்காட்ட வராதபடிக்கும், கோராகைப்போலும் அவன் கூட்டத்தாரைப்போலும் இராதபடிக்கும், இஸ்ரவேல் புத்திரருக்கு ஞாபகக்குறியாயிருக்கும்பொருட்டு, கர்த்தர் மோசேயைக்கொண்டு தனக்குச் சொன்னபடியே அவைகளைப் பலிபீடத்தை மூடும் தகடுகளாக அடிப்பித்தான்.", "en": "To be a memorial unto the children of Israel, that no stranger, which is not of the seed of Aaron, come near to offer incense before the LORD ; that he be not as Korah, and as his company: as the LORD said to him by the hand of Moses."}, {"verse": 41, "start": 508.86, "end": 520.79, "ta": "மறுநாளில் இஸ்ரவேல் புத்திரரின் சபையார் எல்லாரும் மோசேக்கும் ஆரோனுக்கும் விரோதமாக முறுமுறுத்து: நீங்கள் கர்த்தரின் ஜனங்களைக் கொன்றுபோட்டீர்கள் என்றார்கள்.", "en": "But on the morrow all the congregation of the children of Israel murmured against Moses and against Aaron, saying, Ye have killed the people of the LORD ."}, {"verse": 42, "start": 520.79, "end": 532.19, "ta": "சபையார் மோசேக்கும் ஆரோனுக்கும் விரோதமாகக் கூடி ஆசரிப்புக் கூடாரத்துக்கு நேரே பார்க்கிறபோது, மேகம் அதை மூடினது, கர்த்தரின் மகிமை காணப்பட்டது.", "en": "And it came to pass, when the congregation was gathered against Moses and against Aaron, that they looked toward the tabernacle of the congregation: and, behold, the cloud covered it, and the glory of the LORD appeared."}, {"verse": 43, "start": 532.19, "end": 537.34, "ta": "மோசேயும் ஆரோனும் ஆசரிப்புக் கூடாரத்துக்கு முன்பாக வந்தார்கள்.", "en": "And Moses and Aaron came before the tabernacle of the congregation."}, {"verse": 44, "start": 537.34, "end": 539.77, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 45, "start": 539.77, "end": 550.08, "ta": "இந்தச் சபையாரை விட்டு விலகிப்போங்கள்; ஒரு நிமிஷத்தில் அவர்களை அதமாக்குவேன் என்றார்; அவர்கள் முகங்குப்புற விழுந்தார்கள்.", "en": "Get you up from among this congregation, that I may consume them as in a moment. And they fell upon their faces."}, {"verse": 46, "start": 550.08, "end": 571.71, "ta": "மோசே ஆரோனை நோக்கி: நீ தூபகலசத்தை எடுத்து, பலிபீடத்திலிருக்கிற அக்கினியை அதில் போட்டு, அதின்மேல் தூபவர்க்கம் இட்டு, சீக்கிரமாய்ச் சபையினிடத்தில் போய், அவர்களுக்காகப் பாவநிவிர்த்தி செய்; கர்த்தருடைய சந்நிதியிலிருந்து கடுங்கோபம் புறப்பட்டது, வாதை தொடங்கிற்று என்றான்.", "en": "And Moses said unto Aaron, Take a censer, and put fire therein from off the altar, and put on incense, and go quickly unto the congregation, and make an atonement for them: for there is wrath gone out from the LORD ; the plague is begun."}, {"verse": 47, "start": 571.71, "end": 585.18, "ta": "மோசே சொன்னபடி ஆரோன் அதை எடுத்துக்கொண்டு சபையின் நடுவில் ஓடினான்; ஜனங்களுக்குள்ளே வாதை தொடங்கியிருந்தது; அவன் தூபவர்க்கம் போட்டு, ஜனங்களுக்காகப் பாவநிவிர்த்தி செய்து,", "en": "And Aaron took as Moses commanded, and ran into the midst of the congregation; and, behold, the plague was begun among the people: and he put on incense, and made an atonement for the people."}, {"verse": 48, "start": 585.18, "end": 593.05, "ta": "செத்தவர்களுக்கும் உயிரோடிருக்கிறவர்களுக்கும் நடுவே நின்றான்; அப்பொழுது வாதை நிறுத்தப்பட்டது.", "en": "And he stood between the dead and the living; and the plague was stayed."}, {"verse": 49, "start": 593.05, "end": 601.81, "ta": "கோராகின் காரியத்தினிமித்தம் செத்தவர்கள் தவிர, அந்த வாதையினால் செத்துப்போனவர்கள் பதினாலாயிரத்து எழுநூறுபேர்.", "en": "Now they that died in the plague were fourteen thousand and seven hundred, beside them that died about the matter of Korah."}, {"verse": 50, "start": 601.81, "end": 609.98, "ta": "வாதை நிறுத்தப்பட்டது; அப்பொழுது ஆரோன் ஆசரிப்புக் கூடாரவாசலுக்கு மோசேயினிடத்தில் திரும்பிவந்தான்.", "en": "And Aaron returned unto Moses unto the door of the tabernacle of the congregation: and the plague was stayed."}]}, "17": {"chapter": 17, "duration": 152.71, "audio_url": "audio_ot/OT04_17.mp3", "total_verses": 13, "verses": [{"verse": 1, "start": 3.8, "end": 5.96, "ta": "பின்பு கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.96, "end": 20.24, "ta": "நீ இஸ்ரவேல் புத்திரரோடே பேசி, அவர்கள் பிதாக்களின் வம்சங்களாகிய ஒவ்வொரு வம்சத்தினுடைய பிரபுவினிடத்தில், ஒவ்வொரு கோலாகப் பன்னிரண்டு கோலை வாங்கி, அவனவன் கோலில் அவனவன் பேரை எழுதுவாயாக.", "en": "Speak unto the children of Israel, and take of every one of them a rod according to the house of their fathers, of all their princes according to the house of their fathers twelve rods: write thou every man’s name upon his rod."}, {"verse": 3, "start": 20.24, "end": 30.77, "ta": "லேவியினுடைய கோலின்மேல் ஆரோனின் பேரை எழுதக்கடவாய்; அவர்களுடைய பிதாக்களின் ஒவ்வொரு வம்சத்தலைவனுக்காகவும் ஒவ்வொரு கோல் இருக்கவேண்டும்.", "en": "And thou shalt write Aaron’s name upon the rod of Levi: for one rod shall be for the head of the house of their fathers."}, {"verse": 4, "start": 30.77, "end": 39.14, "ta": "அவைகளை ஆசரிப்புக் கூடாரத்திலே நான் உங்களைச் சந்திக்கும் ஸ்தானமாகிய சாட்சிப்பெட்டிக்கு முன்னே வைக்கக்கடவாய்.", "en": "And thou shalt lay them up in the tabernacle of the congregation before the testimony, where I will meet with you."}, {"verse": 5, "start": 39.14, "end": 52.91, "ta": "அப்பொழுது நான் தெரிந்துகொள்ளுகிறவனுடைய கோல் துளிர்க்கும்; இப்படி இஸ்ரவேல் புத்திரர் உங்களுக்கு விரோதமாய் முறுமுறுக்கிற அவர்கள் முறுமுறுப்பை என்னைவிட்டு ஒழியப்பண்ணுவேன் என்றார்.", "en": "And it shall come to pass, that the man’s rod, whom I shall choose, shall blossom: and I will make to cease from me the murmurings of the children of Israel, whereby they murmur against you."}, {"verse": 6, "start": 52.91, "end": 72.1, "ta": "இதை மோசே இஸ்ரவேல் புத்திரரோடே சொன்னான்; அப்பொழுது அவர்களுடைய பிரபுக்கள் எல்லாரும் தங்கள் பிதாக்களுடைய வம்சத்தின்படி ஒε்வெξரு பοரபுவுக்கு ஒவ்வொரு கோலாகப் பன்னிரண்டு கோல்களை அவனிடத்தில் கொடுத்தார்கள்; ஆரோனின் கோலும் அவர்களுடைய கோல்களுடனே இருந்தது.", "en": "And Moses spake unto the children of Israel, and every one of their princes gave him a rod apiece, for each prince one, according to their fathers’ houses, even twelve rods: and the rod of Aaron was among their rods."}, {"verse": 7, "start": 72.1, "end": 78.15, "ta": "அந்தக் கோல்களை மோசே சாட்சியின் கூடாரத்திலே கர்த்தருடைய சமுகத்தில் வைத்தான்.", "en": "And Moses laid up the rods before the LORD in the tabernacle of witness."}, {"verse": 8, "start": 78.15, "end": 93.44, "ta": "மறுநாள் மோசே சாட்சியின் கூடாரத்துக்குள் பிரவேசித்தபோது, இதோ, லேவியின் குடும்பத்தாருக்கு இருந்த ஆரோனின் கோல் துளிர்த்திருந்தது; அது துளிர்விட்டு, பூப்பூத்து, வாதுமைப்பழங்களைக் கொடுத்தது.", "en": "And it came to pass, that on the morrow Moses went into the tabernacle of witness; and, behold, the rod of Aaron for the house of Levi was budded, and brought forth buds, and bloomed blossoms, and yielded almonds."}, {"verse": 9, "start": 93.44, "end": 108.95, "ta": "அப்பொழுது மோசே கர்த்தருடைய சமுகத்திலிருந்த அந்தக் கோல்களையெல்லாம் எடுத்து, இஸ்ரவேல் புத்திரர் எல்லாரும் காண வெளியே கொண்டுவந்தான்; அவர்கள் கண்டு, அவரவர் தங்கள் தங்கள் கோல்களை வாங்கிக்கொண்டார்கள்.", "en": "And Moses brought out all the rods from before the LORD unto all the children of Israel: and they looked, and took every man his rod."}, {"verse": 10, "start": 108.95, "end": 129.43, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி: ஆரோனின் கோல் அந்தக் கலகக்காரருக்கு விரோதமான அடையாளமாகும்பொருட்டு, அதைத் திரும்பவும் சாட்சிப்பெட்டிக்கு முன்னே கொண்டுபோய் வை; இப்படி அவர்கள் எனக்கு விரோதமாய் முறுமுறுப்பதை ஒழியப்பண்ணுவாய், அப்பொழுது அவர்கள் சாகமாட்டார்கள் என்றார்.", "en": "And the LORD said unto Moses, Bring Aaron’s rod again before the testimony, to be kept for a token against the rebels; and thou shalt quite take away their murmurings from me, that they die not."}, {"verse": 11, "start": 129.43, "end": 133.61, "ta": "கர்த்தர் தனக்குக் கட்டளையிட்டபடியே மோசே செய்தான்.", "en": "And Moses did so: as the LORD commanded him, so did he."}, {"verse": 12, "start": 133.61, "end": 142.63, "ta": "அப்பொழுது இஸ்ரவேல் புத்திரர் மோசேயை நோக்கி: இதோ, செத்து அழிந்துபோகிறோம்; நாங்கள் எல்லாரும் அழிந்துபோகிறோம்.", "en": "And the children of Israel spake unto Moses, saying, Behold, we die, we perish, we all perish."}, {"verse": 13, "start": 142.63, "end": 151.21, "ta": "கர்த்தரின் வாசஸ்தலத்தின் கிட்டேவருகிற எவனும் சாகிறான்; நாங்கள் எல்லாரும் செத்துத்தான் தீருமோ என்றார்கள்.", "en": "Whosoever cometh any thing near unto the tabernacle of the LORD shall die: shall we be consumed with dying?"}]}, "18": {"chapter": 18, "duration": 465.75, "audio_url": "audio_ot/OT04_18.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 21.5, "ta": "பின்பு கர்த்தர் ஆரோனை நோக்கி: நீயும் உன்னோடேகூட உன் குமாரரும் உன் தகப்பன் வம்சத்தாரும் பரிசுத்த ஸ்தலத்தைப்பற்றிய அக்கிரமத்தைச் சுமக்கவேண்டும்; நீயும் உன்னோடேகூட உன் குமாரரும் உங்கள் ஆசாரிய ஊழியத்தைப்பற்றிய அக்கிரமத்தைச் சுமக்கவேண்டும்.", "en": "And the LORD said unto Aaron, Thou and thy sons and thy father’s house with thee shall bear the iniquity of the sanctuary: and thou and thy sons with thee shall bear the iniquity of your priesthood."}, {"verse": 2, "start": 21.5, "end": 37.0, "ta": "உன் தகப்பனாகிய லேவியின் கோத்திரத்தாரான உன் சகோதரரையும் உன்னோடே கூடியிருக்கவும் உன்னிடத்திலே சேவிக்கவும் அவர்களைச் சேர்த்துக்கொள்; நீயும் உன் குமாரருமோ சாட்சியின் கூடாரத்துக்குமுன் ஊழியம் செய்யக்கடவீர்கள்.", "en": "And thy brethren also of the tribe of Levi, the tribe of thy father, bring thou with thee, that they may be joined unto thee, and minister unto thee: but thou and thy sons with thee shall minister before the tabernacle of witness."}, {"verse": 3, "start": 37.0, "end": 51.08, "ta": "அவர்கள் உன் காவலையும் கூடாரம் அனைத்தின் காவலையும் காக்கக்கடவர்கள்; ஆகிலும் அவர்களும் நீங்களும் சாகாதபடிக்கு, அவர்கள் பரிசுத்த ஸ்தலத்தின் பணிமுட்டுகளண்டையிலும் பலிபீடத்தண்டையிலும் சேராமல்,", "en": "And they shall keep thy charge, and the charge of all the tabernacle: only they shall not come nigh the vessels of the sanctuary and the altar, that neither they, nor ye also, die."}, {"verse": 4, "start": 51.08, "end": 63.97, "ta": "உன்னோடே கூடிக்கொண்டு, கூடாரத்துக்கடுத்த எல்லாப் பணிவிடையையும் செய்ய, ஆசரிப்புக் கூடாரத்தின் காவலைக்காக்கக்கடவர்கள்; அந்நியன் ஒருவனும் உங்களிடத்தில் சேரக் கூடாது.", "en": "And they shall be joined unto thee, and keep the charge of the tabernacle of the congregation, for all the service of the tabernacle: and a stranger shall not come nigh unto you."}, {"verse": 5, "start": 63.97, "end": 74.09, "ta": "இஸ்ரவேல் புத்திரர்மேல் இனிக் கடுங்கோபம் வராதபடிக்கு, நீங்கள் பரிசுத்த ஸ்தலத்தின் காவலையும் பலிபீடத்தின் காவலையும் காக்கக்கடவீர்கள்.", "en": "And ye shall keep the charge of the sanctuary, and the charge of the altar: that there be no wrath any more upon the children of Israel."}, {"verse": 6, "start": 74.09, "end": 87.4, "ta": "ஆசரிப்புக் கூடாரத்தின் பணிவிடையைச் செய்ய, கர்த்தருக்குக் கொடுக்கப்பட்ட உங்கள் சகோதரராகிய லேவியரை நான் இஸ்ரவேல் புத்திரரிலிருந்து பிரித்து, உங்களுக்குத் தத்தமாகக் கொடுத்தேன்.", "en": "And I, behold, I have taken your brethren the Levites from among the children of Israel: to you they are given as a gift for the LORD , to do the service of the tabernacle of the congregation."}, {"verse": 7, "start": 87.4, "end": 109.83, "ta": "ஆகையால் நீயும் உன்னோடேகூட உன் குமாரரும் பலிபீடத்துக்கும் திரைக்கு உட்புறத்துக்கும் அடுத்த எல்லாவற்றையும் செய்யும்பொருட்டு, உங்கள் ஆசாரிய ஊழியத்தைக் காத்துச் சேவிக்கக்கடவீர்கள்; உங்கள் ஆசாரிய ஊழியத்தை உங்களுக்கு தத்தமாக அருளினேன்; அதைச்செய்யும்படி சேருகிற அந்நியன் கொலைசெய்யப்படக்கடவன் என்றார்.", "en": "Therefore thou and thy sons with thee shall keep your priest’s office for every thing of the altar, and within the vail; and ye shall serve: I have given your priest’s office unto you as a service of gift: and the stranger that cometh nigh shall be put to death."}, {"verse": 8, "start": 109.83, "end": 130.36, "ta": "பின்னும் கர்த்தர் ஆரோனை நோக்கி: இஸ்ரவேல் புத்திரர் பரிசுத்தப்படுத்துகிறவைகளிலெல்லாம் எனக்கு ஏறெடுத்துப்படைக்கப்படும் படைப்புகளைக் காத்துக்கொண்டிருக்கிறீர்களே, அவைகளை உனக்குக் கொடுத்தேன்; அபிஷேகத்தினிமித்தம் அவைகளை உனக்கும் உன் குமாரருக்கும் நித்திய கட்டளையாகக் கொடுத்தேன்.", "en": "And the LORD spake unto Aaron, Behold, I also have given thee the charge of mine heave offerings of all the hallowed things of the children of Israel; unto thee have I given them by reason of the anointing, and to thy sons, by an ordinance for ever."}, {"verse": 9, "start": 130.36, "end": 150.25, "ta": "மகா பரிசுத்தமானவைகளிலே, அக்கினிக்கு உட்படுத்தப்படாமல் உன்னுடையதாயிருப்பது எவையெனில், அவர்கள் எனக்குப் படைக்கும் எல்லாப் படைப்பும், எல்லாப் போஜனபலியும், எல்லாப் பாவநிவாரணபலியும், எல்லாக் குற்றநிவாரணபலியும், உனக்கும் உன் குமாரருக்கும் பரிசுத்தமாயிருக்கும்.", "en": "This shall be thine of the most holy things, reserved from the fire: every oblation of theirs, every meat offering of theirs, and every sin offering of theirs, and every trespass offering of theirs, which they shall render unto me, shall be most holy for thee and for thy sons."}, {"verse": 10, "start": 150.25, "end": 160.45, "ta": "பரிசுத்த ஸ்தலத்திலே அவைகளைப் புசிக்கவேண்டும்; ஆண்மக்கள் யாவரும் அவைகளைப் புசிக்கலாம்; அவைகள் உனக்குப் பரிசுத்தமாயிருப்பதாக.", "en": "In the most holy place shalt thou eat it; every male shall eat it: it shall be holy unto thee."}, {"verse": 11, "start": 160.45, "end": 181.54, "ta": "இஸ்ரவேல் புத்திரர் ஏறெடுத்துப்டைக்கிறதும் அசைவாட்டுகிறதுமான அவர்களுடைய எல்லாக் காணிக்கைகளின் படைப்பும் உன்னுடையவைகளாயிருக்கும். அவைகளை உனக்கும் உன் குமாரருக்கும் உன் குமாரத்திகளுக்கும் நித்திய நியமமாகக் கொடுத்தேன்; உன் வீட்டிலே சுத்தமானவர்கள் எல்லாரும் அவைகளைப் புசிக்கலாம்.", "en": "And this is thine; the heave offering of their gift, with all the wave offerings of the children of Israel: I have given them unto thee, and to thy sons and to thy daughters with thee, by a statute for ever: every one that is clean in thy house shall eat of it."}, {"verse": 12, "start": 181.54, "end": 193.57, "ta": "அவர்கள் கர்த்தருக்குக் கொடுக்கும் அவர்களுடைய முதற்பலன்களாகிய உச்சிதமான எண்ணெயையும், உச்சிதமான திராட்சரசத்தையும், தானியத்தையும் உனக்கு உரியதாகக் கொடுத்தேன்.", "en": "All the best of the oil, and all the best of the wine, and of the wheat, the firstfruits of them which they shall offer unto the LORD , them have I given thee."}, {"verse": 13, "start": 193.57, "end": 206.03, "ta": "தங்கள் தேசத்தில் முதற்பழுத்த பலனில் அவர்கள் கர்த்தருக்குக் கொண்டு வருவதெல்லாம் உனக்கு உரியதாகும்; உன் வீட்டிலே சுத்தமாயிருப்பவர்கள் யாவரும் அவைகளைப் புசிக்கலாம்.", "en": "And whatsoever is first ripe in the land, which they shall bring unto the LORD , shall be thine; every one that is clean in thine house shall eat of it."}, {"verse": 14, "start": 206.03, "end": 211.9, "ta": "இஸ்ரவேலிலே சாபத்தீடாக நேர்ந்துகொள்ளப்பட்டதெல்லாம் உனக்கு உரியதாயிருக்கும்.", "en": "Every thing devoted in Israel shall be thine."}, {"verse": 15, "start": 211.9, "end": 230.88, "ta": "மனிதரிலும் மிருகங்களிலும் அவர்கள் கர்த்தருக்குச் செலுத்தும் சமஸ்த பிராணிகளுக்குள்ளே கர்ப்பந்திறந்து பிறக்கும் யாவும் உனக்கு உரியதாயிருக்கும்; ஆனாலும் மனிதரின் முதற்பேற்றை அகத்தியமாய் மீட்கவேண்டும்; தீட்டான மிருகஜீவனின் தலையீற்றையும் மீட்கவேண்டும்.", "en": "Every thing that openeth the matrix in all flesh, which they bring unto the LORD , whether it be of men or beasts, shall be thine: nevertheless the firstborn of man shalt thou surely redeem, and the firstling of unclean beasts shalt thou redeem."}, {"verse": 16, "start": 230.88, "end": 244.82, "ta": "மீட்கவேண்டியவைகள் ஒரு மாதத்திற்கு மேற்பட்டதனால், உன் மதிப்புக்கு இசைய பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்கின்படி ஐந்து சேக்கல் பணத்தாலே அவைகளை மீட்கவேண்டும்; ஒரு சேக்கல் இருபது கேரா.", "en": "And those that are to be redeemed from a month old shalt thou redeem, according to thine estimation, for the money of five shekels, after the shekel of the sanctuary, which is twenty gerahs."}, {"verse": 17, "start": 244.82, "end": 264.21, "ta": "மாட்டின் தலையீற்றும், செம்மறியாட்டின் தலையீற்றும், வெள்ளாட்டின் தலையீற்றுமோ மீட்கப்படவேண்டாம்; அவைகள் பரிசுத்தமானவைகள்; அவைகளின் இரத்தத்தைப் பலிபீடத்தின்மேல் தெளித்து, அவைகளின் கொழுப்பைக் கர்த்தருக்குச் சுகந்த வாசனையான தகனமாகத் தகனிக்கவேண்டும்.", "en": "But the firstling of a cow, or the firstling of a sheep, or the firstling of a goat, thou shalt not redeem; they are holy: thou shalt sprinkle their blood upon the altar, and shalt burn their fat for an offering made by fire, for a sweet savour unto the LORD ."}, {"verse": 18, "start": 264.21, "end": 271.65, "ta": "அசைவாட்டும் மார்க்கண்டத்தைப்போலும் வலது முன்னந்தொடையைப்போலும் அவைகளின் மாம்சமும் உன்னுடையதாகும்.", "en": "And the flesh of them shall be thine, as the wave breast and as the right shoulder are thine."}, {"verse": 19, "start": 271.65, "end": 291.4, "ta": "இஸ்ரவேல் புத்திரர் கர்த்தருக்கு ஏறெடுத்துப் படைக்கிற பரிசுத்த படைப்புகளையெல்லாம் உனக்கும் உன் குமாரருக்கும் உன் குமாரத்திகளுக்கும் நித்திய கட்டளையாகக் கொடுத்தேன்; கர்த்தருடைய சந்நிதியில் இது உனக்கும் உன் சந்ததிக்கும் என்றைக்கும் செல்லும் மாறாத உடன்படிக்கை என்றார்.", "en": "All the heave offerings of the holy things, which the children of Israel offer unto the LORD , have I given thee, and thy sons and thy daughters with thee, by a statute for ever: it is a covenant of salt for ever before the LORD unto thee and to thy seed with thee."}, {"verse": 20, "start": 291.4, "end": 308.6, "ta": "பின்னும் கர்த்தர் ஆரோனை நோக்கி: அவர்களுடைய தேசத்தில் நீ ஒன்றையும் சுதந்தரித்துக்கொள்ளவேண்டாம், அவர்கள் நடுவே உனக்குப் பங்கு உண்டாயிருக்கவும் வேண்டாம்; இஸ்ரவேல் புத்திரர் நடுவில் நானே உன் பங்கும் உன் சுதந்தரமுமாய் இருக்கிறேன்.", "en": "And the LORD spake unto Aaron, Thou shalt have no inheritance in their land, neither shalt thou have any part among them: I am thy part and thine inheritance among the children of Israel."}, {"verse": 21, "start": 308.6, "end": 321.83, "ta": "இதோ, லேவியின் புத்திரர் ஆசரிப்புக் கூடாரத்தின் பணிவிடையைச் செய்கிற அவர்களுடைய வேலைக்காக, இஸ்ரவேலருக்குள்ளவை எல்லாவற்றிலும் தசமபாகத்தை அவர்களுக்குச் சுதந்தரமாகக் கொடுத்தேன்.", "en": "And, behold, I have given the children of Levi all the tenth in Israel for an inheritance, for their service which they serve, even the service of the tabernacle of the congregation."}, {"verse": 22, "start": 321.83, "end": 329.69, "ta": "இஸ்ரவேல் புத்திரர் குற்றஞ்சுமந்து சாகாதபடிக்கு, இனி ஆசரிப்புக் கூடாரத்தைக் கிட்டாதிருக்கக்கடவர்கள்.", "en": "Neither must the children of Israel henceforth come nigh the tabernacle of the congregation, lest they bear sin, and die."}, {"verse": 23, "start": 329.69, "end": 347.03, "ta": "லேவியர்மாத்திரம் ஆசரிப்புக் கூடாரத்துக்கடுத்த வேலைகளைச் செய்யவேண்டும்; அவர்கள் தங்கள் அக்கிரமத்தைச் சுமப்பார்கள்; இஸ்ரவேல் புத்திரர் நடுவே அவர்களுக்குச் சுதந்தரம் இல்லை என்பது உங்கள் தலைமுறைதோறும் நித்திய கட்டளையாயிருக்கும்.", "en": "But the Levites shall do the service of the tabernacle of the congregation, and they shall bear their iniquity: it shall be a statute for ever throughout your generations, that among the children of Israel they have no inheritance."}, {"verse": 24, "start": 347.03, "end": 363.31, "ta": "இஸ்ரவேல் புத்திரர் கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் படைப்பாகிய தசமபாகத்தை லேவியருக்குச் சுதந்தரமாகக் கொடுத்தேன்; ஆகையால் இஸ்ரவேல் புத்திரரின் நடுவே அவர்களுக்குச் சுதந்தரமில்லையென்று அவர்களுக்குச் சொன்னேன் என்றார்.", "en": "But the tithes of the children of Israel, which they offer as an heave offering unto the LORD , I have given to the Levites to inherit: therefore I have said unto them, Among the children of Israel they shall have no inheritance."}, {"verse": 25, "start": 363.31, "end": 365.58, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 26, "start": 365.58, "end": 385.47, "ta": "நீ லேவியரோடே சொல்லவேண்டியது என்னவென்றால்: இஸ்ரவேல் புத்திரர் கையில் வாங்கிக்கொள்ளும்படி நான் உங்களுக்குச் சுதந்தரமாகக் கொடுத்த தசமபாகத்தை நீங்கள் அவர்கள் கையில் வாங்கும்போது, தசமபாகத்தில் பத்தில் ஒரு பங்கைக் கர்த்தருக்கு ஏறெடுத்துப்படைக்கும் படைப்பாகச் செலுத்தவேண்டும்.", "en": "Thus speak unto the Levites, and say unto them, When ye take of the children of Israel the tithes which I have given you from them for your inheritance, then ye shall offer up an heave offering of it for the LORD , even a tenth part of the tithe."}, {"verse": 27, "start": 385.47, "end": 394.81, "ta": "நீங்கள் ஏறெடுத்துப் படைக்கும் இந்தப் படைப்பு களத்தின் தானியத்தைப்போலும், ஆலையின் இரசத்தைப்போலும் உங்களுக்கு எண்ணப்படும்.", "en": "And this your heave offering shall be reckoned unto you, as though it were the corn of the threshingfloor, and as the fulness of the winepress."}, {"verse": 28, "start": 394.81, "end": 410.17, "ta": "இப்படியே நீங்கள் இஸ்ரவேல் புத்திரர் கையில் வாங்கும் தசமபாகமாகிய உங்கள் பங்குகளிலெல்லாம் நீங்களும் கர்த்தருக்கு என்று ஒரு படைப்பை ஏறெடுத்துப் படைத்து, அந்தப் படைப்பை ஆசாரியனாகிய ஆரோனுக்குக் கொடுக்கவேண்டும்.", "en": "Thus ye also shall offer an heave offering unto the LORD of all your tithes, which ye receive of the children of Israel; and ye shall give thereof the LORD’s heave offering to Aaron the priest."}, {"verse": 29, "start": 410.17, "end": 421.43, "ta": "உங்களுக்குக் கொடுக்கப்படுகிற ஒவ்வொரு காணிக்கையிலுமுள்ள உச்சிதமான பரிசுத்த பங்கையெல்லாம் கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் படைப்பாகச் செலுத்தவேண்டும்.", "en": "Out of all your gifts ye shall offer every heave offering of the LORD , of all the best thereof, even the hallowed part thereof out of it."}, {"verse": 30, "start": 421.43, "end": 436.72, "ta": "ஆதலால் நீ அவர்களோடே சொல்லவேண்டியது என்னவென்றால்: அதில் உச்சிதமானதை நீங்கள் ஏறெடுத்துப் படைக்கும்போது, அது களத்தின் வரத்திலும் ஆலையின் வரத்திலும் இருந்து எடுத்துச் செலுத்துகிறதுபோல லேவியருக்கு எண்ணப்படும்.", "en": "Therefore thou shalt say unto them, When ye have heaved the best thereof from it, then it shall be counted unto the Levites as the increase of the threshingfloor, and as the increase of the winepress."}, {"verse": 31, "start": 436.72, "end": 447.76, "ta": "அதை நீங்களும் உங்கள் குடும்பத்தாரும் எவ்விடத்திலும் புசிக்கலாம்; அது நீங்கள் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடைக்கு ஈடான உங்கள் சம்பளம்.", "en": "And ye shall eat it in every place, ye and your households: for it is your reward for your service in the tabernacle of the congregation."}, {"verse": 32, "start": 447.76, "end": 464.25, "ta": "இப்படி அதில் உச்சிதமானதை ஏறெடுத்துப் படைத்தீர்களானால், நீங்கள் அதினிமித்தம் பாவம் சுமக்கமாட்டீர்கள்; நீங்கள் சாகாதிருக்கும்படிக்கு, இஸ்ரவேல் புத்திரரின் பரிசுத்தமானவைகளைத் தீட்டுப்படுத்தலாகாது என்று சொல் என்றார்.", "en": "And ye shall bear no sin by reason of it, when ye have heaved from it the best of it: neither shall ye pollute the holy things of the children of Israel, lest ye die."}]}, "19": {"chapter": 19, "duration": 294.1, "audio_url": "audio_ot/OT04_19.mp3", "total_verses": 22, "verses": [{"verse": 1, "start": 3.8, "end": 6.46, "ta": "கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and unto Aaron, saying,"}, {"verse": 2, "start": 6.46, "end": 19.93, "ta": "கர்த்தர் கற்பித்த நியமப்பிரமாணமாவது: பழுதற்றதும் ஊனமில்லாததும் நுகத்தடிக்கு உட்படாததுமாகிய சிவப்பான ஒரு கிடாரியை உன்னிடத்தில் கொண்டுவரும்படி இஸ்ரவேல் புத்திரருக்குச் சொல்லுங்கள்.", "en": "This is the ordinance of the law which the LORD hath commanded, saying, Speak unto the children of Israel, that they bring thee a red heifer without spot, wherein is no blemish, and upon which never came yoke:"}, {"verse": 3, "start": 19.93, "end": 32.32, "ta": "அதை எலெயாசார் என்னும் ஆசாரியனிடத்தில் ஒப்புக்கொடுங்கள்; அவன் அதைப் பாளயத்துக்கு வெளியே கொண்டுபோகக்கடவன்; அங்கே அது அவனுக்கு முன்பாகக் கொல்லப்படக்கடவது.", "en": "And ye shall give her unto Eleazar the priest, that he may bring her forth without the camp, and one shall slay her before his face:"}, {"verse": 4, "start": 32.32, "end": 42.91, "ta": "அப்பொழுது ஆசாரியனξகிய Πβெயξசார͠தன் வߠΰலߠΩாலύ அதοΩ் இΰத்ĠΤ்தில் கொஞ்சம் எடுத்து, ஆசரிப்புக் கூடாரத்துக்கு எதிராக ஏழுதரம் தெளிக்கக்கடவன்.", "en": "And Eleazar the priest shall take of her blood with his finger, and sprinkle of her blood directly before the tabernacle of the congregation seven times:"}, {"verse": 5, "start": 42.91, "end": 54.93, "ta": "பின்பு கிடாரியை அவன் கண்களுக்கு முன்பாக ஒருவன் சுட்டெரிக்கவேண்டும்; அதின் தோலும் அதின் மாம்சமும் அதின் இரத்தமும் அதின் சாணியும் சுட்டெரிக்கப்படவேண்டும்.", "en": "And one shall burn the heifer in his sight; her skin, and her flesh, and her blood, with her dung, shall he burn:"}, {"verse": 6, "start": 54.93, "end": 65.02, "ta": "அப்பொழுது ஆசாரியன் கேதுருக்கட்டையையும் ஈசோப்பையும் சிவப்புநூலையும் எடுத்து, கிடாரி எரிக்கப்படுகிற நெருப்பின் நடுவிலே போடக்கடவன்.", "en": "And the priest shall take cedar wood, and hyssop, and scarlet, and cast it into the midst of the burning of the heifer."}, {"verse": 7, "start": 65.02, "end": 77.76, "ta": "பின்பு ஆசாரியன் தன் வஸ்திரங்களைத் தோய்த்து, ஜலத்திலே ஸ்நானம்பண்ணி, அதின்பின்பு பாளயத்தில் பிரவேசிக்கக்கடவன்; ஆசாரியன் சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்.", "en": "Then the priest shall wash his clothes, and he shall bathe his flesh in water, and afterward he shall come into the camp, and the priest shall be unclean until the even."}, {"verse": 8, "start": 77.76, "end": 87.42, "ta": "அதைச் சுட்டெரித்தவனும் தன் வஸ்திரங்களை ஜலத்தில் தோய்த்து, ஜலத்திலே ஸ்நானம்பண்ணி, சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்.", "en": "And he that burneth her shall wash his clothes in water, and bathe his flesh in water, and shall be unclean until the even."}, {"verse": 9, "start": 87.42, "end": 106.72, "ta": "சுத்தமாயிருக்கிற ஒருவன் அந்தக் கிடாரியின் சாம்பலை வாரிக்கொண்டு பாளயத்திற்குப் புறம்பே சுத்தமான ஒரு இடத்திலே கொட்டி வைக்கக்கடவன், அது இஸ்ரவேல் புத்திரரின் சபைக்காகத் தீட்டுக்கழிக்கும் ஜலத்துக்கென்று காத்துவைக்கப்படவேண்டும்; அது பாவத்தைப் பரிகரிக்கும்.", "en": "And a man that is clean shall gather up the ashes of the heifer, and lay them up without the camp in a clean place, and it shall be kept for the congregation of the children of Israel for a water of separation: it is a purification for sin."}, {"verse": 10, "start": 106.72, "end": 122.78, "ta": "கிடாரியின் சாம்பலை வாரினவன் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்; அவன் சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்; இது இஸ்ரவேல் புத்திரருக்கும் அவர்கள் நடுவிலே தங்குகிற அந்நியனுக்கும் நித்திய கட்டளையாயிருப்பதாக.", "en": "And he that gathereth the ashes of the heifer shall wash his clothes, and be unclean until the even: and it shall be unto the children of Israel, and unto the stranger that sojourneth among them, for a statute for ever."}, {"verse": 11, "start": 122.78, "end": 128.39, "ta": "செத்துப்போனவனுடைய பிரேதத்தைத் தொட்டவன் ஏழுநாள் தீட்டுப்பட்டிருப்பான்.", "en": "He that toucheth the dead body of any man shall be unclean seven days."}, {"verse": 12, "start": 128.39, "end": 144.38, "ta": "அவன் மூன்றாம் நாளிலும் ஏழாம் நாளிலும் தீட்டுக்கழிக்கும் ஜலத்தினால் தன்னைச் சுத்திகரிக்கக்கடவன்; அப்பொழுது சுத்தமாவான்; மூன்றாம் நாளிலும் ஏழாம் நாளிலும் தன்னைச் சுத்திகரிக்காமலிருப்பானாகில் சுத்தமாகான்.", "en": "He shall purify himself with it on the third day, and on the seventh day he shall be clean: but if he purify not himself the third day, then the seventh day he shall not be clean."}, {"verse": 13, "start": 144.38, "end": 167.36, "ta": "செத்தவனுடைய பிரேதத்தைத் தொட்டும், தன்னைச் சுத்திகரித்துக்கொள்ளாதவன் கர்த்தரின் வாசஸ்தலத்தைத் தீட்டுப்படுத்துகிறான்; அந்த ஆத்துமா இஸ்ரவேலில் இராமல் அறுப்புண்டுபோவான்; தீட்டுக்கழிக்கும் ஜலம் அவன்மேல் தெளிக்கப்படாததினால், அவன் தீட்டுப்பட்டிருப்பான்; அவன் தீட்டு இன்னும் அவன்மேல் இருக்கும்.", "en": "Whosoever toucheth the dead body of any man that is dead, and purifieth not himself, defileth the tabernacle of the LORD ; and that soul shall be cut off from Israel: because the water of separation was not sprinkled upon him, he shall be unclean; his uncleanness is yet upon him."}, {"verse": 14, "start": 167.36, "end": 179.53, "ta": "கூடாரத்தில் ஒரு மனிதன் செத்தால், அதற்கடுத்த நியமமாவது: அந்தக் கூடாரத்தில் பிரவேசிக்கிற யாவரும் கூடாரத்தில் இருக்கிற யாவரும் ஏழுநாள் தீட்டுப்பட்டிருப்பார்கள்.", "en": "This is the law, when a man dieth in a tent: all that come into the tent, and all that is in the tent, shall be unclean seven days."}, {"verse": 15, "start": 179.53, "end": 185.87, "ta": "மூடிக் கட்டப்படாமல் திறந்திருக்கும் பாத்திரங்கள் எல்லாம் தீட்டுப்பட்டிருக்கும்.", "en": "And every open vessel, which hath no covering bound upon it, is unclean."}, {"verse": 16, "start": 185.87, "end": 197.46, "ta": "வெளியிலே பட்டயத்தால் வெட்டுண்டவனையாவது, செத்தவனையாவது, மனித எலும்பையாவது, பிரேதக்குழியையாவது, தொட்டவன் எவனும் ஏழுநாள் தீட்டுப்பட்டிருப்பான்.", "en": "And whosoever toucheth one that is slain with a sword in the open fields, or a dead body, or a bone of a man, or a grave, shall be unclean seven days."}, {"verse": 17, "start": 197.46, "end": 209.85, "ta": "ஆகையால் தீட்டுப்பட்டவனுக்காக, பாவத்தைப் பரிகரிக்கும் கிடாரியின் சாம்பலிலே கொஞ்சம் எடுத்து, ஒரு பாத்திரத்தில் போட்டு, அதின்மேல் ஊற்று ஜலம் வார்க்கவேண்டும்.", "en": "And for an unclean person they shall take of the ashes of the burnt heifer of purification for sin, and running water shall be put thereto in a vessel:"}, {"verse": 18, "start": 209.85, "end": 230.37, "ta": "சுத்தமான ஒருவன் ஈசோப்பை எடுத்து, அந்த ஜலத்திலே தோய்த்து, கூடாரத்தின்மேலும் அதிலுள்ள சகல பணிமுட்டுகளின்மேலும் அங்கேயிருக்கிற ஜனங்களின்மேலும் தெளிக்கிறதுமல்லாமல், எலும்பையாகிலும் வெட்டுண்டவனையாகிலும் செத்தவனையாகிலும் பிரேதக்குழியையாகிலும் தொட்டவன்மேலும் தெளிக்கக்கடவன்.", "en": "And a clean person shall take hyssop, and dip it in the water, and sprinkle it upon the tent, and upon all the vessels, and upon the persons that were there, and upon him that touched a bone, or one slain, or one dead, or a grave:"}, {"verse": 19, "start": 230.37, "end": 247.59, "ta": "சுத்தமாயிருக்கிறவன் தீட்டுப்பட்டவன்மேல் மூன்றாம் நாளிலும் ஏழாம் நாளிலும் தெளிக்கவேண்டும்; ஏழாம் நாளில் இவன் தன்னைச் சுத்திகரித்து, தன் வஸ்திரங்களைத் தோய்த்து, ஜலத்தில் ஸ்நானம்பண்ணி, சாயங்காலத்திலே சுத்தமாயிருப்பான்.", "en": "And the clean person shall sprinkle upon the unclean on the third day, and on the seventh day: and on the seventh day he shall purify himself, and wash his clothes, and bathe himself in water, and shall be clean at even."}, {"verse": 20, "start": 247.59, "end": 267.18, "ta": "தீட்டுப்பட்டிருக்கிறவன் தன்னைச் சுத்திகரித்துக் கொள்ளாதிருந்தால், அவன் சபையில் இராதபடிக்கு அறுப்புண்டுபோவான்; அவன் கர்த்தரின் பரிசுத்த ஸ்தலத்தைத் தீட்டுப்படுத்தினான்; தீட்டுக்கழிக்கும் ஜலம் அவன்மேல் தெளிக்கப்படாததினால் அவன் தீட்டுப்பட்டிருக்கிறான்.", "en": "But the man that shall be unclean, and shall not purify himself, that soul shall be cut off from among the congregation, because he hath defiled the sanctuary of the LORD : the water of separation hath not been sprinkled upon him; he is unclean."}, {"verse": 21, "start": 267.18, "end": 279.13, "ta": "தீட்டுக்கழிக்கும் ஜலத்தைத் தெளிக்கிறவனும் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்; தீட்டுக்கழிக்கும் ஜலத்தைத்தொட்டவனும் சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்.", "en": "And it shall be a perpetual statute unto them, that he that sprinkleth the water of separation shall wash his clothes; and he that toucheth the water of separation shall be unclean until even."}, {"verse": 22, "start": 279.13, "end": 292.6, "ta": "தீட்டுப்பட்டிருக்கிறவன் தொடுகிறவைகளெல்லாம் தீட்டுப்படும், அவைகளைத் தொடுகிறவனும் சாயங்காலமட்டும் தீட்டுப்பட்டிருப்பான்; இது உங்களுக்கு நித்திய கட்டளையாயிருக்கும் என்றார்.", "en": "And whatsoever the unclean person toucheth shall be unclean; and the soul that toucheth it shall be unclean until even."}]}, "20": {"chapter": 20, "duration": 376.65, "audio_url": "audio_ot/OT04_20.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 17.53, "ta": "இஸ்ரவேல் புத்திரரின் சபையார் எல்லாரும் முதலாம் மாதத்தில் சீன்வனாந்தரத்திலே சேர்ந்து, ஜனங்கள் காதேசிலே தங்கியிருக்கையில், மிரியாம் மரணமடைந்து, அங்கே அடக்கம்பண்ணப்பட்டாள்.", "en": "Then came the children of Israel, even the whole congregation, into the desert of Zin in the first month: and the people abode in Kadesh; and Miriam died there, and was buried there."}, {"verse": 2, "start": 17.53, "end": 26.64, "ta": "ஜனங்களுக்குத் தண்ணீர் இல்லாதிருந்தது; அப்பொழுது அவர்கள் மோசேக்கும் ஆரோனுக்கும் விரோதமாகக் கூட்டங்கூடினார்கள்.", "en": "And there was no water for the congregation: and they gathered themselves together against Moses and against Aaron."}, {"verse": 3, "start": 26.64, "end": 36.77, "ta": "ஜனங்கள் மோசேயோடே வாக்குவாதம் பண்ணி: எங்கள் சகோதரர் கர்த்தருடைய சந்நிதியில் மாண்டபோது நாங்களும் மாண்டுபோயிருந்தால் நலமாயிருக்கும்.", "en": "And the people chode with Moses, and spake, saying, Would God that we had died when our brethren died before the LORD !"}, {"verse": 4, "start": 36.77, "end": 45.51, "ta": "நாங்களும் எங்கள் மிருகங்களும் இங்கே சாகும்படி, நீங்கள் கர்த்தரின் சபையை இந்த வனாந்தரத்திலே கொண்டு வந்தது என்ன;", "en": "And why have ye brought up the congregation of the LORD into this wilderness, that we and our cattle should die there?"}, {"verse": 5, "start": 45.51, "end": 61.44, "ta": "விதைப்பும் அத்திமரமும், திராட்சச்செடியும், மாதளஞ்செடியும், குடிக்கத் தண்ணீரும் இல்லாத இந்த கெட்ட இடத்தில் எங்களைக் கொண்டுவரும்படி, நீங்கள் எங்களை எகிப்திலிருந்து புறப்படப்பண்ணினது என்ன என்றார்கள்.", "en": "And wherefore have ye made us to come up out of Egypt, to bring us in unto this evil place? it is no place of seed, or of figs, or of vines, or of pomegranates; neither is there any water to drink."}, {"verse": 6, "start": 61.44, "end": 73.63, "ta": "அப்பொழுது மோசேயும் ஆரோனும் சபையாரை விட்டு, ஆசரிப்புக் கூடாரவாசலில் போய், முகங்குப்புற விழுந்தார்கள்; கர்த்தருடைய மகிமை அவர்களுக்குக் காணப்பட்டது.", "en": "And Moses and Aaron went from the presence of the assembly unto the door of the tabernacle of the congregation, and they fell upon their faces: and the glory of the LORD appeared unto them."}, {"verse": 7, "start": 73.63, "end": 75.32, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 8, "start": 75.32, "end": 101.32, "ta": "நீ கோலை எடுத்துக்கொண்டு, நீயும் உன் சகோதரனாகிய ஆரோனும் சபையாரைக் கூடிவரச்செய்து, அவர்கள் கண்களுக்குமுன்னே கன்மலையைப் பார்த்துப் பேசுங்கள்; அப்பொழுது அது தன்னிடத்திலுள்ள தண்ணீரைக் கொடுக்கும்; இப்படி நீ அவர்களுக்குக் கன்மலையிலிருந்து தண்ணீர் புறப்படப்பண்ணி, சபையாருக்கும் அவர்கள் மிருகங்களுக்கும் குடிக்கக் கொடுப்பாய் என்றார்.", "en": "Take the rod, and gather thou the assembly together, thou, and Aaron thy brother, and speak ye unto the rock before their eyes; and it shall give forth his water, and thou shalt bring forth to them water out of the rock: so thou shalt give the congregation and their beasts drink."}, {"verse": 9, "start": 101.32, "end": 108.88, "ta": "அப்பொழுது மோசே தனக்குக் கர்த்தர் கட்டளையிட்டபடியே கர்த்தருடைய சந்நிதியிலிருந்த கோலை எடுத்தான்.", "en": "And Moses took the rod from before the LORD , as he commanded him."}, {"verse": 10, "start": 108.88, "end": 124.96, "ta": "மோசேயும் ஆரோனும் சபையாரைக் கன்மலைக்கு முன்பாக கூடிவரச்செய்தார்கள்; அப்பொழுது மோசே அவர்களை நோக்கி: கலகக்காரரே, கேளுங்கள், உங்களுக்கு இந்தக் கன்மலையிலிருந்து நாங்கள் தண்ணீர் புறப்படப்பண்ணுவோமோ என்று சொல்லி,", "en": "And Moses and Aaron gathered the congregation together before the rock, and he said unto them, Hear now, ye rebels; must we fetch you water out of this rock?"}, {"verse": 11, "start": 124.96, "end": 138.18, "ta": "தன் கையை ஓங்கி, கன்மலையைத் தன் கோலினால் இரண்டுதரம் அடித்தான்; உடனே தண்ணீர் ஏராளமாய்ப் புறப்பட்டது, சபையார் குடித்தார்கள்; அவர்கள் மிருகங்களும் குடித்தது.", "en": "And Moses lifted up his hand, and with his rod he smote the rock twice: and the water came out abundantly, and the congregation drank, and their beasts also ."}, {"verse": 12, "start": 138.18, "end": 156.76, "ta": "பின்பு கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி: இஸ்ரவேல் புத்திரரின் கண்களுக்கு முன்பாக என்னைப் பரிசுத்தம் பண்ணும்படி, நீங்கள் என்னை விசுவாசியாமற் போனபடியினால், இந்தச் சபையாருக்கு நான் கொடுத்த தேசத்திற்குள் அவர்களைக் கொண்டுபோவதில்லை என்றார்.", "en": "And the LORD spake unto Moses and Aaron, Because ye believed me not, to sanctify me in the eyes of the children of Israel, therefore ye shall not bring this congregation into the land which I have given them."}, {"verse": 13, "start": 156.76, "end": 168.73, "ta": "இங்கே இஸ்ரவேல் புத்திரர் கர்த்தரோடே வாக்குவாதம்பண்ணினதினாலும், அவர்களுக்குள்ளே அவருடைய பரிசுத்தம் விளங்கினதினாலும் இது மேரிபாவின் தண்ணீர் என்னப்பட்டது.", "en": "This is the water of Meribah; because the children of Israel strove with the LORD , and he was sanctified in them."}, {"verse": 14, "start": 168.73, "end": 174.16, "ta": "பின்பு மோசே காதேசிலிருந்து ஏதோமின் ராஜாவினிடத்துக்கு ஸ்தானாபதிகளை அனுப்பி:", "en": "And Moses sent messengers from Kadesh unto the king of Edom, Thus saith thy brother Israel, Thou knowest all the travail that hath befallen us:"}, {"verse": 15, "start": 174.16, "end": 191.71, "ta": "எங்கள் பிதாக்கள் எகிப்துக்குப் போனதும், நாங்கள் எகிப்திலே நெடுநாள் வாசம்பண்ணினதும், எகிப்தியர் எங்களை எங்கள் பிதாக்களையும் உபத்திரவப்படுத்தினதும், இவைகளினால் எங்களுக்கு நேரிட்ட எல்லா வருத்தமும் உமக்குத் தெரிந்திருக்கிறது.", "en": "How our fathers went down into Egypt, and we have dwelt in Egypt a long time; and the Egyptians vexed us, and our fathers:"}, {"verse": 16, "start": 191.71, "end": 208.46, "ta": "கர்த்தரை நோக்கி நாங்கள் மன்றாடினோம்; அவர் எங்களுக்குச் செவிகொடுத்து, ஒரு தூதனை அனுப்பி, எங்களை எகிப்திலிருந்து புறப்படப்பண்ணினார்; இப்பொழுது நாங்கள் உமது எல்லைக்கு உட்பட்ட காதேஸ் ஊரில் வந்திருக்கிறோம்.", "en": "And when we cried unto the LORD , he heard our voice, and sent an angel, and hath brought us forth out of Egypt: and, behold, we are in Kadesh, a city in the uttermost of thy border:"}, {"verse": 17, "start": 208.46, "end": 236.58, "ta": "நாங்கள் உமது தேசத்தின் வழியாய்க் கடந்துபோகும்படி உத்தரவு கொடுக்கவேண்டும்; வயல்வெளிகள் வழியாகவும், திராட்சத்தோட்டங்கள் வழியாகவும் நாங்கள் போகாமலும், துரவுகளின் தண்ணீரை குடியாமலும், ராஜபாதையாகவே நடந்து, உமது எல்லையைக் கடந்துபோகுமட்டும், வலதுபுறமும் இடதுபுறமும் சாயாதிருப்போம் என்று, உமது சகோதரனாகிய இஸ்ரவேல் சொல்லி அனுப்புகிறான் என்று சொல்லச் சொன்னான்.", "en": "Let us pass, I pray thee, through thy country: we will not pass through the fields, or through the vineyards, neither will we drink of the water of the wells: we will go by the king’s high way, we will not turn to the right hand nor to the left, until we have passed thy borders."}, {"verse": 18, "start": 236.58, "end": 248.26, "ta": "அதற்கு ஏதோம்: நீ என் தேசத்தின் வழியாய்க் கடந்துபோகக் கூடாது; போனால் பட்டயத்தோடே உன்னை எதிர்க்கப் புறப்படுவேன் என்று அவனுக்குச் சொல்லச் சொன்னான்.", "en": "And Edom said unto him, Thou shalt not pass by me, lest I come out against thee with the sword."}, {"verse": 19, "start": 248.26, "end": 266.54, "ta": "அப்பொழுது இஸ்ரவேல் புத்திரர் அவனை நோக்கி: நடப்பான பாதையின் வழியாய் போவோம்; நாங்களும் எங்கள் மிருகங்களும் உன் தண்ணீரைக் குடித்தால் அதற்குக் கிரயங்கொடுப்போம்; வேறொன்றும் செய்யாமல், கால்நடையாய் மாத்திரம் கடந்துபோவோம் என்றார்கள்.", "en": "And the children of Israel said unto him, We will go by the high way: and if I and my cattle drink of thy water, then I will pay for it: I will only, without doing any thing else , go through on my feet."}, {"verse": 20, "start": 266.54, "end": 275.72, "ta": "அதற்கு அவன்: நீ கடந்துபோகக் கூடாது என்று சொல்லி, வெகு ஜனங்களோடும் பலத்த கையோடும் அவர்களை எதிர்க்கப் புறப்பட்டான்.", "en": "And he said, Thou shalt not go through. And Edom came out against him with much people, and with a strong hand."}, {"verse": 21, "start": 275.72, "end": 286.52, "ta": "இப்படி ஏதோம் தன் எல்லைவழியாய்க் கடந்துபோகும்படி இஸ்ரவேலருக்கு உத்தரவு கொடுக்கவில்லை; ஆகையால் இஸ்ரவேலர் அவனை விட்டு விலகிப்போனார்கள்.", "en": "Thus Edom refused to give Israel passage through his border: wherefore Israel turned away from him."}, {"verse": 22, "start": 286.52, "end": 294.81, "ta": "இஸ்ரவேல் புத்திரரான சபையார் எல்லாரும் காதேசை விட்டுப் பிரயாணப்பட்டு, ஓர் என்னும் மலைக்குப் போனார்கள்.", "en": "And the children of Israel, even the whole congregation, journeyed from Kadesh, and came unto mount Hor."}, {"verse": 23, "start": 294.81, "end": 301.42, "ta": "ஏதோம் தேசத்தின் எல்லைக்கு அருகான ஓர் என்னும் மலையிலே கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:", "en": "And the LORD spake unto Moses and Aaron in mount Hor, by the coast of the land of Edom, saying,"}, {"verse": 24, "start": 301.42, "end": 317.87, "ta": "ஆரோன் தன் ஜனத்தாரோடே சேர்க்கப்படுவான். மேரிபாவின் தண்ணீரைப்பற்றிய காரியத்தில் நீங்கள் என் வாக்குக்குக் கீழ்ப்படியாமற்போனபடியினால், நான் இஸ்ரவேல் புத்திரருக்குக் கொடுக்கிற தேசத்தில் அவன் பிரவேசிப்பதில்லை.", "en": "Aaron shall be gathered unto his people: for he shall not enter into the land which I have given unto the children of Israel, because ye rebelled against my word at the water of Meribah."}, {"verse": 25, "start": 317.87, "end": 325.44, "ta": "நீ ஆரோனையும் அவன் குமாரனாகிய எலெயாசாரையும் கூட்டிக்கொண்டு, அவர்களை ஓர் என்னும் மலையில் ஏறப்பண்ணி,", "en": "Take Aaron and Eleazar his son, and bring them up unto mount Hor:"}, {"verse": 26, "start": 325.44, "end": 338.36, "ta": "ஆரோன் உடுத்திருக்கிற வஸ்திரங்களைக் கழற்றி, அவைகளை அவன் குமாரனாகிய எலெயாசாருக்கு உடுத்துவாயாக; ஆரோன் அங்கே மரித்து, தன் ஜனத்தாரோடே சேர்க்கப்படுவான் என்றார்.", "en": "And strip Aaron of his garments, and put them upon Eleazar his son: and Aaron shall be gathered unto his people , and shall die there."}, {"verse": 27, "start": 338.36, "end": 347.25, "ta": "கர்த்தர் கட்டளையிட்டபடியே மோசே செய்தான்; சபையார் எல்லாரும் பார்க்க அவர்கள் ஓர் என்னும் மலையில் ஏறினார்கள்.", "en": "And Moses did as the LORD commanded: and they went up into mount Hor in the sight of all the congregation."}, {"verse": 28, "start": 347.25, "end": 364.21, "ta": "அங்கே ஆரோன் உடுத்திருந்த வஸ்திரங்களை மோசே கழற்றி, அவைகளை அவன் குமாரனாகிய எலெயாசாருக்கு உடுத்தினான்; அப்பொழுது ஆரோன் அங்கே மலையின் உச்சியிலே மரித்தான்; பின்பு மோசேயும் எலெயாசாரும் மலையிலிருந்து இறங்கினார்கள்.", "en": "And Moses stripped Aaron of his garments, and put them upon Eleazar his son; and Aaron died there in the top of the mount: and Moses and Eleazar came down from the mount."}, {"verse": 29, "start": 364.21, "end": 375.15, "ta": "ஆரோன் ஜீவித்துப்போனான் என்பதைச் சபையார் எல்லோரும் கண்டபோது, இஸ்ரவேல் வம்சத்தார் எல்லாரும் ஆரோனுக்காக முப்பது நாள் துக்கங்கொண்டாடினார்கள்.", "en": "And when all the congregation saw that Aaron was dead, they mourned for Aaron thirty days, even all the house of Israel."}]}, "21": {"chapter": 21, "duration": 431.25, "audio_url": "audio_ot/OT04_21.mp3", "total_verses": 35, "verses": [{"verse": 1, "start": 3.8, "end": 19.34, "ta": "வேவுகாரர் காண்பித்த வழியாக இஸ்ரவேலர் வருகிறார்கள் என்று தெற்கே வாசம்பண்ணுகிற கானானியனாகிய ஆராத் ராஜா கேள்விப்பட்டபோது, அவன் இஸ்ரவேலருக்கு விரோதமாக யுத்தம் பண்ணி, அவர்களில் சிலரை சிறைபிடித்துக்கொண்டுபோனான்.", "en": "And when king Arad the Canaanite, which dwelt in the south, heard tell that Israel came by the way of the spies; then he fought against Israel, and took some of them prisoners."}, {"verse": 2, "start": 19.34, "end": 31.83, "ta": "அப்பொழுது இஸ்ரவேலர் கர்த்தரை நோக்கி: தேவரீர் இந்த ஜனங்களை எங்கள் கையில் ஒப்புக்கொடுத்தால், அவர்களுடைய பட்டணங்களைச் சங்காரம் பண்ணுவோம் என்று பிரதிக்கினை பண்ணினார்கள்.", "en": "And Israel vowed a vow unto the LORD , and said, If thou wilt indeed deliver this people into my hand, then I will utterly destroy their cities."}, {"verse": 3, "start": 31.83, "end": 46.95, "ta": "கர்த்தர் இஸ்ரவேலின் சத்தத்துக்குச் செவிகொடுத்து, அவர்களுக்குக் கானானியரை ஒப்புக்கொடுத்தார்; அப்பொழுது அவர்களையும் அவர்கள் பட்டணங்களையும் சங்காரம்பண்ணி, அவ்விடத்திற்கு ஓர்மா என்று பேரிட்டார்கள்.", "en": "And the LORD hearkened to the voice of Israel, and delivered up the Canaanites; and they utterly destroyed them and their cities: and he called the name of the place Hormah."}, {"verse": 4, "start": 46.95, "end": 60.22, "ta": "அவர்கள் ஏதோம் தேசத்தைச் சுற்றிப்போகும்படிக்கு, ஓர் என்னும் மலையைவிட்டு, சிவந்த சமுத்திரத்தின் வழியாய்ப் பிரயாணம்பண்ணினார்கள்; வழியினிமித்தம் ஜனங்கள் மனமடிவடைந்தார்கள்.", "en": "And they journeyed from mount Hor by the way of the Red sea, to compass the land of Edom: and the soul of the people was much discouraged because of the way."}, {"verse": 5, "start": 60.22, "end": 79.08, "ta": "ஜனங்கள் தேவனுக்கும் மோசேக்கும் விரோதமாகப் பேசி: நாங்கள் வனாந்தரத்திலே சாகும்படி நீங்கள் எங்களை எகிப்து தேசத்திலிருந்து வரப்பண்ணினதென்ன? இங்கே அப்பமும் இல்லை, தண்ணீரும் இல்லை; இந்த அற்பமான உணவு எங்கள் மனதுக்கு வெறுப்பாயிருக்கிறது என்றார்கள்.", "en": "And the people spake against God, and against Moses, Wherefore have ye brought us up out of Egypt to die in the wilderness? for there is no bread, neither is there any water; and our soul loatheth this light bread."}, {"verse": 6, "start": 79.08, "end": 90.37, "ta": "அப்பொழுது கர்த்தர் கொள்ளிவாய்ச்சர்ப்பங்களை ஜனங்களுக்குள்ளே அனுப்பினார்; அவைகள் ஜனங்களைக் கடித்ததினால் இஸ்ரவேலருக்குள்ளே அநேக ஜனங்கள் செத்தார்கள்.", "en": "And the LORD sent fiery serpents among the people, and they bit the people; and much people of Israel died."}, {"verse": 7, "start": 90.37, "end": 108.59, "ta": "அதினால் ஜனங்கள் மோசேயினிடத்தில் போய்: நாங்கள் கர்த்தருக்கும் உமக்கும் விரோதமாய்ப் பேசினதினால் பாவஞ்செய்தோம்; சர்ப்பங்கள் எங்களைவிட்டு நீங்கும்படி கர்த்தரை நோக்கி விண்ணப்பம் பண்ணவேண்டும் என்றார்கள்; மோசே ஜனங்களுக்காக விண்ணப்பம் பண்ணினான்.", "en": "Therefore the people came to Moses, and said, We have sinned, for we have spoken against the LORD , and against thee; pray unto the LORD , that he take away the serpents from us. And Moses prayed for the people."}, {"verse": 8, "start": 108.59, "end": 123.07, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ ஒரு கொள்ளிவாய்ச் சர்ப்பத்தின் உருவத்தைச் செய்து, அதை ஒரு கம்பத்தின்மேல் தூக்கிவை; கடிக்கப்பட்டவன் எவனோ அவன் அதை நோக்கிப்பார்த்தால் பிழைப்பான் என்றார்.", "en": "And the LORD said unto Moses, Make thee a fiery serpent, and set it upon a pole: and it shall come to pass, that every one that is bitten, when he looketh upon it, shall live."}, {"verse": 9, "start": 123.07, "end": 137.12, "ta": "அப்படியே மோசே ஒரு வெண்கலச் சர்ப்பத்தை உண்டாக்கி, அதை ஒரு கம்பத்தின்மேல் தூக்கிவைத்தான்; சர்ப்பம் ஒருவனைக் கடித்தபோது, அவன் அந்த வெண்கலச் சர்ப்பத்தை நோக்கிப்பார்த்துப் பிழைப்பான்.", "en": "And Moses made a serpent of brass, and put it upon a pole, and it came to pass, that if a serpent had bitten any man, when he beheld the serpent of brass, he lived."}, {"verse": 10, "start": 137.12, "end": 142.84, "ta": "இஸ்ரவேல் புத்திரர் பிரயாணப்பட்டுப்போய், ஓபோத்தில் பாளயமிறங்கினார்கள்.", "en": "And the children of Israel set forward, and pitched in Oboth."}, {"verse": 11, "start": 142.84, "end": 152.87, "ta": "ஓபோத்திலிருந்து பிரயாணம் பண்ணி, சூரியோதயத்திற்கு நேராய் மோவாபுக்கு எதிரான வனாந்தரத்திலுள்ள அபாரீமின் மேடுகளில் பாளயமிறங்கினார்கள்.", "en": "And they journeyed from Oboth, and pitched at Ije-abarim, in the wilderness which is before Moab, toward the sunrising."}, {"verse": 12, "start": 152.87, "end": 159.15, "ta": "அங்கேயிருந்து பிரயாணப்பட்டுப் போய், சாரேத் பள்ளத்தாக்கிலே பாளயமிறங்கினார்கள்.", "en": "From thence they removed, and pitched in the valley of Zared."}, {"verse": 13, "start": 159.15, "end": 175.82, "ta": "அங்கேயிருந்து பிரயாணப்பட்டுப் போய், எமோரியரின் எல்லையிலிருந்து வருகிறதும் வனாந்தரத்தில் ஓடுகிறதுமான அர்னோன் ஆற்றுக்கு இப்புறம் பாளயமிறங்கினார்கள்; அந்த அர்னோன் மோவாபுக்கும் எமோரியருக்கும் நடுவே இருக்கிற மோவாபின் எல்லை.", "en": "From thence they removed, and pitched on the other side of Arnon, which is in the wilderness that cometh out of the coasts of the Amorites: for Arnon is the border of Moab, between Moab and the Amorites."}, {"verse": 14, "start": 175.82, "end": 180.41, "ta": "அதினால் சூப்பாவிலுள்ள வாகேபும், அர்னோனின் ஆற்றுக்கால்களும்,", "en": "Wherefore it is said in the book of the wars of the LORD , What he did in the Red sea, and in the brooks of Arnon,"}, {"verse": 15, "start": 180.41, "end": 191.21, "ta": "ஆர் என்னும் ஸ்தலத்துக்குப் பாயும் நீரோடையும் மோவாபின் எல்லையைச் சார்ந்திருக்கிறது என்னும் வசனம் கர்த்தருடைய யுத்த புஸ்தகத்தில் எழுதியிருக்கிறது.", "en": "And at the stream of the brooks that goeth down to the dwelling of Ar, and lieth upon the border of Moab."}, {"verse": 16, "start": 191.21, "end": 203.43, "ta": "அங்கேயிருந்து பேயேருக்குப் போனார்கள்; ஜனங்களைக் கூடிவரச்செய், அவர்களுக்குத் தண்ணீர் கொடுப்பேன் என்று கர்த்தர் மோசேக்குச் சொன்ன ஊற்று இருக்கிற இடம் அதுதான்.", "en": "And from thence they went to Beer: that is the well whereof the LORD spake unto Moses, Gather the people together, and I will give them water."}, {"verse": 17, "start": 203.43, "end": 211.69, "ta": "அப்பொழுது இஸ்ரவேலர் பாடின பாட்டாவது: ஊற்றுத் தண்ணீரே, பொங்கிவா; அதைக்குறித்துப் பாடுவோம் வாருங்கள்.", "en": "Then Israel sang this song, Spring up, O well; sing ye unto it:"}, {"verse": 18, "start": 211.69, "end": 223.13, "ta": "நியாயப்பிரமாணிக்கனின் ஏவுதலால் அதிபதிகள் கிணற்றைத் தோண்டினார்கள்; ஜனத்தில் மேன்மக்கள் தங்கள் தண்டாயுதங்களைக்கொண்டு தோண்டினார்கள் என்று பாடினார்கள்.", "en": "The princes digged the well, the nobles of the people digged it, by the direction of the lawgiver, with their staves. And from the wilderness they went to Mattanah:"}, {"verse": 19, "start": 223.13, "end": 231.53, "ta": "அந்த வனாந்தரத்திலிருந்து மாத்தனாவுக்கும், மாத்தனாவிலிருந்து நகாலியேலுக்கும், நகாலியேலிலிருந்து பாமோத்துக்கும்,", "en": "And from Mattanah to Nahaliel: and from Nahaliel to Bamoth:"}, {"verse": 20, "start": 231.53, "end": 240.08, "ta": "பள்ளத்தாக்கிலுள்ள மோவாபின் வெளியில் இருக்கிற பாமோத்திலிருந்து எஷிமோனை நோக்கும் பிஸ்காவின் உச்சிக்கும் போனார்கள்.", "en": "And from Bamoth in the valley, that is in the country of Moab, to the top of Pisgah, which looketh toward Jeshimon."}, {"verse": 21, "start": 240.08, "end": 245.44, "ta": "அப்பொழுது இஸ்ரவேலர் எமோரியரின் ராஜாவாகிய சீகோனிடத்தில் ஸ்தானாபதிகளை அனுப்பி:", "en": "And Israel sent messengers unto Sihon king of the Amorites, saying,"}, {"verse": 22, "start": 245.44, "end": 264.09, "ta": "உமது தேசத்தின் வழியாய்க் கடந்துபோகும்படி உத்தரவு கொடுக்க வேண்டும்; நாங்கள் வயல்களிலும், திராட்சத்தோட்டங்களிலும் போகாமலும், துரவுகளின் தண்ணீரைக் குடியாமலும், உமது எல்லையைக் கடந்துபோகுமட்டும் ராஜபாதையில் நடந்துபோவோம் என்று சொல்லச்சொன்னார்கள்.", "en": "Let me pass through thy land: we will not turn into the fields, or into the vineyards; we will not drink of the waters of the well: but we will go along by the king’s high way, until we be past thy borders."}, {"verse": 23, "start": 264.09, "end": 279.69, "ta": "சீகோன் தன் எல்லைவழியாய்க் கடந்துபோக இஸ்ரவேலுக்கு உத்தரவு கொடாமல், தன் ஜனங்களெல்லாரையும் கூட்டிக்கொண்டு, இஸ்ரவேலருக்கு விரோதமாக வனாந்தரத்திலே புறப்பட்டு, யாகாசுக்கு வந்து, இஸ்ரவேலரோடே யுத்தம்பண்ணினான்.", "en": "And Sihon would not suffer Israel to pass through his border: but Sihon gathered all his people together, and went out against Israel into the wilderness: and he came to Jahaz, and fought against Israel."}, {"verse": 24, "start": 279.69, "end": 295.44, "ta": "இஸ்ரவேலர் அவனைப் பட்டயக்கருக்கினால் வெட்டி, அர்னோன் தொடங்கி அம்மோன் புத்திரரின் தேசத்தைச்சார்ந்த யாப்போக்குவரைக்குமுள்ள அவனுடைய தேசத்தைக் கட்டிக்கொண்டார்கள்; அம்மோன் புத்திரரின் எல்லை அரணிப்பானதாயிருந்தது.", "en": "And Israel smote him with the edge of the sword, and possessed his land from Arnon unto Jabbok, even unto the children of Ammon: for the border of the children of Ammon was strong."}, {"verse": 25, "start": 295.44, "end": 306.74, "ta": "இஸ்ரவேலர் அந்தப் பட்டணங்கள் யாவையும் பிடித்து, எஸ்போனிலும் அதைச் சார்ந்த எல்லாக் கிராமங்களிலும் எமோரியருடைய எல்லாப்பட்டணங்களிலும் குடியிருந்தார்கள்.", "en": "And Israel took all these cities: and Israel dwelt in all the cities of the Amorites, in Heshbon, and in all the villages thereof."}, {"verse": 26, "start": 306.74, "end": 322.13, "ta": "எஸ்போனானது எமோரியரின் ராஜாவாகிய சீகோனின் பட்டணமாயிருந்தது; அவன் மோவாபியரின் முந்தின ராஜாவுக்கு விரோதமாக யுத்தம்பண்ணி, அர்னோன் வரைக்கும் இருந்த அவன் தேசத்தையெல்லாம் அவன் கையிலிருந்து பறித்துக்கொண்டான்.", "en": "For Heshbon was the city of Sihon the king of the Amorites, who had fought against the former king of Moab, and taken all his land out of his hand, even unto Arnon."}, {"verse": 27, "start": 322.13, "end": 329.76, "ta": "அதினாலே கவிகட்டுகிறவர்கள்: எஸ்போனுக்கு வாருங்கள்; சீகோனின் பட்டணம் ஸ்திரமாய்க் கட்டப்படுவதாக.", "en": "Wherefore they that speak in proverbs say, Come into Heshbon, let the city of Sihon be built and prepared:"}, {"verse": 28, "start": 329.76, "end": 342.26, "ta": "எஸ்போனிலிருந்து அக்கினியும் சீகோனுடைய பட்டணத்திலிருந்து ஜுவாலையும் புறப்பட்டு, மோவாபுடைய ஆர் என்னும் ஊரையும், அர்னோனுடைய மேடுகளிலுள்ள ஆண்டவமார்களையும் பட்சித்தது.", "en": "For there is a fire gone out of Heshbon, a flame from the city of Sihon: it hath consumed Ar of Moab, and the lords of the high places of Arnon."}, {"verse": 29, "start": 342.26, "end": 355.04, "ta": "ஐயோ, மோவாபே, கேமோஷ் தேவனின் ஜனமே, நீ நாசமானாய்; தப்பி ஓடின தன் குமாரரையும் தன் குமாரத்திகளையும் எமோரியரின் ராஜாவாகிய சீகோனுக்குச் சிறைகளாக ஒப்புக்கொடுத்தான்.", "en": "Woe to thee, Moab! thou art undone, O people of Chemosh: he hath given his sons that escaped, and his daughters, into captivity unto Sihon king of the Amorites."}, {"verse": 30, "start": 355.04, "end": 367.68, "ta": "அவர்களை எய்துபோட்டோம்; எஸ்போன் பட்டணம் தீபோன் ஊர்வரைக்கும் நாசமாயிற்று; மேதேபாவுக்குச் சமீபமான நோப்பா பட்டணபரியந்தம் அவர்களைப் பாழாக்கினோம் என்று பாடினார்கள்.", "en": "We have shot at them; Heshbon is perished even unto Dibon, and we have laid them waste even unto Nophah, which reacheth unto Medeba."}, {"verse": 31, "start": 367.68, "end": 372.41, "ta": "இஸ்ரவேலர் இப்படியே எமோரியரின் தேசத்திலே குடியிருந்தார்கள்.", "en": "Thus Israel dwelt in the land of the Amorites."}, {"verse": 32, "start": 372.41, "end": 385.19, "ta": "பின்பு, மோசே யாசேர் பட்டணத்துக்கு வேவு பார்க்கிறவர்களை அனுப்பினான்; அவர்கள் அதைச்சேர்ந்த கிராமங்களைக் கட்டிக்கொண்டு, அங்கே இருந்த எமோரியரைத் துரத்திவிட்டார்கள்.", "en": "And Moses sent to spy out Jaazer, and they took the villages thereof, and drove out the Amorites that were there."}, {"verse": 33, "start": 385.19, "end": 400.09, "ta": "பின்பு பாசானுக்குப் போகிற வழியாய்த் திரும்பிவிட்டார்கள்; அப்பொழுது பாசான் ராஜாவாகிய ஓக் என்பவன் தன் சமஸ்த ஜன்ங்களோடும் அவர்களை எதிர்த்து யுத்தம்பண்ணும்படிக்கு, எத்ரேயுக்குப் புறப்பட்டு வந்தான்.", "en": "And they turned and went up by the way of Bashan: and Og the king of Bashan went out against them, he, and all his people, to the battle at Edrei."}, {"verse": 34, "start": 400.09, "end": 418.03, "ta": "கர்த்தர் மோசேயை நோக்கி: அவனுக்குப் பயப்படவேண்டாம்; அவனையும் அவன் ஜனங்கள் எல்லாரையும், அவன் தேசத்தையும் உன் கையில் ஒப்புக்கொடுத்தேன்; எஸ்போனிலே வாசமாயிருந்த எமோரியரின் ராஜாவாகிய சீகோனுக்கு நீ செய்தபடியே இவனுக்கும் செய்வாய் என்றார்.", "en": "And the LORD said unto Moses, Fear him not: for I have delivered him into thy hand, and all his people, and his land; and thou shalt do to him as thou didst unto Sihon king of the Amorites, which dwelt at Heshbon."}, {"verse": 35, "start": 418.03, "end": 429.75, "ta": "அப்படியே ஒருவரும் உயிருடன் மீதியாயிராதபடிக்கு அவனையும், அவன் குமாரரையும், அவனுடைய சகல ஜனங்களையும் வெட்டிப்போட்டு, அவன் தேசத்தைக் கட்டிக்கொண்டார்கள்.", "en": "So they smote him, and his sons, and all his people, until there was none left him alive: and they possessed his land."}]}, "22": {"chapter": 22, "duration": 504.44, "audio_url": "audio_ot/OT04_22.mp3", "total_verses": 41, "verses": [{"verse": 1, "start": 3.8, "end": 14.37, "ta": "பின்பு இஸ்ரவேல் புத்திரர் பிரயாணம் பண்ணி, எரிகோவின் கிட்ட இருக்கும் யோர்தானுக்கு இக்கரையிலே மோவாபின் சமனான வெளிகளில் பாளயமிறங்கினார்கள்.", "en": "And the children of Israel set forward, and pitched in the plains of Moab on this side Jordan by Jericho."}, {"verse": 2, "start": 14.37, "end": 20.52, "ta": "இஸ்ரவேலர் எமோரியருக்குச் செய்த யாவையும் சிப்போரின் குமாரனாகிய பாலாக் கண்டான்.", "en": "And Balak the son of Zippor saw all that Israel had done to the Amorites."}, {"verse": 3, "start": 20.52, "end": 28.02, "ta": "ஜனங்கள் ஏராளமாயிருந்தபடியினால், மோவாப் மிகவும் பயந்து, இஸ்ரவேல் புத்திரரினிமித்தம் கலக்கமடைந்து,", "en": "And Moab was sore afraid of the people, because they were many: and Moab was distressed because of the children of Israel."}, {"verse": 4, "start": 28.02, "end": 44.38, "ta": "மீதியானரின் மூப்பரை நோக்கி: மாடு வெளியின் புல்லை மேய்கிறதுபோல, இப்பொழுது இந்தக் கூட்டம் நம்மைச் சுற்றியிருக்கிற யாவையும் மேய்ந்துபோடும் என்றான் அக்காலத்திலே சிப்போரின் குமாரனாகிய பாலாக் மோவாபியருக்கு ராஜாவாயிருந்தான்.", "en": "And Moab said unto the elders of Midian, Now shall this company lick up all that are round about us, as the ox licketh up the grass of the field. And Balak the son of Zippor was king of the Moabites at that time."}, {"verse": 5, "start": 44.38, "end": 63.32, "ta": "அவன் பேயோரின் குமாரனாகிய பிலேயாமை அழைத்துவரும்படி, தன் சந்ததியாருடைய தேசத்தில் நதியருகேயுள்ள பெத்தூருக்கு ஸ்தானாபதிகளை அனுப்பி: எகிப்திலிருந்து ஒரு ஜனக்கூட்டம் வந்திருக்கிறது; அவர்கள் பூமியின் விசாலத்தை மூடி, எனக்கு எதிரே இறங்கியிருக்கிறார்கள்.", "en": "He sent messengers therefore unto Balaam the son of Beor to Pethor, which is by the river of the land of the children of his people, to call him, saying, Behold, there is a people come out from Egypt: behold, they cover the face of the earth, and they abide over against me:"}, {"verse": 6, "start": 63.32, "end": 87.61, "ta": "அவர்கள் என்னிலும் பலவான்கள்; ஆகிலும், நீர் ஆசீர்வதிக்கிறவன் ஆசீர்வதிக்கப்பட்டவன், நீர் சபிக்கிறவன் சபிக்கப்பட்டவன் என்று அறிவேன்; ஆதலால், நீர் வந்து, எனக்காக அந்த ஜனத்தைச் சபிக்கவேண்டும்; அப்பொழுது ஒருவேளை நான் அவர்களை முறிய அடித்து, அவர்களை இத்தேசத்திலிருந்து துரத்திவிடலாம் என்று சொல்லச்சொன்னான்.", "en": "Come now therefore, I pray thee, curse me this people; for they are too mighty for me: peradventure I shall prevail, that we may smite them, and that I may drive them out of the land: for I wot that he whom thou blessest is blessed, and he whom thou cursest is cursed."}, {"verse": 7, "start": 87.61, "end": 102.04, "ta": "அப்படியே மோவாபின் மூப்பரும் மீதியானின் மூப்பரும் குறிசொல்லுதலுக்குரிய கூலியைத் தங்கள் கையில் எடுத்துக்கொண்டு புறப்பட்டு, பிலேயாமிடத்தில் போய், பாலாகின் வார்த்தைகளை அவனுக்குச் சொன்னார்கள்.", "en": "And the elders of Moab and the elders of Midian departed with the rewards of divination in their hand; and they came unto Balaam, and spake unto him the words of Balak."}, {"verse": 8, "start": 102.04, "end": 116.9, "ta": "அவன் அவர்களை நோக்கி: இராத்திரிக்கு இங்கே தங்கியிருங்கள்; கர்த்தர் எனக்குச் சொல்லுகிறபடியே உங்களுக்கு உத்தரவு கொடுப்பேன் என்றான்; அப்படியே மோவாபின் பிரபுக்கள் பிலேயாமிடத்தில் தங்கினார்கள்.", "en": "And he said unto them, Lodge here this night, and I will bring you word again, as the LORD shall speak unto me: and the princes of Moab abode with Balaam."}, {"verse": 9, "start": 116.9, "end": 122.83, "ta": "தேவன் பிலேயாமிடத்தில் வந்து: உன்னிடத்திலிருக்கிற இந்த மனிதர் யார் என்றார்.", "en": "And God came unto Balaam, and said, What men are these with thee?"}, {"verse": 10, "start": 122.83, "end": 130.34, "ta": "பிலேயாம் தேவனை நோக்கி: சிப்போரின் குமாரனாகிய பாலாக் என்னும் மோவாபின் ராஜா அவர்களை என்னிடத்துக்கு அனுப்பி:", "en": "And Balaam said unto God, Balak the son of Zippor, king of Moab, hath sent unto me, saying ,"}, {"verse": 11, "start": 130.34, "end": 148.7, "ta": "பூமியின் விசாலத்தை மூடுகிற ஒரு ஜனக்கூட்டம் எகிப்திலிருந்து வந்திருக்கிறது; ஆகையால், நீ வந்து எனக்காக அவர்களைச் சபிக்கவேண்டும்; அப்பொழுது நான் அவர்களோடே யுத்தம் பண்ணி, ஒருவேளை அவர்களைத் துரத்திவிடலாம் என்று சொல்லச்சொன்னான் என்றான்.", "en": "Behold, there is a people come out of Egypt, which covereth the face of the earth: come now, curse me them; peradventure I shall be able to overcome them, and drive them out."}, {"verse": 12, "start": 148.7, "end": 159.77, "ta": "அதற்குத் தேவன் பிலேயாமை நோக்கி: நீ அவர்களோடே போகவேண்டாம்; அந்த ஜனங்களைச் சபிக்கவும் வேண்டாம்; அவர்கள் ஆசீர்வதிக்கப்பட்டவர்கள் என்றார்.", "en": "And God said unto Balaam, Thou shalt not go with them; thou shalt not curse the people: for they are blessed."}, {"verse": 13, "start": 159.77, "end": 174.78, "ta": "பிலேயாம் காலமே எழுந்து, பாலாகின் பிரபுக்களை நோக்கி: நீங்கள் உங்கள் தேசத்திற்குப் போய்விடுங்கள்; நான் உங்களோடேகூட வருகிறதற்குக் கர்த்தர் எனக்கு உத்தரவு கொடுக்கமாட்டோம் என்கிறார் என்று சொன்னான்.", "en": "And Balaam rose up in the morning, and said unto the princes of Balak, Get you into your land: for the LORD refuseth to give me leave to go with you."}, {"verse": 14, "start": 174.78, "end": 184.14, "ta": "அப்படியே மோவாபியருடைய பிரபுக்கள் எழுந்து, பாலாகினிடத்தில் போய்: பிலேயாம் எங்களோடே வரமாட்டேன் என்று சொன்னான் என்றார்கள்.", "en": "And the princes of Moab rose up, and they went unto Balak, and said, Balaam refuseth to come with us."}, {"verse": 15, "start": 184.14, "end": 189.71, "ta": "பாலாக் மறுபடியும் அவர்களிலும் கனவான்களான அதிக பிரபுக்களை அனுப்பினான்.", "en": "And Balak sent yet again princes, more, and more honourable than they."}, {"verse": 16, "start": 189.71, "end": 199.93, "ta": "அவர்கள் பிலேயாமிடத்தில் போய், அவனை நோக்கி: சிப்போரின் குமாரனாகிய பாலாக் எங்களை அனுப்பி: நீர் என்னிடத்தில் வருகிறதற்குத் தடைபடவேண்டாம்;", "en": "And they came to Balaam, and said to him, Thus saith Balak the son of Zippor, Let nothing, I pray thee, hinder thee from coming unto me:"}, {"verse": 17, "start": 199.93, "end": 211.57, "ta": "உம்மை மிகவும் கனம்பண்ணுவேன்; நீர் சொல்வதையெல்லாம் செய்வேன்; நீர் வந்து எனக்காக அந்த ஜனங்களைச் சபிக்கவேண்டும் என்று சொல்லச்சொன்னார் என்றார்கள்.", "en": "For I will promote thee unto very great honour, and I will do whatsoever thou sayest unto me: come therefore, I pray thee, curse me this people."}, {"verse": 18, "start": 211.57, "end": 228.36, "ta": "பிலேயாம் பாலாகின் ஊழியக்காரருக்கு பிரதியுத்தரமாக: பாலாக் எனக்குத் தன் வீடு நிறைய வெள்ளியும் பொன்னும் தந்தாலும், சிறிய காரியமானாலும் பெரியகாரியமானாலும் செய்யும்பொருட்டு, என் தேவனாகிய கர்த்தரின் கட்டளையை நான் மீறக் கூடாது.", "en": "And Balaam answered and said unto the servants of Balak, If Balak would give me his house full of silver and gold, I cannot go beyond the word of the LORD my God, to do less or more."}, {"verse": 19, "start": 228.36, "end": 238.51, "ta": "ஆகிலும், கர்த்தர் இனிமேல் எனக்கு என்ன சொல்லுவார் என்பதை நான் அறியும்படிக்கு நீங்களும் இந்த இராத்திரி இங்கே தங்கியிருங்கள் என்றான்.", "en": "Now therefore, I pray you, tarry ye also here this night, that I may know what the LORD will say unto me more."}, {"verse": 20, "start": 238.51, "end": 252.8, "ta": "இரவிலே தேவன் பிலேயாமிடத்தில் வந்து: அந்த மனிதர் உன்னைக் கூப்பிட வந்திருந்தால், நீ அவர்களோடே கூடப்போ; ஆனாலும் நான் உனக்குச் சொல்லும் வார்த்தையின்படிமாத்திரம் நீ செய்யவேண்டும் என்றார்.", "en": "And God came unto Balaam at night, and said unto him, If the men come to call thee, rise up, and go with them; but yet the word which I shall say unto thee, that shalt thou do."}, {"verse": 21, "start": 252.8, "end": 260.16, "ta": "பிலேயாம் காலமே எழுந்து, தன் கழுதையின்மேல் சேணங்கட்டி, மோவாபின் பிரபுக்களோடேகூடப் போனான்.", "en": "And Balaam rose up in the morning, and saddled his ass, and went with the princes of Moab."}, {"verse": 22, "start": 260.16, "end": 275.95, "ta": "அவன் போகிறதினாலே தேவனுக்குக் கோபம் மூண்டது; கர்த்தருடைய தூதனானவர் வழியிலே அவனுக்கு எதிராளியாக நின்றார். அவன் தன் கழுதையின் மேல் ஏறிப்போனான்; அவன் வேலைக்காரர் இரண்டுபேரும் அவனோடே இருந்தார்கள்.", "en": "And God’s anger was kindled because he went: and the angel of the LORD stood in the way for an adversary against him. Now he was riding upon his ass, and his two servants were with him."}, {"verse": 23, "start": 275.95, "end": 290.88, "ta": "கர்த்தருடைய தூதனானவர் உருவின பட்டயத்தைத் தம்முடைய கையிலே பிடித்துக்கொண்டு வழியிலே நிற்கிறதைக் கழுதை கண்டு, வழியை விட்டு வயலிலே விலகிப்போயிற்று; கழுதையை வழியில் திருப்ப பிலேயாம் அதை அடித்தான்.", "en": "And the ass saw the angel of the LORD standing in the way, and his sword drawn in his hand: and the ass turned aside out of the way, and went into the field: and Balaam smote the ass, to turn her into the way."}, {"verse": 24, "start": 290.88, "end": 298.74, "ta": "கர்த்தருடைய தூதனானவர் இருபுறத்திலும் சுவர் வைத்திருந்த திராட்சத் தோட்டங்களின் பாதையிலே போய் நின்றார்.", "en": "But the angel of the LORD stood in a path of the vineyards, a wall being on this side, and a wall on that side."}, {"verse": 25, "start": 298.74, "end": 308.81, "ta": "கழுதை கர்த்தருடைய தூதனைக்கண்டு, சுவர் ஓரமாய் ஒதுங்கி, பிலேயாமின் காலைச் சுவரோடே நெருக்கிற்று; திரும்பவும் அதை அடித்தான்.", "en": "And when the ass saw the angel of the LORD , she thrust herself unto the wall, and crushed Balaam’s foot against the wall: and he smote her again."}, {"verse": 26, "start": 308.81, "end": 317.32, "ta": "அப்பொழுது கர்த்தருடைய தூதன் அப்புறம் போய், வலதுபுறம் இடதுபுறம் விலக வழியில்லாத இடுக்கமான இடத்திலே நின்றார்.", "en": "And the angel of the LORD went further, and stood in a narrow place, where was no way to turn either to the right hand or to the left."}, {"verse": 27, "start": 317.32, "end": 327.82, "ta": "கழுதை கர்த்தருடைய தூதனைக் கண்டு, பிலேயாமின் கீழ்ப் படுத்துக்கொண்டது; பிலேயாம் கோபம் மூண்டவனாகி, கழுதையைத் தடியினால் அடித்தான்.", "en": "And when the ass saw the angel of the LORD , she fell down under Balaam: and Balaam’s anger was kindled, and he smote the ass with a staff."}, {"verse": 28, "start": 327.82, "end": 339.32, "ta": "உடனே கர்த்தர் கழுதையின் வாயைத் திறந்தார்; அது பிலேயாமைப் பார்த்து: நீர் என்னை இப்பொழுது மூன்று தரம் அடிக்கும்படி நான் உமக்கு என்ன செய்தேன் என்றது.", "en": "And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?"}, {"verse": 29, "start": 339.32, "end": 352.33, "ta": "அப்பொழுது பிலேயாம் கழுதையைப் பார்த்து: நீ என்னைப் பரியாசம் பண்ணிக்கொண்டு வருகிறாய்; என் கையில் ஒரு பட்டயம்மாத்திரம் இருந்தால் இப்பொழுதே உன்னைக் கொன்றுபோடுவேன் என்றான்.", "en": "And Balaam said unto the ass, Because thou hast mocked me: I would there were a sword in mine hand, for now would I kill thee."}, {"verse": 30, "start": 352.33, "end": 367.33, "ta": "கழுதை பிலேயாமை நோக்கி: நீர் என்னைக் கைக்கொண்ட காலமுதல் இந்நாள்வரைக்கும் நீர் ஏறின கழுதை நான் அல்லவா? இப்படி உமக்கு எப்போதாகிலும் நான் செய்தது உண்டா என்றது. அதற்கு அவன்: இல்லை என்றான்.", "en": "And the ass said unto Balaam, Am not I thine ass, upon which thou hast ridden ever since I was thine unto this day? was I ever wont to do so unto thee? And he said, Nay."}, {"verse": 31, "start": 367.33, "end": 381.05, "ta": "அப்பொழுது கர்த்தர் பிலேயாமின் கண்களைத் திறந்தார்; வழியிலே நின்று உருவின பட்டத்தைத் தம்முடைய கையிலே பிடித்திருக்கிற தூதனைக் கண்டு, தலைகுனிந்து முகங்குப்புற விழுந்து பணிந்தான்.", "en": "Then the LORD opened the eyes of Balaam, and he saw the angel of the LORD standing in the way, and his sword drawn in his hand: and he bowed down his head, and fell flat on his face."}, {"verse": 32, "start": 381.05, "end": 394.2, "ta": "கர்த்தருடைய தூதனானவர் அவனை நோக்கி: நீ உன் கழுதையை இதனோடே மூன்றுதரம் அடித்ததென்ன? உன் வழி எனக்கு மாறுபாடாயிருக்கிறதினால், நான் உனக்கு எதிரியாகப் புறப்பட்டு வந்தேன்.", "en": "And the angel of the LORD said unto him, Wherefore hast thou smitten thine ass these three times? behold, I went out to withstand thee, because thy way is perverse before me:"}, {"verse": 33, "start": 394.2, "end": 406.91, "ta": "கழுதை என்னைக் கண்டு, இந்த மூன்று தரம் எனக்கு விலகிற்று; எனக்கு விலகாமல் இருந்ததானால், இப்பொழுது நான் உன்னை கொன்றுபோட்டு, கழுதையை உயிரோடே வைப்பேன் என்றார்.", "en": "And the ass saw me, and turned from me these three times: unless she had turned from me, surely now also I had slain thee, and saved her alive."}, {"verse": 34, "start": 406.91, "end": 423.77, "ta": "அப்பொழுது பிலேயாம் கர்த்தருடைய தூதனை நோக்கி: நான் பாவஞ்செய்தேன்; வழியிலே நீர் எனக்கு எதிராக நிற்கிறதை அறியாதிருந்தேன்; இப்பொழுதும் உமது பார்வைக்கு இது தகாததாயிருக்குமானால், நான் திரும்பிப் போய்விடுகிறேன் என்றான்.", "en": "And Balaam said unto the angel of the LORD , I have sinned; for I knew not that thou stoodest in the way against me: now therefore, if it displease thee, I will get me back again."}, {"verse": 35, "start": 423.77, "end": 438.28, "ta": "கர்த்தருடைய தூதனானவர் பிலேயாமை நோக்கி: அந்த மனிதரோடே கூடப்போ; நான் உன்னோடே சொல்லும் வார்த்தையைமாத்திரம் நீ சொல்லக்கடவாய் என்றார்; அப்படியே பிலேயாம் பாலாகின் பிரபுக்களோடேகூடப் போனான்.", "en": "And the angel of the LORD said unto Balaam, Go with the men: but only the word that I shall speak unto thee, that thou shalt speak. So Balaam went with the princes of Balak."}, {"verse": 36, "start": 438.28, "end": 449.14, "ta": "பிலேயாம் வருகிறதைப் பாலாக் கேட்டமாத்திரத்தில், கடைசி எல்லையான அர்னோன் நதியின் ஓரத்திலுள்ள மோவாபின் பட்டணமட்டும் அவனுக்கு எதிர்கொண்டு போனான்.", "en": "And when Balak heard that Balaam was come, he went out to meet him unto a city of Moab, which is in the border of Arnon, which is in the utmost coast."}, {"verse": 37, "start": 449.14, "end": 463.5, "ta": "பாலாக் பிலேயாமை நோக்கி: உம்மை அழைக்கும்படி நான் ஆவலோடே உம்மிடத்தில் ஆள் அனுப்பவில்லையா? என்னிடத்திற்கு வராமல் இருந்ததென்ன? ஏற்றபிரகாரமாக உம்மை நான் கனம் பண்ணமாட்டேனா என்றான்.", "en": "And Balak said unto Balaam, Did I not earnestly send unto thee to call thee? wherefore camest thou not unto me? am I not able indeed to promote thee to honour?"}, {"verse": 38, "start": 463.5, "end": 476.93, "ta": "அப்பொழுது பிலேயாம் பாலாகை நோக்கி: இதோ, உம்மிடத்திற்கு வந்தேன்; ஆனாலும் ஏதாகிலும் சொல்லுகிறதற்கு என்னாலே ஆகுமோ: தேவன் என் வாயிலே அளிக்கும் வார்த்தையையே சொல்லுவேன் என்றான்.", "en": "And Balaam said unto Balak, Lo, I am come unto thee: have I now any power at all to say any thing? the word that God putteth in my mouth, that shall I speak."}, {"verse": 39, "start": 476.93, "end": 483.22, "ta": "பிலேயாம் பாலாகுடனேகூடப் போனான்; அவர்கள் கீரியாத் ஊசோத்தில் சேர்ந்தார்கள்.", "en": "And Balaam went with Balak, and they came unto Kirjath-huzoth."}, {"verse": 40, "start": 483.22, "end": 490.44, "ta": "அங்கே பாலாக் ஆடுமாடுகளை அடித்து, பிலேயாமுக்கும் அவனோடிருந்த பிரபுக்களுக்கும் அனுப்பினான்.", "en": "And Balak offered oxen and sheep, and sent to Balaam, and to the princes that were with him."}, {"verse": 41, "start": 490.44, "end": 502.94, "ta": "மறுநாள் காலமே பாலாக் பிலேயாமைக் கூட்டிக்கொண்டு, அவனைப் பாகாலுடைய மேடுகளில் ஏறப்பண்ணினான்; அவ்விடத்திலிருந்து பிலேயாம் ஜனத்தின் கடைசிப் பாளயத்தைப் பார்த்தான்.", "en": "And it came to pass on the morrow, that Balak took Balaam, and brought him up into the high places of Baal, that thence he might see the utmost part of the people."}]}, "23": {"chapter": 23, "duration": 346.13, "audio_url": "audio_ot/OT04_23.mp3", "total_verses": 30, "verses": [{"verse": 1, "start": 3.8, "end": 14.77, "ta": "பிலேயாம் பாலாகை நோக்கி: நீர் இங்கே எனக்கு ஏழு பலிபீடங்களைக் கட்டி, ஏழு காளைகளையும் ஏழு ஆட்டுக்கடாக்களையும் இங்கே எனக்கு ஆயத்தப்படுத்தும் என்றான்.", "en": "And Balaam said unto Balak, Build me here seven altars, and prepare me here seven oxen and seven rams."}, {"verse": 2, "start": 14.77, "end": 25.19, "ta": "பிலேயாம் சொன்னபடியே பாலாக் செய்தான்; பாலாகும் பிலேயாமும் ஒவ்வொரு பீடத்தில் ஒவ்வொரு காளையையும் ஒவ்வொரு ஆட்டுக்கடாவையும் பலியிட்டார்கள்.", "en": "And Balak did as Balaam had spoken; and Balak and Balaam offered on every altar a bullock and a ram."}, {"verse": 3, "start": 25.19, "end": 43.08, "ta": "பின்பு பிலேயாம் பாலாகை நோக்கி: உம்முடைய சர்வாங்க தகனபலியண்டையில் நில்லும், நான் போய்வருகிறேன்; கர்த்தர் வந்து என்னைச் சந்திக்கிறதாயிருக்கும்; அவர் எனக்கு வெளிப்படுத்துவதை உமக்கு அறிவிப்பேன் என்று சொல்லி, ஒரு மேட்டின்மேல் ஏறினான்.", "en": "And Balaam said unto Balak, Stand by thy burnt offering, and I will go: peradventure the LORD will come to meet me: and whatsoever he sheweth me I will tell thee. And he went to an high place."}, {"verse": 4, "start": 43.08, "end": 56.85, "ta": "தேவன் பிலேயாமைச் சந்தித்தார்; அப்பொழுது அவன் அவரை நோக்கி: நான் ஏழு பலிபீடங்களை ஆயத்தம் பண்ணி, ஒவ்வொரு பலிபீடத்தில் ஒவ்வொரு காளையையும் ஒவ்வொரு ஆட்டுக்கடாவையும் பலியிட்டேன் என்றான்.", "en": "And God met Balaam: and he said unto him, I have prepared seven altars, and I have offered upon every altar a bullock and a ram."}, {"verse": 5, "start": 56.85, "end": 65.45, "ta": "கர்த்தர் பிலேயாமின் வாயிலே வாக்கு அருளி: நீ பாலாகினிடத்தில் திரும்பிப்போய், இவ்விதமாய்ச் சொல்லக்கடவாய் என்றார்.", "en": "And the LORD put a word in Balaam’s mouth, and said, Return unto Balak, and thus thou shalt speak."}, {"verse": 6, "start": 65.45, "end": 75.31, "ta": "அவனிடத்துக்கு அவன் திரும்பிபோனான்; பாலாக் மோவாபுடைய சகல பிரபுக்களோடுங்கூடத் தன் சர்வாங்க தகனபலியண்டையிலே நின்றுகொண்டிருந்தான்.", "en": "And he returned unto him, and, lo, he stood by his burnt sacrifice, he, and all the princes of Moab."}, {"verse": 7, "start": 75.31, "end": 91.94, "ta": "அப்பொழுது அவன் தன் வாக்கியத்தை எடுத்துரைத்து: மோவாபின் ராஜாவாகிய பாலாக் என்னைக் கிழக்கு மலைகளிலுள்ள ஆராமிலிருந்து வரவழைத்து: நீ வந்து எனக்காக யாக்கோபைச் சபிக்கவேண்டும்; நீ வந்து இஸ்ரவேலை வெறுத்து விடவேண்டும் என்று சொன்னான்.", "en": "And he took up his parable, and said, Balak the king of Moab hath brought me from Aram, out of the mountains of the east, saying , Come, curse me Jacob, and come, defy Israel."}, {"verse": 8, "start": 91.94, "end": 98.79, "ta": "தேவன் சபிக்காதவனை நான் சபிப்பதெப்படி? கர்த்தர் வெறுக்காதவனை நான் வெறுப்பதெப்படி?", "en": "How shall I curse, whom God hath not cursed? or how shall I defy, whom the LORD hath not defied?"}, {"verse": 9, "start": 98.79, "end": 109.63, "ta": "கன்மலையுச்சியிலிருந்து நான் அவனைக் கண்டு, குன்றுகளிலிருந்து அவனைப் பார்க்கிறேன்; அந்த ஜனங்கள் ஜாதிகளோடே கலவாமல் தனியே வாசமாயிருப்பார்கள்.", "en": "For from the top of the rocks I see him, and from the hills I behold him: lo, the people shall dwell alone, and shall not be reckoned among the nations."}, {"verse": 10, "start": 109.63, "end": 122.91, "ta": "யாக்கோபின் தூளை எண்ணத்தக்கவன் யார்? இஸ்ரவேலின் காற்பங்கை எண்ணுகிறவன் யார்? நீதிமான் மரிப்பது போல் நான் மரிப்பேனாக, என் முடிவு அவன் முடிவுபோல் இருப்பதாக என்றான்.", "en": "Who can count the dust of Jacob, and the number of the fourth part of Israel? Let me die the death of the righteous, and let my last end be like his!"}, {"verse": 11, "start": 122.91, "end": 135.77, "ta": "அப்பொழுது பாலாக் பிலேயாமை நோக்கி: நீர் எனக்கு என்னசெய்தீர்; என் சத்துருக்களைச் சபிக்கும்படி உம்மை அழைப்பித்தேன்; நீர் அவர்களை ஆசீர்வதிக்கவே ஆசீர்வதித்தீர் என்றான்.", "en": "And Balak said unto Balaam, What hast thou done unto me? I took thee to curse mine enemies, and, behold, thou hast blessed them altogether."}, {"verse": 12, "start": 135.77, "end": 141.64, "ta": "அதற்கு அவன்: கர்த்தர் என் வாயில் அருளினதையே சொல்வது என் கடமையல்லவா என்றான்.", "en": "And he answered and said, Must I not take heed to speak that which the LORD hath put in my mouth?"}, {"verse": 13, "start": 141.64, "end": 159.47, "ta": "பின்பு பாலாக் அவனை நோக்கி: நீர் அவர்களைப் பார்க்கத்தக்க வேறொரு இடத்திற்கு என்னோடேகூட வாரும்; அங்கே அவர்கள் எல்லாரையும் பாராமல், அவர்களுடைய கடைசிப் பாளயத்தைமாத்திரம் பார்ப்பீர்; அங்கேயிருந்து எனக்காக அவர்களைச் சபிக்கவேண்டும் என்று சொல்லி,", "en": "And Balak said unto him, Come, I pray thee, with me unto another place, from whence thou mayest see them: thou shalt see but the utmost part of them, and shalt not see them all: and curse me them from thence."}, {"verse": 14, "start": 159.47, "end": 173.17, "ta": "அவனைப் பிஸ்காவின் கொடுமுடியில் இருக்கிற சோப்பீமீன் வெளியிலே அழைத்துக்கொண்டுபோய், ஏழு பலி பீடங்களைக் கட்டி, ஒவ்வொரு பீடத்தில் ஒவ்வொரு காளையையும் ஒவ்வொரு ஆட்டுக்கடாவையும் பலியிட்டான்.", "en": "And he brought him into the field of Zophim, to the top of Pisgah, and built seven altars, and offered a bullock and a ram on every altar."}, {"verse": 15, "start": 173.17, "end": 184.0, "ta": "அப்பொழுது பிலேயாம் பாலாகை நோக்கி: இங்கே உம்முடைய சர்வாங்க தகனபலியண்டையில் நில்லும்; நான் அங்கே போய்க் கர்த்தரைச் சந்தித்துவருகிறேன் என்றான்.", "en": "And he said unto Balak, Stand here by thy burnt offering, while I meet the Lord yonder."}, {"verse": 16, "start": 184.0, "end": 194.14, "ta": "கர்த்தர் பிலேயாமைச் சந்தித்து, அவன் வாயிலே வசனத்தை அருளி: நீ பாலாகினிடத்திற்குத் திரும்பிபோய், இவ்விதமாய்ச் சொல்லக்கடவாய் என்றார்.", "en": "And the LORD met Balaam, and put a word in his mouth, and said, Go again unto Balak, and say thus."}, {"verse": 17, "start": 194.14, "end": 207.84, "ta": "அவனிடத்திற்கு அவன் வருகிறபோது, அவன் மோவாபின் பிரபுக்களோடுங்கூடத் தன்னுடைய சர்வாங்கதகனபலியண்டையிலே நின்றுகொண்டிருந்தான்; பாலாக் அவனை நோக்கி: கர்த்தர் என்ன சொன்னார் என்று கேட்டான்.", "en": "And when he came to him, behold, he stood by his burnt offering, and the princes of Moab with him. And Balak said unto him, What hath the LORD spoken?"}, {"verse": 18, "start": 207.84, "end": 217.41, "ta": "அப்பொழுது அவன் தன் வாக்கியத்தை எடுத்துரைத்து: பாலாகே, எழுந்திருந்து கேளும்; சிப்போரின் குமாரனே, எனக்குச் செவிகொடும்.", "en": "And he took up his parable, and said, Rise up, Balak, and hear; hearken unto me, thou son of Zippor:"}, {"verse": 19, "start": 217.41, "end": 229.51, "ta": "பொய் சொல்ல தேவன் ஒரு மனிதன் அல்ல; மனம்மாற அவர் ஒரு மனுபுத்திரனும் அல்ல; அவர் சொல்லியும் செய்யாதிருப்பாரா? அவர் வசனித்தும் நிறைவேற்றாதிருப்பாரா?", "en": "God is not a man, that he should lie; neither the son of man, that he should repent: hath he said, and shall he not do it ? or hath he spoken, and shall he not make it good?"}, {"verse": 20, "start": 229.51, "end": 236.84, "ta": "இதோ, ஆசீர்வதிக்கக் கட்டளைபெற்றேன்; அவர் ஆசீர்வதிக்கிறார், அதை நான் திருப்பக் கூடாது.", "en": "Behold, I have received commandment to bless: and he hath blessed; and I cannot reverse it."}, {"verse": 21, "start": 236.84, "end": 251.73, "ta": "அவர் யாக்கோபிலே அக்கிரமத்தைக் காண்கிறதும் இல்லை, இஸ்ரவேலிலே குற்றம் பார்க்கிறதும் இல்லை; அவர்களுடைய தேவனாகிய கர்த்தர் அவர்களோடே இருக்கிறார்; ராஜாவின் ஜயகெம்பீரம் அவர்களுக்குள்ளே இருக்கிறது.", "en": "He hath not beheld iniquity in Jacob, neither hath he seen perverseness in Israel: the LORD his God is with him, and the shout of a king is among them."}, {"verse": 22, "start": 251.73, "end": 259.56, "ta": "தேவன் அவர்களை எகிப்திலிருந்து புறப்படப்பண்ணினார்; காண்டாமிருகத்துக்கொத்த பெலன் அவர்களுக்கு உண்டு.", "en": "God brought them out of Egypt; he hath as it were the strength of an unicorn."}, {"verse": 23, "start": 259.56, "end": 273.68, "ta": "யாக்கோபுக்கு விரோதமான மந்திரவாதம் இல்லை, இஸ்ரவேலுக்கு விரோதமான குறிசொல்லுதலும் இல்லை; தேவன் என்னென்ன செய்தார் என்று கொஞ்சக் காலத்திலே யாக்கோபையும் இஸ்ரவேலையும் குறித்துச் சொல்லப்படும்.", "en": "Surely there is no enchantment against Jacob, neither is there any divination against Israel: according to this time it shall be said of Jacob and of Israel, What hath God wrought!"}, {"verse": 24, "start": 273.68, "end": 288.08, "ta": "அந்த ஜனம் துஷ்ட சிங்கம்போல எழும்பும், பால சிங்கம்போல நிமிர்ந்து நிற்கும்; அது தான் பிடித்த இரையைப் பட்சித்து, வெட்டுண்டவர்களின் இரத்தத்தைக் குடிக்குமட்டும் படுத்துக்கொள்வதில்லை என்றான்.", "en": "Behold, the people shall rise up as a great lion, and lift up himself as a young lion: he shall not lie down until he eat of the prey, and drink the blood of the slain."}, {"verse": 25, "start": 288.08, "end": 296.68, "ta": "அப்பொழுது பாலாக் பிலேயாமை நோக்கி: நீர் அவர்களைச் சபிக்கவும் வேண்டாம், அவர்களை ஆசீர்வதிக்கவும் வேண்டாம் என்றான்.", "en": "And Balak said unto Balaam, Neither curse them at all, nor bless them at all."}, {"verse": 26, "start": 296.68, "end": 305.49, "ta": "அதற்குப் பிலேயாம் பாலாகைப் பார்த்து: கர்த்தர் சொல்லுகிறபடியெல்லாம் செய்வேன் என்று உம்மோடே நான் சொல்லவில்லையா என்றான்.", "en": "But Balaam answered and said unto Balak, Told not I thee, saying, All that the LORD speaketh, that I must do?"}, {"verse": 27, "start": 305.49, "end": 319.05, "ta": "அப்பொழுது பாலாக் பிலேயாமை நோக்கி: வாரும் வேறொரு இடத்திற்கு உம்மை அழைத்துக்கொண்டு போகிறேன்; நீர் அங்கேயிருந்தாவது எனக்காக அவர்களைச் சபிக்கிறது தேவனுக்குப் பிரியமாயிருக்கும் என்று சொல்லி,", "en": "And Balak said unto Balaam, Come, I pray thee, I will bring thee unto another place; peradventure it will please God that thou mayest curse me them from thence."}, {"verse": 28, "start": 319.05, "end": 325.06, "ta": "அவனை எஷிமோனுக்கு எதிராயிருக்கிற பேயோரின் கொடுமுடிக்கு அழைத்துக்கொண்டு போனான்.", "en": "And Balak brought Balaam unto the top of Peor, that looketh toward Jeshimon."}, {"verse": 29, "start": 325.06, "end": 336.31, "ta": "அப்பொழுது பிலேயாம் பாலாகை நோக்கி: இங்கே எனக்கு ஏழு பலிபீடங்களைக் கட்டி, இங்கே எனக்கு ஏழு காளைகளையும் ஏழு ஆட்டுக் கடாக்களையும் ஆயத்தம்பண்ணும் என்றான்.", "en": "And Balaam said unto Balak, Build me here seven altars, and prepare me here seven bullocks and seven rams."}, {"verse": 30, "start": 336.31, "end": 344.63, "ta": "பிலேயாம் சொன்னபடி பாலாக் செய்து, ஒவ்வொரு பீடத்தில் ஒவ்வொரு காளையையும் ஒவ்வொரு ஆட்டுக்கடாவையும் பலியிட்டான்.", "en": "And Balak did as Balaam had said, and offered a bullock and a ram on every altar."}]}, "24": {"chapter": 24, "duration": 281.28, "audio_url": "audio_ot/OT04_24.mp3", "total_verses": 25, "verses": [{"verse": 1, "start": 3.8, "end": 16.81, "ta": "இஸ்ரவேலை ஆசீர்வதிப்பதே கர்த்தருக்குப் பிரியம் என்று பிலேயாம் கண்ட போது, அவன் முந்திச் செய்துவந்தது போல நிமித்தம்பார்க்கப் போகாமல், வனாந்தரத்திற்கு நேராக தன் முகத்தைத் திருப்பி,", "en": "And when Balaam saw that it pleased the LORD to bless Israel, he went not, as at other times, to seek for enchantments, but he set his face toward the wilderness."}, {"verse": 2, "start": 16.81, "end": 26.23, "ta": "தன் கண்களை ஏறெடுத்து, இஸ்ரவேல் தன் கோத்திரங்களின்படியே பாளயமிறங்கியிருக்கிறதைப் பார்த்தான்; தேவ ஆவி அவன்மேல் வந்தது.", "en": "And Balaam lifted up his eyes, and he saw Israel abiding in his tents according to their tribes; and the spirit of God came upon him."}, {"verse": 3, "start": 26.23, "end": 35.44, "ta": "அப்பொழுது அவன் தன் வாக்கியத்தை எடுத்துரைத்து: பேயோரின் குமாரனாகிய பிலேயாம் சொல்லுகிறதாவது, கண் திறக்கப்பட்டவன் உரைக்கிறதாவது,", "en": "And he took up his parable, and said, Balaam the son of Beor hath said, and the man whose eyes are open hath said:"}, {"verse": 4, "start": 35.44, "end": 44.51, "ta": "தேவன் அருளும் வார்த்தைகளைக் கேட்டு, சர்வவல்லவரின் தரிசனத்தைக் கண்டு தாழ விழும் போது, கண்திறக்கப்பட்டவன் விளம்புகிறதாவது,", "en": "He hath said, which heard the words of God, which saw the vision of the Almighty, falling into a trance , but having his eyes open:"}, {"verse": 5, "start": 44.51, "end": 50.49, "ta": "யாக்கோபே, உன் கூடாரங்களும், இஸ்ரவேலே, உன் வாசஸ்தலங்களும் எவ்வளவு அழகானவைகள்!", "en": "How goodly are thy tents, O Jacob, and thy tabernacles, O Israel!"}, {"verse": 6, "start": 50.49, "end": 63.92, "ta": "அவைகள் பரவிப்போகிற ஆறுகளைப் போலவும், நதியோரத்திலுள்ள தோட்டங்களைப்போலவும், கர்த்தர் நாட்டின சந்தனமரங்களைப்போலவும், தண்ணீர் அருகே உள்ள கேதுரு விருட்சங்களைப்போலவும் இருக்கிறது.", "en": "As the valleys are they spread forth, as gardens by the river’s side, as the trees of lign aloes which the LORD hath planted, and as cedar trees beside the waters."}, {"verse": 7, "start": 63.92, "end": 77.7, "ta": "அவர்களுடைய நீர்ச்சால்களிலிருந்து தண்ணீர் பாயும்; அவர்கள் வித்து திரளான தண்ணீர்களில் பரவும்; அவர்களுடைய ராஜா ஆகாகைப் பார்க்கிலும் உயருவான்; அவர்கள் ராஜ்யம் மேன்மையடையும்.", "en": "He shall pour the water out of his buckets, and his seed shall be in many waters, and his king shall be higher than Agag, and his kingdom shall be exalted."}, {"verse": 8, "start": 77.7, "end": 94.93, "ta": "தேவன் அவர்களை எகிப்திலிருந்து புறப்படப்பண்ணினார்; காண்டாமிருகத்துக்கொத்த பெலன் அவர்களுக்கு உண்டு; அவர்கள் தங்கள் சத்துருக்களாகிய ஜாதிகளைப் பட்சித்து, அவர்கள் எலும்புகளை நொறுக்கி, அவர்களைத் தங்கள் அம்புகளாலே எய்வார்கள்.", "en": "God brought him forth out of Egypt; he hath as it were the strength of an unicorn: he shall eat up the nations his enemies, and shall break their bones, and pierce them through with his arrows."}, {"verse": 9, "start": 94.93, "end": 110.47, "ta": "சிங்கம்போலவும் துஷ்ட சிங்கம்போலவும் மடங்கிப் படுத்துக்கொண்டிருக்கிறார்கள்; அவர்களை எழுப்புகிறவன் யார்? உங்களை ஆசீர்வதிக்கிறவன் ஆசீர்வதிக்கப்பட்டவன், உங்களைச் சபிக்கிறவன் சபிக்கப்பட்டவன் என்றான்.", "en": "He couched, he lay down as a lion, and as a great lion: who shall stir him up? Blessed is he that blesseth thee, and cursed is he that curseth thee."}, {"verse": 10, "start": 110.47, "end": 125.93, "ta": "அப்பொழுது பாலாக் பிலேயாமின் மேல் கோபம் மூண்டவனாகி, கையோடே கைதட்டி, பிலேயாமை நோக்கி: என் சத்துருக்களைச் சபிக்க உன்னை அழைத்தனுப்பினேன். நீயோ இந்த மூன்றுமுறையும் அவர்களை ஆசீர்வதிக்கவே ஆசீர்வதித்தாய்.", "en": "And Balak’s anger was kindled against Balaam, and he smote his hands together: and Balak said unto Balaam, I called thee to curse mine enemies, and, behold, thou hast altogether blessed them these three times."}, {"verse": 11, "start": 125.93, "end": 135.64, "ta": "ஆகையால் உன் இடத்துக்கு ஓடிப்போ; உன்னை மிகவும் கனம்பண்ணுவேன் என்றேன்; நீ கனமடையாதபடிக்குக் கர்த்தர் தடுத்தார் என்றான்.", "en": "Therefore now flee thou to thy place: I thought to promote thee unto great honour; but, lo, the LORD hath kept thee back from honour."}, {"verse": 12, "start": 135.64, "end": 152.16, "ta": "அப்பொழுது பிலேயாம் பாலாகை நோக்கி: பாலாக் எனக்கு தன் வீடு நிறைய வெள்ளியும் பொன்னும் கொடுத்தாலும், நான் என் மனதாய் நன்மையாகிலும் தீமையாகிலும் செய்கிறதற்குக் கர்த்தரின் கட்டளையை மீறக் கூடாது; கர்த்தர் சொல்வதையே சொல்வேன் என்று,", "en": "And Balaam said unto Balak, Spake I not also to thy messengers which thou sentest unto me, saying,"}, {"verse": 13, "start": 152.16, "end": 157.58, "ta": "நீர் என்னிடத்திற்கு அனுப்பின ஸ்தானாபதிகளிடத்தில் நான் சொல்லவில்லையா?", "en": "If Balak would give me his house full of silver and gold, I cannot go beyond the commandment of the LORD , to do either good or bad of mine own mind; but what the LORD saith, that will I speak?"}, {"verse": 14, "start": 157.58, "end": 169.32, "ta": "இதோ, நான் என் ஜனத்தாரிடத்திற்குப் போகிறேன்; பிற்காலத்திலே இந்த ஜனங்கள் உம்முடைய ஜனங்களுக்குச் செய்வது இன்னதென்று உமக்குத் தெரிவிப்பேன் வாரும் என்று சொல்லி,", "en": "And now, behold, I go unto my people: come therefore, and I will advertise thee what this people shall do to thy people in the latter days."}, {"verse": 15, "start": 169.32, "end": 177.61, "ta": "அவன் தன் வாக்கியத்தை எடுத்துரைத்து: பேயோரின் குமாரன் பிலேயாம் சொல்லுகிறதாவது, கண் திறக்கப்பட்டவன் உரைக்கிறதாவது,", "en": "And he took up his parable, and said, Balaam the son of Beor hath said, and the man whose eyes are open hath said:"}, {"verse": 16, "start": 177.61, "end": 189.36, "ta": "தேவன் அருளும் வார்த்தைகளைக் கேட்டு, உன்னதமானவர் அளித்த அறிவை அறிந்து, சர்வவல்லவரின் தரிசனத்தைக் கண்டு தாழவிழும்போது, கண்திறக்கப்பட்டவன் விளம்புகிறதாவது;", "en": "He hath said, which heard the words of God, and knew the knowledge of the most High, which saw the vision of the Almighty, falling into a trance , but having his eyes open:"}, {"verse": 17, "start": 189.36, "end": 208.06, "ta": "அவரைக் காண்பேன், இப்பொழுது அல்ல; அவரைத் தரிசிப்பேன், சமீபமாய் அல்ல; ஒரு நட்சத்திரம் யாக்கோபிலிருந்து உதிக்கும், ஒரு செங்கோல் இஸ்ரவேலிலிருந்து எழும்பும்; அது மோவாபின் எல்லைகளை நொறுக்கி, சேத்புத்திரர் எல்லாரையும் நிர்மூலமாக்கும்.", "en": "I shall see him, but not now: I shall behold him, but not nigh: there shall come a Star out of Jacob, and a Sceptre shall rise out of Israel, and shall smite the corners of Moab, and destroy all the children of Sheth."}, {"verse": 18, "start": 208.06, "end": 216.01, "ta": "ஏதோம் சுதந்தரமாகும், சேயீர் தன் சத்துருக்களுக்குச் சுதந்தரமாகும்; இஸ்ரவேல் பராக்கிரமஞ்செய்யும்.", "en": "And Edom shall be a possession, Seir also shall be a possession for his enemies; and Israel shall do valiantly."}, {"verse": 19, "start": 216.01, "end": 223.67, "ta": "யாக்கோபிலிருந்து தோன்றும் ஒருவர் ஆளுகை செய்வார்; பட்டணங்களில் மீதியானவர்களை அழிப்பார் என்றான்.", "en": "Out of Jacob shall come he that shall have dominion, and shall destroy him that remaineth of the city."}, {"verse": 20, "start": 223.67, "end": 235.41, "ta": "மேலும், அவன் அமலேக்கைப் பார்த்து, தன் வாக்கியத்தை எடுத்துரைத்து: அமலேக்கு முந்தியெழும்பினவன்; ஆனாலும் அவன் முடிவிலே முற்றிலும் நாசமடைவான் என்றான்.", "en": "And when he looked on Amalek, he took up his parable, and said, Amalek was the first of the nations; but his latter end shall be that he perish for ever."}, {"verse": 21, "start": 235.41, "end": 245.61, "ta": "அன்றியும் அவன் கேனியனைப் பார்த்து, தன் வாக்கியத்தை எடுத்துரைத்து: உன் வாசஸ்தலம் அரணிப்பானது; உன் கூட்டைக் கன்மலையில் கட்டினாய்.", "en": "And he looked on the Kenites, and took up his parable, and said, Strong is thy dwellingplace, and thou puttest thy nest in a rock."}, {"verse": 22, "start": 245.61, "end": 253.55, "ta": "ஆகிலும் கேனியன் அழிந்துபோவான்; அசூர் உன்னைச் சிறைபிடித்துக் கொண்டுபோக எத்தனைநாள் செல்லும் என்றான்.", "en": "Nevertheless the Kenite shall be wasted, until Asshur shall carry thee away captive."}, {"verse": 23, "start": 253.55, "end": 260.58, "ta": "பின்னும் அவன் தன் வாக்கியத்தை எடுத்துரைத்து: ஐயோ, தேவன் இதைச் செய்யும்போது யார் பிழைப்பான்;", "en": "And he took up his parable, and said, Alas, who shall live when God doeth this!"}, {"verse": 24, "start": 260.58, "end": 271.98, "ta": "சித்தீமின் கரைதுறையிலிருந்து கப்பல்கள் வந்து, அசூரைச் சிறுமைப் படுத்தி, ஏபேரையும் வருத்தப்படுத்தும்; அவனும் முற்றிலும் அழிந்துபோவான் என்றான்.", "en": "And ships shall come from the coast of Chittim, and shall afflict Asshur, and shall afflict Eber, and he also shall perish for ever."}, {"verse": 25, "start": 271.98, "end": 279.78, "ta": "பின்பு பிலேயாம் எழுந்து புறப்பட்டு, தன் இடத்திற்குத் திரும்பினான்; பாலாகும் தன் வழியே போனான்.", "en": "And Balaam rose up, and went and returned to his place: and Balak also went his way."}]}, "25": {"chapter": 25, "duration": 208.98, "audio_url": "audio_ot/OT04_25.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 12.33, "ta": "இஸ்ரவேல் சித்தீமிலே தங்கியிருக்கையில், ஜனங்கள் மோவாபின் குமாரத்திகளோடே வேசித்தனம் பண்ணத்தொடங்கினார்கள்.", "en": "And Israel abode in Shittim, and the people began to commit whoredom with the daughters of Moab."}, {"verse": 2, "start": 12.33, "end": 24.27, "ta": "அவர்கள் தங்கள் தேவர்களுக்கு இட்ட பலிகளை விருந்துண்ணும்படி ஜனங்களை அழைத்தார்கள்; ஜனங்கள் போய் புசித்து, அவர்கள் தேவர்களைப் பணிந்துக்கொண்டார்கள்.", "en": "And they called the people unto the sacrifices of their gods: and the people did eat, and bowed down to their gods."}, {"verse": 3, "start": 24.27, "end": 32.8, "ta": "இப்படி இஸ்ரவேலர் பாகால்பேயோரைப் பற்றிக்கொண்டார்கள்; அதனால் இஸ்ரவேலர் மேல் கர்த்தருடைய கோபம் மூண்டது.", "en": "And Israel joined himself unto Baal-peor: and the anger of the LORD was kindled against Israel."}, {"verse": 4, "start": 32.8, "end": 50.53, "ta": "கர்த்தர் மோசேயை நோக்கி: கர்த்தருடைய உக்கிரமான கோபம் இஸ்ரவேலை விட்டு நீங்கும்படி நீ ஜனங்களின் தலைவர் எல்லாரையும் கூட்டிக்கொண்டு, அப்படிச் செய்தவர்களைச் சூரியனுக்கு எதிரே கர்த்தருடைய சந்நிதானத்தில் தூக்கிப்போடும்படி செய் என்றார்.", "en": "And the LORD said unto Moses, Take all the heads of the people, and hang them up before the LORD against the sun, that the fierce anger of the LORD may be turned away from Israel."}, {"verse": 5, "start": 50.53, "end": 60.91, "ta": "அப்படியே மோசே இஸ்ரவேலின் நியாயாதிபதிகளை நோக்கி: நீங்கள் அவரவர் பாகால்பேயோரைப் பற்றிக்கொண்ட உங்கள் மனிதரைக் கொன்றுபோடுங்கள் என்றான்.", "en": "And Moses said unto the judges of Israel, Slay ye every one his men that were joined unto Baal-peor."}, {"verse": 6, "start": 60.91, "end": 79.53, "ta": "அப்பொழுது மோசேயும் இஸ்ரவேல் புத்திரராகிய சபையார் அனைவரும் ஆசரிப்புக் கூடாரவாசலுக்கு முன்பாக அழுதுகொண்டு நிற்கையில், அவர்கள் கண்களுக்கு முன்பாக இஸ்ரவேல் புத்திரரில் ஒருவன் ஒரு மீதியானிய ஸ்திரீயைத் தன் சகோதரரிடத்தில் அழைத்துக் கொண்டுவந்தான்.", "en": "And, behold, one of the children of Israel came and brought unto his brethren a Midianitish woman in the sight of Moses, and in the sight of all the congregation of the children of Israel, who were weeping before the door of the tabernacle of the congregation."}, {"verse": 7, "start": 79.53, "end": 90.29, "ta": "அதை ஆசாரியனாகிய ஆரோனின் குமாரனான எலெயாசாரின் மகன் பினெகாஸ் கண்டபோது, அவன் நடுச்சபையிலிருந்து எழுந்து, ஒரு ஈட்டியைத் தன் கையிலே பிடித்து,", "en": "And when Phinehas, the son of Eleazar, the son of Aaron the priest, saw it , he rose up from among the congregation, and took a javelin in his hand;"}, {"verse": 8, "start": 90.29, "end": 108.9, "ta": "இஸ்ரவேலனாகிய அந்த மனிதன் வேசித்தனம்பண்ணும் அறையிலே அவன் பின்னாலே போய், இஸ்ரவேல் மனிதனும் அந்த ஸ்திரீயுமாகிய இருவருடைய வயிற்றிலும் ஈட்டி உருவிப்போக அவர்களைக் குத்திப்போட்டான்; அப்பொழுது இஸ்ரவேல் புத்திரரில் உண்டான வாதை நின்றுபோயிற்று.", "en": "And he went after the man of Israel into the tent, and thrust both of them through, the man of Israel, and the woman through her belly. So the plague was stayed from the children of Israel."}, {"verse": 9, "start": 108.9, "end": 113.21, "ta": "அந்த வாதையால் செத்தவர்கள் இருபத்துநாலாயிரம் பேர்.", "en": "And those that died in the plague were twenty and four thousand."}, {"verse": 10, "start": 113.21, "end": 114.91, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 11, "start": 114.91, "end": 134.27, "ta": "நான் என் எரிச்சலில் இஸ்ரவேல் புத்திரரை நிர்மூலமாக்காதபடிக்கு, ஆசாரியனாகிய ஆரோனின் குமாரனான எலெயாசாரின் மகன் பினெகாஸ், என் நிமித்தம் அவர்கள் நடுவில் பக்திவைராக்கியம் காண்பித்ததினால், இஸ்ரவேல் புத்திரர் மேல் உண்டான என் உக்கிரத்தைத் திருப்பினான்.", "en": "Phinehas, the son of Eleazar, the son of Aaron the priest, hath turned my wrath away from the children of Israel, while he was zealous for my sake among them, that I consumed not the children of Israel in my jealousy."}, {"verse": 12, "start": 134.27, "end": 140.8, "ta": "ஆகையால், இதோ, அவனுக்கு என் சமாதானத்தின் உடன்படிக்கையைக் கட்டளையிடுகிறேன்.", "en": "Wherefore say, Behold, I give unto him my covenant of peace:"}, {"verse": 13, "start": 140.8, "end": 158.9, "ta": "அவன் தன் தேவனுக்காக பக்திவைராக்கியம் காண்பித்து, இஸ்ரவேல் புத்திரருக்காகப் பாவநிவர்த்தி செய்தபடியினால், அவனுக்கும் அவனுக்குப் பின்பு அவன் சந்ததிக்கும் நித்திய ஆசாரிய பட்டத்திற்குரிய உடன்படிக்கை உண்டாயிருக்கும் என்று சொல் என்றார்.", "en": "And he shall have it, and his seed after him, even the covenant of an everlasting priesthood; because he was zealous for his God, and made an atonement for the children of Israel."}, {"verse": 14, "start": 158.9, "end": 171.65, "ta": "மீதியானிய ஸ்திரீயோடே குத்துண்டு செத்த இஸ்ரவேல் மனிதனுடைய பேர் சிம்ரி; அவன் சல்லுூவின் குமாரனும், சிமியோனியரின் தகப்பன் வம்சத்தில் ஒரு பிரபுவுமாயிருந்தான்.", "en": "Now the name of the Israelite that was slain, even that was slain with the Midianitish woman, was Zimri, the son of Salu, a prince of a chief house among the Simeonites."}, {"verse": 15, "start": 171.65, "end": 182.93, "ta": "குத்துண்ட மீதியானிய ஸ்திரீயின் பேர் கஸ்பி, அவள் சூரின் குமாரத்தி, அவன் மீதியானியருடைய தகப்பன் வம்சத்தாரான ஜனங்களுக்குத் தலைவனாயிருந்தான்.", "en": "And the name of the Midianitish woman that was slain was Cozbi, the daughter of Zur; he was head over a people, and of a chief house in Midian."}, {"verse": 16, "start": 182.93, "end": 184.63, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 17, "start": 184.63, "end": 188.79, "ta": "மீதியானியரை நெருக்கி அவர்களை வெட்டிப்போடுங்கள்.", "en": "Vex the Midianites, and smite them:"}, {"verse": 18, "start": 188.79, "end": 207.48, "ta": "பேயோரின் சங்கதியிலும் பேயோரின் நிமித்தம் வாதையுண்டான நாளிலே குத்துண்ட அவர்கள் சகோதரியாகிய கஸ்பி என்னும் மீதியான் பிரபுவினுடைய குமாரத்தியின் சங்கதியிலும், அவர்கள் உங்களுக்குச் செய்த சர்ப்பனைகளினால் உங்களை மோசம்போக்கி நெருக்கினார்களே என்றார்.", "en": "For they vex you with their wiles, wherewith they have beguiled you in the matter of Peor, and in the matter of Cozbi, the daughter of a prince of Midian, their sister, which was slain in the day of the plague for Peor’s sake."}]}, "26": {"chapter": 26, "duration": 670.3, "audio_url": "audio_ot/OT04_26.mp3", "total_verses": 65, "verses": [{"verse": 1, "start": 3.8, "end": 11.7, "ta": "அந்த வாதை தீர்ந்தபின்பு, கர்த்தர் மோசேயையும் ஆரோனின் குமாரனும் ஆசாரியனுமாகிய எலெயாசாரையும் நோக்கி:", "en": "And it came to pass after the plague, that the LORD spake unto Moses and unto Eleazar the son of Aaron the priest, saying,"}, {"verse": 2, "start": 11.7, "end": 26.72, "ta": "இஸ்ரவேல் புத்திரரின் சமஸ்த சபையாரையும் அவர்கள் பிதாக்களுடைய வம்சத்தின்படி இருபது வயதுமுதல் அதற்கு மேற்பட்ட இஸ்ரவேலிலே யுத்ததிற்குப் புறப்படத்தக்கவர்கள் எல்லாரையும் எண்ணுங்கள் என்றார்.", "en": "Take the sum of all the congregation of the children of Israel, from twenty years old and upward, throughout their fathers’ house, all that are able to go to war in Israel."}, {"verse": 3, "start": 26.72, "end": 36.89, "ta": "அப்பொழுது மோசேயும் ஆசாரியனாகிய எலெயாசாரும் எரிகோவின் அருகே இருக்கும் யோர்தானுக்கு இப்பாலே மோவாபின் சமனான வெளிகளிலே அவர்களோடே பேசி:", "en": "And Moses and Eleazar the priest spake with them in the plains of Moab by Jordan near Jericho, saying,"}, {"verse": 4, "start": 36.89, "end": 50.5, "ta": "கர்த்தர் மோசேக்கும் எகிப்துதேசத்திலிருந்து புறப்பட்ட இஸ்ரவேல் புத்திரருக்கும் கட்டளையிட்டிருக்கிறபடியே, இருபது வயதுமுதற்கொண்டிருக்கிறவர்களை எண்ணுங்கள் என்றார்கள்.", "en": "Take the sum of the people , from twenty years old and upward; as the LORD commanded Moses and the children of Israel, which went forth out of the land of Egypt."}, {"verse": 5, "start": 50.5, "end": 63.32, "ta": "ரூபன் இஸ்ரவேலின் மூத்த குமாரன்; ரூபனுடைய குமாரர், ஆனாக்கியர் குடும்பத்துக்குத் தகப்பனான ஆனோக்கும், பல்லுூவியர் குடும்பத்துக்குத் தகப்பனான பல்லுூவும்,", "en": "Reuben, the eldest son of Israel: the children of Reuben; Hanoch, of whom cometh the family of the Hanochites: of Pallu, the family of the Palluites:"}, {"verse": 6, "start": 63.32, "end": 71.69, "ta": "எஸ்ரோனியர் குடும்பத்துக்குத் தகப்பனான எஸ்ரோனும், கர்மீயர் குடும்பத்துக்குத் தகப்பனான கர்மீயுமே.", "en": "Of Hezron, the family of the Hezronites: of Carmi, the family of the Carmites."}, {"verse": 7, "start": 71.69, "end": 80.92, "ta": "இவைகளே ரூபனியரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் நாற்பத்து மூவாயிரத்து எழுநூற்று முப்பதுபேர்.", "en": "These are the families of the Reubenites: and they that were numbered of them were forty and three thousand and seven hundred and thirty."}, {"verse": 8, "start": 80.92, "end": 83.74, "ta": "பல்லுூவின் குமாரன் எலியாப்.", "en": "And the sons of Pallu; Eliab."}, {"verse": 9, "start": 83.74, "end": 105.09, "ta": "எலியாபின் குமாரர் நேமுவேல், தாத்தான், அபிராம் என்பவர்கள்; இந்தத் தாத்தான் அபிராம் என்பவர்களே சபையில் பேர்பெற்றவர்களாயிருந்து, கர்த்தருக்கு விரோதமாகப் போராட்டம் பண்ணி, கோராகின் கூட்டாளிகளாகி, மோசேக்கும் ஆரோனுக்கும் விரோதமாக விவாதம்பண்ணினவர்கள்.", "en": "And the sons of Eliab; Nemuel, and Dathan, and Abiram. This is that Dathan and Abiram, which were famous in the congregation, who strove against Moses and against Aaron in the company of Korah, when they strove against the LORD :"}, {"verse": 10, "start": 105.09, "end": 119.56, "ta": "பூமி தன் வாயைத் திறந்து, அவர்களையும் கோராகையும் விழுங்கினதினாலும், அக்கினி இருநூற்று ஐம்பது பேரைப் பட்சித்ததினாலும், அந்தக் கூட்டத்தார் செத்து, ஒரு அடையாளமானார்கள்.", "en": "And the earth opened her mouth, and swallowed them up together with Korah, when that company died, what time the fire devoured two hundred and fifty men: and they became a sign."}, {"verse": 11, "start": 119.56, "end": 122.38, "ta": "கோராகின் குமாரரோ சாகவில்லை.", "en": "Notwithstanding the children of Korah died not."}, {"verse": 12, "start": 122.38, "end": 136.46, "ta": "சிமியோனுடைய குமாரரின் குடும்பங்களாவன: நேமுவேலின் சந்ததியான நேமுவேலரின் குடும்பமும், யாமினின் சந்ததியான யாமினியரின் குடும்பமும், யாகீனின் சந்ததியான யாகீனியரின் குடும்பமும்,", "en": "The sons of Simeon after their families: of Nemuel, the family of the Nemuelites: of Jamin, the family of the Jaminites: of Jachin, the family of the Jachinites:"}, {"verse": 13, "start": 136.46, "end": 144.04, "ta": "சேராகின் சந்ததியான சேராகியரின் குடும்பமும், சவுலின் சந்ததியான சவுலியரின் குடும்பமுமே.", "en": "Of Zerah, the family of the Zarhites: of Shaul, the family of the Shaulites."}, {"verse": 14, "start": 144.04, "end": 150.93, "ta": "இவைகளே சிமியோனியரின் குடும்பங்கள்; அவர்கள் இருபத்தீராயிரத்து இருநூறுபேர்.", "en": "These are the families of the Simeonites, twenty and two thousand and two hundred."}, {"verse": 15, "start": 150.93, "end": 164.61, "ta": "காத்துடைய குமாரரின் குடும்பங்களாவன: சிப்போனின் சந்ததியான சிப்போனியரின் குடும்பமும், ஆகியின் சந்ததியான ஆகியரின் குடும்பமும், சூனியின் சந்ததியான் சூனியரின் குடும்பமும்,", "en": "The children of Gad after their families: of Zephon, the family of the Zephonites: of Haggi, the family of the Haggites: of Shuni, the family of the Shunites:"}, {"verse": 16, "start": 164.61, "end": 171.58, "ta": "ஒஸ்னியின் சந்ததியான ஒஸ்னியரின் குடும்பமும், ஏரியின் சந்ததியான ஏரியரின் குடும்பமும்,", "en": "Of Ozni, the family of the Oznites: of Eri, the family of the Erites:"}, {"verse": 17, "start": 171.58, "end": 179.16, "ta": "ஆரோதின் சந்ததியான ஆரோதியரின் குடும்பமும், அரேலியின் சந்ததியான அரேலியரின் குடும்பமுமே.", "en": "Of Arod, the family of the Arodites: of Areli, the family of the Arelites."}, {"verse": 18, "start": 179.16, "end": 187.69, "ta": "இவைகளே காத் புத்திரரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் நாற்பதினாயிரத்து ஐந்நூறுபேர்.", "en": "These are the families of the children of Gad according to those that were numbered of them, forty thousand and five hundred."}, {"verse": 19, "start": 187.69, "end": 195.27, "ta": "யூதாவின் குமாரர் ஏர் ஓனான் என்பவர்கள்; ஏரும் ஓனானும் கானான் தேசத்தில் செத்தார்கள்.", "en": "The sons of Judah were Er and Onan: and Er and Onan died in the land of Canaan."}, {"verse": 20, "start": 195.27, "end": 210.06, "ta": "யூதாவுடைய மற்றக் குமாரரின் குடும்பங்களாவன: சேலாவின் சந்ததியான சேலாவியரின் குடும்பமும், பாரேசின் சந்ததியான பாரேசியரின் குடும்பமும், சேராவின் சந்ததியான சேராவியரின் குடும்பமுமே.", "en": "And the sons of Judah after their families were; of Shelah, the family of the Shelanites: of Pharez, the family of the Pharzites: of Zerah, the family of the Zarhites."}, {"verse": 21, "start": 210.06, "end": 220.62, "ta": "பாரேசுடைய குமாரரின் குடும்பங்களாவன: எஸ்ரோனின் சந்ததியான எஸ்ரோனியரின் குடும்பமும், ஆமூலின் சந்ததியான ஆமூலியரின் குடும்பமுமே.", "en": "And the sons of Pharez were; of Hezron, the family of the Hezronites: of Hamul, the family of the Hamulites."}, {"verse": 22, "start": 220.62, "end": 228.6, "ta": "இவைகளே யூதாவின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் எழுபத்தாறாயிரத்து ஐந்நூறுபேர்.", "en": "These are the families of Judah according to those that were numbered of them, threescore and sixteen thousand and five hundred."}, {"verse": 23, "start": 228.6, "end": 238.84, "ta": "இசக்காருடைய குமாரரின் குடும்பங்களாவன: தோலாவின் சந்ததியான தோலாவியரின் குடும்பமும், பூவாவின் சந்ததியான பூவாவியரின் குடும்பமும்,", "en": "Of the sons of Issachar after their families: of Tola, the family of the Tolaites: of Pua, the family of the Punites:"}, {"verse": 24, "start": 238.84, "end": 246.9, "ta": "யாசூபின் சந்ததியான யாசூபியரின் குடும்பமும், சிம்ரோனின் சந்ததியான சிம்ரோனியரின் குடும்பமுமே.", "en": "Of Jashub, the family of the Jashubites: of Shimron, the family of the Shimronites."}, {"verse": 25, "start": 246.9, "end": 255.35, "ta": "இவைகளே இசக்காரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் அறுபத்து நாலாயிரத்து முந்நூறுபேர்.", "en": "These are the families of Issachar according to those that were numbered of them, threescore and four thousand and three hundred."}, {"verse": 26, "start": 255.35, "end": 270.21, "ta": "செபுலோனுடைய குமாரரின் குடும்பங்களாவன: சேரேத்தின் சந்ததியான சேரேத்தியரின் குடும்பமும், ஏலோனின் சந்ததியான ஏலோனியரின் குடும்பமும், யாலேயேலின் சந்ததியான யாலேயேலியரின் குடும்பமுமே.", "en": "Of the sons of Zebulun after their families: of Sered, the family of the Sardites: of Elon, the family of the Elonites: of Jahleel, the family of the Jahleelites."}, {"verse": 27, "start": 270.21, "end": 278.42, "ta": "இவைகளே செபுலோனியரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் அறுபதினாயிரத்து ஐந்நூறுபேர்.", "en": "These are the families of the Zebulunites according to those that were numbered of them, threescore thousand and five hundred."}, {"verse": 28, "start": 278.42, "end": 283.66, "ta": "யோசேப்புடைய குமாரரான மனாசே எப்பிராயீம் என்பவர்களின் குடும்பங்களாவன:", "en": "The sons of Joseph after their families were Manasseh and Ephraim."}, {"verse": 29, "start": 283.66, "end": 295.16, "ta": "மனாசேயினுடைய குமாரரின் குடும்பங்கள்: மாகீரின் சந்ததியான மாகீரியரின் குடும்பமும், மாகீர் பெற்ற கிலெயாதின் சந்ததியான கிலெயாதியரின் குடும்பமும்,", "en": "Of the sons of Manasseh: of Machir, the family of the Machirites: and Machir begat Gilead: of Gilead come the family of the Gileadites."}, {"verse": 30, "start": 295.16, "end": 303.76, "ta": "கிலெயாத் பெற்ற ஈயேசேரின் சந்ததியான ஈயேசேயரின் குடும்பமும், ஏலேக்கின் சந்ததியான ஏலேக்கியரின் குடும்பமும்,", "en": "These are the sons of Gilead: of Jeezer, the family of the Jeezerites: of Helek, the family of the Helekites:"}, {"verse": 31, "start": 303.76, "end": 311.35, "ta": "அஸ்ரியேலின் சந்ததியான அஸ்ரியேலரின் குடும்பமும், சேகேமின் சந்ததியான சேகேமியரின் குடும்பமும்,", "en": "And of Asriel, the family of the Asrielites: and of Shechem, the family of the Shechemites:"}, {"verse": 32, "start": 311.35, "end": 319.56, "ta": "செமீதாவின் சந்ததியான செமீதாவியரின் குடும்பமும், ஏப்பேரின் சந்ததியான ஏப்பேரியரின் குடும்பமுமே.", "en": "And of Shemida, the family of the Shemidaites: and of Hepher, the family of the Hepherites."}, {"verse": 33, "start": 319.56, "end": 335.99, "ta": "ஏப்பேரின் குமாரனான செலொப்பியாத்திற்குக் குமாரர் இல்லாமல் இருந்தார்கள், குமாரத்திகள் மாத்திரம் இருந்தார்கள்; இவர்கள் நாமங்கள் மக்லாள், நோவாள், ஒக்லாள், மில்காள், திர்சாள் என்பவைகள்.", "en": "And Zelophehad the son of Hepher had no sons, but daughters: and the names of the daughters of Zelophehad were Mahlah, and Noah, Hoglah, Milcah, and Tirzah."}, {"verse": 34, "start": 335.99, "end": 344.04, "ta": "இவைகளே மனாசேயின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் ஐம்பத்தீராயிரத்து எழுநூறுபேர்.", "en": "These are the families of Manasseh, and those that were numbered of them, fifty and two thousand and seven hundred."}, {"verse": 35, "start": 344.04, "end": 358.83, "ta": "எப்பிராயீமுடைய குமாரரின் குடும்பங்களாவன: சுத்தெலாகின் சந்ததியான சுத்தெலாகியரின் குடும்பமும், பெகேரின் சந்ததியான பெகேரியரின் குடும்பமும், தாகானின் சந்ததியான தாகானியரின் குடும்பமும்,", "en": "These are the sons of Ephraim after their families: of Shuthelah, the family of the Shuthalhites: of Becher, the family of the Bachrites: of Tahan, the family of the Tahanites."}, {"verse": 36, "start": 358.83, "end": 364.07, "ta": "சுத்தெலாக் பெற்ற ஏரானின் சந்ததியான ஏரானியரின் குடும்பமுமே.", "en": "And these are the sons of Shuthelah: of Eran, the family of the Eranites."}, {"verse": 37, "start": 364.07, "end": 377.13, "ta": "இவைகளே எப்பிராயீம் புத்திரரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் முப்பத்தீராயிரத்து ஐந்நூறுபேர்; இவர்களே யோசேப்பு புத்திரரின் குடும்பங்கள்.", "en": "These are the families of the sons of Ephraim according to those that were numbered of them, thirty and two thousand and five hundred. These are the sons of Joseph after their families."}, {"verse": 38, "start": 377.13, "end": 391.44, "ta": "பென்யமீனுடைய குமாரரின் குடும்பங்களாவன: பேலாவின் சந்ததியான பேலாவியரின் குடும்பமும், அஸ்பேலின் சந்ததியான அஸ்பேலியரின் குடும்பமும், அகிராமின் சந்ததியான அகிராமியரின் குடும்பமும்,", "en": "The sons of Benjamin after their families: of Bela, the family of the Belaites: of Ashbel, the family of the Ashbelites: of Ahiram, the family of the Ahiramites:"}, {"verse": 39, "start": 391.44, "end": 399.19, "ta": "சுப்பாமின் சந்ததியான சுப்பாமியரின் குடும்பமும், உப்பாமின் சந்ததியான உப்பாமியரின் குடும்பமும்,", "en": "Of Shupham, the family of the Shuphamites: of Hupham, the family of the Huphamites."}, {"verse": 40, "start": 399.19, "end": 407.79, "ta": "பேலா பெற்ற ஆரேதின் சந்ததியான ஆரேதியரின் குடும்பமும், நாகமானின் சந்ததியான நாகமானியரின் குடும்பமுமே.", "en": "And the sons of Bela were Ard and Naaman: of Ard , the family of the Ardites: and of Naaman, the family of the Naamites."}, {"verse": 41, "start": 407.79, "end": 416.94, "ta": "இவைகளே பென்யமீன் புத்திரரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் நாற்பத்தையாயிரத்து அறுநூறு பேர்.", "en": "These are the sons of Benjamin after their families: and they that were numbered of them were forty and five thousand and six hundred."}, {"verse": 42, "start": 416.94, "end": 426.09, "ta": "தாணுடைய குமாரரின் குடும்பங்களாவன: சூகாமின் சந்ததியான சூகாமியரின் குடும்பமுமே; இவைகள் தாணின் குடும்பம்.", "en": "These are the sons of Dan after their families: of Shuham, the family of the Shuhamites. These are the families of Dan after their families."}, {"verse": 43, "start": 426.09, "end": 433.37, "ta": "சூகாமியரின் வம்சங்களில் எண்ணப்பட்டவர்கள் எல்லோரும் அறுபத்து நாலாயிரத்து நானூறு பேர்.", "en": "All the families of the Shuhamites, according to those that were numbered of them, were threescore and four thousand and four hundred."}, {"verse": 44, "start": 433.37, "end": 447.52, "ta": "ஆசேருடைய குமாரரின் குடும்பங்களாவன: இம்னாவின் சந்ததியான இம்னாவியரின் குடும்பமும், இஸ்வியின் சந்ததியான இஸ்வியரின் குடும்பமும், பெரீயாவின் சந்ததியான பெரீயாவியரின் குடும்பமும்,", "en": "Of the children of Asher after their families: of Jimna, the family of the Jimnites: of Jesui, the family of the Jesuites: of Beriah, the family of the Beriites."}, {"verse": 45, "start": 447.52, "end": 456.13, "ta": "பெரீயா பெற்ற ஏபேரின் சந்ததியான ஏபேரியரின் குடும்பமும், மல்கியேலின் சந்ததியான மல்கியேலியரின் குடும்பமுமே,", "en": "Of the sons of Beriah: of Heber, the family of the Heberites: of Malchiel, the family of the Malchielites."}, {"verse": 46, "start": 456.13, "end": 459.57, "ta": "ஆசேருடைய குமாரத்தியின் பேர் சாராள்.", "en": "And the name of the daughter of Asher was Sarah."}, {"verse": 47, "start": 459.57, "end": 468.49, "ta": "இவைகளே ஆசேர் புத்திரரின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் ஐம்பத்து மூவாயிரத்து நானூறு பேர்.", "en": "These are the families of the sons of Asher according to those that were numbered of them; who were fifty and three thousand and four hundred."}, {"verse": 48, "start": 468.49, "end": 479.36, "ta": "நப்தலியினுடைய குமாரரின் குடும்பங்களாவன: யாத்சியேலின் சந்ததியான யாத்சியேலியரின் குடும்பமும், கூனியின் சந்ததியான கூனியரின் குடும்பமும்,", "en": "Of the sons of Naphtali after their families: of Jahzeel, the family of the Jahzeelites: of Guni, the family of the Gunites:"}, {"verse": 49, "start": 479.36, "end": 487.57, "ta": "எத்செரின் சந்ததியான எத்செரியரின் குடும்பமும், சில்லேமின் சந்ததியான சில்லேமியரின் குடும்பமுமே.", "en": "Of Jezer, the family of the Jezerites: of Shillem, the family of the Shillemites."}, {"verse": 50, "start": 487.57, "end": 495.78, "ta": "இவைகளே நப்தலியின் குடும்பங்கள்; அவர்களில் எண்ணப்பட்டவர்கள் நாற்பத்தையாயிரத்து நானூறு பேர்.", "en": "These are the families of Naphtali according to their families: and they that were numbered of them were forty and five thousand and four hundred."}, {"verse": 51, "start": 495.78, "end": 503.84, "ta": "இஸ்ரவேல் புத்திரரில் எண்ணப்பட்டவர்கள் ஆறுலட்சத்தோராயிரத்து எழுநூற்று முப்பதுபேராயிருந்தார்கள்.", "en": "These were the numbered of the children of Israel, six hundred thousand and a thousand seven hundred and thirty."}, {"verse": 52, "start": 503.84, "end": 505.64, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 53, "start": 505.64, "end": 513.93, "ta": "இவர்களுடைய பேர்களின் இலக்கத்திற்குத்தக்கதாய் தேசம் இவர்களுக்குச் சுதந்தரமாகப் பங்கிடப்படவேண்டும்.", "en": "Unto these the land shall be divided for an inheritance according to the number of names."}, {"verse": 54, "start": 513.93, "end": 528.56, "ta": "அநேகம்பேருக்கு அதிக சுதந்திரமும் கொஞ்சம்பேருக்கு கொஞ்ச சுதந்தரமும் கொடுப்பாயாக; அவர்களில் எண்ணப்பட்ட இலக்கத்திற்குத் தக்கதாக அவரவர்களுக்குச் சுதந்திரம் கொடுக்கப்படவேண்டும்.", "en": "To many thou shalt give the more inheritance, and to few thou shalt give the less inheritance: to every one shall his inheritance be given according to those that were numbered of him."}, {"verse": 55, "start": 528.56, "end": 540.6, "ta": "ஆனாலும் சீட்டுப்போட்டு, தேசத்தைப் பங்கிடவேண்டும்; தங்கள் பிதாக்களுடைய கோத்திரங்களுக்குரிய நாமங்களின்படியே சுதந்தரித்துக்கொள்ளக்கடவர்கள்.", "en": "Notwithstanding the land shall be divided by lot: according to the names of the tribes of their fathers they shall inherit."}, {"verse": 56, "start": 540.6, "end": 550.22, "ta": "அநேகம்பேர்களாயினும் கொஞ்சம்பேர்களாயினும் சீட்டு விழுந்தபடியே அவரவர்களுடைய சுதந்தரங்கள் பங்கிடப்படவேண்டும் என்றார்.", "en": "According to the lot shall the possession thereof be divided between many and few."}, {"verse": 57, "start": 550.22, "end": 565.08, "ta": "எண்ணப்பட்ட லேவியரின் குடும்பங்களாவன: கெர்சோனின் சந்ததியான கெர்சோனியரின் குடும்பமும், கோகாத்தின் சந்ததியான கோகாத்தியரின் குடும்பமும், மெராரியின் சந்ததியான மெராரியரின் குடும்பமும்;", "en": "And these are they that were numbered of the Levites after their families: of Gershon, the family of the Gershonites: of Kohath, the family of the Kohathites: of Merari, the family of the Merarites."}, {"verse": 58, "start": 565.08, "end": 581.51, "ta": "லேவியின் மற்றக் குடும்பங்களாகிய லிப்னீயரின் குடும்பமும், எப்ரோனியரின் குடும்பமும், மகலியரின் குடும்பமும், மூசியரின் குடும்பமும், கோராகியரின் குடும்பமுமே. கோகாத் அம்ராமைப் பெற்றான்.", "en": "These are the families of the Levites: the family of the Libnites, the family of the Hebronites, the family of the Mahlites, the family of the Mushites, the family of the Korathites. And Kohath begat Amram."}, {"verse": 59, "start": 581.51, "end": 595.98, "ta": "அம்ராமுடைய மனைவிக்கு யோகெபேத் என்று பேர்; அவள் எகிப்திலே லேவிக்குப் பிறந்த குமாரத்தி; அவள் அம்ராமுக்கு ஆரோனையும் மோசேயையும் அவர்கள் சகோதரியான மிரியாமையும் பெற்றாள்.", "en": "And the name of Amram’s wife was Jochebed, the daughter of Levi, whom her mother bare to Levi in Egypt: and she bare unto Amram Aaron and Moses, and Miriam their sister."}, {"verse": 60, "start": 595.98, "end": 601.85, "ta": "ஆரோனுக்கு நாதாபும் அபியூவும் எலெயாசாரும் இத்தாமாரும் பிறந்தார்கள்.", "en": "And unto Aaron was born Nadab, and Abihu, Eleazar, and Ithamar."}, {"verse": 61, "start": 601.85, "end": 610.29, "ta": "நாதாபும் அபியூவும் கர்த்தருடைய சந்நிதியில் அந்நிய அக்கினியைக் கொண்டுவந்தபோது, செத்துப்போனார்கள்.", "en": "And Nadab and Abihu died, when they offered strange fire before the LORD ."}, {"verse": 62, "start": 610.29, "end": 628.13, "ta": "அவர்களில் ஒரு மாதத்து ஆண்பிள்ளை முதலாக எண்ணப்பட்டவர்கள் இருபத்து மூவாயிரம்பேர்; இஸ்ரவேல் புத்திரரின் நடுவே அவர்களுக்குச் சுதந்தரம் கொடுக்கப்படாதபடியினால், அவர்கள் இஸ்ரவேல் புத்திரரின் இலக்கத்திற்கு உட்படவில்லை.", "en": "And those that were numbered of them were twenty and three thousand, all males from a month old and upward: for they were not numbered among the children of Israel, because there was no inheritance given them among the children of Israel."}, {"verse": 63, "start": 628.13, "end": 641.11, "ta": "மோசேயும் ஆசாரியனாகிய எலெயாசரும் எரிகோவின் அருகேயிருக்கும் யோர்தானுக்கு இப்பாலே மோவாபின் சமனான வெளிகளில் இஸ்ரவேல் புத்திரரை எண்ணுகிறபோது இருந்தவர்கள் இவர்களே.", "en": "These are they that were numbered by Moses and Eleazar the priest, who numbered the children of Israel in the plains of Moab by Jordan near Jericho."}, {"verse": 64, "start": 641.11, "end": 652.14, "ta": "முன்பு மோசேயும் ஆசாரியனாகிய ஆரோனும் சீனாய் வனாந்தரத்தில் இஸ்ரவேல் புத்திரரை எண்ணும்போது இருந்தவர்களில் ஒருவரும் இவர்களுக்குள் இல்லை.", "en": "But among these there was not a man of them whom Moses and Aaron the priest numbered, when they numbered the children of Israel in the wilderness of Sinai."}, {"verse": 65, "start": 652.14, "end": 668.8, "ta": "வனாந்தரத்தில் சாகவே சாவார்கள் என்று கர்த்தர் அவர்களைக் குறித்துச் சொல்லியிருந்தார்; எப்புன்னேயின் குமாரனாகிய காலேபும் நூனின் குமாரனாகிய யோசுவாவும் தவிர, வேறொருவரும் அவர்களில் மீதியாயிருக்கவில்லை.", "en": "For the LORD had said of them, They shall surely die in the wilderness. And there was not left a man of them, save Caleb the son of Jephunneh, and Joshua the son of Nun."}]}, "27": {"chapter": 27, "duration": 266.85, "audio_url": "audio_ot/OT04_27.mp3", "total_verses": 23, "verses": [{"verse": 1, "start": 3.8, "end": 22.07, "ta": "யோசேப்பின் குமாரனாகிய மனாசேயின் குடும்பங்களில், மனாசேயின் குமாரனாகிய மாகீரின் மகனான கிலெயாத்துக்குப் பிறந்த ஏபேருக்குப் புத்திரனாயிருந்த செலோப்பியாத்தின் குமாரத்திகளாகிய மக்லாள், நோவாள், ஒக்லாள், மில்காள், திர்சாள் என்பவர்கள் வந்து,", "en": "Then came the daughters of Zelophehad, the son of Hepher, the son of Gilead, the son of Machir, the son of Manasseh, of the families of Manasseh the son of Joseph: and these are the names of his daughters; Mahlah, Noah, and Hoglah, and Milcah, and Tirzah."}, {"verse": 2, "start": 22.07, "end": 31.13, "ta": "ஆசரிப்புக் கூடாரவாசலிலே மோசேக்கும், ஆசாரியனாகிய எலெயாசாருக்கும், பிரபுக்களுக்கும், சபையனைத்திற்கும் முன்பாக நின்று:", "en": "And they stood before Moses, and before Eleazar the priest, and before the princes and all the congregation, by the door of the tabernacle of the congregation, saying,"}, {"verse": 3, "start": 31.13, "end": 45.67, "ta": "எங்கள் தகப்பன் வனாந்தரத்தில் மரணமடைந்தார்; அவர் கர்த்தருக்கு விரோதமாகக் கூடின கோராகின் கூட்டத்தாரில் சேர்ந்தவர் அல்ல, தம்முடைய பாவத்தினாலே மரித்தார்; அவருக்குக் குமாரர் இல்லை.", "en": "Our father died in the wilderness, and he was not in the company of them that gathered themselves together against the LORD in the company of Korah; but died in his own sin, and had no sons."}, {"verse": 4, "start": 45.67, "end": 60.73, "ta": "எங்கள் தகப்பனுக்குக் குமாரன் இல்லாததினாலே, அவருடைய பேர் அவருடைய வம்சத்தில் இல்லாமல் அற்றுப்போகலாமா? எங்கள் தகப்பனுடைய சகோதரருக்குள்ளே எங்களுக்குக் காணியாட்சி கொடுக்கவேண்டும் என்றார்கள்.", "en": "Why should the name of our father be done away from among his family, because he hath no son? Give unto us therefore a possession among the brethren of our father."}, {"verse": 5, "start": 60.73, "end": 66.14, "ta": "மோசே அவர்களுடைய நியாயத்தைக் கர்த்தருடைய சந்நிதியில் கொண்டுபோனான்.", "en": "And Moses brought their cause before the LORD ."}, {"verse": 6, "start": 66.14, "end": 68.55, "ta": "அப்பொழுது கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 7, "start": 68.55, "end": 85.06, "ta": "செலோப்பியாத்தின் குமாரத்திகள் சொல்லுகிறது சரிதான்; அவர்களுக்கு அவர்கள் தகப்பனுடைய சகோதரருக்குள்ளே சுதந்தரம் கொடுக்கப்படவேண்டும்; அவர்கள் தகப்பன் பின்வைத்த சுதந்தரத்தை அவர்களுக்குக் கிடைக்கும்படி செய்வாயாக.", "en": "The daughters of Zelophehad speak right: thou shalt surely give them a possession of an inheritance among their father’s brethren; and thou shalt cause the inheritance of their father to pass unto them."}, {"verse": 8, "start": 85.06, "end": 95.66, "ta": "மேலும் நீ இஸ்ரவேல் புத்திரரை நோக்கி: ஒருவன் குமாரன் இல்லாமல் மரித்தால், அவனுக்குரிய சுதந்தரத்தை அவன் குமாரத்திக்குக் கொடுக்கவேண்டும்.", "en": "And thou shalt speak unto the children of Israel, saying, If a man die, and have no son, then ye shall cause his inheritance to pass unto his daughter."}, {"verse": 9, "start": 95.66, "end": 103.77, "ta": "அவனுக்கு குமாரத்தியும் இல்லாதிருந்தால், அவனுக்குரிய சுதந்தரத்தை அவன் சகோதரருக்குக் கொடுக்கவேண்டும்.", "en": "And if he have no daughter, then ye shall give his inheritance unto his brethren."}, {"verse": 10, "start": 103.77, "end": 112.25, "ta": "அவனுக்குச் சகோதரரும் இல்லாதிருந்தால் அவனுக்குரிய சுதந்தரத்தை அவன் தகப்பனுடைய சகோதரருக்குக் கொடுக்கவேண்டும்.", "en": "And if he have no brethren, then ye shall give his inheritance unto his father’s brethren."}, {"verse": 11, "start": 112.25, "end": 134.1, "ta": "அவன் தகப்பனுக்குச் சகோதரர் இல்லாதிருந்தால், அவனுக்குரிய சுதந்தரத்தை அவன் வம்சத்திலே அவனுக்குக் கிட்டின உறவின்முறையானுக்குக் சுதந்தரமாகக் கொடுக்கவேண்டும்; இது, கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, இஸ்ரவேல் புத்திரருக்கு நியாயவிதிப்பிரமாணமாய் இருக்கக்கடவது என்று சொல் என்றார்.", "en": "And if his father have no brethren, then ye shall give his inheritance unto his kinsman that is next to him of his family, and he shall possess it: and it shall be unto the children of Israel a statute of judgment, as the LORD commanded Moses."}, {"verse": 12, "start": 134.1, "end": 143.23, "ta": "பின்பு கர்த்தர் மோசேயை நோக்கி: நீ இந்த அபாரீம் மலையில் ஏறி, நான் இஸ்ரவேல் புத்திரருக்குக் கொடுத்த தேசத்தைப் பார்.", "en": "And the LORD said unto Moses, Get thee up into this mount Abarim, and see the land which I have given unto the children of Israel."}, {"verse": 13, "start": 143.23, "end": 152.15, "ta": "நீ அதைப் பார்த்தபின்பு, உன் சகோதரனாகிய ஆரோன் சேர்க்கப்பட்டது போல, நீயும் உன் ஜனத்தாரிடத்தில் சேர்க்கப்படுவாய்;", "en": "And when thou hast seen it, thou also shalt be gathered unto thy people, as Aaron thy brother was gathered."}, {"verse": 14, "start": 152.15, "end": 171.95, "ta": "சபையார் வாக்குவாதம்பண்ணின சீன் வனாந்தரத்தில் தண்ணீருக்கடுத்த விஷயத்தில் அவர்கள் கண்களுக்கு முன்பாக என்னைப் பரிசுத்தம்பண்ணவேண்டிய நீங்கள் என் கட்டளையை மீறினீர்களே என்றார். இது சீன் வனாந்தரத்தில் காதேஸ் ஊர் அருகே உண்டான மேரிபாவின் தண்ணீருக்கடுத்த காரியமே.", "en": "For ye rebelled against my commandment in the desert of Zin, in the strife of the congregation, to sanctify me at the water before their eyes: that is the water of Meribah in Kadesh in the wilderness of Zin."}, {"verse": 15, "start": 171.95, "end": 174.22, "ta": "அப்பொழுது மோசே கர்த்தரை நோக்கி:", "en": "And Moses spake unto the LORD , saying,"}, {"verse": 16, "start": 174.22, "end": 178.75, "ta": "கர்த்தருடைய சபை மேய்ப்பன் இல்லாத மந்தையைப்போல் இராதபடிக்கு,", "en": "Let the LORD , the God of the spirits of all flesh, set a man over the congregation,"}, {"verse": 17, "start": 178.75, "end": 195.78, "ta": "அந்தச் சபைக்கு முன்பாகப் போக்கும் வரத்துமாய் இருக்கும்படிக்கும், அவர்களைப் போகவும் வரவும் பண்ணும்படிக்கும், மாம்சமான யாவருடைய ஆவிகளுக்கும் தேவனாகிய கர்த்தர் ஒரு புருஷனை அவர்கள்மேல் அதிகாரியாக ஏற்படுத்தவேண்டும் என்றான்.", "en": "Which may go out before them, and which may go in before them, and which may lead them out, and which may bring them in; that the congregation of the LORD be not as sheep which have no shepherd."}, {"verse": 18, "start": 195.78, "end": 205.79, "ta": "கர்த்தர் மோசேயை நோக்கி: ஆவியைப் பெற்றிருக்கிற புருஷனாகிய யோசுவா என்னும் நூனின் குமாரனை நீ தெரிந்துகொண்டு, அவன்மேல் உன் கையை வைத்து,", "en": "And the LORD said unto Moses, Take thee Joshua the son of Nun, a man in whom is the spirit, and lay thine hand upon him;"}, {"verse": 19, "start": 205.79, "end": 214.93, "ta": "அவனை ஆசாரியனாகிய எலெயாசாருக்கும் சபையனைத்திற்கும் முன்பாக நிறுத்தி, அவர்கள் கண்களுக்கு முன்பாக அவனுக்கு கட்டளைகொடுத்து,", "en": "And set him before Eleazar the priest, and before all the congregation; and give him a charge in their sight."}, {"verse": 20, "start": 214.93, "end": 223.84, "ta": "இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரும் அவனுக்குக் கீழ்ப்படியும்படிக்கு, உன் கனத்தில் கொஞ்சம் அவனுக்குக் கொடு.", "en": "And thou shalt put some of thine honour upon him, that all the congregation of the children of Israel may be obedient."}, {"verse": 21, "start": 223.84, "end": 247.81, "ta": "அவன் ஆசாரியனாகிய எலெயாசாருக்கு முன்பாக நிற்கக்கடவன்; அவனிமித்தம் அந்த ஆசாரியன் கர்த்தருடைய சந்நிதானத்தில் வந்து, ஊரீம் என்னும் நியாயத்தினாலே ஆலோசனை கேட்கக்கடவன்; அவருடைய கட்டளையின்படியே, அவனும் அவனோடேகூட இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரும் போகவும் அவருடைய கட்டளையின்படியே வரவும் வேண்டியது என்றார்.", "en": "And he shall stand before Eleazar the priest, who shall ask counsel for him after the judgment of Urim before the LORD : at his word shall they go out, and at his word they shall come in, both he, and all the children of Israel with him, even all the congregation."}, {"verse": 22, "start": 247.81, "end": 258.26, "ta": "மோசே தனக்குக் கர்த்தர் கட்டளையிட்டபடியே யோசுவாவை அழைத்துக்கொண்டுபோய், அவனை ஆசாரியனாகிய எலெயாசாருக்கும் சபையனைத்திற்கும் முன்பாக நிறுத்தி,", "en": "And Moses did as the LORD commanded him: and he took Joshua, and set him before Eleazar the priest, and before all the congregation:"}, {"verse": 23, "start": 258.26, "end": 265.35, "ta": "அவன் மேல் தன் கைகளை வைத்து, கர்த்தர் தனக்குச் சொன்னபடியே அவனுக்குக் கட்டளைகொடுத்தான்.", "en": "And he laid his hands upon him, and gave him a charge, as the LORD commanded by the hand of Moses."}]}, "28": {"chapter": 28, "duration": 335.62, "audio_url": "audio_ot/OT04_28.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 5.54, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.54, "end": 21.07, "ta": "எனக்குச் சுகந்தவாசனையாக, தகனபலிகளுக்கு அடுத்த காணிக்கையையும் அப்பத்தையும், குறித்தகாலத்தில் எனக்குச் செலுத்தும்படிக்குக் கவனமாயிருக்கக்கடவீர்கள் என்று நீ இஸ்ரவேல் புத்திரருக்குக் கட்டளையிடு.", "en": "Command the children of Israel, and say unto them, My offering, and my bread for my sacrifices made by fire, for a sweet savour unto me, shall ye observe to offer unto me in their due season."}, {"verse": 3, "start": 21.07, "end": 35.39, "ta": "மேலும் நீ அவர்களை நோக்கி: நீங்கள் கர்த்தருக்குச் செலுத்தவேண்டிய தகனபலி என்னவென்றால்: நித்திய சர்வாங்க தகனபலியாக நாடோறும் ஒரு வயதான பழுதற்ற இரண்டு ஆட்டுக்குட்டிகளைப் பலியிடவேண்டும்.", "en": "And thou shalt say unto them, This is the offering made by fire which ye shall offer unto the LORD ; two lambs of the first year without spot day by day, for a continual burnt offering."}, {"verse": 4, "start": 35.39, "end": 41.68, "ta": "காலையில் ஒரு ஆட்டுக்குட்டியையும், மாலையில் ஒரு ஆட்டுக்குட்டியையும் பலியிட்டு,", "en": "The one lamb shalt thou offer in the morning, and the other lamb shalt thou offer at even;"}, {"verse": 5, "start": 41.68, "end": 52.74, "ta": "போஜனபலியாக ஒரு மரக்காலிலே பத்தில் ஒரு பங்கானதும் இடித்துப் பிழிந்த காற்படி எண்ணெயிலே பிசைந்ததுமாகிய மெல்லிய மாவையும் செலுத்தக் கடவீர்கள்.", "en": "And a tenth part of an ephah of flour for a meat offering, mingled with the fourth part of an hin of beaten oil."}, {"verse": 6, "start": 52.74, "end": 61.76, "ta": "இது சீனாய் மலையிலே கட்டளையிடப்பட்ட நித்திய சர்வாங்க தகனபலி; இது கர்த்தருக்குச் சுகந்த வாசனைக்கான தகனபலி.", "en": "It is a continual burnt offering, which was ordained in mount Sinai for a sweet savour, a sacrifice made by fire unto the LORD ."}, {"verse": 7, "start": 61.76, "end": 72.74, "ta": "காற்படி திராட்சரசம் ஒரு ஆட்டுக்குட்டிக்கு அடுத்த பானபலி; பரிசுத்த ஸ்தலத்திலே கர்த்தருக்கு அந்த இரசம் பானபலியாக வார்க்கப்படக்கடவது.", "en": "And the drink offering thereof shall be the fourth part of an hin for the one lamb: in the holy place shalt thou cause the strong wine to be poured unto the LORD for a drink offering."}, {"verse": 8, "start": 72.74, "end": 84.56, "ta": "காலையின் போஜனபலிக்கும் அதின் பானபலிக்கும் ஒப்பாகவே மாலையில் மற்ற ஆட்டுக்குட்டியையும் கர்த்தருக்குச் சுகந்த வாசனையான தகனபலியாகச் செலுத்தக்கடவீர்கள்.", "en": "And the other lamb shalt thou offer at even: as the meat offering of the morning, and as the drink offering thereof, thou shalt offer it , a sacrifice made by fire, of a sweet savour unto the LORD ."}, {"verse": 9, "start": 84.56, "end": 99.11, "ta": "ஓய்வுநாளிலோ போஜனபலிக்காக ஒரு வயதான பழுதற்ற இரண்டு ஆட்டுக்குட்டிகளையும், பத்தில் இரண்டு பங்கானதும் எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவையும், அதின் பானபலியையும் செலுத்தக்கடவீர்கள்.", "en": "And on the sabbath day two lambs of the first year without spot, and two tenth deals of flour for a meat offering, mingled with oil, and the drink offering thereof:"}, {"verse": 10, "start": 99.11, "end": 109.87, "ta": "நித்தமும் செலுத்தும் சர்வாங்க தகனபலியும் அதின் பானபலியும் அன்றி ஒவ்வொரு ஒய்வுநாளிலும் இந்தச் சர்வாங்க தகனபலியும் செலுத்தப்படவேண்டும்.", "en": "This is the burnt offering of every sabbath, beside the continual burnt offering, and his drink offering."}, {"verse": 11, "start": 109.87, "end": 123.96, "ta": "உங்கள் மாதப்பிறப்புகளில் நீங்கள் கர்த்தருக்குச் சர்வாங்க தகனபலியாக இரண்டு காளைகளையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும் செலுத்தக்கடவீர்கள்.", "en": "And in the beginnings of your months ye shall offer a burnt offering unto the LORD ; two young bullocks, and one ram, seven lambs of the first year without spot;"}, {"verse": 12, "start": 123.96, "end": 138.66, "ta": "போஜனபலியாக ஒவ்வொரு காளைக்குப் பத்தில் மூன்றுபங்கானதும் எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவையும், போஜனபலியாக ஒரு ஆட்டுக்கடாவுக்குப் பத்தில் இரண்டு பங்கானதும் எண்ணெயிலே பிசைந்ததுமான மாவையும்,", "en": "And three tenth deals of flour for a meat offering, mingled with oil, for one bullock; and two tenth deals of flour for a meat offering, mingled with oil, for one ram;"}, {"verse": 13, "start": 138.66, "end": 151.84, "ta": "போஜனபலியாக ஒவ்வொரு ஆட்டுக்குட்டிக்குப் பத்தில் ஒரு பங்கானதும் எண்ணெயிலே பிசைந்ததுமான மாவையும் கர்த்தருக்குச் சுகந்த வாசனையான சர்வாங்க தகனபலியாகச் செலுத்தக்கடவீர்கள்.", "en": "And a several tenth deal of flour mingled with oil for a meat offering unto one lamb; for a burnt offering of a sweet savour, a sacrifice made by fire unto the LORD ."}, {"verse": 14, "start": 151.84, "end": 170.78, "ta": "அவைகளுக்கேற்ற பானபலிகள் திராட்சரசத்தில் காளைக்கு அரைப்படியும், ஆட்டுக்கடாவுக்குப் படியில் மூன்றில் ஒரு பங்கும், ஆட்டுக்குட்டிக்குக் காற்படி ரசமுமாயிருக்கவேண்டும்; இது வருஷ முழுவதும் மாதந்தோறும் செலுத்தப்படவேண்டிய சர்வாங்க தகனபலி.", "en": "And their drink offerings shall be half an hin of wine unto a bullock, and the third part of an hin unto a ram, and a fourth part of an hin unto a lamb: this is the burnt offering of every month throughout the months of the year."}, {"verse": 15, "start": 170.78, "end": 182.29, "ta": "நித்தமும் இடப்படும் சர்வாங்க தகனபலியும் அதின் பானபலியும் அன்றி, பாவநிவாரண பலியாகக் கர்த்தருக்கு ஒரு வெள்ளாட்டுக்கடாவும் செலுத்தப்படவேண்டும்.", "en": "And one kid of the goats for a sin offering unto the LORD shall be offered, beside the continual burnt offering, and his drink offering."}, {"verse": 16, "start": 182.29, "end": 186.99, "ta": "முதலாம் மாதம் பதினாலாம் தேதி கர்த்தருக்கு உரிய பஸ்கா.", "en": "And in the fourteenth day of the first month is the passover of the LORD ."}, {"verse": 17, "start": 186.99, "end": 194.95, "ta": "அந்த மாதம் பதினைந்தாம் தேதி பண்டிகைநாள்; ஏழுநாளளவும் புளிப்பில்லாத அப்பம் புசிக்கவேண்டும்.", "en": "And in the fifteenth day of this month is the feast: seven days shall unleavened bread be eaten."}, {"verse": 18, "start": 194.95, "end": 203.89, "ta": "முதலாம் நாளிலே பரிசுத்த சபை கூடுதல் இருக்கவேண்டும்; அன்றைத்தினம் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது.", "en": "In the first day shall be an holy convocation; ye shall do no manner of servile work therein:"}, {"verse": 19, "start": 203.89, "end": 214.95, "ta": "அப்பொழுது நீங்கள் கர்த்தருக்குச் சர்வாங்க தகனபலியாக இரண்டு காளைகளையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும்,", "en": "But ye shall offer a sacrifice made by fire for a burnt offering unto the LORD ; two young bullocks, and one ram, and seven lambs of the first year: they shall be unto you without blemish:"}, {"verse": 20, "start": 214.95, "end": 226.08, "ta": "அவைகளுக்கேற்ற போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவிலே காளைக்காகப் பத்தில் மூன்று பங்கையும், ஆட்டுக்கடாவுக்காகப் பத்தில் இரண்டு பங்கையும்,", "en": "And their meat offering shall be of flour mingled with oil: three tenth deals shall ye offer for a bullock, and two tenth deals for a ram;"}, {"verse": 21, "start": 226.08, "end": 231.01, "ta": "ஏழு ஆட்டுக்குட்டிகளில் ஒவ்வொன்றிற்காகப் பத்தில் ஒரு பங்கையும்,", "en": "A several tenth deal shalt thou offer for every lamb, throughout the seven lambs:"}, {"verse": 22, "start": 231.01, "end": 238.43, "ta": "உங்கள் பாவநிவர்த்திக்கென்று பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering, to make an atonement for you."}, {"verse": 23, "start": 238.43, "end": 245.78, "ta": "காலையிலே நித்தமும் செலுத்தும் சர்வாங்க தகனபலியையும் அன்றி இவைகளையும் செலுத்தக்கடவீர்கள்.", "en": "Ye shall offer these beside the burnt offering in the morning, which is for a continual burnt offering."}, {"verse": 24, "start": 245.78, "end": 261.62, "ta": "இந்தப்பிரகாரம் ஏழுநாளளவும் நாடோறும் கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி செலுத்தக்கடவீர்கள்; நித்தமும் செலுத்தப்படும் சர்வாங்க தகனபலியையும் அதின் பானபலியையும் அன்றி, இதையும் செலுத்தவேண்டும்.", "en": "After this manner ye shall offer daily, throughout the seven days, the meat of the sacrifice made by fire, of a sweet savour unto the LORD : it shall be offered beside the continual burnt offering, and his drink offering."}, {"verse": 25, "start": 261.62, "end": 270.56, "ta": "ஏழாம் நாளிலே பரிசுத்த சபைகூடுதல் இருக்கவேண்டும்; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது..", "en": "And on the seventh day ye shall have an holy convocation; ye shall do no servile work."}, {"verse": 26, "start": 270.56, "end": 285.78, "ta": "அந்த வாரங்களுக்குப்பின் நீங்கள் கர்த்தருக்குப் புதிய போஜனபலியாக முதற்கனிகளைச் செலுத்தும் பண்டிகை நாளிலும் பரிசுத்த சபைகூடுதல் இருக்கவேண்டும்; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது.", "en": "Also in the day of the firstfruits, when ye bring a new meat offering unto the LORD , after your weeks be out , ye shall have an holy convocation; ye shall do no servile work:"}, {"verse": 27, "start": 285.78, "end": 297.91, "ta": "அப்பொழுது நீங்கள் கர்த்தருக்குச் சுகந்த வாசனையான சர்வாங்க தகனபலியாக இரண்டு காளைகளையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான ஏழு ஆட்டுக்குட்டிகளையும்.", "en": "But ye shall offer the burnt offering for a sweet savour unto the LORD ; two young bullocks, one ram, seven lambs of the first year;"}, {"verse": 28, "start": 297.91, "end": 309.65, "ta": "அவைகளின் போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவில் ஒரு காளைக்காகப் பத்தில் மூன்று பங்கையும், அந்த ஒரு ஆட்டுக்கடாவுக்காகப் பத்தில் இரண்டு பங்கையும்,", "en": "And their meat offering of flour mingled with oil, three tenth deals unto one bullock, two tenth deals unto one ram,"}, {"verse": 29, "start": 309.65, "end": 314.57, "ta": "ஏழு ஆட்டுக்குட்டிகளில் ஒவ்வொன்றிற்காகப் பத்தில் ஒரு பங்கையும்,", "en": "A several tenth deal unto one lamb, throughout the seven lambs;"}, {"verse": 30, "start": 314.57, "end": 321.92, "ta": "உங்களுக்காகப் பாவநிவர்த்தி செய்யும்படிக்கு ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one kid of the goats, to make an atonement for you."}, {"verse": 31, "start": 321.92, "end": 334.12, "ta": "நித்திய சர்வாங்க தகன பலியையும் அதின் போஜனபலியையும் அதின் பானபலியையும் அன்றி, இவைகளையும் செலுத்தக்கடவீர்கள்; இவைகள் பழுதற்றவைகளாயிருக்கவேண்டும்.", "en": "Ye shall offer them beside the continual burnt offering, and his meat offering, (they shall be unto you without blemish) and their drink offerings."}]}, "29": {"chapter": 29, "duration": 448.13, "audio_url": "audio_ot/OT04_29.mp3", "total_verses": 40, "verses": [{"verse": 1, "start": 3.8, "end": 17.01, "ta": "ஏழாம் மாதம் முதல்தேதி பரிசுத்த சபைகூடும் நாளாயிருக்கக்கடவது; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது; அது உங்களுக்கு எக்காளமூதும் நாளாயிருக்கவேண்டும்.", "en": "And in the seventh month, on the first day of the month, ye shall have an holy convocation; ye shall do no servile work: it is a day of blowing the trumpets unto you."}, {"verse": 2, "start": 17.01, "end": 28.94, "ta": "அப்பொழுது நீங்கள் கர்த்தருக்குச் சுகந்த வாசனையான சர்வாங்க தகனபலியாக ஒரு காளையையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும்,", "en": "And ye shall offer a burnt offering for a sweet savour unto the LORD ; one young bullock, one ram, and seven lambs of the first year without blemish:"}, {"verse": 3, "start": 28.94, "end": 39.59, "ta": "அவைகளுக்கு அடுத்த போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவிலே காளைக்காகப் பத்தில் மூன்று பங்கையும், ஆட்டுக்கடாவுக்காக இரண்டு பங்கையும்,", "en": "And their meat offering shall be of flour mingled with oil, three tenth deals for a bullock, and two tenth deals for a ram,"}, {"verse": 4, "start": 39.59, "end": 43.74, "ta": "ஏழு ஆட்டுக்குட்டிகளில் ஒவ்வொன்றிற்காக ஒரு பங்கையும்,", "en": "And one tenth deal for one lamb, throughout the seven lambs:"}, {"verse": 5, "start": 43.74, "end": 49.03, "ta": "உங்கள் பாவநிவர்த்திக்கான பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தி,", "en": "And one kid of the goats for a sin offering, to make an atonement for you:"}, {"verse": 6, "start": 49.03, "end": 68.58, "ta": "மாதப்பிறப்பின் சர்வாங்க தகனபலியையும் அதின் போஜனபலியையும் தினந்தோறும் இடும் சர்வாங்க தகன பலியையும் அதன் போஜனபலியையும், அவைகளின் முறைமைக்கேற்ற பானபலிகளையும் அன்றி, இவைகளையும் கர்த்தருக்குச் சுகந்த வாசனையான சர்வாங்க தகனபலியாகச் செலுத்தக்கடவீர்கள்.", "en": "Beside the burnt offering of the month, and his meat offering, and the daily burnt offering, and his meat offering, and their drink offerings, according unto their manner, for a sweet savour, a sacrifice made by fire unto the LORD ."}, {"verse": 7, "start": 68.58, "end": 81.64, "ta": "இந்த ஏழாம் மாதம் பத்தாம் தேதி உங்களுக்குப் பரிசுத்த சபைகூடும் நாளாயிருக்கக்கடவது; அதிலே நீங்கள் யாதொரு வேலையும் செய்யாமல், உங்கள் ஆத்துமாக்களைத் தாழ்மைப்படுத்தο,", "en": "And ye shall have on the tenth day of this seventh month an holy convocation; and ye shall afflict your souls: ye shall not do any work therein:"}, {"verse": 8, "start": 81.64, "end": 91.76, "ta": "ர்த்தக்க`் சுகந்த சனையான சர்வξங்க தகனபலியாக ஒரு காளையையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும்,", "en": "But ye shall offer a burnt offering unto the LORD for a sweet savour; one young bullock, one ram, and seven lambs of the first year; they shall be unto you without blemish:"}, {"verse": 9, "start": 91.76, "end": 102.41, "ta": "அவைகளின் போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவிலே காளைக்காகப் பத்தில் மூன்று பங்கையும், அந்த ஒரு ஆட்டுக்கடாவுக்காக இரண்டு பங்கையும்,", "en": "And their meat offering shall be of flour mingled with oil, three tenth deals to a bullock, and two tenth deals to one ram,"}, {"verse": 10, "start": 102.41, "end": 107.32, "ta": "ஏழு ஆட்டுக்குட்டிகளில் ஒவ்வொன்றிற்காகப் பத்தில் ஒரு பங்கையும்,", "en": "A several tenth deal for one lamb, throughout the seven lambs:"}, {"verse": 11, "start": 107.32, "end": 123.02, "ta": "பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தி, பாவநிவாரனபலியையும், நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அவைகளின் பானபலிகளையும் அன்றி, இவைகளையும் செலுத்தக்கடவீர்கள்.", "en": "One kid of the goats for a sin offering; beside the sin offering of atonement, and the continual burnt offering, and the meat offering of it, and their drink offerings."}, {"verse": 12, "start": 123.02, "end": 137.89, "ta": "ஏழாம் மாதம் பதினைந்தாம் தேதி உங்களுக்குப் பரிசுத்த சபைகூடும் நாளாயிருக்கக்கடவது; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது; ஏழுநாள் கர்த்தருக்குப் பண்டிகை ஆசரிக்கக்கடவீர்கள்.", "en": "And on the fifteenth day of the seventh month ye shall have an holy convocation; ye shall do no servile work, and ye shall keep a feast unto the LORD seven days:"}, {"verse": 13, "start": 137.89, "end": 150.81, "ta": "நீங்கள் கர்த்தருக்குச் சுகந்த வாசனையுள்ள சர்வாங்க தகனபலியாக பதின்மூன்று காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And ye shall offer a burnt offering, a sacrifice made by fire, of a sweet savour unto the LORD ; thirteen young bullocks, two rams, and fourteen lambs of the first year; they shall be without blemish:"}, {"verse": 14, "start": 150.81, "end": 165.38, "ta": "அவைகளின் போஜனபலியாக எண்ணெயிலே பிசைந்த மெல்லிய மாவிலே அந்தப் பதின்மூன்று காளைகளில் ஒவ்வொன்றிற்காகப் பத்தில் மூன்று பங்கையும், அந்த இரண்டு ஆட்டுக்கடாக்களில் ஒவ்வொன்றிற்காக இரண்டு பங்கையும்,", "en": "And their meat offering shall be of flour mingled with oil, three tenth deals unto every bullock of the thirteen bullocks, two tenth deals to each ram of the two rams,"}, {"verse": 15, "start": 165.38, "end": 170.44, "ta": "பதினான்கு ஆட்டுக்குட்டிகளின் ஒவ்வொன்றிற்காக ஒரு பங்கையும்.", "en": "And a several tenth deal to each lamb of the fourteen lambs:"}, {"verse": 16, "start": 170.44, "end": 181.61, "ta": "நித்திய தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one kid of the goats for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering."}, {"verse": 17, "start": 181.61, "end": 191.13, "ta": "இரண்டாம் நாளிலே பன்னிரண்டு காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the second day ye shall offer twelve young bullocks, two rams, fourteen lambs of the first year without spot:"}, {"verse": 18, "start": 191.13, "end": 202.22, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத் தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 19, "start": 202.22, "end": 214.38, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அவைகளின் பானபலிகளையும் அன்றி, பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one kid of the goats for a sin offering; beside the continual burnt offering, and the meat offering thereof, and their drink offerings."}, {"verse": 20, "start": 214.38, "end": 223.67, "ta": "மூன்றாம் நாளிலே பதினொரு காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the third day eleven bullocks, two rams, fourteen lambs of the first year without blemish;"}, {"verse": 21, "start": 223.67, "end": 234.69, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 22, "start": 234.69, "end": 246.54, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, and his meat offering, and his drink offering."}, {"verse": 23, "start": 246.54, "end": 255.83, "ta": "நான்காம் நாளிலே பத்துக் காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the fourth day ten bullocks, two rams, and fourteen lambs of the first year without blemish:"}, {"verse": 24, "start": 255.83, "end": 266.86, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "Their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 25, "start": 266.86, "end": 278.78, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one kid of the goats for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering."}, {"verse": 26, "start": 278.78, "end": 287.92, "ta": "ஐந்தாம் நாளிலே ஒன்பது காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the fifth day nine bullocks, two rams, and fourteen lambs of the first year without spot:"}, {"verse": 27, "start": 287.92, "end": 298.94, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 28, "start": 298.94, "end": 310.87, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, and his meat offering, and his drink offering."}, {"verse": 29, "start": 310.87, "end": 319.93, "ta": "ஆறாம் நாளிலே எட்டுக் காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the sixth day eight bullocks, two rams, and fourteen lambs of the first year without blemish:"}, {"verse": 30, "start": 319.93, "end": 330.96, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 31, "start": 330.96, "end": 342.96, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலிகளையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering."}, {"verse": 32, "start": 342.96, "end": 351.72, "ta": "ஏழாம் நாளிலே ஏழு காளைகளையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு வயதான பழுதற்ற பதினான்கு ஆட்டுக்குட்டிகளையும்,", "en": "And on the seventh day seven bullocks, two rams, and fourteen lambs of the first year without blemish:"}, {"verse": 33, "start": 351.72, "end": 362.75, "ta": "காளைகளும் ஆட்டுக்கடாக்களும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "And their meat offering and their drink offerings for the bullocks, for the rams, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 34, "start": 362.75, "end": 374.67, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, his meat offering, and his drink offering."}, {"verse": 35, "start": 374.67, "end": 383.89, "ta": "எட்டாம் நாள் உங்களுக்கு விசேஷித்த ஆசரிப்பு நாளாயிருக்கக்கடவது; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது.", "en": "On the eighth day ye shall have a solemn assembly: ye shall do no servile work therein:"}, {"verse": 36, "start": 383.89, "end": 396.5, "ta": "அப்பொழுது நீங்கள் கர்த்தருக்குச் சுகந்த வாசனையுள்ள தகனமான சர்வாங்க தகனபலியாக ஒரு காளையையும், ஒரு ஆட்டுக்கடாவையும், ஒரு வயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும்,", "en": "But ye shall offer a burnt offering, a sacrifice made by fire, of a sweet savour unto the LORD : one bullock, one ram, seven lambs of the first year without blemish:"}, {"verse": 37, "start": 396.5, "end": 407.22, "ta": "காளையும் ஆட்டுக்கடாவும் ஆட்டுக்குட்டிகளும் இருக்கிற இலக்கத்திற்குத்தக்கதாக முறைமையின்படி அவைகளின் போஜனபலியையும், அவைகளின் பானபலிகளையும்,", "en": "Their meat offering and their drink offerings for the bullock, for the ram, and for the lambs, shall be according to their number, after the manner:"}, {"verse": 38, "start": 407.22, "end": 419.15, "ta": "நித்திய சர்வாங்க தகனபலியையும், அதின் போஜனபலியையும், அதின் பானபலியையும் அன்றி, பாவநிவாரண பலியாக ஒரு வெள்ளாட்டுக்கடாவையும் செலுத்தக்கடவீர்கள்.", "en": "And one goat for a sin offering; beside the continual burnt offering, and his meat offering, and his drink offering."}, {"verse": 39, "start": 419.15, "end": 439.76, "ta": "உங்கள் பொருத்தனைகளையும், உங்கள் உற்சாகபலிகளையும், உங்கள் சர்வாங்க தகனபலிகளையும், உங்கள் போஜனபலிகளையும், உங்கள் பானபலிகளையும், உங்கள் சமாதானபலிகளையும் அன்றி, நீங்கள் உங்கள் பண்டிகைகளிலே கர்த்தருக்குச் செலுத்தவேண்டியவைகள் இவைகளே என்று சொல் என்றார்.", "en": "These things ye shall do unto the LORD in your set feasts, beside your vows, and your freewill offerings, for your burnt offerings, and for your meat offerings, and for your drink offerings, and for your peace offerings."}, {"verse": 40, "start": 439.76, "end": 446.63, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியெல்லாம் மோசே இஸ்ரவேல் புத்திரருக்குச் சொன்னான்.", "en": "And Moses told the children of Israel according to all that the LORD commanded Moses."}]}, "30": {"chapter": 30, "duration": 235.91, "audio_url": "audio_ot/OT04_30.mp3", "total_verses": 16, "verses": [{"verse": 1, "start": 3.8, "end": 10.48, "ta": "மோசே இஸ்ரவேல் புத்திரருடைய கோத்திரங்களின் தலைவரை நோக்கி: கர்த்தர் கட்டளையிடுவது என்னவென்றால்:", "en": "And Moses spake unto the heads of the tribes concerning the children of Israel, saying, This is the thing which the LORD hath commanded."}, {"verse": 2, "start": 10.48, "end": 27.78, "ta": "ஒருவன் கர்த்தருக்கு யாதொரு பொருத்தனை பண்ணினாலும், அல்லது யாதொரு காரியத்தைச் செய்யும்படி ஆணையிட்டுத் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்டாலும், அவன் சொல்தவறாமல் தன் வாயிலிருந்து புறப்பட்ட வாக்கின்படியெல்லாம் செய்யக்கடவன்.", "en": "If a man vow a vow unto the LORD , or swear an oath to bind his soul with a bond; he shall not break his word, he shall do according to all that proceedeth out of his mouth."}, {"verse": 3, "start": 27.78, "end": 39.91, "ta": "தன் தகப்பன் வீட்டிலிருக்கிற ஒரு பெண் பிள்ளை தன் சிறுவயதிலே கர்த்தருக்குப் பொருத்தனைபண்ணி யாதொரு காரியத்தைச் செய்யும்படி தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்டால்,", "en": "If a woman also vow a vow unto the LORD , and bind herself by a bond, being in her father’s house in her youth;"}, {"verse": 4, "start": 39.91, "end": 57.93, "ta": "அவள் செய்த பொருத்தனையையும், அவள் பண்ணிக்கொண்ட நிபந்தனையையும் அவளுடைய தகப்பன் கேட்டும் அவளுக்கு ஒன்றும் சொல்லாதிருப்பானானால், அவள் செய்த எல்லாப் பொருத்தனைகளும் அவள் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்ட நிபந்தனையும் நிறைவேறவேண்டும்.", "en": "And her father hear her vow, and her bond wherewith she hath bound her soul, and her father shall hold his peace at her: then all her vows shall stand, and every bond wherewith she hath bound her soul shall stand."}, {"verse": 5, "start": 57.93, "end": 78.76, "ta": "அவள் செய்த பொருத்தனைகளையும், அவள் செய்யும்படி தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்தின நிபந்தனையையும் அவளுடைய தகப்பன் கேட்கிற நாளிலே அவன் வேண்டாம் என்று தடுத்தால், அது நிறைவேறவேண்டியதில்லை; அவளுடைய தகப்பன் வேண்டாம் என்று தடுத்தபடியால், கர்த்தர் அதை அவளுக்கு மன்னிப்பார்.", "en": "But if her father disallow her in the day that he heareth; not any of her vows, or of her bonds wherewith she hath bound her soul, shall stand: and the LORD shall forgive her, because her father disallowed her."}, {"verse": 6, "start": 78.76, "end": 89.02, "ta": "அவள் பொருத்தனை பண்ணும்போதும், தன் உதடுகளைத் திறந்து தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொள்ளும்போதும், அவளுக்குப் புருஷன் இருந்தால்,", "en": "And if she had at all an husband, when she vowed, or uttered ought out of her lips, wherewith she bound her soul;"}, {"verse": 7, "start": 89.02, "end": 104.82, "ta": "அப்பொழுது அவளுடைய புருஷன் அதைக் கேட்டிருந்தும், அதைக் கேள்விப்படுகிற நாளிலே அவளுக்கு ஒன்றும் சொல்லாதிருந்தால், அவளுடைய பொருத்தனைகளும் அவள் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்தின நிபந்தனையும் நிறைவேறவேண்டும்.", "en": "And her husband heard it , and held his peace at her in the day that he heard it: then her vows shall stand, and her bonds wherewith she bound her soul shall stand."}, {"verse": 8, "start": 104.82, "end": 121.91, "ta": "அவளுடைய புருஷன் அதைக் கேட்கிற நாளில் அவன் வேண்டாம் என்று தடுத்து, அவள் செய்த பொருத்தனையும் அவள் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்ட நிபந்தனையும் செல்லாதபடி செய்தானேயானால், அப்பொழுது கர்த்தர் அதை அவளுக்கு மன்னிப்பார்.", "en": "But if her husband disallowed her on the day that he heard it; then he shall make her vow which she vowed, and that which she uttered with her lips, wherewith she bound her soul, of none effect: and the LORD shall forgive her."}, {"verse": 9, "start": 121.91, "end": 132.39, "ta": "ஒரு விதவையாவது, தள்ளப்பட்டுப்போன ஒரு ஸ்திரீயாவது தன் ஆத்துமாவை எந்த நிபந்தனைக்குட்படுத்திக்கொள்ளுகிறாளோ அந்த நிபந்தனை நிறைவேறவேண்டும்.", "en": "But every vow of a widow, and of her that is divorced, wherewith they have bound their souls, shall stand against her."}, {"verse": 10, "start": 132.39, "end": 144.09, "ta": "அவள் தன் புருஷனுடைய வீட்டில் யாதொரு பொருத்தனை பண்ணினாலும், அல்லது யாதொரு காரியத்தைச் செய்யும்படி ஆணையிட்டுத் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்திக்கொண்டாலும்,", "en": "And if she vowed in her husband’s house, or bound her soul by a bond with an oath;"}, {"verse": 11, "start": 144.09, "end": 159.45, "ta": "அவளுடைய புருஷன் அதைக் கேட்டும் அவளுக்கு அதை வேண்டாமென்று தடுக்காமல் மவுனமாயிருந்தால், அவள் செய்த எல்லாப் பொருத்தனைகளும், அவள் தன் ஆத்துமாவை நிபந்தனைக்குட்படுத்தின எல்லா நிபந்தனைகளும் நிறைவேறவேண்டும்.", "en": "And her husband heard it , and held his peace at her, and disallowed her not: then all her vows shall stand, and every bond wherewith she bound her soul shall stand."}, {"verse": 12, "start": 159.45, "end": 182.36, "ta": "அவளுடைய புருஷன் அவைகளைக்கேட்ட நாளில் அவைகளைச் செல்லாதபடி பண்ணினால், அப்பொழுது அவள் செய்த பொருத்தனைகளும், அவள் தன் ஆத்துமாவையுட்படுத்தின நிபந்தனையைக்குறித்து அவள் வாயிலிருந்து புறப்பட்டதொன்றும் நிறைவேறவேண்டியதில்லை; அவளுடைய புருஷன் அவைகளைச் செல்லாதபடி பண்ணினதினாலே கர்த்தர் அதை அவளுக்கு மன்னிப்பார்.", "en": "But if her husband hath utterly made them void on the day he heard them; then whatsoever proceeded out of her lips concerning her vows, or concerning the bond of her soul, shall not stand: her husband hath made them void; and the LORD shall forgive her."}, {"verse": 13, "start": 182.36, "end": 194.35, "ta": "எந்தப் பொருத்தனையையும் ஆத்துமாவைத் தாழ்மைப்படுத்தும்படி செய்யப்பட்ட எந்த ஆணையையும், அவளுடைய புருஷன் ஸ்திரப்படுத்தவுங்கூடும், செல்லாதபடி பண்ணவும் கூடும்.", "en": "Every vow, and every binding oath to afflict the soul, her husband may establish it, or her husband may make it void."}, {"verse": 14, "start": 194.35, "end": 215.02, "ta": "அவளுடைய புருஷன் ஒருநாளும் அவளுக்கு ஒன்றும் சொல்லாதிருந்தானாகில், அவன் அவளுடைய எல்லாப் பொருத்தனைகளையும், அவள்பேரிலிருக்கிற அவளுடைய எல்லா நிபந்தனைகளையும் ஸ்திரப்படுத்துகிறான்; அவன் அதைக் கேட்ட நாளிலே அவளுக்கு ஒன்றும் சொல்லாமற் போனதினால், அவைகளை ஸ்திரப்படுத்துகிறான்.", "en": "But if her husband altogether hold his peace at her from day to day; then he establisheth all her vows, or all her bonds, which are upon her: he confirmeth them, because he held his peace at her in the day that he heard them ."}, {"verse": 15, "start": 215.02, "end": 222.42, "ta": "அவன் அவைகளைக் கேட்டபின்பு செல்லாதபடி பண்ணினால், அவளுடைய அக்கிரமத்தை அவன் சுமப்பான் என்றார்.", "en": "But if he shall any ways make them void after that he hath heard them; then he shall bear her iniquity."}, {"verse": 16, "start": 222.42, "end": 234.41, "ta": "புருஷனையும் ஸ்திரீயையும், தகப்பனையும் தகப்பனுடைய வீட்டில் சிறுவயதில் இருக்கிற அவன் குமாரத்தியையும் குறித்து, கர்த்தர் மோசேக்கு விதித்த கட்டளைகள் இவைகளே.", "en": "These are the statutes, which the LORD commanded Moses, between a man and his wife, between the father and his daughter, being yet in her youth in her father’s house."}]}, "31": {"chapter": 31, "duration": 537.59, "audio_url": "audio_ot/OT04_31.mp3", "total_verses": 54, "verses": [{"verse": 1, "start": 3.8, "end": 5.53, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.53, "end": 15.7, "ta": "இஸ்ரவேல் புத்திரர் நிமித்தம் மீதியானியரிடத்தில் பழிவாங்குவாயாக; அதன்பின்பு உன் ஜனத்தாரிடத்தில் சேர்க்கப்படுவாய் என்றார்.", "en": "Avenge the children of Israel of the Midianites: afterward shalt thou be gathered unto thy people."}, {"verse": 3, "start": 15.7, "end": 29.03, "ta": "அப்பொழுது மோசே ஜனங்களை நோக்கி: கர்த்தர் நிமித்தம் மீதியானியரிடத்தில் பழிவாங்கும்பொருட்டு, உங்களில் அவர்கள்மேல் யுத்தத்திற்குப் போகத்தக்கதாக மனிதரைப் பிரித்தெடுங்கள்.", "en": "And Moses spake unto the people, saying, Arm some of yourselves unto the war, and let them go against the Midianites, and avenge the LORD of Midian."}, {"verse": 4, "start": 29.03, "end": 37.77, "ta": "இஸ்ரவேலுடைய எல்லாக் கோத்திரங்களிலும் ஒவ்வொரு கோத்திரத்தில் ஆயிரம்பேரை யுத்தத்திற்கு அனுப்பவேண்டும் என்றான்.", "en": "Of every tribe a thousand, throughout all the tribes of Israel, shall ye send to the war."}, {"verse": 5, "start": 37.77, "end": 49.07, "ta": "அப்படியே இஸ்ரவேலராகிய அநேகம் ஆயிரங்களில், ஒவ்வொரு கோத்திரத்தில் ஆயிரமாயிரம் பேராகப் பன்னீராயிரம்பேர் யுத்தசன்னத்தராய் நிறுத்தப்பட்டார்கள்.", "en": "So there were delivered out of the thousands of Israel, a thousand of every tribe, twelve thousand armed for war."}, {"verse": 6, "start": 49.07, "end": 63.53, "ta": "மோசே அவர்களையும் ஆசாரியனாகிய எலெயாசரின் குமாரன் பினெகாசையும் யுத்தத்திற்கு அனுப்புகையில், அவன் கையிலே பரிசுத்த தட்டுமுட்டுகளையும், தொனிக்கும் பூரிகைகளையும் கொடுத்து அனுப்பினான்.", "en": "And Moses sent them to the war, a thousand of every tribe, them and Phinehas the son of Eleazar the priest, to the war, with the holy instruments, and the trumpets to blow in his hand."}, {"verse": 7, "start": 63.53, "end": 72.94, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே அவர்கள் மீதியானியருடன் யுத்தம்பண்ணி, புருஷர்கள் யாவரையும் கொன்றுபோட்டார்கள்.", "en": "And they warred against the Midianites, as the LORD commanded Moses; and they slew all the males."}, {"verse": 8, "start": 72.94, "end": 89.97, "ta": "அவர்களைக் கொன்றுபோட்டதுமன்றி, மீதியானியரின் ஐந்து ராஜாக்களாகிய ஏவி, ரேக்கேம், சூர், ஊர், ரேபா என்பவர்களையும் கொன்றுபோட்டார்கள். பேயோரின் குமாரனாகிய பிலேயாமையும் பட்டயத்தினாலே கொன்றுபோட்டார்கள்.", "en": "And they slew the kings of Midian, beside the rest of them that were slain; namely , Evi, and Rekem, and Zur, and Hur, and Reba, five kings of Midian: Balaam also the son of Beor they slew with the sword."}, {"verse": 9, "start": 89.97, "end": 103.52, "ta": "அன்றியும் இஸ்ரவேல் புத்திரர் மீதியானியரின் ஸ்திரீகளையும் குழந்தைகளையும் சிறைபிடித்து, அவர்களுடைய மிருகஜீவன்களாகிய ஆடுமாடுகள் யாவையும், மற்ற ஆஸ்திகள் யாவையும் கொள்ளையிட்டு,", "en": "And the children of Israel took all the women of Midian captives, and their little ones, and took the spoil of all their cattle, and all their flocks, and all their goods."}, {"verse": 10, "start": 103.52, "end": 109.1, "ta": "அவர்கள் குடியிருந்த ஊர்கள் கோட்டைகள் யாவையும் அக்கினியால் சுட்டெரித்து,", "en": "And they burnt all their cities wherein they dwelt, and all their goodly castles, with fire."}, {"verse": 11, "start": 109.1, "end": 115.88, "ta": "தாங்கள் கொள்ளையிட்ட பொருளையும் தாங்கள் பிடித்த நரஜீவன் மிருகஜீவன் அனைத்தையும் சேர்த்து,", "en": "And they took all the spoil, and all the prey, both of men and of beasts."}, {"verse": 12, "start": 115.88, "end": 138.25, "ta": "சிறைபிடிக்கப்பட்ட மனிதரையும், மிருகங்களையும், கொள்ளையிட்ட பொருள்களையும் எரிகோவின் அருகேயுள்ள யோர்தானுக்கு இக்கரையில் மோவாபின் சமனான வெளிகளிலுள்ள பாளயத்திலிருந்த மோசேயினிடத்துக்கும், ஆசாரியனாகிய எலெயாசாரினிடத்துக்கும், இஸ்ரவேல் புத்திரராகிய சபையாரிடத்துக்கும் கொண்டுவந்தார்கள்.", "en": "And they brought the captives, and the prey, and the spoil, unto Moses, and Eleazar the priest, and unto the congregation of the children of Israel, unto the camp at the plains of Moab, which are by Jordan near Jericho."}, {"verse": 13, "start": 138.25, "end": 148.34, "ta": "மோசேயும் ஆசாரியனாகிய எலெயாசாரும் சபையின் பிரபுக்கள் எல்லாரும் அவர்களைச் சந்திக்கப் பாளயத்திற்கு வெளியே புறப்பட்டுப்போனார்கள்.", "en": "And Moses, and Eleazar the priest, and all the princes of the congregation, went forth to meet them without the camp."}, {"verse": 14, "start": 148.34, "end": 157.76, "ta": "அப்பொழுது மோசே யுத்தத்திலிருந்து வந்த ஆயிரம்பேருக்குத் தலைவரும், நூறுபேருக்குத் தலைவருமாகிய சேனாபதிகள்மேல் கோபங்கொண்டு,", "en": "And Moses was wroth with the officers of the host, with the captains over thousands, and captains over hundreds, which came from the battle."}, {"verse": 15, "start": 157.76, "end": 163.25, "ta": "அவர்களை நோக்கி: ஸ்திரீகள் எல்லாரையும் உயிரோடே விட்டுவிட்டீர்களா?", "en": "And Moses said unto them, Have ye saved all the women alive?"}, {"verse": 16, "start": 163.25, "end": 178.02, "ta": "பேயோரின் சங்கதியிலே பிலேயாமின் ஆலோசனையினால் இஸ்ரவேல் புத்திரர் கர்த்தருக்கு விரோதமாய்த் துரோகம்பண்ணக் காரணமாயிருந்தவர்கள் இவர்கள்தானே; அதினால் கர்த்தரின் சபையிலே வாதையும் நேரிட்டதே.", "en": "Behold, these caused the children of Israel, through the counsel of Balaam, to commit trespass against the LORD in the matter of Peor, and there was a plague among the congregation of the LORD ."}, {"verse": 17, "start": 178.02, "end": 186.75, "ta": "ஆகையால் குழந்தைகளில் எல்லா ஆண்பிள்ளைகளையும், புருஷசம்யோகத்தை அறிந்த எல்லா ஸ்திரீகளையும் கொன்றுபோடுங்கள்.", "en": "Now therefore kill every male among the little ones, and kill every woman that hath known man by lying with him."}, {"verse": 18, "start": 186.75, "end": 194.29, "ta": "ஸ்திரீகளில் புருஷசம்யோகத்தை அறியாத எல்லாப் பெண்பிள்ளைகளையும் உங்களுக்காக உயிரோடே வையுங்கள்.", "en": "But all the women children, that have not known a man by lying with him, keep alive for yourselves."}, {"verse": 19, "start": 194.29, "end": 212.36, "ta": "பின்பு நீங்கள் ஏழுநாள் பாளயத்திற்குப் புறம்பே தங்குங்கள்; நரஜீவனைக் கொன்றவர்களும், வெட்டுண்டவர்ளைத் தொட்டவர்களுமாகிய நீங்கள் யாவரும் மூன்றாம் நாளிலும் ஏழாம் நாளிலும் உங்களையும் உங்களால் சிறைபிடிக்கப்பட்டவர்களையும் சுத்திகரித்து,", "en": "And do ye abide without the camp seven days: whosoever hath killed any person, and whosoever hath touched any slain, purify both yourselves and your captives on the third day, and on the seventh day."}, {"verse": 20, "start": 212.36, "end": 224.79, "ta": "அந்தப்படியே எல்லா வஸ்திரத்தையும், தோலால் செய்த கருவிகளையும், வெள்ளாட்டுமயிரினால் நெய்தவைகளையும், மரச்சாமான்களையும் சுத்திகரிக்கக்கடவீர்கள் என்றான்.", "en": "And purify all your raiment, and all that is made of skins, and all work of goats’ hair , and all things made of wood."}, {"verse": 21, "start": 224.79, "end": 234.28, "ta": "ஆசாரியனாகிய எலெயாசாரும் யுத்தத்திற்குப் போய்வந்த படைவீரரை நோக்கி: கர்த்தர் மோசேக்குக் கட்டளையிட்ட விதிப்பிரமாணம் என்னவென்றால்:", "en": "And Eleazar the priest said unto the men of war which went to the battle, This is the ordinance of the law which the LORD commanded Moses;"}, {"verse": 22, "start": 234.28, "end": 244.22, "ta": "அக்கினிக்கு நிற்கத்தக்கவைகளாகிய பொன், வெள்ளி, வெண்கலம், இரும்பு, தகரம், ஈயம் ஆகிய இவைகளெல்லாம் சுத்தமாகும்படிக்கு,", "en": "Only the gold, and the silver, the brass, the iron, the tin, and the lead,"}, {"verse": 23, "start": 244.22, "end": 259.21, "ta": "அவைகளை அக்கினியிலே போட்டெடுக்கக்கடவீர்கள்; தீட்டுக்கழிக்கும் தண்ணீராலும் அவைகள் சுத்திகரிக்கப்படவேண்டும்; அக்கினிக்கு நிற்கத்தகாதவைகளையெல்லாம் தண்ணீரினால் சுத்தம்பண்ணக்கடவீர்கள்.", "en": "Every thing that may abide the fire, ye shall make it go through the fire, and it shall be clean: nevertheless it shall be purified with the water of separation: and all that abideth not the fire ye shall make go through the water."}, {"verse": 24, "start": 259.21, "end": 270.43, "ta": "ஏழாம் நாளில் உங்கள் வஸ்திரங்களைத் தோய்க்கவேண்டும்; அப்பொழுது சுத்தமாயிருப்பீர்கள்; பின்பு நீங்கள் பாளயத்திற்குள் வரலாம் என்றான்.", "en": "And ye shall wash your clothes on the seventh day, and ye shall be clean, and afterward ye shall come into the camp."}, {"verse": 25, "start": 270.43, "end": 272.17, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 26, "start": 272.17, "end": 282.11, "ta": "பிடித்துக்கொண்டு வரப்பட்ட மனிதரையும் மிருகங்களையும் நீயும் ஆசாரியனாகிய எலெயாசாரும் சபையினுடைய பிதாக்களாகிய தலைவரும் தொகைபார்த்து,", "en": "Take the sum of the prey that was taken, both of man and of beast, thou, and Eleazar the priest, and the chief fathers of the congregation:"}, {"verse": 27, "start": 282.11, "end": 291.83, "ta": "கொள்ளையிடப்பட்டதை இரண்டு பங்காகப் பங்கிட்டு, யுத்தத்திற்குப் படையெடுத்துப்போனவர்களுக்கும் சபையனைத்திற்கும் கொடுங்கள்.", "en": "And divide the prey into two parts; between them that took the war upon them, who went out to battle, and between all the congregation:"}, {"verse": 28, "start": 291.83, "end": 303.2, "ta": "மேலும் யுத்தத்திற்குப்போன படைவீரரிடத்தில் கர்த்தருக்காக மனிதரிலும் மாடுகளிலும் கழுதைகளிலும் ஆடுகளிலும் ஐந்நூற்றிற்கு ஒரு பிராணி வீதமாக பகுதி வாங்கி,", "en": "And levy a tribute unto the LORD of the men of war which went out to battle: one soul of five hundred, both of the persons, and of the beeves, and of the asses, and of the sheep:"}, {"verse": 29, "start": 303.2, "end": 313.29, "ta": "அவர்களுடைய பாதிப்பங்கில் எடுத்து, கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் படைப்பாக ஆசாரியனாகிய எலெயாசாருக்குக் கொடுக்கவேண்டும்.", "en": "Take it of their half, and give it unto Eleazar the priest, for an heave offering of the LORD ."}, {"verse": 30, "start": 313.29, "end": 330.84, "ta": "இஸ்ரவேல் புத்திரரின் பாதிப்பங்கிலோ மனிதரிலும், மாடுகள் கழுதைகள் ஆடுகளாகிய சகலவித மிருகங்களிலும், ஐம்பதிற்கு ஒன்று வீதமாய் வாங்கி அவைகளைக் கர்த்தருடைய வாசஸ்தலத்தின் காவலைக்காக்கும் லேவியருக்குக் கொடுக்கவேண்டும் என்றார்.", "en": "And of the children of Israel’s half, thou shalt take one portion of fifty, of the persons, of the beeves, of the asses, and of the flocks, of all manner of beasts, and give them unto the Levites, which keep the charge of the tabernacle of the LORD ."}, {"verse": 31, "start": 330.84, "end": 338.0, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, மோசேயும் ஆசாரியனாகிய எலெயாசாரும் செய்தார்கள்.", "en": "And Moses and Eleazar the priest did as the LORD commanded Moses."}, {"verse": 32, "start": 338.0, "end": 343.57, "ta": "படைவீரர் கொள்ளையிட்ட பொருளில், ஆறுலட்சத்து எழுபத்தையாயிரம் ஆடுகளும்,", "en": "And the booty, being the rest of the prey which the men of war had caught, was six hundred thousand and seventy thousand and five thousand sheep,"}, {"verse": 33, "start": 343.57, "end": 345.76, "ta": "எழுபத்தீராயிரம் மாடுகளும்,", "en": "And threescore and twelve thousand beeves,"}, {"verse": 34, "start": 345.76, "end": 349.67, "ta": "அறுபத்தோராயிரம் கழுதைகளும் மீதியாயிருந்தது.", "en": "And threescore and one thousand asses,"}, {"verse": 35, "start": 349.67, "end": 355.55, "ta": "புருஷசம்யோகத்தை அறியாத ஸ்திரீகளில் முப்பத்தீராயிரம்பேர் இருந்தார்கள்.", "en": "And thirty and two thousand persons in all, of women that had not known man by lying with him."}, {"verse": 36, "start": 355.55, "end": 364.74, "ta": "யுத்தஞ்செய்யப் போனவர்களுக்குக் கிடைத்த பாதிப்பங்கின் தொகையாவது: ஆடுகள் மூன்றுலட்சத்து முப்பத்தேழாயிரத்து ஐந்நூறு.", "en": "And the half, which was the portion of them that went out to war, was in number three hundred thousand and seven and thirty thousand and five hundred sheep:"}, {"verse": 37, "start": 364.74, "end": 370.54, "ta": "இந்த ஆடுகளிலே கர்த்தருக்குப் பகுதியாக வந்தது அறுநூற்று எழுபத்தைந்து.", "en": "And the LORD’s tribute of the sheep was six hundred and threescore and fifteen."}, {"verse": 38, "start": 370.54, "end": 377.69, "ta": "மாடுகள் முப்பத்தாறாயிரம்; அவைகளில் கர்த்தருக்குப் பகுதியாக வந்தது எழுபத்திரண்டு.", "en": "And the beeves were thirty and six thousand; of which the LORD’s tribute was threescore and twelve."}, {"verse": 39, "start": 377.69, "end": 385.45, "ta": "கழுதைகள் முப்பதினாயிரத்து ஐந்நூறு; அவைகளில் கர்த்தருக்குப் பகுதியாக வந்தது அறுபத்தொன்று.", "en": "And the asses were thirty thousand and five hundred; of which the LORD’s tribute was threescore and one."}, {"verse": 40, "start": 385.45, "end": 393.66, "ta": "நரஜீவன்கள் பதினாறாயிரம் பேர்; அவர்களில் கர்த்தருக்குப் பகுதியாக வந்தவர்கள் முப்பத்திரண்டுபேர்.", "en": "And the persons were sixteen thousand; of which the LORD’s tribute was thirty and two persons."}, {"verse": 41, "start": 393.66, "end": 404.73, "ta": "கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் அந்தப் பகுதியை, மோசே கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, ஆசாரியனாகிய எலெயாசாரிடத்தில் கொடுத்தான்.", "en": "And Moses gave the tribute, which was the LORD’s heave offering, unto Eleazar the priest, as the LORD commanded Moses."}, {"verse": 42, "start": 404.73, "end": 413.92, "ta": "யுத்தம்பண்ணின பேர்களுக்கும் இஸ்ரவேல் புத்திரருக்கும் மோசே பாதிபாதியாகப் பங்கிட்டதின்படியே சபையாருக்கு வந்த பாதிப்பங்காவது:", "en": "And of the children of Israel’s half, which Moses divided from the men that warred,"}, {"verse": 43, "start": 413.92, "end": 417.99, "ta": "ஆடுகளில் முன்றுலட்சத்து முப்பத்தேழாயிரத்து ஐந்நூறு,", "en": "(Now the half that pertained unto the congregation was three hundred thousand and thirty thousand and seven thousand and five hundred sheep,"}, {"verse": 44, "start": 417.99, "end": 420.25, "ta": "மாடுகளில் முப்பத்தாறாயிரம்,", "en": "And thirty and six thousand beeves,"}, {"verse": 45, "start": 420.25, "end": 423.18, "ta": "கழுதைகளில் முப்பதினாயிரத்து ஐந்நூறு,", "en": "And thirty thousand asses and five hundred,"}, {"verse": 46, "start": 423.18, "end": 426.2, "ta": "நரஜீவன்களில் பதினாயிரம் பேருமே.", "en": "And sixteen thousand persons;)"}, {"verse": 47, "start": 426.2, "end": 444.42, "ta": "இஸ்ரவேல் புத்திரரின் பாதிப்பங்குக்கு வந்த இந்த நரஜீவன்களிலும் மிருகங்களிலும் மோசே ஐம்பதுக்கு ஒன்று வீதமாக எடுத்து, அவைகளைக் கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, கர்த்தருடைய வாசஸ்தலத்தின் காவலைக் காக்கிற லேவியருக்குக் கொடுத்தான்.", "en": "Even of the children of Israel’s half, Moses took one portion of fifty, both of man and of beast, and gave them unto the Levites, which kept the charge of the tabernacle of the LORD ; as the LORD commanded Moses."}, {"verse": 48, "start": 444.42, "end": 451.51, "ta": "பின்பு ஆயிரம்பேருக்குத் தலைவரும் நூறுபேருக்குத் தலைவருமான சேனாபதிகள் மோசேயினிடத்தில் வந்து,", "en": "And the officers which were over thousands of the host, the captains of thousands, and captains of hundreds, came near unto Moses:"}, {"verse": 49, "start": 451.51, "end": 461.45, "ta": "ஊழியக்காரராகிய நாங்கள் எங்கள் கையின் கீழிருக்கிற யுத்தமனிதரைத் தொகைபார்த்தோம்; அவர்களுக்குள்ளே ஒரு ஆளும் குறையவில்லை.", "en": "And they said unto Moses, Thy servants have taken the sum of the men of war which are under our charge, and there lacketh not one man of us."}, {"verse": 50, "start": 461.45, "end": 482.99, "ta": "ஆகையால், கர்த்தருடைய சந்நிதியில் எங்கள் ஆத்துமாக்களுக்காகப் பாவநிவிர்த்தி செய்யும்பொருட்டு, எங்களுக்குக் கிடைத்த பொற்பணிகளாகிய பாதசரங்களையும், அஸ்தகடகங்களையும், மோதிரங்களையும், காதணிகளையும், காப்புகளையும் கர்த்தருக்குக் காணிக்கையாகக் கொண்டுவந்தோம் என்றார்கள்.", "en": "We have therefore brought an oblation for the LORD , what every man hath gotten, of jewels of gold, chains, and bracelets, rings, earrings, and tablets, to make an atonement for our souls before the LORD ."}, {"verse": 51, "start": 482.99, "end": 492.93, "ta": "அப்பொழுது மோசேயும் ஆசாரியனாகிய எலெயாசாரும் சகலவித வேலைப்பாடான பணிதிகளான அந்தப் பொன்னாபரணங்களை அவர்களிடத்தில் வாங்கினார்கள்.", "en": "And Moses and Eleazar the priest took the gold of them, even all wrought jewels."}, {"verse": 52, "start": 492.93, "end": 509.35, "ta": "இப்படி ஆயிரம்பேருக்குத் தலைவரானவர்களாலும் நூறுபேருக்குத் தலைவரானவர்களாலும் கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் காணிக்கையாகச் செலுத்தப்பட்ட பொன் முழுவதும் பதினாறாயிரத்து எழுநூற்று ஐம்பது சேக்கல் நிறையாயிருந்தது.", "en": "And all the gold of the offering that they offered up to the LORD , of the captains of thousands, and of the captains of hundreds, was sixteen thousand seven hundred and fifty shekels."}, {"verse": 53, "start": 509.35, "end": 516.43, "ta": "யுத்தத்திற்குப் போன மனிதர் ஒவ்வொருவரும் தங்கள் தங்களுக்காகக் கொள்ளையிட்டிருந்தார்கள்.", "en": "( For the men of war had taken spoil, every man for himself.)"}, {"verse": 54, "start": 516.43, "end": 536.09, "ta": "அந்தப் பொன்னை மோசேயும் ஆசாரியனாகிய எலெயாசாரும் ஆயிரம்பேருக்குத் தலைவரானவர்களின் கையிலும், நூறுபேருக்குத் தலைவரானவர்களின் கையிலும் வாங்கி, இஸ்ரவேல் புத்திரருக்கு ஞாபகக்குறியாக ஆசரிப்புக் கூடாரத்திலே கர்த்தருடைய சந்நிதியில் கொண்டுவந்து வைத்தார்கள்.", "en": "And Moses and Eleazar the priest took the gold of the captains of thousands and of hundreds, and brought it into the tabernacle of the congregation, for a memorial for the children of Israel before the LORD ."}]}, "32": {"chapter": 32, "duration": 471.6, "audio_url": "audio_ot/OT04_32.mp3", "total_verses": 42, "verses": [{"verse": 1, "start": 3.8, "end": 18.41, "ta": "ரூபன் புத்திரருக்கும் காத் புத்திரருக்கும் ஆடுமாடுகள் மிகவும் திரளாயிருந்தது; அவர்கள் யாசேர் தேசத்தையும் கீலேயாத் தேசத்தையும் பார்த்தபோது, அது ஆடுமாடுகளுக்குத் தகுந்த இடமென்று கண்டார்கள்.", "en": "Now the children of Reuben and the children of Gad had a very great multitude of cattle: and when they saw the land of Jazer, and the land of Gilead, that, behold, the place was a place for cattle;"}, {"verse": 2, "start": 18.41, "end": 26.96, "ta": "ஆகையால் ரூபன் புத்திரரும் காத் புத்திரரும் வந்து, மோசேயையும் ஆசாரியனாகிய எலெயாசாரையும் சபையின் பிரபுக்களையும் நோக்கி:", "en": "The children of Gad and the children of Reuben came and spake unto Moses, and to Eleazar the priest, and unto the princes of the congregation, saying,"}, {"verse": 3, "start": 26.96, "end": 42.43, "ta": "கர்த்தர் இஸ்ரவேல் சபைக்கு முன்பாக முறிய அடித்த அதரோத், தீபோன், யாசேர், நிம்ரா, எஸ்போன், எலெயாலெ, சேபாம், நேபோ, பெயோன் என்னும் பட்டணங்களைச் சேர்ந்த நாடானது ஆடுமாடுகளுக்குத் தகுந்த இடம்.", "en": "Ataroth, and Dibon, and Jazer, and Nimrah, and Heshbon, and Elealeh, and Shebam, and Nebo, and Beon,"}, {"verse": 4, "start": 42.43, "end": 45.49, "ta": "உமது அடியாருக்கு ஆடுமாடுகள் உண்டு.", "en": "Even the country which the LORD smote before the congregation of Israel, is a land for cattle, and thy servants have cattle:"}, {"verse": 5, "start": 45.49, "end": 59.46, "ta": "உம்முடைய கண்களில் எங்களுக்குத் தயை கிடைத்ததானால், எங்களை யோர்தான் நதிக்கு அப்புறம் கடந்துபோகப்பண்ணீராக; இந்த நாட்டை உமது அடியாருக்குக் காணியாட்சியாகக் கொடுக்கவேண்டும் என்றார்கள்.", "en": "Wherefore, said they, if we have found grace in thy sight, let this land be given unto thy servants for a possession, and bring us not over Jordan."}, {"verse": 6, "start": 59.46, "end": 69.58, "ta": "அப்பொழுது மோசே காத் புத்திரரையும் ரூபன் புத்திரரையும் நோக்கி: உங்கள் சகோதரர் யுத்தத்திற்குப் போகையில், நீங்கள் இங்கே இருப்பீர்களோ?", "en": "And Moses said unto the children of Gad and to the children of Reuben, Shall your brethren go to war, and shall ye sit here?"}, {"verse": 7, "start": 69.58, "end": 79.91, "ta": "கர்த்தர் இஸ்ரவேல் புத்திரருக்குக் கொடுத்த தேசத்திற்கு அவர்கள் போகாதபடிக்கு, நீங்கள் அவர்கள் இருதயத்தைத் திடனற்றுப்போகப்பண்ணுகிறதென்ன?", "en": "And wherefore discourage ye the heart of the children of Israel from going over into the land which the LORD hath given them?"}, {"verse": 8, "start": 79.91, "end": 89.11, "ta": "அந்த தேசத்தைப் பார்ப்பதற்கு நான் உங்கள் பிதாக்களைக் காதேஸ்பர்னேயாவிலிருந்து அனுப்பினபோது அவர்களும் இப்படியே செய்தார்கள்.", "en": "Thus did your fathers, when I sent them from Kadesh-barnea to see the land."}, {"verse": 9, "start": 89.11, "end": 104.0, "ta": "அவர்கள் எஸ்கோல் பள்ளத்தாக்குமட்டும் போய், அத்தேசத்தைப் பார்த்துவந்து, இஸ்ரவேல் புத்திரர் கர்த்தர் தங்களுக்குக் கொடுத்த தேசத்திற்குப் போகாதபடிக்கு அவர்கள் இருதயத்தைத் திடனற்றுப்போகப்பண்ணினார்கள்.", "en": "For when they went up unto the valley of Eshcol, and saw the land, they discouraged the heart of the children of Israel, that they should not go into the land which the LORD had given them."}, {"verse": 10, "start": 104.0, "end": 107.14, "ta": "அதினால் கர்த்தர் அந்நாளிலே கோபம் மூண்டவராகி:", "en": "And the LORD’s anger was kindled the same time, and he sware, saying,"}, {"verse": 11, "start": 107.14, "end": 114.91, "ta": "உத்தமமாய் என்னைப் பின்பற்றின கேனேசியனான எப்புன்னேயின் குமாரன் காலேபும், நூனின் குமாரன் யோசுவாவும் தவிர,", "en": "Surely none of the men that came up out of Egypt, from twenty years old and upward, shall see the land which I sware unto Abraham, unto Isaac, and unto Jacob; because they have not wholly followed me:"}, {"verse": 12, "start": 114.91, "end": 133.08, "ta": "எகிப்திலிருந்து வந்தவர்களில் இருபது வயதுமுதல் அதற்கு மேற்பட்டமனிதர்களில் ஒருவரும் என்னை உத்தமமாய்ப் பின்பற்றாதபடியால், அவர்கள் நான் ஆபிரகாமுக்கும் ஈசாக்குக்கும் யாக்கோபுக்கும் ஆணையிட்டுக்கொடுத்த தேசத்தைக் காண்பதில்லை என்று ஆணையிட்டிருக்கிறார்.", "en": "Save Caleb the son of Jephunneh the Kenezite, and Joshua the son of Nun: for they have wholly followed the LORD ."}, {"verse": 13, "start": 133.08, "end": 147.47, "ta": "அப்படியே கர்த்தருடைய கோபம் இஸ்ரவேலின்மேல் மூண்டது; கர்த்தருடைய சமுகத்தில் பொல்லாப்புச் செய்த அந்தச் சந்ததியெல்லாம் நிர்மூலமாகுமட்டும் அவர்களை வனாந்தரத்திலே நாற்பது வருஷம் அலையப்பண்ணினார்.", "en": "And the LORD’s anger was kindled against Israel, and he made them wander in the wilderness forty years, until all the generation, that had done evil in the sight of the LORD , was consumed."}, {"verse": 14, "start": 147.47, "end": 161.8, "ta": "இப்பொழுதும் இதோ இஸ்ரவேலர்மேலிருக்கும் கர்த்தருடைய கோபத்தின் உக்கிரத்தை இன்னும் அதிகரிக்கப்பண்ணும்படி, நீங்கள் உங்கள் பிதாக்களின் ஸ்தானத்திலே பாவமுள்ள பெருங்கூட்டமாய் எழும்பியிருக்கிறீர்கள்.", "en": "And, behold, ye are risen up in your fathers’ stead, an increase of sinful men, to augment yet the fierce anger of the LORD toward Israel."}, {"verse": 15, "start": 161.8, "end": 174.06, "ta": "நீங்கள் அவரைவிட்டுப் பின்வாங்கினால், அவர் இன்னும் அவர்களை வனாந்தரத்தில் இருக்கப்பண்ணுவார்; இப்படி நீங்கள் இந்த ஜனங்களையெல்லாம் அழியப்பண்ணுவீர்கள் என்றான்.", "en": "For if ye turn away from after him, he will yet again leave them in the wilderness; and ye shall destroy all this people."}, {"verse": 16, "start": 174.06, "end": 184.68, "ta": "அப்பொழுது அவர்கள் அவன் சமீபத்தில் வந்து: எங்கள் ஆடுமாடுகளுக்காகத் தொழுவங்களையும், எங்கள் பிள்ளைகளுக்காகப் பட்டணங்களையும் இங்கே கட்டுவோம்.", "en": "And they came near unto him, and said, We will build sheepfolds here for our cattle, and cities for our little ones:"}, {"verse": 17, "start": 184.68, "end": 202.92, "ta": "நாங்களோ இஸ்ரவேல் புத்திரரை அவர்கள் ஸ்தானத்திலே கொண்டுபோய்ச் சேர்க்குமளவும், யுத்தசன்னத்தாரய்த் தீவிரத்தோடே அவர்களுக்கு முன்பாக நடப்போம்; எங்கள் பிள்ளைகள் இத்தேசத்துக் குடிகளினிமித்தம் அரணான பட்டணங்களிலே குடியிருக்கக் கேட்டுக்கொள்ளுகிறோம்.", "en": "But we ourselves will go ready armed before the children of Israel, until we have brought them unto their place: and our little ones shall dwell in the fenced cities because of the inhabitants of the land."}, {"verse": 18, "start": 202.92, "end": 213.32, "ta": "இஸ்ரவேல் புத்திரர் யாவரும் தங்கள் தங்கள் சுதந்தரத்தைச் சுதந்தரித்துக் கொள்ளும்வரைக்கும், நாங்கள் எங்கள் வீடுகளுக்குத் திரும்புவதில்லை.", "en": "We will not return unto our houses, until the children of Israel have inherited every man his inheritance."}, {"verse": 19, "start": 213.32, "end": 227.15, "ta": "யோர்தானுக்கு இப்புறத்தில் கிழக்கே எங்களுக்குச் சுதந்தரம் உண்டானபடியினாலே, நாங்கள் அவர்களோடேகூட யோர்தானுக்கு அக்கரையிலும், அதற்கு அப்புறத்திலும் சுதந்தரம் வாங்கமாட்டோம் என்றார்கள்.", "en": "For we will not inherit with them on yonder side Jordan, or forward; because our inheritance is fallen to us on this side Jordan eastward."}, {"verse": 20, "start": 227.15, "end": 235.42, "ta": "அப்பொழுது மோசே அவர்களை நோக்கி: நீங்கள் இந்த வார்த்தையின்படியே செய்து, கர்த்தருடைய சமுகத்தில் யுத்தசன்னத்தராகி,", "en": "And Moses said unto them, If ye will do this thing, if ye will go armed before the LORD to war,"}, {"verse": 21, "start": 235.42, "end": 247.68, "ta": "கர்த்தர் தம்முடைய சத்துருக்களைத் தம்முடைய முகத்திற்கு முன்னின்று துரத்திவிடுமளவும், நீங்கள் யாவரும் அவருடைய சமுகத்தில் யுத்தசன்னத்தராய் யோர்தானைக் கடந்துபோவீர்களனால்,", "en": "And will go all of you armed over Jordan before the LORD , until he hath driven out his enemies from before him,"}, {"verse": 22, "start": 247.68, "end": 265.71, "ta": "அத்தேசம் கர்த்தருக்கு முன்பாக வசப்படுத்தப்பட்டபின்பு நீங்கள் திரும்பிவந்து, கர்த்தருக்கு முன்பாகவும், இஸ்ரவேலருக்கு முன்பாகவும், குற்றமில்லாதிருப்பீர்கள்; அதற்குப்பின்பு இந்த தேசம் கர்த்தருக்கு முன்பாக உங்களுக்குச் சுதந்தரமாகும்.", "en": "And the land be subdued before the LORD : then afterward ye shall return, and be guiltless before the LORD , and before Israel; and this land shall be your possession before the LORD ."}, {"verse": 23, "start": 265.71, "end": 278.39, "ta": "நீங்கள் இப்படிச் செய்யாமற்போனால், கர்த்தருக்கு விரோதமாகப் பாவம் செய்தவர்களாயிருப்பீர்கள்; உங்கள் பாவம் உங்களைத் தொடர்ந்துபிடிக்கும் என்று நிச்சயமாய் அறியுங்கள்.", "en": "But if ye will not do so, behold, ye have sinned against the LORD : and be sure your sin will find you out."}, {"verse": 24, "start": 278.39, "end": 288.87, "ta": "உங்கள் பிள்ளைகளுக்காகப் பட்டணங்களையும், உங்கள் ஆடுமாடுகளுக்காகத் தொழுவங்களையும் கட்டி, உங்கள் வாய்மொழியின்படியே செய்யுங்கள் என்றான்.", "en": "Build you cities for your little ones, and folds for your sheep; and do that which hath proceeded out of your mouth."}, {"verse": 25, "start": 288.87, "end": 298.7, "ta": "அப்பொழுது காத் புத்திரரும் ரூபன் புத்திரரும் மோசேயை நோக்கி: எங்கள் ஆண்டவன் கட்டளையிட்டபடியே உமது ஊழியக்காரராகிய நாங்கள் செய்வோம்.", "en": "And the children of Gad and the children of Reuben spake unto Moses, saying, Thy servants will do as my lord commandeth."}, {"verse": 26, "start": 298.7, "end": 309.61, "ta": "எங்கள் பிள்ளைகளையும் எங்கள் மனைவிகளும், எங்கள் ஆடுமாடு முதலான எங்களுடைய எல்லா மிருகஜீவன்களோடும் இங்கே கீலேயாத்தின் பட்டணங்களில் இருப்பார்கள்.", "en": "Our little ones, our wives, our flocks, and all our cattle, shall be there in the cities of Gilead:"}, {"verse": 27, "start": 309.61, "end": 320.87, "ta": "உமது ஊழியக்காரராகிய நாங்களோ எங்கள் ஆண்டவன் சொன்னபடியே, ஒவ்வொருவரும் யுத்தசன்னத்தராய், கர்த்தருடைய சமுகத்தில் யுத்தத்திற்குப் போவோம் என்றார்கள்.", "en": "But thy servants will pass over, every man armed for war, before the LORD to battle, as my lord saith."}, {"verse": 28, "start": 320.87, "end": 332.91, "ta": "அப்பொழுது மோசே அவர்களுக்காக ஆசாரியனாகிய எலெயாசாருக்கும், நூனின் குமாரனாகிய யோசுவாவுக்கும், இஸ்ரவேல் புத்திரருடைய கோத்திர பிதாக்களாகிய தலைவர்களுக்கும் கட்டளையிட்டு:", "en": "So concerning them Moses commanded Eleazar the priest, and Joshua the son of Nun, and the chief fathers of the tribes of the children of Israel:"}, {"verse": 29, "start": 332.91, "end": 349.73, "ta": "காத் புத்திரரும் ரூபன் புத்திரரும் அவரவர் கர்த்தருடைய சமுகத்தில் யுத்தசன்னத்தாராய் உங்களோடேகூட யோர்தானைக் கடந்துபோனால், அத்தேசம் உங்களுக்கு வசப்பட்டபின்பு, அவர்களுக்குக் கீலேயாத் தேசத்தைச் சுதந்தரமாகக் கொடுக்கக்கடவீர்கள்.", "en": "And Moses said unto them, If the children of Gad and the children of Reuben will pass with you over Jordan, every man armed to battle, before the LORD , and the land shall be subdued before you; then ye shall give them the land of Gilead for a possession:"}, {"verse": 30, "start": 349.73, "end": 360.06, "ta": "உங்களோடேகூட யுத்தசன்னத்தராய்க் கடந்துபோகாதிருந்தார்களேயானால், அவர்கள் உங்கள் நடுவே கானான் தேசத்திலே சுதந்தரம் அடையக்கடவர்கள் என்றான்.", "en": "But if they will not pass over with you armed, they shall have possessions among you in the land of Canaan."}, {"verse": 31, "start": 360.06, "end": 369.61, "ta": "காத் புத்திரரும் ரூபன் புத்திரரும் பிரதியுத்தரமாக: உம்முடைய ஊழியக்காரராகிய நாங்கள் கர்த்தர் எங்களுக்குச் சொன்னபடியே செய்வோம்.", "en": "And the children of Gad and the children of Reuben answered, saying, As the LORD hath said unto thy servants, so will we do."}, {"verse": 32, "start": 369.61, "end": 382.37, "ta": "யோர்தானுக்கு இக்கரையிலே எங்கள் சுதந்தரத்தின் காணியாட்சி எங்களுக்கு உரியதாகும்படி நாங்கள் கர்த்தருடைய சமுகத்தில் யுத்தசன்னத்தாராய்க் கானான்தேசத்திற்குப் போவோம் என்றார்கள்.", "en": "We will pass over armed before the LORD into the land of Canaan, that the possession of our inheritance on this side Jordan may be ours."}, {"verse": 33, "start": 382.37, "end": 405.18, "ta": "அப்பொழுது மோசே காத் புத்திரருக்கும், ரூபன் புத்திரருக்கும், யோசேப்பின் குமாரனாகிய மனாசேயின் பாதிக் கோத்திரத்தாருக்கும், எமோரியருடைய ராஜாவாகிய சீகோனின் ராஜ்யத்தையும், பாசானுடைய ராஜாவாகிய ஓகின் ராஜ்யத்தையும், அவைகளைச் சேர்ந்த தேசங்களையும் அவைகளின் எல்லையைச் சுற்றிலுமுள்ள பட்டணங்களையும் கொடுத்தான்.", "en": "And Moses gave unto them, even to the children of Gad, and to the children of Reuben, and unto half the tribe of Manasseh the son of Joseph, the kingdom of Sihon king of the Amorites, and the kingdom of Og king of Bashan, the land, with the cities thereof in the coasts, even the cities of the country round about."}, {"verse": 34, "start": 405.18, "end": 409.31, "ta": "பின்பு காத் சந்ததியார் தீபோன், அதரோத் ஆரோவேர்.", "en": "And the children of Gad built Dibon, and Ataroth, and Aroer,"}, {"verse": 35, "start": 409.31, "end": 412.59, "ta": "ஆத்ரோத், சோபான், யாசேர், யொகிபேயா,", "en": "And Atroth, Shophan, and Jaazer, and Jogbehah,"}, {"verse": 36, "start": 412.59, "end": 419.57, "ta": "பெத்நிம்ரா, பெத்தாரன் என்னும் அரணான பட்டணங்களையும் ஆட்டுத்தொழுவங்களையும் கட்டினார்கள்.", "en": "And Beth-nimrah, and Beth-haran, fenced cities: and folds for sheep."}, {"verse": 37, "start": 419.57, "end": 423.71, "ta": "ரூபன் சந்ததியார் எஸ்போன், எலெயாலெ, கீரியத்தாயீம்,", "en": "And the children of Reuben built Heshbon, and Elealeh, and Kirjathaim,"}, {"verse": 38, "start": 423.71, "end": 433.83, "ta": "பேர்கள் மற்றப்பட்ட நேபோ, பாகால்மெயோன், சீப்மா என்பவைகளைக் கட்டி, தாங்கள் கட்டின பட்டணங்களுக்கு வேறே பேர்களைக் கொடுத்தார்கள்.", "en": "And Nebo, and Baal-meon, (their names being changed,) and Shibmah: and gave other names unto the cities which they builded."}, {"verse": 39, "start": 433.83, "end": 443.8, "ta": "மனாசேயின் குமாரனாகிய மாகீரின் புத்திரர் கீலேயாத்திற்குப் போய், அதைக் கட்டிக்கொண்டு, அதிலிருந்த எமோரியரைத் துரத்திவிட்டார்கள்.", "en": "And the children of Machir the son of Manasseh went to Gilead, and took it, and dispossessed the Amorite which was in it."}, {"verse": 40, "start": 443.8, "end": 452.14, "ta": "அப்பொழுது மோசே கீலேயாத்தை மனாசேயின் குமாரனாகிய மாகீருக்குக் கொடுத்தான்; அவர்கள் அதிலே குடியேறினார்கள்.", "en": "And Moses gave Gilead unto Machir the son of Manasseh; and he dwelt therein."}, {"verse": 41, "start": 452.14, "end": 460.91, "ta": "மனாசேயின் குமாரனாகிய யாவீர் போய், அவர்களுடைய கிராமங்களைக் கட்டிக்கொண்டு, அவைகளுக்கு யாவீர் என்று பேரிட்டான்.", "en": "And Jair the son of Manasseh went and took the small towns thereof, and called them Havoth-jair."}, {"verse": 42, "start": 460.91, "end": 470.1, "ta": "நோபாக் போய், கேனாத்தையும் அதின் கிராமங்களையும் கட்டிக்கொண்டு, அதற்குத் தன் நாமத்தின்படியே நோபாக் என்று பேரிட்டான்.", "en": "And Nobah went and took Kenath, and the villages thereof, and called it Nobah, after his own name."}]}, "33": {"chapter": 33, "duration": 438.56, "audio_url": "audio_ot/OT04_33.mp3", "total_verses": 56, "verses": [{"verse": 1, "start": 3.8, "end": 13.41, "ta": "மோசே ஆரோன் என்பவர்களுடைய கையின்கீழ்த் தங்கள் தங்கள் சேனைகளின்படியே எகிப்துதேசத்திலிருந்து புறப்பட்ட இஸ்ரவேல் புத்திரருடைய பிரயாணங்களின் விபரம்:", "en": "These are the journeys of the children of Israel, which went forth out of the land of Egypt with their armies under the hand of Moses and Aaron."}, {"verse": 2, "start": 13.41, "end": 24.96, "ta": "மோசே தனக்குக் கர்த்தர் கட்டளையிட்டபடியே அவர்கள் புறப்பட்டபிரகாரமாக அவர்களுடைய பிரயாணங்களை எழுதினான்; அவர்கள் ஒவ்வொரு இடங்களிலிருந்து புறப்பட்டுப்பண்ணின பிரயாணங்களாவன:", "en": "And Moses wrote their goings out according to their journeys by the commandment of the LORD : and these are their journeys according to their goings out."}, {"verse": 3, "start": 24.96, "end": 38.6, "ta": "முதலாம் மாதத்தின் பதினைந்தாம் தேதியிலே அவர்கள் ராமசேசை விட்டுப்புறப்பட்டார்கள்; பஸ்காவுக்கு மறுநாளிலே, எகிப்தியர் எல்லாரும் பார்க்க, இஸ்ரவேல் புத்திரர் பெலத்தகையுடன் புறப்பட்டார்கள்.", "en": "And they departed from Rameses in the first month, on the fifteenth day of the first month; on the morrow after the passover the children of Israel went out with an high hand in the sight of all the Egyptians."}, {"verse": 4, "start": 38.6, "end": 50.01, "ta": "அப்பொழுது எகிப்தியர் கர்த்தர் தங்களுக்குள்ளே சங்கரித்த தலைச்சன்பிள்ளைகளையெல்லாம் அடக்கம்பண்ணினார்கள்; அவர்கள் தேவர்களின்பேரிலும் கர்த்தர் நீதிசெலுத்தினார்.", "en": "For the Egyptians buried all their firstborn, which the LORD had smitten among them: upon their gods also the LORD executed judgments."}, {"verse": 5, "start": 50.01, "end": 57.0, "ta": "பின்பு இஸ்ரவேல் புத்திரர் ராமசேசிலிருந்து புறப்பட்டுப்போய், சுக்கோத்திலே பாளயமிறங்கினார்கள்.", "en": "And the children of Israel removed from Rameses, and pitched in Succoth."}, {"verse": 6, "start": 57.0, "end": 64.32, "ta": "சுக்கோத்திலிருந்து புறப்பட்டுப்போய், வனாந்தரத்தின் எல்லையிலிருக்கிற ஏத்தாமிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Succoth, and pitched in Etham, which is in the edge of the wilderness."}, {"verse": 7, "start": 64.32, "end": 75.61, "ta": "ஏத்தாமிலிருந்து புறப்பட்டுப்போய், பாகால்செபோனுக்கு எதிராக இருக்கிற ஈரோத் பள்ளத்தாக்கின் முன்னடிக்குத்திரும்பி, மிக்தோலுக்கு முன்பாகப் பாளயமிறங்கினார்கள்.", "en": "And they removed from Etham, and turned again unto Pi-hahiroth, which is before Baal-zephon: and they pitched before Migdol."}, {"verse": 8, "start": 75.61, "end": 87.36, "ta": "ஈரோத்தை விட்டுப் புறப்பட்டு, சமுத்திரத்தை நடுவாகக் கடந்து வனாந்தரத்திற்குப்போய், ஏத்தாம் வனாந்தரத்திலே மூன்றுநாள் பிரயாணம்பண்ணி, மாராவிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from before Pi-hahiroth, and passed through the midst of the sea into the wilderness, and went three days’ journey in the wilderness of Etham, and pitched in Marah."}, {"verse": 9, "start": 87.36, "end": 98.31, "ta": "மாராவிலிருந்து புறப்பட்டு, ஏலிமுக்குப் போனார்கள்; ஏலிமிலே பன்னிரண்டு நீரூற்றுகளும் எழுபது பேரீச்சமரங்களும் இருந்தது, அங்கே பாளயமிறங்கினார்கள்.", "en": "And they removed from Marah, and came unto Elim: and in Elim were twelve fountains of water, and threescore and ten palm trees; and they pitched there."}, {"verse": 10, "start": 98.31, "end": 104.02, "ta": "ஏலிமிலிருந்து புறப்பட்டு, சிவந்த சமுத்திரத்தின் அருகே பாளயமிறங்கினார்கள்.", "en": "And they removed from Elim, and encamped by the Red sea."}, {"verse": 11, "start": 104.02, "end": 110.47, "ta": "சிவந்த சமுத்திரத்தை விட்டுப் புறப்பட்டுப்போய், சீன்வனாந்தரத்திலே பாளயமிறங்கினார்கள்.", "en": "And they removed from the Red sea, and encamped in the wilderness of Sin."}, {"verse": 12, "start": 110.47, "end": 116.11, "ta": "சீன்வனாந்தரத்திலிருந்து புறப்பட்டுப்போய், தொப்காவிலே பாளயமிறங்கினார்கள்.", "en": "And they took their journey out of the wilderness of Sin, and encamped in Dophkah."}, {"verse": 13, "start": 116.11, "end": 121.15, "ta": "தொப்காவிலிருந்து புறப்பட்டுப்போய், ஆலுூசிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Dophkah, and encamped in Alush."}, {"verse": 14, "start": 121.15, "end": 130.22, "ta": "ஆலுூசிலிருந்து புறப்பட்டுப்போய், ரெவிதீமிலே பாளயமிறங்கினார்கள்; அங்கே ஜனங்களுக்குக் குடிக்கத் தண்ணீர் இல்லாதிருந்தது.", "en": "And they removed from Alush, and encamped at Rephidim, where was no water for the people to drink."}, {"verse": 15, "start": 130.22, "end": 136.06, "ta": "ரெவிதீமிலிருந்து புறப்பட்டுப்போய், சீனாய் வனாந்தரத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Rephidim, and pitched in the wilderness of Sinai."}, {"verse": 16, "start": 136.06, "end": 142.44, "ta": "சீனாய் வனாந்தரத்திலிருந்து புறப்பட்டுப்போய், கிப்ரோத் அத்தாவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from the desert of Sinai, and pitched at Kibroth-hattaavah."}, {"verse": 17, "start": 142.44, "end": 148.15, "ta": "கிப்ரோத் அத்தாவிலிருந்து புறப்பட்டுப்போய், ஆஸரோத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Kibroth-hattaavah, and encamped at Hazeroth."}, {"verse": 18, "start": 148.15, "end": 153.33, "ta": "ஆஸரோத்திலிருந்து புறப்பட்டுப்போய், ரித்மாவிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Hazeroth, and pitched in Rithmah."}, {"verse": 19, "start": 153.33, "end": 158.9, "ta": "ரித்மாவிலிருந்து புறப்பட்டுப்போய், ரிம்மோன்பேரேசிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Rithmah, and pitched at Rimmon-parez."}, {"verse": 20, "start": 158.9, "end": 164.48, "ta": "ரிம்மோன்பேரேசிலிருந்து புறப்பட்டுப்போய், லிப்னாவிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Rimmon-parez, and pitched in Libnah."}, {"verse": 21, "start": 164.48, "end": 169.51, "ta": "லிப்னாவிலிருந்து புறப்பட்டுப்போய், ரீசாவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Libnah, and pitched at Rissah."}, {"verse": 22, "start": 169.51, "end": 174.62, "ta": "ரீசாவிலிருந்து புறப்பட்டுப்போய், கேலத்தாவிலே பாளயமிறங்கினார்கள்.", "en": "And they journeyed from Rissah, and pitched in Kehelathah."}, {"verse": 23, "start": 174.62, "end": 180.26, "ta": "கேலத்தாவிலிருந்து புறப்பட்டுப்போய், சாப்பேர் மலையிலே பாளயமிறங்கினார்கள்.", "en": "And they went from Kehelathah, and pitched in mount Shapher."}, {"verse": 24, "start": 180.26, "end": 185.7, "ta": "சாப்பேர் மலையிலிருந்து புறப்பட்டுப்போய், ஆரதாவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from mount Shapher, and encamped in Haradah."}, {"verse": 25, "start": 185.7, "end": 190.94, "ta": "ஆரதாவிலிருந்து புறப்பட்டுப்போய், மக்கெலோத்திலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Haradah, and pitched in Makheloth."}, {"verse": 26, "start": 190.94, "end": 196.32, "ta": "மக்கெலோத்திலிருந்து புறப்பட்டுப்போய், தாகாத்திலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Makheloth, and encamped at Tahath."}, {"verse": 27, "start": 196.32, "end": 201.35, "ta": "தாகாத்திலிருந்து புறப்பட்டுப்போய், தாராகிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Tahath, and pitched at Tarah."}, {"verse": 28, "start": 201.35, "end": 206.39, "ta": "தாராகிலிருந்து புறப்பட்டுப்போய், மித்காவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Tarah, and pitched in Mithcah."}, {"verse": 29, "start": 206.39, "end": 211.63, "ta": "மித்காவிலிருந்து புறப்பட்டுப்போய், அஸ்மோனாவிலே பாளயமிறங்கினார்கள்.", "en": "And they went from Mithcah, and pitched in Hashmonah."}, {"verse": 30, "start": 211.63, "end": 217.0, "ta": "அஸ்மோனாவிலிருந்து புறப்பட்டுப்போய், மோசெரோத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Hashmonah, and encamped at Moseroth."}, {"verse": 31, "start": 217.0, "end": 222.58, "ta": "மோசெரோத்திலிருந்து புறப்பட்டுப்போய், பெனெயாக்கானிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Moseroth, and pitched in Bene-jaakan."}, {"verse": 32, "start": 222.58, "end": 228.42, "ta": "பெனெயாக்கானிலிருந்து புறப்பட்டுப்போய், கித்காத் மலையிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Bene-jaakan, and encamped at Hor-hagidgad."}, {"verse": 33, "start": 228.42, "end": 234.27, "ta": "கித்காத் மலையிலிருந்து புறப்பட்டுப்போய், யோத்பாத்தாவிலே பாளயமிறங்கினார்கள்.", "en": "And they went from Hor-hagidgad, and pitched in Jotbathah."}, {"verse": 34, "start": 234.27, "end": 239.78, "ta": "யோத்பாத்தாவிலிருந்து புறப்பட்டுப்போய், எப்ரோனாவிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Jotbathah, and encamped at Ebronah."}, {"verse": 35, "start": 239.78, "end": 245.42, "ta": "எப்ரோனாவிலிருந்து புறப்பட்டுப்போய், எசியோன் கேபேரிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Ebronah, and encamped at Ezion-gaber."}, {"verse": 36, "start": 245.42, "end": 252.14, "ta": "எசியோன் கேபேரிலிருந்து புறப்பட்டுப்போய், காதேசாகிய சீன்வனாந்தரத்திலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Ezion-gaber, and pitched in the wilderness of Zin, which is Kadesh."}, {"verse": 37, "start": 252.14, "end": 259.99, "ta": "காதேசிலிருந்து புறப்பட்டுப்போய், ஏதோம் தேசத்தின் எல்லையிலிருக்கிற ஓர் என்னும் மலையிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Kadesh, and pitched in mount Hor, in the edge of the land of Edom."}, {"verse": 38, "start": 259.99, "end": 274.37, "ta": "அப்பொழுது ஆசாரியனாகிய ஆரோன் கர்த்தருடைய கட்டளையின்படியே ஓர் என்னும் மலையின்மேல் ஏறி, அங்கே இஸ்ரவேல் புத்திரர் எகிப்துதேசத்திலிருந்து புறப்பட்ட நாற்பதாம் வருஷம் ஐந்தாம் மாதம் முதல் தேதியிலே மரணமடைந்தான்.", "en": "And Aaron the priest went up into mount Hor at the commandment of the LORD , and died there, in the fortieth year after the children of Israel were come out of the land of Egypt, in the first day of the fifth month."}, {"verse": 39, "start": 274.37, "end": 280.28, "ta": "ஆரோன் ஓர் என்னும் மலையிலே மரணமடைந்தபோது, நூற்றிருபத்துமூன்று வயதாயிருந்தான்.", "en": "And Aaron was an hundred and twenty and three years old when he died in mount Hor."}, {"verse": 40, "start": 280.28, "end": 289.82, "ta": "அந்நாட்களிலே கானான் தேசத்தின் தென்திசையில் குடியிருந்த கானானியனாகிய ஆராத் என்னும் ராஜா இஸ்ரவேல் புத்திரர் வருகிறதைக் கேள்விப்பட்டான்.", "en": "And king Arad the Canaanite, which dwelt in the south in the land of Canaan, heard of the coming of the children of Israel."}, {"verse": 41, "start": 289.82, "end": 295.73, "ta": "ஓர் என்னும் மலையை விட்டுப் புறப்பட்டுப்போய், சல்மோனாவிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from mount Hor, and pitched in Zalmonah."}, {"verse": 42, "start": 295.73, "end": 300.83, "ta": "சல்மோனாவிலிருந்து புறப்பட்டுப்போய், பூனோனிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Zalmonah, and pitched in Punon."}, {"verse": 43, "start": 300.83, "end": 305.81, "ta": "பூனோனிலிருந்து புறப்பட்டுப்போய், ஓபோத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Punon, and pitched in Oboth."}, {"verse": 44, "start": 305.81, "end": 312.99, "ta": "ஒபோத்திலிருந்து புறப்பட்டுப்போய், மோவாபின் எல்லையிலுள்ள அபாரீமின் மேடுகளிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Oboth, and pitched in Ije-abarim, in the border of Moab."}, {"verse": 45, "start": 312.99, "end": 318.77, "ta": "அந்த மேடுகளை விட்டுப் புறப்பட்டுப்போய், தீபோன்காத்திலே பாளயமிறங்கினார்கள்.", "en": "And they departed from Iim, and pitched in Dibon-gad."}, {"verse": 46, "start": 318.77, "end": 325.08, "ta": "தீபோன்காத்திலிருந்து புறப்பட்டுப்போய், அல்மோன் திப்லத்தாயிமிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Dibon-gad, and encamped in Almon-diblathaim."}, {"verse": 47, "start": 325.08, "end": 332.74, "ta": "அல்மோன் திப்லத்தாயிமிலிருந்து புறப்பட்டுப்போய், நேபோவுக்கு எதிரான அபாரீம் மலைகளிலே பாளயமிறங்கினார்கள்.", "en": "And they removed from Almon-diblathaim, and pitched in the mountains of Abarim, before Nebo."}, {"verse": 48, "start": 332.74, "end": 341.54, "ta": "அபாரீம் மலைகளிலிருந்து புறப்பட்டுப்போய், எரிகோவின் அருகே யோர்தானைச்சார்ந்த மோவாபின் சமனான வெளிகளிலே பாளயமிறங்கினார்கள்.", "en": "And they departed from the mountains of Abarim, and pitched in the plains of Moab by Jordan near Jericho."}, {"verse": 49, "start": 341.54, "end": 350.68, "ta": "யோர்தானைச் சார்ந்த மோவாபின் சமனான வெளிகளில் அவர்கள் பெத்யெசிமோத்தைத் தொடங்கி, ஆபேல்சித்தீம்மட்டும் பாளயமிறங்கியிருந்தார்கள்.", "en": "And they pitched by Jordan, from Beth-jesimoth even unto Abel-shittim in the plains of Moab."}, {"verse": 50, "start": 350.68, "end": 356.25, "ta": "எரிகோவின் அருகே யோர்தானைச் சார்ந்த மோவாபின் சமனான வெளிகளிலே கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the plains of Moab by Jordan near Jericho, saying,"}, {"verse": 51, "start": 356.25, "end": 364.31, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நீங்கள் யோர்தானைக் கடந்து, கானான்தேசத்தில் போய்ச் சேரும்போது,", "en": "Speak unto the children of Israel, and say unto them, When ye are passed over Jordan into the land of Canaan;"}, {"verse": 52, "start": 364.31, "end": 378.08, "ta": "அத்தேசத்துக் குடிகளையெல்லாம் உங்களுக்கு முன்பாகத் துரத்திவிட்டு, அவர்களுடைய எல்லாச் சிலைகளையும் வார்ப்பிக்கப்பட்ட அவர்களுடைய எல்லா விக்கிரகங்களையும் அழித்து, அவர்கள் மேடைகளையெல்லாம் நிர்மூலமாக்கி,", "en": "Then ye shall drive out all the inhabitants of the land from before you, and destroy all their pictures, and destroy all their molten images, and quite pluck down all their high places:"}, {"verse": 53, "start": 378.08, "end": 388.49, "ta": "தேசத்திலுள்ளவர்களைத் துரத்திவிட்டு, அதிலே குடியிருக்கக்கடவீர்கள்; அந்தத் தேசத்தைச் சுதந்தரித்துக்கொள்ளும்படி அதை உங்களுக்குக் கொடுத்தேன்.", "en": "And ye shall dispossess the inhabitants of the land, and dwell therein: for I have given you the land to possess it."}, {"verse": 54, "start": 388.49, "end": 412.07, "ta": "சீட்டுப்போட்டு, தேசத்தை உங்கள் குடும்பங்களுக்குச் சுதந்தரங்களாகப் பங்கிட்டு, அதிக ஜனங்களுக்கு அதிக சுதந்தரமும், கொஞ்ச ஜனங்களுக்குக் கொஞ்சச் சுதந்தரமும் கொடுக்கக்கடவீர்கள்; அவரவர்க்குச் சீட்டு விழும் இடம் எதுவோ, அவ்விடம் அவரவர்க்கு உரியதாகும்; உங்கள் பிதாக்களுடைய கோத்திரங்களின்படியே சுதந்தரம் பெற்றுக்கொள்ளக்கடவீர்கள்.", "en": "And ye shall divide the land by lot for an inheritance among your families: and to the more ye shall give the more inheritance, and to the fewer ye shall give the less inheritance: every man’s inheritance shall be in the place where his lot falleth; according to the tribes of your fathers ye shall inherit."}, {"verse": 55, "start": 412.07, "end": 430.41, "ta": "நீங்கள் தேசத்தின் குடிகளை உங்களுக்கு முன்பாகத் துரத்திவிடாமலிருப்பீர்களானால், அப்பொழுது அவர்களில் நீங்கள் மீதியாக வைக்கிறவர்கள் உங்கள் கண்களில் முள்ளுகளும் உங்கள் விலாக்களிலே கூர்களுமாயிருந்து, நீங்கள் குடியிருக்கிற தேசத்திலே உங்களை உபத்திரவப்படுத்துவார்கள்.", "en": "But if ye will not drive out the inhabitants of the land from before you; then it shall come to pass, that those which ye let remain of them shall be pricks in your eyes, and thorns in your sides, and shall vex you in the land wherein ye dwell."}, {"verse": 56, "start": 430.41, "end": 437.06, "ta": "அன்றியும், நான் அவர்களுக்குச் செய்ய நினைத்ததை உங்களுக்குச் செய்வேன் என்று சொல் என்றார்.", "en": "Moreover it shall come to pass, that I shall do unto you, as I thought to do unto them."}]}, "34": {"chapter": 34, "duration": 254.84, "audio_url": "audio_ot/OT04_34.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 5.5, "ta": "கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 2, "start": 5.5, "end": 19.76, "ta": "நீ இஸ்ரவேல் புத்திரருக்குக் கட்டளையிட்டுச் சொல்லவேண்டியது என்னவென்றால்: கானான்தேசம் அதின் எல்லைகள் உட்பட உங்களுக்குச் சுதந்தரமாகக் கிடைக்கப்போகிறது; நீங்கள் கானான்தேசத்தில் சேரும்போது,", "en": "Command the children of Israel, and say unto them, When ye come into the land of Canaan; (this is the land that shall fall unto you for an inheritance, even the land of Canaan with the coasts thereof:)"}, {"verse": 3, "start": 19.76, "end": 31.95, "ta": "உங்கள் தென்புறம் சீன்வனாந்தரம்தொடங்கி ஏதோம் தேசத்தின் ஓரமட்டும் இருக்கும்; கிழக்கே இருக்கிற உப்புக்கடலின் கடைசி தொடங்கி உங்கள் தென் எல்லையாயிருக்கும்.", "en": "Then your south quarter shall be from the wilderness of Zin along by the coast of Edom, and your south border shall be the outmost coast of the salt sea eastward:"}, {"verse": 4, "start": 31.95, "end": 46.79, "ta": "உங்கள் எல்லை தெற்கிலிருந்து அக்கராபீம் மேடுகளைச் சுற்றி, சீன்வனாந்தரம்வரையில் போய், தெற்கிலே காதேஸ்பர்னேயாவுக்கும், அங்கேயிருந்து ஆத்சார் அதாருக்கும், அங்கேயிருந்து அஸ்மோனாவுக்கும் போய்,", "en": "And your border shall turn from the south to the ascent of Akrabbim, and pass on to Zin: and the going forth thereof shall be from the south to Kadesh-barnea, and shall go on to Hazar-addar, and pass on to Azmon:"}, {"verse": 5, "start": 46.79, "end": 52.78, "ta": "அஸ்மோனாவிலிருந்து எகிப்தின் நதிவரைக்கும் சுற்றிப்போய்க் கடலில் முடியும்.", "en": "And the border shall fetch a compass from Azmon unto the river of Egypt, and the goings out of it shall be at the sea."}, {"verse": 6, "start": 52.78, "end": 60.61, "ta": "மேற்றிசைக்குப் பெருங்கடலே உங்களுக்கு எல்லை; அதுவே உங்களுக்கு மேற்புறத்து எல்லையாயிருக்கும்.", "en": "And as for the western border, ye shall even have the great sea for a border: this shall be your west border."}, {"verse": 7, "start": 60.61, "end": 67.85, "ta": "உங்களுக்கு வடதிசை எல்லை பெருங்கடல் தொடங்கி, ஓர் என்னும் மலையை உங்களுக்குக் குறிப்பாக வைத்து,", "en": "And this shall be your north border: from the great sea ye shall point out for you mount Hor:"}, {"verse": 8, "start": 67.85, "end": 77.01, "ta": "ஓர் என்னும் மலை தொடங்கி, ஆமாத்திற்குப் போகிற வழியைக் குறிப்பாகவைத்து, அங்கேயிருந்து அந்த எல்லை சேதாத்திற்குப் போய்,", "en": "From mount Hor ye shall point out your border unto the entrance of Hamath; and the goings forth of the border shall be to Zedad:"}, {"verse": 9, "start": 77.01, "end": 86.39, "ta": "அங்கேயிருந்து அது சிப்ரோனுக்குப்போய், ஆத்சார் ஏனானிலே முடியும்; அதுவே உங்களுக்கு வடபுறத்து எல்லையாயிருக்கும்.", "en": "And the border shall go on to Ziphron, and the goings out of it shall be at Hazar-enan: this shall be your north border."}, {"verse": 10, "start": 86.39, "end": 92.82, "ta": "உங்களுக்குக் கீழ்த்திசை எல்லைக்கு ஆத்சார் ஏனானிலிருந்து சேப்பாமைக் குறிப்பாக வைத்து,", "en": "And ye shall point out your east border from Hazar-enan to Shepham:"}, {"verse": 11, "start": 92.82, "end": 103.23, "ta": "சேப்பாமிலிருந்து எல்லையானது ஆயினுக்குக் கிழக்கிலுள்ள ரிப்லாபரியந்தமும், அங்கேயிருந்து கின்னரேத் கடல்பரியந்தமும் அதின் கீழ்க்கரையோரமாய்,", "en": "And the coast shall go down from Shepham to Riblah, on the east side of Ain; and the border shall descend, and shall reach unto the side of the sea of Chinnereth eastward:"}, {"verse": 12, "start": 103.23, "end": 114.53, "ta": "அங்கேயிருந்து யோர்தான்பரியந்தமும் போய், உப்புக்கடலில் முடியும்; இந்தச் சுற்றெல்லைகளையுடைய தேசமே உங்களுக்குரிய தேசம் என்று சொல் என்றார்.", "en": "And the border shall go down to Jordan, and the goings out of it shall be at the salt sea: this shall be your land with the coasts thereof round about."}, {"verse": 13, "start": 114.53, "end": 128.79, "ta": "அப்பொழுது மோசே இஸ்ரவேல் புத்திரரை நோக்கி: ஒன்பதரைக் கோத்திரத்தாருக்குக் கொடுக்கும்படி கர்த்தர் கட்டளையிட்டதும், நீங்கள் சீட்டுப்போட்டுச் சுதந்தரித்துக்கொள்ளவேண்டியதுமான தேசம் இதுவே.", "en": "And Moses commanded the children of Israel, saying, This is the land which ye shall inherit by lot, which the LORD commanded to give unto the nine tribes, and to the half tribe:"}, {"verse": 14, "start": 128.79, "end": 147.26, "ta": "ரூபன் புத்திரர் தங்கள் பிதாக்களுடைய வம்சத்தின்படியும், காத் புத்திரர் தங்கள் பிதாக்களுடைய வம்சத்தின்படியும், தங்கள் சுதந்தரத்தைப் பெற்றுக்கொண்டதும் அல்லாமல், மனாசேயின் பாதிக் கோத்திரத்தாரும் தங்கள் சுதந்தரத்தைப் பெற்றுக்கொண்டார்கள்.", "en": "For the tribe of the children of Reuben according to the house of their fathers, and the tribe of the children of Gad according to the house of their fathers, have received their inheritance; and half the tribe of Manasseh have received their inheritance:"}, {"verse": 15, "start": 147.26, "end": 159.23, "ta": "இந்த இரண்டரைக் கோத்திரத்தாரும் சூரியோதய திசையாகிய கிழக்கே எரிகோவின் அருகேயுள்ள யோர்தானுக்கு இப்புறத்திலே தங்கள் சுதந்தரத்தப் பெற்றுக்கொண்டார்கள் என்றான்.", "en": "The two tribes and the half tribe have received their inheritance on this side Jordan near Jericho eastward, toward the sunrising."}, {"verse": 16, "start": 159.23, "end": 161.44, "ta": "மேலும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 17, "start": 161.44, "end": 171.05, "ta": "உங்களுக்கு தேசத்தைப் பங்கிட்டுக்கொடுக்கும் மனிதரின் நாமங்களாவன: ஆசாரியனாகிய எலெயாசாரும், நூனின் குமாரனாகிய யோசுவாவுமே.", "en": "These are the names of the men which shall divide the land unto you: Eleazar the priest, and Joshua the son of Nun."}, {"verse": 18, "start": 171.05, "end": 178.95, "ta": "அன்றியும், தேசத்தைப் பங்கிடும்படி ஒவ்வொரு கோத்திரத்தில் ஒவ்வொரு தலைவனையும் தெரிந்துகொள்ளுங்கள்.", "en": "And ye shall take one prince of every tribe, to divide the land by inheritance."}, {"verse": 19, "start": 178.95, "end": 185.23, "ta": "அந்த மனிதருடைய நாமங்களாவன: யூதா கோத்திரத்துக்கு எப்புன்னேயின் குமாரனாகிய காலேபும்,", "en": "And the names of the men are these: Of the tribe of Judah, Caleb the son of Jephunneh."}, {"verse": 20, "start": 185.23, "end": 190.7, "ta": "சிமியோன் புத்திரரின் கோத்திரத்துக்கு அம்மியூதின் குமாரனாகிய சாமுவேலும்,", "en": "And of the tribe of the children of Simeon, Shemuel the son of Ammihud."}, {"verse": 21, "start": 190.7, "end": 195.35, "ta": "பென்யமீன் கோத்திரத்துக்குக் கிஸ்லோனின் குமாரனாகிய எலிதாதும்,", "en": "Of the tribe of Benjamin, Elidad the son of Chislon."}, {"verse": 22, "start": 195.35, "end": 201.48, "ta": "தாண் புத்திரரின் கோத்திரத்துக்கு யொக்லியின் குமாரனாகிய புக்கி என்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Dan, Bukki the son of Jogli."}, {"verse": 23, "start": 201.48, "end": 209.31, "ta": "யோசேப்பின் குமாரனாகிய மனாசே புத்திரரின் கோத்திரத்துக்கு எபோதின் குமாரனாகிய அன்னியேல் என்னும் பிரபுவும்,", "en": "The prince of the children of Joseph, for the tribe of the children of Manasseh, Hanniel the son of Ephod."}, {"verse": 24, "start": 209.31, "end": 216.26, "ta": "எப்பிராயீம் புத்திரரின் கோத்திரத்துக்குச் சிப்தானின் குமாரனாகிய கேமுவேல் என்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Ephraim, Kemuel the son of Shiphtan."}, {"verse": 25, "start": 216.26, "end": 223.13, "ta": "செபுலோன் புத்திரரின் கோத்திரத்துக்குப் பர்னாகின் குமாரனாகிய எலிசாப்பான் என்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Zebulun, Elizaphan the son of Parnach."}, {"verse": 26, "start": 223.13, "end": 229.7, "ta": "இசக்கார் புத்திரரின் கோத்திரத்துக்கு ஆசானின் குமாரனாகிய பல்த்தியேல் என்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Issachar, Paltiel the son of Azzan."}, {"verse": 27, "start": 229.7, "end": 236.13, "ta": "ஆசேர் புத்திரரின் கோத்திரத்துக்குச் செலோமியின் குமாரனாகிய அகியூத்தென்னும் பிரபுவும்,", "en": "And the prince of the tribe of the children of Asher, Ahihud the son of Shelomi."}, {"verse": 28, "start": 236.13, "end": 243.81, "ta": "நப்தலி புத்திரரின் கோத்திரத்துக்கு அம்மியூதின் குமாரனாகிய பெதாக்கேல் என்னும் பிரபுவுமே என்றார்.", "en": "And the prince of the tribe of the children of Naphtali, Pedahel the son of Ammihud."}, {"verse": 29, "start": 243.81, "end": 253.34, "ta": "கானான்தேசத்திலே இஸ்ரவேல் புத்திரருக்குச் சுதந்தரங்களைப் பங்கிட்டுக் கொடுக்கிறதற்குக் கர்த்தர் கட்டளையிட்டவர்கள் இவர்களே.", "en": "These are they whom the LORD commanded to divide the inheritance unto the children of Israel in the land of Canaan."}]}, "35": {"chapter": 35, "duration": 382.97, "audio_url": "audio_ot/OT04_35.mp3", "total_verses": 34, "verses": [{"verse": 1, "start": 3.8, "end": 9.33, "ta": "எரிகோவின் அருகே யோர்தானைச் சேர்ந்த மோவாபின் சமனான வெளிகளிலே கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses in the plains of Moab by Jordan near Jericho, saying,"}, {"verse": 2, "start": 9.33, "end": 25.78, "ta": "இஸ்ரவேல் புத்திரர் தங்கள் காணியாட்சியாகிய சுதந்தரத்திலே லேவியருக்குக் குடியிருக்கும்படி பட்டணங்களைக் கொடுக்கவேண்டும் என்று அவர்களுக்குக் கட்டளையிடு; அந்தப் பட்டணங்களைச் சூழ்ந்திருக்கிற வெளிநிலங்களையும் லேவியருக்குக் கொடுக்கவேண்டும்.", "en": "Command the children of Israel, that they give unto the Levites of the inheritance of their possession cities to dwell in; and ye shall give also unto the Levites suburbs for the cities round about them."}, {"verse": 3, "start": 25.78, "end": 39.5, "ta": "அந்தப் பட்டணங்கள் அவர்கள் குடியிருப்பதற்கும், அவைகளைச் சூழ்ந்த வெளிநிலங்கள் அவர்களுடைய ஆடுமாடுகளுக்கும், அவர்களுடைய ஆஸ்திகளுக்கும், அவர்களுடைய சகல மிருக ஜீவன்களுக்கும் குறிக்கப்படவேண்டும்.", "en": "And the cities shall they have to dwell in; and the suburbs of them shall be for their cattle, and for their goods, and for all their beasts."}, {"verse": 4, "start": 39.5, "end": 50.03, "ta": "நீங்கள் லேவியருக்குக் கொடுக்கும் பட்டணங்களைச் சூழ்ந்த வெளிநிலங்கள் பட்டணத்தின் மதில்தொடங்கி, வெளியிலே சுற்றிலும் ஆயிரமுழ தூரத்துக்கு எட்டவேண்டும்.", "en": "And the suburbs of the cities, which ye shall give unto the Levites, shall reach from the wall of the city and outward a thousand cubits round about."}, {"verse": 5, "start": 50.03, "end": 67.34, "ta": "பட்டணம் மத்தியில் இருக்க, பட்டணத்தின் வெளிப்புறந்தொடங்கி, கிழக்கே இரண்டாயிரமுழமும், தெற்கே இரண்டாயிரமுழமும், மேற்கே இரண்டாயிரமுழமும், வடக்கே இரண்டாயிரமுழமும் அளந்துவிடக்கடவீர்கள்; இது அவர்கள் பட்டணங்களுக்கு வெளிநிலங்களாயிருப்பதாக.", "en": "And ye shall measure from without the city on the east side two thousand cubits, and on the south side two thousand cubits, and on the west side two thousand cubits, and on the north side two thousand cubits; and the city shall be in the midst: this shall be to them the suburbs of the cities."}, {"verse": 6, "start": 67.34, "end": 84.66, "ta": "நீங்கள் லேவியருக்குக் கொடுக்கும் பட்டணங்களில் அடைக்கலத்துக்காக ஆறு பட்டணங்கள் இருக்கவேண்டும்; கொலைசெய்தவன் அங்கே தப்பி ஓடிப்போகிறதற்கு அவைகளைக் குறிக்கக்கடவீர்கள்; அவைகளையல்லாமல், நாற்பத்திரண்டு பட்டணங்களை அவர்களுக்குக் கொடுக்கவேண்டும்.", "en": "And among the cities which ye shall give unto the Levites there shall be six cities for refuge, which ye shall appoint for the manslayer, that he may flee thither: and to them ye shall add forty and two cities."}, {"verse": 7, "start": 84.66, "end": 92.92, "ta": "நீங்கள் லேவியருக்குக் கொடுக்கவேண்டிய பட்டணங்களெல்லாம் நாற்பத்தெட்டுப் பட்டணங்களும் அவைகளைச் சூழ்ந்த வெளிநிலங்களுமே.", "en": "So all the cities which ye shall give to the Levites shall be forty and eight cities: them shall ye give with their suburbs."}, {"verse": 8, "start": 92.92, "end": 114.77, "ta": "நீங்கள் இஸ்ரவேல் புத்திரரின் சுதந்தரத்திலிருந்து அந்தப் பட்டணங்களைப்பிரித்துக் கொடுக்கும்போது, அதிகமுள்ளவர்களிடத்திலிருந்து அதிகமும், கொஞ்சமுள்ளவர்களிடத்திலிருந்து கொஞ்சமும் பிரித்துக்கொடுக்கவேண்டும்; அவரவர் சுதந்தரித்துக்கொண்ட சுதந்தரத்தின்படியே தங்கள் பட்டணங்களில் லேவியருக்குக் கொடுக்கக்கடவர்கள் என்றார்.", "en": "And the cities which ye shall give shall be of the possession of the children of Israel: from them that have many ye shall give many; but from them that have few ye shall give few: every one shall give of his cities unto the Levites according to his inheritance which he inheriteth."}, {"verse": 9, "start": 114.77, "end": 116.9, "ta": "பின்னும் கர்த்தர் மோசேயை நோக்கி:", "en": "And the LORD spake unto Moses, saying,"}, {"verse": 10, "start": 116.9, "end": 124.89, "ta": "நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நீங்கள் யோர்தானைக் கடந்து, கானான்தேசத்தில் பிரவேசிக்கும்போது,", "en": "Speak unto the children of Israel, and say unto them, When ye be come over Jordan into the land of Canaan;"}, {"verse": 11, "start": 124.89, "end": 133.29, "ta": "கைப்பிசகாய் ஒருவனைக் கொன்று போட்டவன் ஓடிப்போயிருக்கத்தக்க அடைக்கலப்பட்டணங்களாகச் சில பட்டணங்களைக் குறிக்கக்கடவீர்கள்.", "en": "Then ye shall appoint you cities to be cities of refuge for you; that the slayer may flee thither, which killeth any person at unawares."}, {"verse": 12, "start": 133.29, "end": 145.28, "ta": "கொலைசெய்தவன் நியாயசபையிலே நியாயம் விசாரிக்கப்படுமுன் சாகாமல், பழிவாங்குகிறவன் கைக்குத் தப்பிப்போயிருக்கும்படி, அவைகள் உங்களுக்கு அடைக்கலப்பட்டணங்களாய் இருக்கக்கடவது.", "en": "And they shall be unto you cities for refuge from the avenger; that the manslayer die not, until he stand before the congregation in judgment."}, {"verse": 13, "start": 145.28, "end": 151.14, "ta": "நீங்கள் கொடுக்கும் பட்டணங்களில் ஆறு பட்டணங்கள் அடைக்கலத்துக்காக இருக்கவேண்டும்.", "en": "And of these cities which ye shall give six cities shall ye have for refuge."}, {"verse": 14, "start": 151.14, "end": 161.0, "ta": "யோர்தானுக்கு இப்புறத்தில் மூன்று பட்டணங்களையும், கானான்தேசத்தில் மூன்று பட்டணங்களையும் கொடுக்கவேண்டும், அவைகள் அடைக்கலப்பட்டணங்களாம்.", "en": "Ye shall give three cities on this side Jordan, and three cities shall ye give in the land of Canaan, which shall be cities of refuge."}, {"verse": 15, "start": 161.0, "end": 175.85, "ta": "கைப்பிசகாய் ஒருவனைக் கொன்றவன் எவனோ, அவன் அங்கே ஓடிப்போயிருக்கும்படிக்கு, அந்த ஆறு பட்டணங்களும் இஸ்ரவேல் புத்திரருக்கும் உங்கள் நடுவே இருக்கும் பரதேசிக்கும் அந்நியனுக்கும் அடைக்கலப்பட்டணங்களாய் இருக்கவேண்டும்.", "en": "These six cities shall be a refuge, both for the children of Israel, and for the stranger, and for the sojourner among them: that every one that killeth any person unawares may flee thither."}, {"verse": 16, "start": 175.85, "end": 186.24, "ta": "ஒருவன் இருப்பு ஆயுதத்தினால் ஒருவனை வெட்டினதினால் அவன் செத்துப்போனால், வெட்டினவன் கொலைபாதகனாயிருக்கிறான்; கொலைபாதகன் கொலைசெய்யப்படவேண்டும்.", "en": "And if he smite him with an instrument of iron, so that he die, he is a murderer: the murderer shall surely be put to death."}, {"verse": 17, "start": 186.24, "end": 197.36, "ta": "ஒருவன் ஒரு கல்லை எடுத்து, சாகத்தக்கதாக ஒருவன்மேல் எறிகிறதினாலே அவன் செத்துப்போனால், கல்லெறிந்தவன் கொலைபாதகனாயிருக்கிறான், அவன் கொலைசெய்யப்படவேண்டும்.", "en": "And if he smite him with throwing a stone, wherewith he may die, and he die, he is a murderer: the murderer shall surely be put to death."}, {"verse": 18, "start": 197.36, "end": 209.69, "ta": "ஒருவன் தன் கையில் ஒரு மர ஆயுதத்தை எடுத்து, சாகத்தக்கதாக ஒருவனை அடித்ததினால் அவன் செத்துப்போனால், அடித்தவன் கொலைபாதகனாயிருக்கிறான்; கொலைபாதகன் கொலைசெய்யப்படவேண்டும்.", "en": "Or if he smite him with an hand weapon of wood, wherewith he may die, and he die, he is a murderer: the murderer shall surely be put to death."}, {"verse": 19, "start": 209.69, "end": 216.88, "ta": "பழிவாங்கவேண்டியவனே கொலைபாதகனைக் கொல்லவேண்டும்; அவனைக் கண்டமாத்திரத்தில் அவனைக் கொன்றுபோடலாம்.", "en": "The revenger of blood himself shall slay the murderer: when he meeteth him, he shall slay him."}, {"verse": 20, "start": 216.88, "end": 225.41, "ta": "ஒருவன் பகையினால் ஒருவனை விழத்தள்ளினதினாலாயினும், பதுங்கியிருந்து அவன் சாகத்தக்கதாய் அவன்மேல் ஏதாகிலும் எறிந்ததினாலாயினும்,", "en": "But if he thrust him of hatred, or hurl at him by laying of wait, that he die;"}, {"verse": 21, "start": 225.41, "end": 238.99, "ta": "அவனைப் பகைத்து, தன் கையினால் அடித்ததினாலாயினும், அவன் செத்துப்போனால், அடித்தவன் கொலைபாதகன்; அவன் கொலைசெய்யப்படவேண்டும் பழிவாங்குகிறவன் கொலைபாதகனைக் கண்டமாத்திரத்தில் கொன்றுபோடலாம்.", "en": "Or in enmity smite him with his hand, that he die: he that smote him shall surely be put to death; for he is a murderer: the revenger of blood shall slay the murderer, when he meeteth him."}, {"verse": 22, "start": 238.99, "end": 248.72, "ta": "ஒருவன் பகையொன்றும் இல்லாமல் சடுதியில் ஒருவனைத் தள்ளி விழப்பண்ணினதினாலாயினும், பதுங்கியிராமல் யாதொரு ஆயுதத்தை அவன்மேல் பட எறிந்ததினாலாயினும்,", "en": "But if he thrust him suddenly without enmity, or have cast upon him any thing without laying of wait,"}, {"verse": 23, "start": 248.72, "end": 261.77, "ta": "அவனுக்குப் பகைஞனாயிராமலும் அவனுக்குத் தீங்கு செய்ய நினையாமலுமிருக்கையில், ஒருவனைக் கொன்றுபோடத்தக்க ஒரு கல்லினால் அவனைக்காணாமல் எறிய, அது அவன்மேல் பட்டதினாலாயினும், அவன் செத்துப்போனால்,", "en": "Or with any stone, wherewith a man may die, seeing him not, and cast it upon him, that he die, and was not his enemy, neither sought his harm:"}, {"verse": 24, "start": 261.77, "end": 267.44, "ta": "அப்பொழுது கொலைசெய்தவனையும் பழிவாங்குகிறவனையும் சபையார் இந்த நியாயப்படி விசாரித்து,", "en": "Then the congregation shall judge between the slayer and the revenger of blood according to these judgments:"}, {"verse": 25, "start": 267.44, "end": 284.35, "ta": "கொலைசெய்தவனைப் பழிவாங்குகிறவனுடைய கைக்குத் தப்புவித்து, அவன் ஓடிப்போயிருந்த அடைக்கலப்பட்டணத்துக்கு அவனைத் திரும்பப் போகும்படி செய்யக்கடவர்கள்; பரிசுத்த தைலத்தினால் அபிஷேகம் பெற்ற பிரதான ஆசாரியன் மரணமடையுமட்டும் அவன் அதிலே இருக்கக்கடவன்.", "en": "And the congregation shall deliver the slayer out of the hand of the revenger of blood, and the congregation shall restore him to the city of his refuge, whither he was fled: and he shall abide in it unto the death of the high priest, which was anointed with the holy oil."}, {"verse": 26, "start": 284.35, "end": 291.42, "ta": "ஆனாலும் கொலைசெய்தவன் தான் ஓடிப்போயிருக்கிற அடைக்கலப்பட்டணத்தின் எல்லையை விட்டு வெளிப்பட்டிருக்கும்போது,", "en": "But if the slayer shall at any time come without the border of the city of his refuge, whither he was fled;"}, {"verse": 27, "start": 291.42, "end": 300.07, "ta": "பழிவாங்குகிறவன் கொலை செய்தவனை அடைக்கலப்பட்டணத்துக்கு வெளியே கண்டுபிடித்துக் கொன்றுபோட்டால், அவன்மேல் இரத்தப்பழி இல்லை.", "en": "And the revenger of blood find him without the borders of the city of his refuge, and the revenger of blood kill the slayer; he shall not be guilty of blood:"}, {"verse": 28, "start": 300.07, "end": 312.2, "ta": "கொலைசெய்தவன் பிரதான ஆசாரியன் மரணமடையுமட்டும் அடைக்கலப் பட்டணத்திலிருக்கவேண்டும்; பிரதான ஆசாரியன் மரணமடைந்தபின்பு, தன் சுதந்தரமான காணியாட்சிக்குத் திரும்பிப்போகலாம்.", "en": "Because he should have remained in the city of his refuge until the death of the high priest: but after the death of the high priest the slayer shall return into the land of his possession."}, {"verse": 29, "start": 312.2, "end": 319.59, "ta": "இவைகள் உங்கள் வாசஸ்தலங்களிலெங்கும் உங்கள் தலைமுறைதோறும் உங்களுக்கு நியாயவிதிப் பிரமாணமாயிருக்கக்கடவது.", "en": "So these things shall be for a statute of judgment unto you throughout your generations in all your dwellings."}, {"verse": 30, "start": 319.59, "end": 334.24, "ta": "எவனாகிலும், ஒரு மனிதனைக் கொன்றுபோட்டால், அப்பொழுது சாட்சிகளுடைய வாக்குமூலத்தின்படியே அந்தக் கொலைபாதகனைக் கொலைசெய்யக்கடவர்கள்; ஒரே சாட்சியைக்கொண்டுமாத்திரம் ஒரு மனிதன் சாகும்படி தீர்ப்புச்செய்யலாகாது.", "en": "Whoso killeth any person, the murderer shall be put to death by the mouth of witnesses: but one witness shall not testify against any person to cause him to die."}, {"verse": 31, "start": 334.24, "end": 343.77, "ta": "சாகிறதற்கேற்ற குற்றஞ்சுமந்த கொலைபாதகனுடைய ஜீவனுக்காக நீங்கள் மீட்கும்பொருளை வாங்கக் கூடாது; அவன் தப்பாமல் கொலைசெய்யப்படவேண்டும்.", "en": "Moreover ye shall take no satisfaction for the life of a murderer, which is guilty of death: but he shall be surely put to death."}, {"verse": 32, "start": 343.77, "end": 354.49, "ta": "தன் அடைக்கலப்பட்டணத்துக்கு ஓடிப்போனவன் ஆசாரியன் மரணமடையாததற்கு முன்னே தன் நாட்டிற்குத் திரும்பிவரும்படி நீங்கள் அவனுக்காக மீட்கும்பொருளை வாங்கக் கூடாது.", "en": "And ye shall take no satisfaction for him that is fled to the city of his refuge, that he should come again to dwell in the land, until the death of the priest."}, {"verse": 33, "start": 354.49, "end": 370.35, "ta": "நீங்கள் இருக்கும் தேசத்தைப் பரிசுத்தக் குலைச்சலாக்காதிருங்கள்; இரத்தம் தேசத்தைத் தீட்டுப்படுத்தும்; இரத்தம் சிந்தினவனுடைய இரத்தத்தினாலேயொழிய, வேறொன்றினாலும் தேசத்திலே சிந்துண்ட இரத்தத்திற்காகப் பாவநிவிர்த்தியில்லை.", "en": "So ye shall not pollute the land wherein ye are: for blood it defileth the land: and the land cannot be cleansed of the blood that is shed therein, but by the blood of him that shed it."}, {"verse": 34, "start": 370.35, "end": 381.47, "ta": "நீங்கள் குடியிருக்கும் என் வாசஸ்தலமாகிய தேசத்தைத் தீட்டுப்படுத்தவேண்டாம்; கர்த்தராகிய நான் இஸ்ரவேல் புத்திரர் நடுவே வாசம்பண்ணுகிறேன் என்று சொல் என்றார்.", "en": "Defile not therefore the land which ye shall inhabit, wherein I dwell: for I the LORD dwell among the children of Israel."}]}, "36": {"chapter": 36, "duration": 203.52, "audio_url": "audio_ot/OT04_36.mp3", "total_verses": 13, "verses": [{"verse": 1, "start": 3.8, "end": 20.51, "ta": "யோசேப்பின் குமாரனுடைய வம்சத்தாரில் மனாசேயின் குமாரனாகிய மாகீருக்குப் பிறந்த கீலேயாத்தின் வம்ச பிதாக்களான தலைவர் சேர்ந்து, மோசேக்கும் இஸ்ரவேல் புத்திரருடைய பிதாக்களில் தலைவராகிய பிரபுக்களுக்கும் முன்பாகவந்து, அவர்களை நோக்கி:", "en": "And the chief fathers of the families of the children of Gilead, the son of Machir, the son of Manasseh, of the families of the sons of Joseph, came near, and spake before Moses, and before the princes, the chief fathers of the children of Israel:"}, {"verse": 2, "start": 20.51, "end": 42.33, "ta": "சீட்டுப்போட்டு, தேசத்தை இஸ்ரவேல் புத்திரருக்குச் சுதந்தரமாகக் கொடுக்கும்படி எங்கள் ஆண்டவனுக்குக் கர்த்தர் கட்டளையிட்டாரே; அன்றியும், எங்கள் சகோதரனாகிய செலொப்பியாத்தின் சுதந்தரத்தை அவன் குமாரத்திகளுக்குக் கொடுக்கவேண்டும் என்றும் எங்கள் ஆண்டவனுக்குக் கர்த்தராலே கட்டளையிடப்பட்டதே.", "en": "And they said, The LORD commanded my lord to give the land for an inheritance by lot to the children of Israel: and my lord was commanded by the LORD to give the inheritance of Zelophehad our brother unto his daughters."}, {"verse": 3, "start": 42.33, "end": 67.22, "ta": "இப்படியிருக்க, இவர்கள் இஸ்ரவேல் புத்திரருடைய வேறொரு கோத்திரத்தின் புத்திரருக்கு மனைவிகளானால், அந்தக் குமாரத்திகளுடைய சுதந்தரம் எங்கள் பிதாக்களுடைய சுதந்தரத்திலிருந்து நீங்கி, அவர்கள் உட்படுகிற கோத்திரத்தின் சுதந்தரத்தோடே சேர்ந்துபோகும்; இப்படி எங்கள் சுதந்தரத்துக்குச் சீட்டினால் விழுந்த பங்கில் இராமல் அற்றுப்போகுமே.", "en": "And if they be married to any of the sons of the other tribes of the children of Israel, then shall their inheritance be taken from the inheritance of our fathers, and shall be put to the inheritance of the tribe whereunto they are received: so shall it be taken from the lot of our inheritance."}, {"verse": 4, "start": 67.22, "end": 85.03, "ta": "இஸ்ரவேல் புத்திரருக்கு யூபிலி வருஷம் வந்தாலும், அவர்களுடைய சுதந்தரம் அவர்கள் உட்பட்டுப்போன கோத்திரத்தின் சுதந்தரத்தோடே சேர்ந்துபோகும்; இப்படி எங்கள் பிதாக்களுடைய கோத்திரத்தின் சுதந்தரத்திலிருந்து அது நீங்கிப்போகுமே என்றார்கள்.", "en": "And when the jubile of the children of Israel shall be, then shall their inheritance be put unto the inheritance of the tribe whereunto they are received: so shall their inheritance be taken away from the inheritance of the tribe of our fathers."}, {"verse": 5, "start": 85.03, "end": 94.66, "ta": "அப்பொழுது மோசே கர்த்தருடைய கட்டளையின்படியே இஸ்ரவேல் புத்திரரை நோக்கி: யோசேப்பு புத்திரரின் கோத்திரத்தார் சொல்லுகிறது சரியே.", "en": "And Moses commanded the children of Israel according to the word of the LORD , saying, The tribe of the sons of Joseph hath said well."}, {"verse": 6, "start": 94.66, "end": 111.74, "ta": "கர்த்தர் செலொப்பியாத்தின் குமாரத்திகளைக் குறித்த காரியத்தில் கட்டளையிடுகிறதாவது: அவர்கள் தங்களுக்கு இஷ்டமானவர்களை விவாகஞ்செய்யலாம்; ஆனாலும், தங்கள் பிதாவின் கோத்திரவம்சத்தாரில் மாத்திரம் அவர்கள் விவாகஞ்செய்யவேண்டும்.", "en": "This is the thing which the LORD doth command concerning the daughters of Zelophehad, saying, Let them marry to whom they think best; only to the family of the tribe of their father shall they marry."}, {"verse": 7, "start": 111.74, "end": 128.16, "ta": "இப்படியே இஸ்ரவேல் புத்திரரின் சுதந்தரம் ஒரு கோத்திரத்தைவிட்டு, வேறு கோத்திரத்துக்குப் போகாதிருக்கும்; இஸ்ரவேல் புத்திரர் அவரவர் தங்கள் தங்கள் பிதாக்களுடைய கோத்திரத்தின் சுதந்தரத்திலே நிலைகொண்டிருக்கவேண்டும்.", "en": "So shall not the inheritance of the children of Israel remove from tribe to tribe: for every one of the children of Israel shall keep himself to the inheritance of the tribe of his fathers."}, {"verse": 8, "start": 128.16, "end": 145.75, "ta": "இஸ்ரவேல் புத்திரர் அவரவர் தங்கள் தங்கள் பிதாக்களின் சுதந்தரத்தை அநுபவிக்கும்படி, இஸ்ரவேல் புத்திரருடைய ஒரு கோத்திரத்திலே சுதந்தரம் அடைந்திருக்கிற எந்தக் குமாரத்தியும் தன் பிதாவின் கோத்திர வம்சத்தாரில் ஒருவனுக்கு மனைவியாகவேண்டும்.", "en": "And every daughter, that possesseth an inheritance in any tribe of the children of Israel, shall be wife unto one of the family of the tribe of her father, that the children of Israel may enjoy every man the inheritance of his fathers."}, {"verse": 9, "start": 145.75, "end": 160.86, "ta": "சுதந்தரமானது ஒரு கோத்திரத்தைவிட்டு வேறொரு கோத்திரத்தைச் சேரக் கூடாது; இஸ்ரவேல் புத்திரருடைய ஒவ்வொரு கோத்திரமும் தன்தன் சுதந்தரத்திலே நிலைகொண்டிருக்கவேண்டுமென்று கட்டளையிட்டிருக்கிறார் என்றான்.", "en": "Neither shall the inheritance remove from one tribe to another tribe; but every one of the tribes of the children of Israel shall keep himself to his own inheritance."}, {"verse": 10, "start": 160.86, "end": 167.28, "ta": "கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே செலொப்பியாத்தின் குமாரத்திகள் செய்தார்கள்.", "en": "Even as the LORD commanded Moses, so did the daughters of Zelophehad:"}, {"verse": 11, "start": 167.28, "end": 184.21, "ta": "செலொப்பியாத்தின் குமாரத்திகளாகிய மக்லாள் திர்சாள் ஒக்லாள் மில்காள் நோவாள் என்பவர்கள் தங்கள் பிதாவின் சகோதரருடைய புத்திரரை விவாகம்பண்ணினார்கள்; அவர்கள் யோசேப்பின் குமாரனாகிய மனாசே புத்திரரின் வம்சத்தாரை விவாகம்பண்ணினபடியால்,", "en": "For Mahlah, Tirzah, and Hoglah, and Milcah, and Noah, the daughters of Zelophehad, were married unto their father’s brothers’ sons:"}, {"verse": 12, "start": 184.21, "end": 189.9, "ta": "அவர்களுடைய சுதந்தரம் அவர்கள் பிதாவின் வம்சமான கோத்திரத்தோடே இருந்தது.", "en": "And they were married into the families of the sons of Manasseh the son of Joseph, and their inheritance remained in the tribe of the family of their father."}, {"verse": 13, "start": 189.9, "end": 202.02, "ta": "எரிகோவின் அருகே யோர்தானுக்கு இப்புறத்திலுள்ள மோவாபின் சமனான வெளிகளில் கர்த்தர் மோசேயைக்கொண்டு இஸ்ரவேல் புத்திரருக்கு விதித்த கட்டளைகளும் நியாயங்களும் இவைகளே.", "en": "These are the commandments and the judgments, which the LORD commanded by the hand of Moses unto the children of Israel in the plains of Moab by Jordan near Jericho."}]}}};
}
